---  0 ecl1_a リグル 非符（不亮卡名）     1 ecl2_a ルーミア 非符（不亮卡名）
---  2 ecl1_b リグル 蛍符「地上の恒星」   3 ecl2_b ルーミア 闇符「ダークサイドオブザムーン」
---  4 ecl1_c リグル 蝶符「バタフライストーム」 5 ecl2_c ルーミア 夜符「ミッドナイトバード」
---按「一个角色一个组」拆：组 24 = リグル・ナイトバグ（0/2/4，第 1 张是非符）、
---组 25 = ルーミア（1/3/5）。
---立绘：リグル "Nightbug"、ルーミア "Rumia"（BossImageList.lua:13/35）。
boss.Define("24a", "リグル・ナイトバグ", "TH09_5_1", TH095_bg,
        { -128, field_y(-64) }, class.scbg24, "Nightbug", LEVEL)
boss.Define("25a", "ルーミア", "TH09_5_1", TH095_bg,
        { -128, field_y(-64) }, class.scbg25, "Rumia", LEVEL)

do  -- 71 幽雅「死出の誘蛾灯」（ecl17_a，幽幽子，组 1a 第 1 张）
    ---原作是「蛾扑向灯」：本体从场外落到中轴，**一条**发弹上下文每 8 帧甩出**两组**
    ---16 发的整圈蝶弹（像绕着灯打转的蛾群），第 10 秒再放出一只「蛾」（拍照目标）
    ---加一层自机狙大圈。骨架（/tmp/B_ecl17_a.txt）：
    ---  · Sub2：ins_63(-128,-64) 进场 → t=100 ins_64(30,4,0,128) 用 30 帧落到 (0,128)，
    ---    同时 ins_141(7) 把相机的快门上限设成 7 张。
    ---  · Sub3：t=0 起子 ECL 上下文 ins_117(0,4)（= Sub4）+ 一声 ins_106(5)；
    ---    t=600 才放拍照目标（ins_83(6) 的蛾）并起第二条上下文 ins_117(1,5)（= Sub5）。
    ---    两个 ins_117 用的都是**固定槽位**（会把上一个上下文 free 掉、不叠加，
    ---    EclRunTargetHigh.inl:206）⇒ 全场一共只有两条发弹上下文。
    ---──────────────────────── 常量（改手感只动这一段） ────────────────────────
    ---入场：Sub2 t=0 的 ins_63(-128,-64)、t=100 的 ins_64(30,4,0,128)。
    ---（world08 七幕的本体都在左上角外生成，所以入场段是同一套。）
    local BOSS_X, BOSS_START_Y = -128, field_y(-64)     -- 288（场地外）
    local BOSS_HOME_Y = field_y(128)                    -- 96
    local ENTRY_WAIT, ENTRY_TIME = 100, 30
    local EASE_OUT = VALUE_SET.DECEL

    ---主弹幕（Sub4，dump 的 @860-1180）：**一条**上下文、**一轮 8 帧**、一轮发**两组** 16 发。
    ---  @920  t=0  ins_101(0, 0x20, 0, 120, -1, -0.025,  0.019635)  ← 写 slot0（被下面那行覆盖）
    ---  @960  t=0  ins_89(15, 4, 16, 1, 4.0, 1.5, floatV0, 0.0327249, 546)  ← 第 1 组：色号 4
    ---  @1004 t=0  ins_101(0, 0x20, 0, 120, -1, -0.025, -0.019635)  ← 同一个 slot 再写一遍
    ---  @1044 t=4  ins_89(15, 5, 16, 1, 4.0, 1.5, floatV1, 0.0327249, 546)  ← 第 2 组：色号 5
    ---  @1088/1124 t=4  ins_15 / ins_16(floatV0 / floatV1, 0.01309)  ← floatV0 +0.75°、floatV1 −0.75°
    ---  @1108/1144 t=4  ins_37(floatV0 / floatV1)                    ← 归一化到 (−π,π]
    ---  @1160 t=8       ins_4(0, -240) → time 设回 0、跳回 @920
    ---四条**对着源码核过**的读数（旧版注释在这几条上写错过，别再照抄）：
    ---  · ins_89 的 aimMode = opcode − 0x56 = 3 = CIRCLE（EnemyShotDispatch.cpp:145、
    ---    BulletManager.hpp:167）：angle = angle + index1×2π/count1 + index2×angleStep，
    ---    而 count2 = 1 ⇒ 操作数里那个 0.0327249 rad（1.875°）**根本没参与**
    ---    （BulletManager.cpp:368-372 的 CIRCLE 分支）。
    ---  · 一轮是 **8 帧**：ins_4(0,-240) 在 t=8 把 ctx->time 拨回 0 并跳回 @920，而解释器
    ---    跳转后会**在同一帧**继续派发 time 与新值相等的指令（EclRunLow.inl:242-246 的
    ---    `goto low_redispatch_instruction`；th31.lua:2758 记着同一条）⇒ t=0 那一组在
    ---    跳跃的**那一帧**就再放一次。于是稳态下一轮 = 8 帧：第 1 组在跳回的那一帧、
    ---    第 2 组在 4 帧后（t=8 与 t=4 的 frame 相隔 4 帧，t=0 与 t=4 同理）。
    ---  · ins_37 **不是取反**、是归一化（EclRunLow.inl:357-363 调 AddNormalizeAngle，
    ---    RuntimeMath.cpp:7 把角折进 (−π,π]）⇒ 两个基准角各自**单调**转，不是来回翻。
    ---  · ins_101 是「往第 N 号 transform 槽里写一条记录」（EclRunTargetHigh.inl:45-63）。
    ---    slot0 被写了**两遍**（@920 的 +0.019635 与 @1004 的 −0.019635）：descriptor 是
    ---    被后来的那条覆盖，但**两组弹各在发弹那一刻抄一份**（BulletManager.cpp:484）
    ---    ⇒ 色号 4 抄到 +0.019635、色号 5 抄到 −0.019635，两组**反向**自转（不是同向）。
    ---    speedDelta 两遍都是 −0.025/帧，所以两组一起在 120 帧里从 4.0 减到 1.0。
    local CYCLE, SPLIT = 8, 4
    local RING_COUNT = 16                   -- ins_89 的 count1 ⇒ 16 等分 22.5°
    local RING_SPEED = 4.0                  -- ins_89 的 speed1（count2 = 1 ⇒ speed2 不参与）
    ---两个基准角**不是同一个**：t=4 的 ins_15(floatV0, 0.01309) 加、ins_16(floatV1, 0.01309)
    ---减（case 15 = 加、case 16 = 减；EclRunLow.inl:269/273）⇒ 两组基准角每轮**反向**各转
    ---0.75°，越拉越开 —— 这就是「两组蝶弹」在屏幕上分成两圈的原因。换算到我们这边
    ---（TH095 正角 = 顺时针 ⇒ 取反）：floatV0 那组每轮 −BASE_STEP、floatV1 那组 +BASE_STEP。
    local BASE_STEP = 0.75
    local RING_STYLE = butterfly
    ---色号照原作：两组分别是 color 4 与 color 5。butterfly 不是 colorful 样式 ⇒
    ---贴图下标 = ceil(色号/2)（Lresources.lua:208 的 LoadImageGroup + bulletStyle.lua:64
    ---的 init），于是两组正好落在 butterfly2 / butterfly3 **两张不同的贴图**上。
    local RING_COLOR_A, RING_COLOR_B = COLOR.PURPLE, COLOR.DEEP_BLUE

    ---圈里每一颗自己会**一边转一边减速**（Sub4 的 ins_101 slot0，kind = 0x20 = 极坐标加速，
    ---PhotoBulletSpawnDescriptor.hpp:100；实现在 BulletManager.cpp:822-841 的
    ---UpdatePolarAcceleration）：每帧 angle += angleDelta、speed += speedDelta，
    ---持续 int0 = 120 帧，之后整条 transform 失效、弹保持最后的速度与方向直飞。
    ---  angleDelta = ∓0.019635 rad/帧 = ∓1.125°/帧 —— TH095 是「顺时针为正」，换算到
    ---  我们「逆时针为正」的坐标系要**取反**。RING_SPIN 只记大小，两组在 fire_ring 里
    ---  一个拿 −RING_SPIN、一个拿 +RING_SPIN（见下面 fire_ring 的注释）；
    ---  speedDelta = −0.025/帧 ⇒ 4.0 在 120 帧里线性掉到 1.0。
    ---★ 「120 帧之后必须停」是硬要求：极坐标加速是有时长的 transform，过了就没了；
    ---  一直转下去就成了「1.0 px/帧 + 1.125°/帧」的半径 51 px 小圈 —— 子弹永远出不了
    ---  回收边界，同屏弹数会线性涨（旧版实测 1800 帧 1432 → 7200 帧 5548）。
    ---（frame 钩子只收一个参数，§5.2；「还剩几帧」存在弹自己身上。）
    local RING_SPIN = 1.125
    local RING_DRAG = -0.025
    local RING_MIN_SPEED = 1.0              -- 120 帧刚好减到 1.0，这个下限只是兜底
    local RING_FRAMES = 120

    ---自机狙大圈（Sub5，dump 的 @1204-1352）：ins_88(17, 0, 8, 1, 0.8, 1.5, 0, 0.0327249, 514)。
    ---  · opcode 88 ⇒ aimMode 2 = CIRCLE_AIMED：每一发的角度 = 自机角 + index1×2π/count1，
    ---    也就是**整圈一起转向自机**（BulletManager.cpp:367-372）。
    ---  · count1 = 8（8 等分 45°）、speed1 = 0.8（count2 = 1 ⇒ speed2 不参与）、
    ---    transformFlags 0x202 = 0x200 出场音 + 0x2 SPAWN_FAST（出场回退 4 帧的运动量，
    ---    BulletManager.cpp:445-457；我们出膛就飞）。
    ---  · 间隔由 Sub5 自己算：ins_22(extraIntV0, photoIndex, 10) → ×10、
    ---    ins_21(extraIntV0, 120, extraIntV0) → 120 − 它、ins_2 等这么多帧。
    ---    ins_2 = SET_SECONDARY_TIME：**设它的那一帧就已经算掉 1 帧** —— dispatch 顶部
    ---    看到 secondaryTime > 0 就 secondaryTime-- 与 time-- 相抵、本帧到此为止
    ---    （EclRun.cpp:296-303），帧末再统一 time++（同文件 :422）⇒ 冻结 N 帧之后
    ---    下一发**正好隔 N 帧**，不是 N+1（th31.lua:15230-15235 对同一条指令也是这么算的；
    ---    旧版这里按 N+1 写成 121，自机狙每圈慢 1 帧）。
    ---    ⇒ 每 (120 − 10×photoIndex) 帧一圈，拍得越多压得越密；
    ---    photoIndex ≤ 7（ins_141(7)）⇒ 最密 50 帧，正好是 AIM_GAP_MIN。
    ---弹型 17 = 原作的**大玉**（g_PhotoBulletCollisionSizes[17] = 28，命中框取
    ---±28/2 ⇒ 半径 14；BulletManager.cpp:118-122 与 :1155），这里用本仓库最大的一档
    ---**ball_huge**（bulletStyle.lua:174-180）。原作这一发的色号是 0，但 ball_huge 是
    ---colorful 样式（贴图名 = "ball_huge"..色号），色号 0 会取到不存在的 ball_huge0
    ---（AGENTS §9 A2 会当场报错）⇒ 取同色系的紫 4，和上面两组蝶弹同一族。
    local AIM_COUNT = 8
    local AIM_SPEED = 0.8
    local AIM_STYLE = ball_huge
    local AIM_COLOR = COLOR.PURPLE
    local AIM_GAP_BASE, AIM_GAP_STEP, AIM_GAP_MIN = 120, 10, 50
    local AIM_LIMIT = 7                     -- Sub2 的 ins_141(7)：相机快门上限（photo_index 的截断值）

    ---蛾（Sub3 的 ins_83(6)，子程序 Sub6/Sub7）：原作是一只**真的子敌机** ——
    ---ins_55(12) 指 ANM、ins_143(1,99999) 挂拍照标记、ins_77(8,8) 给个小判定框，
    ---然后 Sub7 每帧 ins_63(photoTarget0.x, photoTarget0.y) 把自己挪到「拍照目标」身上；
    ---它自己**不发弹**（整份 ecl17_a 里只有 Sub4/Sub5 发弹）。
    ---我们这边没有「拍照目标」这个对象、也没有子敌机这一层（§7.3），所以按 §7.4 的 C 类
    ---做成 2 只**不出判定的蝶形装饰**绕自机飞 —— 位置含义从「拍照目标」换成「自机」，
    ---既点了「誘蛾灯」的题，也留下原作那只蛾的存在感。
    ---★ Sub3 的时间基准：它是 Sub2 在 t=130 用 ins_52(3) **同步调用**进来的
    ---（CallSubOnEnemy → EclRunTargetHigh.inl:147 的 enter_subroutine），而 CallEclSub
    --- 会把子上下文的 time 清零（EnemyManagerUpdate.cpp:172-186）⇒ **Sub3 的 t=N 是
    ---「入场结束（第 130 帧）之后再过 N 帧」**，不是第 N 帧。
    ---  所以 Sub3 的 t=600 = 第 730 帧。旧版写成 `MOTH_WAIT - ENTRY_WAIT - ENTRY_TIME`
    ---（= 第 600 帧）早了 130 帧，这里按原文改成「入场之后再等 600 帧」。
    local MOTH_WAIT = 600                   -- Sub3 的 t=600（第 730 帧）
    local MOTH_COUNT = 2
    local MOTH_RADIUS_X, MOTH_RADIUS_Y = 58, 30
    local MOTH_ALPHA = 170                  -- §7.6：装饰层 alpha 压在 120~180

    local CARD_NAME = "幽雅「死出の誘蛾灯」"
    local CARD_TIME = 60
    local CARD_HP = 950
    ---符卡历史槽位（跨关卡唯一）：本关 7 张取 410..415 与 416
    ---（409 被 th31.lua 的 LIST 表占走，详见死符那张的注释）。
    local CARD_ID = 410

    ---──────────────────────── 演出 / 弹幕 ────────────────────────

    ---一只蛾：绕自机转一个小椭圆、上下再摆一点，像绕着灯打转。
    ---纯装饰（§7.4 的 C 类无害实体）：不出判定、不撞自机，只在 render 里画贴图。
    class.moth = Class(object, {
        init = function(self, boss, phase)
            self.boss, self.phase, self.t = boss, phase, 0
            self.group = GROUP.GHOST
            self.layer = LAYER.ENEMY_BULLET_EF
            self.colli = false
            self.bound = false
            self.rot = 0
            self._a = 0
            self.x, self.y = boss.x, boss.y
            task.New(self, function()
                while self._a < MOTH_ALPHA do
                    self._a = min(MOTH_ALPHA, self._a + 5)
                    task.Wait()
                end
            end)
        end,
        frame = function(self)
            ---★ 真机只有 `_object`（THlib/misc/misc.lua:13）和 bullet 的 frame 才带 task.Do；
            ---  `Class(object, {...})` 的子类得**自己驱动** init 里 task.New 出来的协程 ——
            ---  否则它永远不 resume（淡入不跑 ⇒ _a 恒 0 ⇒ 不可见；发弹循环与自灭也都不跑）。
            task.Do(self)
            self.t = self.t + 1
            local a = self.phase + self.t * 1.7
            local tx = player.x + cos(a) * MOTH_RADIUS_X
            local ty = player.y + sin(a) * MOTH_RADIUS_Y + sin(self.t * 2.3) * 10
            self.x = self.x + (tx - self.x) * 0.05
            self.y = self.y + (ty - self.y) * 0.05
            self.rot = self.rot + 2.5
        end,
        render = function(self)
            SetImageState("butterfly2", "mul+add", self._a, 235, 205, 255)
            Render("butterfly2", self.x, self.y, self.rot, 0.85)
        end,
    })

---圈弹每一颗的逐帧钩子：**只在前 RING_FRAMES 帧**自转 + 减速（ins_101 那条 transform
---的时长），之后保持最后的速度与方向直飞（理由见上面 RING_SPIN 的注释）。
---自转方向存在弹自己身上（unit.ring_spin）：原作是**发弹前**把 ins_101 写进 descriptor、
---发弹时整份抄给弹（BulletManager.cpp:484 memcpy）—— 两组色号之间 @1004 又改写过一次，
---所以两组抄到的 angleDelta 符号相反（见 fire_ring）。
    local function ring_frame(unit)
        if unit.spin_left == nil then
            unit.spin_left = RING_FRAMES
            unit.ring_v = RING_SPEED
        end
        if unit.spin_left <= 0 then
            return
        end
        unit.spin_left = unit.spin_left - 1
        unit.ring_v = max(RING_MIN_SPEED, unit.ring_v + RING_DRAG)
        object.SetV(unit, unit.ring_v, unit.rot + unit.ring_spin, true)
    end

---一整圈 16 发（圈里每一颗自己还要转 + 减速，见 ring_frame）；
---spin = 这一圈的自转角速度（度/帧），两组取相反符号。
    local function fire_ring(owner, base, color, spin)
        for i = 0, RING_COUNT - 1 do
            local b = NewSimpleBullet(RING_STYLE, color, owner.x, owner.y, RING_SPEED,
                    base + i * 360 / RING_COUNT, false, 0, false,
                    nil, nil, nil, ring_frame)
            b.ring_spin = spin
        end
        -- transformFlags 的 0x200 = PLAY_SPAWN_SOUND：一整圈只响一声（BulletManager.cpp:717-723）。
        PlaySound("tan00", 0.1, owner.x / 256, false)
    end

    ---主弹幕（Sub4 = ins_117(0,4) 的**子 ECL 上下文**，不是子敌机）：一条上下文、一轮两组。
    ---两条基准角 floatV0/floatV1 从同一个 playerAngle 起，但每轮**反向**转 0.75°（见常量段的
    ---BASE_STEP 注释）⇒ 两组各转各的，这里跟着存两个 base。
    ---★ 两组的自转**方向相反**：slot0 在 @920 先写 angleDelta = +0.019635、@1004 又改成
    ---  −0.019635，而弹是**发弹那一刻**把 descriptor 整份抄走的（BulletManager.cpp:484）
    ---  ⇒ 色号 4 那一组抄到 +0.019635、色号 5 那一组抄到 −0.019635，换算到我们这边
    ---  就是 −RING_SPIN 与 +RING_SPIN（两组反向卷，不是同向）。
    ---★ 两组必须**各卷各的**：自转方向与基准角只要有一处跟着对方走，第二组就会贴着第一
    ---  组的弹道飞（同向 + 同 base ⇒ 第二组只是延迟 4 帧的复制品）—— 16 条弹道上叠两组，
    ---  屏幕上只数得出 16 条臂，正是作者报的「子弹少一半」。原件是**反向自转 + 两组基准角
    ---  每轮各背向 0.75°**，臂越拉越开 ⇒ 32 条臂。这里照原件分开存 base_a / base_b。
    ---★ 节拍照抄那个循环本身：t=0 发 A、t=4 发 B、t=8 跳回 t=0 —— 用**逐帧计数器**
    ---  实现，而不是 task.Wait(4)。理由：真机与桩件对「等一帧」的记账差一帧
    ---  （THlib/lib/Ltask.lua:68-77 的 task.Wait(t) = yield t 次，真机每次 resume 推进一帧
    ---  ⇒ Wait(4) 正好 4 帧；tools/check_stage.lua 的等待计数每帧减一，同一句变成 5 帧），
    ---  而这条弹幕的相位很敏感 —— 用计数器两边就是同一把尺子，自检读数 = 真机读数。
    ---  计数器由 card.frame 驱动：boss_system.lua:133 每帧调一次 `b.current_card.frame(b)`，
    ---  所以「过了几帧」就是帧号，t ≡ 0 / 4 (mod 8) 与原作逐条对齐。
    local ring_t = nil                      -- 开始发弹之后的帧数（nil = 还没开始）
    local ring_base_a, ring_base_b = 0, 0   -- 两组基准角（原作的 floatV0 / floatV1）

    local function ring_begin(owner)
        ring_base_a = Angle(owner, player)
        ring_base_b = ring_base_a
        ring_t = 0
    end

    ---自机狙大圈（Sub5）：从原作第 600 帧起，每 max(50, 120 − 10×photoIndex) 帧一圈 8 发。
    ---aim = true ⇒ 整圈一起转到自机方向（CIRCLE_AIMED 就是把 angleToPlayer 加进每一发的角度）。
    local function aim_stream(owner)
        task.New(owner, function()
            while true do
                for i = 0, AIM_COUNT - 1 do
                    NewSimpleBullet(AIM_STYLE, AIM_COLOR, owner.x, owner.y, AIM_SPEED,
                            i * 360 / AIM_COUNT, true, 0, false)
                end
                PlaySound("tan00", 0.1, owner.x / 256, false)
                task.Wait(max(AIM_GAP_MIN,
                        AIM_GAP_BASE - AIM_GAP_STEP * photo_index(AIM_LIMIT)))
            end
        end)
    end

    ---──────────────────────── 符卡本体 ────────────────────────

    local card = boss.card.New(CARD_NAME, 1, 3, CARD_TIME, CARD_HP)
    ---本卡放出的蛾；卡结束时统一收掉（§7.9 第 9 条）。
    local moths = {}

    function card:before()
        moths = {}
    end

    function card:init()
        photo_damage_on(self, AIM_LIMIT)    -- 拍照扣血：拍够 AIM_LIMIT 张 = 清空血条
        self.x, self.y = BOSS_X, BOSS_START_Y
        task.New(self, function()
            task.Wait(ENTRY_WAIT)
            task.MoveTo(0, BOSS_HOME_Y, ENTRY_TIME, EASE_OUT)
            ---到这里是原作第 130 帧（Sub2 的 ins_52(3) 调用 Sub3），
            ---而 Sub3 的 t=0 同时起主弹幕上下文并响一声（ins_106(5)）。
            PlaySound("tan00", 0.1, self.x / 256, false)
            ring_begin(self)
            ---Sub3 的 t=600（第 730 帧）：亮卡名 → 起自机狙大圈 + 放出蛾。
            ---（我们这边卡名由符卡系统在开场就亮，所以这里只做后两件。）
            ---MOTH_WAIT 是 Sub3 自己的时间（见常量段的说明）⇒ 入场之后直接等它。
            task.Wait(MOTH_WAIT)
            for i = 1, MOTH_COUNT do
                moths[i] = New(class.moth, self, (i - 1) * 180)
            end
            aim_stream(self)
        end)
    end

    ---本体的逐帧逻辑：原作里移动与发弹都挂在 ECL 上下文上，这里只驱动 Sub4 那个
    ---8 帧循环的计数器（见上面 ring_t 的注释）。计数器就绪之后每帧进一次，
    ---相位 0 发第 1 组、相位 SPLIT 发第 2 组并在同一拍推进两组基准角
    ---（原作 @1088/1124 的 ins_15/ins_16 紧跟在 @1044 的第二组之后）。
    function card:frame()
        if not ring_t then
            return
        end
        ---卡结束时本体会先被打死（hp 落 0，checkHP 立刻走 object.Kill，boss_system.lua:351-361），
        ---之后 current_card 还指着这张卡、frame 仍会被调上几帧 —— 自己停手，别在死后接着发弹。
        ---★ 判据只能用 hp，**不能**用 `self.is_combat`：真机上 is_combat 由 setStatus
        ---  （boss_system.lua:874）置 true，可自检桩件的 boss_obj（tools/check_stage.lua:1789）
        ---  根本没这个字段 ⇒ `not self.is_combat` 恒真、蝶弹一帧都发不出来（自检读数全假）。
        ---  hp 两边都有：真机 = 卡结束落 0，桩件 = 9999（永不触发），行为一致。
        ---  `self.hp and` 这一层只是「万一是 nil 也当停手」，顺便满足
        ---  tools/check_fields.lua 对 frame 内读字段必须带守卫的要求。
        if self.hp and self.hp <= 0 then
            ring_t = nil
            return
        end
        local phase = ring_t % CYCLE
        if phase == 0 then
            fire_ring(self, ring_base_a, RING_COLOR_A, -RING_SPIN)   -- @960 t=0：色号 4
        elseif phase == SPLIT then
            fire_ring(self, ring_base_b, RING_COLOR_B, RING_SPIN)    -- @1044 t=4：色号 5
            ---@1088/1124 的 ins_15 / ins_16（@1108/1144 的 ins_37 只是归一化）：
            ---两组基准角反向各转 0.75°，下一轮生效 —— 两组越拉越开。
            ring_base_a = (ring_base_a - BASE_STEP) % 360
            ring_base_b = (ring_base_b + BASE_STEP) % 360
        end
        ring_t = ring_t + 1
    end

    function card:del()
        ---卡结束（kill -> current_card.del(b)，boss_system.lua:241）时把发弹计数器也收掉：
        ---超时结束（hp 没到 0）时 frame 里那条 hp 判据不会触发，这里兜住不多吐一轮。
        ring_t = nil
        photo_damage_off(self)
        for i = #moths, 1, -1 do
            if IsValid(moths[i]) then
                object.RawDel(moths[i])
            end
        end
        moths = {}
    end

    local LEVEL = 31
    boss.card.add({ { card, "1a" } }, LEVEL, CARD_NAME, CARD_ID)
end--幽雅「死出の誘蛾灯」

do  -- 73 蝶符「鳳蝶紋の死槍」（ecl17_b，幽幽子，组 1a 第 2 张）
    ---「鳳蝶紋」是凤蝶翅上的眼斑。本体站定，六只蝶形子机分三档从两侧扎进场地：
    ---起飞那一刻朝自机甩一条直激光、一片**背对自机**的乱枪，然后开始每 2 帧一发的
    ---「死槍」——0.02 px/帧 出膛、120 帧里一路加速到 ~1 px/帧 的窄扇；同时子机自己
    ---朝自机冲（原作 ins_65 把子机的 mvAngle/speed 直接设成 playerAngle / 8）。
    ---我们这边没有「敌机」这一层，子机做成不出判定的**自绘蝶**（GROUP.GHOST +
    ---colli = false），威胁全在弹与激光上（和卡 71 的蛾同一个做法）。
    ---──────────────────────── 常量（改手感只动这一段） ────────────────────────
    ---入场：Sub2 的 ins_63(-128,-64) + t=100 的 ins_64(30,4,0,160) ⇒ 落点 (0,160)
    ---（TH095 坐标）⇒ 我们的 (0, field_y(160) = 64)。三张幽幽子卡的落点刻意不同。
    local BOSS_X = -128
    local BOSS_START_Y = field_y(-64)       -- 288（场地之外）
    local BOSS_HOME_Y = field_y(160)        -- 64
    local ENTRY_WAIT, ENTRY_TIME = 100, 30
    local EASE_OUT = VALUE_SET.DECEL

    ---Sub3 的点位表：t=60 / t=180 / t=270 各放一对子机，t=270 的 ins_4(0,-504) 跳回
    ---循环头 ⇒ 一轮 270 帧。点位（TH095 坐标 → 我们的 y）：
    ---  (∓128, 16) → (∓128, 208)　(∓96, −32) → (∓96, 256)　(∓64, −64) → (∓64, 288)
    ---后两档在我们的场地上沿（y = 224）之外 —— 原作那四只就是从场外扎进来的。
---每档带自己的 (intV6, intV7)。ins_94/ins_87 的操作数顺序是
---(type, color, count1, count2, speed1, speed2, angle, angleStep, flags)
---（ShotArgs, EnemyShotDispatch.cpp:83-95 的字段顺序）⇒
---  · **intV6 = Sub5 乱枪的色号**（count1 是字面量 64，不是 intV6）；
---  · **intV7 = Sub4 死槍的色号**（count1 是字面量 1）—— 三档的区别只有颜色。
---(intV6, intV7) = (6,3) / (8,4) / (10,5)（Sub3 的 ins_6 逐档改）。
    local WAVES = {
        { delay = 60, x = 128, y = 16, volley_color = 6, spear_color = 3 },
        { delay = 120, x = 96, y = -32, volley_color = 8, spear_color = 4 },
        { delay = 90, x = 64, y = -64, volley_color = 10, spear_color = 5 },
    }

---子机（Sub5）在 t=60 那一帧一次做四件事：
---  ins_145(12, intV7, 8, playerAngle, 256, 24) —— 直激光（色号 = intV7）
---  ins_94(1, intV6, **64**, 4.0, 0.5, playerAngle+80°/+280°, 512) —— 64 发的 RANDOM 乱枪
---  ins_117(0,4) —— 起 Sub4 子上下文（下面那个每 2 帧一发单发直弹的「死槍」）
---  ins_65(playerAngle, 8) —— 子机自己朝自机冲（8 px/帧）
    local DRONE_FIRE_DELAY = 60
    local DRONE_DASH = 8
    local LASER_SPEED = 8                   -- ins_145 第 3 个操作数
    local LASER_LEN = 256                   -- 第 5 个：最大长度
    local LASER_GROW = LASER_LEN / LASER_SPEED  -- 32 帧长满
    local LASER_W = 10                      -- 我们 laser 的 w（命中半宽 = w/2，见 laser.lua）
    local LASER_SUSTAIN, LASER_FADE = 40, 20

---Sub4（子上下文）：ins_87(15, intV7, 1, 1, 0.02, 1.5, playerAngle, 0.0327249, 536)。
---★ 对着 ShotArgs 读一遍：**count1 = 1**、intV7 是**色号**（旧注释把它当成发数，错）。
---所以「死槍」是**一帧一发单发直弹**、朝自机，不是 3~5 发的窄扇；节拍每 **2 帧**一发
---（Sub4 的 ins_4(0,-116) 在 t=2 跳回 @1404）。三档子机的区别只有色号 3/4/5。
---出膛点每发重抽：@1404 的 ins_27(·, 24, randF32) + ins_38 把「半径 ≤24 px 的随机点」
---算成二维偏移、ins_100 写进 shootOffset ⇒ 死槍围着子机散开，不是一条精确的线。
---536 = 0x218 = 0x200 出场音 + 0x10 矢量加速 + 0x8 慢出；ins_101(0, 0x10, 0, 120, -1,
---1/120, -999.99) 再给弹挂上「沿自身方向 120 帧、每帧 +1/120 px/帧」的加速
---（0x10 = ACCELERATE_VECTOR，BulletManager.cpp 的 UpdateVectorAcceleration），
---于是 0.02 一路加到 ~1.02 之后常速飞出去。
    local FAN_INTERVAL = 2
    local FAN_OFFSET_R = 24                 -- ins_27 的第 2 个操作数：出膛点随机半径
    local FAN_STEP = 1.875                  -- angleStep：count1 = 1 ⇒ 本卡不参与，留着备查
    local FAN_SPEED = 0.02
    local FAN_ACCEL = 1 / 120
    local FAN_ACCEL_FRAMES = 120
    local FAN_STYLE = butterfly
    local FAN_COLOR = COLOR.PURPLE

---乱枪（ins_94，aimMode 8 = RANDOM）：angle = random(angle ∓ angleStep)、
---speed = random(speed2, speed1)（BulletManager.cpp:383-395）。
---ins_94 的参数 = (type 1, color intV6, **count1 = 64**, count2 = 1, speed1 = 4, speed2 = 0.5,
---angle = floatV0, angleStep = floatV1, flags = 512) ⇒ 一发就是 **64 颗**（不是 intV6×64）。
---floatV0/floatV1 的算法（Sub5 的 ins_25/ins_7/ins_16/ins_15，EclRunLow.inl:296/251/273/269）：
---  floatV0 = playerAngle + π → floatV1 = floatV0 → floatV0 −= 100°、floatV1 += 100°
---  ⇒ 操作数里 floatV0 = playerAngle + 80°、floatV1 = playerAngle + 280°。
---RANDOM 分支算的是 GetRandomF32InRange(angle − angleStep) + angleStep；range 为负
---（80−280 = −200°）时落在 [angleStep − 200°, angleStep] = [playerAngle+80°, playerAngle+280°]
---⇒ **以背对自机方向（playerAngle+180°）为中心、宽 200° 的扇**。
---速度同样随机：RANDOM 分支 speed = random(speed2, speed1) = random(0.5, 4.0)。
    local VOLLEY_ARC = 100
    local VOLLEY_COUNT = 64                 -- ins_94 的 count1
    local VOLLEY_SPEED1, VOLLEY_SPEED2 = 4.0, 0.5
    local VOLLEY_STYLE = water_drop

    ---子机的淡入 / 淡出（它在原作里靠「飞出屏幕就回收」，我们照做）。
    local DRONE_FADE_IN = 15
    local DRONE_ALPHA = 175                  -- §7.6：装饰层 alpha 压在 120~180

    ---Sub2 的 ins_141(7)（dump 的 @464）：相机快门上限，也就是**原作要求拍中的张数**。
    ---前半段（Sub3）的扇与乱枪是定死的；后半段 Sub9 的两处冻结读 photoIndex
    ---（见下面 SUB9_* 那一节），所以它同时是「拍几张过关」和代入值。
    local PHOTO_LIMIT = 7

    ---Sub9 —— 拍中本体第 3 张（ins_115(0,3,"Sub9")）后接管的主脚本。常量照抄 dump：
    ---  · @Sub9_124 的 ins_6(ei0, 4) ⇒ **4 轮**，每轮 3 只子机（共 12 只）；
    ---  · 每轮的三只 = Sub9_144 的三组 (intV6 乱枪色, intV7 死槍色) = (6,3)/(8,4)/(10,5)；
    ---  · 每只的 ins_84("Sub5", ef0, ef1)：ef0/ef1 是 ins_27(rnd_f32s, R) 直接算出来的
    ---    偏移（0x2723 = ECL_RANDOM_F32_SIGNED，EclOperands.hpp:52）⇒ **相对本体**的
    ---    随机点（±144, ±32）；这一句的落点是「本体周围随机」，不是 Sub3 那种固定点。
    ---  · 每只后面 ins_2(ei2)、ei2 = 45 − 5×photoIndex；整轮之后
    ---    ins_2(i5)、i5 = 200 − 30×photoIndex；负值 = ins_2 不冻结（EclRun.cpp:294）。
    local SUB9_AT = 3                       -- ins_115(0, 3, "Sub9") 的 frame
    local SUB9_FILE_DELAY = 60              -- Sub9 的 t=60（@Sub9_124 之前那段 +60 的 ins_0）
    local SUB9_ROUNDS = 4                   -- ins_6(ei0, 4)
    local SUB9_ROUND_COLORS = { { 6, 3 }, { 8, 4 }, { 10, 5 } }   -- (intV6, intV7)
    local SUB9_OFF_X, SUB9_OFF_Y = 144, 32  -- ins_27 的两个半径
    local SUB9_FREEZE_BASE, SUB9_FREEZE_STEP = 45, 5    -- ei2 = 45 − 5×photoIndex
    local SUB9_WAIT_BASE, SUB9_WAIT_STEP = 200, 30      -- i5 = 200 − 30×photoIndex

    local st = { dead = false }
    local sub3tok = nil

    local CARD_NAME = "蝶符「鳳蝶紋の死槍」"
    ---原作卡计时 ins_114(6608) ≈ 110 秒（拍照关留给玩家取景用）；沿用本仓库的 50 秒。
    local CARD_TIME = 50
    ---原作 Timeline0 给的生命是 150；这里按本仓库的量级抬到 900（同卡 71/75）。
    local CARD_HP = 900
    ---符卡历史槽位：卡 71 占了 410，这张往下取 411。
    local CARD_ID = 411

    ---──────────────────────── 演出 / 弹幕 ────────────────────────

    ---本卡放出的激光（卡结束时统一 RawDel，§7.9 第 9 条）。
    local lasers = {}

    ---一条「死槍」激光：CyGrow 以 8 px/帧 长到 256（32 帧）→ 维持 40 帧 → 收 20 帧。
    ---⚠ 计时**不能挂在 laser 自己身上**：laser:frame 只在真机里调 task.Do
    ---（THlib/laser/laser.lua:65），而 tools/check_stage.lua 的 laser 桩件不调 ——
    ---挂上去自检里永远不收，7200 帧会攒下上百条激光、看着像泄漏。
    ---所以计时挂在 boss 身上（boss_system 每帧 task.Do），换卡时被 task.Clear 清掉。
    local function fire_spear_laser(drone, x, y, a, color)
        local owner = drone.owner
        local l = New(laser, color, x, y, a, 0, 0, 0, LASER_W, LASER_W, 0)
        laser.CyGrow(l, LASER_SPEED, LASER_GROW, 3, a, true)
        lasers[#lasers + 1] = l
        drone.my_lasers[#drone.my_lasers + 1] = l
        task.New(owner, function()
            task.Wait(LASER_GROW + LASER_SUSTAIN)
            if IsValid(l) then
                laser._TurnOff(l, LASER_FADE, true)
                task.Wait(LASER_FADE)
                if IsValid(l) then
                    object.Del(l)
                end
            end
        end)
    end

    ---窄扇里每一颗的逐帧钩子：只在前 120 帧沿自身方向加速，之后保持末速直飞。
    ---（frame 钩子只收一个参数，§5.2；和卡 71 的 ring_frame 一样**必须停**，
    ---否则一直加速的弹永远出不了回收边界。）
    ---★ ins_87 的 flags 536 里还有 0x8 = SPAWN_SLOW（出场时先退到 velocity×4 再滑回来，
    ---BulletManager.cpp:445-478）；本文件统一不做这层出场滑动（见文件头差异 10），
    ---速度曲线与弹数不变，只是这发「死槍」早几帧到位。
    local function spear_frame(unit)
        if unit.accel_left == nil then
            unit.accel_left = FAN_ACCEL_FRAMES
            unit.cur_v = FAN_SPEED
        end
        if unit.accel_left <= 0 then
            return
        end
        unit.accel_left = unit.accel_left - 1
        unit.cur_v = unit.cur_v + FAN_ACCEL
        object.SetV(unit, unit.cur_v, unit.rot, true)
    end

---Sub4 的一发「死槍」：**单发**朝自机；出膛点每发在子机周围 24 px 内重抽。
---color = intV7（三档 3/4/5）。
    local function fire_fan(x, y, color)
        local base = Angle(x, y, player.x, player.y)
        local pa = ran:Float(0, 360)
        local pr = FAN_OFFSET_R * ran:Float(0, 1)
        NewSimpleBullet(FAN_STYLE, color,
                x + cos(pa) * pr, y + sin(pa) * pr,
                FAN_SPEED, base, false, 0, false,
                nil, nil, nil, spear_frame)
    end

---Sub5 的一片乱枪：64 颗、整片背对自机（±100°）、随机角度、随机速度。
---color = intV6（三档 6/8/10）。
    local function fire_volley(x, y, color)
        local center = Angle(x, y, player.x, player.y) + 180
        for _ = 1, VOLLEY_COUNT do
            NewSimpleBullet(VOLLEY_STYLE, color, x, y,
                    ran:Float(VOLLEY_SPEED2, VOLLEY_SPEED1),
                    center + ran:Float(-VOLLEY_ARC, VOLLEY_ARC), false, 0, false)
        end
        PlaySound("tan00", 0.1, x / 256, false)
    end

---蝶形子机（Sub5 的本体）。自己做自己的回收：起飞后活 DRONE_LIFE 帧就淡出，
---淡出期间先把自己的激光收掉（激光比子机活得久一点）。
    class.spear_drone = Class(object, {
        init = function(self, owner, x, y, spear_color, volley_color)
            self.owner = owner
            self.spear_color, self.volley_color = spear_color, volley_color
            self.group = GROUP.GHOST
            self.layer = LAYER.ENEMY_BULLET_EF
            self.colli = false
            self.bound = false               -- 自己管回收（下面那个协程）
            self.x, self.y = x, y
            self.rot = 0
            self._a = 0
            self.my_lasers = {}
            ---一条协程干完整个 Sub5（★ 不要在里面再 task.New 一条常驻循环：
            ---tools/check_stage.lua 的协程表是全局摊平的，挂在对象名下的 while true
            ---在对象被 RawDel 之后照样会被 resume —— 自检会报「卡结束后还在发弹」。）
            task.New(self, function()
                ---fade in（§7.6：装饰层用淡入，不要凭空出现）
                for _ = 1, DRONE_FADE_IN do
                    self._a = min(DRONE_ALPHA, self._a + DRONE_ALPHA / DRONE_FADE_IN)
                    task.Wait()
                end
                ---Sub5 的 t=60：四条一起（激光 / 乱枪 / 窄扇子上下文 / 起飞）。
                ---★ 淡入的那 15 帧算在这 60 帧里 —— 原作子机生成后第 60 帧开火
                ---（Sub5 的 t=60，上下文建于 t=0），淡入只是本仓库的装饰层笔法；
                ---分开等会变成 75 帧，比原作晚 15 帧。
                task.Wait(DRONE_FIRE_DELAY - DRONE_FADE_IN)
                local a = Angle(self.x, self.y, player.x, player.y)
                fire_spear_laser(self, self.x, self.y, a, self.spear_color)
                fire_volley(self.x, self.y, self.volley_color)
                object.SetV(self, DRONE_DASH, a, true)
                ---Sub4 的死槍：每 FAN_INTERVAL 帧一发单发直弹，直到自己飞出场地为止
                ---（原作靠敌人的 offscreen 检查收掉，这里照做；原作没有「贴脸停火」，
                ---这里也不加 —— 距离由子机自己冲过来决定，玩家有 20 帧按快门）。
                local w = lstg.world
                while self.x > w.l - 64 and self.x < w.r + 64
                        and self.y > w.b - 64 and self.y < w.t + 64 do
                    fire_fan(self.x, self.y, self.spear_color)
                    task.Wait(FAN_INTERVAL)
                end
                ---冲出场地：淡出、把自己那几条激光一起收掉。
                for _ = 1, 20 do
                    self._a = max(0, self._a - DRONE_ALPHA / 20)
                    task.Wait()
                end
                for i = #self.my_lasers, 1, -1 do
                    if IsValid(self.my_lasers[i]) then
                        object.RawDel(self.my_lasers[i])
                    end
                end
                self.my_lasers = {}
                object.RawDel(self)
            end)
        end,
        frame = function(self)
            task.Do(self)
            self.rot = self.rot + 4          -- 自转，让蝶看起来在扑翅
        end,
        render = function(self)
            SetImageState("butterfly2", "mul+add", self._a, 224, 186, 252)
            Render("butterfly2", self.x, self.y, self.rot, 1.15)
            SetImageState("butterfly6", "mul+add", self._a * 0.7, 196, 156, 244)
            Render("butterfly6", self.x - cos(self.rot) * 12, self.y - sin(self.rot) * 12,
                    self.rot + 40, 0.85)
        end,
    })

    ---──────────────────────── 符卡本体 ────────────────────────

    local card = boss.card.New(CARD_NAME, 1, 3, CARD_TIME, CARD_HP)
    ---本卡放出的子机（Sub3 的六只与 Sub9 的十二只共用）；卡结束时统一收掉（§7.9 第 9 条）。
    local drones = {}

    ---ins_85：删掉所有子敌机（EclRunTargetHigh.inl 的 ins_85 分支；我们是自绘子机）。
    local function clear_drones()
        for i = #drones, 1, -1 do
            if IsValid(drones[i]) then
                ---★ 先 task.Clear 再 RawDel：协程是挂在子机名下的，
                ---自检的协程表不认「对象已死」这件事（见子机 init 里的注），
                ---不清的话那 180 帧里它还会接着发弹。
                task.Clear(drones[i])
                object.RawDel(drones[i])
            end
        end
        drones = {}
    end

    ---ins_102：清屏（DespawnAllBullets，EclRunTargetHigh.inl:470）+ 本卡自己放出的激光。
    local function clear_screen()
        object.BulletDo(function(b) object.RawDel(b) end)
        for i = #lasers, 1, -1 do
            if IsValid(lasers[i]) then
                object.RawDel(lasers[i])
            end
        end
        lasers = {}
    end

    ---Sub9（@3540）—— 拍中本体第 3 张后接管的主脚本。
    ---原作的 t=0 是 ins_106 + ins_102（清屏）+ ins_85（清子机）+ ins_106 + ins_83("Sub6")；
    ---Sub6/Sub7 是一张 ANM 12 的整屏叠图 + ins_63 每帧把自己挪到拍照目标（ptTarget），
    ---和「死符」那一张的 Sub4/Sub5 是同一份装饰 —— sprite 拿不到 ⇒ 按文件头差异 1)
    ---交给符卡背景，这里不实现（它也不发弹）。
    local function run_sub9(owner)
        PlaySound("tan00", 0.1, owner.x / 256, false)   -- ins_106
        clear_screen()                                  -- ins_102
        clear_drones()                                  -- ins_85
        for _ = 1, SUB9_FILE_DELAY do                   -- Sub9 的 +60（@Sub9_124 之前）
            if st.dead then return end
            task.Wait(1)
        end
        while not st.dead do
            for _ = 1, SUB9_ROUNDS do
                ---ei2 = 45 − 5×photoIndex，每轮重算（跳回 Sub9_144 落在 ins_22/ins_21 上）。
                local freeze = SUB9_FREEZE_BASE
                        - SUB9_FREEZE_STEP * photo_index(PHOTO_LIMIT)
                for k = 1, #SUB9_ROUND_COLORS do
                    if st.dead then return end
                    local c = SUB9_ROUND_COLORS[k]
                    ---ins_84("Sub5", ef0, ef1)：ef0/ef1 是 ins_27(rnd_f32s, R) 直接算出来的
                    ---偏移、**相对本体**（落点 = 父坐标 + 偏移，EclRunTargetHigh.inl:271-310）。
                    drones[#drones + 1] = New(class.spear_drone, owner,
                            owner.x + SUB9_OFF_X * ran:Float(-1, 1),
                            owner.y - SUB9_OFF_Y * ran:Float(-1, 1),
                            c[2], c[1])
                    for _ = 1, max(0, freeze) do            -- ins_2(ei2)，≤0 不冻结
                        if st.dead then return end
                        task.Wait(1)
                    end
                end
            end
            ---i5 = 200 − 30×photoIndex；之后 ins_4(60, Sub9_124) 把 ei0 重置成 4、t 留在 60。
            local wait = SUB9_WAIT_BASE - SUB9_WAIT_STEP * photo_index(PHOTO_LIMIT)
            for _ = 1, max(0, wait) do
                if st.dead then return end
                task.Wait(1)
            end
        end
    end

    function card:before()
        drones = {}
        lasers = {}
        st = { dead = false }
        sub3tok = nil
    end

    function card:init()
        photo_damage_on(self, PHOTO_LIMIT)  -- 拍照扣血：拍够 PHOTO_LIMIT 张 = 清空血条
        self.x, self.y = BOSS_X, BOSS_START_Y
        task.New(self, function()
            local tok = { alive = true }
            sub3tok = tok
            ---可被 ins_115 的重开打断的 task.Wait（原作那一刻主上下文被整个换掉）。
            local function step(n)
                for _ = 1, n do
                    if not tok.alive or st.dead then return false end
                    task.Wait(1)
                end
                return true
            end
            if not step(ENTRY_WAIT) then return end
            task.MoveTo(0, BOSS_HOME_Y, ENTRY_TIME, EASE_OUT)
            ---到这里是原作第 130 帧：Sub2 的 ins_52(3) 调 Sub3，
            ---而 Sub3 的 t=0 就是 ins_106(5)（一个定位置的音效）。
            PlaySound("tan00", 0.1, self.x / 256, false)
            while tok.alive and not st.dead do
                for _, w in ipairs(WAVES) do
                    if not step(w.delay) then return end
                    for _, sx in ipairs({ -1, 1 }) do
                        drones[#drones + 1] = New(class.spear_drone, self,
                                sx * w.x, field_y(w.y), w.spear_color, w.volley_color)
                    end
                end
            end
        end)
        ---ins_115(0,3,"Sub9")：拍中本体第 3 张时把主上下文整个换掉 —— 释放全部子上下文
        ---（EnemyManagerUpdate.cpp:1281-1310）⇒ Sub3 的撒子机循环当场停下。
        task.New(self, function()
            while not st.dead and photo_index(PHOTO_LIMIT) < SUB9_AT do
                task.Wait(1)
            end
            if st.dead then return end
            if sub3tok then sub3tok.alive = false; sub3tok = nil end
            run_sub9(self)
        end)
    end

    ---本体的逐帧逻辑：**原作没有**（移动与发弹都在 ECL 上下文里）。frame 留空是刻意的。
    function card:frame()
    end

    function card:del()
        st.dead = true
        if sub3tok then sub3tok.alive = false; sub3tok = nil end
        photo_damage_off(self)
        clear_drones()
        for i = #lasers, 1, -1 do
            if IsValid(lasers[i]) then
                object.RawDel(lasers[i])
            end
        end
        lasers = {}
    end

    boss.card.add({ { card, "1a" } }, LEVEL, CARD_NAME, CARD_ID)
end--蝶符「鳳蝶紋の死槍」

do  -- 75 死符「酔人の生、死の夢幻」（ecl17_c，幽幽子，组 1a 第 3 张）
    ---──────────────────────── 常量（改手感只动这一段） ────────────────────────
    ---入场：Sub2 第一帧是 ins_63(-128,-64)（绝对设位置，EclRunLow.inl 的 63 分支），
    ---t=100 的 ins_64(30,4,0,128) 用 30 帧走到 (0,128)。
    ---（ins_64 = ConfigureRelativeMotion，EclHelpers.cpp:43：以「插值到绝对目标点」
    ---的方式移动、顺带把速度清零；第 2 个操作数是缓动，1 = 二次加速、4 = 二次减速，
    ---见 th095/src/PhotoEnemyControl.hpp:18-24。）
    local BOSS_X = -128
    local BOSS_START_Y = field_y(-64)       -- 288：场地之外（上边界是 224）
    local BOSS_HOME_Y = field_y(128)        -- 96
    local ENTRY_WAIT = 100                  -- 原作 t=100 才动
    local ENTRY_TIME = 30

    ---扫动循环（Sub3）：四条腿、每条 400 帧、缓动 1/4/1/4、目标 y = 256/448/256/64，
    ---末尾 ins_4(0,-112) 跳回第一条腿（EclRunLow.inl:242-246：JUMP 把 time 设成
    ---第 1 个操作数、再按第 2 个操作数按字节跳转）。
    local LEG_TIME = 400
    local SWEEP_MID = field_y(256)          -- -32
    local SWEEP_BOTTOM = field_y(448)       -- -224（场地下沿）
    local SWEEP_TOP = field_y(64)           -- 160
    local EASE_IN = VALUE_SET.ACCEL         -- th095 缓动 1 = 二次加速（= n²）
    local EASE_OUT = VALUE_SET.DECEL        -- th095 缓动 4 = 二次减速（= 2n-n²）

    ---两股整圈弹（Sub7 / Sub8）：同一份循环体、循环头的 time 分别是 14 与 0，
    ---所以都是每 28 帧一圈、相位差 14 帧 ⇒ 合起来每 14 帧一圈。
    local RING_PERIOD = 28
    local RING_PHASE = 14
    ---ins_89 的 aimMode = opcode − 0x56 = 3 = CIRCLE（EnemyShotDispatch.cpp:145、
    ---BulletManager.hpp:165-174）：angle = index1*2π/count1 + index2*angleStep + angle，
    ---速度 = speed1（count2 = 1 时 speed2 不参与，BulletManager.cpp:345-350）。
    ---操作数里的 angleStep = 0.18479957（= 2π/34）在这张卡里**没用**：它乘的是 index2，
    ---而 count2 = 1 ⇒ index2 恒为 0。
    local RING_SPEED = 1.3
    local RING_BASE_COUNT = 32              -- ins_20：count1 = camera.photoIndex + 32
    local PHOTO_LIMIT = 10                  -- ins_141(10) ⇒ count1 上限 42（photo_index 的截断值）

    ---两股弹的样式/颜色。原作两股是 type18/color0 与 type15/color4 两道 ANM 脚本，
    ---贴图都是小玉；这里按作者要求换成**蝶与水**滴，两股一眼分得开（§7.6：一张卡
    ---只用一个色系，所以两个都压在紫里）。颜色下标是照贴图像素挑的，不是猜的：
    ---  · butterfly 有 8 行（bullet4.png 的 x=832..864），第 2 行平均 (228,201,237)
    ---    是淡紫；butterfly 的 DeFineBulletStyle 没给 colorful ⇒ 贴图下标 = ceil(色号/2)，
    ---    所以色号 4 落在第 2 行。
    ---  · water_drop 有 16 行，water_drop3 = (104,47,207) 深紫（colorful ⇒ 色号 = 下标）。
    local RING_STYLE_A = butterfly
    local RING_STYLE_B = water_drop
    local RING_COLOR_A = COLOR.PURPLE         -- Sub8 那圈：原作 type15（半径 4.0）→ butterfly（淡紫）
    local RING_COLOR_B = COLOR.DEEP_PURPLE    -- Sub7 那圈：原作 type18（半径 3.0）→ water_drop（深紫）

    local CARD_NAME = "死符「酔人の生、死の夢幻」"
    ---原作卡计时是 ins_114(10208) ≈ 170 秒 —— 那是拍照关留给玩家取景用的。
    ---我们按本仓库符卡惯例取 50 秒（th095.lua 的卡是 45~55 秒）。
    local CARD_TIME = 50
    ---原作 Timeline0 生成本体时给的生命是 150（life；我们这边的 HP 量级见 th095.lua
    ---的 550~900）。
    local CARD_HP = 900
    ---符卡历史的槽位号（spell_card_data 的键，也是符卡练习的解锁 id），跨关卡唯一。
    ---实测：把全项目的 boss.card.add 末参 **和 th31.lua 的 LIST 表第 3 项**一起数，
    ---th31 占 351..367 与 370..**409**（409 就是它 LIST 里「秘術「天文密葬法」」那行）、
    ---th32 占 368/369、本关另 6 张占 410..415，所以 1..415 全满、这张取 416。
    ---⚠ 409 这个坑说明：**只扫 boss.card.add 的末参会漏掉 th31 的 LIST**
    ---（它的 id 写在表里、由变量传进 add），照那种扫法挑的"空号"一注册就被
    ---  `check_stage.lua --all` 报「card_id 跨组重复：N（spell_card_data 会串）」。
    local CARD_ID = 416

    ---──────────────────────── 演出 / 弹幕 ────────────────────────

    ---Sub7 / Sub8 的一次发弹：一整圈、定速直线。
    ---count1 的操作数是变量（ins_20 把 camera.photoIndex + 32 写进 intV0），
    ---所以每圈都在发弹那一刻重读一次 —— 两条上下文读的是同一个值，永远一致。
    local function fire_ring(owner, style, color)
        local count = RING_BASE_COUNT + photo_index(PHOTO_LIMIT)
        local base = ran:Float(0, 360)      -- 原作 ins_89 的 angle = random(−π,π)
        local x, y = owner.x, owner.y
        for i = 0, count - 1 do
            NewSimpleBullet(style, color, x, y, RING_SPEED,
                    base + i * 360 / count, false, 0, false)
        end
        -- flags 的 0x200 = PLAY_SPAWN_SOUND：整圈只响一声（BulletManager.cpp:717-723），
        -- 与逐发的出场音不同。
        PlaySound("tan00", 0.1, x / 256, false)
    end

    ---一条发弹上下文（Sub7 或 Sub8）：先等自己的相位，然后每 28 帧一圈。
    local function ring_stream(owner, phase, style, color)
        task.New(owner, function()
            task.Wait(phase)
            while true do
                fire_ring(owner, style, color)
                task.Wait(RING_PERIOD)
            end
        end)
    end

    ---──────────────────────── 符卡本体 ────────────────────────

    local card = boss.card.New(CARD_NAME, 1, 3, CARD_TIME, CARD_HP)

    function card:before()
    end

    function card:init()
        photo_damage_on(self, PHOTO_LIMIT)  -- 拍照扣血：拍够 PHOTO_LIMIT 张 = 清空血条
        ---入场点：原作本体第一帧就把自己定到 (-128,-64)（场地外），第 100 帧才起步。
        self.x, self.y = BOSS_X, BOSS_START_Y
        task.New(self, function()
            task.Wait(ENTRY_WAIT)
            task.MoveTo(0, BOSS_HOME_Y, ENTRY_TIME, EASE_OUT)
            ---到这里是原作第 130 帧：Sub2 在 t=130 CALL Sub3，而 Sub3 的 t=0 同时
            ---起两股整圈弹、开扫动循环、响一声（ins_106(5)，一个定位置的音效）。
            PlaySound("tan00", 0.1, self.x / 256, false)
            ring_stream(self, 0, RING_STYLE_A, RING_COLOR_A)
            ring_stream(self, RING_PHASE, RING_STYLE_B, RING_COLOR_B)
            while true do
                task.MoveTo(0, SWEEP_MID, LEG_TIME, EASE_IN)
                task.MoveTo(0, SWEEP_BOTTOM, LEG_TIME, EASE_OUT)
                task.MoveTo(0, SWEEP_MID, LEG_TIME, EASE_IN)
                task.MoveTo(0, SWEEP_TOP, LEG_TIME, EASE_OUT)
            end
        end)
    end

    ---本体的逐帧逻辑：**原作没有**。它的移动、发弹、位置跟随全在 ECL 上下文里
    ---（Sub3 的 ins_64、Sub7/Sub8 的 ins_89），我们照抄成协程；frame 留空是刻意的，
    ---不是漏写。（挂在本体上的协程由 boss_system 的 task.Clear 在换卡时统一清掉。）
    function card:frame()
    end

    function card:del()
        photo_damage_off(self)
    end

    boss.card.add({ { card, "1a" } }, LEVEL, CARD_NAME, CARD_ID)
end--死符「酔人の生、死の夢幻」

do  -- 77 「死蝶浮月」（ecl17_d，幽幽子，组 1a 第 4 张）
    ---「死蝶浮月」= 一群死蝶绕着浮在空中的月亮打转。原作（/tmp/B_ecl17_d.txt）的骨架是四层：
    ---  · Sub4 + Sub3：本体在 320x64 的框里慢慢晃（ins_75 划框、ins_67 边界感知走位），
    ---  · Sub5：**两股反向自转的双色整圈**（ins_89 发弹 + ins_101 的 0x20 极坐标加速），
    ---  · Sub7：每 30 帧一圈 12 发的自机狙大玉（ins_88，type17 = 半径 14 的大玉），
    ---  · Sub6：48 根放射状激光（ins_153）—— 这张卡的招牌。
    ---激光为什么锚在本体上：ins_153 的第 11 个操作数 followPhotoTarget = 1
    ---（EclRunHigh.inl:729-750 原样照抄进 args.flags；PhotoEffect.cpp:362 的 Update
    ---把它当「每帧把 position 设到 photoTarget0 上」），而 Sub2 的 ins_109(0)
    ---把本体自己登记成了 photoTarget0（EclRunTargetHigh.inl:104-118 的 ins_109 分支）。
    ---⇒ 48 根光柱是**从「月亮」里射出来的**。我们没有相机这一层，激光直接锚在本体上。
---★ 激光扇**不打折**：48 根、角距 7.5°、前摇 120 帧、长度 512、扇面不自转
---（原作 angularVelocity = 0，靠「本体在晃」+「每轮换随机基准角」两种运动），
---全部照 ins_153 的操作数（见下面常量段）。48 根 16 px 宽的光柱在 r < 122 px 内
---确实是实心的（角距 0.131 rad × r < 16）—— 那是原作的形状，不再压。
    ---──────────────────────── 常量（改手感只动这一段） ────────────────────────
    ---入场：Sub2 t=0 的 ins_63(-128,-64)、t=100 的 ins_64(30,4,0,256)。
    local BOSS_X, BOSS_START_Y = -128, field_y(-64)     -- 288（场地外）
    local BOSS_HOME_Y = field_y(256)                    -- -32（比中心略低）
    local ENTRY_WAIT, ENTRY_TIME = 100, 30
    local EASE_OUT = VALUE_SET.DECEL

    ---扫动（Sub4）：ins_75(-160,192,160,256) 划出 x∈[-160,160]、y∈[192,256]（TH095 坐标）
    ---⇒ 我们的 y∈[field_y(256), field_y(192)] = [-32, 32]。
    ---ins_67(91,1,0.3) = 边界感知走位 91 帧、速度 0.3；t=90 的
    ---ins_66(91,4,mvAngle,0.3) 再沿**同一个方向**走 91 帧（缓动 4 = 二次减速）
    ---（BeginBoundaryAwareMove，EclDependencies.cpp:108：随机挑一个偏向自机的角度，
    ---靠墙时反射；ins_66 的 ConfigurePolarMotion 见 EclHelpers.cpp:28）。
    ---⇒ 一轮 181 帧、走 ~54 px。原作 0.3 px/帧 是真的慢，「浮月」本来就不该乱跑。
    local BOX_L, BOX_R = -160, 160
    local BOX_B, BOX_T = field_y(256), field_y(192)     -- -32 / 32
    local LEG_TIME = 91
    local SWEEP_SPEED = 0.3
    local SWEEP_SPREAD = 40                  -- 方向相对「自机方向」的散角（度）

    ---双色环（Sub5）：整圈 16 发（ins_89(22, 4, 16, 1, 1.0, 1.5, floatV0, 0.0327249)，
    ---type22 = 半径 4、color 4；t=20 再发一圈 color 5）、速 1.0；
    ---ins_101(1, 0x20, 0, 600, -1, 0, ±0.0261799) 给弹挂上
    ---「每帧 angle ± 1.5°、速度不变、持续 600 帧」的极坐标加速（BulletManager.cpp
    ---的 ACCELERATE_POLAR：exStates[2].angleDelta）。t=40 的 ins_4(0,-248) 跳回
    ---@1240（也就是 t=0 那两条 ins_101）⇒ **40 帧一轮、一轮两圈**
    ---（t=0 → t=40 = 40 帧；跳转同帧派发，见卡 71 的注释）。
    ---半径 = v/ω = 1.0 / 0.02618 = 38 px ⇒ 一圈蝶会绕着出发点卷成一个小旋涡（母题正中）。
---★ 转向时长照原作 600 帧（ins_101 slot1 的 int0 = 600）：这 10 秒里蝶一直绕着出发点
---卷（半径 = v/ω = 38 px），10 秒后放它们直线飞出去（见 swirl_frame 的注释）。
    local RING_PERIOD = 40
    local RING_PHASE = 20                    -- 两圈相隔 20 帧（t=0 与 t=20）
    local RING_COUNT = 16
    local RING_SPEED = 1.0
    local RING_SPIN = 1.5                    -- ±1.5°/帧
    local RING_SPIN_FRAMES = 600
    local RING_STYLE_A, RING_STYLE_B = butterfly, butterfly
    ---颜色下标是照贴图挑的（LoadImageGroup('butterfly','bullet4',832,0,32,32,1,8) 的
    ---8 行；非 colorful ⇒ 贴图号 = ceil(色号/2)）：
    ---色号 4 → butterfly2 = (228,201,237) 淡紫；色号 5 → butterfly3 = (190,190,242) 蓝紫。
    ---两个都在紫系里、又一眼分得开（§7.6）。
    local RING_COLOR_A, RING_COLOR_B = COLOR.PURPLE, COLOR.DEEP_BLUE

    ---小环（Sub7）：ins_88(17, 1, 12, 1, 2.5, 1.5, 0, 0.0327249, 514) = CIRCLE_AIMED、
    ---type17（半径 14 的大玉）12 发、整圈、速 2.5；ins_4(0,-44) 跳回 t=0（t=30）⇒ 每 30 帧。
    ---type 17 = 原作的**大玉**，按文件头差异 2 用本仓库最大的一档 **ball_huge**
    ---（同卡 71 的自机狙大圈，那边也是 type 17）。ball_huge 是 colorful 样式 ⇒
    ---贴图名 = "ball_huge"..色号，原作的色号 1 直接可用。
    ---★ 这三条时间（TICK_FIRST / FAN_FIRST / MOTH_MORE）都是 **Sub3 自己的 t**：
    ---Sub3 是 Sub2 在 t=130 用 ins_52(3) 同步调用的，CallEclSub 把子上下文 time 清零
    ---（EnemyManagerUpdate.cpp:172-186）⇒ 「Sub3 的 t=N」= 入场结束（第 130 帧）之后
    ---再过 N 帧。旧版把这三个数又减了一次 ENTRY_WAIT+ENTRY_TIME，整体早了 130 帧
    ---（第一组死蝶那条（t=0）没减，所以旧版自己也是前后不一致的）。
    local TICK_FIRST = 470                  -- Sub3 的 t=470 ⇒ 第 600 帧
    local TICK_PERIOD = 30
    local TICK_COUNT = 12
    local TICK_SPEED = 2.5
    local TICK_STYLE = ball_huge
    local TICK_COLOR = 1                    -- ins_88 的 color（ball_huge 是 colorful：1..16）
    ---★ 自检偶尔会报这张「贴脸狙」（最多 8 发/1200 帧、最短 0 帧）：小环是 ins_88
    ---的 CIRCLE_AIMED、出膛点就是**本体所在点**，所以自机贴在本体身上时那颗是瞬发。
    ---那不是「必中设计」—— 自机站在离本体 5 px 的地方，真机上先被本体撞到；
    ---6 个种子死局全 0，所以照原作的形状留着。

    ---激光扇（Sub6）：ins_153(12, 3, floatV0, 512, 16, 120, 20, 60, 20, 0, 1)
    ---  type 12、color 3、基准角 = random(-π,π)、最大长度 512、最大宽度 16、
    ---  前摇 120 帧 → 张开 20 帧 → 维持 60 帧 → 收 20 帧，followPhotoTarget = 1。
    ---  ins_15(floatV0, 0.1309) + ins_5(0,-84,extraIntV0=48) ⇒ 48 根、每根差 7.5°。
    ---  命中半宽 = 宽度/2 = 8（PhotoEffect.cpp:436-440：width < 32 时取 width*0.5），
    ---  我们的 laser 命中半宽 = w/2 ⇒ LASER_W 也填 16。
---前摇照原作 120 帧；「张开」用我们的 laser:_TurnOn(GROW) 做
---（alpha 与 w 一起涨 ⇒ 视觉上就是一根细线亮起来）。
---★ 四个时长/根数都照 ins_153 的操作数：前摇 120、张开 20、维持 60、收 20、48 根。
    local FAN_FIRST = 320                    -- Sub3 的 t=320 ⇒ 第 450 帧（第一轮扇）
    ---第二轮在 Sub3 的 t=910（320 + 60 + 530），之后每 530 帧一轮：Sub3 的 t=1000
    ---ins_4(470,-20) 把 time 拨回 470、跳回 t=910 的 @964（跳转后同帧派发），
    ---所以从那一轮起周期才是 530。
    local FAN_INTERVAL = 530
    local FAN_COUNT = 48                     -- ins_5(0,-84,extraIntV0=48)：48 根、每根 7.5°
    local FAN_WARN = 120
    local FAN_GROW = 20
    local FAN_HOLD = 60
    local FAN_FADE = 20
    local FAN_SPIN = 0                       -- 原作 angularVelocity = 0（扇面不自转）
    local LASER_INDEX = 3                    -- 原作的 color 3（laser 的颜色下标 1..16）
    local LASER_W = 16                       -- 命中半宽 = 8
    local LASER_LEN = 512                    -- ins_153 的最大长度
    ---laser1 的贴图是 64+128+64 = 256 px 三段，按 LASER_LEN 的比例切 ⇒ 拉长 1.56 倍。
    local LASER_SEG1, LASER_SEG2 = LASER_LEN * 0.25, LASER_LEN * 0.5

    ---死蝶（Sub3 的 ins_83(4) + t=380 的 ins_83(8)）：原作放出来的是敌机
    ---（ins_83 的 TH095 分支见 EclRunTargetHigh.inl:271-281），这里按 §7.4 的 C 类
    ---做成**不出判定的蝶形装饰**绕本体飞 —— 正好接住「死蝶」这层意思。
    ---第一组 4 只在 Sub3 的 t=0（= 出场后的第 130 帧）立刻放，第二组 8 只在 t=380。
    local MOTH_MORE = 380                   -- Sub3 的 t=380 ⇒ 第 510 帧
    local MOTH_COUNT1, MOTH_COUNT2 = 4, 8
    local MOTH_ALPHA = 165                   -- §7.6：装饰层 alpha 压在 120~180

    ---Sub2 的 ins_141(4)（dump 的 @468）：相机快门上限，也就是**原作要求拍中的张数**。
    ---这张卡的弹幕不读 photoIndex（原作四层都是定死的），所以它只用在「拍几张过关」上
    ---（见文件头「拍照扣血」那一节）。
    local PHOTO_LIMIT = 4

    local CARD_NAME = "「死蝶浮月」"
    ---原作卡计时 ins_114(8408) ≈ 140 秒（拍照关留给玩家取景用）；沿用本仓库的 55 秒。
    local CARD_TIME = 55
    ---原作 Timeline0 给的生命是 150；这里按本仓库的量级抬到 1000（本卡四层同时压）。
    local CARD_HP = 1000
    ---符卡历史槽位：410/411 已被卡 71/73 占掉、416 被卡 75 占掉，这张取 412。
    local CARD_ID = 412

    ---──────────────────────── 演出 / 弹幕 ────────────────────────

    ---本卡放出的激光与死蝶（卡结束时统一收掉，§7.9 第 9 条）。
    local lasers = {}
    local moths = {}

    ---双色环里每一颗的逐帧钩子：前 RING_SPIN_FRAMES 帧每帧把方向拧 ±RING_SPIN 度
    ---（速度不变 ⇒ 极坐标加速，跟原作 ins_101 的 0x20 一致），之后放开直线飞走。
    ---（frame 钩子只收一个参数，§5.2；**必须停**，否则弹永远绕在原地。）
    local function swirl_frame(unit)
        if unit.spin_left == nil then
            unit.spin_left = RING_SPIN_FRAMES
        end
        if unit.spin_left <= 0 then
            return
        end
        unit.spin_left = unit.spin_left - 1
        object.SetV(unit, RING_SPEED, unit.rot + unit.spin, true)
    end

    ---一整圈 RING_COUNT 发（原作 ins_89：CIRCLE，count2 = 1 ⇒ 操作数里的 angleStep 不参与）。
    ---spin = ±RING_SPIN，两圈反向自转 ⇒ 一眼看得出是两个旋涡错开转。
    local function fire_ring(owner, base, color, spin)
        local x, y = owner.x, owner.y
        for i = 0, RING_COUNT - 1 do
            local b = NewSimpleBullet(RING_STYLE_A, color, x, y, RING_SPEED,
                    base + i * 360 / RING_COUNT, false, 0, false,
                    nil, nil, nil, swirl_frame)
            b.spin = spin
        end
        -- flags 的 0x200 = PLAY_SPAWN_SOUND：整圈只响一声（BulletManager.cpp:717-723）。
        PlaySound("tan00", 0.1, x / 256, false)
    end

---一股双色环（Sub5）：每 RING_PERIOD 帧两圈（相隔 RING_PHASE 帧），两圈反向自转。
---基准角只在 Sub5 进入时读一次自机角（原作 @1200/@1220 读进 floatV0/floatV1，
---而循环跳回的是 @1240、跳过了那两条）⇒ 之后每轮都用同一个基准角。
---整圈是对称的，基准角只决定相位，所以这里固定取 0 就等价。
---★ 两圈的自转方向**固定**（原作 slot1 在发弹前写一次 +0.0261799、另一圈写 −0.0261799，
---弹在发弹那一刻抄走、之后每轮都是同一份）——旧版每轮把 spin 翻一次符号是错的。
---换算到我们这边（TH095 的正角 = 顺时针 ⇒ 取反）：色号 4 那圈用 −RING_SPIN、
---色号 5 那圈用 +RING_SPIN。
    local function swirl_stream(owner)
        task.New(owner, function()
            while true do
                fire_ring(owner, 0, RING_COLOR_A, -RING_SPIN)
                task.Wait(RING_PHASE)
                fire_ring(owner, 0, RING_COLOR_B, RING_SPIN)
                task.Wait(RING_PERIOD - RING_PHASE)
            end
        end)
    end

    ---小环（Sub7）：每 30 帧一圈 12 发整圈大玉。原作是 CIRCLE_AIMED（基准角 = 自机角），
    ---我们把整圈的相位跟着自机走（对称图案看不出朝向，但相位会跟着转，和原作一致）。
    local function fire_tick(owner)
        local base = Angle(owner.x, owner.y, player.x, player.y)
        for i = 0, TICK_COUNT - 1 do
            NewSimpleBullet(TICK_STYLE, TICK_COLOR, owner.x, owner.y, TICK_SPEED,
                    base + i * 360 / TICK_COUNT, false, 0, false)
        end
        PlaySound("tan00", 0.1, owner.x / 256, false)
    end

    ---一根扇激光（原作 ins_153，PhotoEffect.cpp 的 PhotoRotatingLaserView）。
    ---生命周期四段：前摇（细白线预警）→ 张开（w 0→LASER_W）→ 维持 → 收。
    ---★ 计时**挂在 boss 身上**（见 fire_fan）：laser:frame 只在真机里被调，
    ---tools/check_stage.lua 的 laser 桩件既不调 task.Do、`_TurnOn` 也是空函数，
    ---挂 laser 自己的话自检里既不会亮也不会收 —— 卡 73 踩过这个坑。
    class.fan_laser = Class(laser, {
        init = function(self, x, y, a)
            laser.init(self, LASER_INDEX, x, y, a,
                    LASER_SEG1, LASER_SEG2, LASER_SEG1, LASER_W, 0, 0)
            self.warn = FAN_WARN
        end,
        frame = function(self)
            laser.frame(self)
            if self.warn > 0 then
                ---前摇期间把宽度和亮度按死在 0：**不能有判定**（§7.8 第 4 条：
                ---预警不是墙）。laser:frame 里 alpha > 0.999 才判命中，所以 w/alpha 归零即可。
                self.warn = self.warn - 1
                self.w, self.alpha = 0, 0
            end
        end,
        render = function(self)
            if self.warn > 0 then
                ---细白线：全长的预警，粗细按像素给（§C4）—— white 是 16x16，
                ---Render 的 hscale 是「倍数」⇒ LASER_LEN/16 才是全长，0.2 = 3.2 px 粗。
                ---亮度恒正（§C4）：120 + 60*sin(...) ∈ [60,180]。
                local k = 1 - self.warn / FAN_WARN
                SetImageState("white", "mul+add", 120 + 60 * sin(self.timer * 8), 255, 235, 255)
                Render("white", self.x + cos(self.rot) * LASER_LEN * 0.5,
                        self.y + sin(self.rot) * LASER_LEN * 0.5,
                        self.rot, LASER_LEN / 16, 0.2)
            else
                laser.render(self)
            end
        end,
    })

    ---一轮激光扇（Sub6）：FAN_COUNT 根、角距 360/FAN_COUNT，锚在本体上跟着本体走
    ---（原作 followPhotoTarget 的等价物），扇面自己慢转 FAN_SPIN 度/帧。
    local function fire_fan(owner)
        local base = ran:Float(0, 360)          -- 原作 ins_153 的 angle = random(-π,π)
        local fan = {}
        for i = 0, FAN_COUNT - 1 do
            local l = New(class.fan_laser, owner.x, owner.y, base + i * 360 / FAN_COUNT)
            fan[#fan + 1] = l
            lasers[#lasers + 1] = l
        end
        ---一条协程干完这一轮（★ 不要再在 laser 名下开 task：见 fan_laser 的注释）。
        task.New(owner, function()
            ---前摇：预警线跟着本体+扇面转
            for _ = 1, FAN_WARN do
                for i = 1, #fan do
                    local l = fan[i]
                    if IsValid(l) then
                        l.rot = l.rot + FAN_SPIN
                        l.x, l.y = owner.x, owner.y
                    end
                end
                task.Wait()
            end
            PlaySound("lazer00", 0.25, owner.x / 200)
            for i = 1, #fan do
                laser._TurnOn(fan[i], FAN_GROW, false)
            end
            for _ = 1, FAN_GROW + FAN_HOLD do
                for i = 1, #fan do
                    local l = fan[i]
                    if IsValid(l) then
                        l.rot = l.rot + FAN_SPIN
                        l.x, l.y = owner.x, owner.y
                    end
                end
                task.Wait()
            end
            for i = 1, #fan do
                laser._TurnOff(fan[i], FAN_FADE)
            end
            for _ = 1, FAN_FADE do
                task.Wait()
            end
            for i = #fan, 1, -1 do
                if IsValid(fan[i]) then
                    object.RawDel(fan[i])
                end
            end
        end)
    end

    ---本体在框里慢慢晃（Sub4）：先朝自机方向 ±SWEEP_SPREAD 度挑一个角度走 LEG_TIME 帧
    ---（缓动 1 = 二次加速），再沿同一方向走 LEG_TIME 帧（缓动 4 = 二次减速）。
    ---框是凸的 ⇒ 在框内的两点之间直线插值不会跑出框，所以直接把目标点夹进框里就行
    ---（原作的 ins_75 夹取是引擎行为：TH095_ECL_ENEMY_FLAG_CLAMP_TO_MOVEMENT_BOUNDS）。
    local function sweep(owner)
        task.New(owner, function()
            while true do
                local a = Angle(owner.x, owner.y, player.x, player.y)
                        + ran:Float(-SWEEP_SPREAD, SWEEP_SPREAD)
                local step = SWEEP_SPEED * LEG_TIME
                local tx = max(BOX_L, min(BOX_R, owner.x + step * cos(a)))
                local ty = max(BOX_B, min(BOX_T, owner.y + step * sin(a)))
                task.MoveTo(tx, ty, LEG_TIME, VALUE_SET.ACCEL)
                tx = max(BOX_L, min(BOX_R, tx + step * cos(a)))
                ty = max(BOX_B, min(BOX_T, ty + step * sin(a)))
                task.MoveTo(tx, ty, LEG_TIME, EASE_OUT)
            end
        end)
    end

    ---一只死蝶：绕本体转一个小椭圆（母题：绕着月亮飞的蝶），半径各有不同（§7.7 第 2 条）。
    ---纯装饰（§7.4 的 C 类无害实体）：不出判定、不撞自机，只在 render 里画贴图。
    class.dead_moth = Class(object, {
        init = function(self, owner, phase, radius)
            self.owner, self.phase, self.t = owner, phase, 0
            self.radius = radius
            self.group = GROUP.GHOST
            self.layer = LAYER.ENEMY_BULLET_EF
            self.colli = false
            self.bound = false
            self.rot = 0
            self._a = 0
            self.x, self.y = owner.x, owner.y
            task.New(self, function()
                for _ = 1, 30 do
                    self._a = min(MOTH_ALPHA, self._a + MOTH_ALPHA / 30)
                    task.Wait()
                end
            end)
        end,
        frame = function(self)
            task.Do(self)                                  -- ★ 驱动 init 里的淡入协程
            if not IsValid(self.owner) then
                object.RawDel(self)
                return
            end
            self.t = self.t + 1
            local a = self.phase + self.t * (1.1 + self.radius / 200)
            local tx = self.owner.x + cos(a) * self.radius
            local ty = self.owner.y + sin(a) * self.radius * 0.55
            self.x = self.x + (tx - self.x) * 0.06
            self.y = self.y + (ty - self.y) * 0.06
            self.rot = self.rot + 3
        end,
        render = function(self)
            SetImageState("butterfly2", "mul+add", self._a, 226, 200, 245)
            Render("butterfly2", self.x, self.y, self.rot, 0.9)
        end,
    })

    ---──────────────────────── 符卡本体 ────────────────────────

    local card = boss.card.New(CARD_NAME, 1, 3, CARD_TIME, CARD_HP)

    function card:before()
        lasers = {}
        moths = {}
    end

    function card:init()
        photo_damage_on(self, PHOTO_LIMIT)  -- 拍照扣血：拍够 PHOTO_LIMIT 张 = 清空血条
        self.x, self.y = BOSS_X, BOSS_START_Y
        task.New(self, function()
            task.Wait(ENTRY_WAIT)
            task.MoveTo(0, BOSS_HOME_Y, ENTRY_TIME, EASE_OUT)
            ---到这里是原作第 130 帧：Sub2 的 t=130 同时 ins_52(3)（Sub3 本体脚本，含
            ---ins_83(4) 放 4 只死蝶）和 Sub4（扫动 + Sub5 的双色环）。
            PlaySound("tan00", 0.1, self.x / 256, false)
            for i = 1, MOTH_COUNT1 do
                moths[#moths + 1] = New(class.dead_moth, self, (i - 1) * 360 / MOTH_COUNT1,
                        46 + i * 6)
            end
            swirl_stream(self)
            sweep(self)
            ---Sub3 的 t=320（第 450 帧）：起 Sub6，第一轮 48 根激光扇。
            ---（Sub6 的 t=0 就摆好 ins_153、开始 120 帧前摇 ⇒ 「起扇」就是这一帧。）
            task.Wait(FAN_FIRST)
            fire_fan(self)
            ---Sub3 的 t=380（第 510 帧）：亮卡名 + 再放 8 只死蝶（ins_83(8)）。
            task.Wait(MOTH_MORE - FAN_FIRST)
            for i = 1, MOTH_COUNT2 do
                moths[#moths + 1] = New(class.dead_moth, self, (i - 1) * 360 / MOTH_COUNT2,
                        64 + i * 5)
            end
            ---下一轮激光扇在 Sub3 的 t=910（= 这里再等 FAN_INTERVAL 帧），之后每 530 帧一轮。
            task.Wait(FAN_INTERVAL)
            while true do
                fire_fan(self)
                task.Wait(FAN_INTERVAL)
            end
        end)
        ---Sub7 的小环：原作 t=470 起到卡结束。
        task.New(self, function()
            task.Wait(TICK_FIRST)
            while true do
                fire_tick(self)
                task.Wait(TICK_PERIOD)
            end
        end)
    end

    ---本体的逐帧逻辑：**原作没有**（移动、发弹都在 ECL 上下文里）。frame 留空是刻意的。
    function card:frame()
    end

    function card:del()
        photo_damage_off(self)
        for i = #lasers, 1, -1 do
            if IsValid(lasers[i]) then
                object.RawDel(lasers[i])
            end
        end
        lasers = {}
        for i = #moths, 1, -1 do
            if IsValid(moths[i]) then
                task.Clear(moths[i])
                object.RawDel(moths[i])
            end
        end
        moths = {}
    end

    boss.card.add({ { card, "1a" } }, LEVEL, CARD_NAME, CARD_ID)
end--「死蝶浮月」

do  -- 72 密符「御大師様の秘鍵」（ecl16_b，妖梦，组 2a 第 1 张）
    ---「御大師様の秘鍵」= 空海（御大師）传下来的密教法器。原作的骨架（/tmp/B_ecl16_b.txt）：
    ---  · Sub2/Sub6：本体在一条**很扁的横带**里（ins_75(-160,128,160,144) ⇒ 我们的 y∈[80,96]）
    ---    每 60 帧做一次 ins_67(30,4,4) 的边界感知走位（30 帧、4 px/帧 ⇒ 一次挪 120 px），
    ---  · Sub3：Sub2 在 t=130 用 ins_52(3) **同步调**进来（子上下文 time 从 0 起）。
    ---    t=60 起三件事各自开工：
    ---      Sub4 = 每 45 帧一发「自机狙小弹」，**photoIndex ≥ 3 才开火**
    ---      （ins_44(photoIndex,3,0,72) = 小于就跳过后面的发弹，EclRunLow.inl:409 的比较分支），
    ---      Sub5 = 每 60 帧往**绝对 (±128, -32)** 各放一把「钥匙」（t=0 与 t=30 各一把）
    ---      （ins_26 先把偏移算成 (-128−pos.x)/(-32−pos.y)，ins_84 再加父坐标，
    ---       所以落点是绝对的场地外左上/右上角），
    ---      Sub6 = 每 45 帧一次边界感知挪位（ins_52(6) 是同步调用：Sub6 跑 45 帧、
    ---      调用者的 time 冻着；Sub6 的 ins_53 返回后 ins_4 又把 time 拨回 60、跳回
    ---      ins_52 ⇒ 立刻再来一次）。
    ---  · Sub7 = 钥匙的炮口（Sub8 在 t=0 用 ins_117(1,7) 起它）：t=10 抽 n = 12 + rand(0..15)，
    ---    再**每 2 帧**甩一发**定角**三连（ins_87 九个操作数全是字面量 ⇒ 上/左/右三个死方向，
    ---    floatV0 那条 +5.625° 是没人读的死指令），一共 n 发；n ≤ 15 时 30 帧一轮、
    ---    n ≥ 16 时越过外层 t=40 就此停摆（理由见 burst_cycle）。
---我们这边的一处差异 / 两条形状上的照抄：
---  ① 「钥匙」做成**不出判定的法器装饰**（§7.4 的 C 类）—— 原作的子敌机本体能撞死人，
---     跟卡 71 的蛾 / 卡 73 的蝶子机一样，威胁全交给弹。
---  ② 三连的**节拍与发数照原作**：每 2 帧一发、n = 12..27 发（不再截断到 15，
---     见 burst_cycle）；方向**不旋转**（旧版按那条死指令转了 5.625°/轮，是从没发生过的形状）。
---     **不做距离闸** —— 原作这张卡没有 ins_82，贴着也照发（见常量段）。
---  ③ 钥匙飞出场地就淡出收掉（原作挂到 t=2000 才退役）。
    ---──────────────────────── 常量（改手感只动这一段） ────────────────────────
    ---入场：Sub2 t=0 的 ins_63(-128,-64)、t=100 的 ins_64(30,4,0,160)。
    local BOSS_X, BOSS_START_Y = -128, field_y(-64)     -- 288（场地外）
    local BOSS_HOME_Y = field_y(160)                    -- 64
    local ENTRY_WAIT, ENTRY_TIME = 100, 30
    local EASE_OUT = VALUE_SET.DECEL

    ---横带与「挪一格」（Sub6 的 ins_67(30,4,4) + Sub3 每 60 帧的节奏）：
    ---ins_75 划的是 x∈[-160,160]、y∈[128,144]（TH095）⇒ 我们的 y∈[field_y(144), field_y(128)]。
    local BAND_L, BAND_R = -160, 160
    local BAND_B, BAND_T = field_y(144), field_y(128)   -- 80 / 96
    local SCOOT_PERIOD, SCOOT_TIME = 60, 30
    local SCOOT_SPEED = 4

    ---钥匙（Sub5 的 ins_84 + Sub8）：
    ---  落点 = 绝对 (±KEY_SPAWN_X, KEY_SPAWN_Y)、两次相隔 KEY_GAP 帧（t=0 与 t=30）；
    ---  朝下飞（TH095 的 π/2 是 +y ⇒ 我们的 -90°）、速度 2（ins_65 的第 2 个操作数）；
    ---  每 KEY_BURST_PERIOD 帧甩一次定角三连（上/左/右，见下面「不旋转」那一段）。
    local KEY_SPAWN_X = 128
    local KEY_SPAWN_Y = field_y(-32)                    -- 256（场地上沿之外）
    local KEY_GAP = 30
    local KEY_SPEED = 2
    local KEY_DOWN = -90
    ---淡入 10 帧：原作的 key 在 Sub8 的 t=0 定完速度就开工，Sub7 的 t=10 甩第一轮三连
    ---⇒ 淡入只占这 10 帧（§7.8：不许突然出现 / 突然消失，所以留着这一段）。
    local KEY_FADE_IN, KEY_FADE_OUT = 10, 25
    local KEY_ALPHA = 170                   -- §7.6：装饰层 alpha 压在 120~180
    ---Sub7 的 ins_4(10,-152)：t=40 跳回 t=10 ⇒ **一轮 30 帧**（跳转同帧派发，见卡 71）。
    local KEY_BURST_PERIOD = 30
    local KEY_BURST_GAP = 2                 -- ins_5(10,-64,n) 每轮占 2 帧 ⇒ 2 帧一发三连
    local KEY_BURST_HOLD = KEY_BURST_PERIOD / KEY_BURST_GAP  -- 30 帧里塞得下的三连发数 = 15
    local KEY_BURST_BASE = 12               -- ins_6(extraIntV0, 12)
    local KEY_BURST_RAND = 16               -- ins_24(extraIntV1, randU31, 16) ⇒ 0..15
    ---★ 不要在这里加「贴脸停火」：TH095 的 minimumPlayerDistanceSquared 出生默认是 **0**
    ---（EnemyManagerUpdate.cpp:457 的 `nSquared = 0`），只有卡里调 ins_82 才有距离闸
    ---（EclRunHigh.inl:951-958 把它平方写进去；EnemyShotDispatch.cpp:131-140 才是那个
    ---early return）—— 这张卡**没有** ins_82 ⇒ 原作就是贴着也照甩。加了距离闸等于少发弹。
    ---★ 三连**不旋转**：dump 里 Sub7 的 ins_87 九个操作数 pm=0000（全是字面量）
    ---  ⇒ 基准角写死 −π/2，扇面每轮都是「上/左/右」三个定方向；同帧那条
    ---  ins_15(floatV0, 0.0981748)（floatV0 += 5.625°）**没有任何指令读它**
    ---  （整份 ecl16_b 里 10008 只在这一条被写）⇒ 原作没有「旋转三连」这回事，
    ---  旧版按 5.625°/轮 转是照着那条死指令猜的（画蛇添足）。
    ---  换算：TH095 的 −π/2（朝上）在「逆时针为正」的我们这边是 +90°；
    ---  angleStep = π/2 的两个旁瓣落在 0°（右）与 180°（左）。
    local KEY_STEP = 90                     -- ins_87 的 angleStep = π/2
    local KEY_AIM0 = 90                     -- ins_87 的 angle = -π/2（TH095 朝上）⇒ 我们的 +90°
    local KEY_BULLET_SPEED = 2.0
    local KEY_STYLE = butterfly
    ---颜色：butterfly 非 colorful ⇒ 贴图号 = ceil(色号/2)；色号 8 → butterfly4 = (193,216,235) 冰蓝。
    local KEY_COLOR = COLOR.CYAN

    ---自机狙小弹（Sub4）：ins_86(12, 1, 1, 1, 1.5, 1.5, 0, π/2, 514) = FAN_AIMED、
    ---count1 = 1 ⇒ 单发、正对自机；type12（半径 5）、速 1.5；每 45 帧一发。
    ---★ 原作只在 camera.photoIndex ≥ 3 之后才打（ins_44）—— 这是拍照关「拍够了才开始
    ---给你上强度」的设计，我们照抄：photo_index(PHOTO_LIMIT) < 3 时这一层不存在。
    local AIM_PERIOD = 45
    local AIM_FROM_PHOTO = 3
    local AIM_SPEED = 1.5
    local AIM_STYLE = water_drop
    local AIM_COLOR = COLOR.CYAN            -- water_drop 是 colorful ⇒ 色号 8 = 亮青 (70,204,207)

    local PHOTO_LIMIT = 6                   -- Sub2 的 ins_141(6)：相机快门上限（photo_index 的截断值）

    local CARD_NAME = "密符「御大師様の秘鍵」"
    ---原作卡计时 ins_114(6608) ≈ 110 秒（拍照关留给玩家取景用）；沿用本仓库的 55 秒。
    local CARD_TIME = 55
    ---原作 Timeline0 给的生命是 150；这里按本仓库的量级抬到 900。
    local CARD_HP = 900
    ---符卡历史槽位：410..412 已被卡 71/73/77 占掉、416 被卡 75 占掉，这张取 413。
    local CARD_ID = 413

    ---──────────────────────── 演出 / 弹幕 ────────────────────────

    ---本卡放出的钥匙（卡结束时统一收掉，§7.9 第 9 条）。
    local keys = {}

---一次三连（原作 Sub7 循环体 @1364 的 ins_87）：3 发定角（KEY_AIM0、±90°；
---FAN 的奇数 count1 分支，和卡 74 的 fan_angle 同一条公式），不旋转（理由见常量段）。
    local function fire_burst(key)
        for _, off in ipairs({ 0, KEY_STEP, -KEY_STEP }) do
            NewSimpleBullet(KEY_STYLE, KEY_COLOR, key.x, key.y, KEY_BULLET_SPEED,
                    KEY_AIM0 + off, false, 0, false)
        end
        -- flags 的 0x200 = PLAY_SPAWN_SOUND：一次只响一声（BulletManager.cpp:717-723）。
        PlaySound("tan00", 0.1, key.x / 256, false)
    end

---Sub7 的一轮：t=10 先抽 n = 12 + rand(0..15)（@1300 ins_6 → @1320 ins_24(randU31,16)
---→ @1344 ins_10 累加），然后**每 2 帧**一发三连、一共 n 发（@1428 的 ins_5(10,-64,n)
---把 time 拨回 10 再跳回 @1364 的 ins_87 ⇒ 一圈占 t=10→t=12 这 2 帧，计数器减到 0 才继续）。
---★ 这一轮占用 2n 帧的 ECL 时间，而外层的 @1452 ins_4 只在 **t=40** 才把 time 拨回 10：
---  · n ≤ 15（2n ≤ 30）⇒ 循环结束时 t ≤ 40，外循环照常重开、重抽 n；
---  · n ≥ 16（2n > 40）⇒ 循环结束时 ctx->time 已经越过 40，那条 ins_4 再也不会匹配
---    （EclRun.cpp:302 只在 `time == instruction->time` 时派发）⇒ **Sub7 就此停摆**，
---    这把钥匙发完这 n 轮三连之后不再发弹（这是原作本身的行为，不是我们加的闸；
---    旧版把 n 截断到 15 再重开，反而比原作多发了弹）。
---返回 true = 这一轮按时收工、等满 30 帧重抽；false = 已经停摆。
    local function burst_cycle(key)
        local n = KEY_BURST_BASE + ran:Int(0, KEY_BURST_RAND - 1)   -- 12..27
        for k = 1, n do
            fire_burst(key)
            if k < n then
                task.Wait(KEY_BURST_GAP)
            end
        end
        if n > KEY_BURST_HOLD then
            return false
        end
        task.Wait(KEY_BURST_PERIOD - KEY_BURST_GAP * (n - 1))
        return true
    end

    ---一把「秘鍵」（原作 Sub8）：场地外飘进来 → 一边往下走一边甩三连 → 出场地淡出。
    ---纯装饰实体（§7.4 的 C 类无害实体）：不出判定、不撞自机，只在 render 里画贴图。
    ---★ 一条协程干完整个生命周期（不要在对象名下再开 `while true`）：
    ---  tools/check_stage.lua 的协程表不认「对象已死」，被 RawDel 之后还会接着被 resume
    ---  —— 卡 73 的蝶子机踩过，自检会报「卡结束后还在发弹」。
    class.key = Class(object, {
        init = function(self, x, y)
            self.group = GROUP.GHOST
            self.layer = LAYER.ENEMY_BULLET_EF
            self.colli = false
            self.bound = false
            self.x, self.y = x, y
            self.rot, self._a = 0, 0
            task.New(self, function()
                for _ = 1, KEY_FADE_IN do
                    self._a = min(KEY_ALPHA, self._a + KEY_ALPHA / KEY_FADE_IN)
                    task.Wait()
                end
                object.SetV(self, KEY_SPEED, KEY_DOWN, true)
                local w = lstg.world
                ---firing 变 false = Sub7 停摆（n ≥ 16）⇒ 之后只往下飘，不再发弹。
                local firing = true
                while self.y > w.b - 64 do
                    if firing then
                        firing = burst_cycle(self)
                    else
                        task.Wait()
                    end
                end
                ---冲出场地：淡出再收（§7.8 第 4 条：不许突然消失）。
                for _ = 1, KEY_FADE_OUT do
                    self._a = max(0, self._a - KEY_ALPHA / KEY_FADE_OUT)
                    task.Wait()
                end
                object.RawDel(self)
            end)
        end,
        frame = function(self)
            task.Do(self)
            self.rot = self.rot - 2.5        -- 和卡 73 的蝶子机反着转（§7.7 第 2 条）
        end,
        render = function(self)
            SetImageState("servant", "mul+add", self._a, 175, 240, 240)
            Render("servant", self.x, self.y, self.rot, 1.05)
        end,
    })

    ---★ Sub3 的时间基准：它是 Sub2 在 t=130 用 ins_52(3) **同步调用**进来的、而
    ---CallEclSub 把子上下文的 time 清零（EnemyManagerUpdate.cpp:172-186）⇒
    ---**Sub3 的 t=N = 入场结束（第 130 帧）之后再过 N 帧**。Sub3 的 t=60 起
    ---Sub4（自机狙）/ Sub5（钥匙）/ Sub6（挪位）三件事，所以三条流都先等 SUB3_START。
    local SUB3_START = 60

    ---本体横着挪一格（Sub6）：朝自机方向 ±60° 挑一个角度走 30 帧、一共 120 px。
    ---带子是凸的 ⇒ 把目标点夹进带里就等价于引擎的 CLAMP_TO_MOVEMENT_BOUNDS。
    local function scoot(owner)
        task.New(owner, function()
            task.Wait(SUB3_START)
            while true do
                local a = Angle(owner.x, owner.y, player.x, player.y)
                        + ran:Float(-60, 60)
                local step = SCOOT_SPEED * SCOOT_TIME
                local tx = max(BAND_L, min(BAND_R, owner.x + step * cos(a)))
                local ty = max(BAND_B, min(BAND_T, owner.y + step * sin(a)))
                task.MoveTo(tx, ty, SCOOT_TIME, VALUE_SET.NORMAL)
                task.Wait(SCOOT_PERIOD - SCOOT_TIME)
            end
        end)
    end

    ---两把钥匙（Sub5）：相隔 KEY_GAP 帧、一左一右落在场地外，然后各自往下飘。
    local function key_stream(owner)
        task.New(owner, function()
            task.Wait(SUB3_START)
            while true do
                keys[#keys + 1] = New(class.key, -KEY_SPAWN_X, KEY_SPAWN_Y)
                task.Wait(KEY_GAP)
                keys[#keys + 1] = New(class.key, KEY_SPAWN_X, KEY_SPAWN_Y)
                task.Wait(SCOOT_PERIOD - KEY_GAP)
            end
        end)
    end

    ---自机狙小弹（Sub4）：photoIndex ≥ AIM_FROM_PHOTO 之后，每 45 帧一发正对自机。
    ---★ Sub4 的 t=0 就是「先判 ins_44 的闸、再发那发」⇒ 第一发机会在它被起的那一帧
    ---（不是等 45 帧之后）；跳回的是 @892（t=0）所以每 45 帧一次。
    local function aim_stream(owner)
        task.New(owner, function()
            task.Wait(SUB3_START)
            while true do
                if photo_index(PHOTO_LIMIT) >= AIM_FROM_PHOTO then
                    local a = Angle(owner.x, owner.y, player.x, player.y)
                    NewSimpleBullet(AIM_STYLE, AIM_COLOR, owner.x, owner.y, AIM_SPEED, a,
                            false, 0, false)
                end
                task.Wait(AIM_PERIOD)
            end
        end)
    end

    ---──────────────────────── 符卡本体 ────────────────────────

    local card = boss.card.New(CARD_NAME, 1, 3, CARD_TIME, CARD_HP)

    function card:before()
        keys = {}
    end

    function card:init()
        photo_damage_on(self, PHOTO_LIMIT)  -- 拍照扣血：拍够 PHOTO_LIMIT 张 = 清空血条
        self.x, self.y = BOSS_X, BOSS_START_Y
        task.New(self, function()
            task.Wait(ENTRY_WAIT)
            task.MoveTo(0, BOSS_HOME_Y, ENTRY_TIME, EASE_OUT)
            ---到这里是原作第 130 帧：Sub2 的 t=130 是 ins_104（亮卡名）+ ins_52(3)
            ---（Sub3 = 起点两个子上下文、每 60 帧一次挪位）。
            PlaySound("tan00", 0.1, self.x / 256, false)
            aim_stream(self)
            key_stream(self)
            scoot(self)
        end)
    end

    ---本体的逐帧逻辑：**原作没有**（移动、发弹都在 ECL 上下文里）。frame 留空是刻意的。
    function card:frame()
    end

    function card:del()
        photo_damage_off(self)
        for i = #keys, 1, -1 do
            if IsValid(keys[i]) then
                ---★ 先 task.Clear 再 RawDel：协程挂在钥匙名下，自检的协程表不认「对象已死」
                ---（见 class.key 的注释），不清的话它还会接着发弹。
                task.Clear(keys[i])
                object.RawDel(keys[i])
            end
        end
        keys = {}
    end

    boss.card.add({ { card, "2a" } }, LEVEL, CARD_NAME, CARD_ID)
end--密符「御大師様の秘鍵」

do  -- 74 行符「八千万枚護摩」（ecl16_c，妖梦，组 2a 第 2 张）
    ---「護摩」是密教用火烧护摩木的修行，八千万枚 = 烧掉的木条数。原作的骨架
    ---（/tmp/B_ecl16_c.txt）：
    ---  · Sub5（主体脚本）：t=0 一记 **128 根的整扇**（ins_87，count1=128 ⇒ 每根差 1.875°、
    ---    以自机方向为中心铺开 ±119°），t=15 的 ins_5(0,-44,4) 把它**每 15 帧再放一次**
    ---    （一共 4 次：t=0/15/30/45；ins_5 把 time 拨回 0 ⇒ 一圈 15 帧），
    ---    t=85 调 Sub4（ins_67(20,4,4) 边界感知走位 20 帧 / 4 px/帧），然后 ins_4(0,-140)
    ---    跳回 t=0 ⇒ **一轮 165 帧**（4 次整扇占 45 帧 + 从最后一次回到 t=85 的 85 帧
    ---    + Sub4 的 35 帧）。
    ---  · Sub6：每 3 帧一小圈（ins_89(18, 1, intV0, 1, 2.0, ...)），
    ---    intV0 = photoIndex/3 + 1（ins_23 整除、ins_30 自增）⇒ 拍得越多圈越大（1~3 发）。
    ---    ins_4(100,-84) 跳回 @1172（t=100）⇒ 周期 3 帧（跳到 t=100 后同帧接着跑）。
    ---    角度是 rand(-π,π) ⇒ 每圈换个相位（§7.7 第 1 条）。
---我们这边的一处差异：
---  · type 6（半径 2）→ butterfly（半径 4）：本关只有 butterfly / water_drop 两种贴图。
---    **发数/速度都不打折**：ins_5(0,-44,4) 的「4 次整扇」照抄 ⇒ 4×128 颗一颗不少；
---    4 次之间隔 15 帧、共用同一个基准角（理由见 fire_fan / fan_stream 的注释）。
    ---──────────────────────── 常量（改手感只动这一段） ────────────────────────
    ---入场：Sub2 t=0 的 ins_63(-128,-64)、t=100 的 ins_64(30,4,0,224)。
    local BOSS_X, BOSS_START_Y = -128, field_y(-64)     -- 288（场地外）
    local BOSS_HOME_Y = field_y(224)                    -- 0（场地正中）
    local ENTRY_WAIT, ENTRY_TIME = 100, 30
    local EASE_OUT = VALUE_SET.DECEL

    ---Sub4 的走位框：ins_75(-128,192,128,256) ⇒ x∈[-128,128]、y∈[192,256]（TH095）
    ---⇒ 我们的 y∈[-32, 32]。ins_67(20,4,4)：第 1 个操作数 = 20 帧、第 2 个 = 缓动 4
    ---（4 = 1−(1−t)²，EclRun.cpp:374-378 ⇒ 我们的 VALUE_SET.DECEL）、第 3 个 = 4 px/帧。
    local BAND_L, BAND_R = -128, 128
    local BAND_B, BAND_T = field_y(256), field_y(192)   -- -32 / 32
    local SCOOT_TIME, SCOOT_SPEED = 20, 4

    ---整扇（Sub5）：ins_87(6, 4, 128, 1, 1.4, 1.5, floatV0, 0.0327249, 514)。
    ---count2 = 1 ⇒ speed2 = 1.5 不参与（BulletManager.cpp 的速度公式），速 1.4；
    ---angleStep = 0.0327249 rad = 1.875°；count1 = 128 是**偶数** ⇒ 走偶数分支
    ---（k = index1/2 + 0.5，奇数 index1 取负）⇒ ±0.5、±1.5、…、±63.5 格
    ---= 以自机方向为中心、一口气铺开 ±119.06°。
    ---整扇的节拍：**一共 4 次**（t=0 直落的那次 + ins_5(0,-44,4) 循环出来的 3 次）。
    ---★ 不是「同帧连放 4 次」：ins_5 把 time 拨回 0、跳回 @1008 的 ins_87，而循环体里
    ---  最后一条 ins_5 自己的 time 是 15 ⇒ 每圈要过 15 帧才再派发到它（EclRunLow.inl:419-422
    ---  + 跳转同帧派发）⇒ 4 次整扇落在 t=0/15/30/45。
    ---之后的 85 帧：t=60 那次派发把计数减到 0（退出循环）→ t=85 的 ins_52(4) 是**同步调用**
    ---Sub4（CallSubOnEnemy 把调用者的上下文压栈，EclRunLow.inl:419-420；Sub4 的 ins_53
    ---才返回）—— 调用者的 time 在子程序跑的时候**冻着**，Sub4 自己占 35 帧
    ---（t=15 起步走 20 帧 + 收尾）⇒ 一轮 = 45 + 85 + 35 = 165 帧。
    local FAN_WAIT = 15                     -- 两次整扇之间隔 15 帧（ins_5 的一圈）
    local FAN_REPEAT = 4                    -- ins_5(0,-44,4)：整个扇组一共 4 次
    local FAN_CALL = 85                     -- 最后一次整扇之后 85 帧到 t=85（每次循环都把 time 拨回 0）
    local SCOOT_DELAY = 15                  -- Sub4 的 t=15 才起步
    local SCOOT_TIME = 20                   -- Sub4 的 ins_67(20,4,4) 走 20 帧
    local FAN_COUNT = 128
    local FAN_STEP = 1.875
    local FAN_SPEED = 1.4
    local FAN_STYLE = butterfly
    ---butterfly 非 colorful ⇒ 贴图号 = ceil(色号/2)；色号 8 → butterfly4 = (193,216,235) 冰蓝。
    local FAN_COLOR = COLOR.CYAN

    ---小圈（Sub6）：ins_89(18, 1, intV0, 1, 2.0, 1.5, rand(-π,π), 0.1848, 514)。
    ---type18（半径 3）、color 1、每 3 帧一圈、圈数 = photoIndex/3 + 1（1~3）。
    ---周期是 ins_4(100,-84) 跳回 @1172（t=100）⇒ 100→103 共 3 帧（跳转把 time 拨回 100）。
    local RING_PERIOD = 3
    ---★ Sub6 的第一条指令在 t=100（不是 t=0）：Sub3 在 t=0 起 Sub6，而 CallEclSub 把
    ---子上下文 time 清零（EnemyManagerUpdate.cpp:172-186）⇒ 「Sub6 的 t=100」= 入场
    ---结束（第 130 帧）之后再过 100 帧 = 第 230 帧。旧版入场一结束就开圈，早了 100 帧。
    local RING_DELAY = 100
    local RING_BASE_COUNT = 1               -- 1 + photoIndex/3
    local RING_SPEED = 2.0
    local RING_STYLE = water_drop
    local RING_COLOR = COLOR.CYAN           -- water_drop 是 colorful ⇒ 色号 8 = 亮青 (70,204,207)

    local PHOTO_LIMIT = 7                   -- Sub2 的 ins_141(7)：相机快门上限（photo_index 的截断值）

    local CARD_NAME = "行符「八千万枚護摩」"
    ---原作卡计时 ins_114(8408) ≈ 140 秒；沿用本仓库的 50 秒。
    local CARD_TIME = 50
    ---原作 Timeline0 给的生命是 150；这里按本仓库的量级抬到 900。
    local CARD_HP = 900
    ---符卡历史槽位：410..413 已被占、416 被卡 75 占掉，这张取 414。
    local CARD_ID = 414

    ---──────────────────────── 演出 / 弹幕 ────────────────────────

    ---FAN 的角度公式（aimMode = 1；BulletManager.hpp 的 PhotoBulletAimModeValue，
    ---实现在 BulletManager.cpp 的 FAN 分支）：
    ---  奇数 count1 ⇒ k = (index1+1)/2 的整数除；偶数 ⇒ k = index1/2 + 0.5；
    ---  index1 为奇数时 k 取负 ⇒ 偶数 count1 的扇面**没有正中间那一根**、两两对称成对。
    local function fan_angle(base, index1, count1, step)
        local k
        if count1 % 2 == 1 then
            k = int((index1 + 1) / 2)
        else
            k = index1 / 2 + 0.5
        end
        if index1 % 2 == 1 then
            k = -k
        end
        return base + k * step
    end

    ---一记整扇（Sub5）：128 根、以自机方向为中心铺开 ±119°（奇数/偶数公式见 fan_angle）。
    ---base 由调用方传进来：原作只在**外圈**开头读一次自机方向（@988 的 ins_7 在 ins_5 的
    ---循环体外，ins_5 跳回的是 @1008 的 ins_87）⇒ 同一轮的 4 次整扇共用同一个基准角。
    local function fire_fan(owner, base)
        local x, y = owner.x, owner.y
        for i = 0, FAN_COUNT - 1 do
            NewSimpleBullet(FAN_STYLE, FAN_COLOR, x, y, FAN_SPEED,
                    fan_angle(base, i, FAN_COUNT, FAN_STEP), false, 0, false)
        end
        -- flags 的 0x200 = PLAY_SPAWN_SOUND：整扇只响一声（BulletManager.cpp:717-723）。
        PlaySound("tan00", 0.1, x / 256, false)
    end

    ---一小圈（Sub6）：圈数 = 1 + photoIndex/3，相位每圈重抽（原作 angle = rand(-π,π)）。
    local function fire_ring(owner)
        local count = RING_BASE_COUNT + int(photo_index(PHOTO_LIMIT) / 3)
        local base = ran:Float(0, 360)
        for i = 0, count - 1 do
            NewSimpleBullet(RING_STYLE, RING_COLOR, owner.x, owner.y, RING_SPEED,
                    base + i * 360 / count, false, 0, false)
        end
    end

    ---主体脚本（Sub5）：t=0/15/30/45 各放一扇（共 4 次）→ t=85 调 Sub4（同步 35 帧）
    ---→ 回头（一轮 165 帧）。
    ---★ 4 次循环**不是同帧连放**：ins_5 把 time 拨回 0 再跳回 @1008 的 ins_87，
    ---  而跳转后 time（0）≠ 循环体那条 ins_5 自己的 time（15）⇒ 一圈占 15 帧
    ---  （EclRunLow.inl:419-422 + 跳转同帧派发）。基准角由 @988 的 ins_7 写、@988 在循环体外
    ---  ⇒ 同一轮 4 次整扇用**同一个**基准角，下一轮开头才重读自机方向。
    local function fan_stream(owner)
        task.New(owner, function()
            while true do
                ---@988 ins_7：本轮的自机方向，只在**这里**读一次（4 次整扇共用）。
                local base = Angle(owner.x, owner.y, player.x, player.y)
                ---t=0/15/30/45：4 次整扇，每次之间隔 15 帧（ins_5 的一圈）。
                for k = 1, FAN_REPEAT do
                    fire_fan(owner, base)
                    if k < FAN_REPEAT then
                        task.Wait(FAN_WAIT)
                    end
                end
                task.Wait(FAN_CALL)             -- 到 t=85（调 Sub4 的那一帧）
                task.Wait(SCOOT_DELAY)          -- Sub4 自己的 t=15 才起步
                ---Sub4：朝自机方向 ±60° 挑一个角度、4 px/帧 走 20 帧（= 80 px），夹进框里。
                local a = Angle(owner.x, owner.y, player.x, player.y) + ran:Float(-60, 60)
                local step = SCOOT_SPEED * SCOOT_TIME
                task.MoveTo(max(BAND_L, min(BAND_R, owner.x + step * cos(a))),
                        max(BAND_B, min(BAND_T, owner.y + step * sin(a))),
                        SCOOT_TIME, VALUE_SET.DECEL)
            end
        end)
    end

    ---小圈（Sub6）：t=100 起每 3 帧一圈。
    local function ring_stream(owner)
        task.New(owner, function()
            task.Wait(RING_DELAY)
            while true do
                fire_ring(owner)
                task.Wait(RING_PERIOD)
            end
        end)
    end

    ---──────────────────────── 符卡本体 ────────────────────────

    local card = boss.card.New(CARD_NAME, 1, 3, CARD_TIME, CARD_HP)

    function card:before()
    end

    function card:init()
        photo_damage_on(self, PHOTO_LIMIT)  -- 拍照扣血：拍够 PHOTO_LIMIT 张 = 清空血条
        self.x, self.y = BOSS_X, BOSS_START_Y
        task.New(self, function()
            task.Wait(ENTRY_WAIT)
            task.MoveTo(0, BOSS_HOME_Y, ENTRY_TIME, EASE_OUT)
            ---到这里是原作第 130 帧：Sub2 的 t=130 是 ins_104（亮卡名）+ ins_52(3)。
            PlaySound("tan00", 0.1, self.x / 256, false)
            fan_stream(self)
            ring_stream(self)
        end)
    end

    ---本体的逐帧逻辑：**原作没有**（移动、发弹都在 ECL 上下文里）。frame 留空是刻意的。
    function card:frame()
    end

    function card:del()
        photo_damage_off(self)
    end

    boss.card.add({ { card, "2a" } }, LEVEL, CARD_NAME, CARD_ID)
end--行符「八千万枚護摩」

do  -- 76 超人「飛翔役小角」（ecl16_d，妖梦，组 2a 第 3 张）
    ---「飛翔役小角」= 会飞的役小角（修验道的祖师，传说能在空中飞行）。原作的骨架
    ---（/tmp/B_ecl16_d.txt）不是「站在原地放弹」，而是**本体自己在飞**：
    ---  · Sub3 的 t=0：ins_65(playerAngle, 0.5) + ins_71(0.1) ⇒ 朝自机方向起步、
    ---    速度 0.5、**加速度 0.1**（引擎每帧 speed += acceleration 地飞，越飞越快）；
    ---    然后每帧只跑一段「守卫链」（@940 → @1236 → @1512 → @1788 无条件跳到底），
    ---    也就是**在场地内什么都不做**。
    ---  · 链上的三个分支块（@988 / @1264 / @1540）内容一模一样：把本体挪到
    ---    **(随机 x, -48)**（TH095 坐标 ⇒ 我们的 y = 272，场地上沿之外）、
    ---    换成「俯冲」：ins_65(playerAngle, photoIndex*2)、ins_71(2/60 + 0.1)
    ---    （ins_28 是浮点**除**，EclRunLow.inl:320；2/60 + 0.1 = 0.1333），
    ---    并且 ins_117(0,4) 重启蝶云上下文。
    ---    三个块分别由「出下沿 / 出右沿 / 出左沿」选中 ⇒ **飞出场地就回顶上重来**。
    ---  · Sub4（蝶云）：每帧 1 发、4 发一组（t=0..3，t=4 跳回 @1960），
    ---    出膛点 = 本体 + 半径 24 px 内随机（ins_27 乘随机数、ins_38 化成向量、ins_100 设偏移），
    ---    方向随机；速度 0.02（几乎不动）→ 悬停 60 帧 → 沿自身方向以 1/60 px/帧² 加速 60 帧
    ---    （ins_101 slot0 的 0x8000 = WAIT、slot1 的 0x10 = ACCELERATE_VECTOR，
    ---     见 PhotoBulletSpawnDescriptor.hpp:82-107 的位表）⇒ 最后 ~1.02 px/帧。
    ---    所以这是一片**先悬在半空、再慢慢飘走**的蝶云（母题：役小角身边的蝶）。
---我们这边的一处差异 / 两条只影响自检的说明：
---  ① 俯冲速度照原作：photoIndex × 2（photoIndex 上限 8 ⇒ 最多 16 px/帧），**不封顶**。
---  ② 蝶云只在入场后开一次（原作每次俯冲都重启上下文）。重启只是重置相位
    ---     （ins_117 用的是**固定槽位**、会把上一个上下文 free 掉，EclRunTargetHigh.inl:206，
    ---     不会叠加），图案完全一样，省掉一次协程抖动。
    ---  ③ **自检在这张上的读数偏低，不是卡里缺弹幕。** 桩件只对 `objects` 表里的对象
    ---     积分速度（tools/check_stage.lua 的 step_objects），而本体是它另外造的
    ---     boss_obj、不在那张表里 ⇒ **飞行在自检里是静止的**，蝶云全堆在出生点、
    ---     自机站在别处，所以 `60px 内平均` 只有 0.5。把同一段飞行在桩件里手动积分
    ---     一次（= 引擎真正干的事，LuaSTG-Sub/LuaSTG/LuaSTG/GameObject/GameObject.cpp:330
    ---     的 `x += vx`），同样 1800 帧的读数就是 4.0~4.7。
    ---     这张卡的压迫感本来也主要来自**本体撞人**（自检量不了碰撞），蝶云只是挂在
    ---     身后的软墙；按 §7.2 真正权威的那一栏 `峰值同屏 弹` = 205（阈值 150）⇒ 不空。
    ---──────────────────────── 常量（改手感只动这一段） ────────────────────────
    ---入场：Sub2 t=0 的 ins_63(-128,-64)、t=100 的 ins_64(30,4,16,128)。
    local BOSS_X, BOSS_START_Y = -128, field_y(-64)     -- 288（场地外）
    local BOSS_HOME_X, BOSS_HOME_Y = 16, field_y(128)   -- 16 / 96
    local ENTRY_WAIT, ENTRY_TIME = 100, 30
    local EASE_OUT = VALUE_SET.DECEL

    ---飞行 / 俯冲（Sub3，公式见卡头注释）。
    local DIVE_SPEED0 = 0.5                 -- ins_65 的第 2 个操作数
    local DIVE_ACCEL0 = 0.1                 -- ins_71 的第 1 个操作数
    local DIVE_ACCEL = 2 / 60 + 0.1         -- 俯冲档的 ins_71(ins_28(2,60) + 0.1)
    local DIVE_SPEED_MUL = 2                -- 俯冲速度 = photoIndex × 2（原作，photoIndex 上限 8）
    local DIVE_X_RANGE = 192                -- ins_27(floatV0, randF32S, 192) ⇒ x ∈ [-192,192]
    local DIVE_SPAWN_Y = field_y(-48)       -- 272（原作的 ins_63(..., -48)）

    ---蝶云（Sub4）：4 发一组、每发 1 帧；出膛点在本体 24 px 内、方向随机；
    ---速度 0.02 → 悬停 60 帧 → 沿自身方向加速 1/60 px/帧² 共 60 帧。
    ---三个数都照原作 slot0/slot1 的 ins_101 抄：kind 0x8000(WAIT) 的 int0 = 60、
    ---kind 0x10(ACCELERATE_VECTOR) 的 int0 = 60 与 f0 = 0.0166667 = 1/60
    ---（B_ecl16_d.txt @1860 / @1900；加速度方向 f1 = -999.99 ⇒ 引擎取弹自己的 angle，
    ---BulletManager.cpp:545-556）。
    ---★ CLOUD_ACCEL 别再调大：实测 2/60 时弹更快飞出场地、云反而**更薄**
    ---（1800 帧的 `峰值同屏 弹` 从 205 掉到 139，`60px 内平均` 从 4.7 掉到 2.8）。
    ---1/60 那种慢慢飘的云才是原作「跟在役小角身后的蝶群」。
    local CLOUD_BURST = 4                   -- 一轮 4 发（= 4 帧）
    local CLOUD_RADIUS = 24
    local CLOUD_SPEED0 = 0.02
    local CLOUD_WAIT = 60
    local CLOUD_ACCEL = 1 / 60
    local CLOUD_ACCEL_FRAMES = 60
    local CLOUD_STYLE = butterfly
    ---原作四发轮着用 color 3/4/5/6（t=0..3 各一发）；butterfly 非 colorful ⇒
    ---贴图号 = ceil(色号/2)，3/4 都是 butterfly2、5/6 都是 butterfly3 —— 两种贴图。
    ---照抄原作四个色号（不再自己挑两个色）。
    local CLOUD_COLORS = { 3, 4, 5, 6 }

    local PHOTO_LIMIT = 8                   -- Sub2 的 ins_141(8)：相机快门上限（photo_index 的截断值）

    local CARD_NAME = "超人「飛翔役小角」"
    ---原作卡计时 ins_114(7208) ≈ 120 秒；沿用本仓库的 50 秒。
    local CARD_TIME = 50
    ---原作 Timeline0 给的生命是 150；这里按本仓库的量级抬到 900。
    local CARD_HP = 900
    ---符卡历史槽位：410..414 已被占、416 被卡 75 占掉，这张取 415。
    local CARD_ID = 415

    ---──────────────────────── 演出 / 弹幕 ────────────────────────

    ---蝶云里每一颗的逐帧钩子：先悬停 CLOUD_WAIT 帧（原作 slot0 的 0x8000 WAIT），
    ---再沿自身方向加速 CLOUD_ACCEL_FRAMES 帧（slot1 的 0x10 矢量加速，每帧 +1/60）。
    ---（frame 钩子只收一个参数，§5.2；两次都**必须停**，否则弹会一直加速出不了回收边界。）
    local function cloud_frame(unit)
        if unit.wait_left == nil then
            unit.wait_left = CLOUD_WAIT
            unit.accel_left = CLOUD_ACCEL_FRAMES
            unit.cur_v = 0
        end
        if unit.wait_left > 0 then
            unit.wait_left = unit.wait_left - 1
            ---悬停期间原作也是拿 speed = 0.02 在飘（不是 0）：60 帧只挪 1.2 px，
            ---肉眼看不见，但照抄就是了。
            object.SetV(unit, CLOUD_SPEED0, unit.rot, true)
            return
        end
        if unit.accel_left <= 0 then
            return
        end
        unit.accel_left = unit.accel_left - 1
        unit.cur_v = unit.cur_v + CLOUD_ACCEL
        object.SetV(unit, unit.cur_v, unit.rot, true)
    end

    ---蝶云（Sub4）：每帧 1 发、4 帧一轮（ins_4(0,-756) 在 t=4 跳回 t=0 ⇒ 一轮 4 帧）；
    ---每发在出膛点 24 px 内重抽位置、方向各自随机，颜色按 CLOUD_COLORS 逐发轮换。
    local function cloud_stream(owner)
        task.New(owner, function()
            while true do
                for k = 1, CLOUD_BURST do
                    local pa = ran:Float(0, 360)
                    local pr = CLOUD_RADIUS * ran:Float(0, 1)
                    NewSimpleBullet(CLOUD_STYLE, CLOUD_COLORS[k],
                            owner.x + cos(pa) * pr, owner.y + sin(pa) * pr,
                            CLOUD_SPEED0, ran:Float(0, 360), false, 0, false,
                            nil, nil, nil, cloud_frame)
                    task.Wait()
                end
            end
        end)
    end

    ---主体脚本（Sub3）：起飞 → 每帧累加速度 → 出场地就回顶上改成「俯冲」。
    local function flight(owner)
        task.New(owner, function()
            local a = Angle(owner.x, owner.y, player.x, player.y)
            local speed, accel = DIVE_SPEED0, DIVE_ACCEL0
            object.SetV(owner, speed, a, true)
            local w = lstg.world
            while true do
                speed = speed + accel
                object.SetV(owner, speed, a, true)
                ---出界判据照抄原作（TH095 的 x = ±224、y = 480 ⇒ 我们的 boundl/r/b）。
                if owner.x > w.boundr or owner.x < w.boundl or owner.y < w.boundb then
                    local nx = ran:Float(-DIVE_X_RANGE, DIVE_X_RANGE)
                    owner.x, owner.y = nx, DIVE_SPAWN_Y
                    a = Angle(nx, DIVE_SPAWN_Y, player.x, player.y)
                    speed = photo_index(PHOTO_LIMIT) * DIVE_SPEED_MUL
                    accel = DIVE_ACCEL
                    object.SetV(owner, speed, a, true)
                    -- 定位置音效：原作的 ins_106(16)（一个与发弹无关的提示音）
                    PlaySound("tan00", 0.1, owner.x / 256, false)
                end
                task.Wait()
            end
        end)
    end

    ---──────────────────────── 符卡本体 ────────────────────────

    local card = boss.card.New(CARD_NAME, 1, 3, CARD_TIME, CARD_HP)

    function card:before()
    end

    function card:init()
        photo_damage_on(self, PHOTO_LIMIT)  -- 拍照扣血：拍够 PHOTO_LIMIT 张 = 清空血条
        self.x, self.y = BOSS_X, BOSS_START_Y
        task.New(self, function()
            task.Wait(ENTRY_WAIT)
            task.MoveTo(BOSS_HOME_X, BOSS_HOME_Y, ENTRY_TIME, EASE_OUT)
            ---到这里是原作第 130 帧：Sub2 的 t=130 是 ins_104（亮卡名）+ ins_52(3)。
            PlaySound("tan00", 0.1, self.x / 256, false)
            cloud_stream(self)
            flight(self)
        end)
    end

    ---本体的逐帧逻辑：**原作没有**（飞行与发弹都在 ECL 上下文里）。frame 留空是刻意的。
    function card:frame()
    end

    function card:del()
        photo_damage_off(self)
    end

    boss.card.add({ { card, "2a" } }, LEVEL, CARD_NAME, CARD_ID)
end--超人「飛翔役小角」

---──────────────────── Stage EX ── 两件公共工具 ────────────────────
---下面八张卡（scene 100..107）都要用到的两样东西：
---  ① TH095 的 16 色表 → 本仓库弹贴图的行号；
---  ② 原作的「旋转激光」（ins_147/148/153..157）→ 本仓库 laser 的四段驱动。

---TH095 的弹色是**调色板下标**（BulletManager.cpp:128-133 的 g_PhotoBulletColors16）：
---  0 灰 / 1,2 红 / 3,4 紫 / 5,6 蓝 / 7,8 青 / 9,10,11 绿 / 12,13,14 黄 / 15 灰。
---本仓库的弹样式（ball_small / ball_mid / ball_huge / butterfly / water_drop）都用
---COLOR.* 选行号，所以按色相挑最近的一行（灰 = 16，红 = 2，紫 = 4，蓝 = 6，
---青 = 8，绿 = 10，黄 = 12）。同一张卡的注释里只写原作色号，换算走这张表。
local EX_COLOR = {
    COLOR.GRAY,                    -- 0  0x808080 灰
    COLOR.RED,                     -- 1  0xff1010 红
    COLOR.RED,                     -- 2
    COLOR.PURPLE,                  -- 3  0x801080 紫
    COLOR.PURPLE,                  -- 4
    COLOR.BLUE,                    -- 5  0x1010ff 蓝
    COLOR.BLUE,                    -- 6
    COLOR.CYAN,                    -- 7  0x108080 青
    COLOR.CYAN,                    -- 8
    COLOR.GREEN,                   -- 9  0x10ff10 绿
    COLOR.GREEN,                   -- 10
    COLOR.GREEN,                   -- 11
    COLOR.YELLOW,                  -- 12 0x808010 黄
    COLOR.YELLOW,                  -- 13
    COLOR.YELLOW,                  -- 14
    COLOR.GRAY,                    -- 15
}
local function ex_color(i)
    return EX_COLOR[i] or COLOR.GRAY
end

---一把整圈（原作 ins_89，aimMode = CIRCLE）：基准角 + index1×2π/count1 + index2×angleStep。
---count2 = 1 时 speed2/angleStep 都不参与（BulletManager.cpp:369-372）；整圈是对称的，
---所以 TH095 的「顺时针为正」取反之后方向集合不变，直接用 base + i×360/count。
local function ex_ring(style, color, x, y, count, speed, base, frame)
    for i = 0, count - 1 do
        NewSimpleBullet(style, color, x, y, speed,
                base + i * 360 / count, false, 0, false, nil, nil, nil, frame)
    end
end

---一排扇（原作 ins_86 FAN_AIMED / 87 FAN）：第 index1 发的偏移量 =
---（count1 奇数 ? (index1+1)÷2 : index1÷2 + 0.5）× angleStep，index1 奇数取负
---（BulletManager.cpp:352-365）。FAN_AIMED 还要再加一次自机角（86 号）。
---返回的偏移量是**TH095 坐标系**下的度数；调用方按需要取反。
local function ex_fan_offsets(count, step_deg)
    local t = {}
    local odd = (count % 2) ~= 0
    for i = 0, count - 1 do
        ---★ 原作这两项都是**整数除法**（C 里 index1 是 i32，BulletManager.cpp:352-365）：
        ---    奇数：(index1+1)÷2 向下取整 ⇒ 0, 1, 1, 2, 2, 3…
        ---    偶数：index1÷2 向下取整再 +0.5 ⇒ 0.5, 0.5, 1.5, 1.5…
        ---  （旧写法 (i+1)*0.5 / i*0.5+0.5 从第 3 发起就偏了。）
        local k = odd and math.floor((i + 1) / 2) or (math.floor(i / 2) + 0.5)
        local a = k * step_deg
        if i % 2 ~= 0 then
            a = -a
        end
        t[i + 1] = a
    end
    return t
end

---──────────────────── Stage EX 的旋转激光 ────────────────────
---TH095 的 PhotoRotatingLaserView（PhotoEffect.cpp:348-460）：
---  · 长度每帧 += speed 直到 maximumLength（153/154 从 0 起，147/148/155/156/157 从满长起）；
---  · angle 每帧 += angularVelocity；position 每帧 += velocity（只有 155/156/157 带 vx/vy）；
---  · 四段：STARTUP（宽度恒 2 的细预警线、**无判定**）→ GROWING（宽度 0→maximumWidth）
---    → ACTIVE（maximumWidth 维持）→ FADING（→0、无判定）；宽度是**全宽**。
---  · 判定只在 GROWING/ACTIVE 且 length > 16 时存在（PhotoEffect.cpp:437-451）。
---  · followPhotoTarget 的激光每帧把位置拉回拍照目标（原作 ins_109 指的 boss），
---    我们这边就是本体（见各卡注释）。
---  · 原作的 g_AnmGameSpeed = 1；同时最多 256 条（PhotoEffect.cpp:1165），移植不设上限。
---★ 本仓库 laser 的命中半宽 = w/2（laser.lua:81-110 的 dist = 2），和上面的 width/2 一致；
---  长度放 l2、l1 = l3 = 0 ⇒ 判定盒是直矩形，不是本仓库默认两头收窄的六边形。
---★ 四段计时必须**挂在 owner（boss）的 task 上**：check_stage.lua 的 laser 桩件里
---  _TurnOn/_TurnOff 是空函数、laser:frame 也不跑 task.Do ⇒ 挂在 laser 自己身上，
---  自检里永远不收（th33 的 fan_laser 踩过同一个坑，见 :1310-1400）。
local EX_LASER_WARN_W = 2                 -- STARTUP 的预警线宽（原作初始 width = 2.0）

---把一根 EX 激光跑完四段，到点自己 RawDel。len0 已在 l.l2 里。
local function run_ex_laser(owner, l, max_len, width, speed, startup, grow, sustain, fade,
        ang_vel, vx, vy, follow)
    task.New(owner, function()
        local len = l.l2
        local phase, timer = 1, 0
        while IsValid(l) do
            if len < max_len then
                len = min(max_len, len + speed)
            end
            l.rot = l.rot + ang_vel
            if follow then
                l.x, l.y = owner.x, owner.y
            end
            l.x, l.y = l.x + vx, l.y + vy
            timer = timer + 1
            if phase == 1 then                     -- STARTUP：细线、无判定
                l.w = EX_LASER_WARN_W
                l.colli = false
                if timer >= startup then phase, timer = 2, 0 end
            elseif phase == 2 then                 -- GROWING：宽度线性长到 width
                l.w = width * timer / grow
                l.colli = len > 16
                if timer >= grow then phase, timer = 3, 0 end
            elseif phase == 3 then                 -- ACTIVE
                l.w = width
                l.colli = len > 16
                if timer >= sustain then phase, timer = 4, 0 end
            else                                   -- FADING：无判定
                l.w = width - width * timer / fade
                l.colli = false
                if timer >= fade then break end
            end
            l.l1, l.l2, l.l3 = 0, len, 0
            l.alpha = 1
            task.Wait()
        end
        if IsValid(l) then
            object.RawDel(l)
        end
    end)
end

---生成一根 EX 激光。index = 贴图行（1..16，见各卡注释里挑行的理由）；
---start_full = true ⇒ 初始就是 max_len（147/148/155/156/157），false ⇒ 从 0 长（153/154）。
local function spawn_ex_laser(owner, lasers, index, x, y, angle, max_len, width, speed,
        startup, grow, sustain, fade, ang_vel, vx, vy, follow, start_full)
    local len0 = start_full and max_len or 0
    local l = New(laser, index, x, y, angle, 0, len0, 0, 0, 0, 0)
    l.colli = false
    lasers[#lasers + 1] = l
    run_ex_laser(owner, l, max_len, width, speed, startup, grow, sustain, fade,
            ang_vel, vx, vy, follow)
    return l
end

do  -- 100 禁忌「フォービドゥンフルーツ」（ecl22_a，芙兰，组 3a 第 1 张）
    ---原作是「禁果从场地的四个角长出来」：本体停在**中轴 (0,192)** 不动，只把 shootOffset
    ---依次挪到四个角落，在每个角原地甩出一整圈小玉、再回本体甩一圈 —— 一共五圈一起炸开。
    ---数据源 /tmp/E_ecl22_a.txt（脚本 /tmp/d95v2.py 反汇编，ECL 在
    ---[th095] …/data/ecl22_a.ecl）。骨架：
    ---  · Sub2：ins_63(-128,-64) 进场 → t=100 ins_64(30,4,0,192) 用 30 帧落到 (0,192)，
    ---    同时 ins_141(6) 把「要拍够几张」设成 6；t=130 亮卡名 + ins_75 设移动框
    ---    (-140,128,140,192) + ins_52(3) 起主脚本。
    ---  · Sub3（主脚本）一轮 480 帧：t=0 起 Sub8（装饰），t=60 把 slot0 换成 Sub6（**发弹**），
    ---    t=60 的 ins_2(180) 把 Sub3 自己冻结 180 帧，醒来后重开 Sub8；t=120 处其实是
    ---    被 t=60 的冻结推迟到第 300 帧才执行的第二块 —— 换成 Sub7（另一色发弹），
    ---    再冻结 180 帧，然后 ins_4(0,-272) 跳回 t=0。⇒ 一轮 480 帧、两种颜色交替。
    ---  · Sub6 / Sub7 是发弹上下文，进入时立刻发一轮，之后 t=60 / t=120 各**有条件**再发一轮：
    ---    @2964 / @3472 的 `ins_44(photoIndex, 3)` 是 **CMPlt（< 才跳）**（EclRunLow.inl:420 附近
    ---    的比较表；跳转目标 @3460/@3968 正是「跳过这一轮」）⇒ **photoIndex ≥ 3 才有后两轮**，
    ---    拍得越多这一张越密（旧注释把这条读反过，别再照抄）。
    ---  · 每轮 = 四个角各一整圈（Sub6 96 发 / Sub7 88 发、速 1.0）+ 本体一圈
    ---    （两色都是 68 发、速 0.8）。四个角是 ins_26(extraFloat, 角坐标, pos) + ins_100 得到的
    ---    **世界坐标** (-192,0)/(192,0)/(-192,448)/(192,448)（TH095 坐标），
    ---    换算到我们这边 y = 224 − y ⇒ 四个角就是场地的四角。
    ---  · 弹型 18 = 直径 6 ⇒ 用 ball_small（半径 2，最接近）；ins_89 的 aimMode = CIRCLE
    ---    （angle = 操作数 angle + index1×2π/count1 + index2×angleStep，而 count2 = 1 ⇒
    ---    angleStep = 0.1848 不参与，BulletManager.cpp:369-372）。
    ---    flags 514 = 0x202 = PLAY_SPAWN_SOUND + SPAWN_FAST；出场滑动我们统一不做（文件头差异 3），
    ---    出膛音每条弹幕响一次（原作也是整波响一次，BulletManager.cpp:717-723）。
    ---  · 色号：原作两色是 1 与 0。TH095 的 16 色表 g_PhotoBulletColors16 下标 0 = 灰、
    ---    1 = 红（见文件头「色表」一节）⇒ 我们取 ball_small1（红）与 COLOR.GRAY（16，灰）。
    ---  · Sub8（106(5)+150(10) 每帧）是整屏装饰 ANM，Sub4/Sub5 在 Sub3 里从来没被调用过
    ---    （旧摘要把 4/5 当成主发弹是读错了），Sub9 也没被调用 —— 一律不实现。
    local BOSS_X, BOSS_START_Y = -128, field_y(-64)     -- 288（场地外）
    local BOSS_HOME_X, BOSS_HOME_Y = 0, field_y(192)    -- 0 / 32
    local ENTRY_WAIT, ENTRY_TIME = 100, 30
    local EASE_OUT = VALUE_SET.DECEL

    ---Sub2 的 ins_141(6)：原作要求拍中的张数（也就是本卡的拍照血量分母）。
    local PHOTO_LIMIT = 6

    local CARD_NAME = "禁忌「フォービドゥンフルーツ」"
    ---原作卡计时 ins_114(7208) ≈ 120 秒；沿用本仓库的 50 秒（同前七张）。
    local CARD_TIME = 50
    ---原作 Timeline0 给的生命是 150；这里按本仓库的量级抬到 900。
    local CARD_HP = 900
    ---符卡历史槽位：410..416 已被上一批七张占掉；th31 的 LIST 实际用到 452
    ---（mod/GAME/th31.lua 的 `local LIST = {`，末行「魔砲「ファイナルマスタースパーク」」
    ---占 452 —— **别只扫 boss.card.add 的 CARD_ID=、也别只看 LIST 第 3 项之外的行**），
    ---所以 Stage EX 从 453 起（见文件头「符卡历史槽位」）。
    local CARD_ID = 453

    ---──────────────────────── 演出 / 弹幕 ────────────────────────

    ---四个角（我们的坐标；TH095 的 (-192,0)/(192,0)/(-192,448)/(192,448) 各翻一次 y）。
    local CORNERS = { { -192, 224 }, { 192, 224 }, { -192, -224 }, { 192, -224 } }

    local STYLE = ball_small
    local CORNER_SPEED = 1.0                -- 四角那几圈 ins_89 的 speed1（count2 = 1）
    local BODY_SPEED = 0.8                  -- 本体那圈 ins_89 的 speed1
    local COLOR_A = ex_color(1)             -- Sub6 的 color 1（红）
    local COLOR_B = ex_color(0)             -- Sub7 的 color 0（灰）

    ---时间轴（单位：帧，全部从 Sub3 的 t=0 起算）：60 → Sub6 发第一轮；
    ---Sub6 自己会在 +60 / +120 再各发一轮（photoIndex ≥ 3 才发）；Sub3 冻结到 240 才醒；
    ---再 60 帧（= 300）换 Sub7；再冻结 180 → 480 回到 t=0。
    local FIRST_DELAY = 60
    local REPEAT_GAP = 60
    local REPEAT_LIMIT = 3                  -- Sub6/Sub7 最多 3 轮（t=0/60/120）
    local DENSITY_MIN_PHOTOS = 3            -- ins_44(photoIndex, 3)：< 3 就跳过后续轮
    local PAUSE = 180                       -- Sub3 的 ins_2(180)（冻结 180 帧）

    ---从 (x,y) 甩出一整圈 count 发：基准角每圈重抽（原作的 ins_7(floatV0, rand(-π,π))）。
    ---整圈是对称的，TH095 的「顺时针为正」取反后方向集合不变 ⇒ 直接用 base + i*360/count。
    local function fire_ring(x, y, color, count, speed)
        local base = ran:Float(0, 360)
        for i = 0, count - 1 do
            NewSimpleBullet(STYLE, color, x, y, speed,
                    base + i * 360 / count, false, 0, false)
        end
    end

    ---Sub6 / Sub7 的一轮：四个角各一圈 + 本体一圈（顺序、发数、速度全照 dump）。
    local function fire_volley(owner, color, corner_count, body_count)
        for i = 1, #CORNERS do
            fire_ring(CORNERS[i][1], CORNERS[i][2], color, corner_count, CORNER_SPEED)
        end
        fire_ring(owner.x, owner.y, color, body_count, BODY_SPEED)
        -- flags 的 0x200 = PLAY_SPAWN_SOUND：整波只响一声。
        PlaySound("tan00", 0.1, owner.x / 256, false)
    end

    ---一个发弹上下文（= Sub6 / Sub7）：立刻一轮，然后 t=60 / t=120 各再看一次
    ---「photoIndex ≥ 3 才补一轮」（ins_44 的 CMPlt 意思就是 < 3 时跳过）。
    ---★ 它必须**独立于 Sub3**跑：Sub3 在 t=60 之后被 ins_2 冻住，两个上下文是各跑各的。
    local function volley_context(owner, color, corner_count, body_count)
        task.New(owner, function()
            fire_volley(owner, color, corner_count, body_count)
            for _ = 2, REPEAT_LIMIT do
                task.Wait(REPEAT_GAP)
                if photo_index(PHOTO_LIMIT) >= DENSITY_MIN_PHOTOS then
                    fire_volley(owner, color, corner_count, body_count)
                end
            end
        end)
    end

    ---──────────────────────── 符卡本体 ────────────────────────

    local card = boss.card.New(CARD_NAME, 1, 3, CARD_TIME, CARD_HP)

    function card:before()
    end

    function card:init()
        photo_damage_on(self, PHOTO_LIMIT)  -- 拍照扣血：拍够 PHOTO_LIMIT 张 = 清空血条
        self.x, self.y = BOSS_X, BOSS_START_Y
        task.New(self, function()
            task.Wait(ENTRY_WAIT)
            task.MoveTo(BOSS_HOME_X, BOSS_HOME_Y, ENTRY_TIME, EASE_OUT)
            ---到这里是原作 Sub2 的 t=130：亮卡名 + 起 Sub3（那两条演出我们交给符卡系统）。
            while true do
                task.Wait(FIRST_DELAY)
                volley_context(self, COLOR_A, 96, 68)   -- Sub6（红）
                task.Wait(PAUSE)
                task.Wait(FIRST_DELAY)
                volley_context(self, COLOR_B, 88, 68)   -- Sub7（灰）
                task.Wait(PAUSE)
            end
        end)
    end

    ---本体的逐帧逻辑：原作没有（发弹全在 ECL 上下文里）。留空是刻意的。
    function card:frame()
    end

    function card:del()
        photo_damage_off(self)
    end

    boss.card.add({ { card, "3a" } }, LEVEL, CARD_NAME, CARD_ID)
end--禁忌「フォービドゥンフルーツ」

do  -- 101 禁忌「禁じられた遊び」（ecl22_b，芙兰，组 3a 第 2 张）
    ---原作是「不许玩的游戏」：本体贴着中轴 y=0 在 ±48 的窄框里**左右躲**（自机的反方向），
    ---同时只有**一层**弹幕 —— 每 120 帧换一组朝向的**飞棍激光**（外加每波一颗大玉圈）。
---数据源 /tmp/E_ecl22_b.txt。骨架：
    ---  · Sub2：ins_63(-128,-64) 进场 → **t=40** 就 ins_64(30,4,0,224) 落到 (0,224)（TH095
    ---    坐标 y 朝下 ⇒ 我们的 y = 0，正中央）；t=70 亮卡名 + ins_75(-48,224,48,224)
    ---    ⇒ 移动框就一条横线 x∈[-48,48]、y = 0（原作的 CLAMP_TO_MOVEMENT_BOUNDS 会夹住它）。
    ---  · Sub3（主脚本）：t=0 起 Sub7（装饰）与 Sub4（激光）、t=30 一声演出、
    ---    t=60 的 ins_51(pos.x, player.x) 是**浮点 ≥**（CMPfge，条件成立才跳，EclRunLow.inl
    ---    的比较表）：本体在自机右边就往左走（π），否则往右走（0），ins_66(60,0,角,0.5)
    ---    = 60 帧直线走 30 px；t=120 的 ins_4(0,-132) 跳回 t=30 ⇒ 一轮 **90 帧**
    ---    （走 60 帧 + 歇 30 帧）。x 轴不受坐标翻转影响，判据可以照抄。
    ---  · Sub4（激光，480 帧一轮）：t=0/120/240/360 各放 16 根 **type 12** 的旋转激光
    ---    （4 组 × 4 根；每组先 ins_38 设一个「漂移方向」（155 的最后两参 = 每帧位移），
    ---    组内 4 根的指向是十字 {π, 0, −π/2, π/2}、角速度 ±1.5°/帧）。第 4 波额外再放
    ---    8 根 type 12（长 96、维持 600 帧、角速度 −2°/+3°、漂移 = 朝自机 0.5 px/帧）。
    ---    每波还各甩 4 颗 type 17 大玉（`89(17,0,4,1,1,1.5,基准角,…)`，基准角 π/2 与 π/4 交替）。
    ---  · Sub5（每 10 帧一轮的 ins_87 = FAN 双扇）**在文件里从来没被调用**：
    ---    Sub3 只有 ins_117(0,7) 与 ins_117(1,4) 两条（= 装饰 Sub7 + 激光 Sub4），
    ---    Sub2 的 ins_52(3) 起的是 Sub3 —— 全文件再没有第三条指向 Sub5。
    ---    ⇒ 原作这里不发弹，移植版不实现（见下面「Sub5 是死代码」那段）。
    ---  · Sub6（54(2)+80(8)+81(16)）只动标志位、Sub7（106(5)+150(10)）是整屏装饰 ANM，
    ---    都跟弹幕无关，不实现。
    ---  · 弹型：type 3 → ball_small（半径 2）、type 13 → ball_mid（半径 4）、
    ---    type 17 → ball_huge（半径 13.5）。色号走文件头 ex_color()。
    ---  · 角度换算：TH095 顺时针为正、我们逆时针为正 ⇒ 指向角取反、角速度取反、
    ---    漂移向量按 (cos(−θ), sin(−θ)) 算；x 轴不变。
    local BOSS_X, BOSS_START_Y = -128, field_y(-64)     -- 288（场地外）
    local HOME_X, HOME_Y = 0, field_y(224)              -- 0 / 0
    local ENTRY_WAIT, ENTRY_TIME = 40, 30
    local EASE_OUT = VALUE_SET.DECEL
    local BOX_L, BOX_R = -48, 48                        -- ins_75(-48,224,48,224)
    local MOVE_DELAY = 60                               -- Sub3 t=60 的第一次走位
    local MOVE_FRAMES = 60                              -- ins_66 的 N
    local MOVE_STEP = 30                                -- ins_66 的 speed × N = 0.5 × 60
    local MOVE_IDLE = 30                                -- 一轮 90 帧 = 走 60 + 歇 30

    local PHOTO_LIMIT = 6                               -- ins_141(6)
    local CARD_NAME = "禁忌「禁じられた遊び」"
    local CARD_TIME = 50
    local CARD_HP = 900
    local CARD_ID = 454

    ---──────────────────────── 演出 / 弹幕 ────────────────────────

    ---本卡放出的激光（卡结束时统一 RawDel，§7.9 第 9 条）。
    local lasers = {}

    ---type 12 的激光参数（155：满长起步、每帧长 8、宽 16、四段 20/20/220/10）。
    local LASER_INDEX = 12
    local LASER_LEN = 108
    local LASER_W = 16
    local LASER_SPEED = 8
    local LASER_STARTUP, LASER_GROW, LASER_SUSTAIN, LASER_FADE = 20, 20, 220, 10
    ---第 4 波那 8 根（长 96、维持 600）。
    local LASER2_LEN = 96
    local LASER2_SUSTAIN = 600
    local LASER2_AV = { -2, 3 }                         -- 度/帧（TH095 顺时针为正）
    ---四组基准漂移方向与角速度（单位：度/帧，TH095 坐标；见卡头注释的 dump 行号）。
    ---@type table<{dir:number, av:number}>
    local WAVES = {
        { { 90, 1.5 }, { -90, 1.5 }, { 0, -1.5 }, { 180, -1.5 } },
        { { 45, 1.5 }, { -135, 1.5 }, { -45, -1.5 }, { 135, -1.5 } },
        { { 90, -1.5 }, { -90, -1.5 }, { 0, 1.5 }, { 180, 1.5 } },
        { { 45, -1.5 }, { -135, -1.5 }, { -45, 1.5 }, { 135, 1.5 } },
    }
    local WAVE_GAP = 120
    local RING_BASE = { 90, 45, 90, 45 }                -- 每波大玉圈的基准角（TH095 度）
    local BIG_STYLE = ball_huge
    local BIG_COLOR = ex_color(0)                       -- 89(17, 0, …)
    local BIG_COUNT, BIG_SPEED = 4, 1.0
    ---组内 4 根的指向角（TH095 度）：十字。
    local CROSS = { 180, 0, -90, 90 }

    ---一波激光 + 一颗大玉圈。
    local function fire_wave(owner, w, ring_base)
        for _, g in ipairs(w) do
            local vx = cos(-g[1])                            -- 漂移 = ins_38(dir, 1)
            local vy = sin(-g[1])
            local av = -g[2]                                 -- 角速度取反
            for i = 1, #CROSS do
                spawn_ex_laser(owner, lasers, LASER_INDEX, owner.x, owner.y, -CROSS[i],
                        LASER_LEN, LASER_W, LASER_SPEED,
                        LASER_STARTUP, LASER_GROW, LASER_SUSTAIN, LASER_FADE,
                        av, vx, vy, false, true)
            end
        end
        ex_ring(BIG_STYLE, BIG_COLOR, owner.x, owner.y, BIG_COUNT, BIG_SPEED, -ring_base)
        PlaySound("tan00", 0.1, owner.x / 256, false)
    end

    ---第 4 波额外的 8 根：漂移 = 朝自机 0.5 px/帧（ins_38(playerAngle, 0.5)）。
    local function fire_player_lasers(owner)
        local a = Angle(owner.x, owner.y, player.x, player.y)
        local vx, vy = 0.5 * cos(a), 0.5 * sin(a)
        for i = 1, #LASER2_AV do
            local av = -LASER2_AV[i]
            for k = 1, #CROSS do
                spawn_ex_laser(owner, lasers, LASER_INDEX, owner.x, owner.y, -CROSS[k],
                        LASER2_LEN, LASER_W, LASER_SPEED,
                        LASER_STARTUP, LASER_GROW, LASER2_SUSTAIN, LASER_FADE,
                        av, vx, vy, false, true)
            end
        end
    end

    ---Sub4：480 帧一轮，第 4 波多一组朝自机的 8 根。
    local function laser_context(owner)
        task.New(owner, function()
            while true do
                for i = 1, #WAVES do
                    if i > 1 then
                        task.Wait(WAVE_GAP)
                    end
                    fire_wave(owner, WAVES[i], RING_BASE[i])
                    if i == #WAVES then
                        fire_player_lasers(owner)
                    end
                end
                task.Wait(WAVE_GAP)
            end
        end)
    end

    ---Sub5（原文件里的「对自机 7 发 / 背自机 21 发」双扇）是**死代码**：Sub3 只调
    ---ins_117(0,7) 与 ins_117(1,4)（= 装饰 Sub7 + 激光 Sub4），全文件再没有第二条
    ---ins_117/ins_52 指向 Sub5（`grep id=117 /tmp/E_ecl22_b.txt` 只有 @760/@780 两行）
    ---⇒ 原作里这一层根本不会执行，移植时删掉（旧注释把它当成真发弹，已改正）。

    ---──────────────────────── 符卡本体 ────────────────────────

    local card = boss.card.New(CARD_NAME, 1, 3, CARD_TIME, CARD_HP)

    function card:before()
    end

    function card:init()
        photo_damage_on(self, PHOTO_LIMIT)
        self.x, self.y = BOSS_X, BOSS_START_Y
        task.New(self, function()
            task.Wait(ENTRY_WAIT)
            task.MoveTo(HOME_X, HOME_Y, ENTRY_TIME, EASE_OUT)
            ---到这里是原作 Sub2 的 t=70：亮卡名 + 起 Sub3。
            laser_context(self)
            task.Wait(MOVE_DELAY)
            while true do
                ---ins_51：本体在自机右边就往左走，否则往右走（总是躲开自机）。
                local dir = (self.x >= player.x) and 180 or 0
                local tx = max(BOX_L, min(BOX_R, self.x + MOVE_STEP * cos(dir)))
                task.MoveTo(tx, HOME_Y, MOVE_FRAMES, VALUE_SET.NORMAL)
                task.Wait(MOVE_IDLE)
            end
        end)
    end

    function card:frame()
    end

    function card:del()
        photo_damage_off(self)
        for i = #lasers, 1, -1 do
            if IsValid(lasers[i]) then
                object.RawDel(lasers[i])
            end
        end
    end

    boss.card.add({ { card, "3a" } }, LEVEL, CARD_NAME, CARD_ID)
end--禁忌「禁じられた遊び」

do  -- 102 境符「色と空の境界」（ecl23_a，紫，组 4a 第 1 张）
    ---原作分前后两段，各由「128 根旋转激光」+「4 条扇弹上下文」组成；两段之间把角色
    ---在场上清一次再换一套（激光的旋向、扇的转法都反过来）。
---数据源 /tmp/E_ecl23_a.txt。骨架：
    ---  · Sub2：ins_63(-128,-64) 进场 → t=100 ins_64(30,4,0,192) 落到 (0,192)（我们的 (0,32)）、
    ---    ins_141(5) ⇒ 本卡要拍中 5 张；t=130 亮卡名 + ins_75 + ins_52(3) 起 Sub3。
    ---  · Sub3 全在 t=0、靠 ins_2 一节一节往下走，一轮 **980 帧**：
    ---      117(0,4) Sub4 → 等 150 → 117(0,6) Sub6 → 等 120
    ---      → 4 条 Sub7（扇）→ 等 110 → 演出 → 等 50 → 把 4 条全删 → 等 60
    ---      → 117(0,5) Sub5 → 等 150 → 117(0,6) Sub6 → 等 120
    ---      → 4 条 Sub8（随机扇）→ 等 110 → 演出 → 等 50 → 全删 → 等 60 → 跳回开头。
    ---  · Sub4 / Sub5 是同一套的镜像（角速度符号相反）：128 根 ins_147 旋转激光，
    ---    分两批各 64 根 —— 批量 1（type 7、色 5、四段 30/30/30/10、角速度 ±0.1758°/帧）
    ---    在角度 k×11.25°；批量 2（type 12、色 0、四段 60/30/30/10、角速度 ∓0.1758°/帧）
    ---    在 (k+0.5)×11.25°（Sub4 的 @1836 ins_5 回到 @1708；@2024 回到 @1896）。
    ---    参数照 ins_147：最大长 512、宽 16、followPhotoTarget = 1 ⇒ 每帧钉在本体上。
    ---  · Sub6 换成 ins_157（四段 50/10/10/4、最大长 512、角速度 ∓0.3516°/帧），
    ---    每轮两根：A 在 (k+0.5)×11.25°、B 在 (k+1)×11.25°；64 轮 ⇒ 128 根。
    ---    ★ 两段调的**是同一个 Sub6**（@788 与 @1196 都是 ins_117(0,6)）⇒ 旋向不翻。
    ---  · Sub7（每 2 帧一轮）：先 ins_38(floatV0, 32) 把出膛点挪到本体 32 px 外、ins_100 写进去，
    ---    floatV2 = floatV0 + floatV1，再 ins_87 = FAN 8 发（步进 10°、速 2.5）；
    ---    收尾 floatV0 += 6°、floatV1 −= 3.6°（所以扇角 = floatV0 + floatV1 每轮净转 +2.4°）。
    ---  · Sub8 同构，只是把扇换成 ins_94 = RANDOM：3 发、角度均匀落 [floatV2−22.5°, floatV2+22.5°]、
    ---    速度均匀 [1.5, 3.1]；收尾 floatV0 −= 6°、floatV1 −= 3.6°（净 −9.6°/轮）。
    ---  · ★ 四条子上下文**不是同一个上下文**：Sub3 在每次 ins_117 之前把 floatV0 设成
    ---    π/2、−π/2、0、π，而 ins_117 会把父上下文的**整份变量区**（PhotoEnemy.hpp:25-34 的
    ---    intVariables/floatVariables/extra*/callParameter* 正好 0x80 字节）memcpy 给子上下文
    ---    （EclRunTargetHigh.inl:206-240）⇒ 四条各自从不同的初值出发、之后互不影响。
    ---    （旧摘要把这条读成「float 不复制、从 0 起」，那是把 0x80 当成了 intVariables[8] 的大小。）
    ---  · 弹型 0 → ball_small（半径 2）。色 6 走 ex_color()。
    ---  · 原作的弹槽上限 640（BulletManager.cpp:310-345）：这张卡在原作里是**打满弹槽**的。
    ---    本仓库没有弹槽上限 ⇒ 稳态同屏弹数比原作高（实测里能看到），图案不变，见文件头差异 3。
    local BOSS_X, BOSS_START_Y = -128, field_y(-64)
    local HOME_X, HOME_Y = 0, field_y(192)              -- 0 / 32
    local ENTRY_WAIT, ENTRY_TIME = 100, 30
    local EASE_OUT = VALUE_SET.DECEL

    local PHOTO_LIMIT = 5                               -- ins_141(5)
    local CARD_NAME = "境符「色と空の境界」"
    local CARD_TIME = 50
    local CARD_HP = 900
    local CARD_ID = 455

    ---──────────────────────── 演出 / 弹幕 ────────────────────────

    local lasers = {}

    ---激光（ins_147 / ins_157）的公共参数。
    local LASER_ROT = 11.25                              -- 每根之间的角距（0.19635 rad）
    local LASER_LEN, LASER_W = 512, 16
    local LASER_SPEED_147 = 8                            -- ins_147 每帧长 8
    local LASER_SPEED_157 = 5                            -- ins_157 每帧长 5
    local AV_147 = -0.1758                               -- 0.00306796 rad/帧（TH095 顺时针为正）
    local AV_157 = -0.3516                               -- 0.00613592 rad/帧

    ---一批 ins_147：count 根、从角度 (k + phase)×LASER_ROT 起、角速度 av。
    ---startup 要单独传：同一批里 type 7 是 30 帧、type 12 是 60 帧（见 lasers_4）。
    local function burst_147(owner, count, phase, index, av, startup)
        for k = 0, count - 1 do
            local a = (k + phase) * LASER_ROT
            spawn_ex_laser(owner, lasers, index, owner.x, owner.y, -a,
                    LASER_LEN, LASER_W, LASER_SPEED_147, startup, 30, 30, 10,
                    av, 0, 0, true, true)
        end
    end

    ---Sub4 / Sub5：两批 64 根（先 type 7 色 5 四段 30/30/30/10、再 type 12 色 0 四段 60/30/30/10）。
    ---角速度按「TH095 顺时针为正 ⇒ 我们取反」：
    ---  Sub4（sign = +1）原值 +0.1758 / −0.1758（type 7 / type 12）
    ---  Sub5（sign = −1）原值 −0.1758 / +0.1758  ⇒ 用 AV_147 = −0.1758 表达就是下表。
    local function lasers_4(owner, sign)
        burst_147(owner, 64, 0, 7, AV_147 * sign, 30)
        burst_147(owner, 64, 0.5, 12, -AV_147 * sign, 60)
    end

    ---Sub6：64 轮 × 2 根 ins_157（A 在 (k+0.5)×11.25°、B 在 (k+1)×11.25°）。
    ---★ 两段用的是**同一个 Sub6**（Sub3 两次都 ins_117(0,6)）⇒ 没有 sign，两段一模一样。
    ---原值：type 12 是 −0.3516°/帧、type 7 是 +0.3516°/帧 ⇒ 我们这边正负互换。
    local function lasers_6(owner)
        for k = 0, 63 do
            local a = (k + 0.5) * LASER_ROT
            spawn_ex_laser(owner, lasers, 12, owner.x, owner.y, -a,
                    LASER_LEN, LASER_W, LASER_SPEED_157, 50, 10, 10, 4,
                    -AV_157, 0, 0, true, true)
            a = (k + 1) * LASER_ROT
            spawn_ex_laser(owner, lasers, 7, owner.x, owner.y, -a,
                    LASER_LEN, LASER_W, LASER_SPEED_157, 50, 10, 10, 4,
                    AV_157, 0, 0, true, true)
        end
    end

    ---Sub7 / Sub8：4 条子上下文，初值 floatV0 = π/2、−π/2、0、π（见卡头注释）。
    local SPAWN_R = 32                                   -- ins_38 的 magnitude
    local FAN_STYLE, FAN_COLOR = ball_small, ex_color(6)
    local FAN_COUNT, FAN_SPEED, FAN_STEP_DEG = 8, 2.5, 10
    local FAN_OFFSETS = ex_fan_offsets(FAN_COUNT, FAN_STEP_DEG)
    local RND_STYLE, RND_COLOR = FAN_STYLE, FAN_COLOR
    local RND_COUNT, RND_SPEED1, RND_SPEED2 = 3, 3.1, 1.5
    local RND_HALF = 22.5                                -- 0.392699 rad
    local FAN_STEP = 6                                   -- 0.10472 rad
    local FAN_STEP1 = 3.6                                -- 0.0628319 rad
    local FAN_INTERVAL = 2                               -- ins_4(0,-156) 在 t=2
    ---四条子上下文的初值（TH095 弧度；见 Sub3 的 ins_7 序列）。
    local CHILD_INIT = { math.pi * 0.5, -math.pi * 0.5, 0, math.pi }

    local function start_fan_children(owner, random)
        local toks = {}
        for i = 1, #CHILD_INIT do
            local tok = { alive = true }
            toks[i] = tok
            task.New(owner, function()
                local fv0 = CHILD_INIT[i]                -- 相对角度（TH095 弧度）
                local fv1 = 0
                while tok.alive do
                    local fv2 = fv0 + fv1
                    ---ins_38 的 (cos,sin) 用**弧度**（fv0 是弧度）⇒ 换算成度再交给本仓库
                    ---角度制的 cos/sin（tools/check_stage.lua:324：sin/cos 是角度制）。
                    local ox = cos(-math.deg(fv0)) * SPAWN_R
                    local oy = sin(-math.deg(fv0)) * SPAWN_R
                    if random then
                        for _ = 1, RND_COUNT do
                            local r = ran:Float(0, 1)
                            local a_th = (fv2 - math.rad(RND_HALF))
                                    + math.rad(RND_HALF * 2) * r
                            local v = RND_SPEED2 + (RND_SPEED1 - RND_SPEED2) * ran:Float(0, 1)
                            NewSimpleBullet(RND_STYLE, RND_COLOR,
                                    owner.x + ox, owner.y + oy, v, -math.deg(a_th), false, 0, false)
                        end
                        fv0 = fv0 - math.rad(FAN_STEP)
                    else
                        for k = 1, #FAN_OFFSETS do
                            NewSimpleBullet(FAN_STYLE, FAN_COLOR,
                                    owner.x + ox, owner.y + oy, FAN_SPEED,
                                    -math.deg(fv2) - FAN_OFFSETS[k], false, 0, false)
                        end
                        fv0 = fv0 + math.rad(FAN_STEP)
                    end
                    fv1 = fv1 - math.rad(FAN_STEP1)
                    PlaySound("tan00", 0.1, owner.x / 256, false)
                    task.Wait(FAN_INTERVAL)
                end
            end)
        end
        return toks
    end

    local function stop_children(toks)
        for i = 1, #toks do
            toks[i].alive = false
        end
    end

    ---──────────────────────── 符卡本体 ────────────────────────

    local card = boss.card.New(CARD_NAME, 1, 3, CARD_TIME, CARD_HP)

    function card:before()
    end

    function card:init()
        photo_damage_on(self, PHOTO_LIMIT)
        self.x, self.y = BOSS_X, BOSS_START_Y
        task.New(self, function()
            task.Wait(ENTRY_WAIT)
            task.MoveTo(HOME_X, HOME_Y, ENTRY_TIME, EASE_OUT)
            ---到这里是原作 Sub2 的 t=130，起 Sub3。
            while true do
                lasers_4(self, 1)                     -- 第一批的旋向
                task.Wait(150)
                lasers_6(self)                        -- 两段共用、不翻
                task.Wait(120)
                local toks = start_fan_children(self, false)
                task.Wait(110)
                PlaySound("tan00", 0.1, self.x / 256, false)
                task.Wait(50)
                stop_children(toks)
                task.Wait(60)

                lasers_4(self, -1)                    -- 旋向反过来
                task.Wait(150)
                lasers_6(self)                        -- 同一份 Sub6
                task.Wait(120)
                toks = start_fan_children(self, true)
                task.Wait(110)
                PlaySound("tan00", 0.1, self.x / 256, false)
                task.Wait(50)
                stop_children(toks)
                task.Wait(60)
            end
        end)
    end

    function card:frame()
    end

    function card:del()
        photo_damage_off(self)
        for i = #lasers, 1, -1 do
            if IsValid(lasers[i]) then
                object.RawDel(lasers[i])
            end
        end
    end

    boss.card.add({ { card, "4a" } }, LEVEL, CARD_NAME, CARD_ID)
end--境符「色と空の境界」

do  -- 103 境符「波と粒の境界」（ecl23_b，紫，组 4a 第 2 张）
    ---原作只有一件事：本体停在 (0,192)（我们的 (0,32)）不动，一条发弹上下文**每帧**甩
    ---一圈 **5 发**（半径 2 的小玉）。圈本身每帧被转过一个角度、而这个「每帧转角」又
    ---**每帧再加一点点** ⇒ 子弹被一层层铺成弯的「波」，也就是卡名的「波」与「粒」。
---数据源 /tmp/E_ecl23_b.txt。骨架：
    ---  · Sub2：ins_63(-128,-64) 进场 → t=100 ins_64(30,4,0,192) 落地、ins_141(6)；
    ---    t=130 亮卡名 + ins_75(-140,128,140,192) + ins_52(3) 起 Sub3。
    ---  · Sub3：t=0 设 floatV2 = 0.000654498 rad（= π/4800）并起 Sub4；之后只有两段
    ---    ins_2(180) 的空转（t=60 → t=120 → 跳回 t=60），**Sub4 只起这一次**、永远跑下去。
    ---  · Sub4（每帧一轮，ins_4(0,-160) 在 t=1 跳回 @916）：
    ---      floatV3 = photoIndex × 0.1 + 2.6          ← 弹速：拍得越多越快（2.6 → 3.2）
    ---      ins_91 = OFFSET_CIRCLE：5 发，角度 = π/5 + index1×2π/5 + floatV0
    ---      floatV0 += floatV1；floatV1 += floatV2     ← 圈每帧转 floatV1，floatV1 自己每帧涨
    ---    所以第 t 帧的「每帧转角」= t×π/4800，转角是**二次加速**的（4 分钟才到 180°/帧）。
    ---  · Sub5（102 清屏 + 把 floatV2 改成负的 + 重起 Sub4）在整份 ECL 里**没有任何
    ---    ins_117(·,5)** —— 是死代码，原作里从来没跑过（自己在文件里搜过一遍字节确认），
    ---    所以「加速度反向」这件事不会发生，不实现。
    ---  · 弹型 3 → ball_small（半径 2）；色 4 走 ex_color()。flags 514 = 0x202（出场音 + SPAWN_FAST，
    ---    出场滑动我们统一不做，见文件头差异 3）。
    ---  · 角度：OFFSET_CIRCLE 的一圈是对称的，但整圈的**相位** floatV0 会被取反，
    ---    所以照常按 −(π/5 + i×2π/5 + floatV0) 发。
    local BOSS_X, BOSS_START_Y = -128, field_y(-64)
    local HOME_X, HOME_Y = 0, field_y(192)              -- 0 / 32
    local ENTRY_WAIT, ENTRY_TIME = 100, 30
    local EASE_OUT = VALUE_SET.DECEL

    local PHOTO_LIMIT = 6                               -- ins_141(6)
    local CARD_NAME = "境符「波と粒の境界」"
    local CARD_TIME = 50
    local CARD_HP = 900
    local CARD_ID = 456

    ---──────────────────────── 演出 / 弹幕 ────────────────────────

    local RING_COUNT = 5                                -- ins_91 的 count1
    local RING_STYLE = ball_small
    local RING_COLOR = ex_color(4)                      -- ins_91 的 color 4
    local SPEED_BASE, SPEED_PER_PHOTO = 2.6, 0.1        -- floatV3 = photoIndex×0.1 + 2.6
    local ACCEL = math.pi / 4800                        -- floatV2 = 0.000654498 rad/帧
    local STEP0 = math.pi * 0.5                         -- floatV0 的初值 π/2

    ---Sub4：每帧一圈，圈在转、转速自己还在涨。
    local function ring_stream(owner)
        task.New(owner, function()
            local fv0, fv1 = STEP0, 0
            local step = 2 * math.pi / RING_COUNT
            while true do
                local speed = SPEED_BASE + photo_index(PHOTO_LIMIT) * SPEED_PER_PHOTO
                for i = 0, RING_COUNT - 1 do
                    local a = math.pi / RING_COUNT + i * step + fv0
                    ---原作的 a 是 TH095 弧度（floatV0 初值 π/2、每帧 += π/4800）
                    ---⇒ 取反并转度后再交给角度制的 NewSimpleBullet。
                    NewSimpleBullet(RING_STYLE, RING_COLOR, owner.x, owner.y,
                            speed, -math.deg(a), false, 0, false)
                end
                PlaySound("tan00", 0.1, owner.x / 256, false)
                fv0 = fv0 + fv1
                fv1 = fv1 + ACCEL
                task.Wait(1)
            end
        end)
    end

    ---──────────────────────── 符卡本体 ────────────────────────

    local card = boss.card.New(CARD_NAME, 1, 3, CARD_TIME, CARD_HP)

    function card:before()
    end

    function card:init()
        photo_damage_on(self, PHOTO_LIMIT)
        self.x, self.y = BOSS_X, BOSS_START_Y
        task.New(self, function()
            task.Wait(ENTRY_WAIT)
            task.MoveTo(HOME_X, HOME_Y, ENTRY_TIME, EASE_OUT)
            ---到这里是原作 Sub2 的 t=130：起 Sub3 → 起 Sub4（只起这一次）。
            ring_stream(self)
        end)
    end

    function card:frame()
    end

    function card:del()
        photo_damage_off(self)
    end

    boss.card.add({ { card, "4a" } }, LEVEL, CARD_NAME, CARD_ID)
end--境符「波と粒の境界」

do  -- 104 貴人「サンジェルマンの忠告」（ecl24_a，妹红，组 5a 第 1 张）
    ---原作：本体在一条**浅横带**里来回瞬移，同时每 2 帧朝四周甩一圈「快慢双弹」。
    ---数据源 /tmp/E_ecl24_a.txt（ECL …/data/ecl24_a.ecl）。骨架：
    ---  · Sub2：ins_63(-128,-64) 进场 → t=100 ins_64(30,4,0,192) 用 30 帧落到 (0,192)
    ---    （我们的 (0,32)）；ins_141(10) ⇒ 要拍中 10 张；t=130 亮卡名 +
    ---    ins_75(-140,128,140,192) 把活动框设成 x∈[-140,140]、y∈[128,192]（我们的
    ---    y∈[32,96]）+ ins_52(3) 起 Sub3。
    ---  · Sub3（主脚本）一轮 180 帧：
    ---      t=0 起 Sub4（发弹上下文）；t=75 演出；t=90 先瞬移再**重开 Sub4**
    ---      （ins_117(0,4) 会把旧上下文删掉重建）；t=165 演出；t=180 再瞬移一次，
    ---      然后 ins_4(0,-592) 跳回 **t=0 的 ins_62**（@784）—— 跳回点在那两条 ins_7 之后，
    ---      所以 playerAngle 只在第一轮读一次（旧摘要读成「每轮重读」）。⇒ 每 90 帧
    ---      瞬移一次、并把 Sub4 重开一次（重开时才重读 photoIndex → 圈数每 90 帧才变）。
    ---  · 瞬移（ins_63 = SetPosition，带 ins_75 的活动框 clamp）：
    ---      t=90：x = rand×64 + (intV0 ? 124 : -188)、y = rand×64+128
    ---            ⇒ clamp 后 x 落在 ±140 两侧、y∈[128,192]；
    ---      t=180：x = randSigned×32、y = rand×64+128 ⇒ 回到中线附近。
    ---  · Sub4：**每 2 帧**一轮：
    ---      intV1 = photoIndex/2 + 11（拍得越多圈越密，11..16）；
    ---      ins_89(type 18、color 1、count1 = intV1、count2 = 2、speed1 = 4、speed2 = 1.5、
    ---             angleStep = 0) ⇒ 一圈 intV1 个方向，每个方向**两颗**（速 4.0 与 2.75）。
    ---      基角是 floatV0/floatV1 二选一（intV0 = randU31 % 2，进上下文时抽一次、定死），
    ---      两者每轮分别 −0.5°/+0.5°（TH095）⇒ 环在慢慢转；变量本身由 Sub3 在 t=90/t=180
    ---      加减 45°、甚至被位置量覆盖后再复用（见 main_script / teleport_mid 的注释）。
    ---      ★ Sub4 在 t=2 处有一条 ins_4(0,-224) 跳回自己的 t=0 —— 这条跳转**先**执行、
    ---        且把上下文时间重置为 0，所以 @1740 之后那一段（四角 96 发 + 本体 64 发）
    ---        是**死代码**，原作里从来不会执行（旧摘要把它当成了第二段发弹）。
    ---  · Sub5/Sub6/Sub7：ins_83(5)/83(6) 生出来的**装饰**敌人（ANM 8/9，Sub7 每帧跟随
    ---    photoTarget0），不发弹也不吃判定，按文件头差异 3 的口径不实现。
    ---  · 弹型 18 = 直径 6 ⇒ ball_small；color 1 = 红。flags 514 的出场滑动同差异 3。
    local BOSS_X, BOSS_START_Y = -128, field_y(-64)
    local HOME_X, HOME_Y = 0, field_y(192)              -- 0 / 32
    local ENTRY_WAIT, ENTRY_TIME = 100, 30
    local EASE_OUT = VALUE_SET.DECEL
    local BOX_L, BOX_R = -140, 140                      -- ins_75 的 x 范围
    local BAND_LO, BAND_HI = 128, 192                   -- ins_75 的 y 范围（TH095）

    local PHOTO_LIMIT = 10                              -- ins_141(10)
    local CARD_NAME = "貴人「サンジェルマンの忠告」"
    ---原作卡计时 ins_114(10808)；沿用本仓库的 50 秒。
    local CARD_TIME = 50
    local CARD_HP = 900
    local CARD_ID = 457

    ---──────────────────────── 弹幕 ────────────────────────

    local RING_STYLE, RING_COLOR = ball_small, ex_color(1)
    local RING_COUNT0 = 11                              -- intV1 = photoIndex/2 + 11
    local RING_SPEED1, RING_SPEED2 = 4, 1.5             -- count2 = 2 ⇒ 4.0 与 2.75
    local RING_GAP = 2                                  -- Sub4 的 ins_4(0,-224)
    local BLOCK = 90                                    -- Sub3 每 90 帧重开一次 Sub4

    ---一圈：count1 个方向 × 2 个速度（angleStep = 0 ⇒ 同一方向两颗），基准角 base。
    local function fire_ring(owner, count, base)
        local step = 360 / count
        local v2 = RING_SPEED1 - (RING_SPEED1 - RING_SPEED2) / 2
        for i = 0, count - 1 do
            local a = base + i * step
            NewSimpleBullet(RING_STYLE, RING_COLOR, owner.x, owner.y,
                    RING_SPEED1, a, false, 0, false)
            NewSimpleBullet(RING_STYLE, RING_COLOR, owner.x, owner.y,
                    v2, a, false, 0, false)
        end
    end

    ---t=90 的瞬移：随机选左右一侧（clamp 之后落到 ±140）。
    ---原作顺序是先抽 intV0 = randU31 % 2 决定方向、再抽两个 randF32 当坐标，照抄。
    local function teleport_side(owner)
        local side = (ran:Int(0, 1) == 0)
        local x = ran:Float(0, 64) + (side and -188 or 124)
        owner.x = max(BOX_L, min(BOX_R, x))
        owner.y = field_y(ran:Float(BAND_LO, BAND_HI))
    end

    ---t=180 的瞬移：中线附近。★ 原作的 floatV0/floatV1 在这里**被位置量覆盖**
    ---（randF32S×32 与 randF32×64+128，本来是 x/y 坐标），瞬移之后又拿它们 ±45° 当
    ---**下一轮的基角**用（EclRun 里 floatV0 就是普通 f32，没有类型）——所以把这两个
    ---残值原样返回给 main_script，别当成普通坐标丢掉。
    local function teleport_mid(owner)
        local px = ran:Float(-32, 32)           -- floatV0 = randF32S × 32（TH095 x）
        local py = ran:Float(BAND_LO, BAND_HI)  -- floatV1 = randF32 × 64 + 128（TH095 y）
        owner.x = max(BOX_L, min(BOX_R, px))
        owner.y = field_y(py)
        return px, py
    end

    ---一轮发弹上下文（= Sub3 两次 ins_117(0,4) 之间那 90 帧）：
    ---  · 圈数 intV1 = int(photoIndex / 2) + 11，**重开时才重读**；
    ---  · 基角在 floatV0 / floatV1 里二选一（intV0 = randU31 % 2，进上下文时抽一次、定死）；
    ---  · 每轮（2 帧）floatV0 −0.5°、floatV1 +0.5°（TH095 弧度 0.00872665）⇒ 环慢慢转。
    ---我们这边基角 = −(TH095 角)：floatV0 那一支每轮 +0.5°、floatV1 那一支 −0.5°。
    local RING_DRIFT = 0.5
    local function ring_block(owner, base0, base1)
        local count = math.floor(photo_index(PHOTO_LIMIT) / 2) + RING_COUNT0
        local use0 = (ran:Int(0, 1) == 0)
        local b0, b1 = base0, base1
        for _ = 1, BLOCK / RING_GAP do
            fire_ring(owner, count, use0 and b0 or b1)
            b0 = b0 + RING_DRIFT
            b1 = b1 - RING_DRIFT
            task.Wait(RING_GAP)
        end
    end

    ---Sub3：一轮 180 帧，t=0 / t=90 各起一次发弹上下文（后一次先瞬移、再把两个「角度变量」
    ---±45°，见 Sub3 @1108/@1144），t=180 瞬移 + 覆盖变量后 ins_4 跳回 t=0（@784，
    ---**跳过**开头那两句 floatV0 = floatV1 = playerAngle ⇒ 自机角只在第一轮读一次）。
    local function main_script(owner)
        task.New(owner, function()
            local f0 = Angle(owner.x, owner.y, player.x, player.y)   -- = −deg(floatV0)
            local f1 = f0                                            -- = −deg(floatV1)
            while true do
                ring_block(owner, f0, f1)            -- @784/@796：起 Sub4
                teleport_side(owner)                 -- @1056：t=90 瞬移
                f0, f1 = f0 + 45, f1 - 45            -- @1108/@1144：floatV0 −= 45°、floatV1 += 45°
                ring_block(owner, f0, f1)            -- @1180：重开 Sub4
                local px, py = teleport_mid(owner)   -- @1284：t=180 瞬移
                ---@1304/@1340：残值当角度再 ±45°（TH095 侧 −45/+45 ⇒ 我们 +45/−45）。
                f0 = -math.deg(px) + 45
                f1 = -math.deg(py) - 45
            end
        end)
    end

    ---──────────────────────── 符卡本体 ────────────────────────

    local card = boss.card.New(CARD_NAME, 1, 3, CARD_TIME, CARD_HP)

    function card:before()
    end

    function card:init()
        photo_damage_on(self, PHOTO_LIMIT)
        self.x, self.y = BOSS_X, BOSS_START_Y
        task.New(self, function()
            task.Wait(ENTRY_WAIT)
            task.MoveTo(HOME_X, HOME_Y, ENTRY_TIME, EASE_OUT)
            ---Sub2 的 t=130：亮卡名 + 起 Sub3。
            PlaySound("tan00", 0.1, self.x / 256, false)
            main_script(self)
        end)
    end

    function card:frame()
    end

    function card:del()
        photo_damage_off(self)
    end

    boss.card.add({ { card, "5a" } }, LEVEL, CARD_NAME, CARD_ID)
end--貴人「サンジェルマンの忠告」

do  -- 105 蓬莱「瑞江浦嶋子と五色の瑞亀」（ecl24_b，妹红，组 5a 第 2 张）
    ---原作：本体在一条浅带里慢慢挪，同时每 30 帧在「上移 32 px 的位置」上向**五**个方向
    ---抛出五色亀（Sub4 = 15 发 24° 等分环、Sub5 = 10 发 36° 等分环，各 5 种颜色）。
    ---数据源 /tmp/E_ecl24_b.txt（ECL …/data/ecl24_b.ecl）。骨架：
    ---  · Sub2：ins_63(-128,-64) 进场 → t=100 ins_64(30,4,0,144) 落 (0,144)（我们的 (0,80)）；
    ---    ins_141(5) ⇒ 拍 5 张；t=130 亮卡名 + ins_75(-140,112,140,144)
    ---    （我们的活动框 x∈[-140,140]、y∈[80,112]）+ ins_52(3) 起 Sub3。
    ---  · Sub3 一轮 360 帧：起 Sub6（子上下文 slot 0）→ ins_2(120) → 演出 →
    ---    ins_2(200) → 杀掉 slot 0（ins_117(0,-1)）→ ins_67(40,4,1) 躲 40 帧 →
    ---    ins_4(0,-124) 跳回 t=0 的 ins_117(0,6)。⇒ 每轮 320 帧齐射 + 40 帧移动。
    ---  · Sub6 是 30 帧一轮的**子上下文**：
    ---      t=0：ins_26(floatV0, pos.y, 32) + ins_63(pos.x, floatV0) ⇒ floatV0 = pos.y − 32
    ---           再写回 pos.y（TH095 y 下正 ⇒ 屏幕上**上移** 32 px；我们坐标就是 +32）；
    ---           一轮结束时（@2884）用 ins_25 加回来。发弹用的 worldPosition 就是**移位后**的位置。
    ---      floatV0 = playerAngle；然后 **5 轮**（每轮末 floatV0 += 72°、ins_37 归一化）：
    ---        ins_38(eF0,eF1, floatV0, 40) + ins_100 ⇒ shootOffset = 40 px 外
    ---        ins_52(4) ⇒ 调 Sub4（15 发）；40→32 px + ins_52(5) ⇒ Sub5（10 发）；
    ---        32→72 px + ins_52(5) ⇒ Sub5 再来一次。5 轮 × 35 = **175 发 / 30 帧**。
    ---      ins_4(0,-1232) 跳回 @1716（t=0），一轮正好 30 帧。
    ---  · Sub4 / Sub5 的基角：**都是同一个 playerAngle**（floatV1 = playerAngle，5 次调用
    ---      之间只把 floatV1 **加 24°/36°**，见 @1048 起的 ins_15）—— 不是「每个方向换个基角」。
    ---      由于 ins_89 的 count2 = 1（angleStep 不参与），Sub4 的 5 次调用得到
    ---      {pa + 24×(photoIndex+k) + 120i}，k=0..4、i=0..2 恰好铺满 15 个连续的 24° 网格
    ---      （k+5i = 0..14）⇒ 整体就是「以自机角为 0° 的 15 发 24° 环」；Sub5 同理是
    ---      10 发 36° 环。photoIndex 只改起点、不改集合（15×24 = 10×36 = 360）。
    ---  · Sub7/Sub8/Sub9：ins_83(7)/83(8) 生出来的装饰敌人（Sub9 每帧跟随 photoTarget0），
    ---    不发弹 ⇒ 按文件头差异 3 不实现。
    ---  · 弹型：Sub4 的 (19,6)(12,0)(19,1)(19,3)(12,7) → 半径 3/5/3/3/5（19→ball_small、
    ---    12→ball_mid）；Sub5 全是型 1（半径 3 → ball_small），色 13,0,2,6,15。
    local BOSS_X, BOSS_START_Y = -128, field_y(-64)
    local HOME_X, HOME_Y = 0, field_y(144)              -- 0 / 80
    local ENTRY_WAIT, ENTRY_TIME = 100, 30
    local EASE_OUT = VALUE_SET.DECEL

    local BOX_L, BOX_R = -140, 140                      -- ins_75 的 x 范围
    local BOX_LO, BOX_HI = 112, 144                     -- ins_75 的 y 范围（TH095）

    local PHOTO_LIMIT = 5                               -- ins_141(5)
    local CARD_NAME = "蓬莱「瑞江浦嶋子と五色の瑞亀」"
    ---原作卡计时 ins_114(7208)；沿用本仓库的 50 秒。
    local CARD_TIME = 50
    local CARD_HP = 900
    local CARD_ID = 458

    ---──────────────────────── 弹幕 ────────────────────────

    ---Sub4 的 5 次 ins_89：(弹型, 色)。半径 5 的型 12 用 ball_mid，其余（半径 3）用 ball_small。
    local TURTLE4 = { { 19, 6 }, { 12, 0 }, { 19, 1 }, { 19, 3 }, { 12, 7 } }
    local TURTLE5_COLOR = { 13, 0, 2, 6, 15 }
    local SUB4_SPEED, SUB5_SPEED = 1.5, 2               -- count2 = 1 ⇒ speed1
    local SUB4_STEP, SUB5_STEP = 24, 36                 -- 0.418879 / 0.628319 rad
    local DISPLACE = 32                                 -- ins_26 的 32

    ---Sub4：5 次（每次 24° 基角步进）× 3 发（120° 等分）= 15 发。
    local function fire_sub4(x, y, pa, pi)
        for k = 0, 4 do
            local st, co = TURTLE4[k + 1][1], TURTLE4[k + 1][2]
            local style = (st == 12) and ball_mid or ball_small
            local b = pa - SUB4_STEP * (pi + k)
            for i = 0, 2 do
                NewSimpleBullet(style, ex_color(co), x, y, SUB4_SPEED,
                        b - 120 * i, false, 0, false)
            end
        end
    end

    ---Sub5：5 次（每次 36° 基角步进）× 2 发（180° 对射）= 10 发。
    local function fire_sub5(x, y, pa, pi)
        for k = 0, 4 do
            local b = pa - SUB5_STEP * (pi + k)
            for i = 0, 1 do
                NewSimpleBullet(ball_small, ex_color(TURTLE5_COLOR[k + 1]), x, y,
                        SUB5_SPEED, b - 180 * i, false, 0, false)
            end
        end
    end

    ---Sub6：30 帧一轮，从本体上方 32 px 处向 3 个方向各甩 Sub4 + 2×Sub5。
    local function sub6(owner, tok)
        task.New(owner, function()
            while tok.alive do
                local ox, oy = owner.x, owner.y + DISPLACE
                local pa = Angle(ox, oy, player.x, player.y)
                local pi = photo_index(PHOTO_LIMIT)
                ---★ 原作是 **5 轮**（@1972/@2200/@2428/@2656 各一次 floatV0 += 72°，
                ---第 5 轮 @2692 之后就直接收尾了）⇒ j = 0..4，一圈 5 × 72° = 360°。
                for j = 0, 4 do
                    local dir = pa - 72 * j
                    local cx, cy = cos(dir), sin(dir)
                    fire_sub4(ox + 40 * cx, oy + 40 * cy, pa, pi)
                    fire_sub5(ox + 32 * cx, oy + 32 * cy, pa, pi)
                    fire_sub5(ox + 72 * cx, oy + 72 * cy, pa, pi)
                end
                PlaySound("tan00", 0.1, owner.x / 256, false)
                task.Wait(30)
            end
        end)
    end

    ---ins_67(40,4,1) = BeginBoundaryAwareMove（EclDependencies.cpp:108）：
    ---先随机挑一个「背离自机」的方向（TH095 弧度、顺时针为正），再按活动框的四条边界
    ---规则修正，最后 40 帧走 speed×duration = 40 px、缓动 4（= 我们的 DECEL）。
    ---活动框只有 32 px 高 ⇒ 两条 y 规则**恒成立**，净效果是把角度强制成负的（朝屏幕上方）。
    local function boundary_move(owner)
        local a
        if player.x < owner.x then
            a = ran:Float(0, math.pi / 2) + 3 * math.pi / 4
        else
            a = ran:Float(0, math.pi / 2) - math.pi / 4
        end
        ---原代码在 x 右边界那一条里用的是 enemy->movementAngle（不是 angle）——照抄。
        local ma = owner.ex_move_angle or 0
        if owner.x < BOX_L + 96 then
            if a > math.pi / 2 then
                a = math.pi - a
            elseif a < -math.pi / 2 then
                a = -math.pi - a
            end
        end
        if owner.x > BOX_R - 96 then
            if a < math.pi / 2 and a >= 0 then
                a = math.pi - ma
            elseif a > -math.pi / 2 and a <= 0 then
                a = -math.pi - a
            end
        end
        local yth = field_y(owner.y)
        if yth < BOX_LO + 48 and a < 0 then
            a = -a
        end
        if yth > BOX_HI - 48 and a > 0 then
            a = -a
        end
        owner.ex_move_angle = a
        local deg = -math.deg(a)                        -- 我们坐标的角度（度）
        task.MoveTo(owner.x + 40 * cos(deg), owner.y + 40 * sin(deg), 40, VALUE_SET.DECEL)
    end

    ---Sub3：每 320 帧齐射 + 40 帧移动，一轮 360 帧。
    local function main_script(owner)
        task.New(owner, function()
            while true do
                local tok = { alive = true }
                sub6(owner, tok)
                task.Wait(320)
                tok.alive = false
                boundary_move(owner)
            end
        end)
    end

    ---──────────────────────── 符卡本体 ────────────────────────

    local card = boss.card.New(CARD_NAME, 1, 3, CARD_TIME, CARD_HP)

    function card:before()
    end

    function card:init()
        photo_damage_on(self, PHOTO_LIMIT)
        self.x, self.y = BOSS_X, BOSS_START_Y
        task.New(self, function()
            task.Wait(ENTRY_WAIT)
            task.MoveTo(HOME_X, HOME_Y, ENTRY_TIME, EASE_OUT)
            ---Sub2 的 t=130：亮卡名 + 起 Sub3。
            PlaySound("tan00", 0.1, self.x / 256, false)
            main_script(self)
        end)
    end

    function card:frame()
    end

    function card:del()
        photo_damage_off(self)
    end

    boss.card.add({ { card, "5a" } }, LEVEL, CARD_NAME, CARD_ID)
end--蓬莱「瑞江浦嶋子と五色の瑞亀」

do  -- 106 鬼気「濛々迷霧」（ecl25_a，萃香，组 6a 第 1 张）
    ---原作：萃香连续朝自机突进（每 60 帧一次、一次 120 px），沿途撒「雾滴」（几乎不动的小弹），
    ---并把 12 颗会**沿途加速**的大玉一圈圈甩出去。
    ---数据源 /tmp/E_ecl25_a.txt（ECL …/data/ecl25_a.ecl）。骨架：
    ---  · Sub2：ins_63(-128,-64) 进场 → t=100 ins_64(30,4,0,192) 落 (0,192)（我们的 (0,32)）；
    ---    ins_141(3) ⇒ 拍 3 张；t=130 亮卡名 + ins_52(3) 起 Sub3。**没有 ins_75**（不设活动框）。
    ---  · Sub3（主脚本）：
    ---      t=0 起 Sub5（装饰脉冲，子槽 7）；t=40 演出；
    ---      t=70 起 Sub4（子槽 0，发雾滴）+ ins_143 + extraIntV0=30；
    ---      然后 ins_5 循环 **30 次**：`66(60,1,playerAngle,2)` = 60 帧内朝自机走
    ---        speed×duration = 120 px（缓动 1 = 线性）。
    ---      循环退出后（@888，t=130）起 Sub6（子槽 1，每帧一声脉冲音）+ 再突进一次（@908）；
    ---      t=190（即 60 帧后）把 Sub4 **换成 Sub7**（ins_117(0,7) 删旧建新）并杀掉 Sub6；
    ---      t=370 / t=410 演出；t=440 重新起 Sub4 + extraIntV0=15，
    ---      再 ins_5 循环 15 次突进（900 帧）；
    ---      ins_4(130,-276) 跳回 **@888**（那一次突进），t=130 —— 这就是外层循环。
    ---      ⇒ 首轮 30 次突进（1800 帧）只为开场；此后一轮 = 1 次突进 + 60 + 180 + 40 + 30
    ---        + 15 次突进 = **1210 帧**。
    ---  · Sub4（子槽 0，每帧一轮）：eF0 = 64×randSigned、方向 rand(−π,π) ⇒ 出膛点落在
    ---    离本体 ≤64 px 的圆里；弹角又一次 rand(−π,π)，速 0.05、型 3 色 6（半径 2 → ball_small、蓝）。
    ---    ins_100(0,0) 收尾，ins_4(0,-136) 每帧跳回。flags 520 的出场滑动同差异 3。
    ---  · Sub7（子槽 0，每 60 帧一轮）：先 ins_101(0,16,0,120,-1,0.025,-999) 往变换槽 0 装一条
    ---    ACCEL_VECTOR；然后 ins_89(型 17、色 1、count1=12、count2=1、速 1）甩一圈 12 颗大玉
    ---    （半径 14 → ball_huge）。子弹 flags 536 = 0x218 命中这条变换 ⇒ 之后 120 帧里
    ---    每帧 speed += 0.025（BulletManager.cpp:803-815 的 UpdateVectorAcceleration），
    ---    方向取弹自己的 angle ⇒ 沿原方向一路加速（速 1 → 4）。
    ---  · Sub5/Sub6（子槽 7/1）只做 ANM 脉冲与音效 ⇒ 不实现（文件头差异 3）。
    local BOSS_X, BOSS_START_Y = -128, field_y(-64)
    local HOME_X, HOME_Y = 0, field_y(192)              -- 0 / 32
    local ENTRY_WAIT, ENTRY_TIME = 100, 30
    local EASE_OUT = VALUE_SET.DECEL

    local PHOTO_LIMIT = 3                               -- ins_141(3)
    local CARD_NAME = "鬼気「濛々迷霧」"
    ---原作卡计时 ins_114(12608)；沿用本仓库的 50 秒。
    local CARD_TIME = 50
    local CARD_HP = 900
    local CARD_ID = 459

    ---──────────────────────── 弹幕 ────────────────────────

    local SUB3_LEAD = 70                                -- Sub3 t=0 → t=70 才起 Sub4 / 第一次突进
    local DASH_FRAMES, DASH_SPEED = 60, 2               -- ins_66(60,1,pa,2) ⇒ 120 px
    local MIST_R, MIST_SPEED = 64, 0.05                 -- Sub4：偏移半径 / 弹速
    local MIST_STYLE, MIST_COLOR = ball_small, ex_color(6)
    local BIG_STYLE, BIG_COLOR = ball_huge, ex_color(1)
    local BIG_COUNT, BIG_SPEED = 12, 1                  -- Sub7 的 ins_89
    local BIG_GAP = 60                                  -- Sub7 的 ins_4(0,-80)
    local ACCEL_STEP, ACCEL_FRAMES = 0.025, 120         -- ins_101 的 f0 / int0

    ---Sub4：每帧一颗雾滴（出膛点随机、方向随机、几乎不动）。
    local function sub4(owner, tok)
        task.New(owner, function()
            while tok.alive do
                local m = ran:Float(-MIST_R, MIST_R)
                local th = ran:Float(-math.pi, math.pi)
                local ba = ran:Float(-math.pi, math.pi)
                NewSimpleBullet(MIST_STYLE, MIST_COLOR,
                        owner.x + m * math.cos(th), owner.y - m * math.sin(th),
                        MIST_SPEED, -math.deg(ba), false, 0, false)
                task.Wait(1)
            end
        end)
    end

    ---Sub7 的子弹加速：前 120 帧每帧 +0.025（沿弹自己的 angle）。
    local function big_accel_frame(self)
        local n = self.ex_accel or 0
        if n < ACCEL_FRAMES then
            self.ex_accel = n + 1
            local v = (self.ex_vel or BIG_SPEED) + ACCEL_STEP
            self.ex_vel = v
            object.SetV(self, v, self.rot, true)
        end
    end

    ---Sub7：每 60 帧一圈 12 颗加速大玉（基角 rand(−π,π) ⇒ 30° 网格的随机朝向）。
    local function sub7(owner, tok)
        task.New(owner, function()
            while tok.alive do
                local base = ran:Float(0, 360)
                for i = 0, BIG_COUNT - 1 do
                    NewSimpleBullet(BIG_STYLE, BIG_COLOR, owner.x, owner.y, BIG_SPEED,
                            base + i * 360 / BIG_COUNT, false, 0, false,
                            nil, nil, nil, big_accel_frame)
                end
                PlaySound("tan00", 0.1, owner.x / 256, false)
                task.Wait(BIG_GAP)
            end
        end)
    end

    ---一次突进：60 帧、直线 120 px、朝当时的自机角。
    local function dash(owner)
        local a = Angle(owner.x, owner.y, player.x, player.y)
        task.MoveTo(owner.x + DASH_FRAMES * DASH_SPEED * cos(a),
                owner.y + DASH_FRAMES * DASH_SPEED * sin(a), DASH_FRAMES, VALUE_SET.NORMAL)
    end

    ---Sub3：首轮 30 次突进；之后进入 1210 帧的外层循环。
    local tok4, tok7
    local function main_script(owner)
        task.New(owner, function()
            ---Sub3 自己的时间轴：t=0 起 Sub5（装饰）、t=40 演出、t=70 才起 Sub4 与第一次突进。
            task.Wait(SUB3_LEAD)
            tok4 = { alive = true }
            sub4(owner, tok4)
            for _ = 1, 30 do
                dash(owner)
            end
            while true do
                dash(owner)                             -- @908：循环开头那次突进（60 帧）
                ---@948：Sub4 换成 Sub7（在突进结束的同一刻）。
                tok4.alive = false
                tok7 = { alive = true }
                sub7(owner, tok7)
                ---t=190 → t=440：180 + 40 + 30 帧的空档。
                task.Wait(250)
                ---@1060/@1080：Sub4 重新起、Sub7 收掉，然后是 15 次突进。
                tok7.alive = false
                tok4 = { alive = true }
                sub4(owner, tok4)
                for _ = 1, 15 do
                    dash(owner)
                end
            end
        end)
    end

    ---──────────────────────── 符卡本体 ────────────────────────

    local card = boss.card.New(CARD_NAME, 1, 3, CARD_TIME, CARD_HP)

    function card:before()
    end

    function card:init()
        photo_damage_on(self, PHOTO_LIMIT)
        self.x, self.y = BOSS_X, BOSS_START_Y
        task.New(self, function()
            task.Wait(ENTRY_WAIT)
            task.MoveTo(HOME_X, HOME_Y, ENTRY_TIME, EASE_OUT)
            ---Sub2 的 t=130：亮卡名 + 起 Sub3。
            PlaySound("tan00", 0.1, self.x / 256, false)
            main_script(self)
        end)
    end

    function card:frame()
    end

    function card:del()
        photo_damage_off(self)
        if tok4 then tok4.alive = false end
        if tok7 then tok7.alive = false end
    end

    boss.card.add({ { card, "6a" } }, LEVEL, CARD_NAME, CARD_ID)
end--鬼気「濛々迷霧」

do  -- 107 「百万鬼夜行」（ecl25_b，萃香，组 6a 第 2 张）
    ---原作：本体每隔 120 帧躲一次（拍中 2 张以上才躲），同时六条子上下文按**拍照进度**
    ---逐条解锁的弹幕（拍得越多越密）。
    ---数据源 /tmp/E_ecl25_b.txt（ECL …/data/ecl25_b.ecl）。骨架：
    ---  · Sub2：ins_63(-128,-64) 进场 → t=100 ins_64(30,4,0,192) 落 (0,192)（我们的 (0,32)）；
    ---    ins_141(10) ⇒ 拍 10 张；t=130 亮卡名 + ins_75(-140,128,140,192)
    ---    （我们的活动框 x∈[-140,140]、y∈[32,96]）+ ins_52(3) 起 Sub3。
    ---  · Sub3：t=0 起 Sub11（每帧一声脉冲音，装饰）；t=60 起 Sub4..Sub9（六条发弹上下文，
    ---    只起这一次、之后一直跑）；t=60 的 `ins_44(photoIndex,2,60,52)` 是 **CMPlt**：
    ---    photoIndex < 2 就跳过这一轮的 ins_67(60,4,0.8)；ins_4(60,-228) 每 120 帧跳回
    ---    那句 ins_44（t=60）。⇒ 一轮 120 帧、只有「拍中 ≥2 张」才会躲
    ---    （ins_67 的 60 帧走位就占这一轮的头 60 帧，task.MoveTo 是阻塞的）。
    ---  · Sub4（每 24 帧一轮）：**没有闸**，一上来就发（@1012 之后直接是 @1032 的随机半径，
    ---    全段没有 ins_44）；每轮 6 次「随机出膛点（半径 16×rand）+ ins_89(型 19、色 3、
    ---    count1=3、count2=1、速 1)」= 18 发；收尾 floatV0 += 18°（跳回点是 @1032、
    ---    **跳过**开头的 ins_7 rand ⇒ 基角持续累加）。
    ---  · Sub7 同构，只是色 1、速 2；**它有闸**（@2048 的 `ins_44(photoIndex,6,0,744)`）——
    ---    跳转目标 @2792 正是收尾的 `ins_15(floatV0, 0.314159)`，所以 photoIndex < 6 时
    ---    整轮发弹被跳过、但 18° 照样累加。
    ---  · Sub6（每 20 帧）：ins_91 = OFFSET_CIRCLE、型 3、色 6、count1=32、速 2。
    ---  · Sub8（t=10 起每 20 帧）：`ins_44(photoIndex,4,…)` 闸 ⇒ photoIndex ≥ 4 才有
    ---    ins_91（型 3、色 2、速 2、32 发）。
    ---  · Sub9（t=120 起每 20 帧）：`ins_44(photoIndex,8,…)` 闸 ⇒ photoIndex ≥ 8 才有
    ---    ins_88 = CIRCLE_AIMED（型 19、色 1、速 2、32 发）。
    ---  · Sub5（t=90 起每 60 帧）：ins_88 = CIRCLE_AIMED（型 12、色 3、速 1、32 发）。
    ---  · 32 发的整圈（360/32 = 11.25°）在取反后**方向集合不变**；OFFSET_CIRCLE 多出的
    ---    π/count1 = 5.625° 相位也正好落在同一网格上（−5.625 ≡ 5.625 + 11.25×31）。
    ---  · 弹型：12（半径 5）→ ball_mid；3/19（半径 2/3）→ ball_small。
    ---  · Sub10/Sub11 的 150(17)/150(18) 是 ANM 脉冲 ⇒ 不实现（文件头差异 3）。
    local BOSS_X, BOSS_START_Y = -128, field_y(-64)
    local HOME_X, HOME_Y = 0, field_y(192)              -- 0 / 32
    local ENTRY_WAIT, ENTRY_TIME = 100, 30
    local EASE_OUT = VALUE_SET.DECEL

    local BOX_L, BOX_R = -140, 140                      -- ins_75 的 x 范围
    local BOX_LO, BOX_HI = 128, 192                     -- ins_75 的 y 范围（TH095）

    local PHOTO_LIMIT = 10                              -- ins_141(10)
    local CARD_NAME = "「百万鬼夜行」"
    ---原作卡计时 ins_114(12008)；沿用本仓库的 50 秒。
    local CARD_TIME = 50
    local CARD_HP = 900
    local CARD_ID = 460

    ---──────────────────────── 弹幕 ────────────────────────

    local MOVE_GAP = 120                                -- Sub3 的 ins_4(60,-228)
    local MOVE_MIN_PHOTOS = 2                           -- ins_44(photoIndex, 2)
    local MOVE_FRAMES, MOVE_SPEED = 60, 0.8             -- ins_67(60,4,0.8) ⇒ 48 px

    local BURST_N = 6                                   -- Sub4/Sub7 每轮的出膛点数
    local BURST_R = 16                                  -- eF0 = 16 × randF32
    local BURST_GAP = 24                                -- Sub4/Sub7 的 ins_4(0,-xxx)
    local BURST_STEP = 18                               -- 收尾 floatV0 += 0.314159（18°）
    local DENSITY_A = 6                                 -- ins_44(photoIndex, 6)：Sub4/Sub7
    local DENSITY_B = 4                                 -- ins_44(photoIndex, 4)：Sub8
    local DENSITY_C = 8                                 -- ins_44(photoIndex, 8)：Sub9

    local RING_N = 32                                   -- ins_88/91 的 count1
    local RING_STEP = 360 / RING_N                      -- 11.25°
    local OFFSET_PHASE = 180 / RING_N                   -- OFFSET_CIRCLE 的 π/count1

    ---一次 ins_89「count1=3、count2=1」：3 发 120° 等分环。
    local function fire_three(style, color, speed, x, y, base_deg)
        for i = 0, 2 do
            NewSimpleBullet(style, color, x, y, speed, base_deg - 120 * i, false, 0, false)
        end
    end

    ---Sub4 / Sub7：每 24 帧一轮，6 个随机出膛点各甩一个 3 发环。
    ---gate = nil ⇒ 无闸（Sub4），否则 photoIndex ≥ gate 才发（Sub7 = 6）。
    local function burst_stream(owner, tok, style, color, speed, gate)
        task.New(owner, function()
            local fv0 = ran:Float(-math.pi, math.pi)    -- 只在最开始抽一次
            while tok.alive do
                if not gate or photo_index(PHOTO_LIMIT) >= gate then
                    local b = -math.deg(fv0)
                    for _ = 1, BURST_N do
                        local m = ran:Float(0, BURST_R)
                        local th = ran:Float(-math.pi, math.pi)
                        fire_three(style, color, speed,
                                owner.x + m * math.cos(th), owner.y - m * math.sin(th), b)
                    end
                end
                fv0 = fv0 + math.rad(BURST_STEP)
                task.Wait(BURST_GAP)
            end
        end)
    end

    ---ins_88/91 的 32 发整圈：aimed = true 走 CIRCLE_AIMED（基角 = 自机角），
    ---false 走 OFFSET_CIRCLE（多 5.625° 相位）。
    local function ring_stream(owner, tok, style, color, speed, gap, first, aimed, gate)
        task.New(owner, function()
            if first > 0 then
                task.Wait(first)
            end
            while tok.alive do
                if not gate or photo_index(PHOTO_LIMIT) >= gate then
                    local base = aimed and Angle(owner.x, owner.y, player.x, player.y) or 0
                    for i = 0, RING_N - 1 do
                        local ph = aimed and 0 or OFFSET_PHASE
                        NewSimpleBullet(style, color, owner.x, owner.y, speed,
                                base + ph + i * RING_STEP, false, 0, false)
                    end
                    PlaySound("tan00", 0.1, owner.x / 256, false)
                end
                task.Wait(gap)
            end
        end)
    end

    ---ins_67(60,4,0.8) = BeginBoundaryAwareMove（EclDependencies.cpp:108）：
    ---先挑「背离自机」的随机方向（TH095 弧度），再按活动框边界修正，60 帧走 48 px、缓动 4。
    local function boundary_move(owner)
        local a
        if player.x < owner.x then
            a = ran:Float(0, math.pi / 2) + 3 * math.pi / 4
        else
            a = ran:Float(0, math.pi / 2) - math.pi / 4
        end
        ---原代码在 x 右边界那一条里用的是 enemy->movementAngle（不是 angle）——照抄。
        local ma = owner.ex_move_angle or 0
        if owner.x < BOX_L + 96 then
            if a > math.pi / 2 then
                a = math.pi - a
            elseif a < -math.pi / 2 then
                a = -math.pi - a
            end
        end
        if owner.x > BOX_R - 96 then
            if a < math.pi / 2 and a >= 0 then
                a = math.pi - ma
            elseif a > -math.pi / 2 and a <= 0 then
                a = -math.pi - a
            end
        end
        local yth = field_y(owner.y)
        if yth < BOX_LO + 48 and a < 0 then
            a = -a
        end
        if yth > BOX_HI - 48 and a > 0 then
            a = -a
        end
        owner.ex_move_angle = a
        local deg = -math.deg(a)
        task.MoveTo(owner.x + MOVE_FRAMES * MOVE_SPEED * cos(deg),
                owner.y + MOVE_FRAMES * MOVE_SPEED * sin(deg), MOVE_FRAMES, VALUE_SET.DECEL)
    end

    ---Sub3：起六条上下文；每 120 帧按拍照进度躲一次。
    local toks = {}
    local function main_script(owner)
        task.New(owner, function()
            ---t=60：Sub4..Sub9。
            ---Sub4 **没有闸**（它的 @1032 之后没有 ins_44）⇒ 一直发，不传 gate。
            toks[1] = { alive = true }; burst_stream(owner, toks[1], ball_small, ex_color(3), 1, nil)
            toks[2] = { alive = true }; ring_stream(owner, toks[2], ball_mid, ex_color(3), 1, 60, 90, true, nil)
            toks[3] = { alive = true }; ring_stream(owner, toks[3], ball_small, ex_color(6), 2, 20, 0, false, nil)
            toks[4] = { alive = true }; burst_stream(owner, toks[4], ball_small, ex_color(1), 2, DENSITY_A)
            toks[5] = { alive = true }; ring_stream(owner, toks[5], ball_small, ex_color(2), 2, 20, 10, false, DENSITY_B)
            toks[6] = { alive = true }; ring_stream(owner, toks[6], ball_small, ex_color(1), 2, 20, 120, true, DENSITY_C)
            while true do
                if photo_index(PHOTO_LIMIT) >= MOVE_MIN_PHOTOS then
                    ---ins_67 的移动占一轮的头 60 帧（ins_4 在 t=180 才跳回）。
                    boundary_move(owner)
                    task.Wait(MOVE_GAP / 2)
                else
                    task.Wait(MOVE_GAP)
                end
            end
        end)
    end

    ---──────────────────────── 符卡本体 ────────────────────────

    local card = boss.card.New(CARD_NAME, 1, 3, CARD_TIME, CARD_HP)

    function card:before()
    end

    function card:init()
        photo_damage_on(self, PHOTO_LIMIT)
        self.x, self.y = BOSS_X, BOSS_START_Y
        task.New(self, function()
            task.Wait(ENTRY_WAIT)
            task.MoveTo(HOME_X, HOME_Y, ENTRY_TIME, EASE_OUT)
            ---Sub2 的 t=130：亮卡名 + 起 Sub3。
            PlaySound("tan00", 0.1, self.x / 256, false)
            main_script(self)
        end)
    end

    function card:frame()
    end

    function card:del()
        photo_damage_off(self)
        for i = 1, #toks do
            toks[i].alive = false
        end
    end

    boss.card.add({ { card, "6a" } }, LEVEL, CARD_NAME, CARD_ID)
end--「百万鬼夜行」
---──────────────────── Stage 9（scene group 9 = world10）── 公共工具 ────────────────────
---下面八张卡（scene 90..97）共用 world10（三途の川 / 彼岸）与 enm20/21.anm。
---数据源是 /tmp/S9_ecl20_{a..d}.txt 与 /tmp/S9_ecl21_{a..d}.txt（脚本 /tmp/d95v3.py 反汇编；
---ECL 在 `[th095] …/data/ecl2{0,1}_*.ecl`），各卡注释里的「@地址」都指这几份 dump。
---色表 ex_color / ins_145/147 的激光工具见上面「Stage EX」那一段（同一套）。

---ins_86..94 的一发。th_deg 是 TH095 空间的**度**（顺时针为正、y 朝下）；
---本仓库的角度 = −th_deg（见文件头「坐标系与角度」）。
local function sg_bullet(style, color, x, y, speed, th_deg, frame)
    NewSimpleBullet(style, color, x, y, speed, -th_deg, false, 0, false,
            nil, nil, nil, frame)
end

---自机在 TH095 空间的角度（度）：本仓库 Angle 返回我们的角度（度、逆时针为正）⇒ 取反。
local function sg_aim(x, y)
    return -Angle(x, y, player.x, player.y)
end

---TH095 的弹型 → 本仓库贴图。碰撞直径见 g_PhotoBulletCollisionSizes
---（th095/src/BulletManager.cpp:113-133）：1/3/7/18/23 = 6、4/12 = 10、14/15/16 = 8、
---17 = 28。既有卡的映射是 6→ball_small（半径 2）、10→ball_mid、28→ball_huge；
---直径 8 的 14/15/16 夹在中间，按「观感更接近中玉」一律给 ball_mid（Stage 7 大量用它）。
local function sg_style(t)
    if t == 17 then return ball_huge end
    if t == 1 or t == 3 or t == 7 or t == 18 or t == 23 then return ball_small end
    return ball_mid
end

---flags 的 0x200 = PLAY_SPAWN_SOUND：整条 ins_86..94 响一次（BulletManager.cpp:717-723）。
local function sg_snd(x, flags)
    if flags and math.floor(flags / 0x200) % 2 == 1 then
        PlaySound("tan00", 0.1, x / 256, false)
    end
end

---ins_86..94 的统一出口（SpawnBulletPattern / SpawnSingleBullet，BulletManager.cpp:340-405）。
---mode：86 FAN_AIMED / 87 FAN / 88 CIRCLE_AIMED / 89 CIRCLE / 90 OFFSET_CIRCLE_AIMED /
---      91 OFFSET_CIRCLE / 92 RANDOM_ANGLE / 93 RANDOM_SPEED / 94 RANDOM。
---base / step 都是 TH095 空间的度；aim = true 时把自机角加进去（86/88/90 用）。
---frame（可选）是逐帧钩子，直接透传给 NewSimpleBullet 的第 13 个参数
---（Stage 8 的 ins_101 弹变换就是这么挂上去的，见下面的 sg_tr_hook）。
---速度：count2 > 1 时 sp1 − (sp1−sp2)·index2/count2，否则 sp1（同文件:340-346）。
local function sg_shot(mode, style, color, x, y, c1, c2, sp1, sp2, base, step, aim, flags, frame)
    local ad = aim and sg_aim(x, y) or 0
    local off
    if mode == 86 or mode == 87 then
        off = ex_fan_offsets(c1, step)
    end
    for i2 = 0, c2 - 1 do
        local sp = c2 > 1 and (sp1 - (sp1 - sp2) * i2 / c2) or sp1
        for i1 = 0, c1 - 1 do
            local a
            if mode == 86 or mode == 87 then
                a = ad + base + off[i1 + 1]
            elseif mode == 88 or mode == 89 then
                a = ad + base + i1 * 360 / c1 + i2 * step
            elseif mode == 90 or mode == 91 then
                a = ad + 180 / c1 + base + i1 * 360 / c1
            elseif mode == 92 then
                a = step + ran:Float(0, 1) * (base - step)
            elseif mode == 93 then
                a = ad + base + i2 * step
                sp = sp2 + ran:Float(0, 1) * (sp1 - sp2)
            else
                a = step + ran:Float(0, 1) * (base - step)
                sp = sp2 + ran:Float(0, 1) * (sp1 - sp2)
            end
            sg_bullet(style, color, x, y, sp, a, frame)
        end
    end
    sg_snd(x, flags)
end

---原作的 easing 编号 1..6（EnemyMovement.cpp:112-126）：
---  1 = n²、2 = n³、3 = n⁴、4 = 1−(1−n)²、5 = 1−(1−n)³、6 = 1−(1−n)⁴。
---本仓库 task.MoveTo 的 mode 允许直接给函数（Ltask.lua:163 的 __index）⇒ 原样构造，
---对 ins_64/66/67 的缓动就与原作逐帧一致（原作 progress = 1 − timer/duration = s/n）。
local function sg_ease(k)
    if k == 1 then return function(n) return n * n end end
    if k == 2 then return function(n) return n * n * n end end
    if k == 3 then return function(n) return n * n * n * n end end
    if k == 4 then return function(n) return 1 - (1 - n) * (1 - n) end end
    if k == 5 then
        return function(n) local m = 1 - n; return 1 - m * m * m end
    end
    if k == 6 then
        return function(n) local m = 1 - n; return 1 - m * m * m * m end
    end
    return function(n) return n end
end

---非阻塞的插值移动（ins_64/66/67 都是逐帧积分、不阻塞 ECL）。同一时间只留一条，
---新的会打断旧的（原作里 movementMode = 2 会被后一条指令整个覆盖）。
local function sg_move(owner, st, tx, ty, n, easing)
    if st.mv then st.mv.alive = false end
    local t = { alive = true }
    st.mv = t
    local x0, y0 = owner.x, owner.y
    local dx, dy = tx - x0, ty - y0
    local f = sg_ease(easing)
    task.New(owner, function()
        for s = 1, n do
            if not t.alive or st.dead then return end
            local p = f(s / n)
            owner.x, owner.y = x0 + p * dx, y0 + p * dy
            task.Wait(1)
        end
    end)
end

---ins_67（BeginBoundaryAwareMove，EclDependencies.cpp:108-158）：先按自机位置随机取一个
---「背离自机」的方向，再按活动框（ins_75）反射，最后插值移动 speed×n px。
---TH095 是 y 朝下、顺时针为正 ⇒ 方向在 TH095 空间算完后再交给 sg_move（它按我们的
---坐标取目标点）。box = { x0, y0, x1, y1 }（TH095 坐标，y0 < y1 表示 y0 在上方）。
local function sg_bmove(owner, st, n, easing, speed, box)
    local x = owner.x
    local y = FIELD_HALF_H - owner.y                 -- 本体位置的 TH095 y
    local a
    if player.x < x then
        a = ran:Float(0, math.pi / 2) + 2.3561945     -- rand[0,π/2) + 3π/4
    else
        a = ran:Float(0, math.pi / 2) - 0.78539819    -- rand[0,π/2) − π/4
    end
    if x < box[1] + 96 then
        if a > 1.5707964 then a = 3.1415927 - a
        elseif a < -1.5707964 then a = -3.1415927 - a end
    end
    if x > box[3] - 96 then
        ---★ 原作右边界这一支用的是**上一次的** movementAngle（不是刚算出的 angle）——
        ---EclDependencies.cpp:139 的 `3.1415927 - enemy->movementAngle`。照抄。
        if a < 1.5707964 and a >= 0 then a = 3.1415927 - (st.mv_angle or a)
        elseif a > -1.5707964 and a <= 0 then a = -3.1415927 - a end
    end
    if y < box[2] + 48 and a < 0 then a = -a end
    if y > box[4] - 48 and a > 0 then a = -a end
    st.mv_angle = a
    local d = speed * n
    sg_move(owner, st, x + d * math.cos(a), owner.y - d * math.sin(a), max(1, n), easing)
end

---ins_145 直线激光（PhotoStraightLaserView::Update，PhotoEffect.cpp:208-230）：
---从长度 0 起、每帧 +speed 长到 max_len；长满后每帧沿自己的方向前进 speed。
---初始化时 state 直接是 ACTIVE、宽度恒定（同文件:290-325），所以没有 147 的四段。
---★ 原作 145 的判定还多一道 width > 40 的闸（同文件:252 的 `length > 16 && width > 40`）；
---  world10 的 145 全是 width 16 —— 照搬的话这些激光一颗都打不到自机、这张符卡只剩背景。
---  本仓库的激光本来就是独立判定对象（见上面 run_ex_laser 的口径），这里让 145 和 147
---  一样在 length > 16 时判定。这是本卡组唯一一处对原作的刻意偏离，记在各卡注释里。
local function run_ex_laser_straight(owner, l, max_len, width, speed)
    ---★ 旧写法漏了这一步：laser:init 把 self.w 置 0、只有 counter > 0 时才长宽，
    ---  于是 145 生成的激光**宽度恒为 0** —— 既不显示也不判定（laser.lua:52 与 :76）。
    ---  这里按 ins_145 的 width 直接给上（w0/w 一起写，收尾的淡出才除得动）。
    l.w0, l.w = width, width
    task.New(owner, function()
        local len, full = 0, false
        while IsValid(l) do
            if not full then
                len = min(max_len, len + speed)
                full = len >= max_len
            else
                l.x = l.x + speed * cos(l.rot)
                l.y = l.y + speed * sin(l.rot)
            end
            l.colli = len > 16
            l.l1, l.l2, l.l3 = 0, len, 0
            l.alpha = 1
            task.Wait()
        end
        if IsValid(l) then
            object.RawDel(l)
        end
    end)
end

---生成一根 ins_145 直线激光。
local function spawn_ex_laser_straight(owner, lasers, index, x, y, angle, max_len, width, speed)
    local l = New(laser, index, x, y, angle, 0, 0, 0, 0, 0, 0)
    l.colli = false
    lasers[#lasers + 1] = l
    run_ex_laser_straight(owner, l, max_len, width, speed)
    return l
end

---ins_102（清屏）：DespawnAllBullets + 清掉本卡自己放出的激光（EclRunTargetHigh.inl:470）。
local function sg_clear(lasers)
    object.BulletDo(function(b) object.RawDel(b) end)
    for i = #lasers, 1, -1 do
        if IsValid(lasers[i]) then
            object.RawDel(lasers[i])
        end
        lasers[i] = nil
    end
end



do  -- 90 小町 非符（ecl20_a，组 7a 第 1 张）
    ---原作这一关的第 1 幕**没有** ins_104（不亮卡名），是一个「前哨」：小町在活动框里
    ---随机游走，一边撒两组对称扇（Sub4）；拍到第 3 张后换成更密的整圈（Sub7），
    ---拍到第 6 张后再换成「只游走、不再放弹」（Sub8）。
    ---数据源 /tmp/S9_ecl20_a.txt（ECL …/data/ecl20_a.ecl）。骨架：
    ---  · Sub2：ins_63(-128,-64) 进场 → t=100 ins_64(30,4,0,128) 用 30 帧落到 (0,128)
    ---    （我们的 (0,96)）；ins_141(8) ⇒ 拍 8 张；t=130 的 `id=0`（**不是** ins_104 ——
    ---    它把当前 ANM 脚本停掉）+ ins_75(-140,128,140,192) 设活动框 + ins_149(4.5)
    ---    + ins_132(1) + ins_52(3) 起主脚本。t=0 的两条 ins_115 见下面「按张切换」。
    ---  · Sub3（默认主控，300 帧一轮）：t=0 起 Sub5（装饰）→ t=60 换成 Sub4（发弹）→
    ---    t=180 ins_67(120,4,0.5)：沿「背离自机」的随机方向插值 60 px（120 帧、缓动 4）→
    ---    t=240 收掉 Sub4 → t=300 跳回 t=0。
    ---  · Sub4：两段各 24 帧的连发扇，每帧发两组 ins_87 FAN(type 23 → ball_small，
    ---    count1 = 4 / 3、速 = floatV0、基角 = floatV1、步长 0.392699)。floatV0 每帧 +0.2、
    ---    floatV1 每帧 −0.0448799 rad；第二段（t=31）把两个初值重置（各取当时的 playerAngle）。
    ---  · Sub6（拍中第 3 张起接管主脚本）：ins_102 清屏 → 起 Sub5 → t=60 换成 Sub7 →
    ---    t=180 再一次 ins_67(60,4,1.5) → t=240 收掉 Sub7 → 跳回 t=0（240 帧一轮）。
    ---  · Sub7（真发弹，302 帧一轮）：floatV0 = 0.5、floatV1 = playerAngle、
    ---    intV0 = photoIndex − 2；两段各 24 帧的连发整圈 ins_89 CIRCLE(type 23、色 0/1、
    ---    count1 = 8、count2 = intV0、速 = floatV0、基角 floatV1、步长 0.392699)。
    ---    floatV0 每帧 +0.15；floatV1 第一段每帧 +0.0981748、第二段 −0.0981748（反着转）。
    ---    **count2 = photoIndex − 2 ⇒ 拍不够 3 张时一发都不发**（0 / 负数 = 空循环）。
    ---  · Sub8（拍中第 6 张起）：ins_102 清屏 → 起 Sub5 → t=60 换成 Sub9 →
    ---    此后每 120 帧一次 ins_67(120,4,0.5) 的随机游走。
    ---  · Sub9：每帧把出膛点挪到离本体 ≤32 px 的随机点，再发 3 组 ins_89 CIRCLE
    ---    (type 23、色 0/1/2、count1 = 2、速 = 0.8 + rand×1.2、基角 rand(−π,π))。
    ---  · Sub5（装饰）与 Sub0/Sub1（死亡/退场）不实现（文件头差异 3/5）。
    ---★ 原作 ins_115(slot, frame, sub) 的 frame 比的是 camera.photoIndex
    ---  （EnemyManagerUpdate.cpp:1280-1330 的 UpdateScheduledEclCalls；g_PhotoEnemyGame->
    ---  frameCounter 就在 player 的 camera.photoIndex 偏移 0x29E4 上）。本仓库用「拍中本体
    ---  的张数」（photo_hits）来替代，所以这里是「拍中第 k 张时把主脚本换成 sub」。
    local BOSS_X, BOSS_START_Y = -128, field_y(-64)
    local HOME_X, HOME_Y = 0, field_y(128)              -- 0 / 96
    local ENTRY_WAIT, ENTRY_TIME = 100, 30
    local EASE_OUT = VALUE_SET.DECEL

    local PHOTO_LIMIT = 8                               -- ins_141(8)
    local CARD_NAME = ""                                -- 非符：原作没有 ins_104
    local CARD_TIME, CARD_HP = 50, 900
    local CARD_ID = 470

    local BOX = { -140, 128, 140, 192 }                 -- ins_75 的活动框（TH095 空间）

    ---Sub4（ins_87 FAN）：{ count1, 原作色号 }。
    local FAN_SEG = 24
    local FAN_SPEED0, FAN_SPEED_STEP = 0.5, 0.2
    local FAN_STEP_DEG = 22.5                           -- 0.392699 rad
    local FAN_SPIN = 0.0448799                          -- floatV1 每帧的增量（rad）
    local FAN_GROUP = { { 4, 0 }, { 3, 1 } }
    ---Sub7（ins_89 CIRCLE）。
    local RING_SEG = 24
    local RING_COUNT = 8
    local RING_SPEED0, RING_SPEED_STEP = 0.5, 0.15
    local RING_SPIN = 0.0981748                         -- rad/帧
    ---Sub9（ins_89 CIRCLE，随机点随机角）。
    local SPRAY_R = 32
    local SPRAY_SPEED0, SPRAY_SPEED1 = 0.8, 1.2

    local lasers = {}
    local st = { dead = false }
    local gen = 0                                       -- 当前主脚本代号（ins_115 会 +1）
    local fired = { false, false }

    local function alive(g, sub)
        return g == gen and not st.dead and (sub == nil or sub.alive)
    end

    ---Sub4：两段各 24 帧的连发扇（每帧两组）。
    local function sub4(owner, g, tok)
        task.New(owner, function()
            while alive(g, tok) do
                for _ = 0, 1 do
                    local sp = FAN_SPEED0
                    local ang = -math.rad(Angle(owner.x, owner.y, player.x, player.y))
                    for _ = 1, FAN_SEG do
                        if not alive(g, tok) then return end
                        for k = 1, #FAN_GROUP do
                            sg_shot(87, ball_small, ex_color(FAN_GROUP[k][2]),
                                    owner.x, owner.y, FAN_GROUP[k][1], 1, sp, 1.5,
                                    math.deg(ang), FAN_STEP_DEG, false, 514)
                        end
                        sp = sp + FAN_SPEED_STEP
                        ang = ang + FAN_SPIN
                        task.Wait(1)
                    end
                    task.Wait(7)                        -- t=24 → t=31（或 t=55 → t=62）
                end
            end
        end)
    end

    ---Sub7：两段各 24 帧、每帧一圈（count2 = photoIndex − 2）。
    local function sub7(owner, g, tok)
        task.New(owner, function()
            while alive(g, tok) do
                local n2 = photo_index(PHOTO_LIMIT) - 2
                for pass = 0, 1 do
                    local sp = RING_SPEED0
                    local ang = -math.rad(Angle(owner.x, owner.y, player.x, player.y))
                    for _ = 1, RING_SEG do
                        if not alive(g, tok) then return end
                        sg_shot(89, ball_small, ex_color(pass), owner.x, owner.y,
                                RING_COUNT, n2, sp, 0.5, math.deg(ang), 22.5, false, 514)
                        sp = sp + RING_SPEED_STEP
                        ang = ang + (pass == 0 and RING_SPIN or -RING_SPIN)
                        task.Wait(1)
                    end
                end
                task.Wait(254)                          -- 一轮 302 帧（前 48 帧在发弹）
            end
        end)
    end

    ---Sub9：每帧一组随机点 + 3 组整圈。
    local function sub9(owner, g, tok)
        task.New(owner, function()
            while alive(g, tok) do
                local r = ran:Float(0, 1) * SPRAY_R
                local a = ran:Float(-math.pi, math.pi)
                local ox, oy = math.cos(a) * r, -math.sin(a) * r
                for c = 0, 2 do
                    local sp = SPRAY_SPEED0 + ran:Float(0, 1) * SPRAY_SPEED1
                    local base = math.deg(ran:Float(-math.pi, math.pi))
                    sg_shot(89, ball_small, ex_color(c), owner.x + ox, owner.y + oy,
                            2, 1, sp, 0.5, base, 22.5, false, 514)
                end
                task.Wait(1)
            end
        end)
    end

    ---Sub3：默认主控（300 帧一轮）。
    local function run_default(owner)
        local g = gen
        task.New(owner, function()
            while alive(g) do
                local tok = { alive = true }
                task.Wait(60)                           -- t=0..59（Sub5 装饰期）
                if not alive(g) then return end
                sub4(owner, g, tok)                     -- t=60
                task.Wait(120)                          -- t=60..179
                if alive(g) then
                    sg_bmove(owner, st, 120, 4, 0.5, BOX)   -- t=180（120 帧、60 px）
                end
                task.Wait(60)                           -- t=180..239
                tok.alive = false                       -- t=240
                task.Wait(60)                           -- t=240..299
            end
        end)
    end

    ---Sub6：拍中第 3 张起的循环（240 帧一轮，含一次清屏）。
    local function run_b(owner)
        local g = gen
        task.New(owner, function()
            sg_clear(lasers)
            while alive(g) do
                local tok = { alive = true }
                task.Wait(60)
                if not alive(g) then return end
                sub7(owner, g, tok)
                task.Wait(120)
                if alive(g) then
                    sg_bmove(owner, st, 60, 4, 1.5, BOX)
                end
                task.Wait(60)
                tok.alive = false
            end
        end)
    end

    ---Sub8：拍中第 6 张起（清屏一次，然后只游走）。
    local function run_c(owner)
        local g = gen
        task.New(owner, function()
            sg_clear(lasers)
            local tok = { alive = true }
            task.Wait(60)
            if not alive(g) then return end
            sub9(owner, g, tok)
            task.Wait(120)
            while alive(g) do
                sg_bmove(owner, st, 120, 4, 0.5, BOX)
                task.Wait(120)
            end
        end)
    end

    ---ins_115 的「拍中第 k 张」监视器。
    local function watcher(owner)
        task.New(owner, function()
            while not st.dead do
                local hits = photo_index(PHOTO_LIMIT)
                if hits >= 3 and not fired[1] then
                    fired[1] = true
                    gen = gen + 1
                    run_b(owner)
                elseif hits >= 6 and not fired[2] then
                    fired[2] = true
                    gen = gen + 1
                    run_c(owner)
                end
                task.Wait(1)
            end
        end)
    end

    local card = boss.card.New(CARD_NAME, 1, 3, CARD_TIME, CARD_HP)

    function card:before()
    end

    function card:init()
        photo_damage_on(self, PHOTO_LIMIT)
        self.x, self.y = BOSS_X, BOSS_START_Y
        gen = gen + 1
        task.New(self, function()
            task.Wait(ENTRY_WAIT)
            task.MoveTo(HOME_X, HOME_Y, ENTRY_TIME, EASE_OUT)
            run_default(self)                           -- Sub3
            watcher(self)
        end)
    end

    function card:frame()
    end

    function card:del()
        st.dead = true
        photo_damage_off(self)
        sg_clear(lasers)
    end

    boss.card.add({ { card, "7a" } }, LEVEL, CARD_NAME, CARD_ID)
end--小町 非符（ecl20_a）

do  -- 91 嘘言「タン・オブ・ウルフ」（ecl21_a，映姬，组 8a 第 1 张）
    ---原作是一张「每拍一张就换一次密度」的符卡：本体停在 (0,192) 不动，两条子上下文
    ---交替出手 —— 一段每 4 帧甩一整圈（圈上弹数随拍照进度涨），一段每 20 帧朝自机打六连。
    ---每拍中一张，原作都用 ins_115 触发的 Sub7 把整屏清掉、主循环从头重来。
    ---数据源 /tmp/S9_ecl21_a.txt（ECL …/data/ecl21_a.ecl）。骨架：
    ---  · Sub2：ins_55(2)（ANM 组 2..7）+ ins_81(3) + ins_109(0)（拍照目标 0 = 本体）
    ---    + ins_77(24,24) + ins_141(6)（拍 6 张）+ ins_108(0,31)/ins_108(1,30)（子机）
    ---    + ins_143(1,130) + ins_63(-128,-64) 进场 → t=100 ins_64(30,4,0,192) 落到 (0,192)
    ---    （我们的 (0,32)）→ t=130 亮卡名 + ins_75(-140,128,140,192)（活动框）+ ins_149(1.2)
    ---    + ins_132(1) + ins_52(3) 起 Sub3。t=0 的六条 ins_115 见下面「按张重开」。
    ---  · Sub3（主控，240 帧一轮）：t=0 响一声 + ins_117(0,6)（装饰子上下文）→ t=60 换成
    ---    Sub4（**发弹**）→ t=120 ins_67(120,4,0)（speed = 0 ⇒ 只在原地重取移动方向、不位移）
    ---    → t=180 换成 Sub5（**发弹**）→ t=240 ins_4(0,-112) 跳回 t=0。
    ---  · Sub4（每 4 帧一次，ins_4(0,-148)）：进上下文时 intV0 = photoIndex×4 + 24
    ---    （**只在进入时算一次**，@1072）、floatV0 = 4（速）、floatV1 = 0；循环体
    ---    @1136：floatV2 = playerAngle + rand(-π,π)×floatV1（@1156 乘 + @1180 加），
    ---    ins_89 CIRCLE（型 18、色 0、count1 = intV0、count2 = 1、速 4、基角 floatV2、
    ---    步长 0.1848）⇒ **一圈 24 + 4×拍中张数 发**；每轮 floatV1 += 0.001（基角慢慢散开）。
    ---  · Sub5（每 20 帧一次，ins_4(0,-128)）：进上下文时 floatV0 = 4、floatV1 = 0；
    ---    ins_88 CIRCLE_AIMED（型 18、色 1、count1 = 1、count2 = 6、sp1 = 4、sp2 = 1）
    ---    ⇒ 6 发**全朝自机**、速 = 4 − (4−1)×i2/6 = 4, 3.5, 3, 2.5, 2, 1.5。
    ---  · Sub6（每帧 ins_106(5) + ins_150(8)）是装饰 ANM；Sub0/Sub1 是死亡/退场 ⇒ 不实现。
    ---  · Sub7 = Sub3 前面加一句 ins_102（清屏）、时间轴整体 +50 ⇒ 就是「清屏后重开主循环」。
    ---★ ins_115(slot, frame, sub) 的 frame 比的是 camera.photoIndex（见文件头「已拍张数」
    ---  与卡 90 的说明）⇒ 本卡写「拍中第 k 张时清屏并把主循环从头重来」。
    ---  Sub2 里 slot 2 是空的，其余六条 (0,1,7)(1,2,7)(3,3,7)(4,4,7)(5,5,7)(6,6,7)
    ---  正好覆盖第 1..6 张。
    local BOSS_X, BOSS_START_Y = -128, field_y(-64)
    local HOME_X, HOME_Y = 0, field_y(192)              -- 0 / 32
    local ENTRY_WAIT, ENTRY_TIME = 100, 30
    local EASE_OUT = VALUE_SET.DECEL

    local PHOTO_LIMIT = 6                               -- ins_141(6)
    local CARD_NAME = "嘘言「タン・オブ・ウルフ」"
    local CARD_TIME, CARD_HP = 50, 900
    local CARD_ID = 471

    local RING_WAIT = 4                                 -- Sub4 的 ins_4(0,-148)
    local RING_BASE, RING_PER_PHOTO = 24, 4             -- intV0 = photoIndex×4 + 24
    local RING_SPEED = 4                                -- floatV0（c2 = 1 ⇒ 只用 sp1）
    local RING_STEP = math.deg(0.1848)                  -- c2 = 1 ⇒ 不参与，照抄
    local RING_SPREAD = 0.001                           -- floatV1 每轮的增量（rad）
    local AIM_WAIT = 20                                 -- Sub5 的 ins_4(0,-128)
    local AIM_COUNT = 6
    local AIM_SPEED0, AIM_SPEED1 = 4, 1

    local lasers = {}
    local fired = {}

    ---Sub4：每 4 帧一整圈，弹数 = 24 + 4×photoIndex（进上下文时算一次）。
    local function sub4(owner, tok)
        task.New(owner, function()
            local count = RING_BASE + RING_PER_PHOTO * photo_index(PHOTO_LIMIT)
            local spread = 0                            -- floatV1
            while tok.alive do
                local base = sg_aim(owner.x, owner.y)
                        + math.deg(ran:Float(-math.pi, math.pi) * spread)
                sg_shot(89, ball_small, ex_color(0), owner.x, owner.y,
                        count, 1, RING_SPEED, 1.5, base, RING_STEP, false, 514)
                spread = spread + RING_SPREAD
                task.Wait(RING_WAIT)
            end
        end)
    end

    ---Sub5：每 20 帧六连自机狙（型 18、色 1、速 4..1.5）。
    local function sub5(owner, tok)
        task.New(owner, function()
            while tok.alive do
                sg_shot(88, ball_small, ex_color(1), owner.x, owner.y,
                        1, AIM_COUNT, AIM_SPEED0, AIM_SPEED1, 0, 0, true, 514)
                task.Wait(AIM_WAIT)
            end
        end)
    end

    ---Sub3（clear = false）/ Sub7（clear = true）：240 帧一轮。
    local function cycle(owner, clear)
        task.New(owner, function()
            if clear then
                sg_clear(lasers)
            end
            local tok
            local function drop()
                if tok then tok.alive = false; tok = nil end
            end
            while true do
                PlaySound("tan00", 0.1, owner.x / 256, false)   -- t=0 的 ins_106(5)
                task.Wait(60)                                    -- t=0 → 60（Sub6 装饰不实现）
                drop(); tok = { alive = true }; sub4(owner, tok)  -- t=60：ins_117(0,4)
                task.Wait(120)                                   -- t=60 → 180
                ---t=120 的 ins_67(120,4,0)：speed = 0 ⇒ 没有位移，只重取一次移动方向。
                drop(); tok = { alive = true }; sub5(owner, tok)  -- t=180：ins_117(0,5)
                task.Wait(60)                                    -- t=180 → 240
                drop()
            end
        end)
    end

    ---ins_115：拍中第 1..6 张各触发一次（清屏 + 主循环从 t=0 重开）。
    local function watcher(owner)
        task.New(owner, function()
            while true do
                local hits = photo_index(PHOTO_LIMIT)
                for k = 1, PHOTO_LIMIT do
                    if hits >= k and not fired[k] then
                        fired[k] = true
                        cycle(owner, true)                  -- Sub7
                    end
                end
                task.Wait(1)
            end
        end)
    end

    local card = boss.card.New(CARD_NAME, 1, 3, CARD_TIME, CARD_HP)

    function card:before()
    end

    function card:init()
        photo_damage_on(self, PHOTO_LIMIT)
        self.x, self.y = BOSS_X, BOSS_START_Y
        fired = {}
        task.New(self, function()
            task.Wait(ENTRY_WAIT)
            task.MoveTo(HOME_X, HOME_Y, ENTRY_TIME, EASE_OUT)
            cycle(self, false)                              -- Sub3
            watcher(self)
        end)
    end

    function card:frame()
    end

    function card:del()
        photo_damage_off(self)
        sg_clear(lasers)
    end

    boss.card.add({ { card, "8a" } }, LEVEL, CARD_NAME, CARD_ID)
end--嘘言「タン・オブ・ウルフ」

do  -- 92 死歌「八重霧の渡し」（ecl20_b，小町，组 7a 第 2 张）
    ---原作：本体**一直朝自机走**（ins_65 把 movementAngle 设成自机方向、speed 0.5/帧，
    ---再每 2 帧重取一次方向），同时两条子上下文各管一头 —— Sub4 每 180 帧放两批
    ---各 8 根**反向旋转**的 147 激光，Sub5 每 14−2×拍中张数 帧甩两组 9 发扇。
    ---数据源 /tmp/S9_ecl20_b.txt（ECL …/data/ecl20_b.ecl）。骨架：
    ---  · Sub2：ins_55(2) + ins_81(3) + ins_109(0) + ins_77(24,24) + ins_141(6)（拍 6 张）
    ---    + ins_108(0,31)/ins_108(1,30) + ins_143(1,130) + ins_63(-128,-64) 进场
    ---    → t=100 ins_64(30,4,0,128) 落到 (0,128)（我们的 (0,96)）→ t=130 亮卡名
    ---    + ins_149(4) + ins_132(1) + ins_52(3) 起 Sub3。**Sub2 里没有 ins_115** ——
    ---    这一张不像 91 那样按拍照进度换脚本。
    ---  · Sub3（不发弹，只管走位）：t=0 ins_106(5) + 117(1,6)（装饰）+ 117(0,4)（激光）
    ---    + 117(2,5)（扇）；extraIntV0 = 65；@808 t=0 的 ins_65(playerAngle, 0.5)
    ---    配 @828 t=2 的 ins_5(0,-12,extraIntV0) ⇒ **每 2 帧重取一次方向、走到第 130 帧**。
    ---    随后 @852 起：extraIntV0 = 30、floatV0 = 0.5 → 循环 30 次
    ---    「ins_65(playerAngle, floatV0) → floatV0 += 0.04」（@892/@912，每次 2 帧）；
    ---    再 extraIntV0 = 60、floatV0 = 0.5 → 循环 60 次 @976/@996；
    ---    @1020 t=6 的 ins_4(2,-168) 跳回 @852 ⇒ **之后永远在 30 步 + 60 步这两段之间循环**。
    ---    ins_65 设的是「持续直线运动」（EclRunLow.inl case 65 把 movementMode 置 1），
    ---    方向每 2 帧才刷新一次、中间两帧仍按旧方向走，所以位移是逐帧连续的。
    ---  · Sub4（@1052，一轮 180 帧）：t=60 起两批各 8 根 ins_147（型 1、色 2/色 4、
    ---    长 160、宽 16、四段 70/60/30/10、角速度 ±0.0785398 rad/帧、followPhotoTarget = 1），
    ---    每批的起始角是**各取一次** rand(-π,π)、然后每根 +π/4；
    ---    t=150 的 ins_144(15) 是快门脉冲；t=180 跳回 @1092（t=60）——
    ---    跳转把 time 设成 0，所以要等 60 帧才走到 @1092 ⇒ 两轮之间正好 180 帧。
    ---  · Sub5（@1464，一轮 = 14−2×photoIndex 帧）：t=0 里 floatV0 = photoIndex×0.1 + 2.6
    ---    （@1540 乘、@1564 加；@1484 那句 rand 立刻被覆盖，照抄即可），
    ---    ins_86 FAN_AIMED 两组各 9 发（型 23、色 0 / 色 1、基角 0 / π、步长 0.285599）；
    ---    收尾 extraIntV1 = photoIndex×2（ins_22）、再 extraIntV1 = 14 − extraIntV1（ins_21 是
    ---    **op0 = op1 − op2**，所以是 14 − 2×photoIndex）、ins_2 冻结这么多帧。
    ---    ins_141(6) ⇒ photoIndex ≤ 6 ⇒ 冻结 14 → 2 帧，不会出现「0 帧连转」的卡死。
    ---  · Sub6（每 2 帧 ins_106(5) + ins_150(10)）是装饰 ANM；Sub0/Sub1 死亡/退场 ⇒ 不实现。
    local BOSS_X, BOSS_START_Y = -128, field_y(-64)
    local HOME_X, HOME_Y = 0, field_y(128)              -- 0 / 96
    local ENTRY_WAIT, ENTRY_TIME = 100, 30
    local EASE_OUT = VALUE_SET.DECEL

    local PHOTO_LIMIT = 6                               -- ins_141(6)
    local CARD_NAME = "死歌「八重霧の渡し」"
    local CARD_TIME, CARD_HP = 50, 900
    local CARD_ID = 472

    ---Sub3 的三段位移（步数, 初始速, 每步增速, 每步帧数）。
    local DRIFT = { { 65, 0.5, 0 }, { 30, 0.5, 0.04 }, { 60, 0.5, 0 } }

    ---Sub4 的 ins_147。
    local LASER_LEN, LASER_W = 160, 16
    local LASER_STARTUP, LASER_GROW, LASER_SUSTAIN, LASER_FADE = 70, 60, 30, 10
    local LASER_AV = math.deg(0.0785398)                -- TH095 顺时针为正 ⇒ 我们取负
    local LASER_WAIT = 180                              -- 两轮之间 180 帧
    local LASER_FIRST = 60                              -- 第一轮在 t=60

    ---Sub5 的 ins_86 FAN_AIMED。
    local FAN_COUNT = 9
    local FAN_STEP = math.deg(0.285599)
    local FAN_SPEED0, FAN_SPEED_STEP = 2.6, 0.1         -- 2.6 + photoIndex×0.1
    local FAN_FREEZE0, FAN_FREEZE_STEP = 14, 2          -- 14 − photoIndex×2

    local lasers = {}

    ---ins_65：把本体设成「每帧朝自机 speed 像素」，方向每 2 帧重取一次（见注释）。
    ---★ 这一步是 Sub3 **自己**的顺序流程（原作里 ins_5 循环就在同一个上下文里跑），
    ---  所以这里不能再开 task.New —— 直接在主任务的协程里 task.Wait 才有「等到走完」的语义。
    local function drift(owner, tok, steps, speed0, step)
        local sp = speed0
        for _ = 1, steps do
            if not tok.alive then return end
            local a = Angle(owner.x, owner.y, player.x, player.y)
            owner.x = owner.x + sp * cos(a)
            owner.y = owner.y + sp * sin(a)
            task.Wait(1)
            if not tok.alive then return end
            owner.x = owner.x + sp * cos(a)
            owner.y = owner.y + sp * sin(a)
            task.Wait(1)
            sp = sp + step
        end
    end

    ---Sub4：每 180 帧一批（60 帧预热 + 两批 8 根反向旋转的 147）。
    local function sub4(owner, tok)
        task.New(owner, function()
            while tok.alive do
                task.Wait(LASER_FIRST)
                if not tok.alive then return end
                for _, cfg in ipairs({ { 2, LASER_AV }, { 4, -LASER_AV } }) do
                    local a0 = ran:Float(-math.pi, math.pi)
                    for k = 0, 7 do
                        spawn_ex_laser(owner, lasers, cfg[1], owner.x, owner.y,
                                -math.deg(a0 + k * math.pi / 4), LASER_LEN, LASER_W, 8,
                                LASER_STARTUP, LASER_GROW, LASER_SUSTAIN, LASER_FADE,
                                cfg[2], 0, 0, true, true)
                    end
                end
                task.Wait(LASER_WAIT - LASER_FIRST)
            end
        end)
    end

    ---Sub5：每 (14 − 2×photoIndex) 帧两组 9 发扇（一组朝自机、一组背对）。
    local function sub5(owner, tok)
        task.New(owner, function()
            while tok.alive do
                local sp = FAN_SPEED0 + photo_index(PHOTO_LIMIT) * FAN_SPEED_STEP
                sg_shot(86, ball_small, ex_color(0), owner.x, owner.y,
                        FAN_COUNT, 1, sp, 1.5, 0, FAN_STEP, true, 2)
                sg_shot(86, ball_small, ex_color(1), owner.x, owner.y,
                        FAN_COUNT, 1, sp, 1.5, 180, FAN_STEP, true, 2)
                task.Wait(max(1, FAN_FREEZE0 - FAN_FREEZE_STEP * photo_index(PHOTO_LIMIT)))
            end
        end)
    end

    local card = boss.card.New(CARD_NAME, 1, 3, CARD_TIME, CARD_HP)

    function card:before()
    end

    function card:init()
        photo_damage_on(self, PHOTO_LIMIT)
        self.x, self.y = BOSS_X, BOSS_START_Y
        task.New(self, function()
            task.Wait(ENTRY_WAIT)
            task.MoveTo(HOME_X, HOME_Y, ENTRY_TIME, EASE_OUT)
            ---Sub3 的 t=0。
            PlaySound("tan00", 0.1, self.x / 256, false)
            local tok = { alive = true }                -- slot0/slot2 共用一个取消开关
            sub4(self, tok)
            sub5(self, tok)
            drift(self, tok, DRIFT[1][1], DRIFT[1][2], DRIFT[1][3])
            while tok.alive do                         -- ins_4(2,-168) 跳回 @852
                drift(self, tok, DRIFT[2][1], DRIFT[2][2], DRIFT[2][3])
                drift(self, tok, DRIFT[3][1], DRIFT[3][2], DRIFT[3][3])
            end
        end)
    end

    function card:frame()
    end

    function card:del()
        photo_damage_off(self)
        sg_clear(lasers)
    end

    boss.card.add({ { card, "7a" } }, LEVEL, CARD_NAME, CARD_ID)
end--死歌「八重霧の渡し」

do  -- 93 審判「十王裁判」（ecl21_b，映姬，组 8a 第 2 张）
    ---原作是一张「拍得越多、判词换得越狠」的符卡：本体只有一条主循环
    ---（默认一对弹幕 → 180 帧躲一次），另挂**九条 ins_115 监视器**，拍中第 k 张就把
    ---主循环掐掉、换成第 k 号「波」——每号波都是「清屏 + 每 180 帧放一对新的弹幕」。
    ---数据源 /tmp/S9_ecl21_b.txt（ECL …/data/ecl21_b.ecl）。骨架：
    ---  · Sub2：ins_55(2) + ins_81(3) + ins_109(0) + ins_77(24,24) + ins_141(10)（拍 10 张）
    ---    + ins_108(0,31)/ins_108(1,30) + ins_143(1,130) + ins_63(-128,-64) 进场
    ---    → t=40 ins_64(30,4,0,128) 落到 (0,128)（我们的 (0,96)）→ t=70 亮卡名
    ---    + ins_75(-140,128,140,192) + ins_132(1) + ins_52(3) 起 Sub3。
    ---    t=0 的九条 ins_115 是 (0,1,6)(1,2,12)(2,3,9)(3,4,15)(4,5,19)(5,6,22)
    ---    (6,7,25)(7,8,28)(8,9,31) ⇒ 第 k 张 → 第 k 号波（见下表）。
    ---  · Sub3（默认主控）：t=0 响一声 + 117(0,18)（装饰）+ slot1 = Sub4（激光）、
    ---    slot2 = Sub5（扇）→ t=100 ins_144(15)（快门脉冲）→ t=120 ins_67(60,0,1)
    ---    （缓动 0 = 线性、60 帧走 60 px）+ 收掉 slot1/slot2 → t=180 ins_4(0,-120)
    ---    跳回 @1084（那是 **t=0 的 117(1,4)**，不重放 t=0 的响指与装饰）⇒ 一轮 180 帧。
    ---  · 九号波 Sub6/9/12/15/19/22/25/28/31 结构完全一样，只是换 (A, B) 两个子上下文：
    ---      t=0 ins_102（清屏）→ t=30 响一声 + 117(0,18) + 117(1,A) + 117(2,B)
    ---      → t=130 ins_144(15) → t=150 ins_67(60,0,1) + 收掉 slot1/slot2
    ---      → t=210 ins_4(30,-120) 跳回 @(t=30 的 117(1,A))。
    ---    注意跳转把 time 设成 30 ⇒ 清屏与装饰只在第一遍跑，之后每 180 帧只换一对弹幕。
    ---  · (A, B) 清单（帧号 = 拍中第几张；数值全部照抄 dump）：
    ---      1 (Sub4,  Sub5)   4: 145(型12,色3,速4,角=自机,长96,宽16) 每 30 帧一根
    ---                        5: FAN(型3, 色6, 7发,速5,自机,步0.101342)
    ---                           + FAN(型13,色3,21发,速6,自机+π,步0.241661) 每 10 帧
    ---      2 (Sub13, Sub14) 13: 145(型12,色4,速5,角=自机−22.5°+rand×45°) 每 4 帧
    ---                       14: 同 Sub5 但色 8 / 色 4
    ---      3 (Sub10, Sub11) 10: 五根 145（型12, 色2, 角=自机−22.5°…+22.5° 每根 +11.25°,
    ---                            速 4/6/8/6/4）每 15 帧
    ---                       11: 同 Sub5 但色 4 / 色 2
    ---      4 (Sub16, Sub17) 16: 32 根 ins_147（型12, 色1, 角=自机+k×11.25°, 长512, 宽12,
    ---                            四段 20/10/30/10, 角速度 0, 不跟随）每 30 帧
    ---                       17: **只有** FAN(型3, 色2, 7发, 速5, 自机, 步0.101342) 每 10 帧
    ---      5 (Sub20, Sub21) 20: 同 Sub13 但色6、速4
    ---                       21: 3×[FAN(型3, 色13, 1发, 速=3.5+rand×1.5,
    ---                            角=自机−22.5°+rand×45°, 步0.392699)] + FAN(型13,色6,24发,速6,
    ---                            自机+π, 步0.241661) 每 10 帧
    ---      6 (Sub23, Sub24) 23: 同 Sub13 但色7、速5
    ---                       24: 4×[FAN(型3, 色15, 1发, 速=3.5+rand×2.5, 角同上)] + 上面那组 24 发
    ---      7 (Sub26, Sub27) 26: 只算一个随机角、**不发弹**，每 4 帧
    ---                       27: floatV0 从 45° 起每轮 +6°，FAN(型3, 色2, 8发, 速3,
    ---                            角=floatV0, 步0.1309) + FAN(型18, 色0, 24发, 速6, 自机+π,
    ---                            步0.241661) 每 4 帧
    ---      8 (Sub29, Sub30) 29: 同 Sub26（不发弹）
    ---                       30: floatV0 从 135° 起每轮 −6°，FAN(型3, 色6, 8发, 速3.5,
    ---                            角=floatV0, 步0.136591) + FAN(型18, 色1, 24发, 速6, 自机+π,
    ---                            步0.241661) 每 4 帧
    ---      9 (Sub32, Sub33) 32: 同 Sub26（不发弹）
    ---                       33: floatV0 从 67.5° 起每轮 +6°，FAN(型3, 色2, 16发, 速3.5,
    ---                            角=floatV0, 步0.136591) + FAN(型18, 色1, 24发, 速6, 自机+π,
    ---                            步0.241661) 每 4 帧
    ---  · 型 3/18 半径 2/3 → ball_small；型 12/13 半径 5/6 → ball_mid。
    ---  · Sub4 的 @1292 是 `ins_26(floatV2, floatV0, 0.392699)` 再 `+= 0.19635`×2
    ---    ⇒ 相减相加后就是自机角本身（float32 上差 1e-6）；照抄会得到同样的角。
    ---  · Sub26/29/32 的角算完就丢（后面没有 ins_145/147），是原作留的空壳 ——
    ---    这里保留「每 4 帧空转」算子的位置，但不发弹。
    local BOSS_X, BOSS_START_Y = -128, field_y(-64)
    local HOME_X, HOME_Y = 0, field_y(128)              -- 0 / 96
    local ENTRY_WAIT, ENTRY_TIME = 40, 30
    local EASE_OUT = VALUE_SET.DECEL

    local PHOTO_LIMIT = 10                              -- ins_141(10)
    local CARD_NAME = "審判「十王裁判」"
    local CARD_TIME, CARD_HP = 50, 900
    local CARD_ID = 473

    local BOX = { -140, 128, 140, 192 }                 -- ins_75 的活动框（TH095 空间）
    local ROUND = 180                                   -- Sub3 与九号波共用的一轮

    local SPREAD = math.deg(0.392699)                   -- 22.5°，1 发扇的随机半宽
    local FAN_STEP_A = math.deg(0.101342)               -- 7 发扇的步长
    local FAN_STEP_B = math.deg(0.241661)               -- 21/24 发扇的步长
    local FAN_STEP_C = math.deg(0.1309)                 -- 8 发扇的步长（7 号波）
    local FAN_STEP_D = math.deg(0.136591)               -- 8/16 发扇的步长（8/9 号波）
    local ROT_STEP = math.deg(0.10472)                  -- 6°/轮

    local lasers = {}
    local st = { dead = false }
    local fired = {}

    local function alive(tok)
        return not st.dead and (tok == nil or tok.alive)
    end

    ---Sub4：每 30 帧一根自机方向 145（型 12、色 3、速 4、长 96、宽 16）。
    local function laser_single(owner, tok, index, speed, jitter, period)
        task.New(owner, function()
            while alive(tok) do
                local a = sg_aim(owner.x, owner.y) + (jitter or 0)
                spawn_ex_laser_straight(owner, lasers, index, owner.x, owner.y,
                        -a, 96, 16, speed)
                task.Wait(period)
            end
        end)
    end

    ---五根 145：角 = 自机 −22.5° + k×11.25°、速 4/6/8/6/4（3 号波的 Sub10）。
    local function laser_five(owner, tok)
        local speeds = { 4, 6, 8, 6, 4 }
        task.New(owner, function()
            while alive(tok) do
                for k = 0, 4 do
                    local a = sg_aim(owner.x, owner.y) - SPREAD + k * SPREAD / 2
                    spawn_ex_laser_straight(owner, lasers, 2, owner.x, owner.y,
                            -a, 96, 16, speeds[k + 1])
                end
                task.Wait(15)
            end
        end)
    end

    ---32 根 147（4 号波的 Sub16，型 12、色 1、长 512、宽 12、四段 20/10/30/10）。
    local function laser_ring_147(owner, tok)
        task.New(owner, function()
            while alive(tok) do
                local base = sg_aim(owner.x, owner.y)
                for k = 0, 31 do
                    spawn_ex_laser(owner, lasers, 12, owner.x, owner.y,
                            -math.rad(base + k * 11.25), 512, 12, 8, 20, 10, 30, 10,
                            0, 0, 0, false, true)
                end
                task.Wait(30)
            end
        end)
    end

    ---ins_87 FAN 的一发（base_off 是以自机角为 0 的偏移，度）。
    local function fan(owner, tok, style, color, count, speed, base_off, step, period)
        task.New(owner, function()
            while alive(tok) do
                sg_shot(87, style, ex_color(color), owner.x, owner.y,
                        count, 1, speed, 1.5, sg_aim(owner.x, owner.y) + base_off,
                        step, false, 514)
                task.Wait(period)
            end
        end)
    end

    ---「小扇 + 大扇」组合：FAN(type3, 7 发) + FAN(type13, 21 发, 反方向)。
    local function fan_pair(owner, tok, small_color, big_color)
        task.New(owner, function()
            while alive(tok) do
                local a = sg_aim(owner.x, owner.y)
                sg_shot(87, ball_small, ex_color(small_color), owner.x, owner.y,
                        7, 1, 5, 1.5, a, FAN_STEP_A, false, 514)
                sg_shot(87, ball_mid, ex_color(big_color), owner.x, owner.y,
                        21, 1, 6, 1.5, a + 180, FAN_STEP_B, false, 514)
                task.Wait(10)
            end
        end)
    end

    ---「n 发 1 弹随机扇 + 24 发大扇」组合（5/6 号波的 B）。
    local function fan_random(owner, tok, n, dcolor, dspread, big_color)
        task.New(owner, function()
            while alive(tok) do
                local a = sg_aim(owner.x, owner.y)
                for _ = 1, n do
                    local sp = 3.5 + ran:Float(0, 1) * dspread
                    local ang = a - SPREAD + ran:Float(0, 1) * SPREAD * 2
                    sg_shot(87, ball_small, ex_color(dcolor), owner.x, owner.y,
                            1, 1, sp, 1.5, ang, SPREAD, false, 514)
                end
                sg_shot(87, ball_mid, ex_color(big_color), owner.x, owner.y,
                        24, 1, 6, 1.5, a + 180, FAN_STEP_B, false, 514)
                task.Wait(10)
            end
        end)
    end

    ---「旋转扇 + 24 发大扇」组合（7/8/9 号波的 B）。
    ---start 是 floatV0 的初值（度），drift 是每轮的增量（度，可正可负）。
    local function fan_spin(owner, tok, color, count, sp, step, start, drift, big_color)
        task.New(owner, function()
            local ang = start
            while alive(tok) do
                sg_shot(87, ball_small, ex_color(color), owner.x, owner.y,
                        count, 1, sp, 1.5, ang, step, false, 514)
                sg_shot(87, ball_small, ex_color(big_color), owner.x, owner.y,
                        24, 1, 6, 1.5, sg_aim(owner.x, owner.y) + 180, FAN_STEP_B, false, 514)
                ang = ang + drift
                task.Wait(4)
            end
        end)
    end

    ---7 号波的 A（Sub26）/ 8 号波的 A（Sub29）/ 9 号波的 A（Sub32）：只空转。
    local function noop_stream(owner, tok)
        task.New(owner, function()
            while alive(tok) do
                task.Wait(4)
            end
        end)
    end

    ---九号波的包装：清屏 → t=30 起一对弹幕 → t=150 走位 + 收尾 → 每 180 帧重来。
    local function wave(owner, a, b)
        task.New(owner, function()
            sg_clear(lasers)
            local ta, tb
            local function spawn()
                ta, tb = { alive = true }, { alive = true }
                a(owner, ta)
                b(owner, tb)
            end
            local function drop()
                if ta then ta.alive = false; ta = nil end
                if tb then tb.alive = false; tb = nil end
            end
            task.Wait(30)
            spawn()
            while true do
                task.Wait(120)                          -- t=30 → 150
                sg_bmove(owner, st, 60, 0, 1, BOX)      -- t=150（60 帧、60 px）
                drop()
                task.Wait(60)                           -- t=150 → 210
                spawn()                                 -- 跳回 t=30
            end
        end)
    end

    ---Sub3：默认主控（180 帧一轮，默认只用 Sub4/Sub5）。
    local function main_script(owner)
        task.New(owner, function()
            PlaySound("tan00", 0.1, owner.x / 256, false)   -- t=0 的 ins_106(5)
            local ta, tb = { alive = true }, { alive = true }
            laser_single(owner, ta, 3, 4, 0, 30)            -- Sub4
            fan_pair(owner, tb, 6, 3)                       -- Sub5
            while true do
                task.Wait(120)                              -- t=0 → 120
                sg_bmove(owner, st, 60, 0, 1, BOX)
                ta.alive = false; tb.alive = false
                task.Wait(60)                               -- t=120 → 180
                ta, tb = { alive = true }, { alive = true }
                laser_single(owner, ta, 3, 4, 0, 30)
                fan_pair(owner, tb, 6, 3)
            end
        end)
    end

    ---九条 ins_115：第 k 张 → 第 k 号波（A, B 见文件头清单）。
    local WAVES = {
        { function(o, t) laser_single(o, t, 3, 4, 0, 30) end,
          function(o, t) fan_pair(o, t, 6, 3) end },
        { function(o, t) laser_single(o, t, 4, 5, ran:Float(-SPREAD, SPREAD), 4) end,
          function(o, t) fan_pair(o, t, 8, 4) end },
        { laser_five,
          function(o, t) fan_pair(o, t, 4, 2) end },
        { laser_ring_147,
          function(o, t) fan(o, t, ball_small, 2, 7, 5, 0, FAN_STEP_A, 10) end },
        { function(o, t) laser_single(o, t, 6, 4, ran:Float(-SPREAD, SPREAD), 4) end,
          function(o, t) fan_random(o, t, 3, 13, 1.5, 6) end },
        { function(o, t) laser_single(o, t, 7, 5, ran:Float(-SPREAD, SPREAD), 4) end,
          function(o, t) fan_random(o, t, 4, 15, 2.5, 7) end },
        { noop_stream,
          function(o, t) fan_spin(o, t, 2, 8, 3, FAN_STEP_C, 45, ROT_STEP, 0) end },
        { noop_stream,
          function(o, t) fan_spin(o, t, 6, 8, 3.5, FAN_STEP_D, 135, -ROT_STEP, 1) end },
        { noop_stream,
          function(o, t) fan_spin(o, t, 2, 16, 3.5, FAN_STEP_D, 67.5, ROT_STEP, 1) end },
    }

    local card = boss.card.New(CARD_NAME, 1, 3, CARD_TIME, CARD_HP)

    function card:before()
    end

    function card:init()
        photo_damage_on(self, PHOTO_LIMIT)
        self.x, self.y = BOSS_X, BOSS_START_Y
        fired = {}
        st.dead = false
        task.New(self, function()
            task.Wait(ENTRY_WAIT)
            task.MoveTo(HOME_X, HOME_Y, ENTRY_TIME, EASE_OUT)
            main_script(self)
            task.New(self, function()                       -- ins_115 监视器
                while not st.dead do
                    local hits = photo_index(PHOTO_LIMIT)
                    for k = 1, #WAVES do
                        if hits >= k and not fired[k] then
                            fired[k] = true
                            wave(self, WAVES[k][1], WAVES[k][2])
                        end
                    end
                    task.Wait(1)
                end
            end)
        end)
    end

    function card:frame()
    end

    function card:del()
        st.dead = true
        photo_damage_off(self)
        sg_clear(lasers)
    end

    boss.card.add({ { card, "8a" } }, LEVEL, CARD_NAME, CARD_ID)
end--審判「十王裁判」

do  -- 94 古雨「黄泉中有の旅の雨」（ecl20_c，小町，组 7a 第 3 张）
    ---原作是「场地上缘下起黄泉之雨」：本体在**顶边那条窄带里**左右挪，所有雨点都从
    ---上缘随机位置（x∈[-192,192]、TH095 y∈[0,32]）往下飘；拍得越多雨越密。
    ---数据源 /tmp/S9_ecl20_c.txt（ECL …/data/ecl20_c.ecl）。骨架：
    ---  · Sub2：ins_55(2) + ins_81(3) + ins_109(0) + ins_77(24,24) + ins_141(7)（拍 7 张）
    ---    + ins_108(0,31)/ins_108(1,30) + ins_143(1,130) + ins_63(-128,-64) 进场
    ---    → t=100 ins_64(30,4,0,128) 落到 (0,128)（我们的 (0,96)）→ t=130 亮卡名
    ---    + ins_75(-128,128,128,128)（顶边窄带）+ ins_149(8) + ins_132(1) + ins_52(3)。
    ---  · Sub3（主控，128 帧一轮）：t=0 ins_106(5) + 117(7,8)（装饰）+ slot1 = Sub5
    ---    （自机狙雨点）+ slot0 = Sub4（斜落雨点）+ slot2 = Sub6 + slot3 = Sub7；
    ---    @884 起 ins_144(15) + ins_67(128,0,0.5)（128 帧、缓动 0、走 64 px）
    ---    → t=128 ins_4(0,-40) 跳回 @884。⇒ 一轮 128 帧、每轮只在顶边挪一段。
    ---  · Sub4（每 2 帧，ins_4(0,-576)）：先算出膛点 —— floatV0 = randS×192、
    ---    floatV1 = randF32×32，再用 ins_26/ins_100 得到世界坐标 (randS×192, randF32×32)
    ---    ——就是场地上缘；然后 ins_87 FAN(型3、色6、1 发、速 = 1+randF32、角 = 1.1781
    ---    + randF32×0.785398)。t=1 的 `ins_44(photoIndex, 6, 1, 296)` 是 **CMPlt**：
    ---    photoIndex < 6 就跳过第二块 ⇒ **拍到第 6 张起**每 2 帧再多一颗（色 4、速 1..2.5）。
    ---  · Sub5（每 4 帧）：同样从顶边随机点出发，ins_86 FAN_AIMED(型3、色8、1 发、
    ---    速 = 2 + randF32×2、ang = 0) ⇒ 每 4 帧一颗**朝自机**的雨点。
    ---    （@1712 的 floatV0 = rand×0.314159 算完没人用，是原作的死代码，照抄不算。）
    ---  · Sub6（一轮 121 帧）：每帧一颗 ins_89 CIRCLE（型23、色0、1 发、速 = floatV0 +
    ---    0.15×i、基角 playerAngle、出膛点 = 本体），共 24 颗（ins_5(0,-144,24)）；
    ---    @1972 的 `ins_44(photoIndex, 3, 0, 72)` 闸 ⇒ **拍到第 3 张起才有**。
    ---    发完到 t=121 才跳回 t=0 ⇒ 每轮 24 颗 + 97 帧空档。
    ---  · Sub7（一轮 61 帧）：每帧一组 ins_87 FAN(型23、色1、3 发、速 = floatV0 +
    ---    0.15×i、基角 playerAngle、步长 0.392699)，共 12 组；@2236 的闸是
    ---    `ins_44(photoIndex, 5, 0, 72)` ⇒ **拍到第 5 张起才有**。
    ---  · Sub8（slot 7：t=120..135 把 shootOffset 摆到屏幕外三角 + ins_150(10)）是装饰
    ---    ANM；Sub0/Sub1 死亡/退场 ⇒ 不实现。
    ---  · 型 3/23 都是直径 6/4 ⇒ ball_small。
    local BOSS_X, BOSS_START_Y = -128, field_y(-64)
    local HOME_X, HOME_Y = 0, field_y(128)              -- 0 / 96
    local ENTRY_WAIT, ENTRY_TIME = 100, 30
    local EASE_OUT = VALUE_SET.DECEL

    local PHOTO_LIMIT = 7                               -- ins_141(7)
    local CARD_NAME = "古雨「黄泉中有の旅の雨」"
    local CARD_TIME, CARD_HP = 50, 900
    local CARD_ID = 474

    local BOX = { -128, 128, 128, 128 }                 -- ins_75 的顶边窄带（TH095 空间）
    local MOVE_FRAMES, MOVE_SPEED = 128, 0.5            -- ins_67(128,0,0.5) ⇒ 64 px

    local RAIN_X, RAIN_Y = 192, 32                      -- 上缘：x∈[-192,192]、y∈[0,32]
    local DROP_ANGLE0 = 1.1781                          -- 67.5°（TH095，y 朝下）
    local DROP_ANGLE_RND = 0.785398                     -- ±22.5°
    local DROP_SPEED0, DROP_SPEED_RND = 1, 1            -- 色 6：1 + rand×1
    local DROP2_SPEED_RND = 1.5                         -- 色 4（第 6 张起）：1 + rand×1.5
    local AIM_SPEED0, AIM_SPEED_RND = 2, 2              -- 色 8：2 + rand×2
    local RING_COUNT, RING_SPEED_STEP = 24, 0.15        -- Sub6
    local RING_PERIOD = 121
    local FAN_BURST, FAN_COUNT, FAN_PERIOD = 12, 3, 61  -- Sub7
    local GATE_RING, GATE_FAN, GATE_DROP2 = 3, 5, 6     -- 各闸的 photoIndex 门槛

    local lasers = {}
    local st = { dead = false }

    ---顶边的随机出膛点（TH095 坐标 → 我们的坐标）。
    local function rain_point()
        return ran:Float(-1, 1) * RAIN_X, field_y(ran:Float(0, 1) * RAIN_Y)
    end

    ---Sub4：每 2 帧一颗斜落雨点；第 6 张起每轮再多一颗（色 4）。
    local function sub4(owner, tok)
        task.New(owner, function()
            while not st.dead and tok.alive do
                local x, y = rain_point()
                sg_shot(87, ball_small, ex_color(6), x, y, 1, 1,
                        DROP_SPEED0 + ran:Float(0, 1) * DROP_SPEED_RND, 0.5,
                        math.deg(DROP_ANGLE0 + ran:Float(0, 1) * DROP_ANGLE_RND), 0, false, 514)
                if photo_index(PHOTO_LIMIT) >= GATE_DROP2 then
                    local x2, y2 = rain_point()
                    sg_shot(87, ball_small, ex_color(4), x2, y2, 1, 1,
                            DROP_SPEED0 + ran:Float(0, 1) * DROP2_SPEED_RND, 0.5,
                            math.deg(DROP_ANGLE0 + ran:Float(0, 1) * DROP_ANGLE_RND), 0, false, 514)
                end
                task.Wait(2)
            end
        end)
    end

    ---Sub5：每 4 帧一颗朝自机的雨点（色 8）。
    local function sub5(owner, tok)
        task.New(owner, function()
            while not st.dead and tok.alive do
                local x, y = rain_point()
                sg_shot(86, ball_small, ex_color(8), x, y, 1, 1,
                        AIM_SPEED0 + ran:Float(0, 1) * AIM_SPEED_RND, 0.5, 0, 0, true, 514)
                task.Wait(4)
            end
        end)
    end

    ---Sub6：每帧一颗自机方向小玉、共 24 颗，然后空转 97 帧（一轮 121）。
    local function sub6(owner, tok)
        task.New(owner, function()
            while not st.dead and tok.alive do
                local sp = 0.5
                for _ = 1, RING_COUNT do
                    if not tok.alive or st.dead then return end
                    if photo_index(PHOTO_LIMIT) >= GATE_RING then
                        sg_shot(89, ball_small, ex_color(0), owner.x, owner.y, 1, 1,
                                sp, 0.5, sg_aim(owner.x, owner.y), 0, false, 514)
                    end
                    sp = sp + RING_SPEED_STEP
                    task.Wait(1)
                end
                task.Wait(RING_PERIOD - RING_COUNT)
            end
        end)
    end

    ---Sub7：每帧一组 3 发扇、共 12 组，然后空转 49 帧（一轮 61）。
    local function sub7(owner, tok)
        task.New(owner, function()
            while not st.dead and tok.alive do
                local sp = 1
                for _ = 1, FAN_BURST do
                    if not tok.alive or st.dead then return end
                    if photo_index(PHOTO_LIMIT) >= GATE_FAN then
                        sg_shot(87, ball_small, ex_color(1), owner.x, owner.y,
                                FAN_COUNT, 1, sp, 0.5, sg_aim(owner.x, owner.y),
                                math.deg(0.392699), false, 514)
                    end
                    sp = sp + RING_SPEED_STEP
                    task.Wait(1)
                end
                task.Wait(FAN_PERIOD - FAN_BURST)
            end
        end)
    end

    local card = boss.card.New(CARD_NAME, 1, 3, CARD_TIME, CARD_HP)

    function card:before()
    end

    function card:init()
        photo_damage_on(self, PHOTO_LIMIT)
        self.x, self.y = BOSS_X, BOSS_START_Y
        st.dead = false
        task.New(self, function()
            task.Wait(ENTRY_WAIT)
            task.MoveTo(HOME_X, HOME_Y, ENTRY_TIME, EASE_OUT)
            ---Sub3 的 t=0。
            PlaySound("tan00", 0.1, self.x / 256, false)
            local tok = { alive = true }
            sub4(self, tok)
            sub5(self, tok)
            sub6(self, tok)
            sub7(self, tok)
            while tok.alive and not st.dead do
                sg_bmove(self, st, MOVE_FRAMES, 0, MOVE_SPEED, BOX)    -- @884
                task.Wait(MOVE_FRAMES)                                  -- t=128 跳回 @884
            end
        end)
    end

    function card:frame()
    end

    function card:del()
        st.dead = true
        photo_damage_off(self)
        sg_clear(lasers)
    end

    boss.card.add({ { card, "7a" } }, LEVEL, CARD_NAME, CARD_ID)
end--古雨「黄泉中有の旅の雨」

do  -- 95 審判「ギルティ・オワ・ノットギルティ」（ecl21_c，映姬，组 8a 第 3 张）
    ---原作是「宣判」：本体的主循环每 180 帧交替「装饰 → 一束激光齐射」，另有一条
    ---**一直挂着**的子上下文，每 20 帧按拍照进度扇形甩出大玉。
    ---数据源 /tmp/S9_ecl21_c.txt（ECL …/data/ecl21_c.ecl）。骨架：
    ---  · Sub2：ins_55(2) + ins_81(3) + ins_109(0) + ins_77(24,24) + ins_141(6)（拍 6 张）
    ---    + ins_108(0,31)/ins_108(1,30) + ins_143(1,130) + ins_63(-128,-64) 进场
    ---    → t=100 ins_64(30,4,0,128) 落到 (0,128)（我们的 (0,96)）→ t=130 亮卡名
    ---    + ins_75(-128,128,192,128) + ins_149(3) + ins_132(1) + ins_52(3) 起 Sub3。
    ---  · Sub3（180 帧一轮）：t=0 117(1,5)（slot1 = Sub5，**只建这一次**）+ 117(0,6)
    ---    （装饰，不实现）→ t=60 把 slot0 换成 Sub4（激光）→ t=180 ins_4(0,-56) 跳回
    ---    @780（那是 t=0 的 117(0,6)）⇒ 之后每轮 t=0 只重建装饰、t=60 再放一次激光。
    ---  · Sub4（@868，20 帧后自灭：最后一句是 ins_53）：t=0 取 extraFloatV2 = playerAngle、
    ---    floatV0 = 自机角 + 67.5°、floatV1 = 自机角 − 67.5°，各放一根 ins_147
    ---    （型1、色 2 / 色 6、长 512、宽 16、四段 40/20/60/10、角速度 0、follow = 1）；
    ---    t=4/8/12 各把 floatV0 再 +22.5°、floatV1 再 −22.5°、各再放一根
    ---    ⇒ 共 8 根细激光，角度是 自机角 ± {67.5°, 90°, 112.5°, 135°}；
    ---    t=20 再放一根**宽 96** 的粗激光（色 4），角度是 t=0 时的自机角（@1520/1532/1556/
    ---    1604/1632 那一串比较只在归一化 floatV2，结果没人用 —— 原作死代码，照抄不算）。
    ---  · Sub5（@1732，每 20 帧一轮）：t=180 先把 extraFloatV2 置 −90°；循环体在 t=180：
    ---    intV0 = photoIndex + 2，然后 4 组 ins_86 FAN_AIMED（型 17 = 直径 28 的大玉、
    ---    count1 = intV0、速 3、步长 0.418879），基角依次是
    ---      A、−A、A+3.6°+180°、−(A+3.6°+180°)，颜色 1/0/1/0；
    ---    每轮 A 累加 7.2°（@1888 与 @2044 各 +3.6°、@2064 ins_37 归一化）。
    ---    intV0 = photoIndex + 2 ⇒ 每组 2..8 颗（PHOTO_LIMIT = 6 时满 8 颗），**与拍摄进度同向**。
    ---  · Sub6（每帧 106(5) + 150(8)）是装饰 ANM；Sub0/Sub1 死亡/退场 ⇒ 不实现。
    ---    （本卡 Sub3 的 t=0 没有 ins_106(5)，响指音在装饰上下文里 ⇒ 本卡刻意不放音效。）
    local BOSS_X, BOSS_START_Y = -128, field_y(-64)
    local HOME_X, HOME_Y = 0, field_y(128)              -- 0 / 96
    local ENTRY_WAIT, ENTRY_TIME = 100, 30
    local EASE_OUT = VALUE_SET.DECEL

    local PHOTO_LIMIT = 6                               -- ins_141(6)
    local CARD_NAME = "審判「ギルティ・オワ・ノットギルティ」"
    local CARD_TIME, CARD_HP = 50, 900
    local CARD_ID = 475

    local CYCLE = 180                                   -- Sub3 的 ins_4(0,-56)
    local BEAM_AT = 60                                  -- Sub3 的 t=60
    local BEAM_LEN, BEAM_W, BEAM_WIDE = 512, 16, 96
    local BEAM_STARTUP, BEAM_GROW, BEAM_SUSTAIN, BEAM_FADE = 40, 20, 60, 10
    local BEAM_OFF0, BEAM_OFF_STEP = math.deg(1.1781), math.deg(0.392699)  -- 67.5° / 22.5°

    local FAN_START = -90                               -- Sub5 的 extraFloatV2 初值（TH095 度）
    local FAN_STEP = math.deg(0.418879)                 -- 24°
    local FAN_SPIN = math.deg(0.0628319)                -- 3.6°/次（每轮两次）
    local FAN_SPEED = 3
    local FAN_WAIT = 20
    local FAN_FIRST = 180                               -- 第一条在 t=180

    local lasers = {}
    local st = { dead = false }

    ---Sub4：一次 8 根细 147 + 1 根宽 96 的齐射（20 帧后自己结束）。
    local function sub4(owner)
        task.New(owner, function()
            local base = sg_aim(owner.x, owner.y)       -- extraFloatV2 = playerAngle
            for k = 0, 3 do
                local off = BEAM_OFF0 + k * BEAM_OFF_STEP
                spawn_ex_laser(owner, lasers, 2, owner.x, owner.y, -(base + off),
                        BEAM_LEN, BEAM_W, 8, BEAM_STARTUP, BEAM_GROW, BEAM_SUSTAIN,
                        BEAM_FADE, 0, 0, 0, true, true)
                spawn_ex_laser(owner, lasers, 6, owner.x, owner.y, -(base - off),
                        BEAM_LEN, BEAM_W, 8, BEAM_STARTUP, BEAM_GROW, BEAM_SUSTAIN,
                        BEAM_FADE, 0, 0, 0, true, true)
                if k < 3 then
                    task.Wait(4)
                end
            end
            task.Wait(8)                                -- t=12 → t=20
            spawn_ex_laser(owner, lasers, 4, owner.x, owner.y, -base,
                    BEAM_LEN, BEAM_WIDE, 8, BEAM_STARTUP, BEAM_GROW, BEAM_SUSTAIN,
                    BEAM_FADE, 0, 0, 0, true, true)
        end)
    end

    ---Sub5：每 20 帧四组大玉扇（每颗组的发数 = photoIndex + 2）。
    local function sub5(owner, tok)
        task.New(owner, function()
            local a = FAN_START
            task.Wait(FAN_FIRST)
            while tok.alive and not st.dead do
                local n = photo_index(PHOTO_LIMIT) + 2
                sg_shot(86, ball_huge, ex_color(1), owner.x, owner.y,
                        n, 1, FAN_SPEED, 1.5, a, FAN_STEP, true, 514)
                sg_shot(86, ball_huge, ex_color(0), owner.x, owner.y,
                        n, 1, FAN_SPEED, 1.5, -a, FAN_STEP, true, 514)
                local b = a + FAN_SPIN
                sg_shot(86, ball_huge, ex_color(1), owner.x, owner.y,
                        n, 1, FAN_SPEED, 1.5, b + 180, FAN_STEP, true, 514)
                sg_shot(86, ball_huge, ex_color(0), owner.x, owner.y,
                        n, 1, FAN_SPEED, 1.5, -(b + 180), FAN_STEP, true, 514)
                a = b + FAN_SPIN
                task.Wait(FAN_WAIT)
            end
        end)
    end

    local card = boss.card.New(CARD_NAME, 1, 3, CARD_TIME, CARD_HP)

    function card:before()
    end

    function card:init()
        photo_damage_on(self, PHOTO_LIMIT)
        self.x, self.y = BOSS_X, BOSS_START_Y
        st.dead = false
        task.New(self, function()
            task.Wait(ENTRY_WAIT)
            task.MoveTo(HOME_X, HOME_Y, ENTRY_TIME, EASE_OUT)
            ---Sub3 的 t=0：slot1 = Sub5 只建这一次。
            local tok = { alive = true }
            sub5(self, tok)
            while tok.alive and not st.dead do
                -- t=0：slot0 = Sub6（装饰，不实现）
                task.Wait(BEAM_AT)                          -- t=0 → 60
                if not tok.alive or st.dead then return end
                sub4(self)                                  -- t=60：slot0 = Sub4
                task.Wait(CYCLE - BEAM_AT)                  -- t=60 → 180（跳回 t=0）
            end
        end)
    end

    function card:frame()
    end

    function card:del()
        st.dead = true
        photo_damage_off(self)
        sg_clear(lasers)
    end

    boss.card.add({ { card, "8a" } }, LEVEL, CARD_NAME, CARD_ID)
end--審判「ギルティ・オワ・ノットギルティ」

do  -- 96 死価「プライス・オブ・ライフ」（ecl20_d，小町，组 7a 第 4 张）
    ---原作是「标价」：本体先不动，拍满 2 张之后才开始**慢慢朝自机走**（0.3 px/帧、
    ---方向每 2 帧重取）；两条一样的子上下文在**自机上下各 80 px 处**吐「先停再倒着飘」
    ---的慢弹，另一条每 100 帧甩一圈会**撞墙反弹**的弹。
    ---数据源 /tmp/S9_ecl20_d.txt（ECL …/data/ecl20_d.ecl）。骨架：
    ---  · Sub2：ins_55(2) + ins_81(3) + ins_109(0) + ins_77(24,24) + ins_141(6)（拍 6 张）
    ---    + ins_108(0,31)/ins_108(1,30) + ins_143(1,130) + ins_63(-128,-64) 进场
    ---    → t=100 ins_64(30,4,0,192) 落到 (0,192)（我们的 (0,32)）→ t=130 亮卡名
    ---    + ins_149(6) + ins_132(1) + ins_52(3)。**没有 ins_75**（这一张没有活动框）。
    ---  · Sub3（@696）：t=0 ins_106 装饰句不实现 + 117(0,5)（装饰）→ t=60 先把
    ---    extraFloatV2 = −90°、floatV2 = 3°、intV0 = 1 写进父变量区，再 117(0,4)
    ---    ⇒ slot0 的 Sub4 拿到「−90° / 色 1」；然后 extraFloatV2 = +90°、intV0 = 2、
    ---    117(1,4) ⇒ slot1 的 Sub4 拿到「+90° / 色 2」；再 117(2,6)。
    ---    （ins_117 会把父上下文整份变量区 memcpy 给子上下文 —— 同卡 102 的注释。）
    ---    @928 的 `ins_44(photoIndex, 2, 60, 48)` 是 CMPlt：photoIndex < 2 就绕回 @928
    ---    **每帧只重查一次、原地空转**；够 2 张才 @956 跳到 t=61 开始
    ---    ins_65(playerAngle, 0.3) + @1016 每 2 帧回跳 ⇒ 一直慢慢追着自机走。
    ---  · Sub4（每 2 帧一轮，@1068/@1500）：出膛点 = **自机位置** + 80 px（方向 extraFloatV2）
    ---    —— @1148 的 ins_38 是 (cos,sin)×80，@1176/@1196 再加 player.x/y，@1216/@1240
    ---    再减本体位置当 shootOffset ⇒ 世界坐标就是「自机 ± 上下 80 px」；
    ---    然后 ins_89 CIRCLE（型23、色 intV0、1 发、速 0.2、基角 extraFloatV2、步长 π/2）。
    ---    弹上挂着两条 ins_101（@1068 是 slot0 kind 0x8000 = WAIT、i0 = 20；
    ---    @1108 是 slot1 kind 0x10 = VEC_ACCEL、i0 = 60、f0 = −0.05、f1 = −999）
    ---    ⇒ 前 20 帧不动，随后 60 帧每帧 speed −= 0.05（0.2 → −2.8），弹会**先停住再倒着飘**。
    ---    flags 33298 = 0x8212 = 0x8000 + 0x200(出场音) + 0x10 + 0x2。
    ---    @1328/@1356 两个 CMPlt 闸：photoIndex ≥ 4 且 intV1 ≥ 50（即每 100 帧一次）时，
    ---    在同一个出膛点再甩一圈 10 发（型23、色1、速0.8、基角 rand(−π,π)、步长 π/2）
    ---    并把 intV1 清零；否则 intV1 每轮 +1。
    ---    收尾 extraFloatV2 += 3°（@1464）再 ins_37 归一化（@1484）。
    ---  · Sub6（每 100 帧一轮，@1700/@1836）：弹上挂 ins_101(0, 0x400 BOUNCE_ALL, 999 次,
    ---    速取当前值) ⇒ 会从场地左右/上沿弹回来；@1764 的闸是 `photoIndex ≥ 2`，
    ---    够 2 张才甩一圈 16 发（型23、色0、速1、基角 rand(−π,π)）。
    ---  · Sub5（每帧 106(5) + 150(8)）是装饰 ANM；Sub0/Sub1 死亡/退场 ⇒ 不实现。
    local BOSS_X, BOSS_START_Y = -128, field_y(-64)
    local HOME_X, HOME_Y = 0, field_y(192)              -- 0 / 32
    local ENTRY_WAIT, ENTRY_TIME = 100, 30
    local EASE_OUT = VALUE_SET.DECEL

    local PHOTO_LIMIT = 6                               -- ins_141(6)
    local CARD_NAME = "死価「プライス・オブ・ライフ」"
    local CARD_TIME, CARD_HP = 50, 900
    local CARD_ID = 476

    local CHASE_AT = 2                                  -- ins_44(photoIndex, 2)
    local CHASE_SPEED = 0.3                             -- ins_65(playerAngle, 0.3)

    local RING_SPAWN_GAP = 80                           -- ins_38 的半径
    local BULLET_WAIT, BULLET_ACCEL_FRAMES = 20, 60     -- 两条 ins_101 的 int0
    local BULLET_SPEED0, BULLET_ACCEL_STEP = 0.2, 0.05  -- sp1 / f0（原作是 −0.05）

    local BIG_AT, BIG_COUNT, BIG_SPEED = 4, 10, 0.8     -- 第二个 CMPlt / 10 发圈 / 速
    local BIG_EVERY = 50                                -- intV1 ≥ 50（每 100 帧）

    local BOUNCE_AT, BOUNCE_COUNT, BOUNCE_SPEED = 2, 16, 1
    local BOUNCE_PERIOD = 100

    local lasers = {}
    local st = { dead = false }

    ---Sub4 的逐帧钩子：前 20 帧不动，之后 60 帧每帧 speed −= 0.05（方向仍取弹自己的 rot）。
    local function accel_hook(self)
        local n = (self.ex_wait or 0) + 1
        self.ex_wait = n
        if n <= BULLET_WAIT then return end
        if (self.ex_accel or 0) >= BULLET_ACCEL_FRAMES then return end
        self.ex_accel = (self.ex_accel or 0) + 1
        local v = (self.ex_v or BULLET_SPEED0) - BULLET_ACCEL_STEP
        self.ex_v = v
        object.SetV(self, v, self.rot, true)
    end

    ---Sub4：每 2 帧从「自机 ± 方向 base 上 80 px」处吐一颗倒着飘的慢弹。
    ---base0 是 TH095 空间的度（slot0 = −90°、slot1 = +90°）。
    local function sub4(owner, tok, base0)
        task.New(owner, function()
            local base = base0
            local n = 0
            while tok.alive and not st.dead do
                local sx = player.x + RING_SPAWN_GAP * cos(-base)
                local sy = player.y + RING_SPAWN_GAP * sin(-base)
                local color = (base0 > 0) and 2 or 1
                NewSimpleBullet(ball_small, ex_color(color), sx, sy, BULLET_SPEED0,
                        -base, false, 0, false, nil, nil, nil, accel_hook)
                PlaySound("tan00", 0.1, sx / 256, false)     -- flags 的 0x200
                if photo_index(PHOTO_LIMIT) >= BIG_AT and n >= BIG_EVERY then
                    local a0 = ran:Float(-math.pi, math.pi)
                    for i = 0, BIG_COUNT - 1 do
                        NewSimpleBullet(ball_small, ex_color(1), sx, sy, BIG_SPEED,
                                -math.deg(a0 + i * math.pi / 5), false, 0, false)
                    end
                    PlaySound("tan00", 0.1, sx / 256, false)
                    n = 0
                end
                n = n + 1
                base = base + 3                              -- floatV2 = 0.0523599 rad
                task.Wait(2)
            end
        end)
    end

    ---Sub6：每 100 帧（photoIndex ≥ 2 起）一圈 16 发**会撞墙**的弹。
    local function sub6(owner, tok)
        task.New(owner, function()
            while tok.alive and not st.dead do
                task.Wait(BOUNCE_PERIOD)
                if not tok.alive or st.dead then return end
                if photo_index(PHOTO_LIMIT) >= BOUNCE_AT then
                    local a0 = ran:Float(-math.pi, math.pi)
                    for i = 0, BOUNCE_COUNT - 1 do
                        NewSimpleBullet(ball_small, ex_color(0), owner.x, owner.y,
                                BOUNCE_SPEED, -math.deg(a0 + i * math.pi / 8),
                                false, 0, false, nil, true)      -- rebound = BOUNCE_ALL
                    end
                    PlaySound("tan00", 0.1, owner.x / 256, false)
                end
            end
        end)
    end

    local card = boss.card.New(CARD_NAME, 1, 3, CARD_TIME, CARD_HP)

    function card:before()
    end

    function card:init()
        photo_damage_on(self, PHOTO_LIMIT)
        self.x, self.y = BOSS_X, BOSS_START_Y
        st.dead = false
        task.New(self, function()
            task.Wait(ENTRY_WAIT)
            task.MoveTo(HOME_X, HOME_Y, ENTRY_TIME, EASE_OUT)
            local tok = { alive = true }
            task.Wait(60)                                   -- Sub3 的 t=0 → t=60
            sub4(self, tok, -90)                            -- slot0
            sub4(self, tok, 90)                             -- slot1
            sub6(self, tok)                                 -- slot2
            while tok.alive and not st.dead do
                if photo_index(PHOTO_LIMIT) >= CHASE_AT then
                    for _ = 1, 2 do                         -- ins_65 每 2 帧重取一次方向
                        local a = Angle(self.x, self.y, player.x, player.y)
                        self.x = self.x + CHASE_SPEED * cos(a)
                        self.y = self.y + CHASE_SPEED * sin(a)
                        task.Wait(1)
                        if not tok.alive or st.dead then return end
                    end
                else
                    task.Wait(1)
                end
            end
        end)
    end

    function card:frame()
    end

    function card:del()
        st.dead = true
        photo_damage_off(self)
        sg_clear(lasers)
    end

    boss.card.add({ { card, "7a" } }, LEVEL, CARD_NAME, CARD_ID)
end--死価「プライス・オブ・ライフ」

do  -- 97 審判「浄頗梨審判　-射命丸文-」（ecl21_d，映姬，组 8a 第 4 张）
    ---映姬这张符卡是「本体在活动框里打点射」+「拍够照片后本体改成沿左右边缘上下扫」的两段式。
    ---数据源 /tmp/S9_ecl21_d.txt（ECL …/data/ecl21_d.ecl）。骨架：
    ---  · Sub2：ins_55(2) + ins_81(3) + ins_109(0) + ins_77(24,24) + ins_141(9)（拍 9 张）
    ---    + ins_108(0,31)/ins_108(1,30) + ins_143(1,9000) + ins_63(-128,-64) 进场；
    ---    **ins_115(0,3,7)** / **ins_115(1,6,8)** 是整张卡的分段开关。ins_115 在
    ---    EnemyManagerUpdate.cpp:1283-1300 里做的是
    ---    `TH095_PHOTO_ECL_INIT(..., &enemy->mainEclContext, subId)`，
    ---    即**把本体的主 ECL 整个重启到另一个 sub**（不是新开并行上下文）；比较的帧号是
    ---    g_PhotoEnemyGame->frameCounter = camera.photoIndex ⇒「拍中第 3 张时本体切成 Sub7、
    ---    拍中第 6 张时切成 Sub8」，Sub3 随之被丢弃。
    ---    t=100 ins_64(30,4,0,128) 落到 (0,128)（我们的 (0,96)）；t=130 停 ANM + ins_132(1)
    ---    + ins_52(3)（同步调用 Sub3；Sub3 自带 ins_4(90,-1168) 死循环 ⇒ 本体此后一直跑 Sub3）。
    ---  · Sub3（@708 起，跳回 @1036 的 t=90 ⇒ **742 帧一轮**）：
    ---      t=90  ins_75(-128,96,128,144) 设活动框 + ins_143(0,0) + 起装饰上下文 Sub6
    ---      t=150/200/250 各起一次 Sub4，每次只活 30 帧（t=180/230/280 被 ins_117(0,-1) 杀掉）；
    ---            同一刻 ins_67(30,4,5) 让本体在框里「背离自机」随机走 30 帧 × 5 px
    ---      t=340/380/420 三次：ins_76 清框 → ins_88 CIRCLE_AIMED 48 发自机狙整圈（速 2）
    ---            → ins_64(40,4,player.x,player.y) 用 40 帧贴向自机（非阻塞，每 40 帧重取目标）
    ---      t=520 起 Sub5（活到 t=610，共 90 帧）
    ---      t=670/710/750 三次：ins_86 FAN_AIMED 4 组 × 8 颗自机狙扇（速 6→1、步长 5.625°）
    ---            → 继续贴向自机
    ---      t=790 ins_64(40,4,0,144) 回场中 → t=830 重新设框 → t=832 跳回 t=90
    ---  · Sub4（@2236，每 2 帧一轮、**一直转**直到被 ins_117 杀掉）：
    ---      a) ins_89 CIRCLE(型 7=ball_small、色 2、count1=1、count2=10、速 8→1、
    ---         角 = **Sub4 启动那一刻**的 playerAngle —— 操作数 pm=0040 是 float 变量，
    ---         循环里不再重取）⇒ 每 2 帧沿一条固定射线吐 10 颗「同向不同速」的弹。
    ---      b) ins_88 CIRCLE_AIMED(型 7、色 2、count1=6、count2=1、速 2、基准 π、
    ---         步长 11.25°)⇒ 6 颗**背对自机**的弹（自机角 + 180° + k·60°）。
    ---      c) 夹在 a) 与 b) 之间的 ins_101(0, 0x80 CHDIR_AIMED, allow=0, i0=30, i1=1,
    ---         f0=rand(−π,π)·16, f1=6)：弹是**发弹那一刻**把 transform 槽整份抄走的
    ---         （BulletManager.cpp:484 的 memcpy），所以只有后面那组 b) 抄到了它；
    ---         而 b) 的 flags=642=0x282 里含 0x80、a) 的 flags=514=0x202 里没有 ⇒
    ---         只有 b) 会真的吃这条变换（BulletManager.cpp:523 的
    ---         `(transformFlags & record->kind) == 0` 闸）。效果见
    ---         BulletManager.cpp:929-965 UpdateAimedDirectionChange：此后 30 帧速度从 2 线性
    ---         降到 0（方向不变），第 31 帧把角改成 playerAngle(弹的位置)+f0、速度改成 6
    ---         再飞出去。
    ---  · Sub5（@2452，每 4 帧一轮、活 90 帧）：ins_89 CIRCLE(型 15=ball_mid、色 1、
    ---      count1=32、速 4、角 = floatV0)。floatV0 在 **Sub5 启动那一刻**取 playerAngle，
    ---      之后每轮 +5.625°（ins_15 后接 ins_37）⇒ 32 发整圈每 4 帧转 5.625°。
    ---      （Sub5 自己的 ins_101 写的也是 0x80，但 89 的 flags 里没有 0x80 ⇒ 不生效。原作死数据。）
    ---  · Sub7（@2732，拍中第 3 张后接管本体）：ins_102 清屏 → 40 帧落到 (0,144) →
    ---      循环（t=60..142，82 帧）：floatV0 += rand·floatV1，出 [64,448] 就翻向；
    ---      ins_64(30,4,∓192,floatV0) 30 帧横移到左/右边缘；ins_94 RANDOM(型 7、色 2、
    ---      count1=32、速 0.5..2、角 ∈ [90°,270°]) 撒 32 颗。
    ---      ⇒ 本体贴着左右边缘上下扫，每次到边撒一把（第一把在 (0,144)）。
    ---  · Sub8（@3500，拍中第 6 张后接管本体）：ins_102 → 40 帧落到 (0,144) →
    ---      循环（t=60..310，250 帧）：t=120 起 Sub5 90 帧 → t=270 ins_64(40,4,自机) 贴向
    ---      自机 40 帧 → 回 t=60。
    ---  · Sub6/Sub9 是装饰 ANM 与进场子机；Sub0/Sub1 是死亡/退场 ⇒ 不实现（见文件头差异 3）。
    local BOSS_X, BOSS_START_Y = -128, field_y(-64)
    local HOME_X, HOME_Y = 0, field_y(128)              -- (0,128) → (0,96)
    local ENTRY_WAIT, ENTRY_TIME = 100, 30
    local EASE_OUT = VALUE_SET.DECEL

    local PHOTO_LIMIT = 9                               -- ins_141(9)
    local CARD_NAME = "審判「浄頗梨審判　-射命丸文-」"
    local CARD_TIME, CARD_HP = 50, 900
    local CARD_ID = 477

    local LOOP_AT = 90                                  -- Sub3 的 ins_4 跳回处（t=90）
    local BOX = { -128, 96, 128, 144 }                  -- ins_75(-128,96,128,144)
    local WALK_FRAMES, WALK_SPEED = 30, 5               -- ins_67(30,4,5)
    local DASH_FRAMES = 40                              -- ins_64(40,4,...)
    local EASE_INOUT = 4                                -- ins_64/67 的缓动编号

    local RUSH_COUNT, RUSH_SPEED = 48, 2                -- ins_88(…48,1,2,1,0,0,514)
    local FAN_GROUP, FAN_SPEED1, FAN_SPEED2 = 4, 6, 1   -- ins_86(…4,8,6,1,0,0.0981748,514)
    local FAN_STEP_DEG = 5.625                          -- 0.0981748 rad

    local RING_COUNT, RING_SPEED = 32, 4                -- Sub5 的 ins_89
    local RING_STEP_DEG = 5.625                         -- Sub5 每轮 +0.0981748 rad

    local SUB4_RAY_COUNT, SUB4_RAY_SPEED0, SUB4_RAY_SPEED1 = 10, 8, 1
    local SUB4_BACK_COUNT, SUB4_BACK_SPEED = 6, 2       -- Sub4 b) 的 ins_88
    local SUB4_BACK_STEP_DEG = 11.25                    -- 0.19635 rad
    local CHDIR_FRAMES, CHDIR_SPEED = 30, 6             -- ins_101 的 i0 / f1
    local SUB4_GAP = 2                                  -- Sub4 的 ins_4(0,-152)

    local BURST_COUNT, BURST_SPEED1, BURST_SPEED2 = 32, 2, 0.5   -- Sub7 的 ins_94
    local SPRAY_A = { 90, 270 }                         -- 到左边缘那一下：角 ∈ [90°,270°]
    local SPRAY_B = { -90, 90 }                         -- 到右边缘那一下：角 ∈ [−90°,90°]
    local SWEEP_SPEED_FRAMES = 30                       -- ins_64(30,4,∓192,…)
    local SWEEP_MIN, SWEEP_MAX, SWEEP_DELTA = 64, 448, 64

    local lasers = {}
    local st = { dead = false }
    local gen = 0                                       -- 本体当前主脚本代号（ins_115 会 +1）
    local fired = { false, false }

    local function alive(g, tok)
        return g == gen and not st.dead and (tok == nil or tok.alive)
    end

    local function kill_move()
        if st.mv then
            st.mv.alive = false
            st.mv = nil
        end
    end

    ---ins_64 的逐帧插值（非阻塞；这里和调用者在同一条协程里顺序走完）。
    local function glide(owner, g, tx, ty, n)
        local x0, y0 = owner.x, owner.y
        local f = sg_ease(EASE_INOUT)
        for s = 1, n do
            if not alive(g) then return false end
            local p = f(s / n)
            owner.x, owner.y = x0 + p * (tx - x0), y0 + p * (ty - y0)
            task.Wait(1)
        end
        return true
    end

    ---Sub4 c)：CHDIR_AIMED 的逐帧钩子。f0_deg 是 TH095 空间的角度（度）。
    ---第 1..30 帧速度从 2 线性降到 0（方向不变），第 31 帧重新瞄准自机 + f0、速度 6。
    local function chdir_hook(f0_deg)
        return function(self)
            local n = (self.ex_chdir or 0) + 1
            self.ex_chdir = n
            if n <= CHDIR_FRAMES then
                local v = SUB4_BACK_SPEED * (1 - (n - 1) / CHDIR_FRAMES)
                object.SetV(self, v, self.rot, true)
            elseif n == CHDIR_FRAMES + 1 then
                local a = Angle(self.x, self.y, player.x, player.y) - f0_deg
                object.SetV(self, CHDIR_SPEED, a, true)
            end
        end
    end

    ---Sub4：每 2 帧一轮的两组点射（见块顶注释 a/b/c）。
    local function sub4(owner, g, tok)
        task.New(owner, function()
            local aim = sg_aim(owner.x, owner.y)
            while alive(g, tok) do
                sg_shot(89, ball_small, ex_color(2), owner.x, owner.y,
                        1, SUB4_RAY_COUNT, SUB4_RAY_SPEED0, SUB4_RAY_SPEED1,
                        aim, 0, false, 514)
                local f0 = math.deg(ran:Float(-math.pi, math.pi) * 16)
                local a0 = sg_aim(owner.x, owner.y) + 180
                for i = 0, SUB4_BACK_COUNT - 1 do
                    NewSimpleBullet(ball_small, ex_color(2), owner.x, owner.y,
                            SUB4_BACK_SPEED, -(a0 + i * (360 / SUB4_BACK_COUNT)),
                            false, 0, false, nil, nil, nil, chdir_hook(f0))
                end
                PlaySound("tan00", 0.1, owner.x / 256, false)   -- flags 642 的 0x200
                task.Wait(SUB4_GAP)
            end
        end)
    end

    ---Sub5：每 4 帧一圈 32 发，基准角每轮 +5.625°。
    local function sub5(owner, g, tok)
        task.New(owner, function()
            local base = sg_aim(owner.x, owner.y)
            while alive(g, tok) do
                sg_shot(89, ball_mid, ex_color(1), owner.x, owner.y,
                        RING_COUNT, 1, RING_SPEED, 1, base, 0, false, 514)
                base = base + RING_STEP_DEG
                task.Wait(4)
            end
        end)
    end

    ---Sub7 的一把 32 发 RANDOM：base/step 就是原作的 angle/angleStep（TH095 度）。
    local function burst(owner, base_deg, step_deg)
        sg_shot(94, ball_small, ex_color(2), owner.x, owner.y,
                BURST_COUNT, 1, BURST_SPEED1, BURST_SPEED2, base_deg, step_deg,
                false, 514)
    end

    ---Sub7：接管本体后贴左右边缘上下扫，到边撒一把（见块顶注释）。
    local function run_sub7(owner, g)
        task.New(owner, function()
            sg_clear(lasers)
            if not glide(owner, g, 0, field_y(144), DASH_FRAMES) then return end
            task.Wait(20)                                   -- t=40 → t=60
            local v0, v1 = 144, SWEEP_DELTA
            while alive(g) do
                v0 = v0 + ran:Float(0, 1) * v1
                if v0 > SWEEP_MAX then v1 = -SWEEP_DELTA end
                if v0 < SWEEP_MIN then v1 = SWEEP_DELTA end
                PlaySound("tan00", 0.1, owner.x / 256, false)   -- ins_106(15)
                burst(owner, SPRAY_A[1], SPRAY_A[2])
                if not glide(owner, g, -192, field_y(v0), SWEEP_SPEED_FRAMES) then return end
                task.Wait(10)                                   -- t=60 → t=100
                if not alive(g) then return end
                v0 = v0 + v1
                v0 = v0 + ran:Float(0, 1) * v1
                if v0 > SWEEP_MAX then v1 = -SWEEP_DELTA end
                if v0 < SWEEP_MIN then v1 = SWEEP_DELTA end
                PlaySound("tan00", 0.1, owner.x / 256, false)
                burst(owner, SPRAY_B[1], SPRAY_B[2])
                if not glide(owner, g, 192, field_y(v0), SWEEP_SPEED_FRAMES) then return end
                task.Wait(12)                                   -- t=100 → t=142 → 回 t=60
            end
        end)
    end

    ---Sub8：接管本体后循环「Sub5 90 帧 → 贴向自机 40 帧」（见块顶注释）。
    local function run_sub8(owner, g)
        task.New(owner, function()
            sg_clear(lasers)
            if not glide(owner, g, 0, field_y(144), DASH_FRAMES) then return end
            task.Wait(20)                                   -- t=40 → t=60
            while alive(g) do
                local tok = { alive = true }
                task.Wait(60)                               -- t=60 → t=120
                if not alive(g) then tok.alive = false; return end
                sub5(owner, g, tok)
                task.Wait(90)                               -- t=120 → t=210
                tok.alive = false
                if not alive(g) then return end
                task.Wait(60)                               -- t=210 → t=270
                if not alive(g) then return end
                PlaySound("tan00", 0.1, owner.x / 256, false)   -- ins_106(15)
                glide(owner, g, player.x, player.y, DASH_FRAMES)     -- t=270 → t=310
            end
        end)
    end

    ---Sub3：默认主循环（742 帧一轮，见块顶注释）。
    local function run_sub3(owner, g)
        task.Wait(LOOP_AT)                                  -- Sub3 t=0 → t=90
        while alive(g) do
            local tok = { alive = true }
            task.Wait(60)                                   -- t=90 → t=150
            for k = 1, 3 do
                if not alive(g) then return end
                sub4(owner, g, tok)                         -- ins_117(0,4)
                sg_bmove(owner, st, WALK_FRAMES, EASE_INOUT, WALK_SPEED, BOX)
                task.Wait(WALK_FRAMES)                      -- → t=180 / 230 / 280
                tok.alive = false                           -- ins_117(0,-1)
                if k == 3 then break end
                task.Wait(20)                               -- → t=200 / 250
                tok = { alive = true }
            end
            if not alive(g) then return end
            task.Wait(60)                                   -- t=280 → t=340
            for _ = 1, 3 do                                 -- t=340 / 380 / 420
                if not alive(g) then return end
                sg_move(owner, st, player.x, player.y, DASH_FRAMES, sg_ease(EASE_INOUT))
                PlaySound("tan00", 0.1, owner.x / 256, false)   -- ins_106(15)
                sg_shot(88, ball_small, ex_color(6), owner.x, owner.y,
                        RUSH_COUNT, 1, RUSH_SPEED, 1, 0, 0, true, 514)
                task.Wait(DASH_FRAMES)
            end
            if not alive(g) then return end
            task.Wait(60)                                   -- t=460 → t=520
            local tok5 = { alive = true }
            sub5(owner, g, tok5)                            -- ins_117(0,5)
            task.Wait(90)                                   -- t=520 → t=610
            tok5.alive = false
            if not alive(g) then return end
            task.Wait(60)                                   -- t=610 → t=670
            for _ = 1, 3 do                                 -- t=670 / 710 / 750
                if not alive(g) then return end
                sg_move(owner, st, player.x, player.y, DASH_FRAMES, sg_ease(EASE_INOUT))
                PlaySound("tan00", 0.1, owner.x / 256, false)
                sg_shot(86, ball_small, ex_color(6), owner.x, owner.y,
                        FAN_GROUP, 8, FAN_SPEED1, FAN_SPEED2, 0, FAN_STEP_DEG, true, 514)
                task.Wait(DASH_FRAMES)
            end
            if not alive(g) then return end
            sg_move(owner, st, 0, field_y(144), DASH_FRAMES, sg_ease(EASE_INOUT))  -- t=790
            PlaySound("tan00", 0.1, owner.x / 256, false)
            task.Wait(DASH_FRAMES)                          -- → t=830
            task.Wait(2)                                    -- → t=832，回 t=90
        end
    end

    ---ins_115 的两条定时调用 → 主脚本切换（见块顶注释）。
    local function watch(owner)
        task.New(owner, function()
            while not st.dead do
                local hits = photo_index(PHOTO_LIMIT)
                if hits >= 3 and not fired[1] then
                    fired[1] = true
                    kill_move()
                    gen = gen + 1
                    run_sub7(owner, gen)
                elseif hits >= 6 and not fired[2] then
                    fired[2] = true
                    kill_move()
                    gen = gen + 1
                    run_sub8(owner, gen)
                end
                task.Wait(1)
            end
        end)
    end

    local card = boss.card.New(CARD_NAME, 1, 3, CARD_TIME, CARD_HP)

    function card:before()
    end

    function card:init()
        photo_damage_on(self, PHOTO_LIMIT)
        self.x, self.y = BOSS_X, BOSS_START_Y
        gen = gen + 1
        st.dead = false
        watch(self)
        task.New(self, function()
            task.Wait(ENTRY_WAIT)
            task.MoveTo(HOME_X, HOME_Y, ENTRY_TIME, EASE_OUT)
            run_sub3(self, gen)
        end)
    end

    function card:frame()
    end

    function card:del()
        st.dead = true
        kill_move()
        photo_damage_off(self)
        sg_clear(lasers)
    end

    boss.card.add({ { card, "8a" } }, LEVEL, CARD_NAME, CARD_ID)
end--審判「浄頗梨審判　-射命丸文-」

---──────────────────── Stage 8（scene group 8 = world09）── 公共工具 ────────────────────
---下面八张卡（scene 80..87）共用 world09（永遠亭）与 enm18/19.anm。
---数据源是 /tmp/S8_ecl18_{a..d}.txt 与 /tmp/S8_ecl19_{a..d}.txt（ECL 在
---`[th095] …/data/ecl1{8,9}_*.ecl`，与 th095/src 对照着读），各卡注释里的「@地址」
---都指这几份 dump。色表 ex_color、ins_145/147 的激光工具、sg_shot / sg_move /
---sg_bmove 都在上面 Stage EX 与 Stage 9 两段里（同一套），这一段新加的只有
---ins_101 的「弹变换」。

---ins_101 的一条记录，对应 TH095 的 BulletTransformRecord
---（th095/src/BulletManager.hpp:15-60 的 payload 布局：float0/float1/int0/int1
---依次叠放，含义随 kind 变）。world09 用到的那几种：
---  0x10  ACCEL_VEC   f0 = 每帧加速度大小、f1 = 加速度方向（度；≤ −990 ⇒ 用弹当前角，原作用 −999.99）、i0 = 持续帧
---  0x20  ACCEL_POLAR f0 = 每帧速度增量、f1 = 每帧角度增量（弧度）、i0 = 持续帧
---  0x100 CHDIR_ABS   f0 = 到点后的角（弧度）、f1 = 到点后的速（−999 ⇒ 用当前速）、
---                    i0 = 间隔帧、i1 = 重复次数
---  0x400 BOUNCE_ALL  f0 = 反弹后速度（<0 ⇒ 用当前值）、i0 = 反弹次数上限
---  0x8000 WAIT       i0 = 原地等待的帧数（等完才轮到下一条记录）
---★ dump 工具会把 f0/f1 的语义标反（ecl18_a 的 @880 被标成 f0=−0.0614286 是「角度」）：
---  上面这张表是照 Payload union 的叠放 + BulletManager.cpp 的 Update* 读出来的。
---
---★★ 一个必须记住的坑：文件里有两套**不一样**的「变换 kind 编号」，别抄错：
---  · `src/PhotoBulletSpawnDescriptor.hpp:85` 的 PhotoBulletTransformKind —— **这才是真机
---    编译进 BulletManager.cpp 的那一套**（BulletManager.cpp:3 include 的是
---    PhotoBulletManager.hpp → PhotoBulletSpawnDescriptor.hpp）。WAIT = 0x8000、
---    SET_SPRITE = 0x4000、WRAP_X = 0x100000、SPAWN_CHILD_PATTERN = 0x400000、
---    JUMP = 0x2000000。**ECL 里的 operand 就是按这一套写的**（ecl14_a 的 @2540 写
---    「kind=32768、int0=20」＝等 20 帧，只有 0x8000 说得通）。
---  · `src/BulletManager.hpp:155` 的 BulletTransformKind 是**TH08 那边的**命名表
---    （多插了 ONLY_WHEN_PLAYER_YOUKAI/HUMAN 两位），WAIT 被写成 0x20000、
---    SPAWN_CHILD 写成 0x1000000 —— 和 ECL 数据对不上，**不要照它写**。
---    （EclRunTargetHigh.inl 只是 WriteInt 把 operand 存进 slot->kind，不解释它，
---    所以那份表命不命名都无所谓。）
---下面新增的五个都按 PhotoBulletSpawnDescriptor.hpp 的编号。
local SG_VEC, SG_POLAR, SG_CHDIR_A, SG_BOUNCE, SG_WAIT =
        0x10, 0x20, 0x100, 0x400, 0x8000
local SG_CHDIR_R, SG_BOUNCE_EB, SG_SET_SPRITE, SG_CHILD, SG_JUMP =
        0x40, 0x800, 0x4000, 0x400000, 0x2000000
---0x1000000 SET_OWNER_TAG（PhotoBulletSpawnDescriptor.hpp:109 / BulletManager.cpp:681）：
---把这条弹的 ownerTag 记成 payload.int0。**即时执行、不占 active**（C 里执行完
---`goto nextRecord` 接着找下一条）—— Stage 4 的「按 tag 重新瞄准」（ins_118(2)/(4)
---的回调）就靠它。
local SG_TAG = 0x1000000
---0x1 DECELERATE（PhotoBulletSpawnDescriptor.hpp:79 / BulletManager.cpp:780-796）：
---出生后 17 帧里把「多出来的 5 px/帧」线性收掉（velocity = from_angle(angle,
---(5 − 5·timer/16) + speed)），payload 完全不用（ECL 里 i0/i1/f0/f1 全是 −1 的占位）。
---Stage 2/1 的 ins_101 表头几乎都是这一条。
local SG_DECEL = 0x1
---0x2000 SET_CULL_DELAY（同文件 :607-612）：即时记录，只改「弹出屏后延迟几帧回收」。
---本仓库的回收边界由引擎统一管（文件头差异 3）⇒ 认掉即走，什么都不做。
local SG_CULL = 0x2000
---0x20000 PLAY_SOUND（同文件 :625-631）：即时记录，按 payload.soundIndex 在弹的位置
---响一声。本仓库的音效都是各卡自己的 sg_snd / PlaySound 口径，没有「按 TH095 音效
---表下标播」这一层 ⇒ 认掉即走（音效差异记在各卡注释里）。
local SG_SND_T = 0x20000

---★ C 里各条变换的更新顺序是**按 flag 位**（BulletManager.cpp:1448-1473：
---0x1 → 0x10 → 0x20 → 0x40 → 0x80 → 0x100 → 0x400/0x800 → 0x8000），和记录被认领的
---先后无关。sg_tr_hook 的 acts 表按这个优先级排，② 从头跑一遍即与原作同序。
local SG_PRIORITY = {
    [0x1] = 1, [0x10] = 2, [0x20] = 3, [0x40] = 4, [0x80] = 5, [0x100] = 6,
    [0x400] = 7, [0x800] = 7, [0x8000] = 8,
}

---@param kind number 位掩码（同时也是「这条记录能不能被这颗弹吃」的判据，见 sg_tr_hook）
---@param allow number 操作数 2（allowWhileActive），world09 全是 0
local function sg_rec(kind, allow, i0, i1, f0, f1)
    return { kind = kind, allow = allow, i0 = i0, i1 = i1, f0 = f0, f1 = f1 }
end

---flags & kind ~= 0。flags 一直是 32 位掩码里的小值，整数除比拉 bit 库省事，
---也和上面 sg_snd 的写法一致（那里是 math.floor(flags / 0x200) % 2）。
local function sg_has(flags, kind)
    return math.floor(flags / kind) % 2 == 1
end

---TH095 的弧度角（或角增量）→ 我们的度，取反（见文件头「坐标系与角度」）。
local function sg_deg(th_rad)
    return -math.deg(th_rad)
end

---TH095 的弹变换程序（PhotoBulletView::AdvanceTransformProgram + 每帧 Update*，
---BulletManager.cpp:512-693 与 :1447-1470）。三条要点：
---  ① 发弹那一刻整份记录表被**抄给弹**（同文件 :486），所以「先 ins_101 写表、
---     紧接着 ins_86..94 发弹」是一对，写卡的顺序不能动；
---  ② flags 里没有的 kind 会被跳过（:525）；`kind == 0` 的记录（表尾的空槽）直接结束；
---  ③ 每应用一条就 transformIndex++（:694），而记录还在生效（active != 0）时
---     allow == 0 的后续记录会被挡住（:523）⇒ 表里的记录是**严格按顺序逐条生效**的。
---     0x8000 WAIT 就是靠这一条「先等 i0 帧、再走后面的记录」。
---recs 里的角度/角增量一律用**我们的口径**（度、逆时针为正），由 sg_deg / sg_rec 换算好。
local function sg_tr_hook(recs, flags, start)
    local n = #recs
    return function(self)
        local st = self.sg_tr
        if not st then
            ---start = 第几条记录起跑（0-based 的 transformStartIndex + 1）。生下来的
            ---子弹只吃「父弹记录表里从 transformStartIndex 起」的那一段（见 SG_CHILD）,
            ---所以这里必须能指定起点；不传就是 1（整张表从头跑）。
            ---acts = 当前**同时**生效的记录表（C 里 activeTransformFlags 是位掩码，允许多条
            ---并存：allowWhileActive == 1 的记录可以和前一条一起跑，见文件里的 ①②）。
            st = { i = start or 1, acts = {} }
            self.sg_tr = st
        end
        ---① AdvanceTransformProgram：找下一条能吃的记录。
        ---★ 应用一条就要把索引 +1（C 里是 BulletManager.cpp:694 的
        ---  PhotoBulletAdvanceTransformPhase）—— 不然这条记录走完的下一帧会被**重新应用**
        ---  一遍，一张 70 帧的减速会被无限叠下去（弹速一路减到 0 卡在原地）。
        ---★ C 一帧只认领一条「占时间」的记录（认领完 switch 就 break，下一帧再从下一条
        ---  继续）；即时记录（SET_SPRITE / SET_OWNER_TAG / JUMP / SPAWN_CHILD）当场
        ---  处理完接着往下找。
        ---★ 停条的判据是「有记录在生效 且 这条的 allowWhileActive == 0」（:523）——
        ---  allow == 1 的记录可以和前一条**同时**生效（Stage 4 的 BOUNCE_NOBOT + POLAR
        ---  就是这一种），所以生效中的记录改用一张表 acts 存，不再只留一条。
        ---★ C 的表长只有 18 条（:519 的 `transformIndex >= 18` 就收工），这里照做。
        while st.i <= n and st.i <= 18 do
            local r = recs[st.i]
            if r.kind == 0 then
                st.i = n + 1               -- kind == NONE ⇒ 程序到此结束（:521）
                break
            end
            if r.allow == 0 and #st.acts > 0 then break end
            if not sg_has(flags, r.kind) then
                st.i = st.i + 1
            elseif r.kind == SG_SET_SPRITE then
                ---0x4000 SET_SPRITE：把弹的贴图/色号换成 payload.int0/int1
                ---（BulletManager.cpp:617-622）。**立即执行、不占 active**，执行完
                ---接着找下一条（C 里的 `goto nextRecord`）。本仓库的弹在 New 出来之后
                ---没有「半路换贴图」的接口，ecl14_a 的 Sub9 又只是把型 14 的色 3 换成
                ---色 5（同型同尺寸，只有颜色差），所以这里**不实现**，只按原样跳过。
                st.i = st.i + 1
            elseif r.kind == SG_CULL or r.kind == SG_SND_T then
                ---0x2000 SET_CULL_DELAY / 0x20000 PLAY_SOUND：都是**即时**记录
                ---（认领完 `goto nextRecord` 接着找下一条），不占 active。
                st.i = st.i + 1
            elseif r.kind == SG_TAG then
                ---0x1000000 SET_OWNER_TAG：把这颗弹的 ownerTag 记下来（payload.int0）。
                ---即时记录、不占 active；Stage 4 的 ins_118(2)/(4) 回调按 tag 重新瞄准时
                ---要用（见 sg_callback）。本卡不实现时也照原样走过。
                self.sg_tag = r.i0
                st.i = st.i + 1
            elseif r.kind == SG_JUMP then
                ---0x2000000 JUMP：把 transformIndex 直接设成 payload.int0，重新取那条
                ---（BulletManager.cpp:676-678）。ecl15_b 用它做「发一颗子弹 → 极坐标加速
                ---duration 帧 → 跳回第 0 条」的循环（int0=0）。
                st.i = r.i0 + 1
            elseif r.kind == SG_CHILD then
                ---0x400000 SPAWN_CHILD_PATTERN（BulletManager.cpp:639-675）：**这一条
                ---要连着吃掉后面一条**（第二条的 payload 是 secondary：count2 /
                ---transformFlags / angle / angleStep）。第一条的 packedPattern 位域：
                ---   bit31    fadeParent（放完就自己淡出 —— 见下面的 object.RawDel）
                ---   bit30..24 aimMode（0..8，就是 ins_86..94 的 86+aimMode）
                ---   bit23..16 bulletType
                ---   bit15..8  color
                ---   bit7..0   transformStartIndex（子弹从第几条记录起跑）
                ---子弹表整个 memcpy 给子弹，所以子弹的 recs 就是父弹这张表。
                local sec = recs[st.i + 1]
                local u = r.i0 % 0x100000000
                local aim = math.floor(u / 0x1000000) % 0x80
                local btype = math.floor(u / 0x10000) % 0x100
                local bcolor = math.floor(u / 0x100) % 0x100
                local sidx = u % 0x100
                local c1 = r.i1
                local c2 = sec and sec.i0 or 1
                local cflags = sec and sec.i1 or 0
                local base = sec and sec.f0 or 0
                local step = sec and sec.f1 or 0
                local hook = sg_tr_hook(recs, cflags, sidx + 1)
                sg_shot(86 + aim, sg_style(btype), ex_color(bcolor), self.x, self.y,
                        c1, c2, r.f0, r.f1, math.deg(base), math.deg(step),
                        false, cflags, hook)
                st.i = st.i + 2
                ---bit31 fadeParent：BulletManager.cpp:661-664 放完子弹出后
                ---BeginDespawn 自己（lua 侧就是 object.RawDel，和原作一致）。
                if math.floor(u / 0x80000000) % 2 == 1 then
                    object.RawDel(self)
                end
            else
                ---要吃时间的记录：先记进 acts（本帧就按 ② 跑一次）。
                local a = { kind = r.kind, r = r, timer = 0 }
                if r.kind == SG_DECEL then
                    ---BulletManager.cpp:780-796 用的是弹自己的 `speed` 字段（出生速度）
                    ---⇒ 认领那一刻记下当前速度与方向（DECEL 总是表头第一条，此刻两者就是
                    ---出生值）；payload 不参与。
                    a.spd = GetV(self)
                    a.ang = self.rot
                elseif r.kind == SG_WAIT then
                    a.timer = r.i0
                elseif r.kind == SG_CHDIR_A or r.kind == SG_CHDIR_R then
                    a.left = r.i1
                    ---★ C 的减速基准是**弹当前的速度**（UpdateAbsoluteDirectionChange
                    ---  BulletManager.cpp:908-914 的 this->speed），f1 只决定「到点之后」
                    ---  把速度设成多少 ⇒ 应用这条时先存当前速、到点那一帧才用 f1 覆盖。
                    ---  （旧写法把 st.spd 直接设成 f1，等于把 8 的初速当 1 去减，
                    ---  整条减速轨迹会缩成 1/8。）
                    a.spd = GetV(self)
                elseif r.kind == SG_POLAR then
                    a.spd = GetV(self)
                elseif r.kind == SG_VEC then
                    ---★ 0x10 的加速度方向取**这条记录被应用那一刻**的弹角
                    ---  （BulletManager.cpp:543-546：accelerationAngle ≤ −990 时存下当时的
                    ---  this->angle，之后这个矢量就固定不动）。必须在这里存一次：
                    ---  原作 C 里 accelerationAngle 是 exStates 里的常量，弹被减到速度
                    ---  过零、开始倒退时它不会跟着弹角翻向；若每帧现读 self.rot，弹一
                    ---  倒退就把加速度也翻 180°，会在原地来回抖（卡 494 的 −1/24×120
                    ---  正好让 4→−1，第一次踩到这个坑）。
                    a.vecA = (r.f1 > -990) and r.f1 or self.rot
                elseif r.kind == SG_BOUNCE or r.kind == SG_BOUNCE_EB then
                    a.hits = 0
                end
                ---★ C 里各条变换的更新顺序是**按 flag 位**（0x1 → 0x10 → 0x20 → 0x40 →
                ---  0x80 → 0x100 → 0x400/0x800 → 0x8000，见 :1448-1473），与认领顺序无关
                ---  ⇒ 插进 acts 时按这个优先级排好，② 从头跑一遍就与原作同序（Stage 4 的
                ---  BOUNCE_NOBOT + POLAR 两颗若同帧都动手，顺序反了会差一帧）。
                local pri = SG_PRIORITY[r.kind] or 99
                local pos = #st.acts + 1
                for k = 1, #st.acts do
                    if (SG_PRIORITY[st.acts[k].kind] or 99) > pri then
                        pos = k
                        break
                    end
                end
                table.insert(st.acts, pos, a)
                st.i = st.i + 1
                break
            end
        end
        ---② 逐条跑生效中的记录（和 C 一样：认领的同帧就跑一次）。
        ---★ 必须**从前往后**（1 → #acts），顺序已在 ① 里按 flag 位排好。
        local dirty = false
        for k = 1, #st.acts do
            local a = st.acts[k]
            local r = a.r
            local done = false
            if a.kind == SG_DECEL then
                ---BulletManager.cpp:780-796：timer 0..16 逐帧把弹速压回出生速度
                ---（多出来那 5 px/帧线性归零），timer 到 17 就收掉这条记录。
                if a.timer > 16 then
                    done = true
                else
                    object.SetV(self, (5 - 5 * a.timer / 16) + a.spd, a.ang, true)
                end
                a.timer = a.timer + 1
            elseif a.kind == SG_POLAR then
                if a.timer >= r.i0 then
                    done = true
                else
                    a.ang = (a.ang or self.rot) + r.f1
                    a.spd = a.spd + r.f0
                    object.SetV(self, a.spd, a.ang, true)
                end
                a.timer = a.timer + 1
            elseif a.kind == SG_VEC then
                if a.timer >= r.i0 then
                    done = true
                else
                    ---BulletManager.cpp:543-546：f1 ≤ −990 时用**这条记录被应用那一刻**的弹角
                    ---（原作写 −999.99）⇒ 弹沿自己出生方向加速，各自成一条直线。
                    local aa = a.vecA
                    self.vx = self.vx + r.f0 * cos(aa)
                    self.vy = self.vy + r.f0 * sin(aa)
                    self.rot = Angle(0, 0, self.vx, self.vy)
                end
                a.timer = a.timer + 1
            elseif a.kind == SG_CHDIR_A or a.kind == SG_CHDIR_R then
                if a.timer >= r.i0 then
                    a.left = a.left - 1
                    if a.left <= 0 then done = true end
                    a.spd = (r.f1 > -999) and r.f1 or a.spd
                    ---0x100 CHDIR_ABS 把角**设成** f0；0x40 CHDIR_REL 则是**加上** f0
                    ---（UpdateAbsoluteDirectionChange :895 / UpdateRelativeDirectionChange :849）。
                    ---f0 已经是我们的度数（sg_rec 的调用方用 sg_deg 换过，取反了）。
                    self.rot = (a.kind == SG_CHDIR_R) and (self.rot + r.f0) or r.f0
                    object.SetV(self, a.spd, self.rot, true)
                    a.timer = 0
                else
                    ---BulletManager.cpp:864-869 / :908-914：间隔内速度从当前值线性减到 0
                    ---（方向不变，所以看起来像「滑到几乎停住、再拐弯重新加速」）。
                    object.SetV(self, a.spd * (1 - a.timer / r.i0), self.rot, true)
                end
                a.timer = a.timer + 1
            elseif a.kind == SG_WAIT then
                ---BulletManager.cpp:1468-1473：timer ≤ 0 才收掉这个变换，否则每帧 −1
                if a.timer <= 0 then
                    done = true
                else
                    a.timer = a.timer - 1
                end
            elseif a.kind == SG_BOUNCE or a.kind == SG_BOUNCE_EB then
                ---BulletManager.cpp:959-1001：四条边都反射（x < −192 / x ≥ 192 / y < 0 /
                ---y ≥ 448），反弹满 bounceLimit 次就把这个变换收掉。
                ---★ 本仓库的 straight_bullet 自带一条 rebound（bullet.lua:236-248，
                ---  只反弹左/右/上三面、且次数无限），只能表达原作的 0x800
                ---  （BOUNCE_EXCEPT_BOTTOM）；0x400 多出来的下边界与次数上限在这里自己写，
                ---  所以吃 BOUNCE 的弹一律**不传** rebound 参数。
                if a.hits >= r.i0 then
                    done = true
                else
                    local w = lstg.world
                    local hit = false
                    if self.x < w.l or self.x > w.r then
                        self.vx = -self.vx
                        self.x = (self.x < w.l) and (2 * w.l - self.x) or (2 * w.r - self.x)
                        hit = true
                    end
                    ---0x400 四条边都反射；0x800 BOUNCE_EXCEPT_BOTTOM 少了「下边界那一条」
                    ---（BulletManager.cpp:963-978 里 y 那支会检查 activeTransformFlags 是否含
                    --- BOUNCE_ALL_EDGES）。TH095 的「下边界」= 我们的 y ≤ −224（y 轴翻过来），
                    ---跳过的正是这一条。
                    if (a.kind == SG_BOUNCE or self.y > w.b) and
                            (self.y > w.t or self.y < w.b) then
                        self.vy = -self.vy
                        self.y = (self.y > w.t) and (2 * w.t - self.y) or (2 * w.b - self.y)
                        hit = true
                    end
                    if hit then
                        self.rot = Angle(0, 0, self.vx, self.vy)
                        a.hits = a.hits + 1
                    end
                end
            end
            if done then a.dead = true; dirty = true end
        end
        if dirty then
            local j = 0
            for k = 1, #st.acts do
                if not st.acts[k].dead then
                    j = j + 1
                    st.acts[j] = st.acts[k]
                end
            end
            for k = j + 1, #st.acts do st.acts[k] = nil end
        end
    end
end

do  -- 80 永琳 非符（ecl18_a，永琳，组 9a 第 1 张）
    ---原作这一关的第 1 幕**没有** ins_104（不亮卡名）：永琳进场后站定不动，从第 60 帧起
    ---每 10 帧抛出**两整圈** 15 发中玉 —— 两圈同一基准角、同一初速 5，但分别在
    ---70 帧里以 +0.6°/帧 与 −0.6°/帧 自转，同时速度一起从 5 线性减到 0.7。
    ---数据源 /tmp/S8_ecl18_a.txt（ECL …/data/ecl18_a.ecl）。骨架：
    ---  · Sub2：ins_55(2) + ins_81(3) + ins_109(0) + ins_77(24,24) + ins_141(6)（拍 6 张）
    ---    + ins_108(0,31)/ins_108(1,30)（子机槽）+ ins_143(1,130) + ins_63(-128,-64) 进场
    ---    → t=100 ins_64(30,4,0,128) 落到 (0,128)（我们的 (0,96)）→ t=130 的 `id=0`
    ---    （opcode 0 在 EclRunLow.inl 的 switch 里没有分支 ⇒ **NOP**；这一张就是不亮
    ---    卡名的非符）+ ins_75(-140,128,140,192)（这一张**没有任何移动指令**，框用不上）
    ---    + ins_149(4.5) + ins_132(1) + ins_52(3)。
    ---  · Sub3（@692）：t=0 ins_106(5)（音效）+ 起两条装饰上下文（Sub5/Sub6 都是
    ---    ins_150 的 ANM 装饰，不实现）；t=60 起 slot0 的 Sub4（发弹体）；t=180 的
    ---    ins_4(60,0) 跳回 @768（就是 t=60 那句）⇒ 每 120 帧把 Sub4 重新起一遍。
    ---    Sub4 自己是死循环、周期 10 帧，而 120 = 12 个周期 ⇒ 重起不改变相位，
    ---    这里就写成一条 while（少绕一层）。
    ---  · Sub4（@800）：每 10 帧一轮 ——
    ---      ① floatV0 = rand(−π,π)（@840，跳回点）；floatV1 = floatV0（@860）
    ---      ② 写 slot0 的 ins_101(0, 0x20 ACCEL_POLAR, 0, 70, −1, −0.0614286, +0.010472)
    ---         → 紧接着 ins_89 CIRCLE(型13、色2、15 发、速 5、基角 floatV0、步长 0.1848、
    ---         flags 546) ⇒ 这一圈吃**刚写的那条**记录
    ---      ③ floatV0 += 1.875°、归一化；再把 slot0 改写成角度增量 −0.010472 的那条
    ---         → t=5 的一圈（色 3）吃**第二条**记录
    ---    ⇒ 两圈同起点、反向自旋着减速，像一对缓缓收拢又拧开的伞。
    ---★ 记录的原始字节核过（ecl18_a.ecl 偏移 880 与 1000）：op5 = −0.0614286（速度增量）、
    ---  op6 = ±0.010472（角度增量），0.010472 rad = 0.6°、0.1848 rad = 2π/34。
    local BOSS_X, BOSS_START_Y = -128, field_y(-64)
    local HOME_X, HOME_Y = 0, field_y(128)              -- 0 / 96
    local ENTRY_WAIT, ENTRY_TIME = 100, 30
    local EASE_OUT = VALUE_SET.DECEL

    local PHOTO_LIMIT = 6                               -- ins_141(6)
    local CARD_NAME = ""                                -- 非符：原作没有 ins_104
    local CARD_TIME, CARD_HP = 50, 900
    local CARD_ID = 478

    local RING_COUNT, RING_SPEED = 15, 5                -- ins_89 的 c1 / sp1
    local FIRE_GAP = 5                                  -- 两圈相隔 5 帧（@920 t=0 / @1040 t=5）
    local START_AT = 60                                 -- Sub3 的 t=60
    local SPEED_DELTA, DUR = -0.0614286, 70             -- ins_101 的 f0 / i0
    local ANGLE_DELTA = 0.6                             -- = 0.010472 rad（我们的度/帧）

    local hook_ccw = sg_tr_hook(
            { sg_rec(SG_POLAR, 0, DUR, -1, SPEED_DELTA, ANGLE_DELTA) }, SG_POLAR)
    local hook_cw = sg_tr_hook(
            { sg_rec(SG_POLAR, 0, DUR, -1, SPEED_DELTA, -ANGLE_DELTA) }, SG_POLAR)

    local st = { dead = false }

    ---Sub4：每 10 帧两整圈（色 2 逆时针自旋、色 3 顺时针自旋）。
    ---基准角在 TH095 空间里是 rand(−π,π)；整圈取反后方向集合不变，所以直接抽我们的度。
    local function run_sub4(owner)
        task.New(owner, function()
            while not st.dead do
                local base = sg_deg(ran:Float(-math.pi, math.pi))
                sg_shot(89, ball_mid, ex_color(2), owner.x, owner.y,
                        RING_COUNT, 1, RING_SPEED, 1.5, base, 0, false, 546, hook_ccw)
                task.Wait(FIRE_GAP)
                if st.dead then return end
                sg_shot(89, ball_mid, ex_color(3), owner.x, owner.y,
                        RING_COUNT, 1, RING_SPEED, 1.5, base, 0, false, 546, hook_cw)
                task.Wait(FIRE_GAP)
            end
        end)
    end

    local card = boss.card.New(CARD_NAME, 1, 3, CARD_TIME, CARD_HP)

    function card:before()
    end

    function card:init()
        photo_damage_on(self, PHOTO_LIMIT)
        self.x, self.y = BOSS_X, BOSS_START_Y
        st.dead = false
        task.New(self, function()
            task.Wait(ENTRY_WAIT)
            task.MoveTo(HOME_X, HOME_Y, ENTRY_TIME, EASE_OUT)
            ---到这里是原作第 130 帧：Sub3 的 t=0 是 ins_106(5)（定位置的音效）。
            PlaySound("tan00", 0.1, self.x / 256, false)
            task.Wait(START_AT)
            run_sub4(self)
        end)
    end

    function card:frame()
    end

    function card:del()
        st.dead = true
        photo_damage_off(self)
    end

    boss.card.add({ { card, "9a" } }, LEVEL, CARD_NAME, CARD_ID)
end--永琳 非符（ecl18_a）

do  -- 81 新難題「月のイルメナイト」（ecl19_a，辉夜，组 10a 第 1 张）
    ---原作是辉夜的第一张难题：本体每 120 帧在活动框里换一个位置（走得比相机还慢），
    ---同时每 5 帧从**本体周围 80 px 内的随机一点**甩出一整圈小玉；这一圈不瞄准，
    ---但每颗弹都吃到一条「朝发弹那一瞬间的自机方向加速 1/120 每帧、共 240 帧」的记录
    ---（ins_101 的 ACCEL_VEC）—— 于是整圈弹先各飞各的，再被同一股力慢慢掰成
    ---同一族抛物线。每圈弹数 = photoIndex + 7，颜色是 1..14 里的随机一档。
    ---数据源 /tmp/S8_ecl19_a.txt（ECL …/data/ecl19_a.ecl）。骨架：
    ---  · Sub2：与 ecl18_a 同一套骨架（ins_55/81/109/77/141(6)/108/143/63 → t=100 落到
    ---    (0,128)（我们的 (0,96)）→ t=130 **亮卡名**（有 ins_104，这一张是符卡）
    ---    + ins_75(-140,128,140,192) + ins_149(4.5) + ins_132(1) + ins_52(3)）。
    ---  · Sub3（@732）：t=0 ins_106(5) + 117(0,4)（起发弹体 Sub4）；t=120 ins_67(120,4,0.5)
    ---    ⇒ 用 120 帧、缓动 4、总位移 0.5×120 = 60 px 的「远离自机」游走；
    ---    t=240 的 ins_4(0,-24) 跳回 @768（就是 t=120 那句）⇒ 每 120 帧换一次位置，
    ---    而且 ins_67 一走就是 120 帧 ⇒ 本体其实一直在慢慢挪。
    ---  · Sub4（@824）：每 5 帧一轮（t=5 的 ins_4 跳回 @864）——
    ---      extraFloatV0 = 80×rand[0,1)（@864，跳回点）
    ---      extraFloatV1/…由 ins_38 变成极坐标 (x,y) = (cos·m, sin·m)（随机方向 + 半径 m）
    ---      ins_100 把这对写成 shootOffset ⇒ 出膛点 = 本体 + 那个偏移
    ---      floatV0 = rand(−π,π)（这一圈的基准角）
    ---      ins_101(0, 0x10 ACCEL_VEC, 0, 240, −1, 0.00833333, playerAngle)
    ---        —— f0 = 每帧加速度大小 1/120、f1 = 加速度方向 = **出膛那一刻**的自机角
    ---        （0x2730 = Enemy::ResolveFloat 的 playerAngle，EclOperandsFloat.cpp:175）
    ---      intV0 = photoIndex + 7（这一圈的发数）
    ---      intV1 = randU31 % 14 + 1（颜色 1..14）
    ---      ins_89 CIRCLE(型0 = 直径 4、色 intV1、c1 = intV0、c2 = 1、速 1、基角 floatV0、
    ---      步长 0.1848 = 2π/34、flags 530) ⇒ 这一圈吃上面那条记录
    ---      ins_37 归一化 floatV0，t=5 跳回。
    ---★ randU31 % 14 用的是**整数**随机（EclOperandsFloat.cpp:118 的 0x2720）；
    ---  这里用 ran:Int(0,13)+1（同一分布、另一个实现），数值行为一致。
    ---★ flags 530 = 0x212 = 0x200（出场音）+ 0x10（VEC）+ 0x2（出场滑动，不实现）；
    ---  记录要能被吃，flags 里必须有 0x10 —— 这是写 ins_101 时必须核的一步。
    local BOSS_X, BOSS_START_Y = -128, field_y(-64)
    local HOME_X, HOME_Y = 0, field_y(128)              -- 0 / 96
    local ENTRY_WAIT, ENTRY_TIME = 100, 30
    local EASE_OUT = VALUE_SET.DECEL

    local PHOTO_LIMIT = 6                               -- ins_141(6)
    local CARD_NAME = "新難題「月のイルメナイト」"
    local CARD_TIME, CARD_HP = 50, 900
    local CARD_ID = 479

    local BOX = { -140, 128, 140, 192 }                 -- ins_75(-140,128,140,192)
    local MOVE_FRAMES, MOVE_EASE, MOVE_SPEED = 120, 4, 0.5   -- ins_67(120,4,0.5)
    local FIRE_GAP = 5                                  -- Sub4 的周期
    local RING_EXTRA, RING_SPEED = 7, 1                 -- ins_89 的 c1 偏移 / sp1
    local SPAWN_R = 80                                  -- ins_27 的半径
    local ACCEL_FRAMES, ACCEL_MAG = 240, 0.00833333     -- ins_101 的 i0 / f0
    local COLOR_SPAN = 14                               -- intV1 = randU31 % 14

    local st = { dead = false }

    ---Sub4：每 5 帧一整圈。
    local function run_sub4(owner)
        task.New(owner, function()
            while not st.dead do
                ---shootOffset：本体周围 80 px 内的随机一点（ins_27 + ins_38 + ins_100）。
                local m = SPAWN_R * ran:Float(0, 1)
                local oa = sg_deg(ran:Float(-math.pi, math.pi))
                local sx, sy = owner.x + m * cos(oa), owner.y + m * sin(oa)
                ---这条记录在**出膛那一刻**取值：加速度方向 = 本体→自机的角
                ---（0x2730 用的是 worldPosition，不含 shootOffset）。
                local acc = Angle(owner.x, owner.y, player.x, player.y)
                local hook = sg_tr_hook(
                        { sg_rec(SG_VEC, 0, ACCEL_FRAMES, -1, ACCEL_MAG, acc) }, SG_VEC)
                local base = sg_deg(ran:Float(-math.pi, math.pi))
                local count = photo_index(PHOTO_LIMIT) + RING_EXTRA
                local color = ex_color(ran:Int(0, COLOR_SPAN - 1) + 1)
                sg_shot(89, ball_small, color, sx, sy, count, 1, RING_SPEED, 1.5,
                        base, 0, false, 530, hook)
                task.Wait(FIRE_GAP)
            end
        end)
    end

    local card = boss.card.New(CARD_NAME, 1, 3, CARD_TIME, CARD_HP)

    function card:before()
    end

    function card:init()
        photo_damage_on(self, PHOTO_LIMIT)
        self.x, self.y = BOSS_X, BOSS_START_Y
        st.dead = false
        task.New(self, function()
            task.Wait(ENTRY_WAIT)
            task.MoveTo(HOME_X, HOME_Y, ENTRY_TIME, EASE_OUT)
            ---到这里是原作第 130 帧：亮卡名 + Sub3 的 t=0（ins_106(5) 音效 + 起 Sub4）。
            PlaySound("tan00", 0.1, self.x / 256, false)
            run_sub4(self)
            while not st.dead do
                ---Sub3 的 t=120 / t=240 循环：每 120 帧一次 60 px 的「远离自机」游走。
                task.Wait(MOVE_FRAMES)
                if st.dead then return end
                sg_bmove(self, st, MOVE_FRAMES, MOVE_EASE, MOVE_SPEED, BOX)
            end
        end)
    end

    function card:frame()
    end

    function card:del()
        st.dead = true
        photo_damage_off(self)
    end

    boss.card.add({ { card, "10a" } }, LEVEL, CARD_NAME, CARD_ID)
end--新難題「月のイルメナイト」

do  -- 82 薬符「胡蝶夢丸ナイトメア」（ecl18_b，永琳，组 9a 第 2 张）
    ---原作这一张是两层的「蝴蝶梦丸」：本体每 190 帧做一轮 ——
    ---  · 第 60 帧一次性叠出 **11 层同心圆**：每层 24 发中玉、初速 0，吃一条
    ---    ACCEL_VEC 记录（加速度 = 1/60、2/60 … 11/60 每帧，方向取**弹自己出生时**的角，
    ---    持续 60 帧）⇒ 60 帧后各层速度正好是 1、2 … 11，整叠像一朵被吹开的花。
    ---  · 第 120 帧放出 **9 只蝴蝶子机**：朝「本体→自机」的方向 ±22.5° 起、每只间隔
    ---    45°；每只自己朝那个方向直线飞（速 4）并一路撒「本体周围 48 px 内随机一点、
    ---    随机方向、速 1」的小玉。撒得多快、什么颜色看**拍中本体的张数**：
    ---    <3 ⇒ 绿 10 每 5 帧；3~4 ⇒ 紫 4 每 4 帧；≥5 ⇒ 红 2 每 3 帧。
    ---  · 第 130 帧本体自己挪一次（60 帧走 1.6×60 = 96 px）。
    ---数据源 /tmp/S8_ecl18_b.txt（ECL …/data/ecl18_b.ecl）。骨架：
    ---  · Sub2：ins_141(7)（拍 7 张）+ t=100 ins_64(30,4,0,160) 落到 (0,160)
    ---    （我们的 (0,64)）→ t=130 亮卡名 + ins_75(-160,128,160,144) + ins_149(1.5)
    ---    + ins_132(1) + ins_52(3)。
    ---  · Sub3（@760）：t=0 ins_106(5) + 两条装饰子上下文（Sub6/Sub7 都是 ins_150）；
    ---    t=60 起 slot0 的 Sub4（叠层）与 slot1 的 Sub5（放子机）；t=110 ins_144(15)
    ---    （快门脉冲，不实现）；t=130 ins_67(60,0,1.6)（缓动 0 = 线性）；t=190 的
    ---    ins_4(0,?) 跳回 @780（t=0 那句 ins_106(5)）⇒ 整轮 190 帧、音效每轮响一次。
    ---  · Sub4（@948）：floatV0 = 1/60；extraIntV0 = 10；ins_106(16)；
    ---    @1004 写 slot0 的 ins_101(0, 0x10 ACCEL_VEC, 0, 60, −1, floatV0, −999.99)
    ---    → @1044 ins_90 OFFSET_CIRCLE_AIMED(型15、色3、24 发、速 0、步长 0.03272、
    ---    flags 536) ⇒ 这一层吃刚写的记录；@1088 floatV0 += 1/60；
    ---    @1108 ins_5(0, −104, extraIntV0) 回跳 —— ins_5 是「先 −−n 再判 >0」
    ---    ⇒ 循环体走 **11** 遍（n 从 10 到 0）。@1132 ins_53 自灭。
    ---    ★ 原始字节核过（ecl18_b.ecl 偏移 1004 与 1108）：op5 是 0x2724 = extraIntV0、
    ---      回跳偏移 −104（落回 @1004）。
    ---  · Sub5（@1156，全部指令带 t=60 ⇒ 上下文建好后第 60 帧才动）：
    ---    extraFloatV2 = playerAngle + 22.5°；extraFloatV3 = 4（子机速度）；
    ---    @1256 循环体 = ins_83(11)（**生成子敌机**）+ extraFloatV2 += 45°；
    ---    @1292 ins_5(60, −36, extraIntV0 = 8) ⇒ 9 只（第 1 只与第 9 只方向重合，
    ---    原作就是这样）；@1316 ins_53 自灭。
    ---  · Sub11（@2040，每个子机的脚本）：ins_55(2)/80(8)/81(16) 换 ANM；
    ---    ins_65(extraFloatV2, extraFloatV3) 把自己设成「朝那个方向、速 4」；
    ---    然后按 photoIndex 分三档：ins_50(photoIndex,3,…) ≥3 再判
    ---    ins_50(photoIndex,5,…) —— ≥5 ⇒ ins_117(0,10)，否则 ins_117(0,9)；
    ---    <3 ⇒ ins_117(0,8)。三档就是 Sub8/9/10 三个撒弹器。
    ---  · Sub8/9/10：ins_103(24)（设出场音，**只在进入循环前响一次的那句**）；
    ---    循环体 = extraFloatV0 = 48×rand[0,1) → ins_38 极坐标 → ins_100 shootOffset
    ---    → ins_89 CIRCLE(型3 = 直径 4、色 10/4/2、1 发、速 1、基角 rand(−π,π)、
    ---    flags 536)（flags 的 0x200 让**每一发**都响一次出场音）；周期 **4/3/2** 帧
    ---    （Sub8/9/10 的 ins_4 分别挂在 t=4/3/2 ⇒ 循环体每隔这么多帧进一次，
    ---     见 Sub4 的同一个写法：t=0/t=1 两条发放 + t=2 的 ins_4 = 每帧一发）。
    ---    ★ 子机在本仓库按文件头差异 5 的做法：**数量受限的自绘 object** ——
    ---      直线飞、飞出场地就淡出回收（原作的子敌机是靠 offscreen 检查回收的）。
    local BOSS_X, BOSS_START_Y = -128, field_y(-64)
    local HOME_X, HOME_Y = 0, field_y(160)              -- 0 / 64
    local ENTRY_WAIT, ENTRY_TIME = 100, 30
    local EASE_OUT = VALUE_SET.DECEL

    local PHOTO_LIMIT = 7                               -- ins_141(7)
    local CARD_NAME = "薬符「胡蝶夢丸ナイトメア」"
    local CARD_TIME, CARD_HP = 50, 900
    local CARD_ID = 480

    local BOX = { -160, 128, 160, 144 }                 -- ins_75(-160,128,160,144)
    local CYCLE = 190                                   -- Sub3 一轮
    local BURST_AT = 60                                 -- Sub4 的 t=60 → 本轮第 60 帧
    local DRONE_AT = 120                                -- Sub5 的 t=60（上下文建于第 60 帧）
    local MOVE_AT = 130                                 -- Sub3 的 ins_67
    local MOVE_FRAMES, MOVE_EASE, MOVE_SPEED = 60, 0, 1.6

    local BURST_LAYERS = 11                             -- ins_5 的 n = 10 ⇒ 11 层
    local BURST_COUNT = 24                              -- ins_90 的 c1
    local BURST_STEP, BURST_FRAMES = 1 / 60, 60         -- floatV0 的初值 / 步长、ins_101 的 i0

    local DRONE_N, DRONE_SPEED = 9, 4                   -- ins_83 的遍数 / extraFloatV3
    local DRONE_A0, DRONE_DA = 22.5, 45                 -- 0.392699 rad / 0.785398 rad
    local EMIT_R, EMIT_SPEED = 48, 1                    -- ins_27 的半径 / ins_89 的 sp1
    ---三档撒弹器（Sub8/9/10）：色号与周期（4/3/2 帧 —— Sub8/9/10 的 ins_4 分别在
    ---t=4/3/2；不是 +4 之后再等一发，循环体与回跳同帧进）。
    local EMIT_MODES = { { color = 10, gap = 4 }, { color = 4, gap = 3 }, { color = 2, gap = 2 } }
    local DRONE_FADE_IN, DRONE_FADE_OUT, DRONE_ALPHA = 8, 12, 200

    local st = { dead = false }
    local drones = {}

    ---蝴蝶子机。方向 angle_deg 是**我们的度**（逆时针为正）；发射器周期/色号由生成那一刻的
    ---photoIndex 决定（原作 Sub11 只在开场判一次）。
    class.nightmare_drone = Class(object, {
        init = function(self, owner, angle_deg, color, gap)
            self.group = GROUP.GHOST
            self.layer = LAYER.ENEMY_BULLET_EF
            self.colli = false
            self.bound = false               -- 自己管回收（下面那条协程）
            self.x, self.y = owner.x, owner.y
            self.rot = 0
            self._a = 0
            object.SetV(self, DRONE_SPEED, angle_deg, true)
            local w = lstg.world
            task.New(self, function()
                for _ = 1, DRONE_FADE_IN do
                    self._a = min(DRONE_ALPHA, self._a + DRONE_ALPHA / DRONE_FADE_IN)
                    task.Wait()
                end
                ---Sub8/9/10 的循环：每 gap 帧一发（出膛点在 48 px 内随机、方向随机）。
                while self.x > w.l - 64 and self.x < w.r + 64
                        and self.y > w.b - 64 and self.y < w.t + 64 do
                    local m = EMIT_R * ran:Float(0, 1)
                    local oa = sg_deg(ran:Float(-math.pi, math.pi))
                    local sx, sy = self.x + m * cos(oa), self.y + m * sin(oa)
                    NewSimpleBullet(ball_small, ex_color(color), sx, sy, EMIT_SPEED,
                            sg_deg(ran:Float(-math.pi, math.pi)), false, 0, false)
                    PlaySound("tan00", 0.1, sx / 256, false)   -- flags 536 的 0x200
                    task.Wait(gap)
                end
                for _ = 1, DRONE_FADE_OUT do
                    self._a = max(0, self._a - DRONE_ALPHA / DRONE_FADE_OUT)
                    task.Wait()
                end
                object.RawDel(self)
            end)
        end,
        frame = function(self)
            task.Do(self)                                  -- ★ 驱动淡入 / 撒弹 / 自灭协程
        end,
        render = function(self)
            SetImageState("butterfly4", "mul+add", self._a, 210, 170, 250)
            Render("butterfly4", self.x, self.y, self.rot, 0.8)
            SetImageState("butterfly6", "mul+add", self._a * 0.7, 180, 140, 240)
            Render("butterfly6", self.x - cos(self.rot) * 9, self.y - sin(self.rot) * 9,
                    self.rot + 40, 0.6)
        end,
    })

    ---Sub4：11 层同心圆叠在一帧里放完（原作也是一次性走完这个循环）。
    local function run_burst(owner)
        for k = 1, BURST_LAYERS do
            local hook = sg_tr_hook({ sg_rec(SG_VEC, 0, BURST_FRAMES, -1,
                    BURST_STEP * k, -999.99) }, SG_VEC)
            sg_shot(90, ball_mid, ex_color(3), owner.x, owner.y,
                    BURST_COUNT, 1, 0, 0, 0, 0.0327249, true, 536, hook)
        end
    end

    ---Sub5 + Sub11：9 只蝴蝶子机朝「本体→自机」±22.5° 起、每只差 45°。
    ---★ TH095 的角度是顺时针为正，我们的取反 ⇒ 起始角是「我们的自机角 − 22.5°」，
    ---  且每只**减** 45°（原作的 +45° 取反）；整组方向集合不变（差 45° 的九分之八圈）。
    local function spawn_drones(owner)
        local n = photo_index(PHOTO_LIMIT)
        local mode = (n >= 5) and EMIT_MODES[3] or (n >= 3) and EMIT_MODES[2] or EMIT_MODES[1]
        local a = Angle(owner.x, owner.y, player.x, player.y) - DRONE_A0
        for _ = 1, DRONE_N do
            drones[#drones + 1] = New(class.nightmare_drone, owner, a, mode.color, mode.gap)
            a = a - DRONE_DA
        end
    end

    local card = boss.card.New(CARD_NAME, 1, 3, CARD_TIME, CARD_HP)

    function card:before()
        drones = {}
    end

    function card:init()
        photo_damage_on(self, PHOTO_LIMIT)
        self.x, self.y = BOSS_X, BOSS_START_Y
        st.dead = false
        task.New(self, function()
            task.Wait(ENTRY_WAIT)
            task.MoveTo(HOME_X, HOME_Y, ENTRY_TIME, EASE_OUT)
            ---到这里是原作第 130 帧：亮卡名 + Sub3 的 t=0（ins_106(5)）。
            while not st.dead do
                PlaySound("tan00", 0.1, self.x / 256, false)
                task.Wait(BURST_AT)
                if st.dead then return end
                run_burst(self)
                task.Wait(DRONE_AT - BURST_AT)
                if st.dead then return end
                spawn_drones(self)
                task.Wait(MOVE_AT - DRONE_AT)
                if st.dead then return end
                sg_bmove(self, st, MOVE_FRAMES, MOVE_EASE, MOVE_SPEED, BOX)
                task.Wait(CYCLE - MOVE_AT)
            end
        end)
    end

    function card:frame()
    end

    function card:del()
        st.dead = true
        photo_damage_off(self)
        for i = #drones, 1, -1 do
            if IsValid(drones[i]) then
                task.Clear(drones[i])
                object.RawDel(drones[i])
            end
        end
        drones = {}
    end

    boss.card.add({ { card, "9a" } }, LEVEL, CARD_NAME, CARD_ID)
end--薬符「胡蝶夢丸ナイトメア」

do  -- 83 新難題「エイジャの赤石」（ecl19_b，辉夜，组 10a 第 2 张）
    ---原作这一张是「红石」：辉夜每 124 帧做一轮 ——
    ---  · 先朝自机放一根 **type 12 的直线激光**（长 320、宽 32、速 12）；
    ---  · 同帧再放四组 **FAN_AIMED 大玉**（type 17 = 直径 28 ⇒ ball_huge），以自机方向
    ---    为轴：1 发（速 12）+ 2 发（速 8，±5.29°）+ 2 发（速 6，±10.6°）+ 2 发（速 4，
    ---    ±15.9°），一共 7 发；
    ---  · 另有 5 条并行上下文每 (32 − 4×拍照数) 帧各放一根**随机方向的细直线激光**
    ---    （type 1、长 128、宽 10、速 2）—— 拍中本体越多、激光越密；
    ---  · 本体每 240 帧沿活动框 (x∈[−140,140], TH095 y∈[128,192]) 做一次「边界感知」挪位。
    ---数据源 /tmp/S8_ecl19_b.txt（ECL …/data/ecl19_b.ecl）。骨架：
    ---  · Sub2（@384）：ins_55(2)+ins_81(3)+ins_109(0)+ins_77(24,24)+ins_141(6)（拍 6 张）
    ---    + ins_108(0,31)/ins_108(1,30)+ins_143(1,130)+ins_63(-128,-64) 进场
    ---    → t=100 ins_64(30,4,0,128) 落到 (0,128)（我们的 (0,96)）→ t=130 亮卡名
    ---    + ins_75(-140,128,140,192) + ins_149(4) + ins_132(1) + ins_52(3)。
    ---  · Sub3（@740）：t=0 起 slot0 的 Sub4（发弹体）与 slot2..6 的 5 份 Sub5（每条错开
    ---    10 帧，见 @756/@776/@796/@816/@836 的 ins_117(2..6,5)）；t=160 的
    ---    ins_67(120,4,0.5) 与 t=280 的 ins_4(40,−24) 组成一个 240 帧的外层环 ——
    ---    跳转目标是 @876 的 ins_67 **本身**（900−24=876），所以这个环**只重复挪位**；
    ---    t=0..40 那五条 ins_117 在环外、只跑一次，Sub4/Sub5 各自在内部死循环。
    ---  · Sub4（@932，124 帧一轮）：t=0 起一条装饰子上下文（Sub6，不实现）；t=60 先
    ---    ins_146(12,1,12,0,320,32)（**146 的角度 = 原始角 + 自机角**，见
    ---    EclRunTargetPhoto.inl:21-36）再四组 ins_86 FAN_AIMED；t=64 ins_144(15)（快门
    ---    脉冲，不实现）+ ins_106(16)；t=124 的 ins_4(0,−284) 跳回 @972 ⇒ 124 帧一轮。
    ---    ★ 四组 ins_86 的原始字节核过（ecl19_b.ecl @1028..1160）：op0 都是 0x11
    ---      （type 17、color 0）、count2 全是 1 ⇒ 速度 = speed1 不作插值；四组的
    ---      (count1, speed1, angleStep) = (1,12,0.1848)/(2,8,0.1848)/(2,6,0.3696)/
    ---      (2,4,0.5544)，共 **7** 发。色号 0 按 g_PhotoBulletColors16 = 灰
    ---      （BulletManager.cpp:128-133）⇒ 走 ex_color(0) = 灰 16。
    ---  · Sub5（@1300）：t=0 ins_145(1,2,2,rand(−π,π),128,10) 放一根随机直线激光；
    ---    接着 extraIntV1 = photoIndex×4（ins_22）、extraIntV1 = 30 − 它（ins_21）、
    ---    ins_2 冻结这么多帧；t=2 的 ins_4(0,−156) 跳回 @1320。
    ---    ★ ins_2 的冻结只作用在**执行它的那条上下文**（EclRun.cpp:299-303 减的是
    ---      activeEclContext 的 secondaryTime 与 time），5 份 Sub5 各冻各的 ⇒
    ---      每份的周期 = (30 − 4×photoIndex) + 2 —— 多出来的 2 帧是冻结结束后 time 停在
    ---      0、还要过 t=2 的那条 ins_4（ins_2 把 time 也按帧抵消，见 478 的注释）。
    local BOSS_X, BOSS_START_Y = -128, field_y(-64)
    local HOME_X, HOME_Y = 0, field_y(128)              -- 0 / 96
    local ENTRY_WAIT, ENTRY_TIME = 100, 30
    local EASE_OUT = VALUE_SET.DECEL

    local PHOTO_LIMIT = 6                               -- ins_141(6)
    local CARD_NAME = "新難題「エイジャの赤石」"
    local CARD_TIME, CARD_HP = 50, 900
    local CARD_ID = 481

    local BOX = { -140, 128, 140, 192 }                 -- ins_75(-140,128,140,192)
    local MOVE_AT = 160                                 -- Sub3 的 ins_67
    local MOVE_FRAMES, MOVE_EASE, MOVE_SPEED = 120, 4, 0.5

    local SUB4_CYCLE, SUB4_FIRE = 124, 60               -- Sub4 一轮 / 开火点（t=60）
    local BEAM_LEN, BEAM_W, BEAM_SPEED = 320, 32, 12    -- ins_146 的后四参
    local BEAM_INDEX = 1                                -- 原作 color 1（laser 贴图行 = color）
    local BIG_COLOR = 0                                 -- 原作色号 0（灰）
    ---四组 FAN_AIMED 的 (count1, speed1, angleStep)，见上面的字节核对。
    local BIG = {
        { 1, 12, 0.1848 },
        { 2, 8, 0.1848 },
        { 2, 6, 0.369599 },
        { 2, 4, 0.554399 },
    }

    local SUB5_N = 5                                    -- slot 2..6，共 5 份
    local SUB5_STAGGER = 10                             -- 每条错开 10 帧
    local SUB5_GAP_BASE, SUB5_GAP_STEP = 30, 4          -- ins_2 的 30 − 4×photoIndex
    local SUB5_GAP_EXTRA = 2                            -- t=2 的 ins_4 之前的 2 帧
    local SUB5_INDEX = 2                                -- 原作 color 2
    local SUB5_LEN, SUB5_W, SUB5_SPEED = 128, 10, 2

    local lasers = {}
    local st = { dead = false }

    ---Sub4：每 124 帧 —— 一根自机方向直线激光 + 四组自机方向大玉扇。
    local function run_sub4(owner)
        task.New(owner, function()
            while not st.dead do
                task.Wait(SUB4_FIRE)
                if st.dead then return end
                spawn_ex_laser_straight(owner, lasers, BEAM_INDEX, owner.x, owner.y,
                        -sg_aim(owner.x, owner.y), BEAM_LEN, BEAM_W, BEAM_SPEED)
                for i = 1, #BIG do
                    local b = BIG[i]
                    sg_shot(86, ball_huge, ex_color(BIG_COLOR), owner.x, owner.y,
                            b[1], 1, b[2], 1.5, 0, b[3], true, 514)
                end
                PlaySound("tan00", 0.1, owner.x / 256, false)   -- t=64 的 ins_106(16)
                task.Wait(SUB4_CYCLE - SUB4_FIRE)
            end
        end)
    end

    ---Sub5：每 (32 − 4×拍照数) 帧一根随机方向的细直线激光（5 份错开 10 帧）。
    local function run_sub5(owner)
        task.New(owner, function()
            while not st.dead do
                spawn_ex_laser_straight(owner, lasers, SUB5_INDEX, owner.x, owner.y,
                        -math.deg(ran:Float(-math.pi, math.pi)),
                        SUB5_LEN, SUB5_W, SUB5_SPEED)
                PlaySound("tan00", 0.1, owner.x / 256, false)   -- ins_106(24)
                local gap = SUB5_GAP_BASE - SUB5_GAP_STEP * photo_index(PHOTO_LIMIT)
                if gap < 1 then gap = 1 end
                task.Wait(gap + SUB5_GAP_EXTRA)
            end
        end)
    end

    local card = boss.card.New(CARD_NAME, 1, 3, CARD_TIME, CARD_HP)

    function card:before()
    end

    function card:init()
        photo_damage_on(self, PHOTO_LIMIT)
        self.x, self.y = BOSS_X, BOSS_START_Y
        st.dead = false
        task.New(self, function()
            task.Wait(ENTRY_WAIT)
            task.MoveTo(HOME_X, HOME_Y, ENTRY_TIME, EASE_OUT)
            ---到这里是原作 Sub2 的 t=130 = Sub3 的 t=0：
            ---ins_106(5) 一声 + 起 Sub4 与 5 份 Sub5（每 10 帧一条）。
            PlaySound("tan00", 0.1, self.x / 256, false)
            run_sub4(self)
            run_sub5(self)
            for _ = 1, SUB5_N - 1 do
                task.Wait(SUB5_STAGGER)
                run_sub5(self)
            end
            ---Sub3 的 time 到这里是 40；ins_67 在 t=160。
            task.Wait(MOVE_AT - (SUB5_N - 1) * SUB5_STAGGER)
            while not st.dead do
                sg_bmove(self, st, MOVE_FRAMES, MOVE_EASE, MOVE_SPEED, BOX)
                task.Wait(MOVE_FRAMES)      -- t=160 → 280（ins_4 跳回 t=160）
                task.Wait(MOVE_FRAMES)      -- t=40 → 160
            end
        end)
    end

    function card:frame()
    end

    function card:del()
        st.dead = true
        photo_damage_off(self)
        sg_clear(lasers)
    end

    boss.card.add({ { card, "10a" } }, LEVEL, CARD_NAME, CARD_ID)
end--新難題「エイジャの赤石」

do  -- 84 錬丹「水銀の海」（ecl18_c，永琳，组 9a 第 3 张）
    ---原作是「水银之海」：永琳在场地里**竖直往返**，同时一条并行上下文每 2 帧往
    ---「本体周围 32 px 内的随机一点」丢一颗小玉 —— 出膛方向是两个固定的出发角
    --- −135° / −45°（TH095 度），每 2 帧各向外扩 0.45°，而且吃 BOUNCE 变换、
    --- 最多在四壁反弹 4 次；拍中本体 ≥5 张后**再补一路**（−45° 那一色）。
    ---数据源 /tmp/S8_ecl18_c.txt（ECL …/data/ecl18_c.ecl）。骨架：
    ---  · Sub2（@384）：ins_55(2)+ins_81(3)+ins_109(0)+ins_77(24,24)+ins_141(6)（拍 6 张）
    ---    + ins_108(0,31)/ins_108(1,30)+ins_143(1,130)+ins_63(-128,-64) 进场
    ---    → t=100 ins_64(30,4,0,128) 落到 (0,128)（我们的 (0,96)）→ t=130 亮卡名
    ---    + ins_149(6)+ins_132(1)+ins_52(3)。★ **没有 ins_75**（竖直往返不用活动框）。
    ---  · Sub3（@712）：t=0 extraIntV1=60（给装饰子上下文用）+ ins_117(0,4)（Sub4，装饰）
    ---    + ins_117(2,5)（Sub5，装饰）+ ins_106(5)；t=60 ins_117(0,6) 起 **Sub6**（发弹体，
    ---    一次性、之后自己死循环）+ ins_144(15)（快门脉冲，不实现）+ ins_64(120,1,0,224)。
    ---    之后 t=180/300/420 各一条 ins_64（ease 4/1/4、目标 y=352/224/96），t=540 的
    ---    ins_4(60,−144) 跳回 @808 —— 那一句是 t=60 的 ins_144，**不在**环里的 ins_117(0,6)
    ---    之前，所以整段是一轮 480 帧的竖直往返（我们 y = 0/−128/0/+128）。
    ---  · Sub6（@1120，全部指令带 t=14 ⇒ 子上下文建好后第 14 帧才动；自环 2 帧）：
    ---    extraIntV0=4；floatV0=−2.35619（−135°）、floatV1=−0.785398（−45°）；
    ---    ins_101(0, 0x400 BOUNCE_ALL, allow=0, i0=4（反弹上限）, f0=−999⇒用当前速, f1=0)；
    ---    循环体（@1220..@1480，ins_4(14,−260) 跳回 @1220）每 2 帧一次：
    ---      ① extraFloatV0 = 32×randF32（@1220 的 ins_27），ins_38 把它化成极坐标
    ---         （角度 rand(−π,π)）⇒ 出膛点 = 本体 + 半径 ≤32 的随机点；ins_100 设偏移；
    ---      ② ins_87 FAN(型1、色8、1 发、速 2、基准角 floatV0、步长 π/2、flags 1538)
    ---      ③ ins_44(photoIndex,5,…) —— photoIndex < 5 就跳到 @1408，跳过下面一发；
    ---      ④ ins_87 FAN(型1、色10、1 发、速 2、基准角 floatV1、同上)；
    ---      ⑤ floatV0 −= 0.00785398、floatV1 += 0.00785398（ins_16 / ins_15），再归一化。
    ---    ★ 1538 = 0x602 = 0x400 BOUNCE_ALL + 0x200 出场音 + 0x2 SPAWN_FAST；
    ---      本仓库 straight_bullet 自带的 rebound 只能表 0x800、没有反弹上限，所以这
    ---      一类弹**不传 rebound**、四壁反射交给 sg_tr_hook 的 SG_BOUNCE（见上面 :5728）。
    ---    ★ floatV0/floatV1 在 TH095 里是**弧度**，步子 0.00785398 rad = 0.45°/2 帧。
    local BOSS_X, BOSS_START_Y = -128, field_y(-64)
    local HOME_X, HOME_Y = 0, field_y(128)              -- 0 / 96
    local ENTRY_WAIT, ENTRY_TIME = 100, 30
    local EASE_OUT = VALUE_SET.DECEL

    local PHOTO_LIMIT = 6                               -- ins_141(6)
    local CARD_NAME = "錬丹「水銀の海」"
    local CARD_TIME, CARD_HP = 50, 900
    local CARD_ID = 482

    ---Sub3 的竖直往返：目标 TH095 y = 224 / 352 / 224 / 96，各 120 帧（缓动 1/4/1/4）。
    local RAFT_FRAMES = 120
    local RAFT = {
        { field_y(224), 1 },
        { field_y(352), 4 },
        { field_y(224), 1 },
        { field_y(96), 4 },
    }

    ---Sub6 的参数。
    local EMIT_WAIT = 14                                -- 全部指令的 t=14
    local EMIT_GAP = 2                                  -- ins_4(14,−260) ⇒ 每 2 帧一轮
    local EMIT_R = 32                                   -- ins_27 的 32
    local EMIT_SPEED = 2                                -- ins_87 的 speed1（count2=1）
    local EMIT_A0, EMIT_A1 = -2.35619, -0.785398        -- floatV0 / floatV1（弧度）
    local EMIT_STEP = 0.00785398                        -- 每次 +/−0.45°（弧度）
    local EMIT_SECOND_AT = 5                            -- ins_44 的闸（photoIndex ≥ 5）
    local EMIT_FLAGS = 1538                             -- 0x400 BOUNCE + 0x200 音 + 0x2 FAST

    local st = { dead = false }
    local hook_bounce = sg_tr_hook({ sg_rec(SG_BOUNCE, 0, 4, -1, -999, 0) }, SG_BOUNCE)

    ---Sub6：每 2 帧一发「随机出膛点、固定出发角、四壁反弹」的小玉。
    local function run_sub6(owner)
        task.New(owner, function()
            task.Wait(EMIT_WAIT)
            local a0, a1 = EMIT_A0, EMIT_A1
            while not st.dead do
                local m = EMIT_R * ran:Float(0, 1)
                local oa = sg_deg(ran:Float(-math.pi, math.pi))
                local sx, sy = owner.x + m * cos(oa), owner.y + m * sin(oa)
                sg_shot(87, ball_small, ex_color(8), sx, sy,
                        1, 1, EMIT_SPEED, 0.5, math.deg(a0), 90, false,
                        EMIT_FLAGS, hook_bounce)
                if photo_index(PHOTO_LIMIT) >= EMIT_SECOND_AT then
                    sg_shot(87, ball_small, ex_color(10), sx, sy,
                            1, 1, EMIT_SPEED, 0.5, math.deg(a1), 90, false,
                            EMIT_FLAGS, hook_bounce)
                end
                a0 = a0 - EMIT_STEP
                a1 = a1 + EMIT_STEP
                task.Wait(EMIT_GAP)
            end
        end)
    end

    local card = boss.card.New(CARD_NAME, 1, 3, CARD_TIME, CARD_HP)

    function card:before()
    end

    function card:init()
        photo_damage_on(self, PHOTO_LIMIT)
        self.x, self.y = BOSS_X, BOSS_START_Y
        st.dead = false
        task.New(self, function()
            task.Wait(ENTRY_WAIT)
            task.MoveTo(HOME_X, HOME_Y, ENTRY_TIME, EASE_OUT)
            ---到这里是原作 Sub2 的 t=130 = Sub3 的 t=0。
            PlaySound("tan00", 0.1, self.x / 256, false)   -- Sub3 t=0 的 ins_106(5)
            task.Wait(60)
            if st.dead then return end
            run_sub6(self)                                  -- ins_117(0,6)
            ---竖直往返：每段 120 帧，逐段 ins_64；ins_4 到点即回、不留停顿。
            while not st.dead do
                for i = 1, #RAFT do
                    local r = RAFT[i]
                    sg_move(self, st, HOME_X, r[1], RAFT_FRAMES, r[2])
                    task.Wait(RAFT_FRAMES)
                    if st.dead then return end
                end
            end
        end)
    end

    function card:frame()
    end

    function card:del()
        st.dead = true
        photo_damage_off(self)
    end

    boss.card.add({ { card, "9a" } }, LEVEL, CARD_NAME, CARD_ID)
end--錬丹「水銀の海」

do  -- 85 新難題「金閣寺の一枚天井」（ecl19_c，辉夜，组 10a 第 3 张）
    ---原作是「一块天花板」：辉夜站着不动，两股弹并排走 ——
    ---  · 一股每 60 帧放**两波共 32 发沿同一条射线排开的小玉**：从本体出发朝 +x
    ---    （TH095 0°）与 −x（180°），16 发的初速从 8 递减到 0.97（speed1 8 → speed2 0.5，
    ---    count2=16 做线性插值），随后吃 `0x100 CHDIR_ABS` 变换 —— 60 帧里减速到 0、
    ---    到点瞬间把方向**绝对**改成 ±90°、速度改成 1。±90° 取哪一边由「自机在世界 y 的
    ---    哪一侧」现场决定（ins_51 player.y ≥ 本体 worldPosition.y）。于是 16 发小玉被拉成
    ---    一条线、再一起横着滑走，正是一块「天井」。
    ---  · 另一股每 3 帧放四组「十字」（4 发 90° 等分的小玉），基准角各自以 1.5°/2°/3°/4.5°
    ---    每轮的速率自转；后三组要**拍中本体**到 3/5/6 张才解锁（ins_44 的 CMPlt 闸）。
    ---数据源 /tmp/S8_ecl19_c.txt（ECL …/data/ecl19_c.ecl）。骨架：
    ---  · Sub2（@384）：ins_141(7)（拍 7 张）+ t=100 ins_64(30,4,0,128) 落到 (0,128)
    ---    （我们的 (0,96)）→ t=130 亮卡名 + ins_149(4) + ins_132(1) + ins_52(3)。**没有 ins_75**。
    ---  · Sub3（@712）：t=0 extraIntV1=60 + ins_117(0,6)（Sub6，装饰）+ ins_106(5)；
    ---    t=60 ins_117(0,4)=Sub4 + ins_117(1,5)=Sub5；t=180 的 ins_4(60,0) 跳回**自己**
    ---    （偏移 0）⇒ 之后只是把 time 在 60↔180 之间来回拨、什么都不做，Sub4/Sub5 各自死循环。
    ---  · Sub4（@840，60 帧一轮）：t=0 一次 ins_51 比较选方向（成立→@988 的 +π/2、
    ---    否则@928 的 −π/2）→ ins_101(0, 0x100 CHDIR_ABS, allow=0, i0=60, i1=1, f0=±π/2, f1=1)
    ---    → ins_89 CIRCLE；t=30 再一发 ins_89（基准角 π）；t=60 ins_4(0,−216) 跳回 @900。
    ---    ★ 原始字节核过（ecl19_c.ecl @1028/@1072）：op0 = 0xD0001（type 1、color 13）、
    ---      (count1, count2) = (1,16)、speed1 8 / speed2 0.5、angleStep 0、flags 770 ——
    ---      **count1=1 是「每圈 1 发」、count2=16 是「16 圈」**（BulletManager.cpp:706 的
    ---      外层 index2/内层 index1），所以 16 发的角度全相同、速度按 index2 插值。
    ---  · Sub5（@1160，3 帧一轮）：t=14 起每次先在 32 px 内随机取出膛点，再按 photoIndex
    ---    逐级放 1~4 组 ins_89 CIRCLE(count1=4, count2=1)（色 10/8/6/4、速 2/3/1.8/2.3）；
    ---    每出现一次就把那一组的基准角按 ins_16/ins_15 拨 2°/3°/4.5°，总基准角每轮 +1.5°。
    local BOSS_X, BOSS_START_Y = -128, field_y(-64)
    local HOME_X, HOME_Y = 0, field_y(128)              -- 0 / 96
    local ENTRY_WAIT, ENTRY_TIME = 100, 30
    local EASE_OUT = VALUE_SET.DECEL

    local PHOTO_LIMIT = 7                               -- ins_141(7)
    local CARD_NAME = "新難題「金閣寺の一枚天井」"
    local CARD_TIME, CARD_HP = 50, 900
    local CARD_ID = 483

    ---Sub4：CHDIR_ABS 那一波。
    local CEIL_COUNT = 16                               -- count2
    local CEIL_SP1, CEIL_SP2 = 8, 0.5
    local CEIL_FLAGS = 770                              -- 0x100 CHDIR + 0x200 音 + 0x2 FAST
    local CEIL_WAIT = 60                                -- CHDIR 的 i0（也是两次齐射的间隔×2）
    local CEIL_DELTA = 30                               -- t=30 的第二发
    local CEIL_TURN = 90                                -- f0 的绝对值（度）

    ---Sub5：自转十字那一波。
    local CROSS_GAP = 3
    local CROSS_R = 32
    local CROSS_FLAGS = 514
    ---(色号, 速, 解锁张数, 自转步长 rad, 初始基准角 rad) —— 基准角 4 组都是 π/4。
    local CROSS = {
        { 10, 2, 0, 0.0261799, 0.785398 },              -- 1.5°/轮（永远解锁）
        { 8, 3, 3, -0.0349066, 0.785398 },              -- −2°
        { 6, 1.8, 5, 0.0523599, 0.785398 },             -- +3°
        { 4, 2.3, 6, -0.0785398, 0.785398 },            -- −4.5°
    }

    local st = { dead = false }

    ---Sub4：每 60 帧两波「同射线 16 连・减速转向」。
    local function run_sub4(owner)
        task.New(owner, function()
            while not st.dead do
                ---ins_51(player.y, enemy.worldPosition.y)：自机在**下方**（TH095 y 更大）成立
                ---⇒ @988 用 +π/2（下）、否则 @928 用 −π/2（上）。换算到我们这边：
                ---自机在下（我们的 y 更小）⇒ 转向下（−90°），否则转向上（+90°）。
                local f0 = (player.y <= owner.y) and -CEIL_TURN or CEIL_TURN
                local hook = sg_tr_hook(
                        { sg_rec(SG_CHDIR_A, 0, CEIL_WAIT, 1, f0, 1) }, SG_CHDIR_A)
                sg_shot(89, ball_small, ex_color(13), owner.x, owner.y,
                        1, CEIL_COUNT, CEIL_SP1, CEIL_SP2, 0, 0, false, CEIL_FLAGS, hook)
                task.Wait(CEIL_DELTA)
                if st.dead then return end
                sg_shot(89, ball_small, ex_color(13), owner.x, owner.y,
                        1, CEIL_COUNT, CEIL_SP1, CEIL_SP2, 180, 0, false, CEIL_FLAGS, hook)
                task.Wait(CEIL_WAIT - CEIL_DELTA)
            end
        end)
    end

    ---Sub5：每 3 帧一组「随机出膛点 + 自转十字」。
    local function run_sub5(owner)
        task.New(owner, function()
            local a = {}
            for i = 1, #CROSS do
                a[i] = CROSS[i][5]
            end
            while not st.dead do
                local m = CROSS_R * ran:Float(0, 1)
                local oa = sg_deg(ran:Float(-math.pi, math.pi))
                local sx, sy = owner.x + m * cos(oa), owner.y + m * sin(oa)
                local n = photo_index(PHOTO_LIMIT)
                for i = 1, #CROSS do
                    local c = CROSS[i]
                    if n >= c[3] then
                        sg_shot(89, ball_small, ex_color(c[1]), sx, sy,
                                4, 1, c[2], 0.5, math.deg(a[i]), 0, false, CROSS_FLAGS)
                        a[i] = a[i] + c[4]
                    end
                end
                task.Wait(CROSS_GAP)
            end
        end)
    end

    local card = boss.card.New(CARD_NAME, 1, 3, CARD_TIME, CARD_HP)

    function card:before()
    end

    function card:init()
        photo_damage_on(self, PHOTO_LIMIT)
        self.x, self.y = BOSS_X, BOSS_START_Y
        st.dead = false
        task.New(self, function()
            task.Wait(ENTRY_WAIT)
            task.MoveTo(HOME_X, HOME_Y, ENTRY_TIME, EASE_OUT)
            ---到这里是原作 Sub2 的 t=130 = Sub3 的 t=0。
            PlaySound("tan00", 0.1, self.x / 256, false)   -- Sub3 t=0 的 ins_106(5)
            task.Wait(60)
            if st.dead then return end
            run_sub4(self)
            run_sub5(self)
        end)
    end

    function card:frame()
    end

    function card:del()
        st.dead = true
        photo_damage_off(self)
    end

    boss.card.add({ { card, "10a" } }, LEVEL, CARD_NAME, CARD_ID)
end--新難題「金閣寺の一枚天井」

do  -- 86 秘薬「仙香玉兎」（ecl18_d，永琳，组 9a 第 4 张）
    ---原作是「仙香玉兔」：永琳落到场地偏**下**（TH095 y=192 ⇒ 我们的 y=32）后 ——
    ---  · **一帧里一次性**在半径 32 的圆上摆 25 个发射点（每点差 15°），每点同时甩出
    ---    两根 147 旋转激光（type 12、色 6、满长 384 起步、宽 16、启动 40 帧、张开 20、
    ---    维持 12000、收 10、不自转）—— 一共 **50 根**，方向绕 ±67.5° 一路转满一圈；
    ---  · 60 帧之后开始每 90 帧放 4 颗**反弹大玉**（type 17 ⇒ ball_huge、色 2 红），
    ---    4 发 90° 等分、整组转向自机（ins_88 CIRCLE_AIMED），速度 1 + 0.05×拍照数
    ---    （拍中越多越快）；这些大玉吃 `0x400 BOUNCE_ALL`（反弹上限 999）在四壁弹。
    ---数据源 /tmp/S8_ecl18_d.txt（ECL …/data/ecl18_d.ecl）。骨架：
    ---  · Sub2（@388）：ins_141(8)（拍 8 张）+ **没有 ins_104** —— t=130 的卡名那一句位置
    ---    是一条 `id=0`（opcode 0 在 switch 里没有分支 ⇒ NOP）；t=100 ins_64(30,4,0,192)
    ---    落到 (0,192)（我们的 (0,32)）+ ins_149(6) + ins_132(1) + ins_52(3)。
    ---    **没有 ins_75**。卡名我们按 SceneSelect.cpp 的场景表照给（符卡系统需要 CARD_NAME）。
    ---  · Sub3（@652）：t=0 extraIntV1=60 + ins_106(5) + ins_62（special anm，不实现）
    ---    + ins_117(1,5)/ins_117(2,6)（都是 ins_150 装饰，不实现）+ ins_117(0,4)=Sub4；
    ---    t=60 ins_104（亮卡名）+ ins_117(2,7) 把 slot2 换成 **Sub7**；t=61 的 ins_4(60,0)
    ---    跳回自己 ⇒ 只在 60↔61 之间空转（Sub4 一次性、Sub7 自己死循环）。
    ---  · Sub4（@872，全在 t=0）：floatV0=0、floatV1=−1.1781（−67.5°）、floatV2=+1.1781；
    ---    循环体 @952..@1204 —— ins_38 把 floatV0 化成半径 32 的偏移、ins_100 设 shootOffset、
    ---    两根 ins_147(type12, 6, floatV1 / floatV2, 384, 16, 40, 20, 12000, 10, 0, 0)，
    ---    三个浮点各 +0.261799（15°）再归一化；@1220 的 ins_5(0,−268,extraIntV0=24)
    ---    先把计数 −1 再判 ⇒ 循环体走 **25** 遍，然后 ins_100(0,0) + ins_53 自灭。
    ---    ★ 全部指令的 time 都是 0、跳转又把 time 拨回 0 ⇒ 这 25 遍**在同一帧内**跑完。
    ---  · Sub7（@1424）：t=0 ins_101(0, 0x400, allow=0, i0=999（反弹上限）, f0=−999⇒当前速)
    ---    + floatV0 = photoIndex×0.05 + 1；ins_88 CIRCLE_AIMED(type17、色2、4 发、
    ---    speed1=floatV0、angleStep=π/2、flags 1538)；t=90 的 ins_4(0,−88) 跳回 @1464。
    ---    （@1424 那条 ins_101 在跳回点 @1464 之前 ⇒ 只写一次，参数本来也一样。）
    ---  · 147 用 `spawn_ex_laser(..., start_full=true)`；147 的速度固定 8（EclRunTargetPhoto.inl:
    ---    48-70 的 args.speed = 8.0f），angle **不加**自机角（那是 148）。
    ---  · ★ 这些大玉在原作里是**永久留存**的：bounceLimit 999、四壁反射发生在 384×448 的
    ---    场地边上（BulletManager.cpp:959-1001 的 PhotoBulletIsOutsidePlayfield(…,0,0)），
    ---    比「出屏回收」的判据更靠内 ⇒ 弹心永远出不了屏、不会被回收；原作靠全局 640 个弹槽
    ---    封顶。本仓库没有这个槽位上限，所以这张卡的峰值会随时长线性爬到卡结束
    ---    （每 90 帧 4 颗）—— 这是**原作行为**，不是移植泄漏，泄漏扫描里单独记一笔。
    local BOSS_X, BOSS_START_Y = -128, field_y(-64)
    local HOME_X, HOME_Y = 0, field_y(192)              -- 0 / 32
    local ENTRY_WAIT, ENTRY_TIME = 100, 30
    local EASE_OUT = VALUE_SET.DECEL

    local PHOTO_LIMIT = 8                               -- ins_141(8)
    local CARD_NAME = "秘薬「仙香玉兎」"
    local CARD_TIME, CARD_HP = 50, 900
    local CARD_ID = 484

    ---Sub4 的 25 点 × 2 根 147。
    local BURST_N = 25                                  -- ins_5 的 n = 24 ⇒ 25 遍
    local BURST_R = 32                                  -- ins_38 的半径
    local BURST_STEP = 0.261799                         -- 15°（弧度）
    local BURST_A0 = 0                                  -- floatV0 初值（偏移角）
    local BURST_A1, BURST_A2 = -1.1781, 1.1781          -- floatV1 / floatV2（±67.5°）
    local LASER_INDEX = 6                               -- 原作 color 6（laser 贴图行 = color）
    local LASER_LEN, LASER_W, LASER_SPEED = 384, 16, 8  -- 147 的 maximumLength/Width/固定速
    local LASER_STARTUP, LASER_GROW, LASER_SUSTAIN, LASER_FADE = 40, 20, 12000, 10

    ---Sub7 的反弹大玉。
    local BALL_GAP = 90
    local BALL_COUNT = 4
    local BALL_SPEED_BASE, BALL_SPEED_STEP = 1, 0.05    -- 1 + 0.05×photoIndex
    local BALL_FLAGS = 1538                             -- 0x400 BOUNCE + 0x200 音 + 0x2 FAST

    local lasers = {}
    local st = { dead = false }
    local hook_bounce = sg_tr_hook(
            { sg_rec(SG_BOUNCE, 0, 999, -1, -999, 0) }, SG_BOUNCE)

    ---Sub4：一帧甩完 25 点 × 2 根 147。偏移角/束角都从 TH095 弧度换成我们的度。
    local function run_sub4(owner)
        task.New(owner, function()
            local o = BURST_A0
            local a = BURST_A1
            local b = BURST_A2
            for _ = 1, BURST_N do
                local oa = sg_deg(o)
                local sx = owner.x + BURST_R * cos(oa)
                local sy = owner.y + BURST_R * sin(oa)
                spawn_ex_laser(owner, lasers, LASER_INDEX, sx, sy, sg_deg(a),
                        LASER_LEN, LASER_W, LASER_SPEED, LASER_STARTUP, LASER_GROW,
                        LASER_SUSTAIN, LASER_FADE, 0, 0, 0, false, true)
                spawn_ex_laser(owner, lasers, LASER_INDEX, sx, sy, sg_deg(b),
                        LASER_LEN, LASER_W, LASER_SPEED, LASER_STARTUP, LASER_GROW,
                        LASER_SUSTAIN, LASER_FADE, 0, 0, 0, false, true)
                o = o + BURST_STEP
                a = a + BURST_STEP
                b = b + BURST_STEP
            end
        end)
    end

    ---Sub7：每 90 帧 4 颗自机狙反弹大玉，速度随拍照数增长。
    local function run_sub7(owner)
        task.New(owner, function()
            while not st.dead do
                local sp = BALL_SPEED_BASE
                        + BALL_SPEED_STEP * photo_index(PHOTO_LIMIT)
                sg_shot(88, ball_huge, ex_color(2), owner.x, owner.y,
                        BALL_COUNT, 1, sp, 0.5, 0, 90, true, BALL_FLAGS, hook_bounce)
                task.Wait(BALL_GAP)
            end
        end)
    end

    local card = boss.card.New(CARD_NAME, 1, 3, CARD_TIME, CARD_HP)

    function card:before()
    end

    function card:init()
        photo_damage_on(self, PHOTO_LIMIT)
        self.x, self.y = BOSS_X, BOSS_START_Y
        st.dead = false
        task.New(self, function()
            task.Wait(ENTRY_WAIT)
            task.MoveTo(HOME_X, HOME_Y, ENTRY_TIME, EASE_OUT)
            ---到这里是原作 Sub2 的 t=130 = Sub3 的 t=0。
            PlaySound("tan00", 0.1, self.x / 256, false)   -- Sub3 t=0 的 ins_106(5)
            run_sub4(self)                                  -- ins_117(0,4)
            task.Wait(60)
            if st.dead then return end
            run_sub7(self)                                  -- ins_117(2,7)（t=60 的 ins_104 由符卡系统代劳）
        end)
    end

    function card:frame()
    end

    function card:del()
        st.dead = true
        photo_damage_off(self)
        sg_clear(lasers)
    end

    boss.card.add({ { card, "9a" } }, LEVEL, CARD_NAME, CARD_ID)
end--秘薬「仙香玉兎」

do  -- 87 新難題「ミステリウム」（ecl19_d，辉夜，组 10a 第 4 张）
    ---原作是辉夜的最后一道难题「Mysterium」：本体落到场地**偏上**处不再移动，之后每 16 帧
    ---朝一对随机基准角发**两整圈**小玉（色 6 与色 8 各一圈、相隔 8 帧），每圈弹数 =
    ---32 + 2×(拍中本体的张数)（越拍越密）。这些弹起手先沿自己的方向直飞 60 帧，
    ---然后按五段「自转 + 加减速」程序走完 —— 两条色的程序互为镜像：色 6 先减速再加速、
    ---色 8 反过来，每段的自转方向也相反 ⇒ 两圈同源却朝相反方向拧开，像一呼一吸。
    ---数据源 /tmp/S8_ecl19_d.txt（ECL …/data/ecl19_d.ecl，与 th095/src 对照着读），
    ---下面注释里的「@地址」都指这份 dump。骨架：
    ---  · Sub2（@384）：ins_55(2)+ins_81(3)+ins_109(0)+ins_77(24,24)+**ins_141(7)**（拍 7 张）
    ---    + ins_108(0,31)/ins_108(1,30)（子机槽，不实现）
    ---    + ins_143(1,130)（拍照标记，不实现）+ ins_63(-128,-64) 进场
    ---    → t=100 ins_64(30,4,0,192) 落到 (0,192)（我们的 (0, field_y(192)) = (0,32)）
    ---    → t=100 ins_114(7208)（卡计时，不实现）→ t=130 亮卡名 + ins_149(3)/ins_132(1)
    ---    （都不实现）+ ins_52(3) 起 Sub3。
    ---  · Sub3（@696）：t=0 ins_6(extraIntV1,60)（给装饰用）+ ins_106(5)（音效）
    ---    + ins_117(0,5)（Sub5，装饰）；t=60 ins_117(0,6) 起 **Sub6**（发弹体）；
    ---    t=61 的 ins_4(60,0) —— 目标时间 60、位移 0 ⇒ 跳回**它自己**，之后每帧都在
    ---    60↔61 之间空转（原作拿它当 `while(true){}` 的停车位；Sub6 是独立上下文，
    ---    一旦起了就自己跑）。
    ---  · ★ Sub4（@804）在 ecl19_d 里**没有任何 ins_117 引用它**（对比 ecl18_d 的 Sub3
    ---    里有 ins_117(0,4)）—— 是一段死代码：跟 ecl18_d 的「一帧摆 25 个发射点」同构，
    ---    但没有那两句 ins_147，只 ins_100 设完偏移又 ins_100(0,0) 复位、ins_53 自灭，
    ---    净效果为零。照原作**不实现**（本体 shootOffset 全程是 (0,0)，两圈从本体出膛）。
    ---  · Sub5（@1108）：每帧两句 ins_150(8)（在 worldPosition+shootOffset 生成 ANM 装饰），
    ---    t=1 的 ins_4(0,−32) 跳回自己 ⇒ 无限刷装饰。不实现（本仓库不做这种装饰）。
    ---  · Sub6（@1184，一轮 16 帧，@1960 的 ins_4(0,−696) 跳回 @1264）：
    ---      · **进 Sub6 时只做一次**（都在 @1264 的跳回点之前）：
    ---          ins_101(0, 0x400 BOUNCE_ALL, allow=0, i0=999, f0=−999⇒用当前速)；
    ---          floatV0 = rand(−π,π)、floatV1 = rand(−π,π)（这对基准角只抽一次，
    ---          循环里不再重抽，只按下面的步长慢慢转）。
    ---        ★ @1184 的 BOUNCE 记录紧接着被 @1308 的 WAIT 记录**覆盖**（两句的 slot 都
    ---          是 0，ins_101 是按下标写表、不是追加）⇒ 这一圈弹其实**不反弹**，flags 里的
    ---          0x400 因此空转。这是原作的写法，照抄（不像卡 484 那样留永久反弹弹）。
    ---      · 每轮（第一帧 = @1264）：
    ---          extraIntV1 = 32 + 2×photoIndex（ins_22 乘 + ins_10 加）—— 两圈各自的发数；
    ---          写 slot0..5（表 A）→ ins_89 CIRCLE(型3 ball_small、色6、c1=extraIntV1、c2=1、
    ---                              速 1.2、基角 floatV0、步长 π/2、flags 0x8222) ⇒ 色 6 一圈；
    ---        t=8：把 slot0..5 再写一遍（表 B，f0/f1 全部取反）→
    ---             ins_89 CIRCLE(色8、基角 floatV1、其余同上) ⇒ 色 8 一圈；
    ---             floatV0 += 1.5°、floatV1 −= 2°（都走 ins_37 归一化）；
    ---        t=16：跳回。
    ---      · 6 条记录（TH095 口径；kind / allow / i0 / f0 / f1）：
    ---          slot0 WAIT (0x8000) i0=60                                     ← 先直飞 60 帧
    ---          slot1 POLAR(0x20)   i0=60  f0=−1/60   f1=+0.45°/帧
    ---          slot2 POLAR         i0=60  f0=+1/60   f1=−0.45°/帧
    ---          slot3 POLAR         i0=30  f0=0       f1=+0.45°/帧
    ---          slot4 POLAR         i0=30  f0=+1/60   f1=−0.45°/帧
    ---          slot5 POLAR         i0=30  f0=−1/60   f1=0
    ---        （色 8 那一路 = 表 B：把上表 slot1..5 的 f0、f1 全部取反。）
    ---      · 换算：我们的角 = −TH095 角（文件头「坐标系与角度」）⇒ TH095 的
    ---        +0.00785398 rad（=0.45°）在我们这里就是 −0.45°。SG_POLAR 的 f0 是
    ---        「每帧速度增量」（世界单位）、f1 是「每帧角增量（我们的度）」
    ---        —— hook 口径见上面 sg_tr_hook（:5777 起）。
    ---      · 一颗弹的总行程：60 帧直飞 → 再 60+60+30+30+30 = 210 帧程序，速度
    ---        1.2→0.2→1.2（前两段）→1.2（slot3，只自转 13.5°）→1.7→1.2。
    ---        ★ 这些弹不反弹，出屏（x+宽≤−192 / x−宽≥192 / y+高≤0 / y−高≥448）
    ---          就被原作回收（BulletManager.cpp:1506-1512 的 offscreen 判定）——
    ---          不像卡 484 那样无限累积；峰值仍是本组最高的一张（每 8 帧一圈、
    ---          每圈最多 46 发、寿命约 270 帧）。
    local BOSS_X, BOSS_START_Y = -128, field_y(-64)
    local HOME_X, HOME_Y = 0, field_y(192)              -- 0 / 32
    local ENTRY_WAIT, ENTRY_TIME = 100, 30
    local EASE_OUT = VALUE_SET.DECEL

    local PHOTO_LIMIT = 7                               -- ins_141(7)
    local CARD_NAME = "新難題「ミステリウム」"
    local CARD_TIME, CARD_HP = 50, 900
    local CARD_ID = 485

    ---Sub6 的一轮 16 帧：色 6 在 t=0、色 8 在 t=8，然后 t=16 跳回。
    local RING_GAP = 8                                  -- 两圈的间隔（也是半轮长）
    local RING_SPEED = 1.2                              -- ins_89 的 speed1（c2=1 ⇒ 全部用它）
    local RING_BASE, RING_STEP = 32, 2                  -- extraIntV1 = RING_BASE + RING_STEP×拍照数
    local RING_DRIFT_A = 1.5                            -- floatV0 每轮 +1.5°（TH095）⇒ 我们 −1.5°
    local RING_DRIFT_B = 2.0                            -- floatV1 每轮 −2.0°（TH095）⇒ 我们 +2.0°
    local ROT = 0.45                                    -- 0.00785398 rad = 0.45°/帧
    local UP, DN = 0.0166667, -0.0166667                -- ±1/60 世界单位/帧
    local RING_FLAGS = 0x8222                           -- 0x8000 WAIT + 0x200 音 + 0x20 POLAR + 0x2 FAST

    ---表 A（色 6）：先等 60 帧，再减速 60 → 加速 60 → 只自转 30 → 加速 30 → 减速 30。
    local TR_A = {
        sg_rec(SG_WAIT,  0, 60, -1, -1,  -1),
        sg_rec(SG_POLAR, 0, 60, -1, DN,  -ROT),
        sg_rec(SG_POLAR, 0, 60, -1, UP,  ROT),
        sg_rec(SG_POLAR, 0, 30, -1, 0,   -ROT),
        sg_rec(SG_POLAR, 0, 30, -1, UP,  ROT),
        sg_rec(SG_POLAR, 0, 30, -1, DN,  0),
    }
    ---表 B（色 8）：与 A 逐项镜像（f0、f1 同时取反）。
    local TR_B = {
        sg_rec(SG_WAIT,  0, 60, -1, -1,  -1),
        sg_rec(SG_POLAR, 0, 60, -1, DN,  ROT),
        sg_rec(SG_POLAR, 0, 60, -1, UP,  -ROT),
        sg_rec(SG_POLAR, 0, 30, -1, 0,   ROT),
        sg_rec(SG_POLAR, 0, 30, -1, UP,  -ROT),
        sg_rec(SG_POLAR, 0, 30, -1, DN,  0),
    }

    local st = { dead = false }
    local hook_a = sg_tr_hook(TR_A, RING_FLAGS)
    local hook_b = sg_tr_hook(TR_B, RING_FLAGS)

    ---Sub6：每 16 帧两整圈。基准角在 TH095 空间是 rand(−π,π)，整圈取反后方向集合不变，
    ---但每轮的漂移方向要跟着取反 ⇒ a6 每轮 −1.5°、a8 每轮 +2°。
    local function run_sub6(owner)
        task.New(owner, function()
            local a6 = sg_deg(ran:Float(-math.pi, math.pi))     -- floatV0（只抽一次）
            local a8 = sg_deg(ran:Float(-math.pi, math.pi))     -- floatV1（只抽一次）
            while not st.dead do
                local n = RING_BASE + RING_STEP * photo_index(PHOTO_LIMIT)
                sg_shot(89, ball_small, ex_color(6), owner.x, owner.y,
                        n, 1, RING_SPEED, 0, a6, 90, false, RING_FLAGS, hook_a)
                task.Wait(RING_GAP)
                if st.dead then return end
                sg_shot(89, ball_small, ex_color(8), owner.x, owner.y,
                        n, 1, RING_SPEED, 0, a8, 90, false, RING_FLAGS, hook_b)
                task.Wait(RING_GAP)
                a6 = a6 - RING_DRIFT_A
                a8 = a8 + RING_DRIFT_B
            end
        end)
    end

    local card = boss.card.New(CARD_NAME, 1, 3, CARD_TIME, CARD_HP)

    function card:before()
    end

    function card:init()
        photo_damage_on(self, PHOTO_LIMIT)
        self.x, self.y = BOSS_X, BOSS_START_Y
        st.dead = false
        task.New(self, function()
            task.Wait(ENTRY_WAIT)
            task.MoveTo(HOME_X, HOME_Y, ENTRY_TIME, EASE_OUT)
            ---到这里是原作 Sub2 的 t=130 = Sub3 的 t=0。
            PlaySound("tan00", 0.1, self.x / 256, false)   -- Sub3 t=0 的 ins_106(5)
            task.Wait(60)
            if st.dead then return end
            run_sub6(self)                                  -- t=60 的 ins_117(0,6)
        end)
    end

    function card:frame()
    end

    function card:del()
        st.dead = true
        photo_damage_off(self)
    end

    boss.card.add({ { card, "10a" } }, LEVEL, CARD_NAME, CARD_ID)
end--新難題「ミステリウム」

---──────────────────── Stage 7（scene group 6 = world07）── 公共工具 ────────────────────
---原作 scene group 6 是 scene 60..67（th095/src/SceneSelect.cpp:126-133）：
---  60 ecl14_a 咲夜 非符                       61 ecl15_a レミリア 魔符「全世界ナイトメア」
---  62 ecl14_b 咲夜 時符「トンネルエフェクト」   63 ecl15_b レミリア 紅符「ブラッディマジックスクウェア」
---  64 ecl14_c 咲夜 空虚「インフレーションスクウェア」 65 ecl15_c レミリア 紅蝙蝠「ヴァンピリッシュナイト」
---  66 ecl14_d 咲夜 銀符「パーフェクトメイド」   67 ecl15_d レミリア 神鬼「レミリアストーカー」
---八幕共用 world07.std / enm14,15.anm / bgm th095_03.wav（= music.lua 的 "TH07_1"）。
---数据源是 /tmp/N_ecl14_{a..d}.txt 与 /tmp/N_ecl15_{a..d}.txt（脚本 /tmp/d95c.py 不入库；
---ECL 在 `[th095] …/data/ecl1{4,5}_*.ecl`），各卡注释里的「@地址」都指这几份 dump。
---按「一个角色一个组」（文件头 §8）拆：组 11 = 咲夜（60/62/64/66）、组 12 = レミリア（61/63/65/67）。
---
---★ 八张卡的 Sub2 骨架**完全一样**（只有 ins_64 的目标 y 与 ins_75 的框不同）：
---   ins_55(2)/81(3)/109(0)/77(24,24)/141(N)/108(0,31)/108(1,30)/143(1,130)
---   + ins_63(-128,-64) 进场 → t=100 ins_64(30,4,0,Y) → t=130（咲夜 60 是 id=0 的 NOP，
---   其余七张是 ins_104 亮卡名）+ ins_75(box) + ins_149(分数倍率) + ins_52(3)。
---   世界坐标换算：我们的 y = field_y(TH095 的 y) = 224 − y。
---
---★ 立绘：咲夜 "Sakuya"、レミリア "Remilia"（BossImageList.lua:17-18 都登记过）。
---★ Sub2 里的 ins_115（只有 ecl14_a 用）见卡 60 注释：拍中第 3/6 张时把主上下文整个
---   换成 Sub7/Sub11，所以 ecl14_a 的主脚本按拍照进度在 Sub3→Sub7→Sub11 三条之间切换。

---──────────────────── Stage 7 咲夜 非符（ecl14_a，组 11a 第 1 张） ────────────────────
do  -- 60 咲夜 非符（ecl14_a，组 11a 第 1 张）
    ---原作这一关**没有** ins_104（t=130 的 id=0 在 EclRunLow.inl 的 switch 里没有分支
    ---⇒ NOP），是一个前哨：本体站定不动，每隔 155 帧放 4 只「小刀妖精」子机；子机朝四个
    ---方向慢慢飞出去、自己发弹。**主脚本会随拍照进度整个换掉**（ins_115）：
    ---  · Sub2 @27：… + ins_115(0, 3, "Sub7") / ins_115(1, 6, "Sub11") @37/38（frame 比的是
    ---    camera.photoIndex，见文件头「已拍张数」与卡 90 的说明）⇒ 拍中第 3 张时主脚本换成
    ---    Sub7、第 6 张时换成 Sub11。换脚本时本体的 16 个子上下文槽全被释放
    ---    （EnemyManagerUpdate.cpp:1292-1310），但**已经飞出去的子机是独立敌人**（ins_83 生的），
    ---    不受影响、照自己的寿命走完。
    ---  · 三条主脚本的骨架一样（155 帧一轮，t=95/125 各一次 ins_67(60,4,1.4) 在框里漂），
    ---    区别只在「放哪种子机」，而循环标签都在 ins_102 之后 ⇒ **清屏只在换脚本那一次**：
    ---      A 默认 Sub3 @49 → Sub4 @62：标签在 t=0 ⇒ **到场当帧**就放（子机 Sub6 → 发弹 Sub5）。
    ---      B Sub7 @100（第 3 张起）→ Sub8 @115：+30 先 ins_102 + ins_149(4.0) 再放
    ---        （子机 Sub10 → 发弹 Sub9）。
    ---      C Sub11 @160（第 6 张起）→ Sub12 @175：+30 先 ins_102 + ins_149(0.6) 再放
    ---        （子机 Sub14 → 发弹 Sub13）。
    ---  · 子机（真子敌机）Sub4 @62 / Sub8 @115 / Sub12 @175：各写 4 次「[10079] 移动方向 +
    ---    [10080] 0.4」再 ins_83 生一只，四个方向都是 π / 0 / 3π/4 / π/4（TH095 系）。
    ---    Sub8/Sub12 还多写一条 [10009]「转角」= +π/16 / −π/16 / −π/8 / +π/8；A 的 Sub4
    ---    **不写** [10009] ⇒ 转角 0。
    ---  · A 的发弹器 Sub5 @76：t=60 先 ins_7(floatV0, playerAngle)（子机→自机角，只算一次），
    ---    再每 10 帧 ins_89 CIRCLE(型 4、色 6、32 发、速 3、基角 floatV0、flags 514)，
    ---    t=70 ins_4(60,…) 自循环。子机本体 Sub6 @88：t=120 收掉 slot1、t=134 ins_1
    ---    ⇒ 发 t=60..110 共 **6 轮 × 32 发**。
    ---  · B 的发弹器 Sub9 @133：t=60 写 ins_101(slot0 = 0x800 BOUNCE_EXCEPT_BOTTOM、int0 = 1
    ---    ⇒ 只弹一次；slot1 = 0x4000 SET_SPRITE 型 14 色 3→色 5，纯换色、本仓库不实现) +
    ---    ins_7(floatV0, playerAngle)；循环体（t=70 跳回 t=60）：ins_89 CIRCLE(型 14、色 3、
    ---    4 发、速 2、基角 floatV0、flags 18946) 后 ins_15(floatV0, floatV1) ⇒ **每轮基角
    ---    += 自己的转角**。子机本体 Sub10 @148：t=180 收掉 slot1、t=194 ins_1
    ---    ⇒ 发 t=60..170 共 **12 轮 × 4 发**。
    ---  · C 的发弹器 Sub13 @193：首条指令就带 +30，写 6 条 ins_101（WAIT 20 / CHDIR_REL
    ---    floatV2 各三条）+ floatV0 = π/2 + floatV1；循环体（t=34 跳回 t=30）每 4 帧
    ---    ins_89 CIRCLE(型 14、色 2、8 发、速 4、基角 floatV0、flags 33346)，弹每 20 帧
    ---    拐一次弯。子机本体 Sub14 @213：t=160 收掉 slot1、t=174 ins_1
    ---    ⇒ 发 t=30..158 共 **33 轮 × 8 发**。
    ---★ ins_89 的 9 个 operand 就是 (bulletType, color, count1, count2, speed1, speed2,
    ---  angle, angleStep, transformFlags)（EnemyShotDispatch.cpp:104-135）；count2 = 1 ⇒
    ---  speed2 与 angleStep 都不参与（0.1848 rad = 10.588° 只是占位）。
    local BOSS_X, BOSS_START_Y = -128, field_y(-64)     -- 288（场地外）
    local HOME_X, HOME_Y = 0, field_y(128)              -- 0 / 96
    local ENTRY_WAIT, ENTRY_TIME = 100, 30
    local EASE_OUT = VALUE_SET.DECEL
    local PHOTO_LIMIT = 9                               -- ins_141(9)
    local CARD_NAME = ""                                -- 非符：没有 ins_104
    local CARD_TIME, CARD_HP = 50, 900
    local CARD_ID = 486

    local BOX = { -160, 96, 160, 192 }                  -- ins_75（TH095 坐标）
    local DRONE_SPEED = 0.4                             -- [10080] = extraFloat[3] = 0.4
    local DRONE_STEP = 10.5880                          -- 0.1848 rad（count2 = 1 ⇒ 占位）
    ---子机的移动方向（[10079] = extraFloat[2]，TH095 弧度）——Sub4/Sub8/Sub12 完全一样。
    local DRONE_DIRS = { math.pi, 0, 3 * math.pi / 4, math.pi / 4 }
    ---子机的「转角」（[10009] = floatV1，TH095 弧度）——只有 Sub8/Sub12 写（A 分支 = 0）。
    local DRONE_TURNS = { math.pi / 16, -math.pi / 16, -math.pi / 8, math.pi / 8 }
    ---三条发弹脚本的代号（A/B/C）与各自 ins_89 的 flags。
    local DRONE_FAN32, DRONE_RING4, DRONE_RING8 = 1, 2, 3
    local FLAGS_FAN32, FLAGS_RING4, FLAGS_RING8 = 514, 18946, 33346

    local st = { dead = false }
    local drones = {}
    local lasers = {}
    local gen = 0                                       -- 当前主脚本代号（ins_115 换脚本时 +1）
    local fired = { false, false }                      -- 两条 ins_115 是否已触发

    local function alive(g)
        return g == gen and not st.dead
    end

    ---Sub13 的 ins_101 表（C 分支）：WAIT 20 → CHDIR_REL floatV2，共三组。
    ---f0 用我方口径（sg_tr_hook 的 recs 一律是「度、逆时针为正」）；turn = −floatV2。
    local function zigzag(turn)
        return sg_tr_hook({
            sg_rec(SG_WAIT,    0, 20, -1, -1, -1),
            sg_rec(SG_CHDIR_R, 0, 1, 1, turn, -999),
            sg_rec(SG_WAIT,    0, 20, -1, -1, -1),
            sg_rec(SG_CHDIR_R, 0, 1, 1, turn, -999),
            sg_rec(SG_WAIT,    0, 20, -1, -1, -1),
            sg_rec(SG_CHDIR_R, 0, 1, 1, turn, -999),
        }, FLAGS_RING8)
    end

    ---Sub9 的 ins_101 表（B 分支）：slot0 = 0x800 BOUNCE_EXCEPT_BOTTOM，int0 = 1 ⇒ 弹到
    ---左右/上边界各反弹一次就把这条变换收掉（BulletManager.cpp:959-1001）；slot1 的
    ---0x4000 SET_SPRITE（型 14 色 3→色 5）是纯换色，本仓库没法半路换贴图 ⇒ 不实现。
    local function bounce_once()
        return sg_tr_hook({ sg_rec(SG_BOUNCE_EB, 0, 1, -1, -1, -1) }, FLAGS_RING4)
    end

    ---小刀子机（原作是真子敌机；这里按文件头差异 5 改成**有寿命的自绘 object**）。
    ---mode 决定用哪一条发弹脚本；th_dir / th_turn 是 ECL 里的弧度原值（[10079]/[10009]）。
    class.s7a_drone = Class(object, {
        init = function(self, owner, mode, th_dir, th_turn)
            self.group = GROUP.GHOST
            self.layer = LAYER.ENEMY_BULLET_EF
            self.colli = false
            self.bound = false                           -- 自己管回收
            self.x, self.y = owner.x, owner.y
            self.rot, self._a = 0, 0
            ---Sub4/Sub8/Sub12 的 ins_65(extraFloat[2], extraFloat[3])：方向 / 速 0.4。
            object.SetV(self, DRONE_SPEED, -math.deg(th_dir), true)
            ---★ frame 里必须自己 task.Do(self)：真机只有 `_object`（misc.lua:13）和
            ---  bullet 才带 task.Do，`Class(object, {...})` 的子类没有 —— 漏了协程就永远
            ---  不 resume（卡 71 的 moth / 卡 80 的 nightmare_drone 就踩过这个坑）。
            task.New(self, function()
                ---出场淡入 8 帧（观感；原作是 SPAWN_FAST 的 ANM 出场动画，差异 5）。
                for k = 1, 8 do
                    self._a = min(200, math.floor(200 * k / 8))
                    task.Wait(1)
                end
                ---以「子机年龄」为准排程：age = 现在的帧 − 出生帧，下面每个 for 的 k
                ---直接对应 ECL 里的时刻（Sub5/Sub9 从 t=60 起、Sub13 从 t=30 起）。
                local age = 8
                local function skip_to(t)
                    while age < t do
                        task.Wait(1)
                        age = age + 1
                    end
                end
                if mode == DRONE_FAN32 then
                    ---Sub5：t=60 起每 10 帧一圈 32 发；基角 = 子机→自机角，只算一次。
                    skip_to(60)
                    local base = -Angle(self.x, self.y, player.x, player.y)
                    for k = 0, 5 do                          -- t=60,70,…,110（6 轮）
                        skip_to(60 + 10 * k)
                        sg_shot(89, ball_mid, ex_color(6), self.x, self.y,
                                32, 1, 3, 1.5, base, DRONE_STEP, false, FLAGS_FAN32)
                    end
                    skip_to(120)                             -- Sub6 收掉 slot1
                elseif mode == DRONE_RING4 then
                    ---Sub9：t=60 起每 10 帧 4 发；每轮结束后基角 += 自己的转角。
                    skip_to(60)
                    local base = -Angle(self.x, self.y, player.x, player.y)
                    local hook = bounce_once()
                    for k = 0, 11 do                         -- t=60,70,…,170（12 轮）
                        skip_to(60 + 10 * k)
                        sg_shot(89, ball_mid, ex_color(3), self.x, self.y,
                                4, 1, 2, 1.5, base, DRONE_STEP, false,
                                FLAGS_RING4, hook)
                        base = base + math.deg(th_turn)      -- ins_15(floatV0, floatV1)
                    end
                    skip_to(180)                             -- Sub10 收掉 slot1
                else
                    ---Sub13：t=30 起每 4 帧一圈 8 发；基角 = π/2 + 自己的转角，固定。
                    local base = math.deg(math.pi / 2 + th_turn)
                    local hook = zigzag(-math.deg(th_turn))
                    for k = 0, 32 do                         -- t=30,34,…,158（33 轮）
                        skip_to(30 + 4 * k)
                        sg_shot(89, ball_mid, ex_color(2), self.x, self.y,
                                8, 1, 4, 1.5, base, DRONE_STEP, false,
                                FLAGS_RING8, hook)
                    end
                    skip_to(160)                             -- Sub14 收掉 slot1
                end
                ---Sub6/Sub10/Sub14 末尾的 `+14: ins_1`（淡出，观感）。
                for k = 1, 14 do
                    self._a = max(0, math.floor(200 * (14 - k) / 14))
                    task.Wait(1)
                end
                object.RawDel(self)
            end)
        end,
        frame = function(self)
            task.Do(self)
            self.rot = self.rot + 6                      -- 小刀自转
        end,
        render = function(self)
            SetImageState("servant", "mul+add", self._a, 220, 228, 255)
            Render("servant", self.x, self.y, self.rot, 0.9)
        end,
    })

    ---放一波 4 只子机（Sub4/Sub8/Sub12 里那四个 ins_83）。
    local function spawn_wave(owner, mode)
        for k = 1, #DRONE_DIRS do
            ---A 的 Sub4 不写 [10009]（Sub5 也不读它）⇒ 转角 0。
            local turn = (mode == DRONE_FAN32) and 0 or DRONE_TURNS[k]
            drones[#drones + 1] = New(class.s7a_drone, owner, mode, DRONE_DIRS[k], turn)
        end
    end

    ---Sub3：默认主脚本（拍中 < 3 张时）。循环标签在 t=0 ⇒ **到场当帧**就放第一波。
    local function run_default(owner)
        local g = gen
        task.New(owner, function()
            while alive(g) do
                spawn_wave(owner, DRONE_FAN32)           -- t=0
                task.Wait(95)
                if not alive(g) then return end
                sg_bmove(owner, st, 60, 4, 1.4, BOX)     -- t=95
                task.Wait(60)                            -- t=155 跳回 t=0
            end
        end)
    end

    ---Sub7（第 3 张起）/ Sub11（第 6 张起）：+30 先清一次屏，再进同样的 155 帧循环。
    ---循环标签在 t=30 ⇒ ins_102 只在换脚本这一次，之后每轮从 t=30 重来（不再清屏）。
    local function run_from_30(owner, mode)
        local g = gen
        task.New(owner, function()
            task.Wait(30)
            if not alive(g) then return end
            sg_clear(lasers)                             -- ins_102
            while alive(g) do
                spawn_wave(owner, mode)                  -- t=30
                task.Wait(95)
                if not alive(g) then return end
                sg_bmove(owner, st, 60, 4, 1.4, BOX)     -- t=125
                task.Wait(60)                            -- t=185 跳回 t=30
            end
        end)
    end

    ---ins_115 的「拍中第 k 张」监视器（frame = camera.photoIndex）。
    local function watcher(owner)
        task.New(owner, function()
            while not st.dead do
                local hits = photo_index(PHOTO_LIMIT)
                if hits >= 3 and not fired[1] then
                    fired[1] = true
                    gen = gen + 1
                    ---主上下文整个重开 ⇒ 本体那条 ins_67 的插值移动也一起没了。
                    if st.mv then st.mv.alive = false end
                    run_from_30(owner, DRONE_RING4)      -- Sub7
                elseif hits >= 6 and not fired[2] then
                    fired[2] = true
                    gen = gen + 1
                    if st.mv then st.mv.alive = false end
                    run_from_30(owner, DRONE_RING8)      -- Sub11
                end
                task.Wait(1)
            end
        end)
    end

    local card = boss.card.New(CARD_NAME, 1, 3, CARD_TIME, CARD_HP)

    function card:before()
        drones = {}
    end

    function card:init()
        photo_damage_on(self, PHOTO_LIMIT)
        self.x, self.y = BOSS_X, BOSS_START_Y
        st.dead = false
        fired = { false, false }
        gen = gen + 1
        task.New(self, function()
            task.Wait(ENTRY_WAIT)
            task.MoveTo(HOME_X, HOME_Y, ENTRY_TIME, EASE_OUT)
            run_default(self)                            -- Sub3
            watcher(self)
        end)
    end

    function card:frame()
    end

    function card:del()
        st.dead = true
        photo_damage_off(self)
        for i = #drones, 1, -1 do
            if IsValid(drones[i]) then
                task.Clear(drones[i])
                object.RawDel(drones[i])
            end
        end
        drones = {}
    end

    boss.card.add({ { card, "11a" } }, LEVEL, CARD_NAME, CARD_ID)
end--咲夜 非符（ecl14_a）

---──────────────────── Stage 7 魔符「全世界ナイトメア」（ecl15_a，组 12a 第 1 张） ────────────────────
do  -- 61 レミリア 魔符「全世界ナイトメア」（ecl15_a，组 12a 第 1 张）
    ---原作是「满世界的蝙蝠」：本体在框里漂，**每 96 帧**放一只蝙蝠（子机）到处飞，
    ---蝙蝠越飞越快；另外两条发弹上下文（Sub5 窄扇 / Sub6 整圈）的弹数都写成
    ---`int(photosTaken/7)` 与 `int(photosTaken/15)` —— 这一关的快门上限只有 3（ins_141(3)），
    ---**永远算得出 0 发**，所以这一张的威胁全在蝙蝠身上（这正是原作的样子）。
    ---骨架（/tmp/N_ecl15_a.txt）：
    ---  · Sub2：t=130 ins_104 亮卡名 + ins_75(-160,96,160,192) + ins_149(2)。
    ---  · Sub3 @684：t=0 起装饰 Sub7；t=60 起 Sub4（蝙蝠发生器）+ 音效；t=90 起 Sub5（slot1）/
    ---    Sub6（slot2）+ ins_67；t=210 亮卡名 + 起 Sub7（slot3）；t=270 再起一轮并重复。
    ---  · Sub4 @1164：extraIntV0=96，`ins_83(8)` 每 96 帧生一只 Sub8；V2 = rand[0,π)、V3 = rand[0,2)。
    ---  · Sub8 @2080（蝙蝠）：ins_65(V2,V3)（随机方向、随机初速）+ ins_71(0.0666667)
    ---    （加速度 = 1/15 世界单位/帧）；t=300 ins_1 结束。
    local BOSS_X, BOSS_START_Y = -128, field_y(-64)
    local HOME_X, HOME_Y = 0, field_y(128)              -- 0 / 96
    local ENTRY_WAIT, ENTRY_TIME = 100, 30
    local EASE_OUT = VALUE_SET.DECEL
    local PHOTO_LIMIT = 3                               -- ins_141(3)
    local CARD_NAME = "魔符「全世界ナイトメア」"
    local CARD_TIME, CARD_HP = 50, 900
    local CARD_ID = 487

    local BOX = { -160, 96, 160, 192 }
    ---Sub4（t=60）：ins_6(extraInt0, 96) + ins_5(0, Sub4_108, extraInt0) ⇒ **96 只蝙蝠、
    ---一帧一只**（一帧一圈，见 EclRunLow.inl 的 5/4 分支），打完 Sub4 就结束。
    ---Sub8（蝙蝠本体）：ins_71(1/15) 每帧加速，t=300 ins_1 结束。
    local BAT_COUNT, BAT_LIFE, BAT_ACC = 96, 300, 1 / 15
    local BAT_AT, FAN_AT, WALK_AT, WALK_ROUNDS = 60, 90, 150, 10
    local WALK_SPEED = 0.5

    local st = { dead = false }
    local bats = {}

    class.s7b_bat = Class(object, {
        init = function(self, owner)
            self.group = GROUP.GHOST
            self.layer = LAYER.ENEMY_BULLET_EF
            self.colli = false
            self.bound = false
            self.x, self.y = owner.x, owner.y
            self.rot, self._a = 0, 0
            ---Sub8 的 ins_65(extraFloatV2, extraFloatV3)：方向 rand[0,π)（TH095）、速 rand[0,2)。
            self._dir = sg_deg(ran:Float(0, math.pi))    -- 我们的角度（度）
            self._sp = ran:Float(0, 2)
            object.SetV(self, self._sp, self._dir, true)
            task.New(self, function()
                for _ = 1, 8 do
                    self._a = min(210, self._a + 26)
                    task.Wait()
                end
                ---ins_71(0.0666667)：每帧 speed += 1/15，方向不变（加速直线）。
                for _ = 1, BAT_LIFE do
                    self._sp = self._sp + BAT_ACC
                    object.SetV(self, self._sp, self._dir, true)
                    task.Wait()
                end
                for _ = 1, 15 do
                    self._a = max(0, self._a - 210 / 15)
                    task.Wait()
                end
                object.RawDel(self)
            end)
        end,
        frame = function(self)
            task.Do(self)
            self.rot = self.rot + 8
        end,
        render = function(self)
            SetImageState("butterfly6", "mul+add", self._a, 255, 120, 150)
            Render("butterfly6", self.x, self.y, self.rot, 1.0)
            SetImageState("butterfly4", "mul+add", self._a * 0.6, 220, 90, 130)
            Render("butterfly4", self.x - cos(self.rot) * 10, self.y - sin(self.rot) * 10,
                    self.rot + 40, 0.7)
        end,
    })

    ---Sub5（slot1）：每 4 帧一轮、一轮 3 把扇（每把再 +120°）；弹数 = photosTaken + 7
    ---（intV0 = photosTaken + 7，ins_20(+, 10084, 7)）。8 轮（ins_6(extraInt0,8)）之后
    ---ins_4(0, Sub5_0) 从头重来、重读一次自机角 ⇒ 每 32 帧重瞄准一次。
    ---本移植按用户口径用「拍中本体」的张数（photo_index）当 photosTaken。
    local FAN5_COUNT, FAN5_ROUNDS = 7, 8
    local function run_fan5(owner)
        task.New(owner, function()
            while not st.dead do
                local a = sg_aim(owner.x, owner.y)      -- Sub5_0 的 ins_7(floatV0, playerAngle)
                for _ = 1, FAN5_ROUNDS do
                    local n = photo_index(PHOTO_LIMIT) + FAN5_COUNT
                    for _ = 1, 3 do
                        sg_shot(87, sg_style(4), ex_color(2), owner.x, owner.y,
                                n, 1, 4, 1.5, a, 5.625, false, 514, nil)
                        a = a + 120
                    end
                    task.Wait(4)
                end
            end
        end)
    end

    ---Sub6（slot2）：每 60 帧一圈；弹数 = photosTaken + 15（ins_20(+, 10084, 15)）。
    ---同样 8 轮之后重开、重读自机角（每 480 帧）。
    local FAN6_COUNT, FAN6_ROUNDS = 15, 8
    local function run_fan6(owner)
        task.New(owner, function()
            while not st.dead do
                local a = sg_aim(owner.x, owner.y)
                for _ = 1, FAN6_ROUNDS do
                    local n = photo_index(PHOTO_LIMIT) + FAN6_COUNT
                    sg_shot(88, sg_style(12), ex_color(1), owner.x, owner.y,
                            n, 1, 1, 1.5, a, 5.625, true, 514, nil)
                    task.Wait(60)
                end
            end
        end)
    end

    local card = boss.card.New(CARD_NAME, 1, 3, CARD_TIME, CARD_HP)

    function card:before()
        bats = {}
    end

    function card:init()
        photo_damage_on(self, PHOTO_LIMIT)
        self.x, self.y = BOSS_X, BOSS_START_Y
        st.dead = false
        task.New(self, function()
            task.Wait(ENTRY_WAIT)
            task.MoveTo(HOME_X, HOME_Y, ENTRY_TIME, EASE_OUT)
            ---Sub3 的 t=0 从这里算起（Sub2 在 t=130 才 ins_52(3)）。
            ---t=90（@90）：slot1 = Sub5、slot2 = Sub6（另开任务，两个都是不阻塞的常驻循环）。
            task.New(self, function()
                task.Wait(FAN_AT)
                if st.dead then return end
                run_fan5(self)
                run_fan6(self)
            end)
            ---t=60（@60）：slot0 的 Sub7（扇翅，不实现）被换成 Sub4 —— 96 只蝙蝠一帧一只。
            task.New(self, function()
                task.Wait(BAT_AT)
                for _ = 1, BAT_COUNT do
                    if st.dead then return end
                    bats[#bats + 1] = New(class.s7b_bat, self)
                    task.Wait(1)
                end
            end)
            ---Sub3_152（存储时间 150）+ ins_5(90, Sub3_152, extraInt0=10)：ins_5 把 ECL 计时
            ---拨回 90 再跳回，所以**实机每 60 帧一次 ins_67**，两把轮着（缓动 1 / 缓动 4），
            ---10 轮之后落到存储时间 270 的 ins_104（亮卡名）；第二段从存储时间 330 起再来 10 轮。
            task.Wait(WALK_AT)                          -- → t=150
            for _ = 1, WALK_ROUNDS do
                sg_bmove(self, st, 60, 1, WALK_SPEED, BOX)     -- ins_67(60,1,0.5)
                task.Wait(60)
                sg_bmove(self, st, 60, 4, WALK_SPEED, BOX)     -- ins_67(60,4,0.5)
                task.Wait(60)
            end
            if st.dead then return end
            task.Wait(60)                               -- t=1350 的 ins_104（亮卡名，不实现）
            for _ = 1, WALK_ROUNDS do
                sg_bmove(self, st, 60, 1, WALK_SPEED, BOX)
                task.Wait(60)
                sg_bmove(self, st, 60, 4, WALK_SPEED, BOX)
                task.Wait(60)
            end
        end)
    end

    function card:frame()
    end

    function card:del()
        st.dead = true
        photo_damage_off(self)
        for i = #bats, 1, -1 do
            if IsValid(bats[i]) then
                task.Clear(bats[i])
                object.RawDel(bats[i])
            end
        end
        bats = {}
    end

    boss.card.add({ { card, "12a" } }, LEVEL, CARD_NAME, CARD_ID)
end--魔符「全世界ナイトメア」

---──────────────────── Stage 7 時符「トンネルエフェクト」（ecl14_b，组 11a 第 2 张） ────────────────────
do  -- 62 咲夜 時符「トンネルエフェクト」（ecl14_b，组 11a 第 2 张）
    ---原作是「一条穿过自己的隧道」：本体停在 (0,160)（我们的 (0,64)），一圈一圈地放：
    ---  · Sub5 @1128：进每轮 t=0 时**一圈** type14/色1 的整圈弹，弹数 = 16 + 8×photoIndex；
    ---  · Sub6..9 @1300/1792/2304/2796：四条并行上下文，把发弹点放在**离本体 160 px、
    ---    角度 extraFloatV2 的点**上，每轮转 2π/(8+4×photoIndex)，每次发 3 发（c1=1、c2=3）
    ---    速度 4 / 3.167 / 2.333、方向 = 环上角度 − π。四条只在「上/下」与「顺时针/逆时针」
    ---    上两两不同 ⇒ 看起来像四股沿着隧道内壁扫过去的弹流。
    ---  · Sub4 @980 在每轮 t=120 接管 slot0：每 15 帧一把 3 发**大玉**（型 17，直径 28
    ---    ⇒ ball_huge）、加了自机角的 FAN_AIMED、散布 72°。
    ---骨架（/tmp/N_ecl14_b.txt）：
    ---  · Sub2：t=130 亮卡名 + ins_75(-160,144,160,224) + ins_149(2) + ins_52(3)。
    ---  · Sub3 @736：t=0 ins_117(0,5)…(4,9)（五条上下文）+ extraIntV1=60；t=60 音/ins_67(60,4,1)；
    ---    t=120 ins_117(0,4)（slot0 换成大玉）+ ins_118(19)；t=150 ins_144(15)；
    ---    t=195 ins_4(0,-192) 回 t=0 ⇒ 一輪 195 帧。
    ---  · Sub6 的运算（@1396-1744）**逐条核过**：extraIntV0 = (16+8×photoIndex)/2；
    ---    floatV7 = 2π/extraIntV0；38(floatV2,floatV3, ±π/2, 160) → 环上一点；再
    ---    26/26 把自己（world.x/y）减掉，得到相对本体的 shootOffset（0, ∓160）；
    ---    floatV4 = extraFloatV2 + (−π)（ins_25）；87 FAN(型14色3, 1, 3, 4, 1.5, floatV4,
    ---    0.1848, 512)；floatV7 每轮加/减后归一化（Sub6/8 加、Sub7/9 减）。
    local BOSS_X, BOSS_START_Y = -128, field_y(-64)
    local HOME_X, HOME_Y = 0, field_y(160)              -- 0 / 64
    local ENTRY_WAIT, ENTRY_TIME = 100, 30
    local EASE_OUT = VALUE_SET.DECEL
    local PHOTO_LIMIT = 5                               -- ins_141(5)
    local CARD_NAME = "時符「トンネルエフェクト」"
    local CARD_TIME, CARD_HP = 50, 900
    local CARD_ID = 488

    local BOX = { -160, 144, 160, 224 }
    local CYCLE = 195
    local RING_R_UP, RING_R_DOWN = 160, 60               -- extraFloatV3：Sub6/7 = 160、Sub8/9 = 60
    local st = { dead = false }

    ---Sub5：进每轮 t=0 时一圈（一次，不重复）。
    local function ring_burst(owner)
        local n = 16 + 8 * photo_index(PHOTO_LIMIT)
        sg_shot(89, sg_style(14), ex_color(1), owner.x, owner.y,
                n, 1, 2, 1.5, 0, 5.625, false, 514, nil)
    end

    ---Sub6..9：一条「隧道内壁」弹流。sign = +1 表示环角每轮 +2π/n（Sub6/8），−1 = Sub7/9；
    ---up = +1 表示环点在 −π/2（本体上方，Sub6/7），−1 = +π/2（下方，Sub8/9）。
    ---四条都在子上下文建立那一帧（Sub3 的 t=0）记下本体的 f0/f1，环心是那个位置，不是
    ---每帧的当前位置；发弹从 t=80 才起（Sub6..9 的 `+80`），n 发一发一帧。
    local function tunnel_stream(owner, sign, up)
        ---ECL：ins_7(f0, enemy.x) / ins_7(f1, enemy.y) 在 +80 之前 ⇒ 先记位置再等。
        local ox, oy = owner.x, owner.y
        task.New(owner, function()
            local n = 8 + 4 * photo_index(PHOTO_LIMIT)   -- extraIntV0 = (16+8p)/2
            local step = 360 / n                          -- floatV7 = 2π/extraIntV0（度）
            local ang = up and -90 or 90                  -- extraFloatV2 = ∓π/2（TH095，度）
            local R = up and RING_R_UP or RING_R_DOWN     -- extraFloatV3
            task.Wait(80)                                 -- Sub6..9 的 `+80`
            for _ = 1, n do
                ---环上一点（TH095 空间）→ 我们 = (x, −y) 的偏移。
                local px = ox + R * math.cos(math.rad(ang))
                local py = oy - R * math.sin(math.rad(ang))
                ---方向 = 环上角度 − π（TH095）⇒ base 直接给 TH095 度数（sg_shot 内部取反）。
                sg_shot(87, sg_style(14), ex_color(3), px, py,
                        1, 3, 4, 1.5, ang - 180, 5.625, false, 512, nil)
                ang = ang + sign * step
                if st.dead then return end
                task.Wait()
            end
        end)
    end

    ---Sub4：每 15 帧一把 3 发大玉（型 17 = ball_huge）、FAN_AIMED、散布 72°。
    local function huge_fan(owner)
        task.New(owner, function()
            for _ = 1, 5 do                              -- t=120..195 只有 5 个周期
                sg_shot(86, sg_style(17), ex_color(0), owner.x, owner.y,
                        3, 1, 3.5, 1.5, 0, 36, true, 514, nil)
                if st.dead then return end
                task.Wait(15)
            end
        end)
    end

    local card = boss.card.New(CARD_NAME, 1, 3, CARD_TIME, CARD_HP)

    function card:before()
    end

    function card:init()
        photo_damage_on(self, PHOTO_LIMIT)
        self.x, self.y = BOSS_X, BOSS_START_Y
        st.dead = false
        task.New(self, function()
            task.Wait(ENTRY_WAIT)
            task.MoveTo(HOME_X, HOME_Y, ENTRY_TIME, EASE_OUT)
            while not st.dead do
                ring_burst(self)                         -- Sub5 @ t=0
                tunnel_stream(self,  1, true)            -- Sub6：上方 r=160、+step
                tunnel_stream(self, -1, true)            -- Sub7：上方 r=160、−step
                tunnel_stream(self,  1, false)           -- Sub8：下方 r=60、+step
                tunnel_stream(self, -1, false)           -- Sub9：下方 r=60、−step
                task.Wait(60)                            -- t=60
                if st.dead then return end
                sg_bmove(self, st, 60, 4, 1, BOX)        -- ins_67(60,4,1)
                task.Wait(60)                            -- t=120
                if st.dead then return end
                huge_fan(self)                           -- Sub4 接管 slot0
                task.Wait(CYCLE - 120)
            end
        end)
    end

    function card:frame()
    end

    function card:del()
        st.dead = true
        photo_damage_off(self)
    end

    boss.card.add({ { card, "11a" } }, LEVEL, CARD_NAME, CARD_ID)
end--時符「トンネルエフェクト」

---──────────────────── Stage 7 紅符「ブラッディマジックスクウェア」（ecl15_b，组 12a 第 2 张） ────────────────────
do  -- 63 レミリア 紅符「ブラッディマジックスクウェア」（ecl15_b，组 12a 第 2 张）
    ---原作是「血色的魔法阵」：本体停在 (0,160)（我们的 (0,64)），每轮甩出**一圈 12 颗**
    ---慢速方块（型 14 色 1，速 0.3，每颗差 30°）；每颗方块自己**不断**再炸出朝某方向
    ---漂走的子弹 —— 方块上挂的 ins_101 表（@932-1132）逐条核过：
    ---  slot0 0x400000 SPAWN_CHILD_PATTERN：packed=0x01010208 ⇒ aim=FAN(1)、型 1、色 2、
    ---        子弹出厂就从**第 8 条记录**起跑；count1=1、speed1=speed2=0；子表 flags=0x8212。
    ---  slot1 是 slot0 的 secondary（count2=1、angle=floatV0、angleStep=0）——它的 kind
    ---        字段（0x800000）是**填充值**，运行时不会读。
    ---  slot2 0x20 ACCEL_POLAR：0.033333/帧 的加速 + ±1°/帧 的自转，持续 extraIntV1 帧。
    ---  slot3 0x2000000 JUMP 到第 0 条 ⇒ 方块每（extraIntV1+1）帧再炸一颗、无限循环。
    ---  slot8 0x8000 WAIT 120、slot9 0x10 ACCEL_VEC(240 帧、0.008333/帧、用出厂角) ⇒
    ---        子弹（从 slot8 起跑）先**定住 120 帧**，再沿自己出厂的方向慢慢加速出去。
    ---  extraIntV1 = 9 − photoIndex（ins_21 是 op1 − op2，@908）⇒ 拍得越多炸得越密。
    ---骨架（/tmp/N_ecl15_b.txt）：
    ---  · Sub2：t=130 ins_104 + ins_75(-160,144,160,224) + ins_149(2.7) + ins_52(3)。
    ---  · Sub3 @716：t=60 ins_117(0,4)；t=180 ins_67(60,4,2)；t=240 ins_144(15) + ins_117(0,4)；
    ---    t=240 ins_4(60,-60) 跳回 t=60 ⇒ 一輪 180 帧（且每轮把方块的基准角再转 30°）。
    ---  · Sub4 @848：floatV1=−π、floatV0=rand(−π,π)、extraIntV0=12；写 6 条 ins_101 后
    ---    ins_89 CIRCLE(型14色1, c1=1, c2=1, sp1=0.3, base=floatV1, 步长 0.1848, flags
    ---    0x02400222)；floatV1 += 30°、floatV0 −= 5.625°；ins_5(0,-324,12) 把整段跑 12 次。
    local BOSS_X, BOSS_START_Y = -128, field_y(-64)
    local HOME_X, HOME_Y = 0, field_y(160)              -- 0 / 64
    local ENTRY_WAIT, ENTRY_TIME = 100, 30
    local EASE_OUT = VALUE_SET.DECEL
    local PHOTO_LIMIT = 7                               -- ins_141(7)
    local CARD_NAME = "紅符「ブラッディマジックスクウェア」"
    local CARD_TIME, CARD_HP = 50, 900
    local CARD_ID = 489

    local BOX = { -160, 144, 160, 224 }
    local CYCLE = 180
    local SQ_FLAGS = 0x02400222                         -- CHILD | JUMP | 音 | POLAR | FAST
    local CHILD_FLAGS = 0x8212                          -- WAIT | 音 | ACCEL_VEC | FAST
    local st = { dead = false }

    ---方块的表：前半跑「炸子弹」，后半（slot8/9）是给子弹跑的那一段。
    ---child_ang = ECL 的 floatV0（TH095 弧度）：slot1 的 payload.float0 ⇒ 子弹出厂角
    ---（BulletManager.cpp 的 SPAWN_CHILD：pattern.angle = 第二条记录的 float0）。
    local function square_recs(dur, ang_delta, child_ang)
        return {
            sg_rec(SG_CHILD, 0, 0x01010208, 1, 0, 0),    -- slot0：packed/angleStep 已算好
            sg_rec(0,       0, 1, CHILD_FLAGS, child_ang, 0), -- slot1：secondary（kind 不重要）
            sg_rec(SG_POLAR, 0, dur, -1, 0.0333333, ang_delta),
            sg_rec(SG_JUMP,  0, 0, -1, -1, -1),          -- slot3：跳回 slot0
            sg_rec(0, 0, 0, 0, 0, 0), sg_rec(0, 0, 0, 0, 0, 0),
            sg_rec(0, 0, 0, 0, 0, 0), sg_rec(0, 0, 0, 0, 0, 0),
            sg_rec(SG_WAIT,  0, 120, -1, -1, -1),        -- slot8：子弹先定住 120 帧
            sg_rec(SG_VEC,   0, 240, -1, 0.0083333, -999.99),
        }
    end

    ---Sub4：24 颗方块，全部在同一帧里发出来（两段 ins_5 循环体里都没有 time 标记）：
    ---前 12 颗 floatV1 每颗 +30°、极坐标角速度 +1°/帧；后 12 颗继续 +30°、角速度 −1°/帧
    ---（两段各 12 颗，第二段的 floatV0 接着第一段继续 −5.625°/颗）。
    local function square_ring(owner)
        local dur = 9 - photo_index(PHOTO_LIMIT)         -- extraIntV1
        local a = -180                                   -- floatV1 起手 −π（TH095 度）
        local c = ran:Float(-math.pi, math.pi)           -- floatV0 = rand[−π,π)（TH095 弧度）
        for i = 1, 24 do
            local rot = (i <= 12) and 1 or -1            -- 两段 ins_5：+1°/帧、−1°/帧
            local hook = sg_tr_hook(square_recs(dur, rot, c), SQ_FLAGS)
            sg_shot(89, sg_style(14), ex_color(1), owner.x, owner.y,
                    1, 1, 0.3, 1.5, a, 10.5880, false, SQ_FLAGS, hook)
            a = a + 30
            if a >= 180 then a = a - 360 end
            c = c - 0.09817477                           -- ins_16(f0, 5.625°)（TH095 弧度）
        end
    end

    local card = boss.card.New(CARD_NAME, 1, 3, CARD_TIME, CARD_HP)

    function card:before()
    end

    function card:init()
        photo_damage_on(self, PHOTO_LIMIT)
        self.x, self.y = BOSS_X, BOSS_START_Y
        st.dead = false
        task.New(self, function()
            task.Wait(ENTRY_WAIT)
            task.MoveTo(HOME_X, HOME_Y, ENTRY_TIME, EASE_OUT)
            while not st.dead do
                square_ring(self)
                task.Wait(120)                            -- t=120（Sub3 的 t=180 相位）
                if st.dead then return end
                sg_bmove(self, st, 60, 4, 2, BOX)         -- ins_67(60,4,2)
                task.Wait(CYCLE - 120)
            end
        end)
    end

    function card:frame()
    end

    function card:del()
        st.dead = true
        photo_damage_off(self)
    end

    boss.card.add({ { card, "12a" } }, LEVEL, CARD_NAME, CARD_ID)
end--紅符「ブラッディマジックスクウェア」

---──────────────────── Stage 7 空虚「インフレーションスクウェア」（ecl14_c，组 11a 第 3 张） ────────────────────
do  -- 64 咲夜 空虚「インフレーションスクウェア」（ecl14_c，组 11a 第 3 张）
    ---原作是「不断膨胀的方块」：本体停在 (0,224)（我们的 (0,0)），一条上下文分两段：
    ---  ① @944-1404：30 轮、每轮 2 发 —— 绕着**自机前方 96 px 的那个点**（38/15/15/26/26/100）
    ---     发 type4/色2 的单发（86 FAN_AIMED、速 2），每轮把基准角 +6°；
    ---  ② @1428-1832（本卡核心）：每轮在场地里随机抽一个点（x∈±192、y∈[0,448] TH095），
    ---     离自机 < 64 px 就**重抽**（ins_45 float< 跳回），否则在那个点发一颗 type14/色3、
    ---     速度 = 1 + 0.2×photoIndex、方向 = rand(−π,π) + 自机角（86 FAN_AIMED）。
    ---骨架（/tmp/N_ecl14_c.txt）：
    ---  · Sub2：t=130 ins_104 + ins_75(-160,96,160,256) + ins_149(2.1) + ins_52(3)。
    ---  · Sub3 @716：t=60 ins_117(0,4)；t=180 ins_117(0,-1) 收掉；t=315 ins_67(60,4,1)；
    ---    t=375 ins_4(0,-136) ⇒ 一輪 375 帧（只有前 120 帧在发弹）。
    ---  · Sub4 @904：floatV1=−π（随后被 world.y 覆盖）、extraIntV0=30、extraFloatV2=π。
    ---    ins_5(0,-400,30)（t=1）⇒ ① 段跑 30 次；② 段的 ins_5(1,-296,4) + ins_4(1,-384)
    ---    是「每 4 次重抽一轮」的写法，等价于连续循环。
    local BOSS_X, BOSS_START_Y = -128, field_y(-64)
    local HOME_X, HOME_Y = 0, field_y(224)              -- 0 / 0
    local ENTRY_WAIT, ENTRY_TIME = 100, 30
    local EASE_OUT = VALUE_SET.DECEL
    local PHOTO_LIMIT = 6                               -- ins_141(6)
    local CARD_NAME = "空虚「インフレーションスクウェア」"
    local CARD_TIME, CARD_HP = 50, 900
    local CARD_ID = 490

    local BOX = { -160, 96, 160, 256 }
    local CYCLE = 375
    local R = 96                                        -- ① 段的半径（extraFloatV3）
    local st = { dead = false }

    ---① 段：30 轮 × 2 发，绕着自机前方 96 px 的点。
    local function phase1(owner)
        task.New(owner, function()
            local ang = 180                             -- extraFloatV2 = π（TH095 度）
            for _ = 1, 30 do
                local px = player.x + R * math.cos(math.rad(ang))
                local py = player.y - R * math.sin(math.rad(ang))
                for k = 1, 2 do
                    sg_shot(86, sg_style(4), ex_color(2), px, py,
                            1, 1, 2, 1.5, 0, 36, true, 514, nil)
                    ang = ang + 6                       -- extraFloatV2 += 6°
                    px = player.x + R * math.cos(math.rad(ang))
                    py = player.y - R * math.sin(math.rad(ang))
                end
                if st.dead then return end
                task.Wait(1)
            end
        end)
    end

    ---② 段：随机点撒弹（速度 1 + 0.2×photoIndex），离自机太近就重抽。
    ---Sub3 在 t=180 用 ins_117(0,-1) 把 Sub4 整个收掉 ⇒ ② 段不是永生任务；
    ---stop 由主循环在 Sub4 的 120 帧窗口结束时置上，否则每轮都会多留一条常驻发弹线。
    ---★ ② 段的内层 ins_5(1,-296,4) 循环体里**没有 time 标记** ⇒ 每帧重抽 4 次
    ---   （不是 1 次）；ins_5(1,-384) 的外层才是「每帧一轮」。
    local function phase2(owner, stop)
        task.New(owner, function()
            while not st.dead and not stop.on do
                for _ = 1, 4 do                          -- extraIntV0 = 4
                    local thx = ran:Float(-1, 1) * 192   -- randF32s × 192
                    local thy = ran:Float(0, 1) * 448    -- randF32 × 448
                    local px, py = thx, field_y(thy)     -- 我们的坐标
                    local dx, dy = player.x - px, player.y - py
                    if dx * dx + dy * dy >= 64 * 64 then
                        sg_shot(86, sg_style(14), ex_color(3), px, py,
                                1, 1, 1 + 0.2 * photo_index(PHOTO_LIMIT), 1.5,
                                sg_deg(ran:Float(-math.pi, math.pi)), 36, true, 514, nil)
                    end
                end
                task.Wait(1)
            end
        end)
    end

    local card = boss.card.New(CARD_NAME, 1, 3, CARD_TIME, CARD_HP)

    function card:before()
    end

    function card:init()
        photo_damage_on(self, PHOTO_LIMIT)
        self.x, self.y = BOSS_X, BOSS_START_Y
        st.dead = false
        task.New(self, function()
            task.Wait(ENTRY_WAIT)
            task.MoveTo(HOME_X, HOME_Y, ENTRY_TIME, EASE_OUT)
            ---Sub3：t=60 起 Sub4（① 段 30 帧 → ② 段 90 帧），t=180 收掉，t=195 ins_144(15)、
            ---t=315 ins_67(60,4,1)、t=375 ins_4(0,-136) 跳回 t=0 ⇒ 一輪 375 帧。
            while not st.dead do
                task.Wait(60)                            -- t=60 ins_117(0,"Sub4")
                if st.dead then return end
                phase1(self)                             -- ① 段：30 帧
                task.Wait(30)                            -- t=90
                if st.dead then return end
                local stop = { on = false }
                phase2(self, stop)                       -- ② 段：t=90..180
                task.Wait(90)                            -- t=180 ins_117(0,-1) 收掉 Sub4
                stop.on = true
                if st.dead then return end
                task.Wait(15)                            -- t=195 ins_144(15)
                task.Wait(120)                           -- t=315
                if st.dead then return end
                sg_bmove(self, st, 60, 4, 1, BOX)        -- ins_67(60,4,1)
                task.Wait(60)                            -- t=375 ins_4(0,-136)
            end
        end)
    end

    function card:frame()
    end

    function card:del()
        st.dead = true
        photo_damage_off(self)
    end

    boss.card.add({ { card, "11a" } }, LEVEL, CARD_NAME, CARD_ID)
end--空虚「インフレーションスクウェア」

---──────────────────── Stage 7 紅蝙蝠「ヴァンピリッシュナイト」（ecl15_c，组 12a 第 3 张） ────────────────────
do  -- 65 レミリア 紅蝙蝠「ヴァンピリッシュナイト」（ecl15_c，组 12a 第 3 张）
    ---原作是「成群的吸血蝙蝠」：本体在 (0,224)（我们的 (0,0)），每 10 帧在**自机周围 ±64**
    ---放一只蝙蝠；蝙蝠用 120 帧飞到那个点，然后按（60 − 7×photoIndex）帧的间隔发单发
    ---（速 1 + 0.1×photoIndex、方向 rand(−π,π)+自机角），共发 int(600/间隔) 发。
    ---拍得越多，蝙蝠发得越快（间隔越短），子弹也越快。
    ---骨架（/tmp/N_ecl15_c.txt）：
    ---  · Sub2：t=130 ins_104 + ins_75(-160,96,160,256) + ins_149(4) + ins_52(3)。
    ---  · Sub3 @728：t=0 起装饰 Sub5；t=60 起 Sub4（蝙蝠发生器）；t=120 ins_67(60,4,1.5)；
    ---    t=180 ins_4(60,-24) ⇒ 一輪 120 帧。
    ---  · Sub4 @844：V0 = randF32s×64 + player.x、V1 = randF32s×64 + player.y；ins_83(6)；
    ---    t=10 ins_4(0,-104) ⇒ 每 10 帧一只。
    ---  · Sub6 @1084：ins_64(120,4,V0,V1)（120 帧飞过去）+ ins_112(7)（**设被拍中时跑的
    ---    子程序**，EclRunTargetHigh.inl:133 —— 不是清屏）；
    ---    intV1 = photoIndex×7（ins_22）；intV1 = 60 − intV1（ins_21）；intV0 = 600/intV1；
    ---    floatV0 = 1 + photoIndex×0.1；86 FAN_AIMED(型14色1, c1=1, base=rand(−π,π), flags 514)；
    ---    ins_2(intV1)（冻结）；ins_5(120,-152,intV0) 循环；ins_1 结束。
    local BOSS_X, BOSS_START_Y = -128, field_y(-64)
    local HOME_X, HOME_Y = 0, field_y(224)              -- 0 / 0
    local ENTRY_WAIT, ENTRY_TIME = 100, 30
    local EASE_OUT = VALUE_SET.DECEL
    local PHOTO_LIMIT = 7                               -- ins_141(7)
    local CARD_NAME = "紅蝙蝠「ヴァンピリッシュナイト」"
    local CARD_TIME, CARD_HP = 50, 900
    local CARD_ID = 491

    local BOX = { -160, 96, 160, 256 }
    local BAT_GAP, BAT_ARRIVE, BAT_FIRE_LIFE = 10, 120, 600
    local st = { dead = false }
    local bats = {}

    class.s7c_bat = Class(object, {
        init = function(self, owner, tx, ty)
            self.group = GROUP.GHOST
            self.layer = LAYER.ENEMY_BULLET_EF
            self.colli = false
            self.bound = false
            self.x, self.y = owner.x, owner.y
            self.rot, self._a = 0, 0
            ---ins_64(120,4,tx,ty)：120 帧、缓动 4（1−(1−n)²）飞到那个点。
            ---★ 移动状态用每只蝙蝠**自己**那一份：旧写法把本体卡的 st 递进去，
            ---  等于每生一只蝙蝠就把本体的 ins_67 插值掐掉一次（每 10 帧一次）。
            local mv = { dead = false }
            self._mv = mv
            sg_move(self, mv, tx, ty, BAT_ARRIVE, 4)
            task.New(self, function()
                task.Wait(BAT_ARRIVE)                    -- t=120（ins_64 那段跑完）
                if not IsValid(self) then return end
                ---ins_112(7) 只是「这个敌人被拍中时跑 Sub7」⇒ 本仓库不做小怪的拍照判定，
                ---跳过（不实现成清屏）。
                local gap = 60 - 7 * photo_index(PHOTO_LIMIT)   -- ins_22 + ins_21
                local n = math.floor(BAT_FIRE_LIFE / max(1, gap))
                local sp = 1 + 0.1 * photo_index(PHOTO_LIMIT)
                for _ = 1, n do
                    sg_shot(86, sg_style(14), ex_color(1), self.x, self.y,
                            1, 1, sp, 1.5,
                            sg_deg(ran:Float(-math.pi, math.pi)), 36, true, 514, nil)
                    if st.dead then return end
                    task.Wait(gap)                       -- ins_2(gap) + ins_5 的组合节拍
                end
                object.RawDel(self)
            end)
        end,
        frame = function(self)
            task.Do(self)
            if self._a < 220 then
                self._a = min(220, self._a + 28)         -- 出生 8 帧内淡入（旧写法多占 8 帧）
            end
            self.rot = self.rot + 9
        end,
        render = function(self)
            SetImageState("butterfly6", "mul+add", self._a, 255, 110, 140)
            Render("butterfly6", self.x, self.y, self.rot, 1.1)
            SetImageState("butterfly2", "mul+add", self._a * 0.6, 230, 80, 120)
            Render("butterfly2", self.x - cos(self.rot) * 11, self.y - sin(self.rot) * 11,
                    self.rot + 50, 0.75)
        end,
    })

    ---Sub4：每 10 帧一只蝙蝠，落点 = 自机 ±64。
    local function run_spawner(owner)
        task.New(owner, function()
            while not st.dead do
                local tx = ran:Float(-1, 1) * 64 + player.x
                local ty = ran:Float(-1, 1) * 64 + player.y
                bats[#bats + 1] = New(class.s7c_bat, owner, tx, ty)
                task.Wait(BAT_GAP)
            end
        end)
    end

    local card = boss.card.New(CARD_NAME, 1, 3, CARD_TIME, CARD_HP)

    function card:before()
        bats = {}
    end

    function card:init()
        photo_damage_on(self, PHOTO_LIMIT)
        self.x, self.y = BOSS_X, BOSS_START_Y
        st.dead = false
        task.New(self, function()
            task.Wait(ENTRY_WAIT)
            task.MoveTo(HOME_X, HOME_Y, ENTRY_TIME, EASE_OUT)
            ---Sub3 的 ins_4(60,-24) 跳回目标是 ins_67（@788），而起 Sub4 的 ins_117(@768)
            ---在跳回目标**之前** ⇒ 蝙蝠发生器只起一次。放进循环里重起会让发生器一帧多个
            ---（自检里 7200 帧堆到 3767 个 object），那是移植错误、不是原作行为。
            run_spawner(self)
            while not st.dead do
                task.Wait(60)
                if st.dead then return end
                sg_bmove(self, st, 60, 4, 1.5, BOX)      -- ins_67(60,4,1.5)
                task.Wait(60)
            end
        end)
    end

    function card:frame()
    end

    function card:del()
        st.dead = true
        photo_damage_off(self)
        for i = #bats, 1, -1 do
            if IsValid(bats[i]) then
                task.Clear(bats[i])
                object.RawDel(bats[i])
            end
        end
        bats = {}
    end

    boss.card.add({ { card, "12a" } }, LEVEL, CARD_NAME, CARD_ID)
end--紅蝙蝠「ヴァンピリッシュナイト」

---──────────────────── Stage 7 銀符「パーフェクトメイド」（ecl14_d，组 11a 第 4 张） ────────────────────
do  -- 66 咲夜 銀符「パーフェクトメイド」（ecl14_d，组 11a 第 4 张）
    ---原作是「两把相对旋转的银刀」：本体停在 (0,128)（我们的 (0,96)），两条上下文
    ---（Sub4 @940 / Sub5 @1192）每 8 帧各放一整圈小刀（型 14 色 3、速 2），
    ---圈数 = 8 + photoIndex（ins_6 复制 + ins_10 加 8）；两圈的基准角每轮一个 +6°、一个 −9°，
    ---所以两条反向的刀圈互相穿过。
    ---骨架（/tmp/N_ecl14_d.txt）：
    ---  · Sub2：t=130 ins_104 + ins_75(-160,96,160,192) + ins_149(3) + ins_52(3)。
    ---  · Sub3 @720：t=0 ins_119(20)（相机过渡回调，不实现）+ ins_117(0,4)+ins_117(1,5)；
    ---    t=120 ins_0（NOP）+ ins_42(extraIntV2,0,…)：extraIntV2 是「相机过渡剩余帧数」，
    ---    由回调 20 置 120（EclExtended.cpp:703）⇒ 拍照过渡中跳过 ins_67 的位移；
    ---    本移植没有那套过渡（项目自机自带相机）⇒ extraIntV2 恒 0、这一支恒真，照走
    ---    + ins_119(-1) + ins_144(30) + ins_67(40,4,2.6)；t=160 ins_119(20) + ins_4(0,-112)。
    ---  · Sub4/Sub5：floatV0 = π/2；每轮开头 ins_43(world.x, floatV1)（float≠）——
    ---    **8 帧内本体移动过就跳过这一圈的弹**（跳到 @1016/@1268 的 floatV0 更新处），
    ---    所以 ins_67 位移的那 40 帧里两条刀圈都不发弹；
    ---    intV0 = photoIndex + 8；ins_89 CIRCLE(型14色3, c1=intV0, sp1=2, 步长 0.1848,
    ---    flags 514)；Sub4 每轮 floatV0 += 6°、Sub5 每轮 −9°。
    local BOSS_X, BOSS_START_Y = -128, field_y(-64)
    local HOME_X, HOME_Y = 0, field_y(128)              -- 0 / 96
    local ENTRY_WAIT, ENTRY_TIME = 100, 30
    local EASE_OUT = VALUE_SET.DECEL
    local PHOTO_LIMIT = 5                               -- ins_141(5)
    local CARD_NAME = "銀符「パーフェクトメイド」"
    local CARD_TIME, CARD_HP = 50, 900
    local CARD_ID = 492

    local BOX = { -160, 96, 160, 192 }
    local GAP = 8
    local st = { dead = false }

    ---drift = 每轮基准角的变化（TH095 度）：Sub4 = +6、Sub5 = −9。
    ---ins_43(world.x, floatV1)：本体 x 与上一轮记下的值不相等（= 这 8 帧里动过）就不发弹。
    ---f1 在每轮末尾 `ins_7(f1, world.x)` 更新，所以判据是「本轮开头和上一轮末尾的 x 相同」。
    local function ring(owner, drift)
        task.New(owner, function()
            local a = 90                                  -- floatV0 = π/2（TH095 度）
            local last = owner.x                          -- floatV1（子上下文建立那帧）
            while not st.dead do
                if owner.x == last then                   -- ins_43：没动过才发
                    local n = 8 + photo_index(PHOTO_LIMIT)
                    sg_shot(89, sg_style(14), ex_color(3), owner.x, owner.y,
                            n, 1, 2, 1.5, a, 10.5880, false, 514, nil)
                end
                a = a + drift
                if a >= 180 then a = a - 360 elseif a < -180 then a = a + 360 end
                last = owner.x                            -- ins_7(f1, world.x)
                task.Wait(GAP)
            end
        end)
    end

    local card = boss.card.New(CARD_NAME, 1, 3, CARD_TIME, CARD_HP)

    function card:before()
    end

    function card:init()
        photo_damage_on(self, PHOTO_LIMIT)
        self.x, self.y = BOSS_X, BOSS_START_Y
        st.dead = false
        task.New(self, function()
            task.Wait(ENTRY_WAIT)
            task.MoveTo(HOME_X, HOME_Y, ENTRY_TIME, EASE_OUT)
            ---Sub3 的 ins_4(0,-112) 跳回目标是 @796（ins_0 NOP），而起 Sub4/Sub5 的两条
            ---ins_117(@756/@776) 在目标**之前** ⇒ 两条刀圈只起一次；循环里只有 ins_67 位移。
            ring(self, 6)                             -- Sub4
            ring(self, -9)                            -- Sub5
            while not st.dead do
                task.Wait(120)                            -- t=120
                if st.dead then return end
                sg_bmove(self, st, 40, 4, 2.6, BOX)       -- ins_67(40,4,2.6)
                task.Wait(40)                             -- t=160
            end
        end)
    end

    function card:frame()
    end

    function card:del()
        st.dead = true
        photo_damage_off(self)
    end

    boss.card.add({ { card, "11a" } }, LEVEL, CARD_NAME, CARD_ID)
end--銀符「パーフェクトメイド」

---──────────────────── Stage 7 神鬼「レミリアストーカー」（ecl15_d，组 12a 第 4 张） ────────────────────
do  -- 67 レミリア 神鬼「レミリアストーカー」（ecl15_d，组 12a 第 4 张）
    ---原作是「レミリア追着你跑」：本体在**很窄的框** (-128,96,128,144) 里漂，一轮 240 帧：
    ---  · Sub4 @1064：t=0 **一帧里**甩出 24 根**旋转激光**（ins_153：型1色2、最大长 512、
    ---    宽 16、四段 90/20/30/10、角速 0、follow=1 每帧拉回本体），角度 = playerAngle
    ---    + 15°/根，共 24 根（扫满一圈）。两段 ins_5 的循环体里**没有 time 标记**
    ---    ⇒ 不是「每 24 帧一根」。
    ---  · Sub5 @1284：t=90 接管 slot0 —— 同样一帧里 24 根**直线激光**（ins_145：型12色1、
    ---    速 12、长 144、宽 64），角度接着 Sub3 在 t=0 抽好的那个自机角、每根 +15°。
    ---  · Sub8 @1744：t=150 起，**每帧**在**离本体 60×rand 的一个随机方向点**上发一圈
    ---    type4/色2：弹数 = 1 + int(photoIndex/2)、速 1、方向 rand(−π,π)、步长 0.1848；
    ---    2400 发的上限没意义（每 240 帧就被 Sub3 的 ins_117(3,8) 重起）。
    ---  · Sub7 @1592：t=30 起本体抖 ±4 px；t=90 用 ins_63(V0,V1) 回位。
    ---骨架（/tmp/N_ecl15_d.txt）：Sub2 t=130 ins_104 + ins_75(-128,96,128,144) + ins_149(3.1)；
    ---Sub3 t=0 记 extraFloatV0/V1 = world.x/y、extraFloatV2 = playerAngle、起 Sub4/Sub6；
    ---t=30 起 Sub7；t=90 停 Sub6/Sub7、回位、起 Sub5；t=94 ins_144(20)；t=150 ins_67 + 起 Sub8；
    ---t=240 ins_4(0,-280) ⇒ 一輪 240 帧。
    ---★ ins_153/145 的「角」在 TH095 里不加自机角（EclRunTargetPhoto.inl:85/1），
    ---  所以这里的自机角是 Sub3 在 t=0 抽好、逐根 +15° 的那个 extraFloatV2。
    local BOSS_X, BOSS_START_Y = -128, field_y(-64)
    local HOME_X, HOME_Y = 0, field_y(128)              -- 0 / 96
    local ENTRY_WAIT, ENTRY_TIME = 100, 30
    local EASE_OUT = VALUE_SET.DECEL
    local PHOTO_LIMIT = 7                               -- ins_141(7)
    local CARD_NAME = "神鬼「レミリアストーカー」"
    local CARD_TIME, CARD_HP = 50, 900
    local CARD_ID = 493

    local BOX = { -128, 96, 128, 144 }                  -- ins_75（很窄）
    local CYCLE = 240
    local LASER_ROT, LASER_STR = 2, 12                  -- 贴图行（旋转 / 直线）
    local st = { dead = false }
    local lasers = {}

    ---Sub4：24 根旋转激光（ins_153）。四段 90/20/30/10、角速 0、follow=1；同一帧全出。
    ---a0 = Sub3 在 t=0 抽的 extraFloatV2（TH095 度），每根 +15°。
    local function rot_laser(owner, a0)
        local a_th = a0
        for _ = 1, 24 do
            spawn_ex_laser(owner, lasers, LASER_ROT, owner.x, owner.y,
                    math.rad(-a_th), 512, 16, 8, 90, 20, 30, 10, 0, 0, 0,
                    true, false)
            a_th = a_th + 15
            if a_th >= 180 then a_th = a_th - 360 end
        end
    end

    ---Sub5：24 根直线激光（ins_145）。型12色1、速 12、长 144、宽 64；同一帧全出。
    local function str_laser(owner, a0)
        local a_th = a0
        for _ = 1, 24 do
            spawn_ex_laser_straight(owner, lasers, LASER_STR, owner.x, owner.y,
                    math.rad(-a_th), 144, 64, 12)
            a_th = a_th + 15
            if a_th >= 180 then a_th = a_th - 360 end
        end
    end

    ---Sub7（t=30..90）：本体在「t=0 记下的位置」上随机抖 ±4 px（ins_63 直接设坐标）。
    local function jitter(owner, bx, by, stop)
        task.New(owner, function()
            while not st.dead and not stop.on do
                owner.x = bx + ran:Float(-1, 1) * 4
                owner.y = by - ran:Float(-1, 1) * 4      -- TH095 的 y 偏到我们这一侧取反
                task.Wait(1)
            end
        end)
    end

    ---Sub8：每帧在随机点发一圈 type4/色2（弹数 = 1 + photoIndex/2）；每轮被重起。
    ---Sub3 每轮都用 ins_117(3,8) 重起它 ⇒ 旧的 Sub8 被它占用的 slot 3 顶掉；
    ---本仓库没有 context slot，只能自己在重起前掐掉上一条，否则每轮多留一条常驻发弹线。
    local star_task = nil
    local function star_ring(owner)
        if star_task then star_task.alive = false end
        local t = { alive = true }
        star_task = t
        task.New(owner, function()
            while not st.dead and t.alive do
                local d = 60 * ran:Float(0, 1)
                local a = ran:Float(-math.pi, math.pi)   -- TH095 空间的方向
                local px = owner.x + d * math.cos(a)
                local py = owner.y - d * math.sin(a)     -- TH095 y 轴翻过来
                local n = 1 + math.floor(photo_index(PHOTO_LIMIT) / 2)
                sg_shot(89, sg_style(4), ex_color(2), px, py,
                        n, 1, 1, 1.5, math.deg(ran:Float(-math.pi, math.pi)), 10.5880,
                        false, 514, nil)
                task.Wait(1)
            end
        end)
    end

    local card = boss.card.New(CARD_NAME, 1, 3, CARD_TIME, CARD_HP)

    function card:before()
        lasers = {}
        star_task = nil
    end

    function card:init()
        photo_damage_on(self, PHOTO_LIMIT)
        self.x, self.y = BOSS_X, BOSS_START_Y
        st.dead = false
        task.New(self, function()
            task.Wait(ENTRY_WAIT)
            task.MoveTo(HOME_X, HOME_Y, ENTRY_TIME, EASE_OUT)
            while not st.dead do
                local bx, by = self.x, self.y            -- extraFloatV0/V1（t=0 记下）
                local a0 = sg_aim(self.x, self.y)         -- extraFloatV2 = playerAngle（t=0）
                rot_laser(self, a0)                       -- Sub4 @ t=0
                task.Wait(30)                             -- t=30：Sub7 起
                local jit = { on = false }
                jitter(self, bx, by, jit)
                task.Wait(60)                             -- t=90：停 Sub6/Sub7、回位、Sub5 接管
                jit.on = true
                if st.dead then return end
                self.x, self.y = bx, by                   -- ins_63(extraFloatV0, extraFloatV1)
                str_laser(self, a0)                       -- Sub5
                task.Wait(60)                             -- t=150（t=94 的 ins_144(20) 只是特效）
                if st.dead then return end
                sg_bmove(self, st, 60, 4, 0.5, BOX)       -- ins_67(60,4,0.5)
                star_ring(self)                           -- Sub8
                task.Wait(CYCLE - 150)
            end
        end)
    end

    function card:frame()
    end

    function card:del()
        st.dead = true
        photo_damage_off(self)
        sg_clear(lasers)
    end

    boss.card.add({ { card, "12a" } }, LEVEL, CARD_NAME, CARD_ID)
end--神鬼「レミリアストーカー」
---──────────────────── Stage 6 橙 非符（ecl12_a，组 13a 第 1 张） ────────────────────
do  -- 50 橙 非符（ecl12_a，组 13a 第 1 张）
    ---原作这一关**没有** ins_104（t=130 是一条 `id=0`，opcode 0 在 EclRunLow.inl 的
    --- switch 里没有分支 ⇒ NOP），是个前哨：橙从场外落到场地中心，两条**参数完全相同**的
    ---发弹上下文（Sub5 / Sub6 的字节码逐条一样）轮流甩「正六边形 × 16 档速度」的两组弹；
    ---另有一条装饰/位移上下文每 20 帧在活动框里漂一次。
    ---数据源 /tmp/W6d_ecl12_a.txt（ECL …/data/ecl12_a.ecl）。骨架：
    ---  · Sub2 @384：ins_141(8) ⇒ 拍 8 张；ins_63(-128,-64) 进场 → t=100
    ---    ins_64(30,4,0,224) 用 30 帧落到 TH095 (0,224)（我们的 (0,0)）→ t=130 的 NOP
    ---    + ins_75(-160,128,160,345) + ins_52(3) 起主脚本（@660）。
    ---  · Sub3 @660：t=0 起 Sub4（ins_52(4)）+ 把 slot0 换成 Sub5；t=20 再起一次 Sub4
    ---    + 把 slot0 换成 Sub6；t=40 的 ins_4(0,-72) 跳回 @680（t=0 那两条）⇒ 40 帧一轮、
    ---    每 20 帧一波。@660 的 ins_6(extraIntV1,60) 在跳转目标**之前** ⇒ 只写一次。
    ---  · Sub4 @784：t=15 的 ins_67(20,4,8) 在活动框里按「背离自机」的随机方向漂 160 px；
    ---    其余（ins_144 / ins_119）不实现。
    ---  · Sub5 @900 / Sub6 @1052：进上下文**立刻**发两组 —— ins_101 写 slot0 的
    ---    0x10 VEC（120 帧、每帧 −1/24、方向取出生角），然后
    ---      OCIRC_AIMED：型 6、色 14、c1=6、c2=16、速 4→1.1875、flags 0x212（带 VEC）
    ---      CIRC_AIMED ：同参、flags 0x202（**不带** VEC）
    ---    ⇒ 前一组 96 发沿各自出生方向减速到 −1，后一组 96 发匀速；一波共 192 发。
    ---    c1=6 是每档速度 6 发（六边形），c2=16 是 16 档速度（4 → 1.1875）。
    ---    OCIRC 把整圈再转 180/c1 = 30°，所以两组六边形的相位差 30°。
    local BOSS_X, BOSS_START_Y = -128, field_y(-64)     -- 288（场地外）
    local HOME_X, HOME_Y = 0, 0                          -- TH095 (0,224)
    local ENTRY_WAIT, ENTRY_TIME = 100, 30
    local EASE_OUT = VALUE_SET.DECEL
    local PHOTO_LIMIT = 8                               -- ins_141(8)
    local CARD_NAME = ""                                -- 非符：不亮卡名
    local CARD_TIME, CARD_HP = 50, 900
    local CARD_ID = 494

    local BOX = { -160, 128, 160, 345 }                 -- ins_75（TH095 坐标）
    local BURST_GAP = 20                                -- 每 20 帧一波
    local CYCLE = 40                                    -- t=40 的 ins_4(0,-72) 跳回 @680
    ---型 6 的碰撞直径是 4（g_PhotoBulletCollisionSizes[6]）⇒ ball_small。
    local BULLET_STYLE = ball_small
    local BULLET_COLOR = ex_color(14)                   -- 原作色 14（黄）
    local RING_C1, RING_C2 = 6, 16
    local RING_SP1, RING_SP2 = 4, 1                     -- 4 → 1.1875
    local ACCEL_FRAMES, ACCEL_STEP = 120, -1 / 24       -- ins_101 的 i0 / f0

    local st = { dead = false }
    local sub4 = nil

    ---Sub4（t=15 的 ins_67(20,4,8)）：新的顶掉旧的。
    local function run_sub4(owner)
        if sub4 then sub4.alive = false end
        local tok = { alive = true }
        sub4 = tok
        task.New(owner, function()
            task.Wait(15)
            if not tok.alive or st.dead then return end
            sg_bmove(owner, st, 20, 4, 8, BOX)
        end)
    end

    ---Sub5 / Sub6：一波 = OCIRC_AIMED（带 VEC，减速）+ CIRC_AIMED（不带 VEC，匀速）。
    local function burst(owner)
        sg_shot(90, BULLET_STYLE, BULLET_COLOR, owner.x, owner.y,
                RING_C1, RING_C2, RING_SP1, RING_SP2, 0, 0, true, 0x212,
                sg_tr_hook({ sg_rec(SG_VEC, 0, ACCEL_FRAMES, -1, ACCEL_STEP, -999.99) }, 0x212))
        sg_shot(88, BULLET_STYLE, BULLET_COLOR, owner.x, owner.y,
                RING_C1, RING_C2, RING_SP1, RING_SP2, 0, 0, true, 0x202, nil)
    end

    local card = boss.card.New(CARD_NAME, 1, 3, CARD_TIME, CARD_HP)

    function card:before()
        sub4 = nil
    end

    function card:init()
        photo_damage_on(self, PHOTO_LIMIT)
        self.x, self.y = BOSS_X, BOSS_START_Y
        st.dead = false
        task.New(self, function()
            task.Wait(ENTRY_WAIT)
            task.MoveTo(HOME_X, HOME_Y, ENTRY_TIME, EASE_OUT)
            ---到这里是 Sub2 的 t=130 = Sub3 的 t=0。
            while not st.dead do
                run_sub4(self)                       -- ins_52(4)
                burst(self)                          -- ins_117(0,5)
                task.Wait(BURST_GAP)                 -- t=20
                if st.dead then return end
                run_sub4(self)                       -- ins_52(4)
                burst(self)                          -- ins_117(0,6)
                task.Wait(CYCLE - BURST_GAP)         -- t=40 → 跳回 t=0
            end
        end)
    end

    function card:frame()
    end

    function card:del()
        st.dead = true
        photo_damage_off(self)
    end

    boss.card.add({ { card, "13a" } }, LEVEL, CARD_NAME, CARD_ID)
end--橙 非符

---──────────────────── Stage 6 八云蓝 人智剣「天女返し」（ecl13_a，组 14a 第 1 张） ────────────────────
do  -- 51 八云蓝 人智剣「天女返し」（ecl13_a，组 14a 第 1 张）
    ---原作是「天女回头甩出的两条交叠光带」：本体在 ±128 之间来回瞬移，每次瞬移前先甩
    ---一根满长激光、瞬移到位再甩第二根；同时 slot0 的整圈弹从**本体挪走后的位置 + 一个
    ---固定偏移**处一圈一圈地放。半个月亮一轮，共两根 × 两轮 = 四根激光。
    ---数据源 /tmp/W6d_ecl13_a.txt（ECL …/data/ecl13_a.ecl）。骨架：
    ---  · Sub2 @380：ins_141(4) ⇒ 拍 4 张；ins_63(-128,-64) → t=100 ins_64(30,4,128,160)
    ---    落到 TH095 (128,160)（我们的 (128,64)）→ t=130 ins_104 + ins_149(3.5) + ins_52(3)。
    ---  · Sub3 @692：t=30 起 Sub4（slot0 装饰，不实现）+ ins_118(12)（背景 VM，不实现）
    ---    + ins_119(11)（相机/激光回调 11，不实现）；t=50 ins_144、t=65 ins_54（都不实现）。
    ---    t=70 是**半 A**：先算 floatV2 = world.x−256、floatV3 = world.y，在**原位**
    ---    甩第一根（ins_118(10)：extraFloatV2 = 2π/3 = 120°、extraFloatV3 = 192），
    ---    ins_63(floatV2,floatV3) 把本体挪到 (world.x−256, world.y) 后再甩第二根
    ---    （30°、长 332.5536）；最后 ins_117(0,5) 起整圈。t=130~170 是**半 B**（镜像：
    ---    60° / 150°、本体挪到 world.x+256）。
    ---    t=230 的 ins_4(30,-1000) 跳回 @704（t=30）⇒ 一轮 200 帧。
    ---  · ins_118(10) 回调 = Callback10（th095/src/EclExtended.cpp:786）：position =
    ---    worldPosition + shootOffset、angle = extraFloatV2、maxLength = extraFloatV3、
    ---    初始满长、speed 8、宽 16、startup 1、grow 15、**sustain 40**、fade 6、
    ---    角速 0、follow 0、贴图行 = extraIntV2(=13)。本卡的 shootOffset 恒为 0。
    ---  · Sub5 @1836（slot0，t=70 / t=170 各起一次）：ins_26 把 ins_100 的 shootOffset
    ---    算成本体挪走后仍指向 TH095 (world.x∓64, world.y+110.8512) 的那一点；然后
    ---    ins_101(0,0x10,0,60,-1,1/30,−999.99) 挂 VEC、intV0 = photoIndex×16+8、
    ---    ins_89 CIRCLE（型 7、色 6、c1=intV0、速 2、基角 rand(−π,π)、flags 0x212）
    ---    用 ins_5(0,-44,8) 连发 **8 轮、每轮 5 帧**；t=5 的 ins_100(0,0) + ins_53 收尾。
    ---  · Sub4 @1736 只是 ins_100(0,-32) → ins_150(14) → ins_100(0,0) 的装饰循环，
    ---    照旧不实现（顺带：它保证 shootOffset 恒为 0）。
    local BOSS_X, BOSS_START_Y = -128, field_y(-64)     -- 288（场地外）
    local HOME_X, HOME_Y = 128, field_y(160)            -- 128 / 64
    local ENTRY_WAIT, ENTRY_TIME = 100, 30
    local EASE_OUT = VALUE_SET.DECEL
    local PHOTO_LIMIT = 4                               -- ins_141(4)
    local CARD_NAME = "人智剣「天女返し」"
    local CARD_TIME, CARD_HP = 50, 900
    local CARD_ID = 495

    local HALF = 100                                    -- 半轮 100 帧（t=70 → t=170）
    local CYCLE = 200                                   -- t=230 的 ins_4(30,-1000)
    local LASER_ROW = 13                                -- extraIntV2（贴图行）
    local LASER_W, LASER_SPEED = 16, 8
    local LASER_STARTUP, LASER_GROW, LASER_SUSTAIN, LASER_FADE = 1, 15, 40, 6
    local RING_ROUNDS, RING_GAP = 8, 5                  -- ins_5(0,-44,8)
    local RING_STYLE = ball_small                       -- 型 7：直径 4
    local RING_COLOR = ex_color(6)                      -- 原作色 6（蓝）
    local RING_SPEED, RING_STEP = 2, 0.1848
    local RING_ACCEL_FRAMES, RING_ACCEL_STEP = 60, 0.0333333351
    ---整圈的生成点（我们的坐标）：TH095 (64,270.8512) —— 本体在 (-128,160) 再加
    ---shootOffset (192,110.8512)（半 B 是镜像的 (-64,270.8512)）。
    local RING_OFF_X, RING_OFF_Y = 64, field_y(270.851196)

    local st = { dead = false }
    local lasers = {}
    local ring_tok = nil

    ---一根 ins_118(10)（Callback10）激光：满长、sustain 40、贴图行 13。
    local function spawn_laser(owner, x, y, th_rad)
        spawn_ex_laser(owner, lasers, LASER_ROW, x, y, sg_deg(th_rad),
                192, LASER_W, LASER_SPEED, LASER_STARTUP, LASER_GROW, LASER_SUSTAIN,
                LASER_FADE, 0, 0, 0, false, true)
    end

    ---上半场一根 120°/192、下半场一根 30°/332.5536，第二根在挪位之后放。
    ---x1 = 整圈生成点的 x 偏移（半 A 是 −64、半 B 是 +64，见下面 RING_OFF_X 的注释）。
    local function half(owner, target_x, x1, th1, th2)
        local wx = owner.x                              -- 这一半开头的 world.x
        spawn_laser(owner, wx, owner.y, th1)
        owner.x = target_x
        spawn_ex_laser(owner, lasers, LASER_ROW, owner.x, owner.y, sg_deg(th2),
                332.553589, LASER_W, LASER_SPEED, LASER_STARTUP, LASER_GROW, LASER_SUSTAIN,
                LASER_FADE, 0, 0, 0, false, true)
        if ring_tok then ring_tok.alive = false end
        local tok = { alive = true }
        ring_tok = tok
        local sx, sy = wx + x1, RING_OFF_Y
        task.New(owner, function()
            local hook = sg_tr_hook(
                    { sg_rec(SG_VEC, 0, RING_ACCEL_FRAMES, -1, RING_ACCEL_STEP, -999.99) }, 0x212)
            local n = photo_index(PHOTO_LIMIT) * 16 + 8
            ---★ Sub5 第 1 句就是 ins_89（在 +5 之前、time=0），而 ins_117 建的子上下文
            ---在**同一帧**就会被 RunEcl 的 low_select_next_context 接着跑（EclRun.cpp:425）
            ---⇒ 第一圈与两根激光同帧。之后 ins_5(0,Sub5_172,8) 每次回跳都把 time 归 0，
            ---一轮 5 帧 ⇒ 共 8 圈、落在 t=0/5/…/35。
            for _ = 1, RING_ROUNDS do
                if not tok.alive or st.dead then return end
                local a = math.deg(ran:Float(-math.pi, math.pi))   -- TH095 空间的基准角
                sg_shot(89, RING_STYLE, RING_COLOR, sx, sy, n, 1, RING_SPEED, 0.3,
                        a, RING_STEP, false, 0x212, hook)
                task.Wait(RING_GAP)
            end
        end)
    end

    local card = boss.card.New(CARD_NAME, 1, 3, CARD_TIME, CARD_HP)

    function card:before()
        lasers = {}
        ring_tok = nil
    end

    function card:init()
        photo_damage_on(self, PHOTO_LIMIT)
        self.x, self.y = BOSS_X, BOSS_START_Y
        st.dead = false
        task.New(self, function()
            task.Wait(ENTRY_WAIT)
            task.MoveTo(HOME_X, HOME_Y, ENTRY_TIME, EASE_OUT)
            ---t=30 的第一段（ins_117(0,4) / ins_118(12) / ins_119(11)）都不实现，
            ---直接等到 t=70 的半 A。
            task.Wait(70)
            while not st.dead do
                -- 半 A：world.x = 128 → 本体挪到 -128
                half(self, self.x - 256, -64, 2.09439516, 0.52359879)
                task.Wait(HALF)                          -- t=170
                if st.dead then return end
                -- 半 B：world.x = -128 → 本体挪到 128
                half(self, self.x + 256, 64, 1.04719758, 2.61799383)
                task.Wait(CYCLE - HALF)                  -- t=270 = 下一轮的 t=70
            end
        end)
    end

    function card:frame()
    end

    function card:del()
        st.dead = true
        photo_damage_off(self)
        sg_clear(lasers)
    end

    boss.card.add({ { card, "14a" } }, LEVEL, CARD_NAME, CARD_ID)
end--人智剣「天女返し」

---──────────────────── Stage 6 橙 星符「飛び重ね鱗」（ecl12_b，组 13a 第 2 张） ────────────────────
do  -- 52 橙 星符「飛び重ね鱗」（ecl12_b，组 13a 第 2 张）
    ---名字是「鳞片叠着鳞片」：本体在场地上半部沿折线一路**瞬移 + 插值**，每停一处就撒下
    ---一组三发自机狙 —— 那三发出生速度是 0，先在原地**定住 120 帧**，再用 120 帧沿各自
    ---出生方向加速到 2 px/帧，于是整条折线上就叠出一层层的鳞。
    ---数据源 /tmp/W6d_ecl12_b.txt（ECL …/data/ecl12_b.ecl）。骨架：
    ---  · Sub2 @380：ins_141(5) ⇒ 拍 5 张；ins_63(128,-64) 进场 → t=100
    ---    ins_64(30,4,-224,160) 落到 TH095 (-224,160)（我们的 (-224,64)）→
    ---    t=130 亮卡名 + ins_149(2) + ins_52(3) 起主脚本（**没有** ins_75）。
    ---  · Sub3 @728：t=0 起 Sub4、瞬移到 (-224,64) 再插值到 (224,192)；t=60 到
    ---    (224,96) → (-224,224)；t=120 到 (-224,128) → (224,256)；t=160 到 (224,160)
    ---    → (-224,288)；t=200 到 (-224,192) → (224,320)；t=240 到 (224,224) →
    ---    (-224,356)；t=280 到 (-224,64) → (0,192)；t=310 把 slot0 换成 Sub5；
    ---    t=330 插值到 (-224,320)、slot0 换回 Sub4；t=350 的 ins_4(0,-468) 跳回
    ---    @768（t=0 的 ins_63）⇒ 一轮 350 帧。（以上都是 TH095 坐标。）
    ---  · Sub4 @1268（slot0）：进上下文先写两条 ins_101 —— slot0 = 0x8000 WAIT 120 帧、
    ---    slot1 = 0x10 VEC（120 帧、每帧 +1/60），然后**每帧**一组
    ---    ins_86 FAN_AIMED(型 7、色 13、c1=3、速 0、步长 45°、flags 0x8212)。
    ---    ⇒ 每帧 3 发（±45° 与正前）、出生定住 120 帧再沿各自方向加速到 +2.0。
    ---    （ins_16/ins_37 维护的 floatV1 = −π 每帧 −0.75° 是**死值**：FAN 的 ang 是字面 0。）
    ---  · Sub5 @1532（slot0，t=310 起）：每 4 帧一整圈 ins_88 CIRC_AIMED
    ---    (型 13、色 1、c1=32、速 4、flags 0x202) —— 20 帧里放 5 圈、每圈 32 发。
    ---  · 不实现：ins_6 / ins_144 / ins_149 / ins_104（拍照会话与装饰）。
    local BOSS_X, BOSS_START_Y = 128, field_y(-64)      -- 288（场地外）
    local HOME_X, HOME_Y = -224, field_y(160)           -- -224 / 64
    local ENTRY_WAIT, ENTRY_TIME = 100, 30
    local EASE_OUT = VALUE_SET.DECEL
    local EASE_LIN = 0                                  -- ins_64 的缓动 0 = 线性
    local PHOTO_LIMIT = 5                               -- ins_141(5)
    local CARD_NAME = "星符「飛び重ね鱗」"
    local CARD_TIME, CARD_HP = 50, 900
    local CARD_ID = 496

    ---Sub4：定住 120 帧 + 沿出生方向加速 120 帧（每帧 +1/60 ⇒ 末速 2.0）。
    local FAN_FREEZE, FAN_ACCEL_FRAMES = 120, 120
    local FAN_ACCEL = 0.0166666675
    local FAN_STEP = math.deg(0.785398)                 -- 45°
    ---Sub5：整圈的公共参数（c1 = 32、c2 = 1 ⇒ 速 = sp1 = 4）。
    local RING_COUNT, RING_SPEED, RING_PERIOD = 32, 4, 4

    local st = { dead = false }
    local sub4, sub5 = nil, nil

    ---slot0 一次只能装一条子上下文：起新的 = 掐旧的。
    local function slot0_kill()
        if sub4 then sub4.alive = false; sub4 = nil end
        if sub5 then sub5.alive = false; sub5 = nil end
    end

    local function run_sub4(owner)
        slot0_kill()
        local tok = { alive = true }
        sub4 = tok
        local hook = sg_tr_hook({
            sg_rec(SG_WAIT, 0, FAN_FREEZE, -1, -1, -1),
            sg_rec(SG_VEC, 0, FAN_ACCEL_FRAMES, -1, FAN_ACCEL, -999.99),
        }, 0x8212)
        task.New(owner, function()
            while tok.alive and not st.dead do
                sg_shot(86, ball_small, ex_color(13), owner.x, owner.y,
                        3, 1, 0, 1.5, 0, FAN_STEP, true, 0x8212, hook)
                task.Wait(1)
            end
        end)
    end

    local function run_sub5(owner)
        slot0_kill()
        local tok = { alive = true }
        sub5 = tok
        task.New(owner, function()
            while tok.alive and not st.dead do
                sg_shot(88, ball_mid, ex_color(1), owner.x, owner.y,
                        RING_COUNT, 1, RING_SPEED, 0.5, 0, math.deg(0.241661),
                        true, 0x202, nil)
                task.Wait(RING_PERIOD)
            end
        end)
    end

    local card = boss.card.New(CARD_NAME, 1, 3, CARD_TIME, CARD_HP)

    function card:before()
        sub4, sub5 = nil, nil
    end

    function card:init()
        photo_damage_on(self, PHOTO_LIMIT)
        self.x, self.y = BOSS_X, BOSS_START_Y
        st.dead = false
        task.New(self, function()
            task.Wait(ENTRY_WAIT)
            task.MoveTo(HOME_X, HOME_Y, ENTRY_TIME, EASE_OUT)
            while not st.dead do
                self.x, self.y = -224, field_y(64)          -- ins_63
                run_sub4(self)                              -- ins_117(0,4)
                sg_move(self, st, 224, field_y(192), 40, EASE_LIN)
                task.Wait(60)                               -- t=60
                if st.dead then return end
                self.x, self.y = 224, field_y(96)
                sg_move(self, st, -224, field_y(224), 40, EASE_LIN)
                task.Wait(60)                               -- t=120
                if st.dead then return end
                self.x, self.y = -224, field_y(128)
                sg_move(self, st, 224, field_y(256), 30, EASE_OUT)
                task.Wait(40)                               -- t=160
                if st.dead then return end
                self.x, self.y = 224, field_y(160)
                sg_move(self, st, -224, field_y(288), 25, EASE_OUT)
                task.Wait(40)                               -- t=200
                if st.dead then return end
                self.x, self.y = -224, field_y(192)
                sg_move(self, st, 224, field_y(320), 25, EASE_OUT)
                task.Wait(40)                               -- t=240
                if st.dead then return end
                self.x, self.y = 224, field_y(224)
                sg_move(self, st, -224, field_y(356), 25, EASE_OUT)
                task.Wait(40)                               -- t=280
                if st.dead then return end
                self.x, self.y = -224, field_y(64)
                sg_move(self, st, 0, field_y(192), 25, EASE_OUT)
                task.Wait(30)                               -- t=310
                if st.dead then return end
                run_sub5(self)                              -- ins_117(0,5)
                task.Wait(20)                               -- t=330
                if st.dead then return end
                sg_move(self, st, -224, field_y(320), 20, EASE_LIN)
                run_sub4(self)                              -- ins_117(0,4)
                task.Wait(20)                               -- t=350 → 下一轮 t=0
            end
        end)
    end

    function card:frame()
    end

    function card:del()
        st.dead = true
        slot0_kill()
        photo_damage_off(self)
    end

    boss.card.add({ { card, "13a" } }, LEVEL, CARD_NAME, CARD_ID)
end--星符「飛び重ね鱗」

---──────────────────── Stage 6 八云蓝 妄執剣「修羅の血」（ecl13_b，组 14a 第 2 张） ────────────────────
do  -- 53 八云蓝 妄執剣「修羅の血」（ecl13_b，组 14a 第 2 张）
    ---原作是「阿修罗的血柱」：本体先沉到场地**下方**、两根 576 长的巨柱一上一下地
    ---贯穿场地，同时从两条竖直的「血线」（本体所在那一列上下的随机点）往全屏撒
    ---加速弹。拍中本体到第 3 张后（ins_141(3)）这一张就结束。
    ---数据源 /tmp/W6d_ecl13_b.txt（ECL …/data/ecl13_b.ecl）。骨架：
    ---  · Sub2 @384：ins_141(3) ⇒ 拍 3 张；ins_63(-128,-64) 进场 → t=100
    ---    ins_64(30,4,0,64) 落到 TH095 (0,64)（我们的 (0,160)）→ t=130 亮卡名
    ---    + ins_149(14) + ins_52(3)（**没有** ins_75）。
    ---  · Sub3 @696：t=30 是装饰（ins_106/54/118(12)/119(11)，见文件头差异 11）；
    ---    t=70 把本体（在 (0,64)）**先**甩出第一根巨柱 —— extraFloatV2 = π/2（TH095
    ---    ⇒ 我们的 −90°：朝下）、extraFloatV3 = 576、贴图行 13、ins_118(14)（sustain 300）
    ---    ——再 ins_64(10,0,world.x,512) 沉到场地下方 64 px；t=80 记下 floatV0 = world.x
    ---    后把 world.x 瞬间挪到**自机那一列**、起 Sub5；
    ---    t=81 的 ins_5(80,-20,120) 回跳的是 @756 的 `ins_7(enemy.x, player.x)`（**不是**
    ---    空转：本体在场地下方每帧横移到自机那一列、共 120 次），醒来后 ins_63(player.x,
    ---    world.y) 再对一次列。
    ---    t=121 甩第二根巨柱（extraFloatV2 = −π/2 ⇒ 我们的 +90°：朝上），
    ---    ins_64(10,0,world.x,-64) 升到场地上方；t=131 记 floatV0 = world.x、起 Sub6；
    ---    t=132 的 ins_5(131,-20,32) 同样是 32 帧横移（回跳 @1248 的 ins_7）。
    ---    ins_4(30,-868) 跳回 @708（t=30）⇒ 一轮 252 帧（70→80→200→121→131→163）。
    ---  · ★ ins_5(dt, disp, n) 的**第二操作数（回跳位移）是有效的**：case 5 不满足时
    ---    直接落进 case 4，`context->time = dt; instruction += disp`。上面两条「空转」
    ---    就是靠它回跳到 dt 对得上的那一句、把同一段再跑 n 次（每次 1 帧）实现的。
    ---  · Sub5 @1708（slot1，t=80 起）/ Sub6 @2020（slot2，t=131 起）：extraIntV0 = 300；
    ---    floatV7 = world.y；extraFloatV0 = floatV0 − world.x；extraFloatV1 =
    ---    randF32×(−448 / +448) + (floatV7 − world.y)；ins_100 设出膛偏移 ⇒ 出膛点 =
    ---    (floatV0, floatV7 ∓ 448×rand)——即「本体那一列的竖直线上、上下 448 px 内的随机点」，
    ---    而且出膛点跟着本体当前坐标走（偏移是死的）；
    ---    然后 floatV2 = randF32×0.9 + 0.5、ins_89 CIRCLE(型 3、色 6/8、c1=1、c2=1、
    ---    速 = floatV2、基准角 = rand(−π,π)、步长 0.1848、flags 0x202)，t=2 的
    ---    ins_5(0,-224,300) 回跳 @1748 再放 —— **每 2 帧 1 发、共 300 发**。
    ---  · 不实现：ins_54/106/118(12)/(13)/(15)、ins_119(±11)、ins_144/149/150。
    local BOSS_X, BOSS_START_Y = -128, field_y(-64)      -- 288（场地外）
    local HOME_X, HOME_Y = 0, field_y(64)                -- 0 / 160
    local ENTRY_WAIT, ENTRY_TIME = 100, 30
    local EASE_OUT = VALUE_SET.DECEL
    local EASE_LIN = 0
    local PHOTO_LIMIT = 3                               -- ins_141(3)
    local CARD_NAME = "妄執剣「修羅の血」"
    local CARD_TIME, CARD_HP = 50, 900
    local CARD_ID = 497

    local LASER_ROW = 13                                -- extraIntV2（贴图行）
    local LASER_LEN, LASER_W, LASER_SPEED = 576, 16, 8
    local LASER_STARTUP, LASER_GROW, LASER_FADE = 1, 15, 6
    local LASER_SUSTAIN_LONG, LASER_SUSTAIN_40 = 300, 40
    local SPIN_FRAMES = 120                             -- ins_5(80,-20,120)
    local SUB6_FRAMES = 32                              -- ins_5(131,-20,32)
    local BURSTS, BURST_PERIOD = 300, 2                  -- ins_5(0,-224,300)
    local DROP_STYLE = ball_small                        -- 型 3：直径 6
    local DROP_SPEED_MIN, DROP_SPEED_STEP = 0.5, 0.9

    local lasers = {}
    local st = { dead = false }
    local sub5, sub6 = nil, nil

    ---一根 ins_118 回调激光：满长、宽 16、速 8、角速 0、follow 0。
    local function fire_laser(owner, our_angle, sustain)
        spawn_ex_laser(owner, lasers, LASER_ROW, owner.x, owner.y, our_angle,
                LASER_LEN, LASER_W, LASER_SPEED, LASER_STARTUP, LASER_GROW, sustain,
                LASER_FADE, 0, 0, 0, false, true)
    end

    ---Sub5 / Sub6：每 2 帧 1 发、300 发；出膛点 = (colx, basey ∓ 448×rand)。
    ---colx = Sub3 起它之前记下的 world.x（= floatV0），basey = 进入时的本体 y
    ---（= floatV7）。★ 出膛点 = (colx, basey ∓ 448×rand)：ECL 里 ins_100 的偏移是
    ---**每一发重算**的（`floatV7 − world.y` 抵消本体的移动），所以竖直随机点的基准
    ---fixed 在 Sub5/Sub6 进入那一刻，不跟着本体跑。
    local function run_drop(owner, slot, colx, basey, dir, color)
        if slot == 1 then
            if sub5 then sub5.alive = false end
        else
            if sub6 then sub6.alive = false end
        end
        local tok = { alive = true }
        if slot == 1 then sub5 = tok else sub6 = tok end
        task.New(owner, function()
            for _ = 1, BURSTS do
                if not tok.alive or st.dead then return end
                ---★ ins_5 回跳的是 @1748 起的整段（含 randF32×∓448 与 randF32×0.9），
                ---所以每一发的竖直偏移与速度都是现抽的。
                local y = basey + dir * 448 * ran:Float(0, 1)
                sg_shot(89, DROP_STYLE, ex_color(color), colx, y,
                        1, 1, DROP_SPEED_MIN + DROP_SPEED_STEP * ran:Float(0, 1), 0.3,
                        sg_deg(ran:Float(-math.pi, math.pi)), math.deg(0.1848),
                        false, 0x202, nil)
                task.Wait(BURST_PERIOD)
            end
        end)
    end

    local card = boss.card.New(CARD_NAME, 1, 3, CARD_TIME, CARD_HP)

    ---Sub3_392 / Sub3_836 的 ins_5 循环体：每帧 `ins_7(enemy.x, player.x)`
    ---（EclRunTargetHigh 之外的低位 opcode 7 = float 赋值）。120 / 32 次，一次一帧。
    local function follow_player_x(owner, spin, frames)
        task.New(owner, function()
            for _ = 1, frames do
                if not spin.alive or st.dead then return end
                owner.x = player.x
                task.Wait(1)
            end
        end)
    end

    function card:before()
        lasers = {}
        sub5, sub6 = nil, nil
    end

    function card:init()
        photo_damage_on(self, PHOTO_LIMIT)
        self.x, self.y = BOSS_X, BOSS_START_Y
        st.dead = false
        task.New(self, function()
            task.Wait(ENTRY_WAIT)
            task.MoveTo(HOME_X, HOME_Y, ENTRY_TIME, EASE_OUT)
            ---入场到 t=130 是 Sub2 的 ins_52(3)；Sub3 的 t=0 从这里起算，
            ---t=30/50/65 只有装饰 ⇒ 第一件事是 t=70 的第一根柱。一轮 252 帧。
            task.Wait(70)
            while not st.dead do
                fire_laser(self, sg_deg(1.57079637), LASER_SUSTAIN_LONG)   -- 朝下
                sg_move(self, st, self.x, field_y(512), 10, EASE_LIN)
                task.Wait(10)                               -- t=80
                if st.dead then return end
                local col5, basey5 = self.x, self.y
                run_drop(self, 1, col5, basey5, 1, 6)       -- Sub5
                local spin5 = { alive = true }              -- ins_5(80,-20,120)：120 帧横移
                follow_player_x(self, spin5, SPIN_FRAMES)
                task.Wait(SPIN_FRAMES)
                spin5.alive = false
                if st.dead then return end
                self.x = player.x                           -- ins_63(player.x, world.y)
                task.Wait(40)                               -- t=121
                if st.dead then return end
                fire_laser(self, sg_deg(-1.57079637), LASER_SUSTAIN_LONG)  -- 朝上
                sg_move(self, st, self.x, field_y(-64), 10, EASE_LIN)
                task.Wait(10)                               -- t=131
                if st.dead then return end
                local col6, basey6 = self.x, self.y
                run_drop(self, 2, col6, basey6, -1, 8)      -- Sub6
                local spin6 = { alive = true }              -- ins_5(131,-20,32)：32 帧横移
                follow_player_x(self, spin6, SUB6_FRAMES)
                task.Wait(SUB6_FRAMES)
                spin6.alive = false
                if st.dead then return end
                task.Wait(40)                               -- t=132 空转完 → t=30 的 40 帧后
            end
        end)
    end

    function card:frame()
    end

    function card:del()
        st.dead = true
        if sub5 then sub5.alive = false end
        if sub6 then sub6.alive = false end
        photo_damage_off(self)
        sg_clear(lasers)
    end

    boss.card.add({ { card, "14a" } }, LEVEL, CARD_NAME, CARD_ID)
end--妄執剣「修羅の血」

---──────────────────── Stage 6 橙 鬼神「鳴動持国天」（ecl12_c，组 13a 第 3 张） ────────────────────
do  -- 54 橙 鬼神「鳴動持国天」（ecl12_c，组 13a 第 3 张）
    ---原作是「持国天手中的两条弹幕帘」：前半段本体不动，只从**上边和下边**各撒一条
    ---竖直的单发线（每帧一发、交替上下、出膛点随机横坐标、出生后沿自身方向加速）；
    ---拍中本体第 3 张（ins_115 的 frame=3）时主脚本被换成 Sub10：ins_102 清屏后，
    ---四条**边帘**每 60 帧换一条 —— 下边朝上 → 上边朝下 → 右边朝左 → 左边朝右 ——
    ---每帘 60 发（每 2 帧一发），发完冻结 max(0, 180 − 20×photoIndex) 帧再来一轮。
    ---数据源 /tmp/W6d_ecl12_c.txt（ECL …/data/ecl12_c.ecl）。骨架：
    ---  · Sub2 @400：ins_115(0,3,10)（拍中第 3 张 ⇒ 主脚本换成 Sub10）；ins_104；
    ---    ins_75(-160,96,160,256)；ins_114(5408)；ins_149(7)；ins_52(3)。
    ---  · Sub3 @764：t=0 写 5 个 int/extraInt（60/8/60/30/60）+ ins_118(9)；t=60
    ---    ins_62（停 ANM，不实现）+ ins_117(0,4)；t=100 的 ins_4(60,-20) 跳回 @892
    ---    （t=60 的 ins_117(0,4)）⇒ 每 40 帧重起一次 Sub4。
    ---  · Sub4 @944（1 条 3 帧的小循环）：t=0 写 VEC(120 帧、每帧 +1/120)、
    ---    floatV0 = randF32s×192、floatV1 = 0，ins_100 后 ins_87 FAN(型 0、色 8、
    ---    c1=1、速 0、ang = +π/2 ⇒ 我们的 −90°：向下)；t=1 同法但 floatV1 = 448、
    ---    ang = −π/2（⇒ 我们的 +90°：向上）；t=2 的 ins_4(0,-312) 跳回 @1024 ⇒
    ---    **每帧 1 发**，上/下交替，出膛点 = (rand×192, 0 或 448)（TH095，场地上/下沿）。
    ---  · Sub6..9 @2128/@2520/@2956/@3348：同一条 VEC 但每帧 +1/240（末速 +0.5）；
    ---    extraIntV0 = 60；出膛点固定在一条边、速度 sp1 = randF32×0.5；
    ---    ins_5(0,-N,60) 回跳 ⇒ 每 2 帧 1 发、共 60 发；发完 extraIntV1 = photoIndex×20、
    ---    ins_2(180 − extraIntV1) 冻结、ins_4(0,-308) 回 t=0。四条边与角：
    ---      Sub6 左(x=−192)/ang 0（我们 0°：向 +x）  Sub7 右(x=192)/ang π（我们的 −180°）
    ---      Sub8 上(y=0)  /ang π/2（我们 −90°：向下） Sub9 下(y=448)/ang −π/2（我们 +90°）
    ---  · Sub10 @3740：ins_102 清屏后 t=0 起 Sub9、t=60 起 Sub8、t=120 起 Sub7、
    ---    t=180 起 Sub6、t=220 的 ins_4(180,0) 原地自锁（每 40 帧空转一次，不再换帘）。
    ---  · Sub5 是死代码（没有任何 ins_117 指向它）。
    local BOSS_X, BOSS_START_Y = -128, field_y(-64)      -- 288（场地外）
    local HOME_X, HOME_Y = 0, 0                          -- TH095 (0,224)
    local ENTRY_WAIT, ENTRY_TIME = 100, 30
    local EASE_OUT = VALUE_SET.DECEL
    local PHOTO_LIMIT = 7                               -- ins_141(7)
    local SUB10_AT = 3                                  -- ins_115(0,3,10)
    local CARD_NAME = "鬼神「鳴動持国天」"
    local CARD_TIME, CARD_HP = 50, 900
    local CARD_ID = 498

    local BOX = { -160, 96, 160, 256 }                  -- ins_75（本卡用不到）
    local CURTAIN_BURSTS, CURTAIN_PERIOD = 60, 2
    local CURTAIN_ACCEL_FRAMES, CURTAIN_ACCEL = 120, 0.00416666688
    local BULLET_STYLE = ball_small                     -- 型 0：直径 6
    local BULLET_COLOR = ex_color(8)                    -- 原作色 8
    local CURTAIN_FREEZE_BASE, CURTAIN_FREEZE_STEP = 180, 20

    local st = { dead = false }
    local lasers = {}
    local sub4 = nil
    local curtains = {}                                 -- 4 条边帘各占一个 slot（原作用 3/2/0/1）
    local sub3tok = nil

    ---等价 task.Wait(n)，但可以被 ins_115 的重开打断（原作那一刻主上下文被整个换掉）。
    local function step(tok, n)
        for _ = 1, n do
            if not tok.alive or st.dead then return false end
            task.Wait(1)
        end
        return true
    end

    ---Sub4：上/下沿交替的单发帘（每帧 1 发、末速 +1.0）。
    ---★ 方向别弄反：t=0 走 floatV1 = 0（TH095 上沿 ⇒ 我们的 y=+224）、ang = +π/2
    ---（TH095 朝下 ⇒ 我们 −90°）；t=1 走 floatV1 = 448（下沿 ⇒ y=−224）、ang = −π/2
    ---（我们 +90°）。出膛点 = (randF32s×192, 0/448)（randF32s 有符号）。
    local function run_sub4(owner)
        if sub4 then sub4.alive = false end
        local tok = { alive = true }
        sub4 = tok
        local hook = sg_tr_hook({
            sg_rec(SG_VEC, 0, 120, -1, 0.00833333377, -999.99),
        }, 0x212)
        task.New(owner, function()
            local up = false
            while tok.alive and not st.dead do
                local x = 192 * ran:Float(-1, 1)
                ---★ sg_shot 的 base 是 **TH095 空间的度**（sg_shot 末尾经 sg_bullet 再取一次反，
                ---  sg_bullet 的形参就叫 th_deg）⇒ 这里只能用 math.deg；写成 sg_deg 等于多取一次
                ---  反，上下两条帘都朝场外飞，出生后立刻出 bound（±256）被回收。
                if up then
                    sg_shot(87, BULLET_STYLE, BULLET_COLOR, x, -224,
                            1, 1, 0, 1.5, math.deg(-1.57079637), math.deg(0.0317333),
                            false, 0x212, hook)
                else
                    sg_shot(87, BULLET_STYLE, BULLET_COLOR, x, 224,
                            1, 1, 0, 1.5, math.deg(1.57079637), math.deg(0.0317333),
                            false, 0x212, hook)
                end
                up = not up
                task.Wait(1)
            end
        end)
    end

    ---Sub6..9：一条边帘。spec = { "x"|"y", 固定坐标，TH095 角 }。
    ---★ 四条帘**同时**跑，各占一个 slot（Sub10 每 60 帧在下一个 slot 上起一条，
    ---此后不再重开）—— 不是轮流换。每条自己循环：60 发×2 帧 + 冻结。
    local function run_curtain(owner, slot, spec)
        if curtains[slot] then curtains[slot].alive = false end
        local tok = { alive = true }
        curtains[slot] = tok
        local hook = sg_tr_hook({
            sg_rec(SG_VEC, 0, CURTAIN_ACCEL_FRAMES, -1, CURTAIN_ACCEL, -999.99),
        }, 0x212)
        task.New(owner, function()
            while tok.alive and not st.dead do
                for _ = 1, CURTAIN_BURSTS do
                    if not tok.alive or st.dead then return end
                    local x, y
                    if spec[1] == "x" then
                        x, y = spec[2], 224 - 448 * ran:Float(0, 1)
                    else
                        x, y = 192 * ran:Float(-1, 1), spec[2]
                    end
                    sg_shot(87, BULLET_STYLE, BULLET_COLOR, x, y,
                            1, 1, 0.5 * ran:Float(0, 1), 1.5,
                            math.deg(spec[3]), math.deg(0.0317333), false, 0x212, hook)
                    task.Wait(CURTAIN_PERIOD)
                end
                local freeze = CURTAIN_FREEZE_BASE
                        - CURTAIN_FREEZE_STEP * photo_index(PHOTO_LIMIT)
                if freeze > 0 then
                    task.Wait(freeze)
                end
            end
        end)
    end

    ---Sub10：清屏 → 四条边帘每 60 帧在下一个 slot 上起一条。
    ---slot 编号照原作：Sub9→3、Sub8→2、Sub7→0、Sub6→1。
    local function run_sub10(owner)
        sg_clear(lasers)
        run_curtain(owner, 3, { "y", -224, -1.57079637 })   -- Sub9：下沿朝上
        task.Wait(60)
        if st.dead then return end
        run_curtain(owner, 2, { "y", 224, 1.57079637 })     -- Sub8：上沿朝下
        task.Wait(60)
        if st.dead then return end
        run_curtain(owner, 0, { "x", 192, 3.14159274 })     -- Sub7：右沿朝左
        task.Wait(60)
        if st.dead then return end
        run_curtain(owner, 1, { "x", -192, 0 })             -- Sub6：左沿朝右
        while not st.dead do                                -- ins_4(180,0)：原地自锁
            task.Wait(1)
        end
    end

    local card = boss.card.New(CARD_NAME, 1, 3, CARD_TIME, CARD_HP)

    function card:before()
        lasers = {}
        sub4 = nil
        curtains = {}
        sub3tok = nil
    end

    function card:init()
        photo_damage_on(self, PHOTO_LIMIT)
        self.x, self.y = BOSS_X, BOSS_START_Y
        st.dead = false
        task.New(self, function()
            local tok = { alive = true }
            sub3tok = tok
            if not step(tok, ENTRY_WAIT) then return end
            sg_move(self, st, HOME_X, HOME_Y, ENTRY_TIME, EASE_OUT)
            if not step(tok, 30) then return end
            ---Sub3 的 t=0 在这里；t=60 才起第一发 Sub4，之后每 40 帧一发
            ---（t=100 的 ins_4(60,-20) 跳回 t=60 那一句）。
            if not step(tok, 60) then return end
            while true do
                if not tok.alive or st.dead then return end
                run_sub4(self)
                if not step(tok, 40) then return end
            end
        end)
        ---ins_115(0,3,10)：拍中本体第 3 张时主上下文被**立刻**重开成 Sub10，
        ---同时 16 个 slot 的子上下文全部释放（EnemyManagerUpdate.cpp:1293-1310）。
        task.New(self, function()
            while not st.dead and photo_index(PHOTO_LIMIT) < SUB10_AT do
                task.Wait(1)
            end
            if st.dead then return end
            if sub3tok then sub3tok.alive = false; sub3tok = nil end
            if sub4 then sub4.alive = false; sub4 = nil end
            run_sub10(self)
        end)
    end

    function card:frame()
    end

    function card:del()
        st.dead = true
        if sub3tok then sub3tok.alive = false end
        if sub4 then sub4.alive = false end
        for i = 0, 3 do
            if curtains[i] then curtains[i].alive = false end
        end
        photo_damage_off(self)
        sg_clear(lasers)
    end

    boss.card.add({ { card, "13a" } }, LEVEL, CARD_NAME, CARD_ID)
end--鬼神「鳴動持国天」

---──────────────────── Stage 6 八云蓝 天星剣「涅槃寂静の如し」（ecl13_c，组 14a 第 3 张） ────────────────────
do  -- 55 八云蓝 天星剣「涅槃寂静の如し」（ecl13_c，组 14a 第 3 张）
    ---原作是「流星雨」：本体在活动框里慢慢漂，场地**上半部**随机点上不断生出
    ---朝下的小玉 —— 它们出生速度 1 ~ 1+0.3×拍照数、在 120 帧里再加速 +1.3，
    ---所以拍得越多这一层越凶；中段换一条更密的子上下文（每 2 帧一发）并在
    ---**slot1** 挂一束四发自机狙（速度 4 / 3.375 / 2.75 / 2.125），与流星层叠加。
    ---数据源 /tmp/W6d_ecl13_c.txt（ECL …/data/ecl13_c.ecl）。骨架：
    ---  · Sub2 @384：ins_141(5) ⇒ 拍 5 张；ins_63(-128,-64) 进场 → t=100
    ---    ins_64(30,4,0,224) 落到 TH095 (0,224)（我们的 (0,0)）→ t=130 亮卡名
    ---    + ins_75(-160,144,160,256) + ins_149(1.5) + ins_52(3)。
    ---  · Sub3 @724（**一轮 255 帧**，t=255 的 ins_4(0,-432) 跳回 @724）：
    ---    t=0 起 Sub4（slot0）；t=60 把 slot0 换成 Sub5、起 Sub6（slot1）；
    ---    t=160 收掉 slot0；t=170 重起 Sub4、收掉 slot1；t=215 ins_67(60,4,2)。
    ---  · Sub4 @1188（**每帧 1 发**）：ins_101 挂 VEC(120 帧、每帧 +0.0108333)；
    ---    出膛点 = (randF32s×192, randF32×192)（TH095 的 x ±192、y 0..192 ⇒ 场地
    ---    上半部）；floatV2 = rand×0.1963495 + 1.4726216 ⇒ 方向 84.375°..95.625°
    ---    （TH095 弧度，向下）；floatV3 = 1 + rand×(1 + 0.3×photoIndex)；
    ---    ins_87 FAN(型 0、色 6、c1=1、c2=1、速 = floatV3、flags 0x202)，t=1 的
    ---    ins_4(0,-312) 回跳 @1268（t=0）⇒ 每帧 1 发。
    ---  · Sub5 @1624：与 Sub4 同参，只把 flags 换成 0x2（无出声）、回跳放在 t=2
    ---    ⇒ **每 2 帧 1 发**。
    ---  · Sub6 @2060（slot1）：出膛点同上；ins_86 FAN_AIMED(型 7、色 15、c1=1、c2=4、
    ---    速 4 → 3.375 → 2.75 → 2.125、flags 0x2)，t=1 的 ins_4(0,-160) 回跳
    ---    ⇒ **每帧 4 发**。
    ---  · 不实现：ins_106/54/118(12)/(13)/(15)/(16)、ins_119(±11)、ins_144/150/149。
    local BOSS_X, BOSS_START_Y = -128, field_y(-64)      -- 288（场地外）
    local HOME_X, HOME_Y = 0, 0                          -- TH095 (0,224)
    local ENTRY_WAIT, ENTRY_TIME = 100, 30
    local EASE_OUT = VALUE_SET.DECEL
    local PHOTO_LIMIT = 5                               -- ins_141(5)
    local CARD_NAME = "天星剣「涅槃寂静の如し」"
    local CARD_TIME, CARD_HP = 50, 900
    local CARD_ID = 499

    local BOX = { -160, 144, 160, 256 }                 -- ins_75
    local CYCLE = 255
    local STAR_FREEZE_STEP, STAR_FREEZE_BASE = 0.3, 1
    local STAR_ACCEL_FRAMES, STAR_ACCEL = 120, 0.0108333332
    local AVE_AT = 215                                  -- ins_67 在 t=215
    local st = { dead = false }
    local sub4, sub5, sub6 = nil, nil, nil

    ---Sub4 / Sub5：流星雨。period = 1 / 2 帧；sound = 0x202 / 0x2。
    local function run_stars(owner, slot, period, flags)
        local tok = { alive = true }
        if slot == 4 then
            if sub4 then sub4.alive = false end
            sub4 = tok
        else
            if sub5 then sub5.alive = false end
            sub5 = tok
        end
        local hook = sg_tr_hook({
            sg_rec(SG_VEC, 0, STAR_ACCEL_FRAMES, -1, STAR_ACCEL, -999.99),
        }, flags)
        task.New(owner, function()
            while tok.alive and not st.dead do
                local px = 192 * ran:Float(-1, 1)
                local py = 224 - 192 * ran:Float(0, 1)
                local ang = 1.47262156 + 0.196349546 * ran:Float(0, 1)
                local sp = 1 + (STAR_FREEZE_BASE
                        + STAR_FREEZE_STEP * photo_index(PHOTO_LIMIT)) * ran:Float(0, 1)
                ---★ base 同上（TH095 度）：sg_deg 会把这阵「朝下」的流星雨整个翻成朝上。
                sg_shot(87, ball_small, ex_color(6), px, py,
                        1, 1, sp, 1.5, math.deg(ang), math.deg(0.0317333),
                        false, flags, hook)
                task.Wait(period)
            end
        end)
    end

    ---Sub6（slot1）：四发自机狙，每帧 4 发。
    local function run_snipe(owner)
        if sub6 then sub6.alive = false end
        local tok = { alive = true }
        sub6 = tok
        task.New(owner, function()
            while tok.alive and not st.dead do
                local px = 192 * ran:Float(-1, 1)
                local py = 224 - 192 * ran:Float(0, 1)
                sg_shot(86, ball_small, ex_color(15), px, py,
                        1, 4, 4, 1.5, 0, math.deg(0.0317333), true, 0x2, nil)
                task.Wait(1)
            end
        end)
    end

    local card = boss.card.New(CARD_NAME, 1, 3, CARD_TIME, CARD_HP)

    function card:before()
        sub4, sub5, sub6 = nil, nil, nil
    end

    function card:init()
        photo_damage_on(self, PHOTO_LIMIT)
        self.x, self.y = BOSS_X, BOSS_START_Y
        st.dead = false
        task.New(self, function()
            task.Wait(ENTRY_WAIT)
            task.MoveTo(HOME_X, HOME_Y, ENTRY_TIME, EASE_OUT)
            while not st.dead do
                run_stars(self, 4, 1, 0x202)                -- t=0：Sub4
                task.Wait(60)
                if st.dead then return end
                run_stars(self, 5, 2, 0x2)                  -- t=60：Sub5 顶掉 Sub4
                run_snipe(self)                             -- t=60：Sub6
                task.Wait(100)                              -- t=160
                if st.dead then return end
                if sub5 then sub5.alive = false; sub5 = nil end     -- ins_117(0,-1)
                task.Wait(10)                               -- t=170
                if st.dead then return end
                run_stars(self, 4, 1, 0x202)                -- t=170：Sub4 重起
                if sub6 then sub6.alive = false; sub6 = nil end      -- ins_117(1,-1)
                task.Wait(45)                               -- t=215
                if st.dead then return end
                sg_bmove(self, st, 60, 4, 2, BOX)           -- ins_67(60,4,2)
                task.Wait(40)                               -- t=255 → 下一轮 t=0
            end
        end)
    end

    function card:frame()
    end

    function card:del()
        st.dead = true
        if sub4 then sub4.alive = false end
        if sub5 then sub5.alive = false end
        if sub6 then sub6.alive = false end
        photo_damage_off(self)
    end

    boss.card.add({ { card, "14a" } }, LEVEL, CARD_NAME, CARD_ID)
end--天星剣「涅槃寂静の如し」

---──────────────────── Stage 6 橙 化猫「橙」（ecl12_d，组 13a 第 4 张） ────────────────────
do  -- 56 橙 化猫「橙」（ecl12_d，组 13a 第 4 张）
    ---原作是「猫又乱窜」：本体在场地四个角 / 两条边线 / 中轴之间连续瞬移，每次落地
    ---ins_52(4) 同步调一次子脚本 —— 11 发的自机狙扇、**连放 photoIndex+1 次**、每次
    ---隔 6 帧。所以拍得越准，每个落点的扇就越厚。
    ---数据源 /tmp/W6d_ecl12_d.txt（ECL …/data/ecl12_d.ecl）。骨架：
    ---  · Sub2 @376：ins_141(5) ⇒ 拍 5 张；ins_63(-2,-64) 进场 → t=100
    ---    ins_64(60,4,0,448) 落到 TH095 (0,448)（我们的 (0,-224)）→ t=130 亮卡名
    ---    + ins_149(15) + ins_52(3)（**没有** ins_75）。
    ---  · Sub3 @724：t=30 调 Sub4；t=62 到 (192, player.y)、t=92 到 (-192, player.y)；
    ---    t=122 调 Sub4；t=154 到 (player.x, 448)、t=184 调 Sub4；t=216 到
    ---    (player.x, 0)、t=246 调 Sub4；t=278 到 (-192, player.y)、t=308 到
    ---    (192, player.y)；t=338 调 Sub4；t=370 到 (player.x, 0)、t=400 调 Sub4；
    ---    t=432 到 (player.x, 448)、t=462 调 Sub4 + ins_4(30,-448) 跳回 @760（t=62）。
    ---    （以上都是 TH095 坐标；ins_64 的 4 个目标里带 player.x / player.y 的
    ---    pm=0004/0008，都是**取执行那一刻**的自机坐标。）
    ---  · Sub4 @1240：ins_20(extraIntV0, photoIndex, 1) ⇒ 连发次数 = photoIndex + 1；
    ---    floatV1 = playerAngle；ins_87 FAN(型 7、色 6、c1=11、c2=1、速 1、步长 0.1848、
    ---    flags 0x202)，t=6 的 ins_5(0,-44,extraIntV0) 回跳 @1284 ⇒ 每次隔 6 帧。
    ---    ★ 原作是 ins_52（压栈调用）⇒ Sub3 的**时间轴在调用期间停摆**，所以上面那些
    ---    t=62/92… 是「调用返回之后」的帧号；这里把 call_sub4 写成同步阻塞，等价。
    ---  · 不实现：ins_119(8)、ins_114/141/149/150/104。
    local BOSS_X, BOSS_START_Y = -2, field_y(-64)       -- 288（场地外，x = -2）
    local HOME_X, HOME_Y = 0, field_y(448)              -- 0 / -224
    local ENTRY_WAIT, ENTRY_TIME = 100, 60
    local EASE_OUT = VALUE_SET.DECEL
    local PHOTO_LIMIT = 5                               -- ins_141(5)
    local CARD_NAME = "化猫「橙」"
    local CARD_TIME, CARD_HP = 50, 900
    local CARD_ID = 500

    local FAN_COUNT, FAN_SPEED = 11, 1
    local FAN_STEP = math.deg(0.1848)                   -- 0.1848 rad = 10.588°
    local FAN_GAP = 6                                   -- ins_5(6,-44,…)
    local st = { dead = false }

    ---Sub4：11 发自机狙扇，连放 photoIndex+1 次。
    ---★ 两处必须照抄：① f1 = aimAngle 是**进入 Sub4 那一刻**读一次（ins_7 在循环体
    ---之前），整轮 n 发共用同一个基准角，不是每发重瞄；② ins_5(6,-44,ei0) 的收尾也要
    ---等满 6 帧才轮到 ins_53（返回），少等这 6 帧 Sub3 的整条时间轴会提前 6 帧。
    local function call_sub4(owner)
        local n = photo_index(PHOTO_LIMIT) + 1
        local aim = sg_aim(owner.x, owner.y)
        for _ = 1, n do
            if st.dead then return end
            sg_shot(87, ball_small, ex_color(6), owner.x, owner.y,
                    FAN_COUNT, 1, FAN_SPEED, 1.5, aim, FAN_STEP,
                    false, 0x202, nil)
            task.Wait(FAN_GAP)
        end
    end

    local card = boss.card.New(CARD_NAME, 1, 3, CARD_TIME, CARD_HP)

    function card:before()
    end

    function card:init()
        photo_damage_on(self, PHOTO_LIMIT)
        self.x, self.y = BOSS_X, BOSS_START_Y
        st.dead = false
        task.New(self, function()
            task.Wait(ENTRY_WAIT)
            ---入场 ins_64(60,4,0,448) 要 60 帧才走完，但 Sub2 在 t=130 就
            ---ins_52(3) 切进 Sub3 ⇒ 移动必须非阻塞（Sub3 的 t=0 是入场第 30 帧）。
            sg_move(self, st, HOME_X, HOME_Y, ENTRY_TIME, EASE_OUT)
            task.Wait(60)                               -- Sub3 的 t=0（30 帧）→ t=30 第一次 ins_52(4)
            call_sub4(self)
            while not st.dead do
                task.Wait(32)                           -- t=62
                if st.dead then return end
                sg_move(self, st, 192, player.y, 30, EASE_OUT)
                task.Wait(30)                           -- t=92
                if st.dead then return end
                sg_move(self, st, -192, player.y, 30, EASE_OUT)
                task.Wait(30)                           -- t=122
                call_sub4(self)
                task.Wait(32)                           -- t=154
                if st.dead then return end
                sg_move(self, st, player.x, -224, 30, EASE_OUT)
                task.Wait(30)                           -- t=184
                call_sub4(self)
                task.Wait(32)                           -- t=216
                if st.dead then return end
                sg_move(self, st, player.x, 224, 30, EASE_OUT)
                task.Wait(30)                           -- t=246
                call_sub4(self)
                task.Wait(32)                           -- t=278
                if st.dead then return end
                sg_move(self, st, -192, player.y, 30, EASE_OUT)
                task.Wait(30)                           -- t=308
                sg_move(self, st, 192, player.y, 30, EASE_OUT)
                task.Wait(30)                           -- t=338
                call_sub4(self)
                task.Wait(32)                           -- t=370
                if st.dead then return end
                sg_move(self, st, player.x, 224, 30, EASE_OUT)
                task.Wait(30)                           -- t=400
                call_sub4(self)
                task.Wait(32)                           -- t=432
                if st.dead then return end
                sg_move(self, st, player.x, -224, 30, EASE_OUT)
                task.Wait(30)                           -- t=462
                call_sub4(self)
                task.Wait(32)                           -- 下一轮 t=62
            end
        end)
    end

    function card:frame()
    end

    function card:del()
        st.dead = true
        photo_damage_off(self)
    end

    boss.card.add({ { card, "13a" } }, LEVEL, CARD_NAME, CARD_ID)
end--化猫「橙」

---──────────────────── Stage 6 八云蓝 四生剣「衆生無情の響き」（ecl13_d，组 14a 第 4 张） ────────────────────
do  -- 57 八云蓝 四生剣「衆生無情の響き」（ecl13_d，组 14a 第 4 张）
    ---原作是「四生的无情回响」：本体在两段镜像的「曲」里各放一根横贯场地的巨柱
    ---（先瞬移到一侧边线、朝场地内甩 384 长的大柱、再瞬移回场外），插在两根柱子之间的
    ---是沿四条对角线泼出去的小玉雨 —— 拍中本体不足 4 张时是稀疏版（每次 4 发、
    ---每 2 帧一轮），拍够 4 张（ins_115 的 frame=4）主脚本被重开，从此走密集版
    ---（每次 8 发、每帧一轮，速度区间也抬到 1..2）。
    ---数据源 /tmp/W6d_ecl13_d.txt（ECL …/data/ecl13_d.ecl）。骨架：
    ---  · Sub2 @380：ins_115(0,4,3)（拍中第 4 张 ⇒ 重开主脚本）；ins_141(5)；ins_63(-2,-64)
    ---    进场 → t=100 ins_64(60,4,152,player.y) 落到 TH095 (152,player.y)；ins_114(6008)；
    ---    t=130 亮卡名 + ins_149(5) + ins_52(3)。
    ---  · Sub3 @716 是**一条 t=0..470 的大时间轴**（不是两条互斥分支）：
    ---    t=0 的 ins_44(photoIndex,4,120,184)：photoIndex < 4 时把 time 置 120、跳到 @900
    ---    （t=150）—— 也就是什么都不做、30 帧后进 t=150 那一段；photoIndex ≥ 4 时才落到下面：
    ---    ins_102 清屏、ins_51(world.x,0,60,96)：world.x ≥ 0 时置 time=60 跳到 @852
    ---    （t=60 的 ins_64(60,4,160,player.y)）；否则落 @784 的 ins_64(-160,player.y)、
    ---    t=60 的 ins_4(310,524) 把时间轴直接挪到 t=310。
    ---    t=150..470 这一段里：
    ---      t=150 装饰（ins_106/54/117(0,4)/118(12)/119(11)，见文件头差异 11）；
    ---      t=170 ins_144(15)；t=185 ins_54(11)；
    ---      t=190 记 floatV2 = world.x − 304、floatV3 = world.y、extraFloatV2 = π、
    ---            extraFloatV3 = 384、extraIntV2 = 13，ins_63(192, world.y) 瞬到右边线 →
    ---            ins_118(17)（sustain 120）甩出大柱 → ins_63(floatV2, floatV3) 瞬回场外 →
    ---            ins_117(0,5) 起 Sub5；
    ---      t=250 ins_64(60,4,-160,player.y)；
    ---      t=310 装饰；t=330 ins_144(15)；t=345 ins_54(10)；
    ---      t=350 同 t=190 的套路，但 extraFloatV2 = 0、瞬到**左边线** (−192, world.y)、
    ---            ins_118(10)（sustain 40），且退场用的是 ins_25（world.x **+** 304，往右退）；
    ---      t=410 ins_64(60,4,160,player.y)；
    ---      t=470 的 ins_4(150,-836) 跳回 @912（t=150）⇒ 一轮 320 帧。
    ---  · Sub5 @1880（slot0，t=190 / t=350 各起一次）：floatV1 = world.y（记下当时的 y）；
    ---    extraIntV0 = 8；ins_101 挂 VEC(60 帧、每帧 +1/30 ⇒ 末速 +2.0)；intV0 = photoIndex×16+8；
    ---    ins_44(photoIndex,4,0,48)：photoIndex < 4 时跳到 @2052（稀疏波，每次 4 发、
    ---    每 2 帧一轮、速 0.5 + rand×1.5、色 6/8/10/11），否则落到 @2032 的 ins_4(2,352)
    ---    → @2384（密集波，每次 8 发 = 4 条 c2=2 的 CIRCLE、每帧一轮、速 1 + rand×1、
    ---    色 4/2/2/4）；四条对角线是 −π/4、−3π/4、+π/4、+3π/4（TH095）；
    ---    出膛点是 (randF32s×192, floatV1)——横坐标全屏随机、纵坐标是 Sub5 进入时的本体 y。
    ---  · 不实现：ins_106/54/62/118(12)/(13)、ins_119(±11)、ins_144/149/150/114。
    local BOSS_X, BOSS_START_Y = -2, field_y(-64)       -- 288（场地外，x = -2）
    local HOME_X = 152                                   -- HOME 的 y = 落地那一刻的 player.y
    local ENTRY_WAIT, ENTRY_TIME = 100, 60
    local EASE_OUT = VALUE_SET.DECEL
    local PHOTO_LIMIT = 5                               -- ins_141(5)
    local RESTART_AT = 4                                -- ins_115(0,4,3)
    local CARD_NAME = "四生剣「衆生無情の響き」"
    local CARD_TIME, CARD_HP = 50, 900
    local CARD_ID = 501

    local LASER_ROW = 13
    local LASER_LEN, LASER_W, LASER_SPEED = 384, 16, 8
    local LASER_STARTUP, LASER_GROW, LASER_FADE = 1, 15, 6
    local LASER_SUSTAIN_A, LASER_SUSTAIN_B = 120, 40   -- ins_118(17) / ins_118(10)
    local OFF_FIELD = 304                               -- floatV2 = world.x − 304
    local STAR_ACCEL_FRAMES, STAR_ACCEL = 60, 0.0333333351
    local DIRS = { -0.785398, -2.35619, 0.785398, 2.35619 }   -- TH095 弧度
    local SPARSE_COLORS = { 6, 8, 10, 11 }
    local DENSE_COLORS = { 4, 2, 2, 4 }

    local lasers = {}
    local st = { dead = false }
    local sub5 = nil
    local sub3tok = nil

    ---等价 task.Wait(n)，但可以被 ins_115 的重开（拍够 4 张）随时打断。
    local function step(tok, n)
        for _ = 1, n do
            if not tok.alive or st.dead then return false end
            task.Wait(1)
        end
        return true
    end

    ---Sub5：四条对角线的小玉雨。dense = photoIndex ≥ 4 的版本。
    local function run_sub5(owner)
        if sub5 then sub5.alive = false end
        local tok = { alive = true }
        sub5 = tok
        local sy = owner.y                                 -- floatV1 = world.y
        local dense = photo_index(PHOTO_LIMIT) >= RESTART_AT
        local hook = sg_tr_hook({
            sg_rec(SG_VEC, 0, STAR_ACCEL_FRAMES, -1, STAR_ACCEL, -999.99),
        }, 0x202)
        local colors = dense and DENSE_COLORS or SPARSE_COLORS
        task.New(owner, function()
            while tok.alive and not st.dead do
                local px = 192 * ran:Float(-1, 1)
                local sp = dense and (1 + ran:Float(0, 1)) or (0.5 + 1.5 * ran:Float(0, 1))
                for i = 1, 4 do
                    sg_shot(89, ball_small, ex_color(colors[i]), px, sy,
                            1, dense and 2 or 1, sp, 0.5, sg_deg(DIRS[i]),
                            math.deg(0.1848), false, 0x202, hook)
                end
                task.Wait(dense and 1 or 2)
            end
        end)
    end

    local card = boss.card.New(CARD_NAME, 1, 3, CARD_TIME, CARD_HP)

    function card:before()
        lasers = {}
        sub5 = nil
        sub3tok = nil
    end

    ---一段「边线巨柱」：瞬到 (mx, 当前 y)、甩柱、瞬回 (当前 x + off, 当前 y)。
    ---★ off 有符号：t=190 用 ins_26（f2 = world.x − 304，往左退），
    ---t=350 用 ins_25（f2 = world.x **+** 304，往右退）—— 两根柱子是镜像的。
    local function side_laser(owner, mx, off, our_angle, sustain)
        local wx, wy = owner.x, owner.y
        owner.x, owner.y = mx, wy
        spawn_ex_laser(owner, lasers, LASER_ROW, owner.x, owner.y, our_angle,
                LASER_LEN, LASER_W, LASER_SPEED, LASER_STARTUP, LASER_GROW, sustain,
                LASER_FADE, 0, 0, 0, false, true)
        owner.x, owner.y = wx + off, wy
    end

    ---t=310 → t=470（photoIndex ≥ 4 且 world.x < 0 时由 @812 的 ins_4(310,524) 从 t=60 跳进来）。
    local function tail310(self, tok)
        if not step(tok, 40) then return false end            -- t=350
        side_laser(self, -192, OFF_FIELD, sg_deg(0), LASER_SUSTAIN_B)  -- ins_118(10)：左边线、朝 +x
        run_sub5(self)                                        -- ins_117(0,5)
        if not step(tok, 60) then return false end            -- t=410
        sg_move(self, st, 160, player.y, 60, EASE_OUT)        -- ins_64(60,4,160,player.y)
        if not step(tok, 60) then return false end            -- t=470
        return true
    end

    ---t=150 → t=470：一轮 320 帧（t=470 的 ins_4(150,-836) 把时间轴拉回 t=150）。
    local function cyc150(self, tok)
        if not step(tok, 40) then return false end            -- t=190
        side_laser(self, 192, -OFF_FIELD, sg_deg(math.pi), LASER_SUSTAIN_A)  -- ins_118(17)：右边线、朝 −x
        run_sub5(self)                                        -- ins_117(0,5)
        if not step(tok, 60) then return false end            -- t=250
        sg_move(self, st, -160, player.y, 60, EASE_OUT)       -- ins_64(60,4,-160,player.y)
        if not step(tok, 60) then return false end            -- t=310
        return tail310(self, tok)
    end

    ---Sub3：ins_115 重开时按 ins_44/ins_51 的分支走，否则（第一次进）ins_44 直接等到 t=150。
    ---★ 两处「把时间轴拨过去」都是**同帧生效**（CompareOperands 的 time=operand2 +
    ---instruction+=operand3，EclRunLow.inl:155-179；ins_4 同理），不是再等 N 帧：
    ---  · 第一次进：ins_44 把 time 从 0 拨到 120，离 @900 的 t=150 只差 **30** 帧；
    ---  · 重开后 world.x ≥ 0 一支：ins_51 把 time 拨到 60 直接落到 @852 的 ins_64；
    ---    60 帧走完时 time=120，那一条 ins_4(150,@912) 同帧把「t=150 段」拉起来 ⇒
    ---    这一支从 Sub3 t=0 到 t=190 的巨柱也只有 60+40 帧（与另一支的 60+40 汇合）。
    local function run_sub3(self, tok)
        if photo_index(PHOTO_LIMIT) >= RESTART_AT then
            sg_clear(lasers)                                  -- ins_102
            if self.x >= 0 then
                sg_move(self, st, 160, player.y, 60, EASE_OUT) -- ins_51 成立时的 t=60 目标
                if not step(tok, 60) then return end           -- t=120 → @880 的 ins_4(150,32)
            else
                sg_move(self, st, -160, player.y, 60, EASE_OUT)
                if not step(tok, 60) then return end           -- t=60 → @812 的 ins_4(310,524)
                if not tail310(self, tok) then return end      -- t=310 → t=470
            end
        else
            if not step(tok, 30) then return end               -- ins_44：time=120，离 t=150 差 30 帧
        end
        while true do
            if not cyc150(self, tok) then return end
        end
    end

    function card:init()
        photo_damage_on(self, PHOTO_LIMIT)
        self.x, self.y = BOSS_X, BOSS_START_Y
        st.dead = false
        task.New(self, function()
            local tok = { alive = true }
            sub3tok = tok
            if not step(tok, ENTRY_WAIT) then return end
            ---入场 ins_64(60,4,152,player.y) 要 60 帧才走完，但 Sub2 在 t=130 就
            ---ins_52(3) 切进 Sub3 ⇒ 移动必须非阻塞（Sub3 的 t=0 是入场第 30 帧）。
            sg_move(self, st, HOME_X, player.y, ENTRY_TIME, EASE_OUT)
            if not step(tok, 30) then return end            -- Sub3 的 t=0
            run_sub3(self, tok)
        end)
        ---ins_115(0,4,3)：拍中本体第 4 张时主上下文被**立刻**重开成 Sub3（t=0），
        ---并把 16 个 slot 的子上下文全部释放（EnemyManagerUpdate.cpp:1293-1310）。
        task.New(self, function()
            while not st.dead and photo_index(PHOTO_LIMIT) < RESTART_AT do
                task.Wait(1)
            end
            if st.dead then return end
            if sub3tok then sub3tok.alive = false; sub3tok = nil end
            if sub5 then sub5.alive = false; sub5 = nil end
            local tok = { alive = true }
            sub3tok = tok
            run_sub3(self, tok)
        end)
    end

    function card:frame()
    end

    function card:del()
        st.dead = true
        if sub3tok then sub3tok.alive = false end
        if sub5 then sub5.alive = false end
        photo_damage_off(self)
        sg_clear(lasers)
    end

    boss.card.add({ { card, "14a" } }, LEVEL, CARD_NAME, CARD_ID)
end--四生剣「衆生無情の響き」

---──────────────────── Stage 5（scene group 4 = world05）── 公共工具 / 八张卡 ────────────────────
---下面八张卡（scene 40..47）共用 world05 与 enm10/11.anm。数据源是
---/tmp/S5x_ecl10_{a..d}.txt 与 /tmp/S5x_ecl11_{a..d}.txt（脚本 /tmp/s5dump.py 反汇编；
---ECL 在 `[th095] …/data/ecl1{0,1}_{a..d}.ecl`），各卡注释里的「@地址」都指这几份 dump。
---色表 ex_color、sg_shot / sg_move / sg_bmove / sg_tr_hook / ins_147/153 的激光工具都在
---上面几段里（同一套）。角色对号见文件头「Stage 5」一节：ecl10_* = 红美铃（组 15a）、
---ecl11_* = 帕秋莉（组 16a）；整组只有 40 号这一幕是非符（不亮卡名）。
---
---★ 这一段整体包在一个 do…end 里：公共小工具只在这里有效，不会去挤主 chunk 的
---  200 个 local 名额（Stage 6 那一段就差点撞上）。
do

---TH095 的极坐标偏移 (半径 r, 弧度 θ) → 我们的相对位移：x 同号、y 取反
---（我们的 y = 224 − TH095 的 y）。ins_38(dx,dy,θ,r) + ins_100(dx,dy) 的 shootOffset 用。
local function sg_off(r, th_rad)
    return r * math.cos(th_rad), -r * math.sin(th_rad)
end

---TH095 的 AddNormalizeAngle：把**度**折进 [−180,180]（原作折进 [−π,π]）。
local function sg_norm(a)
    a = a % 360
    if a > 180 then a = a - 360 end
    return a
end

---一帧一帧地把本体挪到 (tx,ty)（线性缓动），**每帧**夹进 ins_75 的活动框 ——
---对应原作 INTERPOLATED 移动 + 同帧 ClampPosition（EnemyManagerUpdate.cpp:903）的组合。
---box = { x0, y0, x1, y1 }（TH095 坐标，y0 < y1）。
local function sg_move_clamped(owner, box, st, tok, tx, ty, n)
    local x0, y0 = owner.x, owner.y
    for s = 1, n do
        if not tok.alive or st.dead then return end
        local p = s / n
        owner.x = max(box[1], min(box[3], x0 + p * (tx - x0)))
        owner.y = max(field_y(box[4]), min(field_y(box[2]), y0 + p * (ty - y0)))
        task.Wait(1)
    end
end

do  -- 40 红美铃 非符（ecl10_a，组 15a 第 1 张）
    ---原作这一幕**不亮卡名**：红美铃先朝自机冲 300 px 进场（t=100 的
    ---ins_66(30,0,playerAngle,10)），t=130 设活动框之后每帧被 ClampPosition 夹进框里；
    ---此后每 80 帧重复一次「20 帧朝自机挪 120 px + 甩两波随机弹」。
    ---数据源 /tmp/S5x_ecl10_a.txt（ECL …/data/ecl10_a.ecl）。骨架：
    ---  · Sub2：ins_55(2)+ins_81(3)+ins_109(0)+ins_77(24,24)+ins_141(5)（拍 5 张）
    ---    + ins_108(0,31)/ins_108(1,30)+ins_143(1,130)+ins_63(-256,0) 进场
    ---    → t=100 ins_66(30,0,playerAngle,10)：30 帧朝「本体→自机」方向挪 300 px
    ---    → t=130 的 `id=0`（opcode 0 在 switch 里没有分支 ⇒ NOP，**不是**亮卡名）
    ---    + ins_75(-160,64,160,416)（活动框）+ ins_149(0.7) + ins_52(3) 起 Sub3。
    ---  · Sub3（80 帧一轮）：t=80 的 ins_52(4) **同步**跑一遍 Sub4（20 帧的
    ---    ins_66(20,0,playerAngle,6) = 挪 120 px），紧接着 ins_117(0,5) 另起 Sub5 甩弹；
    ---    ins_4(0,-52) 的跳转基准是**当前指令**（@816）⇒ 816−52=@764，正是那条
    ---    ins_52(4) ⇒ 每 80 帧「挪一次 + 甩一次」。
    ---  · Sub4（@848）：ins_66(20,0,playerAngle,6) + t=18 装饰 + t=20 ins_53 结束。
    ---  · Sub5（@956，放完 t=1 就 ins_53 结束）：ins_27/15 得
    ---    floatV2 = 0.448798954 + 0.0981747732×拍中张数（25.7° + 5.625°/张）；
    ---    ins_26/25 得 movementAngle±floatV2；7 个颜色各一条 ins_94 RANDOM（型 3、
    ---    count1=24、速 rand[0.5,6]、角在 [mA−f2, mA+f2] 里随机、flags 0x200）；
    ---    t=1 再把上下限改成 movementAngle±240°（跨 480°，等于全向随机）、7 色各
    ---    ins_94（型 0、count1=12、速 rand[0.4,3]、flags 0x210）。t=1 的这批发弹前
    ---    有一条 ins_101(0, 0x10 VEC, 0, 320, −1, 0.02, π/2)——t=0 那批的 flags 里
    ---    没有 0x10、而且写记录在它们之后，所以只有 t=1 这批吃这条加速。
    ---★ ins_66 的 ConfigurePolarMotion **不写** movementAngle；movementAngle 是
    ---  INTERPOLATED 移动每帧按位移方向 atan2 出来的（EnemyMovement.cpp:136）⇒ Sub5
    ---  读到的就是 Sub4 那 20 帧里本体实际走的朝向。这里用 st.mv_angle 记它。
    local BOSS_X, BOSS_START_Y = -256, field_y(0)       -- TH095 (-256,0)
    local ENTRY_WAIT, ENTRY_TIME, ENTRY_SPEED = 100, 30, 10
    local PUNCE_WAIT = 80                               -- Sub3 的 ins_4(0,-52)
    local PUNCE_FRAMES, PUNCE_SPEED = 20, 6             -- ins_52(4) 的 ins_66(20,0,playerAngle,6)
    local SPREAD0, SPREAD_PER = 0.448798954, 0.0981747732   -- floatV2 的初值 / 每张增量（rad）
    local FAR = 4.18879032                              -- t=1 的 ±240°
    local COLORS = { 6, 4, 2, 8, 10, 13, 14 }           -- 七条 RANDOM 的色号（原文顺序）
    local VEC = sg_rec(SG_VEC, 0, 320, -1, 0.02, sg_deg(math.pi / 2))

    local PHOTO_LIMIT = 5                               -- ins_141(5)
    local CARD_NAME = ""                                -- 非符：原作 t=130 是 id=0
    local CARD_TIME, CARD_HP = 50, 900
    local CARD_ID = 502
    local BOX = { -160, 64, 160, 416 }                  -- ins_75（TH095 空间）

    local st = { dead = false, mv_angle = 0 }
    local tok = { alive = true }

    ---Sub5：两帧两波随机弹（见上）。
    local function sub5(owner)
        task.New(owner, function()
            local f2 = math.deg(SPREAD0 + SPREAD_PER * photo_index(PHOTO_LIMIT))
            local mA = st.mv_angle
            for i = 1, #COLORS do
                sg_shot(94, sg_style(3), ex_color(COLORS[i]), owner.x, owner.y,
                        24, 1, 6, 0.5, mA + f2, mA - f2, false, 0x200)
            end
            task.Wait(1)
            if st.dead then return end
            local far = math.deg(FAR)
            local hook = sg_tr_hook({ VEC }, SG_VEC)
            for i = 1, #COLORS do
                sg_shot(94, sg_style(0), ex_color(COLORS[i]), owner.x, owner.y,
                        12, 1, 3, 0.4, mA + far, mA - far, false, 0x210, hook)
            end
        end)
    end

    ---Sub3：每 80 帧「同步挪 20 帧 + 甩一波」。
    local function sub3(owner)
        task.New(owner, function()
            while tok.alive and not st.dead do
                for _ = 1, PUNCE_WAIT do
                    if not tok.alive or st.dead then return end
                    task.Wait(1)
                end
                local a_th = sg_aim(owner.x, owner.y)       -- TH095 度
                st.mv_angle = a_th
                local a = math.rad(-a_th)                   -- 我们的弧度
                sg_move_clamped(owner, BOX, st, tok,
                        owner.x + PUNCE_FRAMES * PUNCE_SPEED * cos(math.deg(a)),
                        owner.y + PUNCE_FRAMES * PUNCE_SPEED * sin(math.deg(a)),
                        PUNCE_FRAMES)
                sub5(owner)
            end
        end)
    end

    local card = boss.card.New(CARD_NAME, 1, 3, CARD_TIME, CARD_HP)

    function card:before()
    end

    function card:init()
        photo_damage_on(self, PHOTO_LIMIT)
        self.x, self.y = BOSS_X, BOSS_START_Y
        st.dead = false
        st.mv_angle = 0
        task.New(self, function()
            task.Wait(ENTRY_WAIT)
            local a_th = sg_aim(self.x, self.y)
            st.mv_angle = a_th
            local a = math.rad(-a_th)
            ---★ 入场这一段的 ins_75 还没执行（活动框在 t=130 才设、ins_75 才开夹取），
            ---所以入场是**不夹**的自由直线（EclRunLow.inl:75 的 case 75 才置
            ---clampToMovementBounds）。之前用 sg_move_clamped 把 (-256,0) 一上来就钉在
            ---x=−160，进场路线整个变了。
            sg_move(self, st,
                    self.x + ENTRY_TIME * ENTRY_SPEED * cos(math.deg(a)),
                    self.y + ENTRY_TIME * ENTRY_SPEED * sin(math.deg(a)),
                    ENTRY_TIME, 0)
            task.Wait(ENTRY_TIME)
            sub3(self)
        end)
    end

    function card:frame()
    end

    function card:del()
        st.dead = true
        tok.alive = false
        photo_damage_off(self)
    end

    boss.card.add({ { card, "15a" } }, LEVEL, CARD_NAME, CARD_ID)
end--红美铃 非符（ecl10_a）

do  -- 41 日＆水符「ハイドロジェナスプロミネンス」（ecl11_a，帕秋莉，组 16a 第 1 张）
    ---原作是一条 210 帧一轮的三件套：① 48 根**跟着本体走**的旋转激光（ins_153）在
    ---同一帧里排成整圈、彼此差 7.5°，整圈的基准角是发那一刻的自机方向；② 一整圈 32 颗
    ---大玉（型 17 = ball_huge、速 2）；③ 在离本体 64 px 的随机点上朝全向甩
    ---（1 + 拍中张数）组 × 各 2 发小玉。
    ---数据源 /tmp/S5x_ecl11_a.txt（ECL …/data/ecl11_a.ecl）。骨架：
    ---  · Sub2：ins_55(2)+ins_81(3)+ins_109(0)+ins_77(24,24)+ins_141(5)（拍 5 张）
    ---    + ins_108(0,31)/ins_108(1,30)+ins_143(1,130)+ins_63(-128,-64) 进场
    ---    → t=100 ins_64(30,4,0,128) 落到 (0,128)（我们的 (0,96)）→ t=130 亮卡名
    ---    + ins_75(-160,96,160,192) + ins_52(3) 起 Sub3。
    ---  · Sub3（210 帧一轮）：t=0 起 Sub4/Sub5/Sub6 三条并行上下文；t=210 的
    ---    ins_4(0,-76) 跳回**当前指令−76** = @728（t=0 的 ins_117(0,4)）⇒ 每 210 帧
    ---    把三条全部重开一遍（三条都是一次性的，重开 = 再来一轮）。
    ---  · Sub4（@836）：ins_6(extraIntV0,48) 当计数；t=60 起 ins_7(floatV0,playerAngle)
    ---    + ins_153(型5、色6、角 floatV0、长 512、宽 16、60/10/80/10、角速 0、follow=1)
    ---    + ins_15(floatV0,+0.1308997 rad) + ins_5(60,−76,extraIntV0)。ins_5 的跳转基准
    ---    是当前指令（@968）⇒ 968−76=@892，正是那条 ins_153；而 ins_5 先把计数 −1、
    ---    再把 time 拨回 60 ⇒ 这 48 根**在同一帧里**放完（不是每 60 帧一根）。
    ---  · Sub5（@1016）：t=30 ins_7(floatV0,playerAngle) + ins_89 CIRCLE(型 17、色 0、
    ---    count1=32、count2=1、速 2、基角 floatV0、flags 0x202) + ins_53。
    ---  · Sub6（@1124）：t=70 intV0 = 1 + 拍中张数；floatV0 = playerAngle + π（备用）；
    ---    循环体 @1172..@1404 跑 intV0 遍：ins_27(extraFloatV0, 64, randF32) +
    ---    ins_38(extraFloatV0, extraFloatV1, rand(−π,π), extraFloatV0) + ins_100 设
    ---    shootOffset（半径 64 的随机点）+ ins_94 RANDOM(型 0、色 2 / 色 6、count1=32、
    ---    速 rand[1.5,4]、角在 [−π,π] 全向、flags 0x202)；收尾 ins_100(0,0) 复位 + ins_53。
    ---★ ins_5 会把 time 拨回 70（不是 0），但跳转目标 @1172 的 t 就是 70 ⇒ 循环体每遍
    ---  **同帧**跑完；两遍之间没有等待。
    local BOSS_X, BOSS_START_Y = -128, field_y(-64)
    local HOME_X, HOME_Y = 0, field_y(128)              -- 0 / 96
    local ENTRY_WAIT, ENTRY_TIME = 100, 30
    local EASE_OUT = VALUE_SET.DECEL

    local PHOTO_LIMIT = 5                               -- ins_141(5)
    local CARD_NAME = "日＆水符「ハイドロジェナスプロミネンス」"
    local CARD_TIME, CARD_HP = 50, 900
    local CARD_ID = 503

    local CYCLE = 210                                   -- Sub3 一轮
    local WHEEL_AT, WHEEL_N, WHEEL_STEP = 60, 48, 7.5   -- Sub4（0.1308997 rad = 7.5°）
    local WHEEL_LEN, WHEEL_W = 512, 16
    local WHEEL_SEG = { 60, 10, 80, 10 }                -- startup/grow/sustain/fade
    local WHEEL_ROW = 6                                 -- 原作 color 6（laser 贴图行 = color）
    local RING_AT, RING_N, RING_SPEED = 30, 32, 2       -- Sub5
    local SPRAY_AT, SPRAY_R = 70, 64                    -- Sub6
    local SPRAY_N, SPRAY_SPEED0, SPRAY_SPEED1 = 32, 4, 1.5
    local BOX = { -160, 96, 160, 192 }                  -- ins_75

    local lasers = {}
    local st = { dead = false }

    ---Sub4：一帧放完 48 根跟随激光（整圈、7.5° 一根）。
    local function sub4(owner)
        task.New(owner, function()
            for _ = 1, WHEEL_AT do
                if st.dead then return end
                task.Wait(1)
            end
            local a = sg_aim(owner.x, owner.y)          -- TH095 度
            for _ = 1, WHEEL_N do
                if st.dead then return end
                spawn_ex_laser(owner, lasers, WHEEL_ROW, owner.x, owner.y, -a,
                        WHEEL_LEN, WHEEL_W, 8, WHEEL_SEG[1], WHEEL_SEG[2],
                        WHEEL_SEG[3], WHEEL_SEG[4], 0, 0, 0, true, false)
                a = a + WHEEL_STEP
            end
        end)
    end

    ---Sub5：t=30 甩一整圈 32 颗大玉。
    local function sub5(owner)
        task.New(owner, function()
            for _ = 1, RING_AT do
                if st.dead then return end
                task.Wait(1)
            end
            sg_shot(89, sg_style(17), ex_color(0), owner.x, owner.y,
                    RING_N, 1, RING_SPEED, 1.5, sg_aim(owner.x, owner.y), 0, false, 0x202)
        end)
    end

    ---Sub6：t=70，在半径 64 的随机点上朝全向甩（1+拍中张数）组 × 各 2 发小玉。
    local function sub6(owner)
        task.New(owner, function()
            for _ = 1, SPRAY_AT do
                if st.dead then return end
                task.Wait(1)
            end
            local base, step = math.deg(-math.pi), math.deg(math.pi)
            for _ = 1, 1 + photo_index(PHOTO_LIMIT) do
                for k = 1, 2 do
                    local ox, oy = sg_off(SPRAY_R * ran:Float(0, 1), ran:Float(-math.pi, math.pi))
                    sg_shot(94, sg_style(0), ex_color(k == 1 and 2 or 6),
                            owner.x + ox, owner.y + oy,
                            SPRAY_N, 1, SPRAY_SPEED0, SPRAY_SPEED1, base, step,
                            false, 0x202)
                end
            end
        end)
    end

    ---Sub3：每 210 帧把三条并行上下文各重开一遍。
    local function sub3(owner)
        task.New(owner, function()
            while not st.dead do
                sub4(owner)
                sub5(owner)
                sub6(owner)
                for _ = 1, CYCLE do
                    if st.dead then return end
                    task.Wait(1)
                end
            end
        end)
    end

    local card = boss.card.New(CARD_NAME, 1, 3, CARD_TIME, CARD_HP)

    function card:before()
    end

    function card:init()
        photo_damage_on(self, PHOTO_LIMIT)
        self.x, self.y = BOSS_X, BOSS_START_Y
        st.dead = false
        task.New(self, function()
            task.Wait(ENTRY_WAIT)
            task.MoveTo(HOME_X, HOME_Y, ENTRY_TIME, EASE_OUT)
            sub3(self)
        end)
    end

    function card:frame()
    end

    function card:del()
        st.dead = true
        photo_damage_off(self)
        sg_clear(lasers)
    end

    boss.card.add({ { card, "16a" } }, LEVEL, CARD_NAME, CARD_ID)
end--日＆水符「ハイドロジェナスプロミネンス」

do  -- 42 華符「彩光蓮華掌」（ecl10_b，红美铃，组 15a 第 2 张）
    ---原作是「两掌开合」：本体随机落在中轴左侧 (64,128) 或右侧 (−64,128)（我们的 ±64,96），
    ---两条并行上下文各朝一侧甩「一圈 7 发、每 4 帧一圈、共 7 圈」的彩弹 —— 这些弹
    ---**先线性减速到停**（70 帧内速 3→0），停住之后**原方向**突然以 1.2~1.8 的速度再冲出去；
    ---每 100 帧还要停掉这两条、让本体在活动框里随机挪 120 px。
    ---数据源 /tmp/S5x_ecl10_b.txt（ECL …/data/ecl10_b.ecl）。骨架：
    ---  · Sub2：… + ins_141(5)（拍 5 张）+ ins_63(-256,-64)；t=0 的 ins_24(intV0,randU31,2)
    ---    + ins_42(intV0,0,100,96)（**整数 ≠** 才跳）⇒ intV0≠0 时跳到 @644 的
    ---    ins_63(256,-64)（跳转基准是当前指令 @548 ⇒ 548+96=644）；intV0==0 时落到
    ---    @596 的 ins_64(30,0,64,128)。⇒ 两个落点 (±64,128)，t=100 / t=200 各一。
    ---    t=230 亮卡名 + ins_75(-160,96,160,192) + ins_52(3)。
    ---  · Sub3（120 帧一轮）：t=0 floatV2=0、floatV1=+0.0392699 + ins_117(0,5)；
    ---    再 floatV2=0、floatV1=−0.0392699 + ins_117(1,5)（两条 Sub5）；t=100 的
    ---    ins_52(4) 同步跑 Sub4，紧接着 ins_117(0,5)/ins_117(1,5) 重开两条，然后
    ---    ins_4(0,-152) 跳回 @916（floatV2=0 那句）⇒ 每轮 100 帧 + Sub4 的 20 帧。
    ---  · Sub4（@1100，同步 20 帧）：ins_117(0,-1)/ins_117(1,-1) 停掉两条，ins_67(20,0,6)
    ---    在活动框里随机挪 120 px，t=20 ins_53。
    ---  · Sub5（@1244，两条实例）：floatV0 = playerAngle；ins_101(0, 0x40 CHDIR_REL, 0,
    ---    70, 1, floatV2, 重写速)——floatV2 = 0（Sub3 刚写的）⇒ 每帧角增量为 0；
    ---    t=0/4/8/…/24 共 7 条 ins_89 CIRCLE(型 3、count1=7、速 3、基角 floatV0、
    ---    flags 0x242 = FAST|CHDIR_REL|SND)，每条用的「到点速」依次 1.6/1.2/1.4/1.6/1.8/
---    1.2/1.4；**每圈发完**都做一次 floatV0 −= floatV1（±2.25°）再归一化（7 句 ins_16 +
---    ins_37 在 dump 里各出现 7 次）⇒ 一圈比上一圈多转 ∓2.25°，一个 28 帧周期共
---    7×2.25° = ∓15.75°；t=28 的 ins_4(0,-840) 跳回**当前指令−840** = @1264（那条
---    ins_101）⇒ 每 28 帧一轮、7 圈，基角一直累加（@1244 读 playerAngle 在跳转点之前，
---    只在每次 Sub5 重开时读一次）。
    ---★ CHDIR_REL 的语义（BulletManager.cpp:846-878）：每 interval 帧把速度线性减到 0，
    ---  到点那一帧角 += f0、速 = f1、重复计数 −1 —— 这里 f0=0、f1=重写值、重复 1 次，
    ---  所以弹是「滑停 → 同方向再冲」。
    local BOSS_X, BOSS_START_Y = -256, field_y(-64)
    local ENTRY_WAIT, ENTRY_TIME = 100, 30
    local PHOTO_LIMIT = 5
    local CARD_NAME = "華符「彩光蓮華掌」"
    local CARD_TIME, CARD_HP = 50, 900
    local CARD_ID = 504
    local BOX = { -160, 96, 160, 192 }                  -- ins_75
    local LAND_Y = field_y(128)                         -- 96
    local FALL = { 64, -64 }                            -- 两个落点（TH095 的 x）

    local CYCLE = 120                                   -- 100 帧 + Sub4 的 20 帧
    local STOP_AT = 90                                  -- Sub3 的 t=90（装饰音）
    local MOVE_FRAMES, MOVE_SPEED = 20, 6               -- Sub4 的 ins_67(20,0,6)
    local SPREAD = math.deg(0.0392699093)               -- 2.25°（floatV1）
    local RING_N, RING_SPEED, RING_STEP = 7, 3, math.deg(0.1848)
    local RING_COLORS = { 4, 6, 8, 10, 13, 14, 2 }      -- 7 条 CIRCLE 的色号（原文顺序）
    local RING_SPEEDS = { 1.6, 1.2, 1.4, 1.6, 1.8, 1.2, 1.4 }   -- 每条重写的「到点速」
    local RING_GAP = 4                                  -- 相邻两圈的帧距
    local CHDIR_FRAMES, CHDIR_REPEAT = 70, 1
    local CHDIR_FLAGS = 0x242                           -- FAST|CHDIR_REL|SND

    local st = { dead = false }
    local sub5_tok = {}

    ---Sub5 一条实例。dir = +1 时基角每轮 −2.25°、−1 时 +2.25°。
    local function sub5(owner, dir, tok)
        task.New(owner, function()
            local fv = sg_aim(owner.x, owner.y)         -- floatV0 = playerAngle（TH095 度）
            while tok.alive and not st.dead do
                for k = 1, #RING_COLORS do
                    if not tok.alive or st.dead then return end
                    local hook = sg_tr_hook({
                        sg_rec(SG_CHDIR_R, 0, CHDIR_FRAMES, CHDIR_REPEAT, 0, RING_SPEEDS[k]),
                    }, SG_CHDIR_R)
                    sg_shot(89, sg_style(3), ex_color(RING_COLORS[k]), owner.x, owner.y,
                            RING_N, 1, RING_SPEED, 1.5, fv, RING_STEP, false,
                            CHDIR_FLAGS, hook)
                    ---@1348：每一圈发完都做一次 ins_16(floatV0 −= floatV1) + ins_37(归一化)
                    ---⇒ 下一圈的基角比这一圈多转 ∓2.25°（两掌一张一合）。
                    fv = sg_norm(fv - dir * SPREAD)
                    task.Wait(RING_GAP)
                end
            end
        end)
    end

    local function stop_one(i)
        if sub5_tok[i] then sub5_tok[i].alive = false; sub5_tok[i] = nil end
    end

    local function start_one(owner, i, dir)
        stop_one(i)
        local tok = { alive = true }
        sub5_tok[i] = tok
        sub5(owner, dir, tok)
    end

    local function stop_sub5()
        stop_one(1)
        stop_one(2)
    end

    ---Sub3：每轮 120 帧（100 帧节拍 + 20 帧 Sub4）。
    local function sub3(owner)
        task.New(owner, function()
            start_one(owner, 1, 1)                      -- floatV1 = +2.25°
            start_one(owner, 2, -1)                     -- floatV1 = −2.25°
            while not st.dead do
                for _ = 1, STOP_AT + 10 do              -- t=90 的装饰 + t=100 的 ins_52
                    if st.dead then return end
                    task.Wait(1)
                end
                ---Sub4：停掉两条 → 20 帧随机挪位 → 再重开两条（原作的 117(0,-1)/(1,-1)）。
                stop_sub5()
                sg_bmove(owner, st, MOVE_FRAMES, 0, MOVE_SPEED, BOX)
                for _ = 1, MOVE_FRAMES do
                    if st.dead then return end
                    task.Wait(1)
                end
                if st.dead then return end
                start_one(owner, 1, 1)
                start_one(owner, 2, -1)
            end
        end)
    end

    local card = boss.card.New(CARD_NAME, 1, 3, CARD_TIME, CARD_HP)

    function card:before()
    end

    function card:init()
        photo_damage_on(self, PHOTO_LIMIT)
        self.x, self.y = BOSS_X, BOSS_START_Y
        st.dead = false
        sub5_tok = {}
        local side = ran:Int(0, 1)                      -- ins_24(intV0, randU31, 2)
        task.New(self, function()
            task.Wait(ENTRY_WAIT)
            if side == 0 then
                task.MoveTo(FALL[1], LAND_Y, ENTRY_TIME, 0)     -- t=100 → 130
                task.Wait(100)                                  -- 到 t=230
            else
                self.x, self.y = 256, field_y(-64)              -- t=100 的 ins_63(256,-64)
                task.Wait(100)                                  -- 到 t=200
                task.MoveTo(FALL[2], LAND_Y, ENTRY_TIME, 0)     -- t=200 → 230
                ---（两条路都是 t=230 亮卡名：A 是 100+30+100，B 是 100+100+30；
                --- 原来 B 这里多等了一帧 ⇒ 会晚 1 帧起 Sub3。）
            end
            if st.dead then return end
            sub3(self)
        end)
    end

    function card:frame()
    end

    function card:del()
        st.dead = true
        stop_sub5()
        photo_damage_off(self)
    end

    boss.card.add({ { card, "15a" } }, LEVEL, CARD_NAME, CARD_ID)
end--華符「彩光蓮華掌」

do  -- 43 水＆火符「フロギスティックレイン」（ecl11_b，帕秋莉，组 16a 第 2 张）
    ---原作是「两股逆流的水火」：两条常驻上下文各每帧放 1 发小玉、方向每帧 −0.75°（TH095），
    ---一条从 180°、一条从 0° 起步 ⇒ 两股正好相对、一起转；另有一条每 190 帧来一轮
    ---「1、2、3、…、7 发的自机狙扇」（同帧全放完），本体每轮还在活动框里随机挪 60 px。
    ---数据源 /tmp/S5x_ecl11_b.txt（ECL …/data/ecl11_b.ecl）。骨架：
    ---  · Sub2：… + ins_141(5)（拍 5 张）+ ins_63(-128,-64) → t=100 ins_64(30,4,0,160)
    ---    落到 (0,160)（我们的 (0,64)）→ t=130 亮卡名 + ins_75(-160,96,160,256) + ins_52(3)。
    ---  · Sub3：t=0 起 Sub4/Sub5/Sub6（三条都只起一次）；t=60 ins_67(60,4,1)（60 帧挪
    ---    60 px）；t=60 起 Sub6 又在 t=120 重开一次；t=190 的 ins_4(0,-80) 跳回
    ---    **当前指令−80** = @768（t=0 的 ins_117(2,6)）⇒ 每 190 帧重开 Sub6 两次
    ---    （t=0 与 t=120），Sub4/Sub5 不受影响、一直转。
    ---  · Sub4（@880）：floatV1 = −π（朝左）、floatV0 = 3（速）、extraIntV0 = 240（没用到）；
    ---    ins_87 FAN(型 18、色 0、count1=1、速 floatV0、基角 floatV1、flags 0x202) →
    ---    ins_16(floatV1, 0.01308997 rad)（−0.75°）→ ins_37；t=1 的 ins_4(0,-80) 跳回
    ---    **当前指令−80** = @940（那条 FAN）⇒ 每帧一发、方向每帧 −0.75°。
    ---  · Sub5（@1064）：同 Sub4，只是 floatV1 = 0（朝右）。
    ---  · Sub6（@1248）：floatV1 = playerAngle、floatV0 = 2.5、extraIntV0 = 7、intV0 = 1；
    ---    ins_87 FAN(count1 = **intV0**、速 floatV0、基角 floatV1、步长 0.241661 rad = 13.846°)
    ---    → ins_10(intV0,+1) → t=10 的 ins_5(0,−64,extraIntV0)。ins_5 把计数 −1、time 拨回 0
    ---    后跳回 @1328（那条 ins_87）；但 ins_5 自己的 time 是 10，所以每轮都要先等满 10 帧
    ---    ⇒ 7 个扇分别落在 t=0/10/…/60（1+2+…+7 = 28 发），t=60 的 ins_53 收尾。
    local BOSS_X, BOSS_START_Y = -128, field_y(-64)
    local HOME_X, HOME_Y = 0, field_y(160)              -- 0 / 64
    local ENTRY_WAIT, ENTRY_TIME = 100, 30
    local EASE_OUT = VALUE_SET.DECEL

    local PHOTO_LIMIT = 5                               -- ins_141(5)
    local CARD_NAME = "水＆火符「フロギスティックレイン」"
    local CARD_TIME, CARD_HP = 50, 900
    local CARD_ID = 505
    local BOX = { -160, 96, 160, 256 }                  -- ins_75

    local CYCLE = 190
    local MOVE_AT, MOVE_FRAMES, MOVE_SPEED = 60, 60, 1  -- Sub3 的 ins_67(60,4,1)
    local STREAM_SPEED = 3                              -- floatV0
    local STREAM_TURN = math.deg(0.0130899698)          -- −0.75°/帧（TH095）
    local FAN_SPEED = 2.5                               -- floatV0
    local FAN_N = 7                                     -- extraIntV0
    local FAN_STEP = math.deg(0.241660967)              -- 13.846°
    local FAN_GAP = 10                                  -- ins_5 的 time=10（@1332 的 +10）

    local st = { dead = false }

    ---Sub4/Sub5：每帧一发的旋转流（th0 是 TH095 度）。
    local function stream(owner, th0)
        task.New(owner, function()
            local a = th0
            while not st.dead do
                sg_shot(87, sg_style(18), ex_color(0), owner.x, owner.y,
                        1, 1, STREAM_SPEED, 1.5, a, 0, false, 0x202)
                a = sg_norm(a - STREAM_TURN)
                task.Wait(1)
            end
        end)
    end

    ---Sub6：1..7 发的自机狙扇，每 10 帧一轮（共 28 发）。
    ---★ ins_5 的 time 是 **10**（raw ecl 的 `+10: //10` 就压在 ins_5 上），而 ins_5
    ---  把 time 拨回 0 后再跳回 @1328（那条 ins_87）—— 于是每轮到 ins_5 都要先等满
    ---  10 帧，7 轮分别落在 t=0/10/…/60，**不是**同帧放完。
    local function fan(owner)
        task.New(owner, function()
            local base = sg_aim(owner.x, owner.y)
            for n = 1, FAN_N do
                if st.dead then return end
                sg_shot(87, sg_style(18), ex_color(0), owner.x, owner.y,
                        n, 1, FAN_SPEED, 1.5, base, FAN_STEP, false, 0x202)
                if n < FAN_N then
                    for _ = 1, FAN_GAP do
                        if st.dead then return end
                        task.Wait(1)
                    end
                end
            end
        end)
    end

    local function sub3(owner)
        task.New(owner, function()
            stream(owner, 180)                          -- floatV1 = −π（TH095 度 −180）
            stream(owner, 0)
            while not st.dead do
                fan(owner)                              -- t=0
                for _ = 1, MOVE_AT do
                    if st.dead then return end
                    task.Wait(1)
                end
                sg_bmove(owner, st, MOVE_FRAMES, 4, MOVE_SPEED, BOX)    -- t=60
                for _ = 1, MOVE_AT do
                    if st.dead then return end
                    task.Wait(1)
                end
                fan(owner)                              -- t=120
                for _ = 1, CYCLE - 2 * MOVE_AT do
                    if st.dead then return end
                    task.Wait(1)
                end
            end
        end)
    end

    local card = boss.card.New(CARD_NAME, 1, 3, CARD_TIME, CARD_HP)

    function card:before()
    end

    function card:init()
        photo_damage_on(self, PHOTO_LIMIT)
        self.x, self.y = BOSS_X, BOSS_START_Y
        st.dead = false
        task.New(self, function()
            task.Wait(ENTRY_WAIT)
            task.MoveTo(HOME_X, HOME_Y, ENTRY_TIME, EASE_OUT)
            sub3(self)
        end)
    end

    function card:frame()
    end

    function card:del()
        st.dead = true
        photo_damage_off(self)
    end

    boss.card.add({ { card, "16a" } }, LEVEL, CARD_NAME, CARD_ID)
end--水＆火符「フロギスティックレイン」

do  -- 44 彩翔「飛花落葉」（ecl10_c，红美铃，组 15a 第 3 张）
    ---原作是「飞花落叶」：本体随机落在中轴一侧，先把两条子上下文停掉、自己在活动框里
    ---随机挪 120 px（20 帧），然后**一次性**甩出 4 批 × 7 色 × 4 发 = 112 发小玉 ——
    ---4 批各自沿一个固定方向（±90°、180°、0°，TH095）做 320 帧、0.02 px/帧² 的加速，
    ---同一批里的角度在 480° 宽的范围里随机、速度在 [0.4,1.8] 里随机。拍的张数越多，
    ---两次出手的间隔越短（70 − 10×拍中张数 帧的冻结）。
    ---数据源 /tmp/S5x_ecl10_c.txt（ECL …/data/ecl10_c.ecl）。骨架：
    ---  · Sub2：… + ins_141(6)（拍 **6** 张）+ 与卡 42 同一套左右随机（两个落点 ±64,128）
    ---    → t=230 亮卡名 + ins_75(-160,64,160,384) + ins_149(1.6) + ins_52(3)。
    ---  · Sub3（一轮 = 冻结 + 20 帧 Sub4 + 30 帧）：t=0 起 Sub5（slot0）；t=30
    ---    extraIntV0 = 70 − 10×photoIndex（ins_22 = 整数乘 + ins_21 = 整数减），
    ---    ins_2(extraIntV0) 把本上下文冻结这么多帧；醒来后 ins_52(4) 同步跑 Sub4
    ---    （20 帧的 ins_66(20,0,playerAngle,6)），紧接 ins_117(0,5) 重开 Sub5，再
    ---    ins_4(0,-116) 跳回 **当前指令−116** = @952（t=30 的 ins_144）⇒ 每轮
    ---    (70−10×p) + 20 + 30 帧。Sub5 是一次性的（t=0 放完就 ins_53）。
    ---  · Sub4（@1100，同步 20 帧）：ins_66(20,0,playerAngle,6) + t=18 装饰 + t=20 ins_53。
    ---  · Sub5（@1208，全在 t=0）：先 ins_101(0, 0x10 VEC, 0, 320, −1, 0.02, 加速方向)，
    ---    再 ins_7 设 floatV0/floatV1（角度的上下限，TH095 弧度）、7 条 ins_94 RANDOM
    ---    (型 3、count1=4、速 [0.4,1.8]、flags 0x210)；四批的加速方向依次
    ---    +π/2、−π/2、π、0，上下限依次 (±/∓)…（见 BATCHES）。t=0 放完即 ins_53。
    local BOSS_X, BOSS_START_Y = -256, field_y(-64)
    local ENTRY_WAIT, ENTRY_TIME = 100, 30
    local PHOTO_LIMIT = 6                               -- ins_141(6)
    local CARD_NAME = "彩翔「飛花落葉」"
    local CARD_TIME, CARD_HP = 50, 900
    local CARD_ID = 506
    local BOX = { -160, 64, 160, 384 }                  -- ins_75
    local LAND_Y = field_y(128)                         -- 96
    local FALL = { 64, -64 }

    local FREEZE_BASE, FREEZE_PER = 70, 10              -- extraIntV0 = 70 − 10×photoIndex
    local MOVE_FRAMES, MOVE_SPEED = 20, 6               -- ins_66(20,0,playerAngle,6)
    local LEAD = 30                                     -- ins_4 跳回 @968（t=30）的 30 帧
    local VEC_FRAMES, VEC_ACCEL = 320, 0.02
    local COLORS = { 6, 4, 2, 8, 10, 13, 14 }
    local BALL_N, BALL_SP1, BALL_SP2 = 4, 1.8, 0.4
    ---四批：(加速方向/rad, 角度上限 floatV0/rad, 角度下限 floatV1/rad)。
    local BATCHES = {
        { math.pi / 2, -5.75958633, 2.61799383 },
        { -math.pi / 2, -2.61799383, 5.75958633 },
        { math.pi, -4.18879032, 4.18879032 },
        { 0, -1.04719758, 7.33038282 },
    }

    local st = { dead = false }
    local tok = { alive = true }

    ---Sub5：一帧放完 4 批 × 7 色 × 4 发。
    local function sub5(owner)
        for b = 1, #BATCHES do
            local hook = sg_tr_hook({
                sg_rec(SG_VEC, 0, VEC_FRAMES, -1, VEC_ACCEL, sg_deg(BATCHES[b][1])),
            }, SG_VEC)
            local base = math.deg(BATCHES[b][2])
            local step = math.deg(BATCHES[b][3])
            for i = 1, #COLORS do
                sg_shot(94, sg_style(3), ex_color(COLORS[i]), owner.x, owner.y,
                        BALL_N, 1, BALL_SP1, BALL_SP2, base, step, false, 0x210, hook)
            end
        end
    end

    ---Sub3：t=0 先甩一波，此后每轮「等 30 帧 → 冻结（70−10×拍中张数）→ 同步挪 20 帧
    ---→ 再甩一波」。★ ins_4(0, Sub3_112) 的目标 @968 是 t=**30**（不是 t=0），所以
    ---每轮开头要空转 30 帧；原来漏了这个前置等待、也漏了 t=0 的第一波。
    local function sub3(owner)
        task.New(owner, function()
            sub5(owner)                                 -- Sub3 t=0 的 ins_117(0,5)
            while tok.alive and not st.dead do
                for _ = 1, LEAD do
                    if not tok.alive or st.dead then return end
                    task.Wait(1)
                end
                local freeze = max(0, FREEZE_BASE - FREEZE_PER * photo_index(PHOTO_LIMIT))
                for _ = 1, freeze do
                    if not tok.alive or st.dead then return end
                    task.Wait(1)
                end
                local a_th = sg_aim(owner.x, owner.y)
                local a = math.rad(-a_th)
                sg_move_clamped(owner, BOX, st, tok,
                        owner.x + MOVE_FRAMES * MOVE_SPEED * cos(math.deg(a)),
                        owner.y + MOVE_FRAMES * MOVE_SPEED * sin(math.deg(a)),
                        MOVE_FRAMES)
                sub5(owner)
            end
        end)
    end

    local card = boss.card.New(CARD_NAME, 1, 3, CARD_TIME, CARD_HP)

    function card:before()
    end

    function card:init()
        photo_damage_on(self, PHOTO_LIMIT)
        self.x, self.y = BOSS_X, BOSS_START_Y
        st.dead = false
        local side = ran:Int(0, 1)
        task.New(self, function()
            task.Wait(ENTRY_WAIT)
            if side == 0 then
                task.MoveTo(FALL[1], LAND_Y, ENTRY_TIME, 0)
                task.Wait(100)
            else
                self.x, self.y = 256, field_y(-64)
                task.Wait(100)
                task.MoveTo(FALL[2], LAND_Y, ENTRY_TIME, 0)
            end
            if st.dead then return end
            sub3(self)
        end)
    end

    function card:frame()
    end

    function card:del()
        st.dead = true
        tok.alive = false
        photo_damage_off(self)
    end

    boss.card.add({ { card, "15a" } }, LEVEL, CARD_NAME, CARD_ID)
end--彩翔「飛花落葉」

do  -- 45 月＆木符「サテライトヒマワリ」（ecl11_c，帕秋莉，组 16a 第 3 张）
    ---原作是「卫星向日葵」：本体不动，两个发射点（离本体 144 px、一上一下）各连续吐弹 ——
    ---每颗弹**先在原地等 120/190 帧**（WAIT 记录），再沿自己出生方向以 1/15（或 1/17.14）
    ---每帧加速 60 帧 —— 所以场面上是一层层「悬停的花籽」同时炸开；发射点自己还在绕圈
    ---（3.6°/轮、0.9°/帧）。
    ---数据源 /tmp/S5x_ecl11_c.txt（ECL …/data/ecl11_c.ecl）。骨架：
    ---  · Sub2：… + ins_141(5)（拍 5 张）+ ins_63(-128,-64) → t=100 ins_64(30,4,0,224)
    ---    落到 (0,224)（我们的 (0,0)）→ t=130 亮卡名 + ins_75(-160,96,160,256) + ins_149(0.9)
    ---    + ins_52(3)。
    ---  · Sub3：t=0 起 Sub4/Sub5 两条；t=40 的 ins_4(0,0) 跳回**自己** ⇒ 此后只是空转，
    ---    两条并行上下文从第一次起就一直跑。
    ---  · Sub4（@812，4 帧一轮）：extraFloatV2 = −π/2、floatV3 = +π/2；
    ---    ins_101(0, 0x8000 WAIT, 0, 190, …) + ins_101(1, 0x10 VEC, 0, 60, …)；
    ---    ins_38(extraFloatV0, extraFloatV1, extraFloatV2, 144) + ins_100 设 shootOffset；
    ---    intV0 = 3；三条 ins_87 FAN(型 3、色 13、count1=intV0、速 0、基角 floatV3、
    ---    步长 0.031733 rad)、三条用的 VEC 加速度依次 1/15、1/21.4、1/42.9；
    ---    收尾 extraFloatV2 += 3.6°、floatV3 += 1.8°、归一化，t=4 的 ins_4(0,-432)
    ---    跳回 **当前指令−432** = @852（那条 WAIT 记录）⇒ 每 4 帧重算一次发射点/角度。
    ---  · Sub5（@1328，**1 帧一轮**）：对称，extraFloatV2 = +π/2、floatV3 = −π/2、
    ---    WAIT 120、VEC 1/17.14、色 10、count1=2、步长 0.020944 rad；
    ---    extraFloatV2 += 0.9°、floatV3 += 1.5°，t=1 的 ins_4(0,-264) 跳回 @1368。
    ---★ 弹的 flags 0x8212 = FAST|VEC|SND|WAIT —— WAIT 在前、VEC 在后，记录表严格按顺序
    ---  逐条生效（见 sg_tr_hook 的说明）⇒ 悬停 → 加速。
    local BOSS_X, BOSS_START_Y = -128, field_y(-64)
    local HOME_X, HOME_Y = 0, field_y(224)              -- 0 / 0
    local ENTRY_WAIT, ENTRY_TIME = 100, 30
    local EASE_OUT = VALUE_SET.DECEL

    local PHOTO_LIMIT = 5                               -- ins_141(5)
    local CARD_NAME = "月＆木符「サテライトヒマワリ」"
    local CARD_TIME, CARD_HP = 50, 900
    local CARD_ID = 507
    local BOX = { -160, 96, 160, 256 }                  -- ins_75
    local OFF_R = 144                                   -- ins_38 的半径

    local A_WAIT, A_ACC = 190, 1 / 15                   -- Sub4
    local A_ACCS = { 1 / 15, 0.0466666669, 0.0233333334 }
    local A_SPIN, A_TILT = math.rad(3.6), math.rad(1.8)
    local A_STEP, A_GAP = math.deg(0.0317332596), 4
    local B_WAIT, B_ACC = 120, 1 / 17.14                -- Sub5
    local B_SPIN, B_TILT = math.rad(0.9), math.rad(1.5)
    local B_STEP, B_GAP = math.deg(0.0209439509), 1
    local FLAGS = 0x8212                                -- FAST|VEC|SND|WAIT

    local st = { dead = false }

    ---Sub4：两个发射点里「上面那一个」——每 4 帧一组 3×3 发悬停弹。
    local function sub4(owner)
        task.New(owner, function()
            local off, tilt = -math.pi / 2, math.pi / 2
            while not st.dead do
                local ox, oy = sg_off(OFF_R, off)
                for k = 1, #A_ACCS do
                    local hook = sg_tr_hook({
                        sg_rec(SG_WAIT, 0, A_WAIT, -1, -1, -1),
                        sg_rec(SG_VEC, 0, 60, -1, A_ACCS[k], -999.9),
                    }, FLAGS)
                    sg_shot(87, sg_style(3), ex_color(13), owner.x + ox, owner.y + oy,
                            3, 1, 0, 1.5, math.deg(tilt), A_STEP, false, FLAGS, hook)
                end
                ---ins_16(ef2, +3.6°) 是**减**（EclRunLow.inl:16 的 float -=）；
                ---off 是 TH095 弧度，这里照抄递减（原来写成递增 ⇒ 发射点反向绕圈）。
                off = off - A_SPIN
                tilt = tilt + A_TILT
                for _ = 1, A_GAP do
                    if st.dead then return end
                    task.Wait(1)
                end
            end
        end)
    end

    ---Sub5：下面那一个——每帧一组 2 发悬停弹。
    local function sub5(owner)
        task.New(owner, function()
            local off, tilt = math.pi / 2, -math.pi / 2
            while not st.dead do
                local ox, oy = sg_off(OFF_R, off)
                local hook = sg_tr_hook({
                    sg_rec(SG_WAIT, 0, B_WAIT, -1, -1, -1),
                    sg_rec(SG_VEC, 0, 60, -1, B_ACC, -999.9),
                }, FLAGS)
                sg_shot(87, sg_style(3), ex_color(10), owner.x + ox, owner.y + oy,
                        2, 1, 0, 1, math.deg(tilt), B_STEP, false, FLAGS, hook)
                off = off - B_SPIN                  -- ins_16(ef2, +0.9°)，同 Sub4
                tilt = tilt + B_TILT
                for _ = 1, B_GAP do
                    if st.dead then return end
                    task.Wait(1)
                end
            end
        end)
    end

    local card = boss.card.New(CARD_NAME, 1, 3, CARD_TIME, CARD_HP)

    function card:before()
    end

    function card:init()
        photo_damage_on(self, PHOTO_LIMIT)
        self.x, self.y = BOSS_X, BOSS_START_Y
        st.dead = false
        task.New(self, function()
            task.Wait(ENTRY_WAIT)
            task.MoveTo(HOME_X, HOME_Y, ENTRY_TIME, EASE_OUT)
            sub4(self)
            sub5(self)
        end)
    end

    function card:frame()
    end

    function card:del()
        st.dead = true
        photo_damage_off(self)
    end

    boss.card.add({ { card, "16a" } }, LEVEL, CARD_NAME, CARD_ID)
end--月＆木符「サテライトヒマワリ」

do  -- 46 彩華「虹色太極拳」（ecl10_d，红美铃，组 15a 第 4 张）
    ---原作是「彩虹太极拳」：本体停在 (0,224)（我们的 (0,0)），一条上下文每 4 帧甩出
    ---**一整圈 7 颗**不同颜色的弹（每颗从本体出发、沿自己方向以 ±4.5°/帧 盘旋着加速），
    ---整圈的相位每轮转 −(3.6° + 0.18°×拍中张数)，盘旋方向每 110 轮翻一次。
    ---数据源 /tmp/S5x_ecl10_d.txt（ECL …/data/ecl10_d.ecl）。骨架：
    ---  · Sub2：… + ins_141(7)（拍 **7** 张）+ ins_63(-128,-64) → t=100 ins_64(30,4,0,224)
    ---    落到 (0,224)（我们的 (0,0)）→ t=130 亮卡名 + ins_75(-160,32,160,416) + ins_52(3)。
    ---  · Sub3：t=0 起 Sub4/Sub5 两条；t=115 的 ins_4(0,-16) 跳回 **当前指令−16** = @764
    ---    （t=75 的 ins_144）⇒ 只在 75↔115 之间空转，两条上下文从第一次起一直跑。
    ---  · Sub4（@812）：floatV0 = playerAngle；extraIntV0 = 110；
    ---    ins_101(0, 0x20 POLAR, 0, 120, −1, 0.0015, +0.0785398 rad)（120 帧、速 +0.0015/帧、
    ---    角 +4.5°/帧）；t=0..3 共 7 条 ins_87 FAN(count1=1、速 2、基角 floatV0、
    ---    flags 0x222 = FAST|POLAR|SND)，两条 FAN 之间 ins_15(floatV0, +0.897597909 rad)；
    ---    收尾 floatV0 −= 0.0628319 rad、−= photoIndex×0.00314159、归一化；
    ---    t=4 的 ins_5(0,−528,extraIntV0) 跳回 **当前指令−528** = @892（第一条 FAN）——
    ---    7 条 FAN 的 t 是 0,1,1,2,2,3,3 ⇒ 一轮 4 帧；跑满 110 轮之后落到 t=4 的
    ---    ins_6(extraIntV0,110) + ins_101(POLAR 角增量 **取反** = −4.5°/帧) 再跑 110 轮，
    ---    最后 t=8 的 ins_4(0,−1224) 跳回 **当前指令−1224** = @832（extraIntV0=110）
    ---    ⇒ 外层每 880 帧换一次盘旋方向，floatV0 不重置（相位一直漂）。
    ---  · Sub5（@2100）是装饰 ANM（ins_56/54/51/66），不实现。
    local BOSS_X, BOSS_START_Y = -128, field_y(-64)
    local HOME_X, HOME_Y = 0, field_y(224)              -- 0 / 0
    local ENTRY_WAIT, ENTRY_TIME = 100, 30
    local EASE_OUT = VALUE_SET.DECEL

    local PHOTO_LIMIT = 7                               -- ins_141(7)
    local CARD_NAME = "彩華「虹色太極拳」"
    local CARD_TIME, CARD_HP = 50, 900
    local CARD_ID = 508
    local BOX = { -160, 32, 160, 416 }                  -- ins_75

    local COLORS = { 4, 6, 8, 10, 13, 14, 2 }           -- 7 条 FAN 的色号（原文顺序）
    local RING_STEP = math.deg(0.897597909)             -- 每颗 +51.43°
    local FAN_STEP = math.deg(0.1848)                   -- c1=1 ⇒ 不参与，照抄
    ---一轮 4 帧，7 发按 1/2/2/2 分到 t=0/1/2/3（raw ecl10_d 的 Sub4：`+1: //1` 压在
    ---ins_87(色 6) 前、`+1: //2` 压在 ins_87(色 10) 前、`+1: //3` 压在 ins_87(色 14) 前；
    ---`+1: //4` 那条 ins_5 再拨回 t=0 ⇒ 一轮正好 4 帧）。
    local SHOT_SHAPE = { 1, 2, 2, 2 }
    local ROUND_N = 110                                 -- 每种盘旋方向跑 110 轮
    local DRIFT, DRIFT_PER = math.deg(0.0628318563), math.deg(0.00314159272)  -- 3.6° + 0.18°/张
    local POLAR_FRAMES, POLAR_ACCEL = 120, 0.0015
    local POLAR_TURN = math.deg(0.0785398185)           -- 4.5°/帧
    local FLAGS = 0x222                                 -- FAST|POLAR|SND

    local st = { dead = false }

    ---Sub4：每 4 帧一整圈 7 色（7 发分 1/2/2/2 落在 4 帧里；整圈共享同一条 POLAR 记录，
    ---盘旋方向每 110 轮翻）。
    local function sub4(owner)
        task.New(owner, function()
            local fv = sg_aim(owner.x, owner.y)         -- floatV0 = playerAngle（TH095 度）
            local round = 0
            while not st.dead do
                local sign = (math.floor(round / ROUND_N) % 2 == 0) and 1 or -1
                local hook = sg_tr_hook({
                    sg_rec(SG_POLAR, 0, POLAR_FRAMES, -1, POLAR_ACCEL,
                            -sign * POLAR_TURN),
                }, SG_POLAR)
                local j = 0
                for fi = 1, #SHOT_SHAPE do
                    for _ = 1, SHOT_SHAPE[fi] do
                        if st.dead then return end
                        sg_shot(87, sg_style(5), ex_color(COLORS[j + 1]), owner.x, owner.y,
                                1, 1, 2, 1.5, fv + RING_STEP * j, FAN_STEP, false, FLAGS, hook)
                        j = j + 1
                    end
                    if st.dead then return end
                    task.Wait(1)
                end
                fv = sg_norm(fv - DRIFT - DRIFT_PER * photo_index(PHOTO_LIMIT))
                round = round + 1
            end
        end)
    end

    local card = boss.card.New(CARD_NAME, 1, 3, CARD_TIME, CARD_HP)

    function card:before()
    end

    function card:init()
        photo_damage_on(self, PHOTO_LIMIT)
        self.x, self.y = BOSS_X, BOSS_START_Y
        st.dead = false
        task.New(self, function()
            task.Wait(ENTRY_WAIT)
            task.MoveTo(HOME_X, HOME_Y, ENTRY_TIME, EASE_OUT)
            sub4(self)
        end)
    end

    function card:frame()
    end

    function card:del()
        st.dead = true
        photo_damage_off(self)
    end

    boss.card.add({ { card, "15a" } }, LEVEL, CARD_NAME, CARD_ID)
end--彩華「虹色太極拳」

do  -- 47 日＆月符「ロイヤルダイアモンドリング」（ecl11_d，帕秋莉，组 16a 第 4 张）
    ---原作是「钻石环」：本体停在 (0,128)（我们的 (0,96)），每 270 帧来三波 —— 每波生成
    ---**3 只子机**（彼此差 120°、离本体 0.5 px/帧地螺旋加速外飞），子机一面飞一面每 4 帧
    ---放一根**满长、朝自己当前朝向**的 147 激光（长 128、宽 16、60/10/40/10）和一颗
    ---**反方向**的小玉（这颗要在原地等 120 帧、再以 (0.1×拍中张数+1)/60 每帧加速 60 帧）。
    ---数据源 /tmp/S5x_ecl11_d.txt（ECL …/data/ecl11_d.ecl）。骨架：
    ---  · Sub2：… + ins_141(6)（拍 6 张）+ ins_63(-128,-64) → t=100 ins_64(30,4,0,128)
    ---    落到 (0,128)（我们的 (0,96)）→ t=130 亮卡名 + ins_75(-160,96,160,192) + ins_149(2)
    ---    + ins_52(3)。
    ---  · Sub3（270 帧一轮）：t=0 extraIntV1=60 + extraFloatV2 = π/2、floatV0 = 0.0314159
    ---    （1.8°，再 ins_17 取负）+ ins_117(0,4)（Sub4）；三波之前各来一次
    ---    ins_16(extraFloatV2, 6°)（**减**）、ins_17(floatV0, −1)（取反）再起 Sub4；
    ---    t=210 ins_67(60,4,2)；t=270 的 ins_4(0,-264) 跳回 **当前指令−264** = @784
    ---    （t=0 的 ins_16）⇒ 每 270 帧再来三波（起始方向每轮再 −18°，螺旋方向交替）。
    ---  · Sub4（@1080）：extraIntV0=3、extraFloatV3=0.5、floatV1=1/15、floatV2=extraFloatV2、
    ---    floatV3=floatV0、ins_83(5)（生成子机，子机继承这些 int/float 变量）、
    ---    extraFloatV2 += 2.0943952（120°）、归一化、ins_5(0,−132,extraIntV0) 跳回
    ---    **当前指令−132** = @1100 ⇒ 每轮 3 只、彼此差 120°。
    ---  · Sub5（子机上下文）：ins_54(2)+ins_80(8)、ins_65(extraFloatV2, extraFloatV3=0.5)
    ---    （朝 extraFloatV2、速 0.5）、ins_70(floatV0)（角速度）、ins_71(floatV1)（加速度）、
    ---    ins_117(0,6)（起发弹上下文）、t=200 ins_1（结束 ⇒ 子机寿命 200 帧）。
    ---  · Sub6（子机发弹）：ins_101(0, 0x8000 WAIT, 0, 120, …) + floatV0 = (0.1×拍中张数+1)/60
    ---    + ins_101(1, 0x10 VEC, 0, 60, −1, floatV0, −999.9) + ins_106(16)
    ---    + ins_147(型3、色13、movementAngle、128、16、60、10、40、10、0、follow=0)
    ---    + floatV2 = movementAngle + π + ins_87 FAN(型 1、色 13、count1=1、速 0.5、
    ---    基角 floatV2、flags 0x8212)；t=4 的 ins_4(0,−192) 跳回 **当前指令−192** = @1552
    ---    （那条 ins_106）⇒ 子机每 4 帧「一根激光 + 一颗反向弹」；records 只写一次。
    ---★ 子机在原作是真子敌机（ins_83，life=10）；本仓库按文件头差异 5 换成**有明确寿命
    ---  （200 帧）、自绘、淡出离场**的 object（class.diamond_child）。
    local BOSS_X, BOSS_START_Y = -128, field_y(-64)
    local HOME_X, HOME_Y = 0, field_y(128)              -- 0 / 96
    local ENTRY_WAIT, ENTRY_TIME = 100, 30
    local EASE_OUT = VALUE_SET.DECEL

    local PHOTO_LIMIT = 6                               -- ins_141(6)
    local CARD_NAME = "日＆月符「ロイヤルダイアモンドリング」"
    local CARD_TIME, CARD_HP = 50, 900
    local CARD_ID = 509
    local BOX = { -160, 96, 160, 192 }                  -- ins_75

    local CYCLE = 270                                   -- Sub3 一轮
    local CHILD_AT = { 0, 90, 180 }                     -- 三次 ins_117(0,4)
    local BMOVE_AT = 210                                -- ins_67(60,4,2) 的 t=210
    local CHILD_N = 3                                   -- extraIntV0
    local CHILD_SPACING = math.deg(2.09439516)          -- 每只 +120°（TH095）
    ---★ Sub3 t=0 的 ins_7(ef2, π/2) = 90°，此后**每个 `ins_16` 都是减 6°**（float -=，
    ---  见 EclRunLow.inl 的 case 16）⇒ 三波的起始方向是 84°/78°/72°（再往后每轮继续 −18°）。
    ---  （原来写成 96° + 每波 +6° ⇒ 方向和相位都反了。）
    local CHILD_DIR0 = math.deg(math.pi / 2)            -- 90°（TH095）
    local CHILD_DIR_STEP = math.deg(0.104719758)        -- 每轮 +6°
    local CHILD_TURN = math.deg(0.0314159282)           -- ±1.8°/帧（TH095）
    local CHILD_SPEED, CHILD_ACCEL = 0.5, 1 / 15        -- extraFloatV3 / floatV1
    local CHILD_LIFE = 200                              -- Sub5 的 t=200 ins_1
    local CHILD_R = 120                                 -- ins_67(60,4,2) 的 120 px
    local LASER_ROW = 13                                -- 原作 color 13（laser 贴图行 = color）
    local LASER_LEN, LASER_W = 128, 16
    local LASER_SEG = { 60, 10, 40, 10 }                -- startup/grow/sustain/fade
    local FIRE_GAP = 4                                  -- Sub6 的 ins_4(0,-192)
    local REV_WAIT, REV_FRAMES = 120, 60                -- 反向弹的 WAIT / VEC 帧数
    local REV_SPEED = 0.5                               -- FAN 的 sp1
    local REV_STEP = math.deg(0.1848)                   -- c1=1 ⇒ 不参与，照抄
    local FLAGS = 0x8212                                -- FAST|VEC|SND|WAIT

    local lasers = {}
    local st = { dead = false }
    local children = {}

    ---子机：一项自绘 object，按 extraFloatV2/floatV0/floatV1 做螺旋加速外飞，
    ---t=200 淡出离场；期间每 4 帧放一根 147 激光 + 一颗反向弹。
    class.diamond_child = Class(object, {
        init = function(self, owner, dir_th, turn, accel)
            self.group = GROUP.GHOST
            self.layer = LAYER.ENEMY_BULLET_EF
            self.colli = false
            self.bound = false
            self.x, self.y = owner.x, owner.y
            self.rot = 0
            self.dir = dir_th                                   -- TH095 弧度
            self.spd, self.turn, self.acc = CHILD_SPEED, turn, accel
            self._a = 0
            local hook = sg_tr_hook({
                sg_rec(SG_WAIT, 0, REV_WAIT, -1, -1, -1),
                sg_rec(SG_VEC, 0, REV_FRAMES, -1,
                        (0.1 * photo_index(PHOTO_LIMIT) + 1) / 60, -999.9),
            }, FLAGS)
            task.New(self, function()
                for f = 1, CHILD_LIFE do
                    if st.dead then break end
                    ---Sub5 的 ins_65/70/71：极坐标运动。
                    self.dir = self.dir + self.turn
                    self.spd = self.spd + self.acc
                    ---self.dir 是 TH095 的**弧度**，这里必须用 math.cos/math.sin
                    ---（本文件全局的 cos/sin 是引擎的角度制版本，见 Lapi.lua:110）。
                    self.x = self.x + self.spd * math.cos(self.dir)
                    self.y = self.y - self.spd * math.sin(self.dir)
                    self.rot = -math.deg(self.dir) + 90
                    ---Sub6：满长 147 激光 + 一颗反方向小玉（每 4 帧，第 0 帧就放）。
                    if (f - 1) % FIRE_GAP == 0 then
                        local a = -math.deg(self.dir)               -- 我们的度
                        spawn_ex_laser(self, lasers, LASER_ROW, self.x, self.y, a,
                                LASER_LEN, LASER_W, 8, LASER_SEG[1], LASER_SEG[2],
                                LASER_SEG[3], LASER_SEG[4], 0, 0, 0, false, true)
                        sg_shot(87, sg_style(1), ex_color(13), self.x, self.y,
                                1, 1, REV_SPEED, 1.5, sg_norm(math.deg(self.dir) + 180),
                                REV_STEP, false, FLAGS, hook)
                    end
                    ---最后 12 帧淡出（文件头差异 5 的窗口）。
                    self._a = (f > CHILD_LIFE - 12)
                            and max(0, 200 * (CHILD_LIFE - f) / 12) or 200
                    task.Wait(1)
                end
                if IsValid(self) then
                    object.RawDel(self)
                end
            end)
        end,
        frame = function(self)
            task.Do(self)                                  -- ★ 驱动极坐标飞行 + 一路发激光/小玉
        end,
        render = function(self)
            SetImageState("ball_mid13", "mul+add", self._a, 210, 170, 250)
            Render("ball_mid13", self.x, self.y, self.rot, 0.6, 0.6)
        end,
    })

    ---Sub4：一次生成 3 只子机（彼此差 120°）。
    local function spawn_children(owner, dir, turn)
        for _ = 1, CHILD_N do
            if st.dead then return end
            children[#children + 1] = New(class.diamond_child, owner, dir, turn, CHILD_ACCEL)
            dir = dir + math.rad(CHILD_SPACING)
        end
    end

    ---Sub3：270 帧一轮、每轮三波（t=0/90/180），起始方向每轮 +6°、螺旋方向交替。
    local function sub3(owner)
        task.New(owner, function()
            local dir, turn = math.rad(CHILD_DIR0), math.rad(CHILD_TURN)
            while not st.dead do
                for wave = 1, #CHILD_AT do
                    if st.dead then return end
                    dir = dir - math.rad(CHILD_DIR_STEP)
                    turn = -turn
                    spawn_children(owner, dir, turn)
                    local gap = (CHILD_AT[wave + 1] or BMOVE_AT) - CHILD_AT[wave]
                    for _ = 1, gap do
                        if st.dead then return end
                        task.Wait(1)
                    end
                end
                ---t=210 的 ins_67(60,4,2)：60 帧、120 px 的随机挪位。
                sg_bmove(owner, st, 60, 4, 2, BOX)
                for _ = 1, CYCLE - BMOVE_AT do
                    if st.dead then return end
                    task.Wait(1)
                end
            end
        end)
    end

    local card = boss.card.New(CARD_NAME, 1, 3, CARD_TIME, CARD_HP)

    function card:before()
        children = {}
    end

    function card:init()
        photo_damage_on(self, PHOTO_LIMIT)
        self.x, self.y = BOSS_X, BOSS_START_Y
        st.dead = false
        task.New(self, function()
            task.Wait(ENTRY_WAIT)
            task.MoveTo(HOME_X, HOME_Y, ENTRY_TIME, EASE_OUT)
            sub3(self)
        end)
    end

    function card:frame()
    end

    function card:del()
        st.dead = true
        photo_damage_off(self)
        for i = #children, 1, -1 do
            if IsValid(children[i]) then
                task.Clear(children[i])
                object.RawDel(children[i])
            end
        end
        children = {}
        sg_clear(lasers)
    end

    boss.card.add({ { card, "16a" } }, LEVEL, CARD_NAME, CARD_ID)
end--日＆月符「ロイヤルダイアモンドリング」

end  -- Stage 5

---──────────────────── Stage 4（scene group 3 = world04）── 公共工具 / 九张卡 ────────────────────
---原作 scene group 3 是 world04（メディスン·メランコリー / 铃仙·优昙华院·因幡 / 因幡帝）。
---SceneSelect.cpp:100-109 的 TH095_SCENE 表里 scene 30..38 共九幕：
---  30 ecl7_a メディスン 非符（不亮卡名）      31 ecl9_a 铃仙 霧符「ガシングガーデン」
---  32 ecl8_a 帝   脱兎「フラスターエスケープ」 33 ecl7_b メディスン 散符「朧月花栞（ロケット・イン・ミスト）」
---  34 ecl9_b 铃仙 毒符「ポイズンブレス」      35 ecl7_c メディスン 波符「幻の月（インビジブルハーフムーン）」
---  36 ecl9_c 铃仙 譫妄「イントゥデリリウム」  37 ecl8_b 帝   借符「大穴牟遅様の薬」
---  38 ecl7_d メディスン 狂夢「風狂の夢（ドリームワールド）」
---按「一个角色一个组」拆：组 17 = メディスン（30/33/35/38，第 1 张是非符）、
---组 18 = 铃仙（31/34/36）、组 19 = 帝（32/37）。★ 别把两人塞进同一个组的 a/b。
---原作整组 BGM 是 bgm/th095_02.wav ——**本仓库没有这首**（music.lua 里 th095 系只有
---TH07_1 = th095_04、TH09_5_1 = th095_03），整组沿用 "TH09_5_1"（与 Stage EX / Stage 5 同一首），
---背景沿用 TH095_bg；world04.std 的贴图本仓库也没有，三套符卡背景照 Stage 5 的做法拿
---th06/th07/th08/th10 的通用贴图重新配色（见上面 class.scbg17/18/19）。
---数据源 /tmp/S4x_ecl{7,8,9}_{a..d}.txt（脚本 /tmp/s4dump.py 不入库；ECL 在
---`[th095] …/data/ecl{7,8,9}_{a..d}.ecl`），各卡注释里的「@地址」都指这几份 dump。
---
---这一组九幕共用同一套外壳（Sub2）：ins_55(2)+ins_81(3)+ins_109(0)+ins_77(24,24)
---+ins_141(N)（拍 N 张）+ins_108(0,31)/ins_108(1,30)（子机槽）+ins_143(1,130)
---+ins_63(-128,-64) 进场 → t=100 的 ins_64(30,4,0,Y) 用 30 帧从场地左上角外落到中轴
---（我们的 (0, field_y(Y))）→ t=130 亮卡名（ecl7_a 是 id=0，**非符不亮**）+ ins_75(box)
---+ ins_149(倍率) + ins_52(3) 起主脚本。Sub0/Sub1 是死亡/退场，不实现；ins_114（卡计时）
---也不实现，卡时限沿用本仓库惯例 CARD_TIME = 50、CARD_HP = 900。
---★ ins_84 的子敌机（ecl9_a/b/c 的 Sub4）在 world04 里**只飞不发弹**（它们自己的子程序
---  Sub6 只有 ins_54/ins_151/ins_112/ins_119/ins_65 的移动 + 到点自灭），所以按文件头
---  差异 5 不实现，弹幕部分不受影响（各卡注释里写明）。
---★ 循环的「周期」不总是 ins_4 的字节偏移：ins_4(time, offset) 把 **time 置成 operand0**、
---  跳到指令地址 + offset。所以周期 = 上一帧的 time 值（不是 offset）；offset 只是字节数。
---  跳转目标是 t≠0 时，context 的 time 被置 0，要等 time 涨到那个 t 才执行 ⇒ 有段空转。
---★ ins_2(n) 是「冻结」：`secondaryTime>0` 时 RunEcl 每帧先 `secondaryTime--` 再 `time--`，
---  叠加帧尾的 `time++` ⇒ 时间轴原地不动，等于多等 n 帧（n ≤ 0 不生效）。
do

---TH095 的极坐标偏移 (半径 r, 弧度 θ) → 我们的相对位移：x 同号、y 取反
---（我们的 y = 224 − TH095 的 y）。ins_38(dx,dy,θ,r) + ins_100(dx,dy) 的 shootOffset 用。
local function sg_off(r, th_rad)
    return r * math.cos(th_rad), -r * math.sin(th_rad)
end

---TH095 的 AddNormalizeAngle：把**度**折进 [−180,180]（原作折进 [−π,π]）。
local function sg_norm(a)
    a = a % 360
    if a > 180 then a = a - 360 end
    return a
end

---一帧一帧地把本体挪到 (tx,ty)（线性缓动），**每帧**夹进 ins_75 的活动框 ——
---对应原作 INTERPOLATED 移动 + 同帧 ClampPosition 的组合。
---box = { x0, y0, x1, y1 }（TH095 坐标，y0 < y1）。
local function sg_move_clamped(owner, box, st, tok, tx, ty, n)
    local x0, y0 = owner.x, owner.y
    for s = 1, n do
        if not tok.alive or st.dead then return end
        local p = s / n
        owner.x = max(box[1], min(box[3], x0 + p * (tx - x0)))
        owner.y = max(field_y(box[4]), min(field_y(box[2]), y0 + p * (ty - y0)))
        task.Wait(1)
    end
end

---ins_118(2)/(4) 的回调（EclExtended.cpp:941 的 Callback02 / :1018 的 Callback04）：
---遍历场上所有敌弹，把 ownerTag == tag 的那一批重设速度与角度。
---  mode 2 = Callback02：新角 = angle（**绝对角**）；速率 = speed。
---  mode 4 = Callback04：新角 = angle + 弹当前角（**相对角**）；speed ≤ −999 时保持原速。
---angle 与 speed 都换算成**我们的口径**（度、逆时针为正；见文件头「坐标系与角度」）。
---原作这两个回调还会把弹的贴图转向关掉（REINITIALIZE_SHIFTED）并把
---captureDisabled 置 1（本仓库的相机是独立系统，没有这两个概念，不实现）。
local function sg_callback(mode, tag, angle, speed)
    object.BulletDo(function(b)
        if b.sg_tag ~= tag then return end
        local spd, ang
        if mode == 2 then
            spd, ang = speed, angle
        else
            spd = (speed > -999) and speed or GetV(b)
            ang = angle + b.rot
        end
        object.SetV(b, spd, ang, true)
    end)
end

do  -- 30 メディスン 非符（ecl7_a，组 17a 第 1 张）
    ---原作这一幕**不亮卡名**（Sub2 的 t=130 是 id=0 —— opcode 0 在 EclRunLow.inl 的
    ---switch 里没有分支 ⇒ NOP）：本体落到中轴后不动，每 135 帧（第二遍起再额外等
    ---70−10×拍中张数 帧）重开一轮「同心环」——一轮 10 圈，每圈间隔 8 帧、弹数从 64 起
    ---每圈 −5、速度从 0.5 起每圈 +0.33（型 8 = 中玉，色号 2/4 交替）。
    ---数据源 /tmp/S4x_ecl7_a.txt（ECL …/data/ecl7_a.ecl）。骨架：
    ---  · Sub2：… ins_141(4)（拍 4 张）+ ins_63(-128,-64) → t=100 ins_64(30,4,0,128)
    ---    落到 (0,128)（我们的 (0,96)）→ t=130 的 id=0（NOP，非符）+ ins_75(-160,96,160,192)
    ---    + ins_149(2.5) + ins_52(3) 起 Sub3。
    ---  · Sub3（@668，135 + 冻结 帧一轮）：t=0 的 ins_6(extraIntV1,60) 与 @688 的
    ---    ins_4(0,+196) —— 第一次进 Sub3 时 ins_4 直接跳到 @884（跳过 @708..@868 的初始段）；
    ---    @884 t=15 的 ins_117(0,4) 起 Sub4；t=75 的 ins_67(60,4,2) 在框里随机挪 120 px；
    ---    t=135 的 ins_4(0,−272) 跳回 **@708** ⇒ 从第二遍起才跑 @708..@772：
    ---    ins_144（快门脉冲，装饰）+ extraIntV0 = 70 − 10×拍中张数 + ins_2(extraIntV0)（冻结）。
    ---    跳转基准是**当前指令**：@980−272 = @708、@688+196 = @884。
    ---  · Sub4（@1012，8 帧一轮、共 5 轮 = 10 圈）：extraIntV0=5、intV0=64、floatV1=0.5、
    ---    floatV0=rand(−π,π)（基准角，整段固定）；每轮两圈 —— t=0 的 CIRCLE(型 8/色 2，
    ---    c1=intV0、速 floatV1)、t=8 的 CIRCLE(型 8/色 4)。两圈之后 floatV1 += 0.33、
    ---    intV0 −= 5（顺序是**先发弹、再改参数**）。t=16 的 ins_5(0,−180,extraIntV0)
    ---    先自减、>0 就跳回 @1092。⇒ 10 圈的（弹数, 速度）= (64,0.5)(59,0.83)(54,1.16)
    ---    (49,1.49)(44,1.82)(39,2.15)(34,2.48)(29,2.81)(24,3.14)(19,3.47)，共 415 发；
    ---    圈与圈之间严格 8 帧（ins_5 与下一次 t=0 是同一帧）。
    ---  · flags 0x202 = FAST|SND（型 8 的出场动画按本仓库惯例不实现，只影响弹的贴图演出）。
    local BOSS_X, BOSS_START_Y = -128, field_y(-64)
    local HOME_X, HOME_Y = 0, field_y(128)
    local ENTRY_WAIT, ENTRY_TIME = 100, 30
    local EASE_OUT = VALUE_SET.DECEL

    local PHOTO_LIMIT = 4                               -- ins_141(4)
    local CARD_NAME = ""                                -- 非符：原作 t=130 是 id=0
    local CARD_TIME, CARD_HP = 50, 900
    local CARD_ID = 510
    local BOX = { -160, 96, 160, 192 }                  -- ins_75（TH095 空间）
    local RING0, RING_STEP = 64, 5                      -- Sub4 首圈弹数 / 每圈递减
    local SPD0, SPD_STEP = 0.5, 0.33                    -- Sub4 首圈速度 / 每圈递增
    local RINGS, RING_GAP = 10, 8                       -- 共 10 圈、圈间隔 8 帧
    local FREEZE0, FREEZE_STEP = 70, 10                 -- ins_2: 70 − 10×拍中张数

    local st = { dead = false }

    ---Sub4（@1012）：10 圈同心环，先发弹再改参数。
    local function sub4(owner)
        task.New(owner, function()
            local base = math.deg(ran:Float(-math.pi, math.pi))
            local n, sp = RING0, SPD0
            for i = 1, RINGS do
                if st.dead then return end
                sg_shot(89, sg_style(8), ex_color((i % 2 == 1) and 2 or 4),
                        owner.x, owner.y, n, 1, sp, 1, base, 0, false, 0x202)
                n = n - RING_STEP
                sp = sp + SPD_STEP
                if i < RINGS then
                    for _ = 1, RING_GAP do
                        if st.dead then return end
                        task.Wait(1)
                    end
                end
            end
        end)
    end

    ---Sub3（@668）：135 帧一轮（第二遍起先冻结 70−10×h 帧）。
    local function sub3(owner)
        task.New(owner, function()
            local t = 0
            local function goto_t(target)
                while t < target do
                    if st.dead then return false end
                    task.Wait(1)
                    t = t + 1
                end
                return true
            end
            local function freeze(n)
                for _ = 1, n do
                    if st.dead then return false end
                    task.Wait(1)
                end
                return true
            end
            --- 第一次：@688 的 ins_4(15, Sub3_216) 把 time 置成 15 后同帧跳过去 ——
            --- 目标 ins_117 的 time 字段正是 15（EclRun.cpp:293 的 time == instruction->time
            --- 在同一次 redispatch 里立刻成立）⇒ 不等待，Sub4 在 Sub3 的第 0 帧就起。
            t = 15
            sub4(owner)
            if not goto_t(75) then return end
            sg_bmove(owner, st, 60, 4, 2, BOX)
            if not goto_t(135) then return end
            while not st.dead do
                --- ins_4(0,−272)：time 置 0、跳回 @708（@708..@772 的冻结段每轮都跑）
                t = 0
                local d = FREEZE0 - FREEZE_STEP * photo_index(PHOTO_LIMIT)
                if d > 0 and not freeze(d) then return end
                if not goto_t(15) then return end
                sub4(owner)
                if not goto_t(75) then return end
                sg_bmove(owner, st, 60, 4, 2, BOX)
                if not goto_t(135) then return end
            end
        end)
    end

    local card = boss.card.New(CARD_NAME, 1, 3, CARD_TIME, CARD_HP)

    function card:before()
    end

    function card:init()
        photo_damage_on(self, PHOTO_LIMIT)
        self.x, self.y = BOSS_X, BOSS_START_Y
        st.dead = false
        task.New(self, function()
            task.Wait(ENTRY_WAIT)
            task.MoveTo(HOME_X, HOME_Y, ENTRY_TIME, EASE_OUT)
            sub3(self)
        end)
    end

    function card:frame()
    end

    function card:del()
        st.dead = true
        photo_damage_off(self)
    end

    boss.card.add({ { card, "17a" } }, LEVEL, CARD_NAME, CARD_ID)
end--メディスン 非符（ecl7_a）

do  -- 31 霧符「ガシングガーデン」（ecl9_a，铃仙，组 18a 第 1 张）
    ---原作是「喷涌的花园」：本体在框里每 135 帧随机挪 120 px，一条上下文每 4 帧甩
    ---「两发 ×2 + 两发 ×1」的随机弹（速度 0.8~1.8；拍中 4 张后换成 1.5~2.5），
    ---另一条上下文每 135 帧在自机周围 60 px 处按自机方向 ±45° 放出 3 只**只飞不发弹**的
    ---子敌机（装饰，见段首注）。
    ---数据源 /tmp/S4x_ecl9_a.txt（ECL …/data/ecl9_a.ecl）。骨架：
    ---  · Sub2：… ins_141(6)（拍 6 张）+ ins_63(-128,-64) → t=100 ins_64(30,4,0,128)
    ---    → t=130 亮卡名 + ins_75(-160,96,160,192) + ins_149(1.6) + ins_52(3)。
    ---  · Sub3（@728，135 帧一轮）：t=0 起 slot0 的 Sub4 + slot1 的 Sub5；t=30 的 ins_144
    ---    （装饰）；t=75 的 ins_67(60,4,2) 挪 120 px；t=135 的 ins_4(0,−80) 跳回 **@748**
    ---    （= 那对 ins_117）⇒ 两条子上下文每轮都重开。
    ---  · Sub4（@860，一帧跑完）：floatV0 = playerAngle；三次
    ---    「ins_38(…,60) 算极坐标偏移 + ins_84(6,dx,dy) 在偏移处生成子敌机」，
    ---    角度依次 playerAngle → ins_16(−45°) → ins_15(+45°)（ins_16 是**减**）。
    ---  · Sub5（@1100，4 帧一轮）：先看拍中张数 —— 少于 4 张用 floatV0/floatV1 = 1.8/0.8，
    ---    否则 2.5/1.5；t=0/1/2/3 四发 ins_94 RANDOM：前三条各 2 发、第四条 1 发，
    ---    型 3 = 小玉，色 4/13/11/10，速 rand[floatV1,floatV0]、角 rand(−π,π)；
    ---    t=4 的 ins_4(0,−304) 跳回 @1120 ⇒ **每帧一发**（4 帧里 2+2+2+1 = 7 发）。
    ---  · 0x202 = FAST|SND。
    local BOSS_X, BOSS_START_Y = -128, field_y(-64)
    local HOME_X, HOME_Y = 0, field_y(128)
    local ENTRY_WAIT, ENTRY_TIME = 100, 30
    local EASE_OUT = VALUE_SET.DECEL

    local PHOTO_LIMIT = 6                               -- ins_141(6)
    local CARD_NAME = "霧符「ガシングガーデン」"
    local CARD_TIME, CARD_HP = 50, 900
    local CARD_ID = 514
    local BOX = { -160, 96, 160, 192 }                  -- ins_75
    local SP_FAR, SP_NEAR = 2.5, 1.5                     -- 拍中 ≥4 张
    local SP_FAR0, SP_NEAR0 = 1.8, 0.8                   -- 拍中 <4 张
    local SPRAY = { 2, 2, 2, 1 }                        -- t=0/1/2/3 四发的弹数
    local SPRAY_COLOR = { 4, 13, 11, 10 }               -- 四发的色号
    local SPRAY_TURN = 4                                -- ins_44 的阈值（photoIndex < 4）

    local st = { dead = false }
    local tok5 = nil

    ---Sub5（@1100）：每 4 帧的随机弹（见上）。
    local function sub5(owner)
        local tok = { alive = true }
        task.New(owner, function()
            while tok.alive and not st.dead do
                local lo, hi = SP_FAR0, SP_NEAR0
                if photo_index(PHOTO_LIMIT) >= SPRAY_TURN then
                    lo, hi = SP_FAR, SP_NEAR
                end
                for i = 1, 4 do
                    if not tok.alive or st.dead then return end
                    sg_shot(94, sg_style(3), ex_color(SPRAY_COLOR[i]),
                            owner.x, owner.y, SPRAY[i], 1, hi, lo, 180, -180, false, 0x202)
                    if i < 4 then
                        task.Wait(1)
                    end
                end
                if not tok.alive or st.dead then return end
                task.Wait(1)
            end
        end)
        return tok
    end

    ---Sub3（@728）：135 帧一轮，每轮重开 slot0/Sub4 与 slot1/Sub5。
    local function sub3(owner)
        task.New(owner, function()
            local t = 0
            local function goto_t(target)
                while t < target do
                    if st.dead then return false end
                    task.Wait(1)
                    t = t + 1
                end
                return true
            end
            while not st.dead do
                if tok5 then tok5.alive = false end
                tok5 = sub5(owner)                          -- ins_117(1,5)：固定槽位，先掐掉上一条
                --- ins_117(0,4) 的 Sub4 只放装饰子敌机（不发弹），不实现
                if not goto_t(75) then return end
                sg_bmove(owner, st, 60, 4, 2, BOX)
                if not goto_t(135) then return end
                --- ins_4(0,−80)：time 置 0、跳回 @748（那对 ins_117）
                t = 0
            end
        end)
    end

    local card = boss.card.New(CARD_NAME, 1, 3, CARD_TIME, CARD_HP)

    function card:before()
    end

    function card:init()
        photo_damage_on(self, PHOTO_LIMIT)
        self.x, self.y = BOSS_X, BOSS_START_Y
        st.dead = false
        tok5 = nil
        task.New(self, function()
            task.Wait(ENTRY_WAIT)
            task.MoveTo(HOME_X, HOME_Y, ENTRY_TIME, EASE_OUT)
            sub3(self)
        end)
    end

    function card:frame()
    end

    function card:del()
        st.dead = true
        if tok5 then tok5.alive = false end
        photo_damage_off(self)
    end

    boss.card.add({ { card, "18a" } }, LEVEL, CARD_NAME, CARD_ID)
end--霧符「ガシングガーデン」

do  -- 32 脱兎「フラスターエスケープ」（ecl8_a，帝，组 19a 第 1 张）
    ---原作是「flare escape」：本体在框里每 150 帧挪 120 px，一条上下文**每 2 帧**朝自机方向
    ---甩一扇小玉（弹数 2×拍中张数+6，速 3→1.5，扇宽 25.7°）。每颗弹挂两条记录：
    ---「4 次反弹」（BOUNCE_NOBOT，allow 0，只反射左/右/上三面）和
    ---「6000 帧的 ±0.9°/帧 自转」（POLAR，allow **1**）——第一条在出生帧认领、
    ---第二条**下一帧**跟着认领（allow 1 不与前一条互斥），所以弹从出生第 2 帧起
    ---**一边反弹一边拐弯**（sg_tr_hook 的 acts 表同时跑这两条）。
    ---自转方向**每轮按本体当前 x 的符号现选**：x ≥ 0 走 −0.015708 rad/帧 那一支。
    ---数据源 /tmp/S4x_ecl8_a.txt（ECL …/data/ecl8_a.ecl）。骨架：
    ---  · Sub2：… ins_141(5)（拍 5 张）+ ins_63(-128,-64) → t=100 ins_64(30,4,0,128)
    ---    → t=130 亮卡名 + ins_75(-160,96,160,192) + ins_149(0.7) + ins_52(3)。
    ---  · Sub3（@716，150 帧一轮）：t=0 起 Sub4；t=90 的 ins_67(60,4,2) 挪 120 px；
    ---    t=150 的 ins_4(0,−60) 跳回 @736（Sub4 的 ins_117）。
    ---  · Sub4（@828）：extraIntV0=40（轮数）、extraIntV1 = 2×拍中张数 + 6（每轮弹数）、
    ---    floatV0 = playerAngle（整段固定）；@912 的 ins_51(world.x, 0, 0, 172) ——
    ---    ins_51 是**浮点 ≥** 条件跳转（CompareOperands），world.x ≥ 0 时跳到 @1084 的
    ---    镜像组（POLAR 反向），否则往下走 @940 的正向组；两组最后都落到 @1208 的
    ---    ins_5(0,−296,extraIntV0) ⇒ 每 2 帧一扇、共 40 扇。
    ---  · 每轮先写 slot0 = BOUNCE_NOBOT(4 次)、slot1 = POLAR(6000 帧, ±0.015708 rad)，
    ---    然后 FAN(型 3 = 小玉、色 2、扇宽 0.448798954 rad、flags 0x1000C44 =
    ---    FAST|POLAR|SND|BOUNCE_NOBOT)。
    local BOSS_X, BOSS_START_Y = -128, field_y(-64)
    local HOME_X, HOME_Y = 0, field_y(128)
    local ENTRY_WAIT, ENTRY_TIME = 100, 30
    local EASE_OUT = VALUE_SET.DECEL

    local PHOTO_LIMIT = 5                               -- ins_141(5)
    local CARD_NAME = "脱兎「フラスターエスケープ」"
    local CARD_TIME, CARD_HP = 50, 900
    local CARD_ID = 517
    local BOX = { -160, 96, 160, 192 }                  -- ins_75
    local ROUNDS = 40                                   -- extraIntV0
    local FAN_BASE_COUNT, FAN_COUNT_STEP = 6, 2         -- 2×拍中张数 + 6
    local FAN_SPEED1, FAN_SPEED2 = 3, 1.5
    local FAN_STEP = math.deg(0.448798954)              -- 25.71°
    local TURN = 0.0157079641                           -- ±0.9°/帧（rad）
    local BOUNCES = 4
    local FLAGS = 0xA22                                 -- FAST|POLAR|SND|BOUNCE_NOBOT

    local st = { dead = false }

    ---Sub4（@828）：每 2 帧一扇，自转方向按 world.x 的符号现选。
    local function sub4(owner)
        task.New(owner, function()
            local count = FAN_COUNT_STEP * photo_index(PHOTO_LIMIT) + FAN_BASE_COUNT
            local base = sg_aim(owner.x, owner.y)       -- floatV0 = playerAngle（TH095 度）
            for _ = 1, ROUNDS do
                if st.dead then return end
                local d = TURN
                if owner.x >= 0 then d = -TURN end
                local hook = sg_tr_hook({
                    sg_rec(SG_BOUNCE_EB, 0, BOUNCES, -1, -999, 0),
                    ---@ecs ins_101(1, 32, 1, 6000, -1, 0.0f, ±0.015707964f)：POLAR 的
                    ---allowWhileActive = **1**（操作数 3）⇒ 它在 BOUNCE 认领后的下一帧
                    ---就和反弹**同时**生效（BulletManager.cpp:523 的判据）。
                    sg_rec(SG_POLAR, 1, 6000, -1, 0, sg_deg(d)),
                }, FLAGS)
                sg_shot(87, sg_style(3), ex_color(2), owner.x, owner.y,
                        count, 1, FAN_SPEED1, FAN_SPEED2, base, FAN_STEP,
                        false, FLAGS, hook)
                for _ = 1, 2 do
                    if st.dead then return end
                    task.Wait(1)
                end
            end
        end)
    end

    ---Sub3（@716）：150 帧一轮。
    local function sub3(owner)
        task.New(owner, function()
            local t = 0
            local function goto_t(target)
                while t < target do
                    if st.dead then return false end
                    task.Wait(1)
                    t = t + 1
                end
                return true
            end
            while not st.dead do
                sub4(owner)
                if not goto_t(90) then return end
                sg_bmove(owner, st, 60, 4, 2, BOX)
                if not goto_t(150) then return end
                --- ins_4(0,−60)：time 置 0、跳回 @736（Sub4 的 ins_117）
                t = 0
            end
        end)
    end

    local card = boss.card.New(CARD_NAME, 1, 3, CARD_TIME, CARD_HP)

    function card:before()
    end

    function card:init()
        photo_damage_on(self, PHOTO_LIMIT)
        self.x, self.y = BOSS_X, BOSS_START_Y
        st.dead = false
        task.New(self, function()
            task.Wait(ENTRY_WAIT)
            task.MoveTo(HOME_X, HOME_Y, ENTRY_TIME, EASE_OUT)
            sub3(self)
        end)
    end

    function card:frame()
    end

    function card:del()
        st.dead = true
        photo_damage_off(self)
    end

    boss.card.add({ { card, "19a" } }, LEVEL, CARD_NAME, CARD_ID)
end--脱兎「フラスターエスケープ」

do  -- 33 散符「朧月花栞（ロケット・イン・ミスト）」（ecl7_b，メディスン，组 17a 第 2 张）
    ---原作是「雾中的月光花栞」：本体在框里每 175 帧挪 120 px；一条上下文每 4 帧从
    ---**5 个出膛偏移**各甩一圈 4 发中玉（ownerTag 0..3 连续轮转），到 t=115 把场上
    ---这批弹**按 tag 重新瞄准**成四个正交方向（自机角 + k·90°、速率 1）；
    ---拍中第 4 张后整段换成更短的密版（135 帧一轮、进密版时先清屏）。
    ---数据源 /tmp/S4x_ecl7_b.txt（ECL …/data/ecl7_b.ecl）。骨架：
    ---  · Sub2：… ins_141(6)（拍 6 张）+ ins_115(0,4,8)（**拍中第 4 张**时把主上下文整个
    ---    换成 Sub8；EclRunTargetHigh.inl:190 的排程每帧拿 operand1 与 camera.photoIndex
    ---    比大小、命中后把这条排程清掉 ⇒ 只会触发一次）+ ins_63(-128,-64) 进场 → t=100
    ---    ins_64(30,4,0,128) 落到 (0,128)＝我们的 (0,96) → t=130 亮卡名 +
    ---    ins_75(-160,96,160,192) + ins_149(0.4) + ins_52(3)。
    ---  · Sub3（@756，**175 帧**一轮）：t=0 的 ins_117(0,4) 起 Sub4、@796 的
    ---    floatV0 = playerAngle（本上下文自己的）；t=100 装饰；t=115 的 ins_67(60,4,2)
    ---    挪 120 px + ins_117(0,-1) 收掉 Sub4 + 四组「sharedInt0=k、sharedFloat0=floatV0、
    ---    sharedFloat1=1、ins_52(5)」，每组之后 floatV0 += π/2 并归一化（ins_15/ins_37）；
    ---    t=145 装饰；t=175 的 ins_52(7)（一声 + 回调 3）+ ins_4(0,−580) 跳回 **@776**：
    ---    time 被置 0、跳 580 **字节**，周期是 ins_4 的 t = 175，不是 offset。
    ---  · Sub4（@1388，4 帧一轮）：@1388 的 floatV0 = playerAngle 只在**起 Sub4 那一帧**跑
    ---    （循环是 @2128 的 ins_4 跳回 @1408）；5 个出膛偏移
    ---    (0,0) (32,0) (−32,0) (0,32) (0,−32)，每条「ins_101(0, TAG, 0, intV0) +
    ---    CIRCLE(型 8/色 2、4 发、速 4)」之后 intV0 = (intV0+1) % 4（ins_10/ins_14）
    ---    ⇒ tag 0,1,2,3,0,1,… 跨轮连续轮转。
    ---  · Sub5（@2160）：ins_106(16) + extraIntV2/extraFloatV2/extraFloatV3 ←
    ---    callInt0/callFloat0/callFloat1 + ins_118(2) = Callback02（EclExtended.cpp:941）
    ---    —— 把场上 ownerTag == extraIntV2 的弹设成 extraFloatV2/extraFloatV3（绝对角/速率）。
    ---    ins_52 会把 eclManager 的共享块拷进被调上下文的 call*（EclDependencies.cpp:315），
    ---    而那块共享块与 ECL 的 sharedInt/sharedFloat 是**同一地址**（EclOperandsInt.cpp:17
    ---    的 EclSharedOperandView = unknown[0x168] + int[4] + float[4]，与
    ---    PhotoEnemyEclManagerView 的 callParameters 同形）⇒ 四组 shared 依次被读成
    ---    「tag k 重瞄到 floatV0_k、速率 1」。本节用 sg_callback(2, …) 复刻。
    ---  · Sub8（@2440）：进密版那一帧先 ins_118(3)，t=30 才 ins_102 清屏 + 起 Sub4 +
    ---    重新取自机角；之后与 Sub3 同构但整体 +30 帧、t=105 重瞄、t=135 装饰、
    ---    t=165 回调 3 + ins_4(30,−580) 跳回 @2488 ⇒ **135 帧**一轮。
    ---  · Sub6/Sub7 是装饰 ANM / 一声 + 回调 3；回调 3 = 按当前角速重设 + 恢复可捕获，
    ---    本仓库没有捕获概念，是空操作。
    local BOSS_X, BOSS_START_Y = -128, field_y(-64)
    local HOME_X, HOME_Y = 0, field_y(128)
    local ENTRY_WAIT, ENTRY_TIME = 100, 30
    local EASE_OUT = VALUE_SET.DECEL

    local PHOTO_LIMIT = 6                               -- ins_141(6)
    local SWITCH_AT = 4                                 -- ins_115(0,4,8) 的 operand1
    local CARD_NAME = "散符「朧月花栞（ロケット・イン・ミスト）」"
    local CARD_TIME, CARD_HP = 50, 900
    local CARD_ID = 511
    local BOX = { -160, 96, 160, 192 }                  -- ins_75（TH095 空间）
    local OFFSETS = { { 0, 0 }, { 32, 0 }, { -32, 0 }, { 0, 32 }, { 0, -32 } }  -- ins_100 ×5
    local RING_COUNT, RING_SPEED = 4, 4                 -- CIRCLE c1=4 sp1=4
    local RING_FLAGS = 0x1000202                        -- FAST|SND|TAG
    local AIM_SPEED = 1                                 -- sharedFloat1

    local st = { dead = false, sub4 = nil }

    ---Sub4（@1388）：每 4 帧从 5 个偏移各甩一圈（tag 连续轮转）。base 只在起 Sub4 时取一次。
    local function sub4(owner)
        local tok = { alive = true }
        task.New(owner, function()
            local base = sg_aim(owner.x, owner.y)       -- floatV0 = playerAngle
            local tag = 0                               -- 本上下文 intV0 的初值
            while tok.alive and not st.dead do
                for i = 1, #OFFSETS do
                    if not tok.alive or st.dead then return end
                    local dx, dy = OFFSETS[i][1], OFFSETS[i][2]
                    local hook = sg_tr_hook({ sg_rec(SG_TAG, 0, tag, -1, 0, 0) }, RING_FLAGS)
                    sg_shot(89, sg_style(8), ex_color(2),
                            owner.x + dx, owner.y - dy,
                            RING_COUNT, 1, RING_SPEED, 1, base, 0, false, RING_FLAGS, hook)
                    tag = (tag + 1) % 4
                end
                for _ = 1, 4 do
                    if not tok.alive or st.dead then return end
                    task.Wait(1)
                end
            end
        end)
        return tok
    end

    ---Sub3 / Sub8 共用的一轮：t_loop 是这一轮的起点（也是 ins_4 跳回的时刻，
    ---Sub3 = 0、Sub8 = 30）；clear 只在**第一次**进 t_loop 时做（Sub8 的 ins_102 在
    ---跳转目标之前，只跑一次）。
    local function main_loop(owner, tok, t_loop, t_move, t_end, clear)
        task.New(owner, function()
            local t = 0
            local function goto_t(target)
                while t < target do
                    if not tok.alive or st.dead then return false end
                    task.Wait(1)
                    t = t + 1
                end
                return true
            end
            if not goto_t(t_loop) then return end
            local first = true
            while tok.alive and not st.dead do
                if first and clear then
                    sg_clear({})                        -- ins_102
                end
                first = false
                if st.sub4 then st.sub4.alive = false end
                st.sub4 = sub4(owner)                   -- ins_117(0,4)
                local base = sg_aim(owner.x, owner.y)   -- floatV0 = playerAngle
                if not goto_t(t_move) then return end
                sg_bmove(owner, st, 60, 4, 2, BOX)      -- ins_67(60,4,2)
                if st.sub4 then st.sub4.alive = false end
                ---四组 ins_52(5)：sharedInt0 = k、sharedFloat0 = 自机角 + k·90°、sharedFloat1 = 1
                for k = 0, 3 do
                    sg_callback(2, k, sg_norm(base + 90 * k), AIM_SPEED)
                end
                if not goto_t(t_end) then return end
                t = t_loop                              -- ins_4(t_loop,−580)：time 置 t_loop、跳回 t_loop
            end
        end)
    end

    local card = boss.card.New(CARD_NAME, 1, 3, CARD_TIME, CARD_HP)

    function card:before()
    end

    function card:init()
        photo_damage_on(self, PHOTO_LIMIT)
        self.x, self.y = BOSS_X, BOSS_START_Y
        st.dead = false
        task.New(self, function()
            task.Wait(ENTRY_WAIT)
            task.MoveTo(HOME_X, HOME_Y, ENTRY_TIME, EASE_OUT)   -- ins_64(30,4,0,128)
            local sub3 = { alive = true }
            main_loop(self, sub3, 0, 115, 175, false)           -- Sub3
            while not st.dead do
                ---ins_115(0,4,8)：拍中第 4 张 ⇒ 主上下文整个换成 Sub8
                if photo_index(PHOTO_LIMIT) >= SWITCH_AT then
                    sub3.alive = false
                    if st.sub4 then st.sub4.alive = false end
                    if st.mv then st.mv.alive = false end
                    st.sub4 = nil
                    main_loop(self, { alive = true }, 30, 105, 165, true)
                    return
                end
                task.Wait(1)
            end
        end)
    end

    function card:frame()
    end

    function card:del()
        st.dead = true
        photo_damage_off(self)
    end

    boss.card.add({ { card, "17a" } }, LEVEL, CARD_NAME, CARD_ID)
end--散符「朧月花栞（ロケット・イン・ミスト）」

do  -- 34 毒符「ポイズンブレス」（ecl9_b，铃仙，组 18a 第 2 张）
    ---原作是「毒息」：本体落在中轴偏下；一条上下文每 3 帧朝**四个正交方向**各甩一排
    ---小玉（每排 photoIndex+1 发、速 3、排内相邻 8.57°），四个方向每轮整体转 −3°；
    ---另一条上下文每 7 帧在自机方向 60 px 处放一只**只飞不发弹**的子敌机（装饰）。
    ---数据源 /tmp/S4x_ecl9_b.txt（ECL …/data/ecl9_b.ecl）。骨架：
    ---  · Sub2：… ins_141(5)（拍 5 张）+ ins_63(-128,-64) → t=100 ins_64(30,4,0,160)
    ---    落到 (0,160)＝我们的 (0,64) → t=130 亮卡名 + ins_75(-128,160,128,256)
    ---    （**没有 ins_149**）+ ins_52(3)。
    ---  · Sub3（@712，**160 帧**一轮）：t=0 的 ins_117(0,4)（装饰子敌机）与 ins_117(1,5)
    ---    （起 Sub5）只在**第一遍**跑 —— 循环是 @824 的 ins_4(0,−52) 跳回 **@772**，
    ---    把 @712..@752 跳过 ⇒ Sub5 起一次后一直跑到卡末（卡里没有 ins_117(1,-1)）；
    ---    @772 t=75 的 ins_62/ins_144 是装饰；t=120 的 ins_67(60,4,1) 挪 60 px。
    ---  · Sub5（@992，3 帧一轮）：floatV0..V3 = π/2, π, −π/2, 0；intV0 = photoIndex + 1
    ---    （ins_20 是**加**）；四条 FAN(型 5、色 10/13/4/11、c1=intV0、c2=1、sp1=3、sp2=1.5、
    ---    step 0.149599656、flags 0x202)；随后四条 ins_16(floatVk, 0.052359879)（**减** 3°）
    ---    + 一条 ins_37(floatV0)（只归一化 V0，V1/V2/V3 一直减下去）⇒ 四个方向整体转。
    ---  · Sub6/Sub7 = 子敌机的脚本（只有移动 + 被拍到放个特效）与拍照子程序，不实现。
    local BOSS_X, BOSS_START_Y = -128, field_y(-64)
    local HOME_X, HOME_Y = 0, field_y(160)
    local ENTRY_WAIT, ENTRY_TIME = 100, 30
    local EASE_OUT = VALUE_SET.DECEL

    local PHOTO_LIMIT = 5                               -- ins_141(5)
    local CARD_NAME = "毒符「ポイズンブレス」"
    local CARD_TIME, CARD_HP = 50, 900
    local CARD_ID = 515
    local BOX = { -128, 160, 128, 256 }                 -- ins_75（TH095 空间）
    local FAN_COLORS = { 10, 13, 4, 11 }                -- 四条 FAN 的色号
    local FAN_STEP = math.deg(0.149599656)              -- 8.57°
    local FAN_SP1, FAN_SP2 = 3, 1.5                     -- c2=1 ⇒ 实发速 3
    local TURN = math.deg(0.052359879)                  -- ins_16 的 3°
    local FAN_FLAGS = 0x202                             -- FAST|SND

    local st = { dead = false }

    ---Sub5（@992）：3 帧一轮，四个正交方向各一排，方向每轮转 −3°。
    local function sub5(owner)
        local tok = { alive = true }
        task.New(owner, function()
            ---sg_deg(π/2)=−90、sg_deg(π)=−180、sg_deg(−π/2)=+90、0
            local dir = { -90, -180, 90, 0 }
            while tok.alive and not st.dead do
                local count = photo_index(PHOTO_LIMIT) + 1
                for k = 1, 4 do
                    sg_shot(87, sg_style(5), ex_color(FAN_COLORS[k]), owner.x, owner.y,
                            count, 1, FAN_SP1, FAN_SP2, dir[k], FAN_STEP, false, FAN_FLAGS)
                end
                for k = 1, 4 do
                    dir[k] = dir[k] + TURN          -- ins_16 = 减 3°（取反后是 +3）
                end
                dir[1] = sg_norm(dir[1])            -- ins_37：只归一化 V0
                for _ = 1, 3 do
                    if not tok.alive or st.dead then return end
                    task.Wait(1)
                end
            end
        end)
        return tok
    end

    ---Sub3（@712）：第一遍 t=0 起 Sub5，之后每 160 帧循环 @772(t=75) 那一段。
    local function sub3(owner)
        task.New(owner, function()
            local t = 0
            local function goto_t(target)
                while t < target do
                    if st.dead then return false end
                    task.Wait(1)
                    t = t + 1
                end
                return true
            end
            sub5(owner)                                 -- ins_117(1,5)
            while not st.dead do
                if not goto_t(120) then return end
                sg_bmove(owner, st, 60, 4, 1, BOX)      -- ins_67(60,4,1)
                if not goto_t(160) then return end
                t = 0                                   -- ins_4(0,−52)：跳回 @772(t=75)
                if not goto_t(75) then return end
            end
        end)
    end

    local card = boss.card.New(CARD_NAME, 1, 3, CARD_TIME, CARD_HP)

    function card:before()
    end

    function card:init()
        photo_damage_on(self, PHOTO_LIMIT)
        self.x, self.y = BOSS_X, BOSS_START_Y
        st.dead = false
        task.New(self, function()
            task.Wait(ENTRY_WAIT)
            task.MoveTo(HOME_X, HOME_Y, ENTRY_TIME, EASE_OUT)   -- ins_64(30,4,0,160)
            sub3(self)
        end)
    end

    function card:frame()
    end

    function card:del()
        st.dead = true
        photo_damage_off(self)
    end

    boss.card.add({ { card, "18a" } }, LEVEL, CARD_NAME, CARD_ID)
end--毒符「ポイズンブレス」

do  -- 35 波符「幻の月（インビジブルハーフムーン）」（ecl7_c，メディスン，组 17a 第 3 张）
    ---原作是「隐形半月」：本体在框里每 230 帧挪 120 px；每轮 t=0 从本体甩**两圈**大环
    ---（型 8、64 发 ×5 层、速 2.4→1.4 与 2.6→1.6，分别挂 tag 1 / tag 2），
    ---t=80 把 tag 1 的弹**相对转 +90°**、tag 2 的**相对转 −90°**（速率不变），
    ---t=170 起另一条上下文每 5 帧发一圈「photoIndex×2+10」发的自机狙（tag 0、速 1.2）。
    ---数据源 /tmp/S4x_ecl7_c.txt（ECL …/data/ecl7_c.ecl）。骨架：
    ---  · Sub2：… ins_141(6) + ins_63(-128,-64) → t=100 ins_64(30,4,0,128) → t=130 亮卡名 +
    ---    ins_75(-160,96,160,192) + ins_149(0.4) + ins_52(3)。
    ---  · Sub3（@736，**230 帧**一轮）：t=0 的 ins_6(extraIntV1,60) 紧接着被 @756 的
    ---    ins_6(extraIntV1, photoIndex) **覆盖**；t=0 起 Sub4；t=30 装饰；t=80 的
    ---    ins_40(extraIntV1, photoIndex, 80, 48) 是**恒等**比较（两边都是 photoIndex）
    ---    ⇒ 永远跳到 @872，@852 的 ins_4(170,204) 是死代码。@872/@948 两组
    ---    「sharedInt0=1/2、sharedFloat0=∓π/2、sharedFloat1=−999.9、ins_52(6)」＝
    ---    Callback04（**相对角**重瞄；速率 −999.9 < −999 ⇒ 保持当前速）；t=140 的
    ---    ins_52(8) 是 Callback05（本仓库不实现）；t=170 的 ins_52(9)（一声 + 回调 3）+
    ---    extraIntV1=photoIndex（死写）+ ins_67(60,4,2) + ins_117(0,5) 起 Sub5；
    ---    t=230 的 ins_4(0,−356) 跳回 @776（周期 230）。
    ---  · Sub4（@1164，一帧跑完、ins_53 自收）：ins_101(0, TAG, 0, 1) +
    ---    CIRCLE(型 8/色 2、64 发 ×5 层、速 2.4→1.4) + ins_101(0, TAG, 0, 2) +
    ---    CIRCLE(同型同色、速 2.6→1.6)。Sub4 **没有**给 floatV0 赋过值
    ---    ⇒ 基准角 = 上下文的 0。
    ---  · Sub5（@1356，5 帧一轮）：ins_101(0, TAG, 0, 0) + extraIntV0 = photoIndex×2 + 10
    ---    + CIRC_AIM(型 13/色 3、extraIntV0 发、速 1.2、step 0.392699) ⇒ 每 5 帧一圈自机狙。
    ---    ins_117(0,5) 换进 slot0 时会把上一轮的 Sub5 顶掉（EclRunTargetHigh.inl:206）。
    ---  · Sub6（@1528）= ins_52(6) 的那个回调上下文：call* ← shared*，再 ins_118(4)。
    ---  · Sub7/Sub9 装饰；Sub8 是 Callback05。
    local BOSS_X, BOSS_START_Y = -128, field_y(-64)
    local HOME_X, HOME_Y = 0, field_y(128)
    local ENTRY_WAIT, ENTRY_TIME = 100, 30
    local EASE_OUT = VALUE_SET.DECEL

    local PHOTO_LIMIT = 6                               -- ins_141(6)
    local CARD_NAME = "波符「幻の月（インビジブルハーフムーン）」"
    local CARD_TIME, CARD_HP = 50, 900
    local CARD_ID = 512
    local BOX = { -160, 96, 160, 192 }                  -- ins_75（TH095 空间）
    local RING_BIG1, RING_BIG2 = { 64, 5, 2.4, 1.4 }, { 64, 5, 2.6, 1.6 }  -- 两条 CIRCLE
    local RING_FLAGS = 0x1000202                        -- FAST|SND|TAG
    local AIM_SPEED = 1.2                               -- CIRC_AIM sp1
    local AIM_STEP = math.deg(0.392699093)              -- 22.5°（c2=1 用不到，照抄）
    local KEEP_SPEED = -999.9                           -- Callback04: ≤ −999 ⇒ 保持当前速

    local st = { dead = false, sub5 = nil }

    ---Sub4（@1164）：一帧跑完的两圈大环（tag 1 / tag 2）。
    local function sub4(owner)
        local base = 0                                  -- 上下文的 floatV0 初值
        local h1 = sg_tr_hook({ sg_rec(SG_TAG, 0, 1, -1, 0, 0) }, RING_FLAGS)
        sg_shot(89, sg_style(8), ex_color(2), owner.x, owner.y,
                RING_BIG1[1], RING_BIG1[2], RING_BIG1[3], RING_BIG1[4],
                base, 0, false, RING_FLAGS, h1)
        local h2 = sg_tr_hook({ sg_rec(SG_TAG, 0, 2, -1, 0, 0) }, RING_FLAGS)
        sg_shot(89, sg_style(8), ex_color(2), owner.x, owner.y,
                RING_BIG2[1], RING_BIG2[2], RING_BIG2[3], RING_BIG2[4],
                base, 0, false, RING_FLAGS, h2)
    end

    ---Sub5（@1356）：5 帧一轮的自机狙整圈（tag 0）。
    local function sub5(owner)
        local tok = { alive = true }
        task.New(owner, function()
            while tok.alive and not st.dead do
                local count = photo_index(PHOTO_LIMIT) * 2 + 10
                local hook = sg_tr_hook({ sg_rec(SG_TAG, 0, 0, -1, 0, 0) }, RING_FLAGS)
                sg_shot(88, sg_style(13), ex_color(3), owner.x, owner.y,
                        count, 1, AIM_SPEED, 0.6, 0, AIM_STEP, true, RING_FLAGS, hook)
                for _ = 1, 5 do
                    if not tok.alive or st.dead then return end
                    task.Wait(1)
                end
            end
        end)
        return tok
    end

    ---Sub3（@736）：230 帧一轮。
    local function sub3(owner)
        task.New(owner, function()
            local t = 0
            local function goto_t(target)
                while t < target do
                    if st.dead then return false end
                    task.Wait(1)
                    t = t + 1
                end
                return true
            end
            while not st.dead do
                if st.sub5 then st.sub5.alive = false end
                sub4(owner)                             -- ins_117(0,4)
                if not goto_t(80) then return end
                ---ins_52(6) 两组：tag 1 相对 +90°、tag 2 相对 −90°（速率不变）
                sg_callback(4, 1, sg_deg(-math.pi / 2), KEEP_SPEED)
                sg_callback(4, 2, sg_deg(math.pi / 2), KEEP_SPEED)
                if not goto_t(170) then return end
                sg_bmove(owner, st, 60, 4, 2, BOX)      -- ins_67(60,4,2)
                st.sub5 = sub5(owner)                   -- ins_117(0,5)
                if not goto_t(230) then return end
                t = 0                                   -- ins_4(0,−356)：跳回 @776
            end
        end)
    end

    local card = boss.card.New(CARD_NAME, 1, 3, CARD_TIME, CARD_HP)

    function card:before()
    end

    function card:init()
        photo_damage_on(self, PHOTO_LIMIT)
        self.x, self.y = BOSS_X, BOSS_START_Y
        st.dead = false
        task.New(self, function()
            task.Wait(ENTRY_WAIT)
            task.MoveTo(HOME_X, HOME_Y, ENTRY_TIME, EASE_OUT)   -- ins_64(30,4,0,128)
            sub3(self)
        end)
    end

    function card:frame()
    end

    function card:del()
        st.dead = true
        photo_damage_off(self)
    end

    boss.card.add({ { card, "17a" } }, LEVEL, CARD_NAME, CARD_ID)
end--波符「幻の月（インビジブルハーフムーン）」

do  -- 36 譫妄「イントゥデリリウム」（ecl9_c，铃仙，组 18a 第 3 张）
    ---原作是「谵妄」：本体每 (100 + 100−10×拍中张数) 帧一轮、在框里挪 120 px；一轮里
    ---另一条上下文每帧发 2 颗（型 17 ball_huge / 型 12 中玉 各一：速 rand[1,3)、方向随机、
    ---出膛点在半径 20 px 的随机方向上），共 60 帧；另有 16 只只飞不发弹的子敌机（装饰）。
    ---数据源 /tmp/S4x_ecl9_c.txt（ECL …/data/ecl9_c.ecl）。骨架：
    ---  · Sub2：… ins_141(6) + ins_63(-128,-64) → ins_64(30,4,0,128) → t=130 亮卡名 +
    ---    ins_75(-160,96,160,192) + ins_149(0.7) + ins_52(3)。
    ---  · Sub3（@728，**100 + 冻结** 帧一轮）：t=0 起 Sub4（装饰子敌机）与 Sub5；
    ---    t=40 的 ins_62/ins_144 装饰 + extraIntV0 = 100 − 10×photoIndex（ins_22 乘、
    ---    ins_21 减）+ ins_2(extraIntV0)（冻结）+ ins_67(60,4,2)；t=100 的 ins_4(0,−156)
    ---    跳回 @748 ⇒ 周期 = 100 + (100 − 10×拍中张数) 帧（拍得越多冻结越短 = 越密）。
    ---  · Sub4（@936）：floatV0 = playerAngle 起 16 只子敌机（ins_38+ins_84，一次一秒内
    ---    16 发），world04 里它们**只飞不发弹** ⇒ 不实现。
    ---  · Sub5（@1116，每帧一轮、共 60 轮）：extraIntV0 = 60；intV0 = photoIndex + 1（没用上）；
    ---    每颗弹三步（顺序不能动，随机数要吃三发）：ins_38(·, rand(−π,π), 20) 定出膛点 →
    ---    ins_100 写入 shootOffset → ins_27(floatV0, randF32, 2) + ins_15(floatV0, 1) 定速 →
    ---    FAN(c1=1、ang=rand(−π,π)、型 17/色 2 或 型 12/色 6)；t=1 的 ins_5(0,−296,60)
    ---    ⇒ 每帧一发。flags 0x202 = FAST|SND。
    ---  · Sub6/Sub7 = 子敌机脚本与拍照子程序，不实现。
    local BOSS_X, BOSS_START_Y = -128, field_y(-64)
    local HOME_X, HOME_Y = 0, field_y(128)
    local ENTRY_WAIT, ENTRY_TIME = 100, 30
    local EASE_OUT = VALUE_SET.DECEL

    local PHOTO_LIMIT = 6                               -- ins_141(6)
    local CARD_NAME = "譫妄「イントゥデリリウム」"
    local CARD_TIME, CARD_HP = 50, 900
    local CARD_ID = 516
    local BOX = { -160, 96, 160, 192 }                  -- ins_75（TH095 空间）
    local BURST_ROUNDS = 60                             -- extraIntV0
    local OFFSET_R = 20                                 -- ins_38 的半径
    local FAN_STEP = math.deg(0.149599656)              -- c1=1 用不到，照抄 ECL
    local FAN_FLAGS = 0x202                             -- FAST|SND

    local st = { dead = false, sub5 = nil }

    ---Sub5（@1116）：每帧两颗（一 huge 一中玉）。
    local function sub5(owner)
        local tok = { alive = true }
        task.New(owner, function()
            for _ = 1, BURST_ROUNDS do
                if not tok.alive or st.dead then return end
                local dx, dy = sg_off(OFFSET_R, ran:Float(-math.pi, math.pi))
                local sp = ran:Float(0, 1) * 2 + 1
                sg_shot(87, sg_style(17), ex_color(2), owner.x + dx, owner.y + dy,
                        1, 1, sp, 1.5, ran:Float(0, 360), FAN_STEP, false, FAN_FLAGS)
                local dx2, dy2 = sg_off(OFFSET_R, ran:Float(-math.pi, math.pi))
                local sp2 = ran:Float(0, 1) * 2 + 1
                sg_shot(87, sg_style(12), ex_color(6), owner.x + dx2, owner.y + dy2,
                        1, 1, sp2, 1.5, ran:Float(0, 360), FAN_STEP, false, FAN_FLAGS)
                task.Wait(1)
            end
        end)
        return tok
    end

    ---Sub3（@728）：100 + 冻结 帧一轮。
    local function sub3(owner)
        task.New(owner, function()
            local t = 0
            local function goto_t(target)
                while t < target do
                    if st.dead then return false end
                    task.Wait(1)
                    t = t + 1
                end
                return true
            end
            local function freeze(n)
                for _ = 1, n do
                    if st.dead then return false end
                    task.Wait(1)
                end
                return true
            end
            while not st.dead do
                if st.sub5 then st.sub5.alive = false end
                st.sub5 = sub5(owner)                   -- ins_117(1,5)
                if not goto_t(40) then return end
                local d = 100 - 10 * photo_index(PHOTO_LIMIT)
                if d > 0 and not freeze(d) then return end
                sg_bmove(owner, st, 60, 4, 2, BOX)      -- ins_67(60,4,2)
                if not goto_t(100) then return end
                t = 0                                   -- ins_4(0,−156)：跳回 @748
            end
        end)
    end

    local card = boss.card.New(CARD_NAME, 1, 3, CARD_TIME, CARD_HP)

    function card:before()
    end

    function card:init()
        photo_damage_on(self, PHOTO_LIMIT)
        self.x, self.y = BOSS_X, BOSS_START_Y
        st.dead = false
        task.New(self, function()
            task.Wait(ENTRY_WAIT)
            task.MoveTo(HOME_X, HOME_Y, ENTRY_TIME, EASE_OUT)   -- ins_64(30,4,0,128)
            sub3(self)
        end)
    end

    function card:frame()
    end

    function card:del()
        st.dead = true
        photo_damage_off(self)
    end

    boss.card.add({ { card, "18a" } }, LEVEL, CARD_NAME, CARD_ID)
end--譫妄「イントゥデリリウム」

do  -- 37 借符「大穴牟遅様の薬」（ecl8_b，帝，组 19a 第 2 张）
    ---原作是「大穴牟迟神的药」：本体每 240 帧用 120 帧慢慢挪 120 px；一条上下文
    ---每 4 帧轮发**两圈**中玉（型 13/色 6 与 色 5、圈弹数 = 拍中<3 ? 7 : 拍中+5、
    ---速 2.2，两圈分别挂 BOUNCE_NOBOT(4 次) + POLAR(6000 帧、±0.72°/帧)），共 20 轮。
    ---数据源 /tmp/S4x_ecl8_b.txt（ECL …/data/ecl8_b.ecl）。骨架：
    ---  · Sub2：… ins_141(6) + ins_63(-128,-64) → ins_64(30,4,0,128) → t=130 亮卡名 +
    ---    ins_75(-160,96,160,224)（**没有 ins_149**）+ ins_52(3)。
    ---  · Sub3（@700，**240 帧**一轮）：t=0 起 Sub4；t=75 装饰；t=90 的 ins_67(120,4,1)
    ---    用 120 帧挪 120 px；t=240 的 ins_4(0,−60) 跳回 @720（t=0）。
    ---  · Sub4（@812，20 轮 × 4 帧，之后 ins_53 自收）：extraIntV0 = 20；
    ---    ins_50(photoIndex,3,0,68) 若 photoIndex ≥ 3 跳到 @900 ⇒ extraIntV1 = photoIndex−2，
    ---    否则 @860 的 extraIntV1 = 0（@880 的 ins_4(0,44) 再跳到 @924）；
    ---    @924 的 extraIntV1 += 7 ⇒ 圈弹数 = 拍中<3 ? 7 : 拍中+5。floatV0 = playerAngle（固定）。
    ---    t=0 两圈（色 6、POLAR +0.0125663709）、t=2 再两圈（色 5、POLAR −0.0125663709）；
    ---    t=4 的 ins_5(0,−260,20) 轮 20 次。
    ---  · 两条 ins_101 = BOUNCE_NOBOT(0x800, allow 0, i0=4) + POLAR(0x20, allow 1, i0=6000)
    ---    ⇒ 极坐标下一帧起与反弹同时生效（sg_tr_hook 的 acts 表按 flag 位排）。
    local BOSS_X, BOSS_START_Y = -128, field_y(-64)
    local HOME_X, HOME_Y = 0, field_y(128)
    local ENTRY_WAIT, ENTRY_TIME = 100, 30
    local EASE_OUT = VALUE_SET.DECEL

    local PHOTO_LIMIT = 6                               -- ins_141(6)
    local CARD_NAME = "借符「大穴牟遅様の薬」"
    local CARD_TIME, CARD_HP = 50, 900
    local CARD_ID = 518
    local BOX = { -160, 96, 160, 224 }                  -- ins_75（TH095 空间）
    local ROUNDS = 20                                   -- extraIntV0
    local COUNT_LOW = 7                                 -- 拍中 < 3 张
    local COUNT_BIAS = 5                                -- 拍中 ≥ 3 张：photoIndex + 5
    local COUNT_THRESHOLD = 3                           -- ins_50 的右操作数
    local RING_SPEED1, RING_SPEED2 = 2.2, 1.5
    local TURN = 0.0125663709                           -- ±0.72°/帧（rad）
    local BOUNCES = 4
    local RING_FLAGS = 0xA22                            -- FAST|POLAR|SND|BOUNCE_NOBOT

    local st = { dead = false, sub4 = nil }

    ---Sub4（@812）：每 4 帧两圈（两色、反向自转）。
    local function sub4(owner)
        local tok = { alive = true }
        task.New(owner, function()
            local hits = photo_index(PHOTO_LIMIT)
            local count = (hits >= COUNT_THRESHOLD) and (hits + COUNT_BIAS) or COUNT_LOW
            local base = sg_aim(owner.x, owner.y)       -- floatV0 = playerAngle
            for _ = 1, ROUNDS do
                if not tok.alive or st.dead then return end
                local h1 = sg_tr_hook({
                    sg_rec(SG_BOUNCE_EB, 0, BOUNCES, -1, -999, 0),
                    sg_rec(SG_POLAR, 1, 6000, -1, 0, sg_deg(TURN)),
                }, RING_FLAGS)
                sg_shot(89, sg_style(13), ex_color(6), owner.x, owner.y,
                        count, 1, RING_SPEED1, RING_SPEED2, base, 0, false, RING_FLAGS, h1)
                for _ = 1, 2 do
                    if not tok.alive or st.dead then return end
                    task.Wait(1)
                end
                local h2 = sg_tr_hook({
                    sg_rec(SG_BOUNCE_EB, 0, BOUNCES, -1, -999, 0),
                    sg_rec(SG_POLAR, 1, 6000, -1, 0, sg_deg(-TURN)),
                }, RING_FLAGS)
                sg_shot(89, sg_style(13), ex_color(5), owner.x, owner.y,
                        count, 1, RING_SPEED1, RING_SPEED2, base, 0, false, RING_FLAGS, h2)
                for _ = 1, 2 do
                    if not tok.alive or st.dead then return end
                    task.Wait(1)
                end
            end
        end)
        return tok
    end

    ---Sub3（@700）：240 帧一轮。
    local function sub3(owner)
        task.New(owner, function()
            local t = 0
            local function goto_t(target)
                while t < target do
                    if st.dead then return false end
                    task.Wait(1)
                    t = t + 1
                end
                return true
            end
            while not st.dead do
                if st.sub4 then st.sub4.alive = false end
                st.sub4 = sub4(owner)                   -- ins_117(0,4)；Sub4 跑 80 帧自收
                if not goto_t(90) then return end
                sg_bmove(owner, st, 120, 4, 1, BOX)     -- ins_67(120,4,1)
                if not goto_t(240) then return end
                t = 0                                   -- ins_4(0,−60)：跳回 @720
            end
        end)
    end

    local card = boss.card.New(CARD_NAME, 1, 3, CARD_TIME, CARD_HP)

    function card:before()
    end

    function card:init()
        photo_damage_on(self, PHOTO_LIMIT)
        self.x, self.y = BOSS_X, BOSS_START_Y
        st.dead = false
        task.New(self, function()
            task.Wait(ENTRY_WAIT)
            task.MoveTo(HOME_X, HOME_Y, ENTRY_TIME, EASE_OUT)   -- ins_64(30,4,0,128)
            sub3(self)
        end)
    end

    function card:frame()
    end

    function card:del()
        st.dead = true
        photo_damage_off(self)
    end

    boss.card.add({ { card, "19a" } }, LEVEL, CARD_NAME, CARD_ID)
end--借符「大穴牟遅様の薬」

do  -- 38 狂夢「風狂の夢（ドリームワールド）」（ecl7_d，メディスン，组 17a 第 4 张）
    ---原作是「疯狂的梦」：本体每 (190 + 100−10×拍中张数) 帧一轮、在框里慢慢挪 78 px；
    ---一条上下文每 5 帧甩**两圈** 22 发中玉（型 8/色 6、速 0.6、基准角固定 0），
    ---两圈的弹分别挂 tag 1 / tag 2，并各自**加速 +0.03/帧、转向 ±1.5°/帧**（POLAR 120 帧）；
    ---t=80 把两批弹按相对角 0 重设（速率不变，等于只重算一次速度矢量）；
    ---t=100 的 Callback05（淡出被捕获弹）本仓库不实现。
    ---数据源 /tmp/S4x_ecl7_d.txt（ECL …/data/ecl7_d.ecl）。骨架：
    ---  · Sub2：… ins_141(5) + ins_63(-128,-64) → ins_64(30,4,0,128) → t=130 亮卡名 +
    ---    ins_75(-130,96,130,192) + ins_149(0.5) + ins_52(3)。
    ---  · Sub3（@732，**190 + 冻结** 帧一轮）：t=0 起 Sub4；t=15 装饰；t=80 两组
    ---    「sharedInt0=1/2、sharedFloat0=0、sharedFloat1=−999.9、ins_52(5)」= Callback04，
    ---    同一帧 extraIntV0 = 100 − 10×photoIndex（ins_22/ins_21）+ ins_2 冻结；
    ---    t=100 的 ins_52(7) = Callback05；t=130 的 ins_52(8)（一声 + 回调 3）+
    ---    ins_67(60,4,1.3)（挪 78 px）；t=190 的 ins_4(0,−312) 跳回 **@772(t=15)**
    ---    ⇒ 周期 = 190 + (100 − 10×拍中张数) 帧（拍得越多冻结越短 = 越密）。
    ---  · Sub4（@1116，5 帧一轮、一直跑到卡末）：@1116 的 extraIntV0 = photoIndex×2+10
    ---    是**死代码**（两圈用的是字面量 22）；ins_101(0, TAG, 0, 1) + ins_101(1, POLAR, 0,
    ---    120, f0=0.03, f1=+0.0261799395) + CIRCLE(型 8/色 6、22 发、速 0.6、step 0.392699)，
    ---    再镜像一组（TAG 2、f1=−0.0261799395）；t=5 的 ins_4(0,−248) 跳回 @1160，
    ---    而 @1428 的 ins_53 在跳转目标之前 ⇒ 永远循环（卡里没有 ins_117(0,-1)）。
    ---  · Sub5（@1452）= Callback04 的上下文（angle=0 ⇒ 只按当前角速重设一遍）。
    ---  · Sub6/Sub7/Sub8 都是装饰 / Callback05。
    local BOSS_X, BOSS_START_Y = -128, field_y(-64)
    local HOME_X, HOME_Y = 0, field_y(128)
    local ENTRY_WAIT, ENTRY_TIME = 100, 30
    local EASE_OUT = VALUE_SET.DECEL

    local PHOTO_LIMIT = 5                               -- ins_141(5)
    local CARD_NAME = "狂夢「風狂の夢（ドリームワールド）」"
    local CARD_TIME, CARD_HP = 50, 900
    local CARD_ID = 513
    local BOX = { -130, 96, 130, 192 }                  -- ins_75（TH095 空间）
    local RING_COUNT, RING_SPEED = 22, 0.6              -- CIRCLE c1=22 sp1=0.6
    local RING_STEP = math.deg(0.392699093)             -- c2=1 用不到，照抄 ECL
    local ACCEL = 0.03                                  -- POLAR f0（每帧 +0.03 速）
    local SPIN = 0.0261799395                           -- POLAR f1（±1.5°/帧，rad）
    local POLAR_FRAMES = 120
    local RING_FLAGS = 0x1000222                        -- FAST|POLAR|SND|TAG
    local KEEP_SPEED = -999.9                           -- Callback04: ≤ −999 ⇒ 保持当前速

    local st = { dead = false, sub4 = nil }

    ---Sub4（@1116）：每 5 帧两圈（tag 1 / tag 2，各自加速 + 反向自转）。
    local function sub4(owner)
        local tok = { alive = true }
        task.New(owner, function()
            while tok.alive and not st.dead do
                local h1 = sg_tr_hook({
                    sg_rec(SG_TAG, 0, 1, -1, 0, 0),
                    sg_rec(SG_POLAR, 0, POLAR_FRAMES, -1, ACCEL, sg_deg(SPIN)),
                }, RING_FLAGS)
                sg_shot(89, sg_style(8), ex_color(6), owner.x, owner.y,
                        RING_COUNT, 1, RING_SPEED, RING_SPEED, 0,
                        RING_STEP, false, RING_FLAGS, h1)
                local h2 = sg_tr_hook({
                    sg_rec(SG_TAG, 0, 2, -1, 0, 0),
                    sg_rec(SG_POLAR, 0, POLAR_FRAMES, -1, ACCEL, sg_deg(-SPIN)),
                }, RING_FLAGS)
                sg_shot(89, sg_style(8), ex_color(6), owner.x, owner.y,
                        RING_COUNT, 1, RING_SPEED, RING_SPEED, 0,
                        RING_STEP, false, RING_FLAGS, h2)
                for _ = 1, 5 do
                    if not tok.alive or st.dead then return end
                    task.Wait(1)
                end
            end
        end)
        return tok
    end

    ---Sub3（@732）：190 + 冻结 帧一轮。
    local function sub3(owner)
        task.New(owner, function()
            local t = 0
            local function goto_t(target)
                while t < target do
                    if st.dead then return false end
                    task.Wait(1)
                    t = t + 1
                end
                return true
            end
            local function freeze(n)
                for _ = 1, n do
                    if st.dead then return false end
                    task.Wait(1)
                end
                return true
            end
            while not st.dead do
                if st.sub4 then st.sub4.alive = false end
                st.sub4 = sub4(owner)                   -- ins_117(0,4)
                if not goto_t(80) then return end
                ---ins_52(5) 两组：tag 1 / tag 2 相对转 0°、速率不变
                sg_callback(4, 1, 0, KEEP_SPEED)
                sg_callback(4, 2, 0, KEEP_SPEED)
                local d = 100 - 10 * photo_index(PHOTO_LIMIT)
                if d > 0 and not freeze(d) then return end
                if not goto_t(130) then return end
                sg_bmove(owner, st, 60, 4, 1.3, BOX)    -- ins_67(60,4,1.3)
                if not goto_t(190) then return end
                t = 0                                   -- ins_4(0,−312)：time 置 0、跳回 @772(t=15)
                if not goto_t(15) then return end
            end
        end)
    end

    local card = boss.card.New(CARD_NAME, 1, 3, CARD_TIME, CARD_HP)

    function card:before()
    end

    function card:init()
        photo_damage_on(self, PHOTO_LIMIT)
        self.x, self.y = BOSS_X, BOSS_START_Y
        st.dead = false
        task.New(self, function()
            task.Wait(ENTRY_WAIT)
            task.MoveTo(HOME_X, HOME_Y, ENTRY_TIME, EASE_OUT)   -- ins_64(30,4,0,128)
            sub3(self)
        end)
    end

    function card:frame()
    end

    function card:del()
        st.dead = true
        photo_damage_off(self)
    end

    boss.card.add({ { card, "17a" } }, LEVEL, CARD_NAME, CARD_ID)
end--狂夢「風狂の夢（ドリームワールド）」

end  -- Stage 4


---──────────────────── Stage 3（scene group 2 = world03）── 公共工具 / 八张卡 ────────────────────
---原作 scene group 2 是 world03（アリス・マーガトロイド / 上白沢慧音）。SceneSelect.cpp:88-96
---的 TH095_SCENE 表里 scene 20..27 共八幕（这一组的第 1 幕是**非符**，按原作不亮卡名），
---奇偶分属两位角色：
---  20 ecl6_a アリス 非符（不亮卡名）        21 ecl5_a 慧音 光符「アマテラス」
---  22 ecl6_b アリス 操符「ドールズインシー」 23 ecl5_b 慧音 包符「昭和の雨」
---  24 ecl6_c アリス 呪符「ストロードールカミカゼ」 25 ecl5_c 慧音 葵符「水戸の光圀」
---  26 ecl6_d アリス 赤符「ドールミラセティ」 27 ecl5_d 慧音 倭符「邪馬台の国」
---（角色对号是从 ins_104 的卡名表解出来的，别按文件名猜。）
---按「一个角色一个组」拆：组 20 = アリス（20/22/24/26，第 1 张是非符）、
---组 21 = 上白沢慧音（21/23/25/27）。★ 别把两人塞进同一个组的 a/b。
---原作整组 BGM 是 bgm/th095_02.wav ——**本仓库没有这首**（music.lua 里 th095 系只有
---TH07_1 = th095_04、TH09_5_1 = th095_03），整组沿用 "TH09_5_1"（与 Stage EX/5/4 同一首），
---背景沿用 TH095_bg；world03.std 的贴图本仓库也没有，两套符卡背景照 Stage 4/5 的做法
---拿 th06/th07/th08/th10 的通用贴图重新配色（见上面 class.scbg20/21）。
---数据源 /tmp/D95x_ecl{5,6}_{a..d}.txt（脚本 /tmp/d95dump.py 不入库；ECL 在
---`[th095] …/data/ecl{5,6}_{a..d}.ecl`），各卡注释里的「@地址」都指这几份 dump。
---
---这一组八幕共用同一套外壳（Sub2）：ins_55(2)+ins_81(3)+ins_109(0)+ins_77(24,24)
---+ins_141(N)+ins_108(0,31)/ins_108(1,30)+ins_143(1,130)+ins_63(-128,-64) 进场
---→ t=100 的 ins_64(30,4,0,Y) 用 30 帧从场地左上角外落到中轴（我们的 (0, field_y(Y))）
---→ t=130 亮卡名（ecl6_a 是 id=0，**非符不亮**）+ ins_75(box) + ins_149(倍率) + ins_52(3)。
---★ ins_83 生成的子敌机（アリス的人偶、慧音的光球）按文件头差异 5 一律做成
---  「数量受限、有寿命、淡出离场」的自绘 object；它们发的弹照抄。
---★ 循环的「周期」不是 ins_4 的字节偏移：ins_4(time, offset) 把 **time 置成 operand0**、
---  跳到「当前指令地址 + offset」，然后**在同一帧内**重取自标（time 相等才执行）
---  ⇒ 同一 t 的循环体在一帧里跑完，time 对不上就直接结束本帧（th095/src/ecl/EclRun.cpp）。
---★ ins_5(a, offset, n) 先把 n−1、n ≤ 0 就不跳（顺序执行下一条）；否则和 ins_4 一样跳。
---★ ins_2(n) 是「冻结」：接下来 n 帧 context 的 time 原地不动、一条指令都不跑。
do

---TH095 的极坐标偏移 (半径 r, 弧度 θ) → 我们的相对位移：x 同号、y 取反
---（我们的 y = 224 − TH095 的 y）。ins_38 + ins_100 的 shootOffset 用。
local function sg_off(r, th_rad)
    return r * math.cos(th_rad), -r * math.sin(th_rad)
end

---TH095 的 AddNormalizeAngle（ins_37）：把**弧度**折进 [−π,π]（原作折进 [−π,π]）。
---★ 与 Stage 4/5 段里那个「度」版的 sg_norm 不同名同实 —— 这一段的卡都在 TH095
---  空间算角（弧度），所以这里单独给一份弧度版，别去引用外面那个。
local function sg_norm(a)
    a = a % (2 * math.pi)
    if a > math.pi then a = a - 2 * math.pi end
    return a
end

---一帧一帧地把本体挪到 (tx,ty)（线性缓动），**每帧**夹进 ins_75 的活动框。
local function sg_move_clamped(owner, box, st, tok, tx, ty, n)
    local x0, y0 = owner.x, owner.y
    for s = 1, n do
        if not tok.alive or st.dead then return end
        local p = s / n
        owner.x = max(box[1], min(box[3], x0 + p * (tx - x0)))
        owner.y = max(field_y(box[4]), min(field_y(box[2]), y0 + p * (ty - y0)))
        task.Wait(1)
    end
end

do  -- 20 アリス 非符（ecl6_a，组 20a 第 1 张）
    ---原作这一幕**不亮卡名**（Sub2 的 t=130 是 id=0 = NOP）：本体落到中轴后每 185 帧
    ---重开一轮 —— 一轮 3 对、共 6 只「人偶」子机（每对间隔 120°、对里两只各偏
    ---+3° / −2.25°）绕本体转；每只人偶每 4 帧朝外放一发小玉（初速 0.2、沿出膛方向
    ---以 2/60 px/帧² 加速 60 帧 ⇒ 末速 2.2）。拍中第 3 张后主脚本换成 Sub9：
    ---清一次屏 + 把一圈改成 4 对 8 只（每对间隔 60°）。
    ---数据源 /tmp/D95x_ecl6_a.txt（ECL …/data/ecl6_a.ecl）。骨架：
    ---  · Sub2：… ins_141(5)（拍 5 张）+ ins_115(0,3,9)（拍中第 3 张换主脚本）+ ins_63(-128,-64)
    ---    → t=100 ins_64(30,4,0,128) 落到 (0,128)（我们的 (0,96)）→ t=130 的 id=0（NOP，非符）
    ---    + ins_75(-160,96,160,192) + ins_149(2) + ins_52(3) 起 Sub3。
    ---  · Sub3（@716，185 帧一轮）：extraIntV0 = 4 − 拍中张数（dump 里有、Sub4 没用到）→
    ---    ins_117(0,4) 起 Sub4 → t=105 ins_67(60,4,1)（框里随机挪 60 px）→
    ---    t=165 ins_144（快门脉冲，装饰）→ t=185 ins_4(0,−84) 跳回 @716。
    ---  · Sub4（@832，一次性）：floatV0 = rand(−π,π)（**TH095 弧度**）；每对先
    ---    floatV7 = +0.05236 rad（3°）发一只、再 −0.03927 rad（−2.25°）发一只；
    ---    一对发完 floatV0 += 2.0944 rad（120°）并归一化；共 3 对 6 只，然后 ins_53。
    ---  · 每只人偶（Sub5，寿命 190 帧，ins_83(5) 生、跑 Sub6/Sub7 两条子上下文）：
    ---    · Sub6（@1320，2 帧一轮）：floatV1 = 0→60 的线性插值（30 帧、缓动 4）当半径，
    ---      目标 = 拍照目标（本体）+ 极坐标(floatV1, floatV0)，ins_64(6,0,…) 用 6 帧线性靠过去，
    ---      每轮 floatV0 += floatV7 再归一化 ⇒ **绕本体螺旋外扩**；
    ---    · Sub7（@1528，4 帧一轮）：floatV7 ×= 1.3、ins_101(0, 0x10, 0, 60, −1, 2/60, −999)
    ---      写 VEC 记录 + ins_89 CIRCLE（型 7 小玉、色 2、count1 = 1、速 floatV3 = 0.2、
    ---      基角 floatV0、步长 0.19635）⇒ 每 4 帧一发；每轮 floatV0 −= floatV7。
    ---  · Sub9（拍中第 3 张起接管主脚本）：t=30 ins_85（重置敌人）+ ins_102（清屏）→
    ---    t=60 ins_117(0,10) → t=165 ins_67(60,4,1) → t=245 ins_4(60,−60) 跳回 @1964（t=60）
    ---    ⇒ 之后从 t=60 起每 185 帧按 Sub10 再放一圈。
    ---  · Sub10（@2056）：与 Sub4 同构，只是每对之间 floatV0 += 1.0472 rad（60°）、共 4 对 8 只。
    ---  · Sub0/Sub1 是死亡/退场 ⇒ 不实现（文件头差异 3）。
    local BOSS_X, BOSS_START_Y = -128, field_y(-64)
    local HOME_X, HOME_Y = 0, field_y(128)              -- 0 / 96
    local ENTRY_WAIT, ENTRY_TIME = 100, 30
    local EASE_OUT = VALUE_SET.DECEL

    local PHOTO_LIMIT = 5                               -- ins_141(5)
    local CARD_NAME = ""                                -- 非符：原作 t=130 是 id=0
    local CARD_TIME, CARD_HP = 50, 900
    local CARD_ID = 519
    local BOX = { -160, 96, 160, 192 }                  -- ins_75

    local ROUND = 185                                   -- Sub3 一轮的周期（ins_4(0,−84)）
    local MOVE_AT, MOVE_FRAMES, MOVE_EASE, MOVE_SPEED = 105, 60, 4, 1
    local PULSE_AT = 165                                -- ins_144（装饰）
    local SUB9_AT = 60                                  -- Sub9 起 Sub10 的时刻

    local PAIRS0, STEP0 = 3, 2.09439516                 -- Sub4：3 对、每对 +120°（rad）
    local PAIRS1, STEP1 = 4, 1.04719758                 -- Sub10：4 对、每对 +60°（rad）
    local OFF_A, OFF_B = 0.052359879, -0.0392699093     -- floatV7（rad）
    local FIRE_MUL = 1.3                                -- Sub7：floatV7 ×= 1.3
    local DOLL_LIFE = 190                               -- Sub5 的 t=190（ins_52(8) 起退场）
    local EXIT_FRAMES, EXIT_DROP = 60, 64               -- Sub8：ins_64(60,1,world.x,world.y+64)
    local ORBIT_R, ORBIT_FRAMES = 60, 30              -- Sub6：半径 0→60、30 帧（ins_36）
    local FIRE_GAP = 4                                  -- Sub7
    local BULLET_SPEED = 0.2                            -- Sub7 的 floatV3
    local BULLET_FRAMES, BULLET_ACC = 60, 2 / 60        -- ins_101 的 i0 / f0
    local DOLL_ALPHA = 170

    local st = { dead = false }
    local gen = 0                                       -- 主脚本代号（ins_115 会 +1）
    local dolls = {}
    local lasers = {}

    ---一只人偶（Sub5）。v0 = 出生角（TH095 弧度）、v7 = 每轮的角增量（TH095 弧度）。
    class.alice_doll = Class(object, {
        init = function(self, owner, v0, v7)
            self.owner = owner
            self.group = GROUP.GHOST
            self.layer = LAYER.ENEMY_BULLET_EF
            self.colli = false
            self.bound = false
            self.rot = 0
            self._a = 0
            self.x, self.y = owner.x, owner.y
            local mv = { dead = false }
            task.New(self, function()
                local v = v0
                local vfire = v0
                local v7f = v7 * FIRE_MUL
                local tick = 0
                local life = 0
                ---Sub6（slot0）和 Sub7（slot1）是 ins_117 建出来的**两条独立子上下文**，
                ---各自跑自己的时钟，不能并成一条：Sub6 每帧重设一次目标（+1 帧循环），
                ---Sub7 每 4 帧发一发（ins_4(0,Sub7_120) 的 +4）。两条上下文各持一份
                ---floatV0/floatV7（ins_117 会 memcpy 父块），所以两个角度互不影响。
                while not st.dead and life < DOLL_LIFE do
                    ---Sub6：ins_36(floatV1, 30, 4, 4, 0, 60, 0, 0) 把半径 f1 从 0 缓动到 60，
                    ---再 ins_38(f0,f1) + ptTarget + ins_64(6,0,…) 每帧重设一次 6 帧插值目标；
                    ---f0 每帧 += floatV7。
                    local rp = min(1, life / ORBIT_FRAMES)
                    local r = ORBIT_R * (1 - (1 - rp) * (1 - rp))
                    local ox, oy = sg_off(r, v)
                    sg_move(self, mv, owner.x + ox, owner.y + oy, 6, 0)
                    v = v + v7
                    ---Sub7：每 4 帧一发小玉（首帧即发），角度每发 -= 1.3×floatV7。
                    if tick % FIRE_GAP == 0 then
                        local hook = sg_tr_hook({ sg_rec(SG_VEC, 0, BULLET_FRAMES, -1,
                                BULLET_ACC, -999) }, 0x212)
                        sg_shot(89, sg_style(7), ex_color(2), self.x, self.y,
                                1, 1, BULLET_SPEED, BULLET_SPEED, math.deg(vfire), 0,
                                false, 0x212, hook)
                        vfire = vfire - v7f
                    end
                    tick = tick + 1
                    life = life + 1
                    self._a = min(DOLL_ALPHA, self._a + 11)
                    task.Wait(1)
                end
                ---退场（Sub8 = ins_64(60,1,world.x,world.y+64) + t=60 的 ins_1）。
                local x0, y0 = self.x, self.y
                local f = sg_ease(1)
                for s = 1, EXIT_FRAMES do
                    if st.dead then break end
                    local p = f(s / EXIT_FRAMES)
                    self.x, self.y = x0, y0 - EXIT_DROP * p
                    self._a = DOLL_ALPHA * (1 - s / EXIT_FRAMES)
                    task.Wait(1)
                end
                object.RawDel(self)
            end)
        end,
        frame = function(self)
            task.Do(self)                                  -- ★ 驱动环绕 / 发弹 / 退场协程
        end,
        render = function(self)
            SetImageState("butterfly3", "mul+add", self._a, 240, 200, 250)
            Render("butterfly3", self.x, self.y, self.rot, 0.8)
        end,
    })

    ---Sub4/Sub10：一次性放一圈「每对两只」的人偶。
    local function spawn_dolls(owner, pairs, step)
        local v = ran:Float(-math.pi, math.pi)
        for _ = 1, pairs do
            dolls[#dolls + 1] = New(class.alice_doll, owner, v, OFF_A)
            dolls[#dolls + 1] = New(class.alice_doll, owner, v, OFF_B)
            v = v + step
        end
    end

    local function sub4(owner)
        spawn_dolls(owner, PAIRS0, STEP0)
    end

    local function sub3(owner)
        local g = gen
        task.New(owner, function()
            while not st.dead and g == gen do
                sub4(owner)
                task.Wait(MOVE_AT)
                if st.dead then return end
                sg_bmove(owner, st, MOVE_FRAMES, MOVE_EASE, MOVE_SPEED, BOX)
                task.Wait(PULSE_AT - MOVE_AT)
                if st.dead or g ~= gen then return end
                task.Wait(ROUND - PULSE_AT)
            end
        end)
    end

    ---Sub9：拍中第 3 张起接管主脚本（ins_85 重置敌人 + ins_102 清屏 + 换成 8 只一圈）。
    local function sub9(owner)
        local g = gen
        task.New(owner, function()
            task.Wait(30)
            if st.dead then return end
            for i = #dolls, 1, -1 do                       -- ins_85：清掉场上的人偶
                if IsValid(dolls[i]) then
                    task.Clear(dolls[i])
                    object.RawDel(dolls[i])
                end
                dolls[i] = nil
            end
            sg_clear(lasers)                               -- ins_102
            task.Wait(SUB9_AT - 30)
            while not st.dead and g == gen do
                spawn_dolls(owner, PAIRS1, STEP1)
                task.Wait(MOVE_AT - SUB9_AT)
                if st.dead or g ~= gen then return end
                sg_bmove(owner, st, MOVE_FRAMES, MOVE_EASE, MOVE_SPEED, BOX)
                task.Wait(ROUND - MOVE_AT)
            end
        end)
    end

    local card = boss.card.New(CARD_NAME, 1, 3, CARD_TIME, CARD_HP)

    function card:before()
        gen = 1
        dolls = {}
        lasers = {}
    end

    function card:init()
        photo_damage_on(self, PHOTO_LIMIT)
        self.x, self.y = BOSS_X, BOSS_START_Y
        st.dead = false
        task.New(self, function()
            task.Wait(ENTRY_WAIT)
            task.MoveTo(HOME_X, HOME_Y, ENTRY_TIME, EASE_OUT)
            sub3(self)
            task.New(self, function()                   -- ins_115(0,3,9) 的监视器
                while not st.dead do
                    if photo_index(PHOTO_LIMIT) >= 3 then
                        gen = gen + 1
                        sub9(self)
                        return
                    end
                    task.Wait(1)
                end
            end)
        end)
    end

    function card:frame()
    end

    function card:del()
        st.dead = true
        photo_damage_off(self)
        sg_clear(lasers)
        for i = #dolls, 1, -1 do
            if IsValid(dolls[i]) then
                task.Clear(dolls[i])
                object.RawDel(dolls[i])
            end
        end
        dolls = {}
    end

    boss.card.add({ { card, "20a" } }, LEVEL, CARD_NAME, CARD_ID)
end--アリス 非符（ecl6_a）

do  -- 22 アリス 操符「ドールズインシー」（ecl6_b，组 20a 第 2 张）
    ---原作：本体每 160 帧一轮 —— 一轮在**本体身上**一帧放完 3 圈 × 3 对 = 18 只人偶（Sub4）。
    ---每圈先随机取一个基准角 floatV0 = rand[−π,π)（Sub4 每圈首条 ins_7 的 0x2751 就是
    ---`rnd*2π−π`，EclOperandsFloat.cpp:118）；圈内 3 对之间 floatV0 += 120°（ins_15+ins_37）。
    ---同一对的两只**出生角相同**，区别只在每帧角增量 floatV7 = ±δ —— 时间一长两只向两侧散开；
    ---δ 逐圈变小：2.25°（40 px 圈）→ 1.5°（80 px 圈）→ 1.125°（120 px 圈）。
    ---每只人偶（Sub6/7/8/9）：Sub7 每帧把「本体位置 + 极坐标(插值半径, 自己角度)」当目标，用
    ---ins_64(6,0,…) 贴过去 —— 这条插值**每帧重发**，所以每帧只走剩余距离的 1/6
    ---（EclHelpers.cpp:43 ConfigureRelativeMotion + EnemyMovement.cpp:96 的 progress=1/6）；
    ---半径是 ins_36(floatV1,30,线性,缓动4,0,floatV2)：30 帧从 0 走到 40/80/120，
    ---缓动 4 = 1−(1−n)²（EclRun.cpp:372）；角度每帧 += floatV7（ins_15+ins_37）。
    ---Sub8 发弹：进 Sub8 那一刻先定两样 —— 总发数 extraIntV0 = 拍中数×3 + 10
    ---（ins_22/ins_10，**只算一次**）与 floatV7 *= 1.3（ins_17，也只一次）；之后每轮以
    ---floatV1 = 0.8 + 0.05×拍中数（每轮重取）的速度、在 floatV0（每发 += 1.3×floatV7）方向
    ---放 2 发相隔 180° 的小玉（型 3、色 6、匀速），两轮之间 ins_2(10 − 拍中数)（每轮重取）
    ---冻结这么多帧；放满 extraIntV0 发就结束。
    ---Sub8 开头另有一条 ins_101(slot0,VEC,allow0,60,−1,floatV6) 的加速记录，但发弹描述符的
    ---transformFlags = 0x202 里**没有** 0x10 VEC ⇒ 这颗弹永远吃不到它（BulletManager.cpp:525
    ---的 `transformFlags & kind`）—— 原作遗留的空写，照抄。
    ---人偶 160 帧后走 Sub9 退场：先 ins_117(0,−1)/(1,−1) 掐掉 Sub7/Sub8，再
    ---ins_64(60,1,world.x,world.y+64)（floatV0 = enemy.y + 64，ins_25 是**加**）向下落 64 px
    ---（缓动 1 = n²），60 帧后连同敌机一起消失。
    ---数据源 /tmp/th095ecs/ecl6_b.ecs（ECL …/data/ecl6_b.ecl）。骨架：
    ---  · Sub2：ins_141(5) + ins_63(-128,-64) → t=100 ins_64(30,4,0,128) 落 (0,96)
    ---    → t=130 亮卡名 + ins_75(-160,96,160,192) + ins_52("Sub3")。
    ---  · Sub3（160 帧一轮）：extraIntV1=60 / extraIntV2=10（Sub4 都没用到）→
    ---    ins_117(0,"Sub4") → t=60 ins_67(60,4,1.4) + ins_144(15)（快门脉冲，装饰）→
    ---    t=120 ins_0（停 ANM）→ t=160 ins_4(0,Sub3_40) 跳回。
    ---  · Sub4（一次性，无 WAIT）：3 圈，每圈先重抽 floatV0；`ins_83("Sub6")` 生成的子敌机
    ---    继承父上下文的**整份 scriptState（0x80 字节：int/float/extraInt/extraFloat）**。
    ---★ Sub5（另一组「五个角上的人偶」）在 Sub3 里**从来没被调用**（Sub3 只起 slot0 = Sub4）
    ---  ——是死代码，照它写会凭空多出一倍人偶 ⇒ 不实现。
    local BOSS_X, BOSS_START_Y = -128, field_y(-64)
    local HOME_X, HOME_Y = 0, field_y(128)              -- 0 / 96
    local ENTRY_WAIT, ENTRY_TIME = 100, 30
    local EASE_OUT = VALUE_SET.DECEL

    local PHOTO_LIMIT = 5                               -- ins_141(5)
    local CARD_NAME = "操符「ドールズインシー」"
    local CARD_TIME, CARD_HP = 50, 900
    local CARD_ID = 520
    local BOX = { -160, 96, 160, 192 }                  -- ins_75

    local ROUND = 160                                   -- Sub3 一轮（ins_4(0,−72)）
    local MOVE_AT, MOVE_FRAMES, MOVE_EASE, MOVE_SPEED = 60, 60, 4, 1.4
    local DOLL_LIFE = 160                               -- Sub6 的 t=160（ins_52(9)）
    local EXIT_FRAMES, EXIT_DROP = 60, 64               -- Sub9：ins_64(60,1,world.x,world.y+64)

    ---Sub4 的三圈：{半径, 同一对两只的每帧角增量 δ（TH095 弧度、一正一负）}。
    ---δ 直接抄 Sub4 里的字面量：0.03926991 / 0.02617994 / 0.019634955（= 2.25° / 1.5° / 1.125°）。
    local RINGS = { { 40, 0.03926991 }, { 80, 0.02617994 }, { 120, 0.019634955 } }
    local PAIRS, PAIR_STEP = 3, 2.0943952               -- 每圈 3 对、每对 +120°（Sub4 的 ins_15 字面量）

    local ORBIT_FRAMES, GLIDE_FRAMES = 30, 6            -- Sub7 的 ins_36(30,…) / ins_64(6,…)
    local FIRE_GAP0 = 10                                -- 每轮重取：ins_21(ei1, 10, photoIndex)
    local FIRE_ROUNDS0, FIRE_ROUNDS_STEP = 10, 3        -- 进 Sub8 只算一次：ins_22/ins_10(ei0)
    local FIRE_SPEED0, FIRE_SPEED_STEP = 0.8, 0.05      -- floatV1 = photoIndex×0.05 + 0.8
    local VEC_FRAMES = 60                               -- ins_101 的 i1（@2780）
    local VEC_ACC0, VEC_ACC_STEP = 2, 0.3               -- floatV6 = (photoIndex×0.3 + 2)/60
    local TURN_MUL = 1.3                                -- ins_17(floatV7, 1.3)（只在 Sub8 开头做一次）
    ---★ 发弹描述符的 tf 是 **FAST|SND = 0x202**（不含 0x10 VEC）⇒ 上面那条 ins_101 的
    ---  加速记录虽然写进了表，但 BulletManager.cpp:525 的 `transformFlags & kind` 判不过，
    ---  **永远不会被这颗弹吃掉**（原作遗留的空写）。这里照抄：flags 给 0x202。
    local DOLL_FLAGS = 0x202                            -- FAST | SND
    local DOLL_ALPHA = 170

    local st = { dead = false }
    local gen = 0
    local dolls = {}

    ---一只人偶（Sub6/7/8）。v0 = 出生角（TH095 弧度）、v7 = 每帧角增量、radius = 圈半径。
    class.s3b_doll = Class(object, {
        init = function(self, owner, v0, v7, radius)
            self.owner = owner
            self.group = GROUP.GHOST
            self.layer = LAYER.ENEMY_BULLET_EF
            self.colli = false
            self.bound = false
            self.rot = 0
            self._a = 0
            self.x, self.y = owner.x, owner.y
            local mv = { dead = false }
            task.New(self, function()
                local life = 0
                local orbit, fire = v0, v0
                ---Sub8 的 t=0 里只跑一次的 ins_17：floatV7 *= 1.3（回跳点在它**后面**，
                ---所以整支 Sub8 只乘这一回，不是每发都乘）。
                local fv7 = v7 * TURN_MUL
                ---Sub8 的 t=0 里只算一次的轮数（ins_22/ins_10）：拍中数×3 + 10。
                ---（每轮重取的只有 速度 floatV1 和 间隔 10−拍中数，不是这个轮数。）
                local rounds = FIRE_ROUNDS0 + FIRE_ROUNDS_STEP * photo_index(PHOTO_LIMIT)
                ---ins_101 的 floatV6 也在 t=0 只算一次（而且这颗弹根本吃不到，见文件头）。
                local vec_acc = (VEC_ACC0 + VEC_ACC_STEP * photo_index(PHOTO_LIMIT)) / 60
                local fired, next_fire = 0, 0
                while not st.dead and life < DOLL_LIFE do
                    local pi_now = photo_index(PHOTO_LIMIT)
                    ---Sub7：半径 0→radius（ins_36 的 30 帧线性插值 + 缓动 4 = 1−(1−t)²），
                    ---目标 = 本体 + 极坐标(半径, 角度)；每帧重开一次 6 帧缓动 ⇒ 每帧只走
                    ---剩余距离的 1/6。ins_36 只在 Sub7 的 t=0 装一次（回跳点 @2512 在它后面）。
                    local p = min(1, life / ORBIT_FRAMES)
                    local r = radius * (1 - (1 - p) * (1 - p))
                    local ox, oy = sg_off(r, orbit)
                    sg_move(self, mv, owner.x + ox, owner.y + oy, GLIDE_FRAMES, 0)
                    orbit = sg_norm(orbit + v7)
                    ---Sub8：每 (10 − 拍中张数) 帧两发（相隔 180°）；共 拍中数×3 + 10 轮。
                    ---发完一发先记下「下一发在第几帧」= 本帧 + ins_2 的帧数（每轮按当前
                    ---拍中数重取，照抄 ins_21 在循环体内）。原作 ins_2 是**冻结**（th095/src/
                    ---ecl/EclRun.cpp:299 的 secondaryTime），所以两发之间正好差 10−拍中数 帧。
                    if fired < rounds and life >= next_fire then
                        sg_shot(89, sg_style(3), ex_color(6), self.x, self.y,
                                2, 1, FIRE_SPEED0 + FIRE_SPEED_STEP * pi_now, 1.5,
                                math.deg(fire), 0, false, DOLL_FLAGS,
                                sg_tr_hook({ sg_rec(SG_VEC, 0, VEC_FRAMES, -1, vec_acc, -999.99) },
                                        DOLL_FLAGS))
                        fire = sg_norm(fire + fv7)
                        fired = fired + 1
                        next_fire = life + max(0, FIRE_GAP0 - pi_now)
                    end
                    life = life + 1
                    self._a = min(DOLL_ALPHA, self._a + 30)
                    task.Wait(1)
                end
                ---Sub9：停发弹（ins_117(0,−1)/ins_117(1,−1)）、向下落 64 px（60 帧、缓动 1）后消失。
                local x0, y0 = self.x, self.y
                local f = sg_ease(1)
                for s = 1, EXIT_FRAMES do
                    if st.dead then break end
                    local q = f(s / EXIT_FRAMES)
                    self.x, self.y = x0, y0 - EXIT_DROP * q
                    self._a = DOLL_ALPHA * (1 - s / EXIT_FRAMES)
                    task.Wait(1)
                end
                if IsValid(self) then
                    object.RawDel(self)
                end
            end)
        end,
        frame = function(self)
            task.Do(self)                                  -- ★ 驱动环绕 / 发弹 / 退场协程
        end,
        render = function(self)
            SetImageState("butterfly3", "mul+add", self._a, 240, 200, 250)
            Render("butterfly3", self.x, self.y, self.rot, 0.8)
        end,
    })

    ---Sub4：3 圈 × 3 对，同一帧里放完。
    local function spawn3b(owner)
        for k = 1, #RINGS do
            local radius, delta = RINGS[k][1], RINGS[k][2]
            local v = ran:Float(-math.pi, math.pi)
            for _ = 1, PAIRS do
                dolls[#dolls + 1] = New(class.s3b_doll, owner, v, delta, radius)
                dolls[#dolls + 1] = New(class.s3b_doll, owner, v, -delta, radius)
                v = sg_norm(v + PAIR_STEP)
            end
        end
    end

    local function sub3(owner)
        local g = gen
        task.New(owner, function()
            while not st.dead and g == gen do
                spawn3b(owner)
                task.Wait(MOVE_AT)
                if st.dead or g ~= gen then return end
                sg_bmove(owner, st, MOVE_FRAMES, MOVE_EASE, MOVE_SPEED, BOX)
                ---sg_bmove 不阻塞（只起一条插值），所以这里不能减 MOVE_FRAMES。
                task.Wait(ROUND - MOVE_AT)
            end
        end)
    end

    local card = boss.card.New(CARD_NAME, 1, 3, CARD_TIME, CARD_HP)

    function card:before()
        gen = 1
        st.dead = false
        dolls = {}
    end

    function card:init()
        photo_damage_on(self, PHOTO_LIMIT)
        self.x, self.y = BOSS_X, BOSS_START_Y
        st.dead = false
        task.New(self, function()
            task.Wait(ENTRY_WAIT)
            task.MoveTo(HOME_X, HOME_Y, ENTRY_TIME, EASE_OUT)
            sub3(self)
        end)
    end

    function card:frame()
    end

    function card:del()
        st.dead = true
        photo_damage_off(self)
        for i = #dolls, 1, -1 do
            if IsValid(dolls[i]) then
                task.Clear(dolls[i])
                object.RawDel(dolls[i])
            end
        end
        dolls = {}
    end

    boss.card.add({ { card, "20a" } }, LEVEL, CARD_NAME, CARD_ID)
end--操符「ドールズインシー」（ecl6_b）

do  -- 24 アリス 呪符「ストロードールカミカゼ」（ecl6_c，组 20a 第 3 张）
    ---原作是「人偶神风」：本体每 170 帧重开一次 Sub5 —— 每轮在**本体身上**放 5 只人偶
    ---（出膛方向依次 −180° / 0° / −90° / −45° / −135°（TH095），间隔 10 帧），共 2 轮
    ---（ins_5 的计数 2）⇒ 每 170 帧 10 只。
    ---每只人偶的移动（Sub6 主上下文 + Sub8 子上下文）：Sub6 在 t=0 用
    ---ins_65(floatV0, 4) 按**出生方向**设一次 movementMode=POLAR（拍中 ≥3 张改 6）
    ---⇒ 每帧位置 += (cos,sin)·speed，方向不变。Sub8 是同一帧另起的一条子上下文，
    ---它做的事就一句：**每帧检查人偶还在不在场地框内**（TH095 x∈(−192,192)、y≥0），
    ---在框内就什么都不干 —— 那三条 ins_49(enemy.x,−192)/ins_45(enemy.x,192)/
    ---ins_51(enemy.y,0) 是**浮点比较**（>、<、≥；EclRunLow.inl:357 的 case 49 等，
    ---条件成立才跳），不是位移指令。
    ---飞出框那一帧（x≤−192 / x≥192 / y<0）Sub8 走 Sub8_164：ins_65(aimAngle, 3.5/5.5)
    ---把移动方向改成「当场记下的自机角」并 ins_117(1,"Sub7") 开始发弹。
    ---⇒ 人偶是**先直线飞出场外、再掉头以 3.5/5.5 撞向自机**，一边撞一边撒弹。
    ---发弹（Sub7）：ins_101 写 WAIT 60 → VEC 120 两条记录、发弹角 = Sub7 起跑那一帧的
    ---playerAngle（整支 Sub7 fixed）；时间轴是「t=0 发 1 发（型 1 色 13）→ t=2 发 1 发
    ---（型 0 色 12）→ t=4 的 ins_4(0,Sub7_292) 跳回 t=0」⇒ **每 2 帧一发、两型交替**。
    ---弹无初速：先靠 WAIT 定住 60 帧，再用 VEC 加速 120 帧
    ---（拍中 <3 张：1/48 每帧 ⇒ 末速 2.5；≥3 张：0.0375 每帧 ⇒ 末速 4.5）。
    ---人偶寿命 290 帧，之后走 Sub9 退场（停发弹、换 ANM、向下 64 px 落 60 帧后消失）。
    ---拍中第 3 张起本体换成 Sub11：清一次屏 + 重置敌人，之后每 160 帧重开 Sub10
    ---（同一套 5 个方向、间隔缩到 6 帧、计数 3）⇒ 密度翻 1.5 倍。
    ---数据源 /tmp/D95x_ecl6_c.txt（ECL …/data/ecl6_c.ecl）。骨架：
    ---  · Sub2：ins_141(5) + ins_115(0,3,11)（拍中第 3 张换主脚本）+ ins_63(-128,-64)
    ---    → t=100 ins_64(30,4,0,128) 落 (0,96) → t=130 亮卡名 + ins_75(-160,96,160,192)
    ---    + ins_149(1.7) + ins_52(3)。
    ---  · Sub3（@780，170 帧一轮）：extraIntV1=60 / extraIntV2=10（都没用到）→
    ---    ins_117(1,5) → t=60 intV0 = 拍中数/3 + 32（人偶脚本没读，等于空转）→
    ---    t=110 ins_67(60,4,1.4) → t=170 ins_144（快门脉冲，装饰）→ ins_4(0,−104) 跳回 @820。
    ---  · Sub5（@1172）：exF0/exF1 写的四角坐标**没有任何人读**（Sub6 用的是 floatV0
    ---    这个方向），是原作遗留的空写 —— 照抄的话只是白写两个变量，这里不实现。
    ---★ Sub4（@956，另一套「每 10 帧自机狙 3 连」）在 Sub3 里没被调用（Sub3 只起 slot1
    ---  = Sub5）—— 死代码，不实现。
    local BOSS_X, BOSS_START_Y = -128, field_y(-64)
    local HOME_X, HOME_Y = 0, field_y(128)              -- 0 / 96
    local ENTRY_WAIT, ENTRY_TIME = 100, 30
    local EASE_OUT = VALUE_SET.DECEL

    local PHOTO_LIMIT = 5
    local CARD_NAME = "呪符「ストロードールカミカゼ」"
    local CARD_TIME, CARD_HP = 50, 900
    local CARD_ID = 521
    local BOX = { -160, 96, 160, 192 }

    local ROUND = 170                                   -- Sub3 一轮（ins_4(0,−104)）
    local ROUND11 = 160                                 -- Sub11 一轮（ins_4(30,−104)）
    local MOVE_AT, MOVE_FRAMES, MOVE_EASE, MOVE_SPEED = 110, 60, 4, 1.4
    local SWITCH_AT = 3                                 -- ins_115(0,3,11)

    ---Sub5 / Sub10：5 个出生方向（TH095 弧度，依次 180°/0°/90°/45°/135°，符号见 dump）与间隔。
    local DIRS5 = { -math.pi, 0, -math.pi / 2, -math.pi / 4, -math.pi * 3 / 4 }
    local SPOT_GAP, SPOT_ROUNDS = 10, 2                 -- Sub5
    local SPOT_GAP2, SPOT_ROUNDS2 = 6, 3                -- Sub10

    local DOLL_LIFE = 290                               -- Sub6 的 t=290（ins_52(9)）
    local EXIT_FRAMES, EXIT_DROP = 60, 64
    local FLY_SPEED, FLY_SPEED_FAST = 4, 6              -- ins_65(floatV0, 4/6)（Sub6 t=0）
    local DASH_SPEED, DASH_SPEED_FAST = 3.5, 5.5        -- Sub8 的 ins_65(playerAngle, …)
    ---Sub8 的场地框（TH095 坐标，见 PhotoBulletIsOutsidePlayfield 用的同四个边界）：
    ---x≤−192 / x≥192 / y<0 任一成立就飞出去了 ⇒ 换冲刺方向、起 Sub7。
    local FIELD_L, FIELD_R, FIELD_T = -192, 192, 0
    local WAIT_FRAMES = 60                              -- Sub7 的 WAIT 记录
    local VEC_FRAMES = 120
    local VEC_ACC_SLOW, VEC_ACC_FAST = 0.020833334, 0.0375
    local FIRE_FLAGS = 0x8212                           -- FAST | VEC | SND | WAIT
    local EXIT_WAIT = 1

    local PHOTO_SLOW = 3                                -- ins_50(photoIndex, 3) 的分界
    local DOLL_ALPHA = 170

    local st = { dead = false }
    local gen = 0
    local phase = 1                                     -- 1 = Sub3，2 = Sub11
    local dolls = {}
    local lasers = {}

    ---一只人偶（Sub6 主 + Sub8 移动 + Sub7 发弹）。dir_th = 出生方向（TH095 弧度）。
    ---★ 帧序照原作：ECL 先跑指令、**帧尾**才 UpdateMovement（EclRun.cpp:450 的
    ---  enemy->UpdateMovement()）⇒ 本帧的「守卫判定 / 发弹」用的是上一帧末尾的位置，
    ---  位移在本帧末尾才生效。协程里也按这个顺序写（先判定+发弹、再挪位置）。
    ---★ Sub6 的 ins_65(floatV0, 4/6) 只设一次方向与速度；出框后 Sub8 的
    ---  ins_65(playerAngle, 3.5/5.5) 把 movementAngle/speed **整个换掉**。
    ---★ Sub7 的 ins_101 记录、`floatV0 = playerAngle`、VEC 加速度都在出框那一帧
    ---  （Sub7 的 t=0）取一次，之后整支 Sub7 只重复「每 2 帧一发、型 1/型 0 交替」。
    class.s3c_doll = Class(object, {
        init = function(self, owner, dir_th)
            self.owner = owner
            self.group = GROUP.GHOST
            self.layer = LAYER.ENEMY_BULLET_EF
            self.colli = false
            self.bound = false
            self.rot = -math.deg(dir_th) + 90
            self._a = 0
            self.x, self.y = owner.x, owner.y
            task.New(self, function()
                ---Sub6 的 ins_65(floatV0, 4/6)：**出生方向** + 速度（t=0 取一次）。
                ---ins_65 设的是 movementMode=POLAR ⇒ 每帧 position += (cosθ,sinθ)·speed。
                local fly = (photo_index(PHOTO_LIMIT) >= PHOTO_SLOW)
                        and FLY_SPEED_FAST or FLY_SPEED
                local vx = fly * math.cos(dir_th)          -- TH095 的 x 分量
                local vy = -fly * math.sin(dir_th)         -- TH095 的 +y 是我们的 −y
                ---Sub8_164 / Sub7 的 t=0 都在**出框那一帧**取一次，先留空。
                local firing, sub7 = false, 0
                local dash_vx, dash_vy, fire_a, hook = 0, 0, 0, nil
                local life = 0
                while not st.dead and life < DOLL_LIFE do
                    ---① Sub8_0..Sub8_144 的守卫链：只要还在场地框内就什么也不做。
                    ---   （TH095 的边界：x ∈ (−192,192)、y ≥ 0；三条 ins_49/45/51 是
                    ---   浮点 >、<、≥ 的比较，EclRunLow.inl:357。）
                    if not firing then
                        local thx, thy = self.x, FIELD_HALF_H - self.y
                        if thx <= FIELD_L or thx >= FIELD_R or thy < FIELD_T then
                            ---② Sub8_164：换成「朝自机」的冲刺（记下此刻的自机角）并起 Sub7。
                            local dash_fast = photo_index(PHOTO_LIMIT) >= PHOTO_SLOW
                            local dash = dash_fast and DASH_SPEED_FAST or DASH_SPEED
                            fire_a = sg_aim(self.x, self.y)
                            dash_vx = dash * math.cos(math.rad(fire_a))
                            dash_vy = -dash * math.sin(math.rad(fire_a))
                            ---Sub7 的 ins_101：WAIT 60 帧 → VEC 120 帧
                            ---（拍中 ≥3 张改用 0.0375/帧）。
                            local acc = dash_fast and VEC_ACC_FAST or VEC_ACC_SLOW
                            hook = sg_tr_hook({
                                sg_rec(SG_WAIT, 0, WAIT_FRAMES, -1, -1, -1),
                                sg_rec(SG_VEC, 0, VEC_FRAMES, -1, acc, -999.99),
                            }, FIRE_FLAGS)
                            self.rot = -fire_a + 90
                            firing, sub7 = true, 0
                        end
                    end
                    ---③ Sub7：t=0 发型 1 色 13、t=2 发型 0 色 12、t=4 跳回 t=0
                    ---   ⇒ 每 2 帧一发、两型交替。发弹角整支 Sub7 固定用 fire_a。
                    if firing and sub7 % 2 == 0 then
                        if (sub7 / 2) % 2 == 0 then
                            sg_shot(89, sg_style(1), ex_color(13), self.x, self.y,
                                    1, 1, 0, 1, fire_a, 0, false, FIRE_FLAGS, hook)
                        else
                            sg_shot(89, sg_style(0), ex_color(12), self.x, self.y,
                                    1, 1, 0, 1, fire_a, 0, false, FIRE_FLAGS, hook)
                        end
                    end
                    sub7 = sub7 + 1
                    ---④ 帧尾的位移（UpdateMovement）：出框前按出生方向、出框后按自机角。
                    if firing then
                        self.x, self.y = self.x + dash_vx, self.y + dash_vy
                    else
                        self.x, self.y = self.x + vx, self.y + vy
                    end
                    life = life + 1
                    self._a = min(DOLL_ALPHA, self._a + 30)
                    task.Wait(1)
                end
                ---Sub9：停发弹、换 ANM、向下落 64 px（60 帧、缓动 1）后消失。
                if st.dead then
                    if IsValid(self) then object.RawDel(self) end
                    return
                end
                local x1, y1 = self.x, self.y
                local f = sg_ease(EXIT_WAIT)
                for s2 = 1, EXIT_FRAMES do
                    if st.dead then break end
                    local q = f(s2 / EXIT_FRAMES)
                    self.x, self.y = x1, y1 - EXIT_DROP * q
                    self._a = DOLL_ALPHA * (1 - s2 / EXIT_FRAMES)
                    task.Wait(1)
                end
                if IsValid(self) then
                    object.RawDel(self)
                end
            end)
        end,
        frame = function(self)
            task.Do(self)                                  -- ★ 驱动环绕 / 发弹 / 退场协程
        end,
        render = function(self)
            SetImageState("butterfly4", "mul+add", self._a, 235, 205, 255)
            Render("butterfly4", self.x, self.y, self.rot, 0.85)
        end,
    })

    ---Sub5 / Sub10：一套「5 个方向、每个间隔 gap、共 rounds 轮」的人偶。
    local function spawn_spot_dolls(owner, gap, rounds)
        task.New(owner, function()
            local g = gen
            for _ = 1, rounds do
                for k = 1, #DIRS5 do
                    if st.dead or g ~= gen then return end
                    dolls[#dolls + 1] = New(class.s3c_doll, owner, DIRS5[k])
                    task.Wait(gap)
                end
            end
        end)
    end

    ---Sub3：170 帧一轮（ins_117 重开 Sub5 + 随机挪位）。sg_bmove 不阻塞，别减 MOVE_FRAMES。
    local function sub3(owner)
        local g = gen
        task.New(owner, function()
            while not st.dead and g == gen and phase == 1 do
                spawn_spot_dolls(owner, SPOT_GAP, SPOT_ROUNDS)
                task.Wait(MOVE_AT)
                if st.dead or g ~= gen or phase ~= 1 then return end
                sg_bmove(owner, st, MOVE_FRAMES, MOVE_EASE, MOVE_SPEED, BOX)
                task.Wait(ROUND - MOVE_AT)
            end
        end)
    end

    ---Sub11：拍中第 3 张后接管主脚本（清屏 + 重置敌人 → 每 160 帧重开 Sub10）。
    local function sub11(owner)
        local g = gen
        phase = 2
        task.New(owner, function()
            task.Wait(30)
            if st.dead or g ~= gen then return end
            for i = #dolls, 1, -1 do
                if IsValid(dolls[i]) then
                    task.Clear(dolls[i])
                    object.RawDel(dolls[i])
                end
                dolls[i] = nil
            end
            sg_clear(lasers)                               -- ins_102
            ---Sub11 的时间轴：t=30 起 Sub10 → t=90 挪位 → t=150 快门 → t=190 跳回 t=30。
            ---（sub11 从 ins_115 触发那一刻算 t=0，先等 30 帧。）之后每 160 帧一轮。
            while not st.dead and g == gen do
                spawn_spot_dolls(owner, SPOT_GAP2, SPOT_ROUNDS2)
                task.Wait(60)
                if st.dead or g ~= gen then return end
                sg_bmove(owner, st, MOVE_FRAMES, MOVE_EASE, MOVE_SPEED, BOX)
                task.Wait(ROUND11 - 60)
            end
        end)
    end

    local card = boss.card.New(CARD_NAME, 1, 3, CARD_TIME, CARD_HP)

    function card:before()
        gen = 1
        phase = 1
        st.dead = false
        dolls = {}
        lasers = {}
    end

    function card:init()
        photo_damage_on(self, PHOTO_LIMIT)
        self.x, self.y = BOSS_X, BOSS_START_Y
        st.dead = false
        task.New(self, function()
            task.Wait(ENTRY_WAIT)
            task.MoveTo(HOME_X, HOME_Y, ENTRY_TIME, EASE_OUT)
            sub3(self)
            task.New(self, function()                   -- ins_115(0,3,11) 的监视器
                while not st.dead do
                    if photo_index(PHOTO_LIMIT) >= SWITCH_AT then
                        gen = gen + 1
                        sub11(self)
                        return
                    end
                    task.Wait(1)
                end
            end)
        end)
    end

    function card:frame()
    end

    function card:del()
        st.dead = true
        photo_damage_off(self)
        for i = #dolls, 1, -1 do
            if IsValid(dolls[i]) then
                task.Clear(dolls[i])
                object.RawDel(dolls[i])
            end
        end
        dolls = {}
        sg_clear(lasers)
    end

    boss.card.add({ { card, "20a" } }, LEVEL, CARD_NAME, CARD_ID)
end--呪符「ストロードールカミカゼ」（ecl6_c）

do  -- 26 アリス 赤符「ドールミラセティ」（ecl6_d，组 20a 第 4 张）
    ---原作是「人偶在四角落放自机狙大玉」：本体每 362 帧一轮 ——
    ---一轮里 ①每 10 帧放一圈 3 发（型 7、色 2、速 1.5、基准角 = 当时的自机角，
    ---所以三个方向是「朝自机 ±120°」）；②t=140 再放一大圈 `拍中数×3 + 32` 发 × 2 圈
    ---（第二圈整体 +11.25°、初速 2 → 1.5）；③重开 Sub5：每轮 5 只人偶、间隔 4 帧
    ---（ins_5(16,−20,10) 的回跳点在「floatV1 += 0.3」那句，后 9 轮不再放人偶）。
    ---每只人偶：先 30 帧线性挪到自己的角落（Sub5 用 exF0/exF1 写的绝对坐标；
    ---发弹的 Sub7 与这次挪位**同帧起**），Sub7 的**第一发在 t=20**、之后每
    ---(36 − 拍中数×3) 帧朝自机放**一发**大玉（型 17、色 0、速 4，ins_88 CIRC_AIMED）；
    ---寿命 290 帧后走 Sub8 退场（停发弹、向下 64 px 落 60 帧后消失）。
    ---Sub4 那支圈弹的基准角只在它自己的 t=0 取一次 aimAngle，之后每轮只 +11.25°。
    ---数据源 /tmp/D95x_ecl6_d.txt（ECL …/data/ecl6_d.ecl）。骨架：
    ---  · Sub2：ins_141(5) + ins_63(-128,-64) → t=100 ins_64(30,4,0,128) 落 (0,96)
    ---    → t=130 亮卡名 + ins_75(-160,96,160,192) + ins_149(2) + ins_52(3)。
    ---  · Sub3（@744，362 帧一轮）：extraIntV1=60 / extraIntV2=10 → ins_117(0,4)（Sub4 圈弹）
    ---    + ins_117(1,5)（Sub5 人偶）→ t=140 `intV0 = 拍中数/3 + 32` + 大圈 →
    ---    t=172/282 ins_144（快门脉冲，装饰）→ t=222 ins_67(60,4,1.4) → t=312 ins_0（停 ANM）
    ---    → t=362 ins_4(0,−176) 跳回 **@804**（Sub4 的 ins_117(0,4) 在 @784、**不在**循环里
    ---    ⇒ 12 位「角落人偶」只有第一轮有）。
    ---  · Sub7 的 `floatV6`（拍中数×0.3+2）÷60 和 `floatV0 -= floatV7` 之后都没人读
    ---    （这一支的 88 号发弹用的是 aim 角、且没写 ins_101）—— 原作遗留，不实现。
    local BOSS_X, BOSS_START_Y = -128, field_y(-64)
    local HOME_X, HOME_Y = 0, field_y(128)              -- 0 / 96
    local ENTRY_WAIT, ENTRY_TIME = 100, 30
    local EASE_OUT = VALUE_SET.DECEL

    local PHOTO_LIMIT = 5
    local CARD_NAME = "赤符「ドールミラセティ」"
    local CARD_TIME, CARD_HP = 50, 900
    local CARD_ID = 522
    local BOX = { -160, 96, 160, 192 }

    local ROUND = 362
    local RING_AT = 140                                 -- t=140 的大圈
    ---intV0 = photoIndex×3 + 32（ins_22 是**乘法**：ins_22 = a×b、ins_23 才是 a/b）。
    local RING_ADD, RING_MUL = 32, 3
    local MOVE_AT, MOVE_FRAMES, MOVE_EASE, MOVE_SPEED = 222, 60, 4, 1.4

    ---Sub4：每 10 帧一圈 3 发（型 7、色 2、速 1.5、基准角 = 自机角）。
    local RING_GAP = 10
    local RING_N, RING_SPEED, RING_STYLE_T, RING_COLOR = 3, 1.5, 7, 2

    ---Sub5：5 个出生方向 + 10 轮 × 6 帧。
    local DIRS5 = { -math.pi, 0, -math.pi / 2, -math.pi / 4, -math.pi * 3 / 4 }
    ---五只人偶的落脚点 = Sub5 写进 exF0/exF1 的**绝对**（TH095）坐标。
    local CORNERS = { { -160, 96 }, { 80, 64 }, { 160, 96 }, { -80, 64 }, { 0, 48 } }
    ---Sub5 的 5 个 ins_83 在 t=0/4/8/12/16 —— 每轮只放 5 只；ins_5(16,−20,10) 的回跳点是
    ---「floatV1 += 0.3」那句（@1572），**不含** spawn 段 ⇒ 后 9 轮不再放人偶（原作如此）。
    local SPOT_GAP, SPOT_ROUNDS = 4, 1
    local DOLL_MOVE_FRAMES = 30                         -- Sub6 的 ins_64(30,0,…)

    local DOLL_LIFE = 290
    local EXIT_FRAMES, EXIT_DROP = 60, 64
    ---extraIntV0 = 36 − photoIndex×3（ins_21 是减法、ins_22 是乘法），每次发弹重算。
    local FIRE_GAP0, FIRE_GAP_MUL = 36, 3
    local BALL_STYLE_T, BALL_SPEED = 17, 4
    local DOLL_ALPHA = 180

    local st = { dead = false }
    local gen = 0
    local dolls = {}

    ---一只角落人偶（Sub6 + Sub7）。
    class.s3d_doll = Class(object, {
        init = function(self, owner, tx, ty)
            self.owner = owner
            self.group = GROUP.GHOST
            self.layer = LAYER.ENEMY_BULLET_EF
            self.colli = false
            self.bound = false
            self.rot = 0
            self._a = DOLL_ALPHA
            self.x, self.y = owner.x, owner.y
            task.New(self, function()
                ---Sub6 的 ins_64(30,0,ef0,ef1)：从出生点用 30 帧**线性**挪到角落
                ---（movementMode=2，EnemyMovement.cpp:96 的 progress = 1 − timer/30）。
                local x0, y0 = self.x, self.y
                ---Sub7（与 Sub6 同帧起的子上下文）：t=0 只写没人读的 floatV3/V6/V7，
                ---第一发在 **t=20**（`+20: //20` 那条 WAIT，回跳点 @Sub7_104 在它之后），
                ---之后每 (36 − 拍中数×3) 帧一发（ins_22/ins_21，每次发弹重算）。
                local life = 0
                local next_at = 20
                while not st.dead and life < DOLL_LIFE do
                    ---① 本帧的发弹（用**位移之前**的位置：ECL 的 UpdateMovement 在帧尾）。
                    if next_at <= 0 then
                        sg_shot(88, sg_style(BALL_STYLE_T), ex_color(0), self.x, self.y,
                                1, 1, BALL_SPEED, 1, 0, 0, true, 0x202)
                        next_at = FIRE_GAP0 - FIRE_GAP_MUL * photo_index(PHOTO_LIMIT)
                    end
                    next_at = next_at - 1
                    ---② 帧尾：Sub6 的 30 帧线性挪位（到点后就停住不动）。
                    if life < DOLL_MOVE_FRAMES then
                        local p = (life + 1) / DOLL_MOVE_FRAMES
                        self.x, self.y = x0 + (tx - x0) * p, y0 + (ty - y0) * p
                    end
                    life = life + 1
                    task.Wait(1)
                end
                ---Sub8：向下落 64 px（60 帧、缓动 1）后消失。
                local x1, y1 = self.x, self.y
                local f = sg_ease(1)
                for s = 1, EXIT_FRAMES do
                    if st.dead then break end
                    local q = f(s / EXIT_FRAMES)
                    self.x, self.y = x1, y1 - EXIT_DROP * q
                    self._a = DOLL_ALPHA * (1 - s / EXIT_FRAMES)
                    task.Wait(1)
                end
                if IsValid(self) then
                    object.RawDel(self)
                end
            end)
        end,
        frame = function(self)
            task.Do(self)                                  -- ★ 驱动环绕 / 发弹 / 退场协程
        end,
        render = function(self)
            SetImageState("butterfly6", "mul+add", self._a, 240, 170, 250)
            Render("butterfly6", self.x, self.y, self.rot, 0.9)
        end,
    })

    ---Sub4：每 10 帧一圈 3 发。★ 基准角 floatV0 只在 Sub4 的 t=0 取**一次**
    ---（`ins_7(f0, aimAngle)` 在回跳点 @Sub4_60 **之前**），之后每轮
    ---`ins_15(f0, 0.19634955)` + `ins_37(f0)` 只把它 +11.25° 并归一化 ——
    ---**不是**每轮重新瞄自机。ten 轮下来整圈会慢慢转起来。
    local function sub4(owner)
        task.New(owner, function()
            local a = math.rad(sg_aim(owner.x, owner.y))    -- Sub4 t=0 的 aimAngle（TH095 弧度）
            while not st.dead do
                sg_shot(89, sg_style(RING_STYLE_T), ex_color(RING_COLOR), owner.x, owner.y,
                        RING_N, 1, RING_SPEED, 1.5, math.deg(a), 0, false, 0x202)
                a = sg_norm(a + 0.196349546)               -- ins_15 + ins_37
                task.Wait(RING_GAP)
            end
        end)
    end

    ---Sub5：5 只人偶（间隔 6 帧 ×10 轮），每人偶带自己的角落坐标。
    local function sub5(owner)
        task.New(owner, function()
            local g = gen
            for _ = 1, SPOT_ROUNDS do
                for k = 1, #DIRS5 do
                    if st.dead or g ~= gen then return end
                    local c = CORNERS[k]
                    dolls[#dolls + 1] = New(class.s3d_doll, owner, c[1], field_y(c[2]))
                    task.Wait(SPOT_GAP)
                end
            end
        end)
    end

    ---Sub3：362 帧一轮。
    local function sub3(owner)
        local g = gen
        task.New(owner, function()
            while not st.dead and g == gen do
                sub5(owner)
                task.Wait(RING_AT)
                if st.dead or g ~= gen then return end
                sg_shot(89, sg_style(RING_STYLE_T), ex_color(RING_COLOR), owner.x, owner.y,
                        RING_MUL * photo_index(PHOTO_LIMIT) + RING_ADD, 2, 2, 1,
                        sg_aim(owner.x, owner.y), math.deg(0.196349546), false, 0x202)
                task.Wait(MOVE_AT - RING_AT)
                if st.dead or g ~= gen then return end
                sg_bmove(owner, st, MOVE_FRAMES, MOVE_EASE, MOVE_SPEED, BOX)
                task.Wait(ROUND - MOVE_AT)
            end
        end)
    end

    local card = boss.card.New(CARD_NAME, 1, 3, CARD_TIME, CARD_HP)

    function card:before()
        gen = 1
        st.dead = false
        dolls = {}
    end

    function card:init()
        photo_damage_on(self, PHOTO_LIMIT)
        self.x, self.y = BOSS_X, BOSS_START_Y
        st.dead = false
        task.New(self, function()
            task.Wait(ENTRY_WAIT)
            task.MoveTo(HOME_X, HOME_Y, ENTRY_TIME, EASE_OUT)
            sub4(self)
            sub3(self)
        end)
    end

    function card:frame()
    end

    function card:del()
        st.dead = true
        photo_damage_off(self)
        for i = #dolls, 1, -1 do
            if IsValid(dolls[i]) then
                task.Clear(dolls[i])
                object.RawDel(dolls[i])
            end
        end
        dolls = {}
    end

    boss.card.add({ { card, "20a" } }, LEVEL, CARD_NAME, CARD_ID)
end--赤符「ドールミラセティ」（ecl6_d）

do  -- 21 上白沢慧音 光符「アマテラス」（ecl5_a，组 21a 第 1 张）
    ---原作是「天照」：本体在框里每 215 帧挪 60 px；Sub3 每轮 `ins_117(0,"Sub4")`
    ---把子上下文**先 free 再重建**（EclRunTargetHigh.inl:206）⇒ Sub4 每 215 帧从
    ---t=0 重来一次（所以它自己那点 4+拍中数 轮常常跑不完就被掐掉）。
    ---Sub4 每 40 帧放「两批 16 根」直线激光：一批色 6、角 = 自机角 + k×22.5°、速 floatV2；
    ---20 帧后同一圈再放一批色 2、整体多转 11.25°（正好插在上一批的缝里）。
    ---每批 16 根**在同一帧**发完（ins_5 循环的 time 相同 ⇒ 一帧内跑完）；
    ---每轮的轮数 = 4 + 拍中张数（ins_20 = a+b，EclRunLow.inl:311），每跑完一轮
    ---`ins_15(f2, f3)` ⇒ 下一轮的激光初速再 +0.5（floatV2 是累加，不是赋值）。
    ---数据源 /tmp/D95x_ecl5_a.txt（ECL …/data/ecl5_a.ecl）。骨架：
    ---  · Sub2：… ins_141(5)（拍 5 张）+ ins_63(-128,-64) → t=100 ins_64(30,4,0,128)
    ---    落到 (0,128)（我们的 (0,96)）→ t=130 亮卡名 + ins_75(-160,96,160,192)
    ---    + ins_149(1.4) + ins_52(3) 起 Sub3。
    ---  · Sub3（@716，215 帧一轮）：extraIntV0 = 4 − 拍中张数（**Sub4 的循环数**）→
    ---    ins_117(0,4) 起 Sub4 → t=120 ins_144（快门脉冲，装饰）→ t=135 ins_67(60,4,1)
    ---    → t=215 ins_4(0,−96) 跳回 @716。
    ---  · Sub4（@844）：floatV1=0.5、floatV2=2（激光速度，**每轮 +0.5**）、floatV3=0.5、
    ---    ins_106(24)（一声）→ floatV0 = playerAngle（**每批重读**）→ ins_106(16)
    ---    → 16 根 ins_145(型 1、色 6、速 floatV2、角 floatV0、长 192、宽 8)，
    ---      出膛偏移 = 沿该角 8 px（ins_38 + ins_100）；每根后 floatV0 += 0.392699（22.5°）；
    ---    t=20 再一批 16 根（色 2）、floatV0 先 +0.19635（11.25°）、floatV2 += 0.5；
    ---    t=40 ins_5(0,−404,extraIntV0)：循环数 −1，>0 就跳回 @928（time=0）重来。
    ---★ 原作 145 的判定还多一道 width > 40 的闸（PhotoEffect.cpp:252）—— 这张的宽只有 8，
    ---  照搬就一根都打不到人；按 Stage 9 已写下的口径，145 和 147 一样在 length > 16 时判定。
    local BOSS_X, BOSS_START_Y = -128, field_y(-64)
    local HOME_X, HOME_Y = 0, field_y(128)              -- 0 / 96
    local ENTRY_WAIT, ENTRY_TIME = 100, 30
    local EASE_OUT = VALUE_SET.DECEL

    local PHOTO_LIMIT = 5                               -- ins_141(5)
    local CARD_NAME = "光符「アマテラス」"
    local CARD_TIME, CARD_HP = 50, 900
    local CARD_ID = 523
    local BOX = { -160, 96, 160, 192 }                  -- ins_75

    local ROUND = 215                                   -- Sub3 一轮的周期（ins_4(0,−96)）
    local PULSE_AT = 120                                -- ins_144（装饰）
    local MOVE_AT, MOVE_FRAMES, MOVE_EASE, MOVE_SPEED = 135, 60, 4, 1

    local BEAMS = 16                                    -- 每批 16 根
    ---★ 这两个值在 ECL 里本来就是**弧度**（ins_15 的 0.3926991 rad = 22.5°，
    ---0.19634955 rad = 11.25°），base 也是弧度 ⇒ 直接相加，别再套 math.rad
    ---（套了会变成 0.39°、整圈缩成 6°，16 根激光全挤在一条线上）。
    local BEAM_STEP = 0.392699093                       -- 每根 +22.5°（TH095 弧度）
    local BEAM_STEP2 = 0.196349546                      -- 第二批整体 +11.25°（TH095 弧度）
    local BEAM_LEN, BEAM_WIDTH, BEAM_OFF = 192, 8, 8    -- ins_145 的长度/宽度、ins_38 的半径
    local SPEED0, SPEED_STEP, PASS_GAP = 2, 0.5, 20     -- floatV2 / floatV3 / 两批间隔
    local ROUNDS0 = 4                                   -- extraIntV0 = 4 + 拍中张数（ins_20 是**加**）
    local CYCLE = 40                                    -- 一轮 40 帧
    local BEAM_COLOR_A, BEAM_COLOR_B = 6, 2             -- 两批的 ins_145 色号（= laser 贴图行）

    local lasers = {}
    local st = { dead = false }
    local sub4_gen = 0                                  -- ins_117 的「先 free 再建」代号

    ---Sub4：一轮 40 帧、两批 16 根（同一帧内发完）。
    ---★ Sub3 每 215 帧 `ins_117(0,"Sub4")` 会把上一支 Sub4 **直接 free 掉**重建；
    ---  而 40×(4+拍中数) 最多 360 帧 > 215 ⇒ 拍中 2 张以后旧的那支本来就会被掐掉。
    ---  这里用 sub4_gen 复刻这次掐断，否则旧任务会和新任务同时发弹（弹数翻倍）。
    local function sub4(owner)
        sub4_gen = sub4_gen + 1
        local my = sub4_gen
        task.New(owner, function()
            local speed = SPEED0
            for _ = 1, ROUNDS0 + photo_index(PHOTO_LIMIT) do
                if st.dead or my ~= sub4_gen then return end
                local base = -math.rad(Angle(owner.x, owner.y, player.x, player.y))
                for k = 0, BEAMS - 1 do
                    local a = base + k * BEAM_STEP
                    local ox, oy = sg_off(BEAM_OFF, a)
                    spawn_ex_laser_straight(owner, lasers, BEAM_COLOR_A, owner.x + ox, owner.y + oy,
                            -math.deg(a), BEAM_LEN, BEAM_WIDTH, speed)
                end
                PlaySound("tan00", 0.1, owner.x / 256, false)   -- ins_106
                task.Wait(PASS_GAP)
                if st.dead or my ~= sub4_gen then return end
                base = base + BEAM_STEP2
                for k = 0, BEAMS - 1 do
                    local a = base + k * BEAM_STEP
                    local ox, oy = sg_off(BEAM_OFF, a)
                    spawn_ex_laser_straight(owner, lasers, BEAM_COLOR_B, owner.x + ox, owner.y + oy,
                            -math.deg(a), BEAM_LEN, BEAM_WIDTH, speed)
                end
                PlaySound("tan00", 0.1, owner.x / 256, false)
                speed = speed + SPEED_STEP
                task.Wait(CYCLE - PASS_GAP)
            end
        end)
    end

    local function sub3(owner)
        task.New(owner, function()
            while not st.dead do
                sub4(owner)
                task.Wait(PULSE_AT)
                if st.dead then return end
                task.Wait(MOVE_AT - PULSE_AT)
                if st.dead then return end
                sg_bmove(owner, st, MOVE_FRAMES, MOVE_EASE, MOVE_SPEED, BOX)
                task.Wait(ROUND - MOVE_AT)
            end
        end)
    end

    local card = boss.card.New(CARD_NAME, 1, 3, CARD_TIME, CARD_HP)

    function card:before()
        lasers = {}
    end

    function card:init()
        photo_damage_on(self, PHOTO_LIMIT)
        self.x, self.y = BOSS_X, BOSS_START_Y
        st.dead = false
        task.New(self, function()
            task.Wait(ENTRY_WAIT)
            task.MoveTo(HOME_X, HOME_Y, ENTRY_TIME, EASE_OUT)
            sub3(self)
        end)
    end

    function card:frame()
    end

    function card:del()
        st.dead = true
        photo_damage_off(self)
        sg_clear(lasers)
    end

    boss.card.add({ { card, "21a" } }, LEVEL, CARD_NAME, CARD_ID)
end--光符「アマテラス」（ecl5_a）

do  -- 23 上白沢慧音 包符「昭和の雨」（ecl5_b，组 21a 第 2 张）
    ---原作是「昭和的雨」：本体在框里挪 60 px，一条上下文从**本体附近的随机点**朝自机打
    ---64 px 的短直线激光，下一根来得越来越快（间隔 = 31 − 5×拍中张数 ⇒ 拍满 6 张每帧一根）；
    ---另一条上下文在每 314 帧里放两轮 24 发大扇 —— 基准角 = 自机角 + 180°、
    ---step = 0.241661 rad、初速 1 起每发 +0.3、共 10 发、每 7 帧一发。
    ---数据源 /tmp/D95x_ecl5_b.txt（ECL …/data/ecl5_b.ecl）。骨架：
    ---  · Sub2：ins_141(6) + ins_63(-128,-64) → t=100 ins_64(30,4,0,128) 落到 (0,128)
    ---    （我们的 (0, field_y(128)) = (0,96)）→ t=130 亮卡名 + ins_75(-160,96,160,192)
    ---    + ins_149(1.5) + ins_52(3)。
    ---  · Sub3（@732，**314 帧**一轮）：t=0 起 slot0 的 Sub4 与 slot1 的 Sub5 ——
    ---    t=314 的 ins_4(0,−96) 跳回 **@792 的 ins_117(1,5)**（不是 @772 的 slot0）
    ---    ⇒ Sub4 只起一次、Sub5 每轮重开；t=72/224 的 ins_144(15) 是快门脉冲（装饰）；
    ---    t=152 再 ins_117(1,5) 重开一次 Sub5；t=274 的 ins_67(60,4,1.4) 挪 60 px。
    ---  · Sub4（@920）：ins_101(0,1,0,−1,−1,−1,−1) 写一条 DECEL 记录（这张卡的弹
    ---    flags = 0x202 = FAST|SND、不含 0x1 ⇒ 这条记录全程不生效）；
    ---    floatV0 = randF32s×96（半径，可为负）；ins_38(exF0,exF1, rand(−π,π), floatV0)
    ---    + ins_18(exF1 ÷ 2) + ins_100 ⇒ 出膛点 = 本体 + (r·cosθ, −(r·sinθ)/2)（本仓库坐标）；
    ---    ins_106(16)（音效）→ ins_146(型 1、色 6、速 4、**角 = 原始角 0 + 自机角**、长 64、宽 8)；
    ---    floatV0 += 0.392699（下一轮开头被 ins_27 覆盖，死代码）；
    ---    extraIntV2 = photoIndex×5（ins_22 乘）→ extraIntV2 = 31 − extraIntV2（ins_21 减）
    ---    → ins_2 冻结 → ins_4(0,−228) 跳回 @960 ⇒ **周期 = 31 − 5×拍中张数 帧**
    ---    （ins_4 的 time 操作数是 0 ⇒ 冻几帧就隔几帧；−228 只是字节偏移，别当成 228 帧）。
    ---  · Sub5（@1232）：一轮 10 发、每 7 帧一发（ins_5 的 t=7、跳回 @1312）：
    ---    FAN_AIMED(型 3、色 8、count1 = 24、count2 = 1、速 floatV1 = 1 起每轮 +0.3、
    ---    基准角 π、step = 0.241661 rad) ⇒ 24 发铺开约 319°、整体朝自机反方向甩。
    ---    10 发打完（ins_5 计数到 0 不跳）落到 @1420 的 ins_53 自灭。
    local BOSS_X, BOSS_START_Y = -128, field_y(-64)
    local HOME_X, HOME_Y = 0, field_y(128)              -- 0 / 96
    local ENTRY_WAIT, ENTRY_TIME = 100, 30
    local EASE_OUT = VALUE_SET.DECEL

    local PHOTO_LIMIT = 6                               -- ins_141(6)
    local CARD_NAME = "包符「昭和の雨」"
    local CARD_TIME, CARD_HP = 50, 900
    local CARD_ID = 524
    local BOX = { -160, 96, 160, 192 }                  -- ins_75

    local ROUND = 314                                   -- Sub3 一轮（ins_4(0,−96)）
    local BURST2_AT, MOVE_AT = 152, 274                 -- Sub5 第二轮 / ins_67
    local MOVE_FRAMES, MOVE_EASE, MOVE_SPEED = 60, 4, 1.4

    local RAIN_R = 96                                   -- ins_27 的乘数
    local RAIN_GAP, RAIN_STEP = 31, 5                   -- ins_2 的 31 − 5×拍中张数
    local RAIN_LEN, RAIN_W, RAIN_SPEED, RAIN_ROW = 64, 8, 4, 6

    local FAN_ROUNDS = 10                               -- extraIntV0
    local FAN_COUNT, FAN_STEP = 24, math.deg(0.241660967)
    local FAN_BASE = math.deg(math.pi)                  -- 基准角 π（TH095 度）
    local FAN_SPEED0, FAN_SPEED_STEP, FAN_SPEED2 = 1, 0.3, 1.5
    local FAN_GAP = 7                                   -- ins_5 的 t=7

    local lasers = {}
    local st = { dead = false }

    ---Sub4：每 (31 − 5×拍中张数) 帧一根朝自机的 64 px 短直线激光。
    local function sub4(owner)
        task.New(owner, function()
            while not st.dead do
                local r = ran:Float(-1, 1) * RAIN_R             -- ins_27：randF32s × 96
                local th = ran:Float(-math.pi, math.pi)         -- ins_38 的极角
                local ox, oy = sg_off(r, th)                    -- ins_38
                local x, y = owner.x + ox, owner.y + oy * 0.5   -- ins_18：exF1 ÷ 2
                PlaySound("tan00", 0.1, x / 256, false)         -- ins_106(16)
                ---ins_146 的角 = 原始角 0 + 自机角（EclRunTargetPhoto.inl:21-36）。
                spawn_ex_laser_straight(owner, lasers, RAIN_ROW, x, y,
                        -sg_aim(x, y), RAIN_LEN, RAIN_W, RAIN_SPEED)
                local gap = RAIN_GAP - RAIN_STEP * photo_index(PHOTO_LIMIT)
                if gap < 1 then gap = 1 end
                task.Wait(gap)                                  -- ins_2(gap) + ins_4(0,−228)
            end
        end)
    end

    ---Sub5：一轮 10 发、每 7 帧一发（背对自机的 24 发大扇）。
    local function sub5(owner)
        task.New(owner, function()
            local speed = FAN_SPEED0
            for _ = 1, FAN_ROUNDS do
                if st.dead then return end
                sg_shot(86, sg_style(3), ex_color(8), owner.x, owner.y,
                        FAN_COUNT, 1, speed, FAN_SPEED2, FAN_BASE, FAN_STEP, true, 0x202)
                speed = speed + FAN_SPEED_STEP                  -- ins_15：floatV1 += 0.3
                task.Wait(FAN_GAP)
            end
        end)
    end

    ---Sub3：314 帧一轮（Sub4 常驻，Sub5 在 t=0 与 t=152 各起一轮）。
    local function sub3(owner)
        sub4(owner)
        task.New(owner, function()
            while not st.dead do
                sub5(owner)                                     -- @792（t=0）
                task.Wait(BURST2_AT)
                if st.dead then return end
                sub5(owner)                                     -- t=152
                task.Wait(MOVE_AT - BURST2_AT)
                if st.dead then return end
                sg_bmove(owner, st, MOVE_FRAMES, MOVE_EASE, MOVE_SPEED, BOX)
                task.Wait(ROUND - MOVE_AT)
            end
        end)
    end

    local card = boss.card.New(CARD_NAME, 1, 3, CARD_TIME, CARD_HP)

    function card:before()
        lasers = {}
        st.dead = false
    end

    function card:init()
        photo_damage_on(self, PHOTO_LIMIT)
        self.x, self.y = BOSS_X, BOSS_START_Y
        st.dead = false
        task.New(self, function()
            task.Wait(ENTRY_WAIT)
            task.MoveTo(HOME_X, HOME_Y, ENTRY_TIME, EASE_OUT)
            sub3(self)
        end)
    end

    function card:frame()
    end

    function card:del()
        st.dead = true
        photo_damage_off(self)
        sg_clear(lasers)
    end

    boss.card.add({ { card, "21a" } }, LEVEL, CARD_NAME, CARD_ID)
end--包符「昭和の雨」（ecl5_b）

do  -- 25 上白沢慧音 葵符「水戸の光圀」（ecl5_c，组 21a 第 3 张）
    ---原作是「水戸光圀」：本体站定不动（这一张的 Sub3 **没有任何 ins_67**），t=0 在左右
    ---上方各放一个光球子机（ins_84(4/5, ∓128, −32)）；两个光球各自每 4 帧朝自己的角度
    ---甩一根直线激光（长 = 96 + 48×拍中张数、宽 8、速 2.5），每发角度 −0.125163 rad
    ---（≈ −7.17°）⇒ 两台缓慢旋转的激光喷头。本体自己每 454 帧放两轮 12 发整圈
    ---（先逆时针、t=232 起顺时针），每轮 5 发、间隔 10 帧、基准角每发转 ±0.19635 rad（11.25°）。
    ---数据源 /tmp/D95x_ecl5_c.txt（ECL …/data/ecl5_c.ecl）。骨架：
    ---  · Sub2：ins_141(7) + ins_63(-128,-64) → t=100 ins_64(30,4,0,160) 落到 (0,160)
    ---    （我们的 (0, field_y(160)) = (0,64)；**没有 ins_149**）→ t=130 亮卡名 +
    ---    ins_75(-160,96,160,192) + ins_52(3)。
    ---  · Sub3（@724，**454 帧**一轮）：t=0 的 ins_84(4,−128,−32)/ins_84(5,128,−32)
    ---    各放一个光球（子敌机继承父上下文 0x80 字节 scriptState，
    ---    EnemyManagerUpdate.cpp:801；位置 = 本体 + 偏移、y 取反）；@812 的 ins_117(1,7)
    ---    起整圈上下文 Sub7；t=72/102/132 的 ins_144(15)（快门脉冲，装饰）+ t=182 的
    ---    ins_0（停 ANM）；t=232 的 ins_117(1,6) 用 Sub6 **顶掉** Sub7（同一个槽位）；
    ---    t=304/334/364 的 ins_144(15) + t=414 的 ins_0；t=454 的 ins_4(0,−160)
    ---    跳回 **@812** ⇒ 每轮重开 Sub7，而 @764/@788 在跳回点之前 ⇒ **光球只生成一次**。
    ---  · Sub4/Sub5（@1004/@1216，光球自己的脚本）：ins_55(2)+ins_80(8)（出生演出，
    ---    不实现）→ floatV0 = π（左）/ 0（右）；循环从 @1056/@1268 起：
    ---    floatV2 = photoIndex×48（ins_27 乘）+ 96（ins_15）→ ins_106(7) →
    ---    ins_145(型 7、色 2、速 2.5、角 floatV0、长 floatV2、宽 8) →
    ---    floatV0 −= 0.125163049（ins_16 是**减**）→ @1172/@1384 的 ins_4(**t=4**) 跳回
    ---    ⇒ **周期 = 4 帧**（周期看 ins_4 的 time 操作数；那条 ∓116 只是字节偏移，
    ---    正是文件头警告过的那种写法）。
    ---  · Sub6/Sub7（@1428/@1680）：ins_101(0,1,0,−1,−1,−1,−1)（DECEL 记录，弹的
    ---    flags = 0x202 不含 0x1 ⇒ 全程不生效）；floatV0 = playerAngle 只在开始时读一次
    ---    （循环从 @1528/@1780 的 ins_100(0,0) 起）→ 整圈 CIRCLE(型 7、色 6、count1 = 12、
    ---    速 1.2、基准角 floatV0) → Sub6 每发 floatV0 += 0.196349546、Sub7 每发 −= →
    ---    t=10 的 ins_5(0,−104,5) 轮 5 次 ⇒ 5 圈、每 10 帧一圈。
    ---    （floatV1 = 1 起每轮 +0.3 是死代码：count2 = 1 ⇒ sp2 不参与速度。）
    local BOSS_X, BOSS_START_Y = -128, field_y(-64)
    local HOME_X, HOME_Y = 0, field_y(160)              -- 0 / 64
    local ENTRY_WAIT, ENTRY_TIME = 100, 30
    local EASE_OUT = VALUE_SET.DECEL

    local PHOTO_LIMIT = 7                               -- ins_141(7)
    local CARD_NAME = "葵符「水戸の光圀」"
    local CARD_TIME, CARD_HP = 50, 900
    local CARD_ID = 525
    local BOX = { -160, 96, 160, 192 }                  -- ins_75

    local ROUND = 454                                   -- Sub3 一轮（ins_4(0,−160)）
    local RING2_AT = 232                                -- ins_117(1,6) 顶掉 Sub7

    local ORB_DX, ORB_DY = 128, 32                      -- ins_84 的 ∓128 / −32（y 取反）
    local ORB_FIRE_GAP = 4                              -- ins_4 的 time 操作数
    local ORB_TURN = -0.125163049                       -- ins_16：floatV0 −=
    local ORB_LEN0, ORB_LEN_STEP = 96, 48               -- floatV2 = photoIndex×48 + 96
    local ORB_W, ORB_SPEED, ORB_ROW = 8, 2.5, 2         -- ins_145 的后三参（色 2 → 贴图行 2）

    local RING_COUNT, RING_SPEED, RING_SPEED2 = 12, 1.2, 1.5
    local RING_STEP = math.deg(0.241660967)             -- count2 = 1 ⇒ 不参与
    local RING_TURN = 0.196349546                       -- 每发 ±0.19635 rad
    local RING_ROUNDS, RING_GAP = 5, 10

    local lasers = {}
    local orbs = {}
    local st = { dead = false }

    ---一个光球（Sub4/Sub5）：站定不动，每 4 帧朝「当前角度」甩一根直线激光。
    class.k_orb = Class(object, {
        init = function(self, owner, dx, dy, th_angle)
            self.owner = owner
            self.group = GROUP.GHOST
            self.layer = LAYER.ENEMY_BULLET_EF
            self.colli = false
            self.bound = false
            self.rot = 0
            self.x, self.y = owner.x + dx, owner.y + dy
            task.New(self, function()
                local a = th_angle
                while not st.dead do
                    if not IsValid(self) then return end
                    spawn_ex_laser_straight(owner, lasers, ORB_ROW, self.x, self.y, sg_deg(a),
                            ORB_LEN0 + ORB_LEN_STEP * photo_index(PHOTO_LIMIT), ORB_W, ORB_SPEED)
                    PlaySound("tan00", 0.1, self.x / 256, false)    -- ins_106(7)
                    a = a + ORB_TURN
                    task.Wait(ORB_FIRE_GAP)
                end
            end)
        end,
        frame = function(self)
            task.Do(self)                                  -- ★ 驱动光球转圈 + 每 4 帧甩激光
        end,
        render = function(self)
            SetImageState("ball_mid8", "mul+add", 215, 200, 235, 255)
            Render("ball_mid8", self.x, self.y, self.rot, 1.4)
        end,
    })

    ---Sub6/Sub7：12 发整圈、5 发每 10 帧一发，基准角每发 turn×11.25°（turn = ±1）。
    local function ring_emitter(owner, turn)
        task.New(owner, function()
            ---floatV0 = playerAngle（TH095 弧度），只在开始时读一次。
            local base = math.rad(sg_aim(owner.x, owner.y))
            for _ = 1, RING_ROUNDS do
                if st.dead then return end
                sg_shot(89, sg_style(7), ex_color(6), owner.x, owner.y,
                        RING_COUNT, 1, RING_SPEED, RING_SPEED2, math.deg(base), RING_STEP,
                        false, 0x202)
                base = base + turn * RING_TURN
                task.Wait(RING_GAP)                             -- ins_5(0,−104,5) 的 t=10
            end
        end)
    end

    ---Sub3：454 帧一轮（光球只生成一次，两轮整圈在 t=0 / t=232）。
    local function sub3(owner)
        orbs[1] = New(class.k_orb, owner, -ORB_DX, ORB_DY, math.pi)   -- ins_84(4, −128, −32)
        orbs[2] = New(class.k_orb, owner, ORB_DX, ORB_DY, 0)          -- ins_84(5,  128, −32)
        task.New(owner, function()
            while not st.dead do
                ring_emitter(owner, -1)                         -- Sub7：每发 −11.25°
                task.Wait(RING2_AT)
                if st.dead then return end
                ring_emitter(owner, 1)                          -- Sub6：每发 +11.25°（顶掉 Sub7）
                task.Wait(ROUND - RING2_AT)
            end
        end)
    end

    local card = boss.card.New(CARD_NAME, 1, 3, CARD_TIME, CARD_HP)

    function card:before()
        lasers = {}
        orbs = {}
        st.dead = false
    end

    function card:init()
        photo_damage_on(self, PHOTO_LIMIT)
        self.x, self.y = BOSS_X, BOSS_START_Y
        st.dead = false
        task.New(self, function()
            task.Wait(ENTRY_WAIT)
            task.MoveTo(HOME_X, HOME_Y, ENTRY_TIME, EASE_OUT)
            sub3(self)
        end)
    end

    function card:frame()
    end

    function card:del()
        st.dead = true
        photo_damage_off(self)
        sg_clear(lasers)
        for i = #orbs, 1, -1 do
            if IsValid(orbs[i]) then
                task.Clear(orbs[i])
                object.RawDel(orbs[i])
            end
        end
        orbs = {}
    end

    boss.card.add({ { card, "21a" } }, LEVEL, CARD_NAME, CARD_ID)
end--葵符「水戸の光圀」（ecl5_c）

do  -- 27 上白沢慧音 倭符「邪馬台の国」（ecl5_d，组 21a 第 4 张）
    ---原作是「邪马台国」：本体每 520 帧在框里挪两个来回（t=0/t=260 各随机挪一次、
    ---t=120/t=380 各挪 60 px），t=0 放一圈 **12 根 ins_147 旋转激光**、t=260 再放一圈
    ---镜像的（同样 12 根）；另有一条常驻上下文每 (max(1, 7 − 2×拍中张数) + 1) 帧从本体附近
    ---半径 40 的随机方向上甩一圈 3 发（互隔 120°、速 1.6），基准角每发转 45°。
    ---数据源 /tmp/D95x_ecl5_d.txt（ECL …/data/ecl5_d.ecl）。骨架：
    ---  · Sub2：ins_141(4)、**t=0 就 ins_149(3.5)** + ins_63(-128,-64) →
    ---    t=100 ins_64(30,4,0,128) 落到 (0,128)（我们的 (0,96)）→ t=130 亮卡名 +
    ---    ins_75(-160,96,160,192) + ins_52(3)。
    ---  · Sub3（@724，**520 帧**一轮）：@724 的 ins_117(1,6) 起整圈上下文 Sub6（只起一次 ——
    ---    跳回点 @744 在它之后）；@744 的 ins_20(extraIntV0, 4, photoIndex) = 4 + 拍中张数
    ---    （**这一张里没人读 extraIntV0，是死代码**）；t=0 的 ins_117(0,4) 起 12 根激光轮盘
    ---    Sub4；t=0/t=260 的 ins_62（慧音的特殊 ANM 演出，装饰）；t=120/t=380 的
    ---    ins_67(60,4,0.7) 各挪 60 px；t=180/t=440 的 ins_144(15)（快门脉冲，装饰）；
    ---    t=260 的 ins_117(0,5) 用 Sub5 顶掉 Sub4；t=520 的 ins_4(0,−168) 跳回 @744。
    ---  · Sub4/Sub5（@944/@1144）：floatV0 = −π、extraIntV0 = 12 → ins_106(16) →
    ---    ins_100(0,0) → 循环（@1000/@1200 起）ins_147(型 1、色 2、角 floatV0、
    ---    长 512、宽 8、四段 60/10/120/10、角速 +0.005236 / −0.005236 rad/帧、
    ---    followPhotoTarget = 1 ⇒ 每帧钉在本体身上) → floatV0 += 0.5236（30°）→
    ---    ins_5(**t=0**, 0,−96, 12) ⇒ 12 次迭代**全在同一帧**跑完 ⇒ 一次放出 12 根轮盘。
    ---    ins_147 的速度恒为 8（EclRunTargetPhoto.inl），而且初始就是满长。
    ---  · Sub6（@1344）：floatV0 = −π（只读一次）；循环从 @1384 起（这一条上下文
    ---    **没有** ins_101 —— 别照抄别张卡的 DECEL 记录）：
    ---    ins_38(exF0,exF1, rand(−π,π), 40) + ins_100 ⇒ 出膛点 = 本体 + 半径 40 的随机方向；
    ---    CIRCLE(型 7、色 6、count1 = 3、速 1.6、基准角 floatV0) → floatV0 += 0.785398（45°）
    ---    → extraIntV0 = photoIndex×2（ins_22 乘）→ extraIntV0 = 7 − extraIntV0（ins_21 减）
    ---    → ins_48(extraIntV0, 0, 0, 48)：**整数 >** 的条件跳转，成立就跳到 @1592 的 ins_2；
    ---    不成立（拍中 4 张时 7 − 8 < 0）才落到 @1572 的 ins_6 把 extraIntV0 夹成 1
    ---    ⇒ 冻结 = max(1, 7 − 2×拍中张数)，再由 t=1 的 ins_4(0,−224) 跳回 @1384
    ---    ⇒ 周期 = 冻结 + 1 帧（拍中 0..4 张 = 8/6/4/2/2 帧）。
    local BOSS_X, BOSS_START_Y = -128, field_y(-64)
    local HOME_X, HOME_Y = 0, field_y(128)              -- 0 / 96
    local ENTRY_WAIT, ENTRY_TIME = 100, 30
    local EASE_OUT = VALUE_SET.DECEL

    local PHOTO_LIMIT = 4                               -- ins_141(4)
    local CARD_NAME = "倭符「邪馬台の国」"
    local CARD_TIME, CARD_HP = 50, 900
    local CARD_ID = 526
    local BOX = { -160, 96, 160, 192 }                  -- ins_75

    local ROUND = 520                                   -- Sub3 一轮（ins_4(0,−168)）
    local MOVE_AT1, MOVE_AT2, WHEEL_AT = 120, 380, 260  -- 两处 ins_67 / Sub5 顶掉 Sub4
    local MOVE_FRAMES, MOVE_EASE, MOVE_SPEED = 60, 4, 0.7

    local WHEEL_N = 12                                  -- extraIntV0
    local WHEEL_STEP = 0.52359879                       -- 每根 +30°（TH095 弧度）
    local WHEEL_LEN, WHEEL_W, WHEEL_SPEED = 512, 8, 8   -- ins_147 的长度 / 宽度 / 速度
    local WHEEL_PHASES = { 60, 10, 120, 10 }            -- 147 的四段
    local WHEEL_AV = 0.00523598772                      -- Sub4 的角速（Sub5 取负）
    local WHEEL_ROW = 2                                 -- ins_147 的色 2

    local RING_COUNT, RING_SPEED, RING_SPEED2 = 3, 1.6, 1.5
    local RING_STEP = math.deg(0.241660967)             -- count2 = 1 ⇒ 不参与
    local RING_TURN = 0.785398185                       -- 每发 +45°
    local RING_OFF_R = 40                               -- ins_38 的半径
    local RING_FREEZE0, RING_FREEZE_STEP = 7, 2         -- extraIntV0 = 7 − 2×拍中张数

    local lasers = {}
    local st = { dead = false }

    ---Sub4/Sub5：一次 12 根旋转激光（同一帧放完，基准角每根 +30°）。
    local function wheel(owner, th_av)
        local base = -math.pi
        PlaySound("tan00", 0.1, owner.x / 256, false)       -- ins_106(16)
        for _ = 1, WHEEL_N do
            if st.dead then return end
            spawn_ex_laser(owner, lasers, WHEEL_ROW, owner.x, owner.y, sg_deg(base),
                    WHEEL_LEN, WHEEL_W, WHEEL_SPEED,
                    WHEEL_PHASES[1], WHEEL_PHASES[2], WHEEL_PHASES[3], WHEEL_PHASES[4],
                    sg_deg(th_av), 0, 0, true, true)
            base = base + WHEEL_STEP
        end
    end

    ---Sub6：常驻的 3 发小圈（出膛点每轮重随机，基准角每轮 +45°）。
    local function sub6(owner)
        task.New(owner, function()
            local base = -math.pi
            while not st.dead do
                local th = ran:Float(-math.pi, math.pi)         -- ins_38 的极角
                local ox, oy = sg_off(RING_OFF_R, th)           -- ins_38 + ins_100
                sg_shot(89, sg_style(7), ex_color(6), owner.x + ox, owner.y + oy,
                        RING_COUNT, 1, RING_SPEED, RING_SPEED2, math.deg(base), RING_STEP,
                        false, 0x202)
                base = base + RING_TURN                         -- ins_15：floatV0 += 0.785398
                local freeze = RING_FREEZE0 - RING_FREEZE_STEP * photo_index(PHOTO_LIMIT)
                if freeze < 1 then freeze = 1 end               -- ins_48 + ins_6 的夹逼
                task.Wait(freeze + 1)                           -- ins_2 + ins_4(1,−224)
            end
        end)
    end

    ---Sub3：520 帧一轮（Sub6 常驻，Sub4/Sub5 各在 t=0 / t=260 放一圈轮盘）。
    local function sub3(owner)
        sub6(owner)
        task.New(owner, function()
            while not st.dead do
                wheel(owner, WHEEL_AV)                          -- t=0：逆时针
                task.Wait(MOVE_AT1)
                if st.dead then return end
                sg_bmove(owner, st, MOVE_FRAMES, MOVE_EASE, MOVE_SPEED, BOX)
                task.Wait(WHEEL_AT - MOVE_AT1)
                if st.dead then return end
                wheel(owner, -WHEEL_AV)                         -- t=260：顺时针
                task.Wait(MOVE_AT2 - WHEEL_AT)
                if st.dead then return end
                sg_bmove(owner, st, MOVE_FRAMES, MOVE_EASE, MOVE_SPEED, BOX)
                task.Wait(ROUND - MOVE_AT2)
            end
        end)
    end

    local card = boss.card.New(CARD_NAME, 1, 3, CARD_TIME, CARD_HP)

    function card:before()
        lasers = {}
        st.dead = false
    end

    function card:init()
        photo_damage_on(self, PHOTO_LIMIT)
        self.x, self.y = BOSS_X, BOSS_START_Y
        st.dead = false
        task.New(self, function()
            task.Wait(ENTRY_WAIT)
            task.MoveTo(HOME_X, HOME_Y, ENTRY_TIME, EASE_OUT)
            sub3(self)
        end)
    end

    function card:frame()
    end

    function card:del()
        st.dead = true
        photo_damage_off(self)
        sg_clear(lasers)
    end

    boss.card.add({ { card, "21a" } }, LEVEL, CARD_NAME, CARD_ID)
end--倭符「邪馬台の国」（ecl5_d）


end  -- Stage 3
---──────────────────── Stage 2（scene group 1 = world02）── 公共工具 / 六张卡 ────────────────────
---原作 scene group 1 是 world02（チルノ / レティ・ホワイトロック）。SceneSelect.cpp:82-87
---的 TH095_SCENE 表里 scene 10..15 共六幕（两位角色各自的第 1 幕都是**非符**、不亮卡名）：
---  10 ecl3_a チルノ 非符（不亮卡名）   11 ecl4_a レティ 非符（不亮卡名）
---  12 ecl3_b チルノ 雪符「ダイアモンドブリザード」 13 ecl4_b レティ 寒符「コールドスナップ」
---  14 ecl3_c チルノ 凍符「マイナスＫ」  15 ecl4_c レティ 冬符「ノーザンウイナー」
---（角色对号与卡名都是从 ins_104 的 48 字节 payload 解出来的，别按文件名猜。）
---按「一个角色一个组」拆：组 22 = チルノ（10/12/14，第 1 张非符）、
---组 23 = レティ（11/13/15，第 1 张非符）。★ 别把两人塞进同一个组的 a/b。
---原作整组 BGM 是 bgm/th095_01.wav ——**本仓库没有这首**（music.lua 里 th095 系只有
---TH07_1 = th095_04、TH09_5_1 = th095_03），整组沿用 "TH09_5_1"，背景沿用 TH095_bg；
---world02.std 的贴图本仓库也没有，两套符卡背景照 Stage 3/4/5 的做法拿 th06/th07/th08/
---th10 的通用贴图重新配色（见上面 class.scbg22/23）。
---数据源 /tmp/D95x_ecl{3,4}_{a..c}.txt（脚本 /tmp/d95dump.py 不入库；ECL 在
---`[th095] …/data/ecl{3,4}_{a..c}.ecl`），各卡注释里的「@地址」都指这几份 dump。
---
---这一组六幕共用同一套外壳（Sub2 的样子）：ins_55(2)+ins_81(3)+ins_109(0)+ins_77(24,24)
---+ins_141(N)+ins_108(0,31)/ins_108(1,30)+ins_143(1,130)+ins_63(起点) 进场
---→ t=100 的 ins_64(30,4,0,Y) 用 30 帧从场外落到中轴（我们的 (0, field_y(Y))）
---→ t=130 亮卡名（第 1 幕是 id=0，**非符不亮**）+ ins_75(box) + ins_149(倍率) + ins_52(3)。
---★ ins_115(slot, frame, sub)：原作在**拍中第 frame 张**之后把主上下文整个换成 Sub
---  （EnemyManagerUpdate.cpp:1281-1310 的 UpdateScheduledEclCalls，frame 比的是拍照计数；
---  换的时候会释放全部子上下文、重置弹表）—— 本文件各卡用 gen + 监视器照抄。
---★ ins_117(slot, sub) 起的子上下文在**创建那一刻**把父上下文的 int/float 变量整块
---  抄一份（EclRunTargetHigh.inl:230-235 的 memcpy）⇒ 之后再改父变量不影响子上下文；
---  ins_83/84 生成的子敌机同理（EnemyManagerUpdate.cpp:842-850 的 EnemyContextCopy）。
---★ ins_2(n) 是「冻结」：接下来 n 帧 context 的 time 原地不动、一条指令都不跑
---  （EclRunLow.inl:230-232）⇒ 等价 task.Wait(n)。
---★ ins_4/5 的跳转目标是**当前指令地址 + operand1**（EclRunLow.inl:242-246），记在每张卡
---  自己的注释里；跳转后会在同一帧重取自标，所以 t=0 的循环体一帧跑完。
---★ ins_83/84 生成的子敌机（チルノ的冰晶、レティ的霜精）按文件头差异 5 一律做成
---  「数量受限、有寿命、淡出离场」的自绘 object；它们发的弹按各自的 ECL 照抄。
do

---TH095 的极坐标偏移 (半径 r, 弧度 θ) → 我们的相对位移（x 同号、y 取反）。
local function sg_off(r, th_rad)
    return r * math.cos(th_rad), -r * math.sin(th_rad)
end

---自机在 TH095 空间的角（弧度、顺时针为正）：sg_aim 给的是本仓库的度（逆时针为正），
---取反再转弧度即得 TH095 的 playerAngle（见文件头「坐标系与角度」）。
local function th_aim(x, y)
    return math.rad(sg_aim(x, y))
end

---ins_66（ConfigurePolarMotion，EclHelpers.cpp:28-40）：用 duration 帧从当前位置沿
---TH095 方向 angle 线性插值移动 speed×duration（speed 可负 = 反向），缓动 easing。
local function sg_polar_move(owner, st, duration, easing, th_angle, speed)
    local d = speed * duration
    local dx, dy = sg_off(d, th_angle)
    sg_move(owner, st, owner.x + dx, owner.y + dy, max(1, duration), easing)
end

---ins_67（BeginBoundaryAwareMove）见 Stage 9 段的 sg_bmove：先按自机位置随机取一个
---「背离自机」的方向，再按活动框反射。这一组六幕的 ins_67 参数都是 (60,4,1~2)。
do  -- 10 チルノ 非符（ecl3_a，组 22a 第 1 张）
    ---原作这一幕**不亮卡名**（Sub2 的 t=130 是 id=0）：本体落到中轴后每 160 帧重开一轮，
    ---一轮里两条发弹上下文各放一次 —— 一条是「连打 60 帧、每帧 2 发小弹」，
    ---另一条是「沿开火时的自机方向、速度 1.0→3.2 的 12 连直线弹（每 8 帧一发）」。
    ---拍中第 3 张后主脚本换成 Sub6：清一次屏，改成 Sub7（4 发 30° 扇、每 8 帧一波 ×12）。
    ---数据源 /tmp/D95x_ecl3_a.txt（ECL …/data/ecl3_a.ecl）。骨架：
    ---  · Sub2：… ins_141(5) + ins_115(0,3,6) + ins_63(-128,-64) 进场 → t=100
    ---    ins_64(30,4,0,128) 落到 (0,128)（我们的 (0,96)）→ t=130 的 id=0（非符）
    ---    + ins_75(-160,96,160,192) + ins_52(3) 起 Sub3。
    ---  · Sub3（@688，160 帧一轮）：ins_6(extraIntV1,60) → ins_117(0,4)+ins_117(1,5)
    ---    → t=120 ins_67(60,4,2) → t=160 ins_4(0,−92) 跳回 **@708**（ins_117(0,4)）
    ---    ⇒ 每轮都把两条发弹上下文重新起一遍。
    ---  · Sub4（@832，**连打 60 帧、每帧 2 发**）：floatV2 = playerAngle **只在进入时读一次**、
    ---    floatV1=0（速度随机幅度）、floatV4=0.4（角度幅度）；内层 ins_5 每帧发
    ---    extraIntV2=2 发：每发 floatV3 = floatV2 + rand(−π,π)×floatV4、
    ---    floatV0 = randF32×floatV1 + 0.8（速度）→ FAN 型5/色6、c1=1、tf=FAST|SND；
    ---    内层跑完再 floatV1+=0.04 / floatV4+=0.005，然后 **t=1 的外层 ins_5(0,−308,ei1)**
    ---    跳回 @960 —— 跳回点在两句 ins_15 **之前** ⇒ 两句是**每帧**都加一次，
    ---    速率上限 0.04k、角度幅度 0.4+0.005k，一直连打到外层 60 帧跑完。
    ---    （旧注释把外层循环当成了「只跑一次」，别再照抄。）
    ---  · Sub5（@1216，一次性 12 发）：floatV0 = playerAngle（**全程不变**）、floatV1=1；
    ---    每 8 帧一发 FAN 型1/色6、c1=1，速度 floatV1（每发 +0.2）→ 1.0…3.2。
    ---  · Sub6（@1428，拍中第 3 张）：t=90 ins_102 清屏 + 重开 Sub4/Sub7 → t=170 ins_67
    ---    → t=210 ins_4(90,−92) 跳回 **@1460**（ins_117(0,4)）⇒ 周期 120 帧、每轮重起。
    ---  · Sub7（@1584）：floatV0 = playerAngle（不变）、extraIntV0=12；每 8 帧一波
    ---    FAN 型12/色3、c1=4（±15°/±45°）、速度 3。
    ---  · Sub0/Sub1 是死亡/退场 ⇒ 不实现（文件头差异 3）。
    local BOSS_X, BOSS_START_Y = -128, field_y(-64)
    local HOME_X, HOME_Y = 0, field_y(128)              -- 0 / 96
    local ENTRY_WAIT, ENTRY_TIME = 100, 30
    local EASE_OUT = VALUE_SET.DECEL

    local PHOTO_LIMIT = 5                               -- ins_141(5)
    local CARD_NAME = ""                                -- 非符：原作 t=130 是 id=0
    local CARD_TIME, CARD_HP = 50, 900
    local CARD_ID = 527
    local BOX = { -160, 96, 160, 192 }                  -- ins_75

    local ROUND = 160                                   -- Sub3 一轮（ins_4(0,−92)）
    local MOVE_AT, MOVE_FRAMES, MOVE_EASE, MOVE_SPEED = 120, 60, 4, 2
    local SUB6_AT, SUB6_MOVE_AT = 90, 170               -- Sub6 的重开点 / 挪动点
    local SUB6_SPAN = 210 - SUB6_AT                     -- 周期 120

    local A4_SHOTS, A4_SPREAD, A4_SPEED = 2, 0.4, 0.8   -- Sub4
    local A4_ITERS = 60                                 -- Sub4 外层 ins_5 的 ei1=60 次
    local A4_SP_INC, A4_ANG_INC = 0.04, 0.005           -- 每轮 floatV1+=0.04 / floatV4+=0.005
    local A5_SHOTS, A5_GAP = 12, 8                      -- Sub5
    local A5_SPEED0, A5_SPEED_STEP = 1.0, 0.2
    local A7_SHOTS, A7_GAP, A7_SPEED = 12, 8, 3         -- Sub7
    local A7_COUNT, A7_STEP = 4, 0.5235988              -- 4 发 30° 扇

    local SWITCH_AT = 3                                 -- ins_115(0,3,6)
    local st = { dead = false }
    local gen = 0                                       -- 主脚本代号（ins_115 会 +1）
    local lasers = {}

    ---Sub4 的 ins_101 表头是 DECEL，但弹的 tf=0x202 里没有 0x1 ⇒ 按 BulletManager.cpp:525
    ---这条记录会被跳过（照原样传进 hook，sg_tr_hook 自己会认掉）。
    local hook_decel = sg_tr_hook({ sg_rec(SG_DECEL, 0, -1, -1, -1, -1) }, 0x202)

    ---Sub4（@832）：连打 60 帧、每帧 2 发小弹（基准角只在进入时取一次）。
    local function sub4(owner)
        local base_a = th_aim(owner.x, owner.y)             -- ins_7(f2, aimAngle)，只读一次
        local f1, f4 = 0.0, A4_SPREAD                       -- floatV1 / floatV4
        for _ = 1, A4_ITERS do
            if st.dead then return end
            for _ = 1, A4_SHOTS do                          -- ins_6(ei2,2) 的内层循环
                local a = base_a + ran:Float(-math.pi, math.pi) * f4
                sg_shot(87, sg_style(5), ex_color(6), owner.x, owner.y, 1, 1,
                        ran:Float(0, 1) * f1 + A4_SPEED, 1.5, math.deg(a), 0, false,
                        0x202, hook_decel)
            end
            f1 = f1 + A4_SP_INC                             -- ins_15(f1, 0.04)
            f4 = f4 + A4_ANG_INC                            -- ins_15(f4, 0.005)
            task.Wait(1)                                    -- t=1 的外层 ins_5
        end
    end

    ---Sub5（@1216）：沿开火时的自机方向、速度 1.0→3.2 的 12 连直线弹（每 8 帧一发）。
    local function sub5(owner)
        local a = th_aim(owner.x, owner.y)
        local sp = A5_SPEED0
        for i = 1, A5_SHOTS do
            if st.dead then return end
            sg_shot(87, sg_style(1), ex_color(6), owner.x, owner.y, 1, 1,
                    sp, 1.5, math.deg(a), 0, false, 0x202, hook_decel)
            sp = sp + A5_SPEED_STEP
            if i < A5_SHOTS then task.Wait(A5_GAP) end
        end
    end

    ---Sub7（@1584）：每 8 帧一波 4 发 30° 扇（±15°/±45°）、速度 3，方向固定。
    local function sub7(owner)
        local a = th_aim(owner.x, owner.y)
        for i = 1, A7_SHOTS do
            if st.dead then return end
            sg_shot(87, sg_style(12), ex_color(3), owner.x, owner.y, A7_COUNT, 1,
                    A7_SPEED, 1.5, math.deg(a), math.deg(A7_STEP), false, 0x202, hook_decel)
            if i < A7_SHOTS then task.Wait(A7_GAP) end
        end
    end

    ---Sub3（@688）：进场后的主循环，160 帧一轮，每轮重起 Sub4/Sub5。
    local function sub3(owner)
        local g = gen
        task.New(owner, function()
            while not st.dead and g == gen do
                task.New(owner, function() sub4(owner) end)
                task.New(owner, function() sub5(owner) end)
                task.Wait(MOVE_AT)
                if st.dead or g ~= gen then return end
                sg_bmove(owner, st, MOVE_FRAMES, MOVE_EASE, MOVE_SPEED, BOX)
                task.Wait(ROUND - MOVE_AT)
            end
        end)
    end

    ---Sub6（@1428）：拍中第 3 张起接管；t=90 清屏 + 重开 Sub4/Sub7，之后 120 帧一轮。
    local function sub6(owner)
        local g = gen
        task.New(owner, function()
            task.Wait(SUB6_AT)
            if st.dead or g ~= gen then return end
            sg_clear(lasers)                            -- ins_102
            while not st.dead and g == gen do
                task.New(owner, function() sub4(owner) end)
                task.New(owner, function() sub7(owner) end)
                task.Wait(SUB6_MOVE_AT - SUB6_AT)
                if st.dead or g ~= gen then return end
                sg_bmove(owner, st, MOVE_FRAMES, MOVE_EASE, MOVE_SPEED, BOX)
                task.Wait(SUB6_SPAN - (SUB6_MOVE_AT - SUB6_AT))
            end
        end)
    end

    local card = boss.card.New(CARD_NAME, 1, 3, CARD_TIME, CARD_HP)

    function card:before()
        gen = 1
        lasers = {}
    end

    function card:init()
        photo_damage_on(self, PHOTO_LIMIT)
        self.x, self.y = BOSS_X, BOSS_START_Y
        st.dead = false
        task.New(self, function()
            task.Wait(ENTRY_WAIT)
            task.MoveTo(HOME_X, HOME_Y, ENTRY_TIME, EASE_OUT)
            sub3(self)
            task.New(self, function()                   -- ins_115(0,3,6) 的监视器
                while not st.dead do
                    if photo_index(PHOTO_LIMIT) >= SWITCH_AT then
                        gen = gen + 1
                        sub6(self)
                        return
                    end
                    task.Wait(1)
                end
            end)
        end)
    end

    function card:frame()
    end

    function card:del()
        st.dead = true
        photo_damage_off(self)
        sg_clear(lasers)
    end

    boss.card.add({ { card, "22a" } }, LEVEL, CARD_NAME, CARD_ID)
end--チルノ 非符（ecl3_a）
do  -- 12 チルノ 雪符「ダイアモンドブリザード」（ecl3_b，组 22a 第 2 张）
    ---原作是「把冰晶撒满屏」：本体每 200 帧一轮 —— t=0 起两条发弹上下文，每 15 帧各放一圈
    ---6 发冰晶（随机基准角、随机旋转、出膛点在半径 64 px 内随机，速 1.7~2.7）；t=90 再把
    ---槽 0/1 换成 Sub6/Sub7（它们各自又起一对内层环，freeze 13 与 10）；t=60 / t=120 各挪
    ---一次。拍中第 1~4 张各触发一次相位切换（清屏 + 换一对环 + 改 freeze）。
    ---数据源 /tmp/D95x_ecl3_b.txt。骨架：
    ---  · Sub2：… ins_141(5) + 四条 ins_115(0,1,6)(1,2,7)(2,3,10)(3,4,13) + ins_63(-128,-64)
    ---    → t=100 ins_64(30,4,0,128) 落到 (0,128)（我们的 (0,96)）→ t=130 亮卡名
    ---    + ins_75(-160,96,160,192) + ins_149(3) + ins_52(3)。
    ---  · Sub3（@756，**160 帧一轮**）：extraIntV1=60 + extraIntV2=15 + ins_117(0,4)/(1,5)
    ---    （这两条在标签 Sub3_80 **之前** ⇒ Sub4/Sub5 只起一次）→ 标签落回点在
    ---    **ins_67（t=120）** 上 → t=160 的 ins_4(0,−172) 把 time 拨回 0 ⇒ 之后每 160 帧
    ---    只挪一次位（120 帧后挪、挪 60 帧、再闲 100 帧）。
    ---  · Sub4/Sub5（@1020/@1280）：死循环 —— 出膛点在半径 64 px 内随机；CIRCLE 型5/色6 与
    ---    型0/色6、c1=6、速 floatV1=**randF32signed×1+1.7（0.7~2.7）**、基角 rand(−π,π)；
    ---    `ins_2(extraIntV2)` 冻结（15）后 `ins_4(0,−176)` 跳回 **@1060** ⇒ 每 15 帧一圈。
    ---  · Sub8/Sub9（@1828/@2088）：型5/色6 与 型1/色6、freeze=10（Sub7 的内层）。
    ---  · Sub11/Sub12（@2492/@2752）：型5/色6 与 型1/色6、**c1=8**、freeze=10（Sub10 的内层）。
    ---  · Sub14/Sub15（@3156/@3416）：型5/色6 与 **型12/色3**、c1=6、freeze=10（Sub13 的内层）。
    ---  · Sub6（@1540，拍中第 1 张）：t=30 ins_102 清屏 + extraIntV2=13 + 起 Sub4/Sub5 →
    ---    t=150 ins_67(60,4,2) → t=190 ins_4(30,−40) 跳回 **@1612**（ins_67）⇒ 之后只重复移动。
    ---  · Sub7（拍 2，freeze 10、型5/1、周期 130）→ Sub10（拍 3，c1=8、周期 100）
    ---    → Sub13（拍 4，型12/色3、周期 100）同形。
    ---  · Sub0/Sub1 是死亡/退场 ⇒ 不实现。
    ---★ 与原作的差异：Sub3 在 t=90 起的 Sub6/Sub7 是**嵌套上下文**、自身也带 ins_67 移动；
    ---  本移植只保留外层 Sub3 的移动计划（原作里同一时刻的 movementMode 会被后写的那条
    ---  整个覆盖，观感就是「在框里随机游走」，简化后差别不可见），环的种类/节奏/freeze 照抄。
    local BOSS_X, BOSS_START_Y = -128, field_y(-64)
    local HOME_X, HOME_Y = 0, field_y(128)              -- 0 / 96
    local ENTRY_WAIT, ENTRY_TIME = 100, 30
    local EASE_OUT = VALUE_SET.DECEL

    local PHOTO_LIMIT = 5                               -- ins_141(5)
    local CARD_NAME = "雪符「ダイアモンドブリザード」"
    local CARD_TIME, CARD_HP = 50, 900
    local CARD_ID = 528
    local BOX = { -160, 96, 160, 192 }                  -- ins_75

    local MOVE_EASE = 4
    local SCATTER = 64                                  -- 出膛点半径
    local RING_SPEED_BIAS, RING_STEP = 1.7, 0.448798954  -- 速 floatV1 = randF32signed+1.7

    local st = { dead = false }
    local gen = 0                                       -- 主脚本代号（ins_115 会 +1）
    local ring_seq = 0                                  -- 环发弹体代号（换相位时 +1 收掉旧的）
    local lasers = {}

    ---Sub4/Sub5 的 ins_101 表头是 DECEL，但弹的 tf=0x202 里没有 0x1 ⇒ 按 BulletManager.cpp:525
    ---这条记录会被跳过（照原样传进 hook）。
    local hook_decel = sg_tr_hook({ sg_rec(SG_DECEL, 0, -1, -1, -1, -1) }, 0x202)

    ---Sub4/5/8/9/11/12/14/15 的统一形状：每 freeze 帧放一圈 count 发、随机基准角的环。
    local function ring(owner, seq, btype, bcolor, count, freeze)
        task.New(owner, function()
            while not st.dead and seq == ring_seq and gen > 0 do
                local r = ran:Float(-SCATTER, SCATTER)
                local ox, oy = sg_off(r, ran:Float(-math.pi, math.pi))
                local sp = ran:Float(-1, 1) + RING_SPEED_BIAS    -- ins_27(rnd_f32s)×1 + 1.7
                local a = ran:Float(-math.pi, math.pi)
                sg_shot(89, sg_style(btype), ex_color(bcolor), owner.x + ox, owner.y + oy,
                        count, 1, sp, 1.5, math.deg(a), math.deg(RING_STEP),
                        false, 0x202, hook_decel)
                task.Wait(freeze)
            end
        end)
    end

    local function pair(owner, seq, ta, ca, tb, cb, count, freeze)
        ring(owner, seq, ta, ca, count, freeze)
        ring(owner, seq, tb, cb, count, freeze)
    end

    ---Sub3（@756）：200 帧一轮。
    local function sub3(owner)
        local g = gen
        ring_seq = ring_seq + 1
        pair(owner, ring_seq, 5, 6, 0, 6, 6, 15)            -- t=0：Sub4/Sub5，只起一次
        task.New(owner, function()
            while not st.dead and g == gen do
                task.Wait(120)                               -- 标签落在 t=120 的 ins_67 上
                if st.dead or g ~= gen then return end
                sg_bmove(owner, st, 60, MOVE_EASE, 2.0, BOX) -- ins_67(60,4,2.0)（不阻塞）
                if st.dead or g ~= gen then return end
                task.Wait(40)                                -- t=160 的 ins_4 ⇒ 周期 160
            end
        end)
    end

    ---Sub6/Sub7/Sub10/Sub13（拍中第 k 张后的相位）：t=30 清屏 + 换一对环，
    ---之后每 (jump_at−30) 帧挪一次位（挪 move_frames 帧）。
    local function phase(owner, ta, ca, tb, cb, count, freeze, move_at, move_frames, move_speed, jump_at)
        local g = gen
        task.New(owner, function()
            task.Wait(30)
            if st.dead or g ~= gen then return end
            sg_clear(lasers)                                -- ins_102
            ring_seq = ring_seq + 1
            pair(owner, ring_seq, ta, ca, tb, cb, count, freeze)
            while not st.dead and g == gen do
                task.Wait(move_at - 30)                     -- 下一次 ins_67 之前
                if st.dead or g ~= gen then return end
                sg_bmove(owner, st, move_frames, MOVE_EASE, move_speed, BOX)
                task.Wait(jump_at - move_at)                -- 周期 = jump_at − 30
            end
        end)
    end

    ---相位表：拍中第 k 张 → (型A/色A, 型B/色B, 发数, freeze, 挪动时刻, 挪动帧数, 速度, 周期末)。
    local PHASE = {
        { 5, 6, 0, 6, 6, 13, 150, 60, 2, 190 },             -- Sub6（拍 1）
        { 5, 6, 1, 6, 6, 10, 120, 40, 2, 160 },             -- Sub7（拍 2）
        { 5, 6, 1, 6, 8, 10, 90, 60, 1.5, 130 },            -- Sub10（拍 3）
        { 5, 6, 12, 3, 6, 10, 90, 60, 1.5, 130 },           -- Sub13（拍 4）
    }
    local PHASE_AT = { 1, 2, 3, 4 }

    local card = boss.card.New(CARD_NAME, 1, 3, CARD_TIME, CARD_HP)

    function card:before()
        gen = 1
        ring_seq = 0
        lasers = {}
    end

    function card:init()
        photo_damage_on(self, PHOTO_LIMIT)
        self.x, self.y = BOSS_X, BOSS_START_Y
        st.dead = false
        task.New(self, function()
            task.Wait(ENTRY_WAIT)
            task.MoveTo(HOME_X, HOME_Y, ENTRY_TIME, EASE_OUT)
            sub3(self)
            task.New(self, function()                   -- 四条 ins_115 的监视器
                local step = 0
                while not st.dead and step < 4 do
                    local p = photo_index(PHOTO_LIMIT)
                    while step < 4 and p >= PHASE_AT[step + 1] do
                        step = step + 1
                        gen = gen + 1
                        local ph = PHASE[step]
                        phase(self, ph[1], ph[2], ph[3], ph[4], ph[5], ph[6],
                              ph[7], ph[8], ph[9], ph[10])
                    end
                    task.Wait(1)
                end
            end)
        end)
    end

    function card:frame()
    end

    function card:del()
        st.dead = true
        photo_damage_off(self)
        sg_clear(lasers)
    end

    boss.card.add({ { card, "22a" } }, LEVEL, CARD_NAME, CARD_ID)
end--雪符「ダイアモンドブリザード」（ecl3_b）
do  -- 14 チルノ 凍符「マイナスＫ」（ecl3_c，组 22a 第 3 张）
    ---原作是「大玉飞到一半冻结、再炸成冰尘」：本体每 160 帧一轮，一轮里朝自机方向、
    ---自机方向 +120°、+240° 各放一颗大玉（型13/色3、速 2）。大玉**沿自机方向直飞 50 帧**、
    ---然后原地停住 30 帧，接着同时炸成两簇各 12 颗的冰尘（型5/色6 与 型0/色6，
    ---散角 ±45°、速 0.5~3 随机），自己消失。另有两条「往本体附近随机位置撒整圈」的
    ---辅助环随拍照张数加入。拍中第 1~4 张各触发一次相位切换（清屏 + 换 freeze + 加环）。
    ---数据源 /tmp/D95x_ecl3_c.txt。骨架：
    ---  · Sub2：ins_55(2)+ins_81(3)+ins_109(0)+ins_77(24,24)+ins_141(5)
    ---    +ins_108(0,31)/ins_108(1,30)+ins_143(1,130)
    ---    +ins_115(0,1,5)(1,2,6)(2,3,7)(3,4,9)+ins_63(-128,-64)
    ---    → t=100 ins_64(30,4,0,192) 落到 (0,192)（我们的 (0,32)）→ t=130 亮卡名
    ---    +ins_75(-160,128,160,256)+ins_149(2)+ins_52(3)。
    ---  · Sub3（@848，**160 帧一轮**）：extraIntV1=60、extraIntV2=60 + ins_117(0,4)（起 Sub4，
    ---    freeze=60，只起一次）→ 标签落回点在 **t=120 的 ins_67** 上 → t=160 的
    ---    ins_4(0,−40) 把 time 拨回 0 ⇒ 之后每 160 帧挪一次位（挪 60 帧、闲 100 帧）。
    ---  · Sub4（@980，发弹主上下文，循环）：写 10 条 ins_101 后发一颗大玉 —— 大玉的记录表：
    ---      slot0 WAIT 50 → slot1 CHDIR_REL(i0=1,i1=1,f0=0,f1=0)（把弹速设成 0 = 冻住）
    ---      → slot2 PLAY_SOUND → slot3 SET_SPRITE(13,7) → slot4 WAIT 30 → slot5 PLAY_SOUND
    ---      → slot6 SPAWN_CHILD(packed 0x08050600：aim=RANDOM、型5、色6、start=0；
    ---        c1=12、sp1=3、sp2=0.5；secondary：c2=1、flags=FAST、ang=floatV3、step=floatV4)
    ---      → slot8 SPAWN_CHILD(packed 0x88000600：**bit31 fadeParent**、aim=RANDOM、型0、色6)
    ---      ⇒ 大玉先飞 50 帧、冻结 30 帧、炸两簇各 12 颗、自己消失。
    ---    每轮 floatV2=playerAngle、重启循环时重取；floatV3=floatV2+45°、floatV4=floatV2−45°；
    ---    CIRCLE 型13/色3、c1=1、速 2、基角 floatV2；三颗之间 floatV2 += 120°；
    ---    之后 ins_2(extraIntV2) 冻结（60/15/10/10，随相位）→ ins_4(0,−856) 跳回 @1220。
    ---  · Sub5/6/7/9（拍中第 1/2/3/4 张起接管主脚本）：t=10 ins_102 清屏 + 设 freeze
    ---    + ins_117(0,4) 重起 Sub4（拍 3/4 还会 extraIntV2=60/30 + ins_117(1,8)/(1,10)
    ---    再加一条边环）→ 之后每 130/100 帧挪一次位（Sub5 是 160 帧）。
    ---  · Sub8/Sub10（附加环，@2532/@2916）：在本体附近 ≤16 px 的随机点放一整圈
    ---    （型5/色6 c1=8 或 型12/色3 c1=6），速 rand+0.2、freeze = 60 / 30。
    ---  · Sub0/Sub1 是死亡/退场 ⇒ 不实现。
    local BOSS_X, BOSS_START_Y = -128, field_y(-64)
    local HOME_X, HOME_Y = 0, field_y(192)              -- 0 / 32
    local ENTRY_WAIT, ENTRY_TIME = 100, 30
    local EASE_OUT = VALUE_SET.DECEL

    local PHOTO_LIMIT = 5                               -- ins_141(5)
    local CARD_NAME = "凍符「マイナスＫ」"
    local CARD_TIME, CARD_HP = 50, 900
    local CARD_ID = 529
    local BOX = { -160, 128, 160, 256 }                 -- ins_75

    local PARENT_FLAGS = 0x42C242                       -- FAST|CHDIR_REL|SND|SPRITE|WAIT|SND2|CHILD
    local CHILD_A = 0x08050600                          -- aim=RANDOM type=5 color=6 start=0
    local CHILD_B = 0x88000600                          -- 同上 + bit31 fadeParent, type=0
    local CHILD_N, CHILD_SP1, CHILD_SP2 = 12, 3, 0.5    -- SPAWN_CHILD 的 c1/sp1/sp2
    local PARENT_TYPE, PARENT_COLOR, PARENT_SPEED = 13, 3, 2
    local WAIT_A, WAIT_B = 50, 30                       -- slot0 / slot4 的 WAIT
    local RING_STEP = 0.448798954                       -- CIRCLE 的 step（c1=1 ⇒ 不用）

    local ROUND = 160                                   -- Sub3 一轮
    local MOVE_AT, MOVE_FRAMES, MOVE_EASE, MOVE_SPEED = 120, 60, 4, 2
    local RING_SCATTER = 16                             -- Sub8/10 的撒点半径

    local st = { dead = false }
    local gen = 0                                       -- 主脚本代号（ins_115 会 +1）
    local slot0_seq, slot1_seq = 0, 0                   -- 槽 0/1 的发弹上下文代号
    local lasers = {}

    ---大玉的记录表（每次发射重建：floatV3/floatV4 随基角变）。
    local function parent_recs(v3, v4)
        return {
            sg_rec(SG_WAIT, 0, WAIT_A, -1, -1, -1),          -- slot0
            sg_rec(SG_CHDIR_R, 0, 1, 1, 0, 0),               -- slot1：把速设 0
            sg_rec(SG_SND_T, 0, 24, -1, -1, -1),             -- slot2：PLAY_SOUND（跳过）
            sg_rec(SG_SET_SPRITE, 0, 13, 7, -1, -1),         -- slot3：SET_SPRITE（跳过）
            sg_rec(SG_WAIT, 0, WAIT_B, -1, -1, -1),          -- slot4
            sg_rec(SG_SND_T, 0, 24, -1, -1, -1),             -- slot5
            sg_rec(SG_CHILD, 0, CHILD_A, CHILD_N, CHILD_SP1, CHILD_SP2),   -- slot6
            sg_rec(0x00800000, 0, 1, 2, v3, v4),             -- slot7（secondary）
            sg_rec(SG_CHILD, 0, CHILD_B, CHILD_N, CHILD_SP1, CHILD_SP2),   -- slot8
            sg_rec(0x00800000, 0, 1, 2, v3, v4),             -- slot9（secondary）
        }
    end

    ---Sub4：发弹主上下文 —— 每次在自机方向起、三颗大玉（彼此 120°），然后冻结 freeze 帧。
    local function sub4(owner, seq, freeze)
        task.New(owner, function()
            while not st.dead and slot0_seq == seq and gen > 0 do
                local base = th_aim(owner.x, owner.y)        -- floatV2（TH095 弧度）
                for _ = 1, 3 do
                    if st.dead or slot0_seq ~= seq then return end
                    local v3 = base + math.pi / 4            -- floatV3
                    local v4 = base - math.pi / 4            -- floatV4
                    local hook = sg_tr_hook(parent_recs(v3, v4), PARENT_FLAGS)
                    sg_shot(89, sg_style(PARENT_TYPE), ex_color(PARENT_COLOR),
                            owner.x, owner.y, 1, 1, PARENT_SPEED, 1.5,
                            math.deg(base), math.deg(RING_STEP), false, PARENT_FLAGS, hook)
                    base = base + 2 * math.pi / 3
                end
                task.Wait(freeze)
            end
        end)
    end

    ---Sub8/Sub10：在本体附近 ≤16 px 的随机点放一整圈（型5/色6 c1=8 或 型12/色3 c1=6）。
    local function ring(owner, seq, btype, bcolor, count, freeze)
        task.New(owner, function()
            while not st.dead and slot1_seq == seq and gen > 0 do
                local mag = ran:Float(-1, 1) * RING_SCATTER
                local off = ran:Float(-math.pi, math.pi)
                local ox, oy = sg_off(mag, off)
                local sp = ran:Float(0, 1) + 0.2
                local a = ran:Float(-math.pi, math.pi)
                sg_shot(89, sg_style(btype), ex_color(bcolor), owner.x + ox, owner.y + oy,
                        count, 1, sp, 1.5, math.deg(a), 0, false, 0x202)
                task.Wait(freeze)
            end
        end)
    end

    ---Sub3（@848）：160 帧一轮。
    local function sub3(owner)
        local g = gen
        slot0_seq = slot0_seq + 1
        sub4(owner, slot0_seq, 60)
        task.New(owner, function()
            while not st.dead and g == gen do
                task.Wait(MOVE_AT)                          -- 标签落在 t=120 的 ins_67 上
                if st.dead or g ~= gen then return end
                sg_bmove(owner, st, MOVE_FRAMES, MOVE_EASE, MOVE_SPEED, BOX)
                if st.dead or g ~= gen then return end
                task.Wait(ROUND - MOVE_AT)                  -- t=160 的 ins_4 ⇒ 周期 160
            end
        end)
    end

    ---Sub5/6/7/9（拍中第 k 张后的相位）：清屏 + 重起槽 0（± 槽 1），之后每 period 帧挪一次。
    ---phase = (freeze, ring_type, ring_color, ring_count, ring_freeze, wait, speed, period)
    local function phase(owner, freeze, rtype, rcolor, rcount, rfreeze, wait, speed, period)
        local g = gen
        task.New(owner, function()
            task.Wait(10)
            if st.dead or g ~= gen then return end
            sg_clear(lasers)                                -- ins_102
            slot0_seq = slot0_seq + 1
            sub4(owner, slot0_seq, freeze)
            if rtype then
                slot1_seq = slot1_seq + 1
                ring(owner, slot1_seq, rtype, rcolor, rcount, rfreeze)
            end
            while not st.dead and g == gen do
                task.Wait(wait)                             -- 下一次 ins_67 之前
                if st.dead or g ~= gen then return end
                sg_bmove(owner, st, MOVE_FRAMES, MOVE_EASE, speed, BOX)
                task.Wait(period - wait)                    -- ins_4 的周期
            end
        end)
    end

    ---相位表：拍中第 k 张 → Sub5/6/7/9 的
    ---(freeze, 环型/色/数/freeze, 首次挪位前的等待, 速度, 周期)。
    local PHASE = {
        { 15, nil, nil, nil, nil, 120, 1, 160 },            -- Sub5（拍 1）：t=130 挪、t=170 回
        { 10, nil, nil, nil, nil,  90, 1, 130 },            -- Sub6（拍 2）：t=100 挪、t=140 回
        { 10, 5, 6, 8, 60, 60, 1, 100 },                    -- Sub7（拍 3）：t=70 挪、t=110 回
        { 10, 12, 3, 6, 30, 60, 1, 100 },                   -- Sub9（拍 4）：同上
    }
    local PHASE_AT = { 1, 2, 3, 4 }

    local card = boss.card.New(CARD_NAME, 1, 3, CARD_TIME, CARD_HP)

    function card:before()
        gen = 1
        slot0_seq, slot1_seq = 0, 0
        lasers = {}
    end

    function card:init()
        photo_damage_on(self, PHOTO_LIMIT)
        self.x, self.y = BOSS_X, BOSS_START_Y
        st.dead = false
        task.New(self, function()
            task.Wait(ENTRY_WAIT)
            task.MoveTo(HOME_X, HOME_Y, ENTRY_TIME, EASE_OUT)
            sub3(self)
            task.New(self, function()                   -- 四条 ins_115 的监视器
                local step = 0
                while not st.dead and step < 4 do
                    local p = photo_index(PHOTO_LIMIT)
                    while step < 4 and p >= PHASE_AT[step + 1] do
                        step = step + 1
                        gen = gen + 1
                        local ph = PHASE[step]
                        phase(self, ph[1], ph[2], ph[3], ph[4], ph[5], ph[6], ph[7], ph[8])
                    end
                    task.Wait(1)
                end
            end)
        end)
    end

    function card:frame()
    end

    function card:del()
        st.dead = true
        photo_damage_off(self)
        sg_clear(lasers)
    end

    boss.card.add({ { card, "22a" } }, LEVEL, CARD_NAME, CARD_ID)
end--凍符「マイナスＫ」（ecl3_c）
---レティ三张符卡（ecl4_a/b/c）公用的「霜精」子机与「冰雨」装饰。
---★ 这些是 Stage 2 外层（do ... end）的 local，三张卡共用；每张卡把自己的
---  st（{ dead = ... }）与子机列表传进来，**别让子机去捕获某一关的状态**。
local SHARD_N, SHARD_R, SHARD_SPEED = 32, 32, 0.5
local FIRE_AT, FIRE_SP2 = 60, 0.5
local DECEL_FLAGS = 0x203                               -- DECEL|FAST|SND
local RAIN_GAP, RAIN_X, RAIN_Y = 2, 192, 128            -- Sub12/13 的 ins_2(2) 与撒点范围
local RAIN_ANG0, RAIN_ANG1 = 1.5707964, 0.0981748

---霜精：自绘 object，按 dir（TH095 弧度）以 0.5 速直线外飞，60 帧后连放
---fire_n 发随机弹（RANDOM、角 ∈ dir±45°、速 sp2~sp1、出膛点在自己附近
---radius px 内随机），随后淡出离场（原作子敌机在脚本跑完时结束，文件头差异 5）。
---opt = { dir, st, list, fire_n（数字或函数）, btype, bcolor, sp1, sp2, flags, recs,
---         radius?, speed? }
class.frost_shard = Class(object, {
    init = function(self, owner, opt)
        local dir = opt.dir
        local radius = opt.radius or SHARD_R
        local st = opt.st
        self.group = GROUP.GHOST
        self.layer = LAYER.ENEMY_BULLET_EF
        self.colli = false
        self.bound = false
        self.x = owner.x + radius * math.cos(dir)
        self.y = owner.y - radius * math.sin(dir)
        self.rot = -math.deg(dir) + 90
        self.dir = dir
        self.spd = opt.speed or SHARD_SPEED
        self._a = 0
        task.New(self, function()
            local hook = sg_tr_hook(opt.recs, opt.flags)
            for _ = 1, FIRE_AT do
                if st.dead then break end
                self.x = self.x + self.spd * math.cos(self.dir)
                self.y = self.y - self.spd * math.sin(self.dir)
                self._a = min(200, self._a + 20)
                task.Wait(1)
            end
            local n = type(opt.fire_n) == "function" and opt.fire_n() or (opt.fire_n or 0)
            for _ = 1, n do
                if st.dead then break end
                local v2 = self.dir + math.pi / 4
                local v3 = self.dir - math.pi / 4
                local v4 = ran:Float(-1, 1) * radius
                local off = ran:Float(-math.pi, math.pi)
                local ox, oy = sg_off(v4, off)
                sg_shot(94, sg_style(opt.btype), ex_color(opt.bcolor), self.x + ox, self.y + oy,
                        1, 1, opt.sp1, opt.sp2, math.deg(v2), math.deg(v3),
                        false, opt.flags, hook)
                ---★ 没有 task.Wait：Sub9/Sub10 的 ins_5 的 time 操作数 = 60 = 标签处指令的
                ---  time ⇒ 跳转后**同帧**继续，fire_n 发在一帧里打完（Sub10 的 3 连发）。
            end
            for i = 1, 10 do
                if st.dead then break end
                self._a = max(0, 200 * (10 - i) / 10)
                task.Wait(1)
            end
            if IsValid(self) then
                object.RawDel(self)
            end
        end)
    end,
    frame = function(self)
        task.Do(self)                                      -- ★ 驱动飞行 / 炸裂协程
    end,
    render = function(self)
        SetImageState("ball_mid14", "mul+add", self._a, 190, 220, 255)
        Render("ball_mid14", self.x, self.y, self.rot, 0.9, 0.9)
    end,
})

---Sub4/Sub5/Sub7/Sub8：沿 dir0 起撒 opt.count 只霜精（每只方向差 step）。
---★ 一次只生一只、之间隔 opt.gap 帧（ecl4_a 的 ins_5 在 t=2 ⇒ gap=2；ecl4_b 的在 t=4
---  ⇒ gap=4），ecl4_b 的 Sub5/Sub7 还多 opt.delay=2 帧入口延迟（它的 ins_6 在 t=2）。
---  原作这两条都是 ins_117 起的**独立子上下文**、不挡父脚本 ⇒ 这里自己开一条协程。
local function spawn_arc(owner, dir0, step, opt)
    task.New(owner, function()
        local n = opt.count or SHARD_N
        if opt.delay then task.Wait(opt.delay) end
        local d = dir0
        for i = 1, n do
            if opt.st.dead then return end
            local o = {}
            for k, v in pairs(opt) do o[k] = v end
            o.dir = d
            opt.list[#opt.list + 1] = New(class.frost_shard, owner, o)
            d = d + step
            if i < n then task.Wait(opt.gap or 2) end
        end
    end)
end

local function clear_shards(list)
    for i = #list, 1, -1 do
        if IsValid(list[i]) then
            task.Clear(list[i])
            object.RawDel(list[i])
        end
        list[i] = nil
    end
end

---冰雨（Sub12/13）：每一 RAIN_GAP 帧在场地顶部随机横坐标投一颗下落弹。
---原作是一个 ins_83 子敌机 + ins_4 自循环；这里做成自绘（空）object。
class.ice_rain = Class(object, {
    init = function(self, owner, opt)
        self.group = GROUP.GHOST
        self.layer = LAYER.ENEMY_BULLET - 10
        self.colli = false
        self.bound = false
        self.x, self.y = owner.x, owner.y
        self.rot = 0
        local st = opt.st
        task.New(self, function()
            while IsValid(self) and not st.dead do
                local x = ran:Float(-RAIN_X, RAIN_X)
                local y = field_y(ran:Float(0, RAIN_Y))
                local a = ran:Float(-1, 1) * RAIN_ANG1 + RAIN_ANG0   -- ins_27(rnd_f32s)×0.0982+π/2
                local sp = ran:Float(0, 1) + 0.5
                sg_shot(87, sg_style(0), ex_color(15), x, y,
                        1, 1, sp, 0.5, math.deg(a), 0, false, DECEL_FLAGS)
                task.Wait(RAIN_GAP)
            end
        end)
    end,
    frame = function(self)
        task.Do(self)                                      -- ★ 驱动撒冰尘的循环协程
    end,
    render = function(self)
    end,
})

local function spawn_rain(owner, opt)
    return New(class.ice_rain, owner, opt)
end

do  -- 11 レティ 非符（ecl4_a，组 23a 第 1 张）
    ---原作这一幕**不亮卡名**（Sub2 的 t=130 是 id=0）：本体每 350 帧重开一轮，一轮里
    ---朝自机方向 ±90° 起、各撒 32 只「霜精」子机（沿各自方向以 0.5 速直线外飞，
    ---60 帧后朝自己前方 ±45° 内放 1 颗随机速小玉）；两轮之间本体在框里挪两次位。
    ---另有一只一次性「冰雨」装饰子机，每 2 帧在场地顶部随机横坐标投一颗下落弹。
    ---拍中第 3 张后主脚本换成 Sub6：清屏 + 清子机 + 换新的冰雨 + 每半轮撒 3 连发的霜精。
    ---数据源 /tmp/D95x_ecl4_a.txt。骨架：
    ---  · Sub2：ins_141(4) + ins_115(0,3,6) + ins_63(-128,-64) → t=100 ins_64(30,4,0,128)
    ---    落到 (0,128)（我们的 (0,96)）→ t=130 的 id=0（**非符不亮卡名**）
    ---    + ins_75(-160,96,160,192) + ins_149(1) + ins_52(3) 起 Sub3。
    ---  · Sub3（@728，350 帧一轮）：extraIntV1=60 + ins_83(12)（冰雨装饰，只起一次）
    ---    + ins_117(0,4) → t=105 ins_67(60,4,1) → t=175 ins_117(0,5)
    ---    → t=280 ins_67(60,4,1) → t=350 ins_4(0,−144) 跳回 **@764**（ins_117(0,4)）。
    ---  · Sub4（@940，一次性）：floatV0 = playerAngle + π/2、floatV1=0.5、extraIntV0=32；
    ---    每轮「ins_84(9, 极坐标(floatV0, 32)) 生 1 只霜精 + floatV0 −= 0.0981748」共 32 只，
    ---    间隔由 t=2 的 ins_5 决定 ⇒ **每 2 帧一只、撒满 64 帧**。
    ---    Sub5（@1140）同形，只是 floatV0 = playerAngle − π/2、每轮 += 0.0981748。
    ---  · Sub9/Sub10（霜精脚本 @1976/@2300）：slot0 DECEL；ins_65(floatV0, floatV1=0.5)（直线外飞）；
    ---    t=60 起每帧一颗 —— floatV2 = floatV0+π/4、floatV3 = floatV0−π/4、
    ---    floatV4 = randF32s×32、出膛点 = 自己位置 + 极坐标(floatV4, rand(−π,π))；
    ---    RANDOM 型1/色6、速 0.5~2、角 ∈ [floatV3, floatV2]、tf=DECEL|FAST|SND。
    ---    Sub9 的 extraIntV0=1（只 1 发）、Sub10=3（连放 3 发）。
    ---  · Sub12/Sub13（冰雨装饰 @2664/@3004）：每 2 帧一颗 —— 出膛点 = (randS×192, rand×128)
    ---    （TH095 绝对坐标，用 shootOffset = 该点 − world 实现）、角 = randS×0.0982 + π/2、
    ---    速 = rand + 0.5、FAN 型0/色15、tf=DECEL|FAST|SND；ins_4(0,−264) 跳回。
    ---  · Sub6（拍中第 3 张起接管）：t=30 ins_102 清屏 + ins_85 清子机 + ins_83(13)（换冰雨）
    ---    + extraIntV1=60 + ins_117(0,7) → t=135 ins_67(60,4,1) → t=205 ins_117(0,8)
    ---    → t=310 ins_67(60,4,1) → t=380 ins_4(30,−144) 跳回 **@1400**（ins_117(0,7)）。
    ---    Sub7/Sub8 与 Sub4/Sub5 同形，步长改 0.1963495、子机脚本换 Sub10。
    ---  · Sub0/Sub1 是死亡/退场 ⇒ 不实现。
    local BOSS_X, BOSS_START_Y = -128, field_y(-64)
    local HOME_X, HOME_Y = 0, field_y(128)              -- 0 / 96
    local ENTRY_WAIT, ENTRY_TIME = 100, 30
    local EASE_OUT = VALUE_SET.DECEL

    local PHOTO_LIMIT = 4                               -- ins_141(4)
    local CARD_NAME = ""                                -- 非符：原作 t=130 是 id=0
    local CARD_TIME, CARD_HP = 50, 900
    local CARD_ID = 530
    local BOX = { -160, 96, 160, 192 }                  -- ins_75

    local ROUND = 350                                   -- Sub3 一轮
    local BMOVE_AT, BMOVE_FRAMES, BMOVE_SPEED = 105, 60, 1
    local STEP_A, STEP_B = 0.0981748, -0.0981748        -- ±5.625°（TH095 弧度）
    local STEP_C, STEP_D = 0.1963495, -0.1963495        -- ±11.25°（Sub7/Sub8）
    local FIRE_SP1 = 2                                  -- RANDOM 的 sp1（sp2 = FIRE_SP2）

    local SWITCH_AT = 3                                 -- ins_115(0,3,6)
    local SUB6_AT = 30
    local st = { dead = false }
    local gen = 0                                       -- 主脚本代号（ins_115 会 +1）
    local shards = {}                                   -- 霜精
    local rain_obj = nil                                -- 冰雨装饰
    local lasers = {}

    local SHARD_RECS = { sg_rec(SG_DECEL, 0, -1, -1, -1, -1) }
    local function arc(owner, dir, step, fire_n)
        spawn_arc(owner, dir, step, { st = st, list = shards, fire_n = fire_n,
                btype = 1, bcolor = 6, sp1 = FIRE_SP1, sp2 = FIRE_SP2,
                flags = DECEL_FLAGS, recs = SHARD_RECS, gap = 2 })
    end

    local function set_rain(owner)
        if IsValid(rain_obj) then
            task.Clear(rain_obj)
            object.RawDel(rain_obj)
        end
        rain_obj = spawn_rain(owner, { st = st })
    end

    ---Sub3（@728）：350 帧一轮。
    local function sub3(owner)
        local g = gen
        set_rain(owner)                                     -- ins_83(12)
        task.New(owner, function()
            while not st.dead and g == gen do
                arc(owner, th_aim(owner.x, owner.y) + math.pi / 2, STEP_B, 1)
                task.Wait(BMOVE_AT)
                if st.dead or g ~= gen then return end
                sg_bmove(owner, st, BMOVE_FRAMES, 4, BMOVE_SPEED, BOX)
                task.Wait(70)
                if st.dead or g ~= gen then return end
                arc(owner, th_aim(owner.x, owner.y) - math.pi / 2, STEP_A, 1)
                task.Wait(BMOVE_AT)
                if st.dead or g ~= gen then return end
                sg_bmove(owner, st, BMOVE_FRAMES, 4, BMOVE_SPEED, BOX)
                task.Wait(70)
            end
        end)
    end

    ---Sub6（拍中第 3 张起接管）：清屏 + 清子机 + 换冰雨 + 每半轮撒 3 连发的霜精。
    local function sub6(owner)
        local g = gen
        task.New(owner, function()
            task.Wait(SUB6_AT)
            if st.dead or g ~= gen then return end
            sg_clear(lasers)                                -- ins_102
            clear_shards(shards)                            -- ins_85
            set_rain(owner)                                 -- ins_83(13)
            while not st.dead and g == gen do
                arc(owner, th_aim(owner.x, owner.y) + math.pi / 2, STEP_D, 3)
                task.Wait(70)
                if st.dead or g ~= gen then return end
                task.Wait(35)
                if st.dead or g ~= gen then return end
                sg_bmove(owner, st, BMOVE_FRAMES, 4, BMOVE_SPEED, BOX)
                task.Wait(70)
                if st.dead or g ~= gen then return end
                arc(owner, th_aim(owner.x, owner.y) - math.pi / 2, STEP_C, 3)
                task.Wait(70)
                if st.dead or g ~= gen then return end
                task.Wait(35)
                if st.dead or g ~= gen then return end
                sg_bmove(owner, st, BMOVE_FRAMES, 4, BMOVE_SPEED, BOX)
                task.Wait(70)
            end
        end)
    end

    local card = boss.card.New(CARD_NAME, 1, 3, CARD_TIME, CARD_HP)

    function card:before()
        gen = 1
        shards = {}
        rain_obj = nil
        lasers = {}
    end

    function card:init()
        photo_damage_on(self, PHOTO_LIMIT)
        self.x, self.y = BOSS_X, BOSS_START_Y
        st.dead = false
        task.New(self, function()
            task.Wait(ENTRY_WAIT)
            task.MoveTo(HOME_X, HOME_Y, ENTRY_TIME, EASE_OUT)
            sub3(self)
            task.New(self, function()                   -- ins_115(0,3,6) 的监视器
                while not st.dead do
                    if photo_index(PHOTO_LIMIT) >= SWITCH_AT then
                        gen = gen + 1
                        sub6(self)
                        return
                    end
                    task.Wait(1)
                end
            end)
        end)
    end

    function card:frame()
    end

    function card:del()
        st.dead = true
        photo_damage_off(self)
        sg_clear(lasers)
        clear_shards(shards)
        if IsValid(rain_obj) then
            task.Clear(rain_obj)
            object.RawDel(rain_obj)
        end
        rain_obj = nil
    end

    boss.card.add({ { card, "23a" } }, LEVEL, CARD_NAME, CARD_ID)
end--レティ 非符（ecl4_a）

do  -- 13 レティ 寒符「コールドスナップ」（ecl4_b，组 23a 第 2 张）
    ---原作：本体每 200 帧一轮 —— t=0 朝自机方向 ±90° 各撒 16 只霜精（两弧的扫描方向相反），
    ---t=60 挪一次位；t=90 再各撒 16 只（这次两弧都向同一侧扫）；t=120 再挪一次。
    ---每只霜精沿自己方向以 0.5 速直线外飞，60 帧后朝自己前方 ±45° 连放 (3 + 拍中张数) 发
    ---随机速小玉（左弧型1/色8、右弧型1/色6），随后淡出。
    ---★ ecl4_b 的 Sub2 **没有** ins_115：Sub8/Sub9/Sub10/Sub14/Sub15（「拍中第 3 张后
    ---  清屏换冰雨」那一支）在原作里**没有任何调用者**，是死代码（本文档口径：跳过）。
    ---数据源 /tmp/D95x_ecl4_b.txt。骨架：
    ---  · Sub2：ins_141(4) + ins_63(128,-64) → t=100 ins_64(30,4,0,160) 落到 (0,160)
    ---    （我们的 (0,64)）→ t=130 亮卡名 + ins_75(-160,128,160,224) + ins_52(3) 起 Sub3。
    ---  · Sub3（@756，200 帧一轮）：extraIntV1=60 + ins_117(0,4)/(1,5)
    ---    → t=60 ins_67(60,4,1.2) → t=90 ins_117(0,6)/(1,7) → t=120 ins_67(80,4,1.4)
    ---    → t=200 ins_4(0,−172) 跳回 **@776**（ins_117(0,4)）。
    ---  · Sub4（@980）：floatV0 = playerAngle+π/2、floatV1=0.5、extraIntV0=16；
    ---    每轮「ins_84(11, 极坐标(floatV0,32)) 生 1 只霜精 + floatV0 −= 0.1963495」共 16 只，
    ---    t=4 的 ins_5 ⇒ **每 4 帧一只、撒满 60 帧**（Sub5/Sub7 的入口在 t=2、ins_5 在 t=6）。
    ---    Sub5（@1180）用 playerAngle−π/2，同样 −=。Sub6/Sub7 都是 +=，子机脚本分别 11/12。
    ---  · Sub11/Sub12（霜精脚本 @2416/@2744）：slot0 DECEL；ins_65(floatV0, 0.5)（直线外飞）；
    ---    t=60 起每帧一颗 —— extraIntV0 = 3 + 拍中张数；floatV2 = floatV0+π/4、
    ---    floatV3 = floatV0−π/4、floatV4 = randF32s×32、出膛点 = 自己位置 + 极坐标(floatV4, rand)；
    ---    RANDOM（Sub11 型1/色8、Sub12 型1/色6）、速 0.5~1.5、角 ∈ [floatV3, floatV2]、
    ---    tf=DECEL|FAST|SND。
    ---  · Sub0/Sub1 是死亡/退场 ⇒ 不实现。
    local BOSS_X, BOSS_START_Y = 128, field_y(-64)
    local HOME_X, HOME_Y = 0, field_y(160)              -- 0 / 64
    local ENTRY_WAIT, ENTRY_TIME = 100, 30
    local EASE_OUT = VALUE_SET.DECEL

    local PHOTO_LIMIT = 4                               -- ins_141(4)
    local CARD_NAME = "寒符「コールドスナップ」"
    local CARD_TIME, CARD_HP = 50, 900
    local CARD_ID = 531
    local BOX = { -160, 128, 160, 224 }                 -- ins_75

    local ROUND = 200                                   -- Sub3 一轮
    local SHARD_N2 = 16                                 -- Sub4~Sub7 每次 16 只
    local STEP_E = 0.1963495                            -- ±11.25°（TH095 弧度）
    local FIRE_SP3 = 1.5                                -- Sub11/12 的 sp1

    local st = { dead = false }
    local gen = 0
    local shards = {}
    local lasers = {}

    local SHARD_RECS = { sg_rec(SG_DECEL, 0, -1, -1, -1, -1) }
    ---★ 原作 Sub11/Sub12 发射的是 `ins_94(1, C, 1, 1, 1.5, 0.5, f2, f3, 515)`
    ---（EnemyShotDispatch.cpp:120-160 的 ShotArgs：bulletType / color / count1 / count2 /
    --- speed1 / speed2 / angle / angleStep / flags）⇒ **型号恒为 1**，两弧只差**色号**
    ---（+π/2 一侧 Sub11 色 8；−π/2 一侧 Sub12 色 6）。别把色号填进 btype。
    local function arc2(owner, dir0, step, bcolor, delay)
        spawn_arc(owner, dir0, step, {
            st = st, list = shards, count = SHARD_N2, delay = delay, gap = 4,
            btype = 1, bcolor = bcolor, sp1 = FIRE_SP3, sp2 = FIRE_SP2,
            flags = DECEL_FLAGS, recs = SHARD_RECS,
            fire_n = function() return 3 + photo_index(PHOTO_LIMIT) end,
        })
    end

    ---Sub3（@756）：200 帧一轮。
    local function sub3(owner)
        local g = gen
        task.New(owner, function()
            while not st.dead and g == gen do
                arc2(owner, th_aim(owner.x, owner.y) + math.pi / 2, -STEP_E, 8, 0)  -- Sub4
                arc2(owner, th_aim(owner.x, owner.y) - math.pi / 2, -STEP_E, 6, 2)  -- Sub5（t=2 起）
                task.Wait(60)
                if st.dead or g ~= gen then return end
                sg_bmove(owner, st, 60, 4, 1.2, BOX)        -- t=60
                task.Wait(30)
                if st.dead or g ~= gen then return end
                arc2(owner, th_aim(owner.x, owner.y) + math.pi / 2, STEP_E, 8, 0)   -- Sub6
                arc2(owner, th_aim(owner.x, owner.y) - math.pi / 2, STEP_E, 6, 2)   -- Sub7（t=2 起）
                task.Wait(30)
                if st.dead or g ~= gen then return end
                sg_bmove(owner, st, 80, 4, 1.4, BOX)        -- t=120
                task.Wait(80)                               -- t=200 → 跳回 t=0
            end
        end)
    end

    local card = boss.card.New(CARD_NAME, 1, 3, CARD_TIME, CARD_HP)

    function card:before()
        gen = 1
        shards = {}
        lasers = {}
    end

    function card:init()
        photo_damage_on(self, PHOTO_LIMIT)
        self.x, self.y = BOSS_X, BOSS_START_Y
        st.dead = false
        task.New(self, function()
            task.Wait(ENTRY_WAIT)
            task.MoveTo(HOME_X, HOME_Y, ENTRY_TIME, EASE_OUT)
            sub3(self)
        end)
    end

    function card:frame()
    end

    function card:del()
        st.dead = true
        photo_damage_off(self)
        sg_clear(lasers)
        clear_shards(shards)
    end

    boss.card.add({ { card, "23a" } }, LEVEL, CARD_NAME, CARD_ID)
end--寒符「コールドスナップ」（ecl4_b）

do  -- 15 レティ 冬符「ノーザンウイナー」（ecl4_c，组 23a 第 3 张）
    ---原作：本体每「80 + (130 − 23×拍中张数) 帧」一轮 —— 每轮先放一组**自机狙的 3 连大玉**
    ---（型17、色1、速 3.2、自机方向 ±60°），再朝**远离自机**的方向平移 30 px，
    ---然后在框里挪一次位，最后原地冻结 (130 − 23×拍中张数) 帧（拍照越多节奏越快）。
    ---★ ecl4_c 的 Sub7/Sub8/Sub9/Sub10/Sub11（撒霜精 + 清屏那几支）在原作里**没有任何
    ---  调用者**（入口 Sub3 只 ins_52(4)），是死代码；本文档口径：跳过。Sub6 是
    ---  ins_118(1) 的「把大玉换成额外目标」特效，也不影响发弹（跳过）。
    ---数据源 /tmp/D95x_ecl4_c.txt。骨架：
    ---  · Sub3：ins_55(2)+ins_81(3)+ins_109(0)+ins_77(24,24)+ins_141(5)
    ---    +ins_108(1,31)/ins_108(2,30)+ins_143(1,130)+ins_63(128,-64)
    ---    → t=100 ins_64(30,4,0,160) 落到 (0,160)（我们的 (0,64)）→ t=130 亮卡名
    ---    +ins_75(-160,96,160,192)+ins_149(1.3)+ins_52(4) 起 Sub4。
    ---  · Sub4（@1172）：extraIntV1=60 + ins_117(1,6)（特效）+ ins_117(0,5)（大玉）
    ---    + ins_66(20,4,playerAngle,−1.5)（沿自机方向 −1.5 px/帧走 20 帧 = 远离自机 30 px）
    ---    → t=40 ins_144 → t=60 ins_67(60,4,1.2) + intV0 = 130 − 23×photoIndex + ins_2(intV0)
    ---    （冻结）→ t=80 ins_4(0,−164) 跳回 **@1212**（ins_117(0,5)）。
    ---  · Sub5（@1408，一次性）：FAN_AIM 型17/色1、c1=3、速 3.2、步长 1.0471976（60°）⇒
    ---    自机方向 ±60° 各一颗大玉；tf=SLOW|SND（没有变换记录）。
    ---  · Sub0/Sub1/Sub2 是子机脚本/死亡/退场 ⇒ 不实现。
    local BOSS_X, BOSS_START_Y = 128, field_y(-64)
    local HOME_X, HOME_Y = 0, field_y(160)              -- 0 / 64
    local ENTRY_WAIT, ENTRY_TIME = 100, 30
    local EASE_OUT = VALUE_SET.DECEL

    local PHOTO_LIMIT = 5                               -- ins_141(5)
    local CARD_NAME = "冬符「ノーザンウイナー」"
    local CARD_TIME, CARD_HP = 50, 900
    local CARD_ID = 532
    local BOX = { -160, 96, 160, 192 }                  -- ins_75

    local MOVE_IN = 20                                  -- ins_66 的 20 帧
    local MOVE_IN_SPEED = -1.5                          -- 负 = 远离自机
    local BMOVE_AT, BMOVE_FRAMES, BMOVE_SPEED = 60, 60, 1.2
    local FREEZE_BASE, FREEZE_STEP = 130, 23            -- ins_2 的帧数
    local ROUND = 80                                    -- 固定部分（不含冻结）

    local FAN_N, FAN_TYPE, FAN_COLOR = 3, 17, 1
    local FAN_SPEED, FAN_STEP = 3.2, 1.0471976          -- 60°
    local FAN_FLAGS = 0x208                             -- SLOW|SND

    local st = { dead = false }
    local gen = 0
    local lasers = {}

    ---Sub5（@1408）：自机狙的 3 连大玉（±60°、速 3.2）。
    local function sub5(owner)
        sg_shot(86, sg_style(FAN_TYPE), ex_color(FAN_COLOR), owner.x, owner.y,
                FAN_N, 1, FAN_SPEED, 0.5, 0, math.deg(FAN_STEP), true, FAN_FLAGS, nil)
    end

    ---Sub4（@1172）：主循环 —— 每轮：大玉 → 远离自机 30 px → 挪位 → 冻结。
    local function sub4(owner)
        local g = gen
        task.New(owner, function()
            while not st.dead and g == gen do
                sub5(owner)
                sg_polar_move(owner, st, MOVE_IN, 4, th_aim(owner.x, owner.y), MOVE_IN_SPEED)
                task.Wait(BMOVE_AT)
                if st.dead or g ~= gen then return end
                sg_bmove(owner, st, BMOVE_FRAMES, 4, BMOVE_SPEED, BOX)
                local freeze = FREEZE_BASE - FREEZE_STEP * photo_index(PHOTO_LIMIT)
                if freeze > 0 then
                    task.Wait(freeze)
                end
                task.Wait(ROUND - BMOVE_AT)
            end
        end)
    end

    local card = boss.card.New(CARD_NAME, 1, 3, CARD_TIME, CARD_HP)

    function card:before()
        gen = 1
        lasers = {}
    end

    function card:init()
        photo_damage_on(self, PHOTO_LIMIT)
        self.x, self.y = BOSS_X, BOSS_START_Y
        st.dead = false
        task.New(self, function()
            task.Wait(ENTRY_WAIT)
            task.MoveTo(HOME_X, HOME_Y, ENTRY_TIME, EASE_OUT)
            sub4(self)
        end)
    end

    function card:frame()
    end

    function card:del()
        st.dead = true
        photo_damage_off(self)
        sg_clear(lasers)
    end

    boss.card.add({ { card, "23a" } }, LEVEL, CARD_NAME, CARD_ID)
end--冬符「ノーザンウイナー」（ecl4_c）

end  -- Stage 2


---──────────────────── Stage 1（scene group 0 = world01）── 公共工具 / 六张卡 ────────────────────
---原作 scene group 0 是 world01（リグル・ナイトバグ / ルーミア）。SceneSelect.cpp 的
---TH095_SCENE 表里 scene 0..5 共六幕（两位角色各自的第 1 幕都是**非符**、不亮卡名）：
---   0 ecl1_a リグル 非符（不亮卡名）          1 ecl2_a ルーミア 非符（不亮卡名）
---   2 ecl1_b リグル 蛍符「地上の恒星」        3 ecl2_b ルーミア 闇符「ダークサイドオブザムーン」
---   4 ecl1_c リグル 蝶符「バタフライストーム」 5 ecl2_c ルーミア 夜符「ミッドナイトバード」
---（角色对号与卡名都是从 ins_104 的 48 字节 payload 解出来的，别按文件名猜。）
---按「一个角色一个组」拆：组 24 = リグル（scene 0/2/4，第 1 张非符）、
---组 25 = ルーミア（scene 1/3/5，第 1 张非符）。★ 别把两人塞进同一个组的 a/b。
---整组 BGM 沿用 "TH09_5_1"、背景沿用 TH095_bg（和其它 world 一样：本仓库没有 th095_01.wav）。
---数据源 /tmp/D95x_ecl{1,2}_{a..c}.txt（脚本 /tmp/d95dump.py 不入库；ECL 在
---`[th095] …/data/ecl{1,2}_{a..c}.ecl`），各卡注释里的「@地址」都指这几份 dump。
---
---这一组六幕共用同一套外壳（Sub2 的样子）：ins_55(2)+ins_81(3)+ins_109(0)+ins_77(24,24)
---+ins_141(N)+ins_108(0,31)/ins_108(1,30)+ins_143(1,130)[+ins_115(...)]+ins_63(起点) 进场
---→ t=100 的 ins_64(30,4,0,128) 用 30 帧从场外落到中轴（我们的 (0, field_y(128))=(0,96)）
---→ t=130 亮卡名（第 1 幕是 id=0，**非符不亮**）+ ins_75(box) + [ins_149(倍率)] + ins_52(3)。
---★ ins_115(slot, frame, sub)：原作在「已拍张数」达标时把**主上下文整个**换成 sub。
---  EnemyManagerUpdate.cpp:1292 读的 g_PhotoEnemyGame->frameCounter 就是
---  PhotoCapacityCounterTaskView::capturedPhotoCount（PhotoGameTaskExact.inl:119-129），
---  :1280-1310 的 UpdateScheduledEclCalls 用 `capturedPhotoCount >= frame` 触发、触发后
---  该槽置 −1（一次性）。本文件各卡用 gen + 监视器照抄（photo_index 口径见文件中部那一节）。
---★ ins_117(slot, sub) 起的子上下文在**创建那一刻**把父上下文 int/float/extra 四组变量
---  整块抄一份（EclRunTargetHigh.inl:226-235 的 memcpy 0x80）⇒ 之后改父变量不影响子上下文；
---  ins_83/84 生成的子敌机同理（EnemyManagerUpdate.cpp:842-850 的 scriptState 拷贝）。
---★ ins_52(sub) 是**同步调用**（CallSubOnEnemy，EclDependencies.cpp:299-330）：调用者的整块
---  0x230 上下文压栈、子程序以 time=0 起跑，ins_53 弹栈还原（EclRunLow.inl:419-426）
---  ⇒ 子程序跑完前调用者的时间**不走**（ecl1_c 的 Sub9 一跑就是 120 帧，下面按「直接调用」
---  写，自然复现这个阻塞），且子程序里改的变量返回后全部还原。
---★ ins_2(n) 是「冻结」：接下来 n 帧 context 的 time 原地不动、一条指令都不跑
---  （EclRunLow.inl:230-232）⇒ 等价 task.Wait(n)。
---★ ins_4/5 的跳转目标是**当前指令地址 + operand1**（EclRunLow.inl:242-246）；跳转后会在
---  同一帧重取自标（time 被设成 operand0），所以 t=0 的循环体一帧跑完。
---  ins_5(op0,op1,op2) 先把 op2 减 1、减到 ≤0 就落空往下走，否则 time=op0 并跳 op1
---  ⇒ 「op2 遍、每 (ins_5 自己的 t − op0) 帧一遍」。
---★ ins_83/84 生成的子敌机（リグルの蛍）按文件头差异 5 一律做成「有寿命、淡出离场」的
---  自绘 object；它们发的弹按各自的 ECL 照抄。ルーミア的 ecl2_b Sub5 只发 ins_150 装饰
---  ANM（不发射弹）、ecl1_c Sub10/Sub11 是常驻装饰子机（ins_80(8) 反复播 ANM、同样不
---  发射弹）——都忽略，注释里记一笔。
do

---TH095 的极坐标偏移 (半径 r, 弧度 θ) → 我们的相对位移（x 同号、y 取反）。
local function sg_off(r, th_rad)
    return r * math.cos(th_rad), -r * math.sin(th_rad)
end

---自机在 TH095 空间的角（弧度、顺时针为正）：sg_aim 给的是本仓库的度（逆时针为正），
---取反再转弧度即得 TH095 的 playerAngle（见文件头「坐标系与角度」）。
local function th_aim(x, y)
    return math.rad(sg_aim(x, y))
end

do  -- 533 リグル 非符（ecl1_a，组 24a 第 1 张）
    ---原作这一幕**不亮卡名**（Sub2 的 t=130 是 id=0）：本体落到中轴后每 264 帧重开一轮，
    ---一轮里槽 0 先跑 Sub4（10 向环、每 6 帧一发、共 12 发，弹带三段极坐标自旋），
    ---t=132 换成 Sub5（同样的环、自旋方向相反）；t=72 / t=204 各挪一次。
    ---拍中第 2 张后主脚本换成 Sub6：清一次屏，之后每 360 帧一轮 —— t=90 / t=270 各重起一次
    ---「槽 0（Sub9↔Sub8 的 20 连快环）+ 槽 1（Sub7 的 6 发大环）」，t=210 / t=390 各挪一次。
    ---数据源 /tmp/D95x_ecl1_a.txt。骨架：
    ---  · Sub2：… ins_141(3) + ins_115(0,2,6) + ins_63(-128,-64) 进场 → t=100
    ---    ins_64(30,4,0,128) 落到 (0,128)（我们的 (0,96)）→ t=130 的 id=0（非符）
    ---    + ins_75(-160,96,160,192) + ins_52(3) 起 Sub3。
    ---  · Sub3（@696，264 帧一轮）：ins_6(extraIntV1,60) → ins_117(0,4) → t=72
    ---    ins_67(60,4,1.7) → t=132 ins_117(0,5) → t=204 ins_67(60,4,1.7)
    ---    → t=264 ins_4(0,−120) 跳回 **@716**（t=0 的 ins_117(0,4)）。
    ---  · Sub4（@868）/Sub5（@1120，f1 符号相反）：三条 ins_101（POLAR、allow=0）给出
    ---    「±1.5°/帧 30 帧 → ∓1.5°/帧 60 帧 → ±1.5°/帧 60 帧」；t=1 floatV3 = playerAngle
    ---    → CIRCLE 型1/色13、10 发、速 3、tf=FAST|POLAR|SND(0x222)；t=7 ins_5(1,−44,12)
    ---    ⇒ 12 发、每 (7−1)=6 帧一发；t=7 ins_53 返回。
    ---  · Sub6（@1372，拍中第 2 张）：t=90 ins_102 清屏 + 起槽 0/1 → t=210 ins_67 →
    ---    t=270 重起槽 0/1 → t=390 ins_67 → t=450 ins_4(90,−160) 跳回 **@1404**
    ---    （t=90 的 ins_117(0,9)）⇒ 之后每 (450−90)=**360 帧**一轮。
    ---  · Sub7（@1596）：槽 0 的表头是 DECEL(0x1) 但 tf=0x202 里没有 0x1 ⇒ 空转；
    ---    t=32 floatV0 = playerAngle → CIRCLE 型12/色6、6 发、速 3、step=30°；
    ---    t=40 ins_5(32,−44,12) ⇒ 12 发、每 (40−32)=8 帧一发。
    ---  · Sub8（@1768）= Sub4、Sub9（@2020）= Sub5，但 extraIntV0 = 20（20 连、仍每 6 帧）。
    local BOSS_X, BOSS_START_Y = -128, field_y(-64)
    local HOME_X, HOME_Y = 0, field_y(128)              -- 0 / 96
    local ENTRY_WAIT, ENTRY_TIME = 100, 30
    local EASE_OUT = VALUE_SET.DECEL

    local PHOTO_LIMIT = 3                               -- ins_141(3)
    local CARD_NAME = ""                                -- 非符：原作 t=130 是 id=0
    local CARD_TIME, CARD_HP = 50, 900
    local CARD_ID = 533
    local BOX = { -160, 96, 160, 192 }                  -- ins_75

    local ROUND = 264                                   -- Sub3 一轮（ins_4(0,−120)）
    local MOVE_AT1, MOVE_AT2 = 72, 204                  -- ins_67 的两个时刻
    local SWITCH_AT = 132                               -- t=132：槽 0 从 Sub4 换成 Sub5
    local MOVE_FRAMES, MOVE_EASE, MOVE_SPEED = 60, 4, 1.7

    local A_SHOTS, A_GAP = 12, 6                        -- Sub4/Sub5 的 ins_5(1,−44,12)
    local A_COUNT, A_SPEED = 10, 3                      -- CIRCLE 型1/色13
    local A_ROT = 0.0261799395                          -- ±1.5°/帧
    local A_ROT_FIRST, A_ROT_REST = 30, 60              -- 三段自旋的时长

    local B_SHOTS, B_GAP = 12, 8                        -- Sub7 的 ins_5(32,−44,12)
    local B_COUNT, B_SPEED, B_STEP = 6, 3, 0.52359879   -- CIRCLE 型12/色6、step=30°

    local S6_AT = 2                                     -- ins_115(0,2,6)
    local S6_LEAD, S6_SPAN = 90, 360                    -- Sub6 的起点 / 一轮
    local S6_SWITCH, S6_MOVE = 180, 120                 -- t=90→270 / t=90→210 的间隔
    local C_SHOTS = 20                                  -- Sub8/Sub9 的 extraIntV0 = 20

    local st = { dead = false }
    local gen = 0                                       -- 主脚本代号（ins_115 会 +1）
    local lasers = {}

    ---Sub4/Sub5/Sub8/Sub9 的弹变换表：三条 POLAR 串行（allow=0 ⇒ 严格逐条接），
    ---±1.5°/帧 走 30 帧、反向 60 帧、再正向 60 帧；f0 是速度增量 = 0 ⇒ 只自旋不加速。
    ---表里的角一律换成本仓库口径（sg_deg 取反）。
    local function hook_polar(sign)
        return sg_tr_hook({
            sg_rec(SG_POLAR, 0, A_ROT_FIRST, -1, 0, sg_deg(sign * A_ROT)),
            sg_rec(SG_POLAR, 0, A_ROT_REST, -1, 0, sg_deg(-sign * A_ROT)),
            sg_rec(SG_POLAR, 0, A_ROT_REST, -1, 0, sg_deg(sign * A_ROT)),
        }, 0x222)
    end

    local hook_ccw = hook_polar(1)                      -- Sub4/Sub8（TH095 f1 = +1.5°）
    local hook_cw = hook_polar(-1)                      -- Sub5/Sub9

    ---Sub4/Sub5/Sub8/Sub9：shots 发 10 向环，每 A_GAP 帧一发，基准角固定成
    ---「子上下文 t=1 时刻的自机角」（原作 floatV3 只赋一次）。
    local function ring_shots(owner, hook, shots)
        task.New(owner, function()
            task.Wait(1)
            local a = math.deg(th_aim(owner.x, owner.y))
            for i = 1, shots do
                if st.dead then return end
                sg_shot(89, sg_style(1), ex_color(13), owner.x, owner.y,
                        A_COUNT, 1, A_SPEED, 1.5, a, 0, false, 0x222, hook)
                if i < shots then task.Wait(A_GAP) end
            end
        end)
    end

    ---Sub7（@1596）：12 波 6 向 30° 扇，每 8 帧一波，基准角固定成 t=32 的自机角。
    local function fan_shots(owner)
        task.New(owner, function()
            task.Wait(32)
            local a = math.deg(th_aim(owner.x, owner.y))
            for i = 1, B_SHOTS do
                if st.dead then return end
                sg_shot(89, sg_style(12), ex_color(6), owner.x, owner.y,
                        B_COUNT, 1, B_SPEED, 1.5, a, math.deg(B_STEP), false, 0x202)
                if i < B_SHOTS then task.Wait(B_GAP) end
            end
        end)
    end

    ---Sub3（@696）：进场后的主循环，264 帧一轮 —— 起槽 0、挪、换槽 0、挪。
    local function sub3(owner)
        local g = gen
        task.New(owner, function()
            while not st.dead and g == gen do
                ring_shots(owner, hook_ccw, A_SHOTS)            -- ins_117(0,4)  t=0
                task.Wait(MOVE_AT1)                             -- t=72
                if st.dead or g ~= gen then return end
                sg_bmove(owner, st, MOVE_FRAMES, MOVE_EASE, MOVE_SPEED, BOX)
                task.Wait(MOVE_FRAMES)                          -- t=132
                if st.dead or g ~= gen then return end
                ring_shots(owner, hook_cw, A_SHOTS)             -- ins_117(0,5)  t=132
                task.Wait(MOVE_AT2 - SWITCH_AT)                 -- t=204
                if st.dead or g ~= gen then return end
                sg_bmove(owner, st, MOVE_FRAMES, MOVE_EASE, MOVE_SPEED, BOX)
                task.Wait(ROUND - MOVE_AT2 - MOVE_FRAMES)       -- t=264
            end
        end)
    end

    ---Sub6（@1372，拍中第 2 张起接管）：t=90 清一次屏，之后每 360 帧跑两段
    ---「20 连快环（槽 0）+ 12 波 6 发扇（槽 1）」，中间各挪一次。
    local function sub6(owner)
        local g = gen
        task.New(owner, function()
            task.Wait(S6_LEAD)                                  -- t=90
            if st.dead or g ~= gen then return end
            sg_clear(lasers)                                    -- ins_102
            while not st.dead and g == gen do
                ring_shots(owner, hook_cw, C_SHOTS)             -- ins_117(0,9)  t=90
                fan_shots(owner)                                -- ins_117(1,7)  t=90
                task.Wait(S6_MOVE)                              -- t=210
                if st.dead or g ~= gen then return end
                sg_bmove(owner, st, MOVE_FRAMES, MOVE_EASE, MOVE_SPEED, BOX)
                task.Wait(S6_SWITCH - S6_MOVE)                  -- t=270
                if st.dead or g ~= gen then return end
                ring_shots(owner, hook_ccw, C_SHOTS)            -- ins_117(0,8)  t=270
                fan_shots(owner)                                -- ins_117(1,7)  t=270
                task.Wait(S6_MOVE)                              -- t=390
                if st.dead or g ~= gen then return end
                sg_bmove(owner, st, MOVE_FRAMES, MOVE_EASE, MOVE_SPEED, BOX)
                task.Wait(S6_SPAN - S6_SWITCH - S6_MOVE)        -- t=450 → 回到 t=90
            end
        end)
    end

    local card = boss.card.New(CARD_NAME, 1, 3, CARD_TIME, CARD_HP)

    function card:before()
        gen = 1
        lasers = {}
    end

    function card:init()
        photo_damage_on(self, PHOTO_LIMIT)
        self.x, self.y = BOSS_X, BOSS_START_Y
        st.dead = false
        task.New(self, function()
            task.Wait(ENTRY_WAIT)
            task.MoveTo(HOME_X, HOME_Y, ENTRY_TIME, EASE_OUT)
            sub3(self)
            task.New(self, function()                   -- ins_115(0,2,6) 的监视器
                while not st.dead do
                    if photo_index(PHOTO_LIMIT) >= S6_AT then
                        gen = gen + 1
                        sub6(self)
                        return
                    end
                    task.Wait(1)
                end
            end)
        end)
    end

    function card:frame()
    end

    function card:del()
        st.dead = true
        photo_damage_off(self)
        sg_clear(lasers)
    end

    boss.card.add({ { card, "24a" } }, LEVEL, CARD_NAME, CARD_ID)
end--リグル 非符（ecl1_a）

do  -- 534 リグル 蛍符「地上の恒星」（ecl1_b，组 24a 第 2 张）
    ---原作是「本体把六只蛍撒出去、每只蛍再抖出一串小星」：本体每 350 帧一轮 ——
    ---t=0 沿自机方向撒 3 只（相互差 120°）、t=175 再撒 3 只（自旋方向相反），
    ---t=115 / t=290 各挪一次。拍中第 3 张后主脚本换成 Sub4：每 350 帧撒两组、
    ---每组 3 只 Sub5 + 3 只 Sub6（方向沿用上一次的推进值）。
    ---数据源 /tmp/D95x_ecl1_b.txt。骨架：
    ---  · Sub2：… ins_141(5) + ins_115(0,3,4) + ins_63(-128,-64) → t=100 ins_64 → t=130
    ---    ins_104 NAME=蛍符「地上の恒星」+ ins_75(-160,96,160,192) + ins_52(3)。
    ---  · Sub3（@732，350 帧一轮）：ins_6(extraIntV1,60) → t=0 ins_65/70/71 + ins_7 ×4
    ---    （floatV0=playerAngle、floatV1=5、floatV2=±0.0628、floatV3=−0.05）
    ---    → ins_83(5)×3（各差 120°）→ t=115 ins_67(60,4,1) → t=175 重设 + ins_83(5)×3
    ---    → t=290 ins_67(60,4,1) → t=350 ins_4(0,−416) 跳回 **@804**（t=0 的 ins_7(floatV0,…)）。
    ---    ★ t=0 的 ins_65(floatV0,floatV1) 用的是**尚未赋值**的 0/0（ins_7 在它后面）⇒
    ---    本体自身那套「转 floatV2、加速 floatV3」实际是 0，整段只有 ins_67 在动。
    ---  · Sub4（@1252，拍中第 3 张）：t=90 ins_102 清屏 + floatV0 = **rand(−π,π)**、floatV2=−0.0628
    ---    → ins_83(5)×3；再 floatV2=+0.0628 → ins_83(6)×3 → t=175 ins_144 → t=205 ins_67
    ---    → t=265 反过来（ins_83(6)×3 再 ins_83(5)×3）→ t=350 ins_144 → t=380 ins_67
    ---    → t=440 ins_4(90,−712) 跳回 **@1284**（t=90 的 ins_7(floatV0,rand)）⇒ 350 帧一轮。
    ---  · Sub5（@2028，ins_83(5) 的子机）/Sub6（@2548，ins_83(6) 的子机）：两套只有
    ---    「弹型」与 VEC 加速度（0.0333 / 0.0283）不同 —— 见下面的蛍 object。
    local BOSS_X, BOSS_START_Y = -128, field_y(-64)
    local HOME_X, HOME_Y = 0, field_y(128)
    local ENTRY_WAIT, ENTRY_TIME = 100, 30
    local EASE_OUT = VALUE_SET.DECEL

    local PHOTO_LIMIT = 5                               -- ins_141(5)
    local CARD_NAME = "蛍符「地上の恒星」"               -- ins_104
    local CARD_TIME, CARD_HP = 50, 900
    local CARD_ID = 534
    local BOX = { -160, 96, 160, 192 }

    local S3_ROUND = 350                                -- Sub3 一轮
    local S3_MOVE1, S3_MOVE2 = 115, 290                 -- ins_67 的两个时刻
    local S3_SPAWN2 = 175                               -- 第二组蛍
    local MOVE_FRAMES, MOVE_EASE, MOVE_SPEED = 60, 4, 1

    local S4_LEAD, S4_ROUND = 90, 350                   -- Sub4（拍中第 3 张）
    local S4_MOVE1, S4_MOVE2 = 205, 380

    local SPAWN_AT = 3                                  -- ins_115(0,3,4)
    local SPAWN_STEP = 2.09439516                       -- 每只差 +120°（TH095 弧度）
    local FLY_SPEED, FLY_TURN, FLY_ACC = 5, 0.0628318563, -0.05

    local FF_WAVES = 7                                  -- ins_6(extraIntV0,7)
    local FF_GAP = 4                                    -- 两发之间的间隔（ins_15 之间的 t 差）
    ---★ Sub5/Sub6 的循环：一次 8 帧 —— t=0 放 A、t=4 放 B、t=8 的
    ---  `ins_5(0, Sub5_344, ei0)` 把 time 设回 0 并跳回标签（标签处指令的 time 也是 0 ⇒
    ---  跳回那一帧**同帧**接着放 A）。所以全程是「每 4 帧一发、A/B 交替」共
    ---  2×FF_WAVES = 14 发，脚本在第 2×FF_WAVES×FF_GAP = 56 帧跑完 ins_1。
    local FF_LIFE = FF_WAVES * FF_GAP * 2
    local FF_SPEED = 0.05                               -- CIRCLE 的 sp1
    local FF_FLAGS = 0x8212                             -- FAST|VEC|SND|WAIT
    local FF_WAIT, FF_VEC = 60, 60                      -- slot0 WAIT 60 → slot1 VEC 60
    local FF_V5, FF_V6 = 0.0333333351, 0.0283333343     -- Sub5 / Sub6 的 VEC 加速度

    local st = { dead = false }
    local gen = 0
    local lasers = {}
    local ffs = {}                                      -- 活着的蛍（del 时清掉）

    ---蛍的弹变换表（TF=FAST|VEC|SND|WAIT=0x8212）：slot0 WAIT 60（allow=0）→
    ---slot1 VEC 60 帧（f0=加速度、f1≤−990 ⇒ 沿「这条生效那一刻」的弹角加速）。
    ---后面的 POLAR 槽（slot2/3/4）不在 tf 里，原作会跳过（BulletManager.cpp:525）⇒ 不写。
    local function ff_hook(acc)
        return sg_tr_hook({
            sg_rec(SG_WAIT, 0, FF_WAIT, -1, -1, -1),
            sg_rec(SG_VEC, 0, FF_VEC, -1, acc, -999),
        }, FF_FLAGS)
    end

    ---蛍（ins_83(5)/(6) 的子敌机）：从本体位置出发，沿生成时的 floatV0 以速 5 直飞，
    ---每帧转 floatV2（±0.0628）、每帧加速 floatV3（−0.05）；放弹方向每发步进 floatV2×4。
    ---脚本 56 帧跑完 ⇒ 活 56 帧、放 2×FF_WAVES = 14 发（每 4 帧一发，A/B 交替）。
    class.wriggle_firefly = Class(object, {
        init = function(self, owner, opt)
            self.group = GROUP.GHOST
            self.layer = LAYER.ENEMY_BULLET_EF
            self.colli = false
            self.bound = false
            self.x, self.y = owner.x, owner.y
            self.rot = 0
            self._a = 0
            local st = opt.st
            local ang = opt.ang                          -- TH095 弧度（floatV0）
            local spd = opt.spd                          -- floatV1 = 5
            local turn = opt.turn                        -- floatV2
            local acc = opt.acc                          -- floatV3
            local kinds = opt.kinds                      -- {t0型,t0色,t4型,t4色}
            local hook = ff_hook(opt.vaccel)
            local aim = ang                              -- 放弹方向（每发步进 turn×4）
            local step = turn * 4                        -- ins_17(floatV2,4)
            task.New(self, function()
                ---第 0、8、16…发是 A（kinds[1]/kinds[2]），第 4、12…发是 B。
                local plan = {}
                for k = 0, FF_WAVES * 2 - 1 do
                    plan[k * FF_GAP] = (k % 2 == 0)
                            and { { kinds[1], kinds[2] } }
                            or { { kinds[3], kinds[4] } }
                end
                for f = 0, FF_LIFE do
                    if st.dead then break end
                    local p = plan[f]
                    if p then
                        for _, k in ipairs(p) do
                            sg_shot(89, sg_style(k[1]), ex_color(k[2]), self.x, self.y,
                                    1, 1, FF_SPEED, 1.5, math.deg(aim), 0, false,
                                    FF_FLAGS, hook)
                            aim = aim + step
                        end
                    end
                    ---ins_65/70/71 的极坐标飞行：先转角、再加速、再按新速度走一帧
                    ---（EnemyMovement.cpp 的 PHOTO_ENEMY_MOVEMENT_POLAR 分支）。
                    ang = ang + turn
                    spd = spd + acc
                    self.x = self.x + spd * math.cos(ang)
                    self.y = self.y - spd * math.sin(ang)
                    self.rot = -math.deg(ang)
                    self._a = min(200, self._a + 40)
                    if f < FF_LIFE then task.Wait(1) end
                end
                for _ = 1, 8 do                          -- 原作脚本一结束子敌机就消失
                    if not IsValid(self) then return end
                    self._a = max(0, self._a - 25)
                    task.Wait(1)
                end
                if IsValid(self) then object.RawDel(self) end
            end)
        end,
        frame = function(self)
            task.Do(self)                                  -- ★ 驱动极坐标飞行 + 发弹协程
        end,
        render = function(self)
            SetImageState("ball_mid14", "mul+add", self._a, 235, 255, 150)
            Render("ball_mid14", self.x, self.y, 0, 0.7, 0.7)
        end,
    })

    ---ins_83 的 spawn：v0 是生成那一刻父上下文里的 floatV0（TH095 弧度）。
    ---每只生成后（除最后一只）v0 += 120°，与 ins_83 → ins_15 的顺序一致。
    local function spawn_wave(owner, v0, turn, sub)
        for k = 1, 3 do
            if st.dead then return v0 end
            local kinds = (sub == 5) and { 17, 3, 1, 13 } or { 1, 13, 12, 6 }
            local o = New(class.wriggle_firefly, owner,
                    { st = st, ang = v0, spd = FLY_SPEED, turn = turn, acc = FLY_ACC,
                      kinds = kinds, vaccel = (sub == 5) and FF_V5 or FF_V6 })
            ffs[#ffs + 1] = o
            if k < 3 then v0 = v0 + SPAWN_STEP end
        end
        return v0
    end

    ---Sub3（@732）：350 帧一轮 —— t=0 撒 3 只、t=175 再撒 3 只，中间各挪一次。
    local function sub3(owner)
        local g = gen
        task.New(owner, function()
            while not st.dead and g == gen do
                spawn_wave(owner, th_aim(owner.x, owner.y), FLY_TURN, 5)
                task.Wait(S3_MOVE1)                          -- t=115
                if st.dead or g ~= gen then return end
                sg_bmove(owner, st, MOVE_FRAMES, MOVE_EASE, MOVE_SPEED, BOX)
                task.Wait(S3_SPAWN2 - S3_MOVE1 - MOVE_FRAMES)  -- t=175
                if st.dead or g ~= gen then return end
                spawn_wave(owner, th_aim(owner.x, owner.y), -FLY_TURN, 5)
                task.Wait(S3_MOVE2 - S3_SPAWN2)              -- t=290
                if st.dead or g ~= gen then return end
                sg_bmove(owner, st, MOVE_FRAMES, MOVE_EASE, MOVE_SPEED, BOX)
                task.Wait(S3_ROUND - S3_MOVE2 - MOVE_FRAMES)  -- t=350
            end
        end)
    end

    ---Sub4（@1252，拍中第 3 张）：350 帧一轮 —— t=90 清屏后撒 6 只（3×Sub5 + 3×Sub6）、
    ---t=265 再撒 6 只（3×Sub6 + 3×Sub5），中间各挪一次。基准角是 rand(−π,π)。
    local function sub4(owner)
        local g = gen
        task.New(owner, function()
            task.Wait(S4_LEAD)                               -- t=90
            if st.dead or g ~= gen then return end
            sg_clear(lasers)                                 -- ins_102
            while not st.dead and g == gen do
                local v0 = ran:Float(-math.pi, math.pi)
                v0 = spawn_wave(owner, v0, -FLY_TURN, 5)
                spawn_wave(owner, v0, FLY_TURN, 6)
                task.Wait(S4_MOVE1 - S4_LEAD)                -- t=205
                if st.dead or g ~= gen then return end
                sg_bmove(owner, st, MOVE_FRAMES, MOVE_EASE, MOVE_SPEED, BOX)
                task.Wait(60)                                -- t=265
                if st.dead or g ~= gen then return end
                local w0 = ran:Float(-math.pi, math.pi)
                w0 = spawn_wave(owner, w0, -FLY_TURN, 6)
                spawn_wave(owner, w0, FLY_TURN, 5)
                task.Wait(S4_MOVE2 - S4_MOVE1 - 60)          -- t=380
                if st.dead or g ~= gen then return end
                sg_bmove(owner, st, MOVE_FRAMES, MOVE_EASE, MOVE_SPEED, BOX)
                task.Wait(S4_ROUND - S4_MOVE2 - MOVE_FRAMES)  -- t=440 → 回到 t=90
            end
        end)
    end

    local card = boss.card.New(CARD_NAME, 1, 3, CARD_TIME, CARD_HP)

    function card:before()
        gen = 1
        lasers = {}
        ffs = {}
    end

    function card:init()
        photo_damage_on(self, PHOTO_LIMIT)
        self.x, self.y = BOSS_X, BOSS_START_Y
        st.dead = false
        task.New(self, function()
            task.Wait(ENTRY_WAIT)
            task.MoveTo(HOME_X, HOME_Y, ENTRY_TIME, EASE_OUT)
            sub3(self)
            task.New(self, function()                   -- ins_115(0,3,4) 的监视器
                while not st.dead do
                    if photo_index(PHOTO_LIMIT) >= SPAWN_AT then
                        gen = gen + 1
                        sub4(self)
                        return
                    end
                    task.Wait(1)
                end
            end)
        end)
    end

    function card:frame()
    end

    function card:del()
        st.dead = true
        photo_damage_off(self)
        sg_clear(lasers)
        for i = #ffs, 1, -1 do
            if IsValid(ffs[i]) then
                task.Clear(ffs[i])
                object.RawDel(ffs[i])
            end
            ffs[i] = nil
        end
    end

    boss.card.add({ { card, "24a" } }, LEVEL, CARD_NAME, CARD_ID)
end--蛍符「地上の恒星」（ecl1_b）

do  -- 535 リグル 蝶符「バタフライストーム」（ecl1_c，组 24a 第 3 张）
    ---原作是「一群蝶弹飞出去、停一下、折回来变成朝外的蝴蝶」：本体每轮**同步**调一次
    ---Sub9（蝶弹发射器，一跑 120 帧），Sub9 每 4 帧放一波、共 30 波；Sub9 返回后本体
    ---等 tail 帧、挪一次，再回头。拍中第 1/2/3/4 张各换一次主脚本（Sub5/6/7/8），
    ---换的只是「每波几发」（6/7/7/8）与一轮的长度（tail 200/180/160/140）。
    ---数据源 /tmp/D95x_ecl1_c.txt。骨架：
    ---  · Sub2：… ins_141(5) + ins_115(0,1,5)(1,2,6)(2,3,7)(3,4,8) + ins_63(-128,-64)
    ---    → t=100 ins_64(30,4,0,128) → t=130 ins_104 NAME=蝶符「バタフライストーム」
    ---    + ins_75(-160,96,160,192) + ins_52(3)。
    ---  · Sub3（@824）：t=0 extraIntV2=0 / extraIntV3=6 / floatV4=0.0448799 /
    ---    floatV7=π/2 / floatV6=floatV7/2.5，ins_83(10)（装饰）、ins_62、ins_117(0,4)
    ---    （Sub4 = 「等 100 帧」的计时器）、sharedFloat0=floatV4、**ins_52(9)**；
    ---    t=240 ins_67(60,4,**0**) + callFloat0=playerAngle+floatV7 / callInt0=130 /
    ---    callFloat1=128 / extraIntV0=6 + floatV7,floatV6,floatV4 各 ×(−1) + ins_44(装装饰
    ---    插值槽，随即 extraIntV2 归 0)；t=300 ins_4(0,−324) 跳回 **@944**（t=0 的 ins_62）。
    ---    ★ Sub9 里对变量的改动被 ins_53 还原 ⇒ t=240 那批 call* 是**本地重设**的。
    ---  · Sub5/6/7/8（@1340/1840/2340/2840，拍中第 1/2/3/4 张）：ins_85 → t=60 ins_102
    ---    + 重设参数（extraIntV3 = 6/7/7/8）+ ins_83(11) + ins_62 + ins_117(0,4)
    ---    + sharedFloat0 + **ins_52(9)** → t=260/240/220/200 的 ins_67 → t=320/300/280/260
    ---    ins_4(60,−324) 跳回各自的 t=60 块。
    ---  · Sub9（@3340）：见下面 sub9。
    ---  · Sub10（@5076）/Sub11（@5412）：ins_80(8) 的**常驻蝶环发射器**子机。两者
    ---    都是「原地每 5 帧放一圈 8 发（CIRCLE 型15、速 2.5 / 2.5+0.5×拍中、角=起手
    ---    那一刻的自机角），每发带一条**确实存在**的 POLAR 记录（ins_101(0,32,0,120,-1,
    ---    0,±0.006981317) ⇒ 120 帧里 ±0.4°/帧自旋）；色 1/3 每 13 圈交替，13 圈后
    ---    反向，再 13 圈后回起点重取自机角」。Sub10 由 Sub3 起一次（发射前先空等 300
    ---    帧，t=300 才开火）；Sub11 由 Sub5..Sub8 各自的 t=60 起一次、**不空等**。
    ---    两者都由下一阶段 Sub5..Sub8 开头的 ins_85（清子机）清掉 ⇒ 任一时刻至多一个。
    local BOSS_X, BOSS_START_Y = -128, field_y(-64)
    local HOME_X, HOME_Y = 0, field_y(128)
    local ENTRY_WAIT, ENTRY_TIME = 100, 30
    local EASE_OUT = VALUE_SET.DECEL

    local PHOTO_LIMIT = 5                               -- ins_141(5)
    local CARD_NAME = "蝶符「バタフライストーム」"       -- ins_104
    local CARD_TIME, CARD_HP = 50, 900
    local CARD_ID = 535
    local BOX = { -160, 96, 160, 192 }

    local BF_SHOTS, BF_GAP = 30, 4                      -- Sub9：两段 ins_5 合起来 30 波
    local BF_STEP = 0.261799395                         -- CIRCLE 的 step（c2=1 ⇒ 不用）
    local BF_SPEED0 = 2.2                               -- floatV7 的初值
    local BF_DECAY = 0.006                              -- 每波 floatV7 −= 0.006
    local BF_FLAGS = 0x2E244                            -- NORMAL|CHDIR_REL|SND|CULL|SPRITE|WAIT|SND2
    local BF_LEAD_EXTRA = 4                             -- 最后一个 ins_5 落空后才到 ins_53
    local BF_MOVE_TAIL = 60                             -- 收尾的 ins_67(60,4,0) + 等待

    local st = { dead = false }
    local gen = 0
    local taken = 0
    local lasers = {}
    local bf_ems = {}                                   -- Sub10/Sub11 蝶环发射器

    ---每波弹的变换表（ins_101 slot0..slot9 的槽序就是程序序）：
    ---  slot0 CULL 400（allow=1，即时）
    ---  slot1 WAIT 20（allow=1）→ 卡住后面 allow=0 的槽 ⇒ 「先原地停 20 帧」
    ---  slot2 CHDIR_REL i0=25 i1=1 f0=±90° f1=−999（角按 callFloat0 的正负选方向、速度不变）
    ---  slot3/5/8 SET_SPRITE（换贴图，本仓库没有半路换图的接口 ⇒ sg_tr_hook 认掉即走）
    ---  slot4 CHDIR_REL i0=45 i1=1 f0=180° f1=0 ⇒ 边减速到 0 边转半圈（到点后速度 0）
    ---  slot6 WAIT 10（allow=1）
    ---  slot7 CHDIR_REL i0=10 i1=1 f0=+120°/180°/−120° f1=floatV6/floatV5
    ---  slot9 PLAY_SOUND（认掉即走）
    local function bf_hook(callf0, slot7_ang, slot7_spd)
        return sg_tr_hook({
            sg_rec(SG_CULL, 1, 400, -1, -1, -1),
            sg_rec(SG_WAIT, 1, 20, -1, -1, -1),
            sg_rec(SG_CHDIR_R, 0, 25, 1,
                   sg_deg((callf0 >= 0) and math.pi / 2 or -math.pi / 2), -999),
            sg_rec(SG_SET_SPRITE, 0, 1, 14, -1, -1),
            sg_rec(SG_CHDIR_R, 0, 45, 1, sg_deg(math.pi), 0),
            sg_rec(SG_SET_SPRITE, 0, 0, 13, -1, -1),
            sg_rec(SG_WAIT, 1, 10, -1, -1, -1),
            sg_rec(SG_CHDIR_R, 0, 10, 1, slot7_ang, slot7_spd),
            sg_rec(SG_SET_SPRITE, 0, 3, 13, -1, -1),
            sg_rec(SG_SND_T, 0, 26, -1, -1, -1),
        }, BF_FLAGS)
    end

    ---Sub10/Sub11（蝶环发射器，ins_83 的子敌机）：
    ---  · Sub10（Sub3 里起一次）：原地什么都不发，**空等 300 帧**后每 5 帧放一圈 8 发
    ---    （ins_89(15,1,8,1,2.5,0.5,f0,0.2618,544)），13 圈后把自旋方向取反再来 13 圈，
    ---    然后 ins_4(300,Sub10_28) 回起点重取自机角。
    ---  · Sub11（Sub5..Sub8 各自的 t=60 起一次）：同形但不等 300 帧，速度是
    ---    2.5 + 0.5×拍中张数（`ins_27(f1,photoIndex,0.5)` + `ins_15(f1,2.5)`），
    ---    每 26 圈重读一次自机角与速度。
    ---  · 每发的变换表只有 slot0 的 POLAR（allow=0、i0=120、f0=0、f1=±0.006981317）⇒
    ---    弹在 120 帧里以 ±0.4°/帧 自旋，之后直飞（flags=544=SND|POLAR 只放行这一条）。
    local BF_RING_CNT, BF_RING_N = 8, 13               -- 每圈 8 发 / 每半程 13 圈
    local BF_RING_GAP, BF_RING_SPEED = 5, 2.5          -- 每 5 帧一圈 / Sub10 的速度
    local BF_RING_FLAGS = 0x220                        -- SND|POLAR
    local BF_RING_SPIN = 0.006981317                   -- ±0.4°/帧（TH095 弧度）
    local BF_RING_ROT = 120                            -- POLAR 的 i0

    local function bf_ring_hook(spin)
        return sg_tr_hook({
            sg_rec(SG_POLAR, 0, BF_RING_ROT, -1, 0, sg_deg(spin)),
        }, BF_RING_FLAGS)
    end

    class.butterfly_emitter = Class(object, {
        init = function(self, owner, opt)
            self.group = GROUP.GHOST
            self.layer = LAYER.ENEMY_BULLET_EF
            self.colli = false
            self.bound = false
            self.x, self.y = owner.x, owner.y
            self.rot = 0
            local st = opt.st
            task.New(self, function()
                if opt.delay and opt.delay > 0 then task.Wait(opt.delay) end  -- Sub10 的 +300
                while IsValid(self) and not st.dead do
                    local aim = th_aim(self.x, self.y)          -- ins_7(f0, aimAngle)
                    local speed = opt.speed and opt.speed() or BF_RING_SPEED
                    for half = 0, 1 do
                        local hook = bf_ring_hook(((half == 0) and 1 or -1) * BF_RING_SPIN)
                        local color = (half == 0) and 1 or 3
                        for _ = 1, BF_RING_N do
                            if not IsValid(self) or st.dead then return end
                            sg_shot(89, sg_style(15), ex_color(color),
                                    self.x, self.y, BF_RING_CNT, 1, speed, 0.5,
                                    math.deg(aim), 0, false, BF_RING_FLAGS, hook)
                            task.Wait(BF_RING_GAP)
                        end
                    end
                end
            end)
        end,
        frame = function(self) task.Do(self) end,
        render = function(self) end,
    })

    local function spawn_bf_emitter(owner, list, opt)
        local o = New(class.butterfly_emitter, owner, opt)
        list[#list + 1] = o
        return o
    end

    local function clear_bf_emitters(list)
        for i = #list, 1, -1 do
            if IsValid(list[i]) then
                task.Clear(list[i])
                object.RawDel(list[i])
            end
            list[i] = nil
        end
    end

    ---Sub9（@3340）：ring = 每波几发（调用者的 extraIntV3 = 6/7/7/8）。
    ---floatV0 = rand(−π,π) 起、每波 += floatV2（floatV2 每 3 波再 −= floatV1）；
    ---floatV7 从 2.2 起、每波 −0.006；slot7 的 f0 按 +120°/180°/−120° 循环。
    local function sub9(owner, callf0, ring)
        local v0 = ran:Float(-math.pi, math.pi)
        local v2 = callf0
        local v1 = callf0 * 0.1
        local v7 = BF_SPEED0
        local pi = photo_index(PHOTO_LIMIT)
        local v6 = pi * 0.22 + 1.8
        local v5 = pi * 0.1 + 1.4
        for n = 0, BF_SHOTS - 1 do
            if st.dead then return end
            local variant = n % 3
            local hook
            if variant == 0 then
                hook = bf_hook(callf0, sg_deg(math.rad(120)), v6)
            elseif variant == 1 then
                hook = bf_hook(callf0, sg_deg(math.pi), v5)
            else
                hook = bf_hook(callf0, sg_deg(math.rad(-120)), v6)
            end
            sg_shot(89, sg_style(0), ex_color(0), owner.x, owner.y,
                    ring, 1, v7, 0.7, math.deg(v0), math.deg(BF_STEP), false,
                    BF_FLAGS, hook)
            v7 = v7 - BF_DECAY
            v0 = v0 + v2
            ---★ f2 的增量符号两段相反：第一段（前 18 发）是 ins_15(f2,f1) ⇒ += ；
            ---  第二段（后 12 发）才是 ins_16(f2,f1) ⇒ −=。整段都用 −= 是错的。
            if variant == 2 then
                if n < 18 then v2 = v2 + v1 else v2 = v2 - v1 end
            end
            if n < BF_SHOTS - 1 then task.Wait(BF_GAP) end
        end
        for _ = 1, BF_LEAD_EXTRA do task.Wait(1) end
    end

    ---Sub3/Sub5..Sub8 共用的循环体（lead = 循环块所在的 t：Sub3 是 0、Sub5..Sub8 是 60；
    ---tail = 从循环块到 ins_67 的帧数：240/200/180/160/140）。
    local function butterfly_loop(owner, ring, lead, tail)
        local g = gen
        task.New(owner, function()
            local callf0 = 0                                -- 第一轮 callFloat0 = 初始 0
            local v7 = math.pi / 2                          -- Sub3/Sub5..Sub8 的 floatV7
            if lead > 0 then
                clear_bf_emitters(bf_ems)                   -- ins_85：先清上一阶段的子机
                task.Wait(lead)                             -- Sub5..Sub8 的 t=60
                if st.dead or g ~= gen then return end
                sg_clear(lasers)                            -- ins_102
                spawn_bf_emitter(owner, bf_ems, {           -- ins_83("Sub11") t=60
                    st = st,
                    speed = function() return BF_RING_SPEED + 0.5 * photo_index(PHOTO_LIMIT) end,
                })
            else
                spawn_bf_emitter(owner, bf_ems, {           -- ins_83("Sub10")，先空等 300 帧
                    st = st, delay = 300,
                })
            end
            while not st.dead and g == gen do
                sub9(owner, callf0, ring)                   -- ins_52(9)，阻塞 ~120 帧
                if st.dead or g ~= gen then return end
                task.Wait(tail)                             -- 到 ins_67 的 t
                if st.dead or g ~= gen then return end
                callf0 = th_aim(owner.x, owner.y) + v7      -- ins_25
                v7 = -v7                                    -- floatV7 ×(−1)
                sg_bmove(owner, st, BF_MOVE_TAIL, 4, 0, BOX) -- ins_67(60,4,0)：只当计时器
                task.Wait(BF_MOVE_TAIL)
            end
        end)
    end

    local card = boss.card.New(CARD_NAME, 1, 3, CARD_TIME, CARD_HP)

    function card:before()
        gen = 1
        taken = 0
        lasers = {}
        bf_ems = {}
    end

    function card:init()
        photo_damage_on(self, PHOTO_LIMIT)
        self.x, self.y = BOSS_X, BOSS_START_Y
        st.dead = false
        task.New(self, function()
            task.Wait(ENTRY_WAIT)
            task.MoveTo(HOME_X, HOME_Y, ENTRY_TIME, EASE_OUT)
            butterfly_loop(self, 6, 0, 240)                 -- Sub3
            task.New(self, function()                       -- ins_115(0..3,1..4,5..8) 的监视器
                while not st.dead do
                    local p = photo_index(PHOTO_LIMIT)
                    local idx = 0
                    if p >= 4 then idx = 4
                    elseif p >= 3 then idx = 3
                    elseif p >= 2 then idx = 2
                    elseif p >= 1 then idx = 1 end
                    if idx > taken then
                        taken = idx
                        gen = gen + 1
                        if idx == 1 then butterfly_loop(self, 6, 60, 200) end
                        if idx == 2 then butterfly_loop(self, 7, 60, 180) end
                        if idx == 3 then butterfly_loop(self, 7, 60, 160) end
                        if idx == 4 then butterfly_loop(self, 8, 60, 140) end
                    end
                    task.Wait(1)
                end
            end)
        end)
    end

    function card:frame()
    end

    function card:del()
        st.dead = true
        photo_damage_off(self)
        sg_clear(lasers)
        clear_bf_emitters(bf_ems)
    end

    boss.card.add({ { card, "24a" } }, LEVEL, CARD_NAME, CARD_ID)
end--蝶符「バタフライストーム」（ecl1_c）

do  -- 536 ルーミア 非符（ecl2_a，组 24a→25a 第 1 张）
    ---原作这一幕**不亮卡名**（Sub2 的 t=130 是 id=0）：本体落到中轴后每 314 帧一轮 ——
    ---t=0 起槽 0（Sub4：朝「自机角 −90°」摆动的成对弹）、t=20 起槽 1（Sub5：镜像，+90°）、
    ---t=97 挪一次、t=157 槽 0 换 Sub5、t=177 槽 1 换 Sub4、t=254 挪一次。
    ---每个子脚本放 16 组「成对弹」（每帧一组、组内两发速度 6→3 递减），收尾再补一圈
    ---「16 + 10×已拍张数」发的自机狙小玉（出膛点偏 (16,−24)）。
    ---拍中第 2 张后主脚本换成 Sub6：清一次屏，之后每 360 帧两段 20 连锁 + 6 发扇（速 1.7）。
    ---数据源 /tmp/D95x_ecl2_a.txt。骨架：
    ---  · Sub2：… ins_141(3) + ins_115(0,2,6) + ins_63(-128,-64) → t=100 ins_64(30,4,0,128)
    ---    → t=130 的 id=0（非符）+ ins_75(-160,96,160,192) + ins_52(3)。
    ---  · Sub3（@672，314 帧一轮）：ins_6(extraIntV1,60) → ins_117(0,4) → t=20 ins_117(1,5)
    ---    → t=97 ins_67(60,4,1.4) → t=157 ins_117(0,5) → t=177 ins_117(1,4)
    ---    → t=254 ins_67(60,4,1.4) → t=314 ins_4(0,−184) 跳回 **@692**（t=0 的 ins_117(0,4)）。
    ---  · Sub4（@908）：ins_6(extraIntV0,16)；t=1 floatV3 = playerAngle → floatV0 = −90°
    ---    （ins_16）、floatV1 = 6、floatV2 = +90°（ins_15）、floatV3 = floatV1/2；
    ---    CIRCLE 型2/色10、c1=1、**c2=2**、sp1=floatV1、sp2=floatV3、ang=floatV0、tf=FAST|SND；
    ---    之后 floatV0 += 0.1366 / floatV2 −= 0.1366 / floatV1 −= 0.35625；
    ---    t=2 ins_5(1,−128,16) ⇒ 16 遍、每 (2−1)=**1 帧**一遍（子上下文里 ins_28 会重算）。
    ---    t=2 intV0 = 16 + 10×photoIndex；t=14 ins_100(16,−24) + CIRC_AIM 型0/色10、c1=intV0、
    ---    速 0.8 + ins_100(0,0)；t=14 ins_53 返回。
    ---  · Sub5（@1352）= Sub4 的镜像（CIRCLE 用 floatV2，其余同）。
    ---  · Sub6（@1796，拍中第 2 张）：t=90 ins_102 + 起槽 0/1 → t=210 ins_67(60,4,1.7) →
    ---    t=270 重起 → t=390 ins_67 → t=450 ins_4(90,−160) 跳回 **@1828** ⇒ 360 帧一轮。
    ---  · Sub7（@2020）= 533 的 Sub7（DECEL 空转 + 12 波 6 发扇、每 8 帧一波）；
    ---    Sub8/Sub9（@2192/@2444）= Sub4/Sub5 但 extraIntV0 = 20。
    local BOSS_X, BOSS_START_Y = -128, field_y(-64)
    local HOME_X, HOME_Y = 0, field_y(128)
    local ENTRY_WAIT, ENTRY_TIME = 100, 30
    local EASE_OUT = VALUE_SET.DECEL

    local PHOTO_LIMIT = 3                               -- ins_141(3)
    local CARD_NAME = ""                                -- 非符：原作 t=130 是 id=0
    local CARD_TIME, CARD_HP = 50, 900
    local CARD_ID = 536
    local BOX = { -160, 96, 160, 192 }

    local ROUND = 314                                   -- Sub3 一轮（ins_4(0,−184)）
    local PAIR_AT2, PAIR_SWAP1, PAIR_SWAP2 = 20, 157, 177
    local MOVE_AT1, MOVE_AT2 = 97, 254
    local MOVE_FRAMES, MOVE_EASE, MOVE_SPEED = 60, 4, 1.4

    local P_SHOTS = 16                                  -- Sub4/Sub5 的 ins_5(1,−128,16)
    local P_TURN = 0.136590987                          -- 每发摆动量
    local P_SPEED0, P_SPEED_STEP = 6, 0.356249988
    local P_AIM_DELAY = 13                              -- 最后一发到收尾自机狙之间
    local P_AIM_SPEED, P_AIM_OFF_X, P_AIM_OFF_Y = 0.8, 16, 24
    local P_AIM_BASE, P_AIM_PER = 16, 10                -- c1 = 16 + 10×photoIndex

    local S6_AT = 2                                     -- ins_115(0,2,6)
    local S6_LEAD, S6_SPAN = 90, 360
    local S6_SWITCH, S6_MOVE = 180, 120
    local C_SHOTS = 20
    local A_COUNT, A_SPEED = 10, 3                      -- Sub8/Sub9 的 CIRCLE
    local A_ROT = 0.0261799395
    local A_ROT_FIRST, A_ROT_REST = 30, 60
    local B_SHOTS, B_GAP = 12, 8                        -- Sub7
    local B_COUNT, B_SPEED, B_STEP = 6, 3, 0.52359879
    local S6_MOVE_SPEED = 1.7

    local st = { dead = false }
    local gen = 0
    local lasers = {}

    local function hook_polar(sign)
        return sg_tr_hook({
            sg_rec(SG_POLAR, 0, A_ROT_FIRST, -1, 0, sg_deg(sign * A_ROT)),
            sg_rec(SG_POLAR, 0, A_ROT_REST, -1, 0, sg_deg(-sign * A_ROT)),
            sg_rec(SG_POLAR, 0, A_ROT_REST, -1, 0, sg_deg(sign * A_ROT)),
        }, 0x222)
    end

    local hook_ccw = hook_polar(1)                      -- Sub4/Sub8
    local hook_cw = hook_polar(-1)                      -- Sub5/Sub9

    ---Sub4（which=1，用 floatV0）/Sub5（which=2，用 floatV2）：16 组成对弹 + 收尾自机狙。
    local function pair_shots(owner, which)
        task.New(owner, function()
            task.Wait(1)
            local aim = th_aim(owner.x, owner.y)
            local v0 = aim - math.pi / 2
            local v2 = aim + math.pi / 2
            local v1 = P_SPEED0
            for i = 1, P_SHOTS do
                if st.dead then return end
                local base = (which == 1) and v0 or v2
                sg_shot(89, sg_style(2), ex_color(10), owner.x, owner.y,
                        1, 2, v1, v1 / 2, math.deg(base), 0, false, 0x202)
                v0 = v0 + P_TURN
                v2 = v2 - P_TURN
                v1 = v1 - P_SPEED_STEP
                if i < P_SHOTS then task.Wait(1) end
            end
            task.Wait(P_AIM_DELAY)
            if st.dead then return end
            local n = P_AIM_BASE + P_AIM_PER * photo_index(PHOTO_LIMIT)
            sg_shot(88, sg_style(0), ex_color(10),
                    owner.x + P_AIM_OFF_X, owner.y + P_AIM_OFF_Y,
                    n, 1, P_AIM_SPEED, 0, 0, 0, true, 0x202)
        end)
    end

    local function ring_shots(owner, hook, shots)
        task.New(owner, function()
            task.Wait(1)
            local a = math.deg(th_aim(owner.x, owner.y))
            for i = 1, shots do
                if st.dead then return end
                sg_shot(89, sg_style(1), ex_color(13), owner.x, owner.y,
                        A_COUNT, 1, A_SPEED, 1.5, a, 0, false, 0x222, hook)
                if i < shots then task.Wait(6) end
            end
        end)
    end

    local function fan_shots(owner)
        task.New(owner, function()
            task.Wait(32)
            local a = math.deg(th_aim(owner.x, owner.y))
            for i = 1, B_SHOTS do
                if st.dead then return end
                sg_shot(89, sg_style(12), ex_color(6), owner.x, owner.y,
                        B_COUNT, 1, B_SPEED, 1.5, a, math.deg(B_STEP), false, 0x202)
                if i < B_SHOTS then task.Wait(B_GAP) end
            end
        end)
    end

    ---Sub3（@672）：314 帧一轮 —— 起槽 0（Sub4）、起槽 1（Sub5）、挪、换槽、换槽、挪。
    local function sub3(owner)
        local g = gen
        task.New(owner, function()
            while not st.dead and g == gen do
                pair_shots(owner, 1)                        -- ins_117(0,4)  t=0
                task.Wait(PAIR_AT2)                         -- t=20
                pair_shots(owner, 2)                        -- ins_117(1,5)  t=20
                task.Wait(MOVE_AT1 - PAIR_AT2)              -- t=97
                if st.dead or g ~= gen then return end
                sg_bmove(owner, st, MOVE_FRAMES, MOVE_EASE, MOVE_SPEED, BOX)
                ---★ sg_bmove 是**非阻塞**的（sg_move 内部另起 task）⇒ 这里必须再等
                ---  MOVE_FRAMES 帧才是原作 ins_67 结束的 t=157。旧写法多减了一个
                ---  MOVE_FRAMES（当成阻塞），整轮会缩成 194 帧。
                task.Wait(MOVE_FRAMES)                      -- t=157
                if st.dead or g ~= gen then return end
                pair_shots(owner, 2)                        -- ins_117(0,5)  t=157
                task.Wait(PAIR_SWAP2 - PAIR_SWAP1)          -- t=177
                pair_shots(owner, 1)                        -- ins_117(1,4)  t=177
                task.Wait(MOVE_AT2 - PAIR_SWAP2)            -- t=254
                if st.dead or g ~= gen then return end
                sg_bmove(owner, st, MOVE_FRAMES, MOVE_EASE, MOVE_SPEED, BOX)
                task.Wait(MOVE_FRAMES)                      -- t=314
            end
        end)
    end

    ---Sub6（@1796，拍中第 2 张起接管）：t=90 清屏，之后每 360 帧两段 20 连锁 + 6 发扇。
    local function sub6(owner)
        local g = gen
        task.New(owner, function()
            task.Wait(S6_LEAD)                              -- t=90
            if st.dead or g ~= gen then return end
            sg_clear(lasers)
            while not st.dead and g == gen do
                ring_shots(owner, hook_cw, C_SHOTS)         -- ins_117(0,9)  t=90
                fan_shots(owner)                            -- ins_117(1,7)  t=90
                task.Wait(S6_MOVE)                          -- t=210
                if st.dead or g ~= gen then return end
                sg_bmove(owner, st, MOVE_FRAMES, MOVE_EASE, S6_MOVE_SPEED, BOX)
                task.Wait(S6_SWITCH - S6_MOVE)              -- t=270
                if st.dead or g ~= gen then return end
                ring_shots(owner, hook_ccw, C_SHOTS)        -- ins_117(0,8)  t=270
                fan_shots(owner)                            -- ins_117(1,7)  t=270
                task.Wait(S6_MOVE)                          -- t=390
                if st.dead or g ~= gen then return end
                sg_bmove(owner, st, MOVE_FRAMES, MOVE_EASE, S6_MOVE_SPEED, BOX)
                task.Wait(S6_SPAN - S6_SWITCH - S6_MOVE)    -- t=450 → 回到 t=90
            end
        end)
    end

    local card = boss.card.New(CARD_NAME, 1, 3, CARD_TIME, CARD_HP)

    function card:before()
        gen = 1
        lasers = {}
    end

    function card:init()
        photo_damage_on(self, PHOTO_LIMIT)
        self.x, self.y = BOSS_X, BOSS_START_Y
        st.dead = false
        task.New(self, function()
            task.Wait(ENTRY_WAIT)
            task.MoveTo(HOME_X, HOME_Y, ENTRY_TIME, EASE_OUT)
            sub3(self)
            task.New(self, function()                   -- ins_115(0,2,6) 的监视器
                while not st.dead do
                    if photo_index(PHOTO_LIMIT) >= S6_AT then
                        gen = gen + 1
                        sub6(self)
                        return
                    end
                    task.Wait(1)
                end
            end)
        end)
    end

    function card:frame()
    end

    function card:del()
        st.dead = true
        photo_damage_off(self)
        sg_clear(lasers)
    end

    boss.card.add({ { card, "25a" } }, LEVEL, CARD_NAME, CARD_ID)
end--ルーミア 非符（ecl2_a）

do  -- 537 ルーミア 闇符「ダークサイドオブザムーン」（ecl2_b，组 25a 第 2 张）
    ---原作是「暗玉里往外吐小弹」：本体进场后每 180 帧一轮 ——
    ---  · 槽 0（Sub4，@1052）在**本体周围 ±32 px** 随机取出膛点、每次抽一个随机朝向，
    ---    连放两簇 3 发（型0/色1 速 0.6、型1/色2 速 1.4，都是 SLOW|SND），
    ---    然后用 ins_2 冻结「12 − 3×已拍张数」帧，t=1 的 ins_4(0,−288) 跳回 **@1052**
    ---    （本轮开头）⇒ 自循环；间隔 13→10→7→4→1 帧随拍照数收紧。
    ---  · t=115 本体 ins_100(0,0) + ins_117(0,−1) 收掉槽 0，再从质心放一圈 16 发
    ---    （型12/色6、速 2、30° 步进、随机基准角、SLOW|SND）；t=120 的 ins_144/ins_81/ins_62
    ---    与 t=0 的 ins_80(8)/ins_65/70/71（全 0）都是音效、控制位与 ANM，忽略。
    ---  · t=180 的 ins_4(0,−208) 跳回 **@812**（t=0 的 ins_117(0,4)）⇒ 180 帧一轮。
    ---  · 槽 1（Sub5，@1372）只按随机出膛点连放 25 个 ins_150(8) 装饰 ANM、一颗弹都不发
    ---    （文件头差异 5：装饰类子机/ANM 一律忽略），这里只留注释。
    ---本幕**没有 ins_115**：拍中不会换主脚本，拍照只让 Sub4 的间隔按 ins_22/ins_21 变短。
    ---数据源 /tmp/D95x_ecl2_b.txt。骨架：
    ---  · Sub2：ins_55(2)+ins_81(3)+ins_109(0)+ins_77(24,24)+ins_141(4)+ins_108(0,31)/
    ---    ins_108(1,30)+ins_143(1,130)+ins_63(-128,-64) → t=100 ins_64(30,4,0,128)
    ---    → t=130 ins_104「闇符「ダークサイドオブザムーン」」+ins_75(-160,96,160,192)
    ---    +ins_149(3)+ins_52(3)。
    ---  · Sub3（@720）：t=0 ins_6(extraIntV1,60)+ins_65/70/71（全 0，清一次运动）
    ---    +ins_6(extraIntV0,1)+ins_117(0,4)+ins_80(8)+ins_67(114,4,1)+ins_117(1,5)
    ---    → t=115 ins_100(0,0)+ins_117(0,−1)+CIRCLE → t=120 ins_144(15)+ins_81(8)+ins_62
    ---    → t=180 ins_4(0,−208)。
    ---  · Sub4（@1052）：ins_27(extraFloatV0,randF32s,32)+ins_27(extraFloatV1,randF32s,32)
    ---    +ins_100+型0/色1 c1=3 速 0.6 → 再来一次（新随机点）+型1/色2 c1=3 速 1.4
    ---    → ins_22(extraIntV0,photoIndex,3)+ins_21(extraIntV0,12,extraIntV0)+ins_2(extraIntV0)
    ---    → t=1 ins_4(0,−288)。
    local BOSS_X, BOSS_START_Y = -128, field_y(-64)
    local HOME_X, HOME_Y = 0, field_y(128)              -- 0 / 96
    local ENTRY_WAIT, ENTRY_TIME = 100, 30
    local EASE_OUT = VALUE_SET.DECEL

    local PHOTO_LIMIT = 4                               -- ins_141(4)
    local CARD_NAME = "闇符「ダークサイドオブザムーン」"
    local CARD_TIME, CARD_HP = 50, 900
    local CARD_ID = 537
    local BOX = { -160, 96, 160, 192 }                  -- ins_75

    local ROUND = 180                                   -- Sub3 一轮（ins_4(0,-208)）
    local RING_AT = 115                                 -- t=115：收槽 0 + 放整圈
    local MOVE_FRAMES, MOVE_EASE, MOVE_SPEED = 114, 4, 1 -- ins_67(114,4,1)

    local RING_COUNT, RING_SPEED = 16, 2                -- CIRCLE 型12/色6、step=30°（c2=1 不参与）
    local RING_FLAGS = 0x208                            -- SLOW|SND

    local PAIR_TYPES, PAIR_COLORS = { 0, 1 }, { 1, 2 }  -- 型0/色1、型1/色2
    local PAIR_COUNT = 3                                -- 每簇 3 发
    local PAIR_SPEEDS = { 0.6, 1.4 }
    local PAIR_OFF = 32                                 -- ins_27：randF32s × 32
    local PAUSE_BASE, PAUSE_PER = 12, 3                 -- ins_21：12 − 3×photoIndex

    local st = { dead = false }
    local gen = 0                                       -- 主脚本代号
    local lasers = {}

    ---Sub4（@1052）：本体周围随机出膛点、随机朝向的两簇 3 发；放完冻结「12−3×已拍张数」帧。
    ---stop 由主循环在 t=115 置真（照 ins_117(0,−1) 收掉槽 0）。
    local function sub4(owner, stop)
        task.New(owner, function()
            while not stop[1] and not st.dead do
                for j = 1, 2 do
                    local ox = ran:Float(-PAIR_OFF, PAIR_OFF)
                    local oy = -ran:Float(-PAIR_OFF, PAIR_OFF)
                    local a = -math.deg(ran:Float(-math.pi, math.pi))
                    sg_shot(89, sg_style(PAIR_TYPES[j]), ex_color(PAIR_COLORS[j]),
                            owner.x + ox, owner.y + oy,
                            PAIR_COUNT, 1, PAIR_SPEEDS[j], 1.5, a, 0, false, RING_FLAGS)
                end
                ---★ ins_2(pause) 是「冻结 pause 帧」（EclRunLow.inl:230-232）；冻结期间
                ---  dispatch 顶部每帧先 secondaryTime-- 再 time--（EclRun.cpp:296-303），
                ---  所以冻结结束时 time 停在 0，还要再过一帧才走到 t=1 的 ins_4(0,Sub4_0)
                ---  ⇒ 实际周期 = pause + 1 = 13/10/7/4/1 帧（与 ins_141(4) 截断后的 0..4 张对应）。
                task.Wait(max(1, PAUSE_BASE + 1 - PAUSE_PER * photo_index(PHOTO_LIMIT)))
            end
        end)
    end

    ---Sub3（@720）：180 帧一轮 —— 起槽 0、挪 114 帧、t=115 收槽 0 并放整圈、t=180 回到起点。
    local function sub3(owner)
        local g = gen
        task.New(owner, function()
            while not st.dead and g == gen do
                local stop = { false }                  -- 每轮新开一张，等价 ins_117 先 Free 旧槽
                sub4(owner, stop)                       -- ins_117(0,4)   t=0
                sg_bmove(owner, st, MOVE_FRAMES, MOVE_EASE, MOVE_SPEED, BOX) -- ins_67(114,4,1)
                task.Wait(RING_AT)                      -- t=115
                if st.dead or g ~= gen then return end
                stop[1] = true                          -- ins_117(0,-1)
                local a = -math.deg(ran:Float(-math.pi, math.pi))
                sg_shot(89, sg_style(12), ex_color(6), owner.x, owner.y,
                        RING_COUNT, 1, RING_SPEED, 1.5, a, 0, false, RING_FLAGS)
                task.Wait(ROUND - RING_AT)              -- t=180 → 下一轮
            end
        end)
    end

    local card = boss.card.New(CARD_NAME, 1, 3, CARD_TIME, CARD_HP)

    function card:before()
        gen = 1
        lasers = {}
    end

    function card:init()
        photo_damage_on(self, PHOTO_LIMIT)
        self.x, self.y = BOSS_X, BOSS_START_Y
        st.dead = false
        task.New(self, function()
            task.Wait(ENTRY_WAIT)
            task.MoveTo(HOME_X, HOME_Y, ENTRY_TIME, EASE_OUT)
            sub3(self)
        end)
    end

    function card:frame()
    end

    function card:del()
        st.dead = true
        photo_damage_off(self)
        sg_clear(lasers)
    end

    boss.card.add({ { card, "25a" } }, LEVEL, CARD_NAME, CARD_ID)
end--闇符「ダークサイドオブザムーン」（ecl2_b）

do  -- 538 ルーミア 夜符「ミッドナイトバード」（ecl2_c，组 25a 第 3 张）
    ---原作是「黑翼扫射 + 拍中三张后加一圈大玉」：本体进场后每 181 帧一轮 ——
    ---  · t=0..50 每 10 帧起一个槽，槽 0..5 交替跑 Sub4/Sub5；另有一条槽 1 的 Sub5 只做装饰。
    ---  · Sub4（@956，槽 k 偶数）/ Sub5（@1392，槽 k 奇数）：一次性 33 发的「会掉头的直线弹」——
    ---    t=1 取本体→自机角 θ，Sub4 从 θ−90° 起、每发 +7.5°，Sub5 从 θ+90° 起、每发 −7.5°；
    ---    速度从 6 起每发 −0.35625，穿过 0 时被 ins_51/ins_47 的 ±0.2 闸钳一次（见下），
    ---    之后一路递减到 ≈−5.54 ⇒ 前 17 发向外飞、后面的被「吸」回来。
    ---  · t=121 ins_67(60,4,1) 挪一次；t=181 的 ins_4(0,−172) 跳回 **@752**（t=0 的 ins_117(0,4)）。
    ---  · ins_115(0,3,6)：拍中第 3 张后主上下文整个换成 Sub6（@1828，同时释放全部子槽、
    ---    重置弹表）—— t=60 清屏 + 每 7 帧起一个槽（共 8 个、4/5 交替）；
    ---    t=125 从质心放一圈 8 发大玉（型17/色3、速 2、朝自机）；t=180 挪一次；
    ---    t=240 的 ins_4(60,−256) 跳回 **@1840**（t=60 的 ins_6）⇒ 之后 180 帧一轮。
    ---数据源 /tmp/D95x_ecl2_c.txt。骨架：
    ---  · Sub2：ins_55(2)+ins_81(3)+ins_109(0)+ins_77(24,24)+ins_141(5)+ins_108(0,31)/
    ---    ins_108(1,30)+ins_143(1,130)+**ins_115(0,3,6)**+ins_63(-128,-64)
    ---    → t=100 ins_64(30,4,0,128) → t=130 ins_104「夜符「ミッドナイトバード」」+ins_75+ins_52(3)。
    ---  · Sub3（@732）：t=0 ins_6(extraIntV1,60)+ins_117(0,4) → t=10k ins_117(k,4/5)
    ---    → t=66 ins_62 → t=76 ins_144 → t=121 ins_67(60,4,1) → t=181 ins_4(0,−172)。
    ---  · Sub4/Sub5（@956/@1392）：ins_6(extraIntV0,33)；t=1 算 θ 与起始角/速度
    ---    +CIRCLE 型2/色10 c1=1 c2=1 sp1=floatV1 sp2=floatV1/2 ang=θ∓90° tf=FAST|SND
    ---    +floatV0 += 7.5° / floatV2 −= 7.5° / floatV1 −= 0.35625
    ---    +ins_51(floatV1,0.2,1,76)/ins_47(floatV1,−0.2,1,48)（两条都跳 @1300）/+@1280 floatV1=−0.2
    ---    → t=2 ins_5(1,−204,33) 每帧一发共 33 发 + intV0=16+10×photoIndex（死代码）+ ins_53。
    ---  · Sub6（@1828）：见上。
    local BOSS_X, BOSS_START_Y = -128, field_y(-64)
    local HOME_X, HOME_Y = 0, field_y(128)              -- 0 / 96
    local ENTRY_WAIT, ENTRY_TIME = 100, 30
    local EASE_OUT = VALUE_SET.DECEL

    local PHOTO_LIMIT = 5                               -- ins_141(5)
    local CARD_NAME = "夜符「ミッドナイトバード」"
    local CARD_TIME, CARD_HP = 50, 900
    local CARD_ID = 538
    local BOX = { -160, 96, 160, 192 }                  -- ins_75

    local ROUND = 181                                   -- Sub3 一轮（ins_4(0,-172)）
    local SLOT_N, SLOT_GAP = 6, 10                      -- 槽 0..5、每 10 帧起一个
    local MOVE_AT = 121                                 -- t=121 才挪
    local MOVE_FRAMES, MOVE_EASE, MOVE_SPEED = 60, 4, 1 -- ins_67(60,4,1)

    local MB_SHOTS = 33                                 -- Sub4/Sub5 的 ins_5(1,−204,33)
    local MB_SPEED0 = 6                                 -- floatV1 初值
    local MB_DECAY = 0.356249988                        -- 每发 −0.35625
    local MB_TURN = 0.130899698                         -- 每发 ±7.5°（Sub4 +、Sub5 −）
    local MB_CLAMP = 0.2                                -- ins_51/ins_47 的 ±0.2 闸

    local SWITCH_AT = 3                                 -- ins_115(0,3,6)
    local S6_LEAD = 60                                  -- Sub6 第一段 t=60
    local S6_SLOT_N, S6_SLOT_GAP = 8, 7                 -- 8 个槽、每 7 帧起一个
    local S6_RING_AT = 125                              -- t=125：一圈大玉
    local S6_MOVE_AT = 180                              -- t=180：ins_67(60,4,1)
    local S6_SPAN = 180                                 -- ins_4(60,−256) ⇒ 之后 180 帧一轮
    local S6_RING_N, S6_RING_SPEED = 8, 2               -- CIRCLE 型17/色3

    local st = { dead = false }
    local gen = 0                                       -- 主脚本代号（ins_115 会 +1）
    local lasers = {}

    ---Sub4（@956，槽 k 偶数）/ Sub5（@1392，槽 k 奇数）：一次性 33 发「会掉头的直线弹」。
    ---★ t=1 的两条比较分支（@1224 ins_51 ≥0.2、@1252 ins_47 ≤−0.2）**都跳 @1300**，
    ---  只有两者都不成立（|floatV1| < 0.2）时才会落到 @1280 把 floatV1 写成 −0.2
    ---  ⇒ 第 17 发前后速度过零、被钳一次，随后一路递减。
    ---★ t=2 的 ins_5 跳回 **@1096**（t=1 的 ins_28）；t=2 末尾的 intV0 是死代码（子上下文
    ---  结束不回写父变量，见 EclDependencies.cpp:327 的 PopEclContext），忽略。
    ---★ 角增量方向：Sub4 的弹角是 floatV0（起始 aimAngle−π/2），循环体里 ins_15(f0,+7.5°)
    ---  ⇒ **每发 +7.5°**；Sub5 的弹角是 floatV2（起始 aimAngle+π/2），ins_16(f2,+7.5°)
    ---  ⇒ **每发 −7.5°**（EclRunLow.inl:271-277 的 case 15 += / case 16 −=）。
    ---  故两边都是「向内收」：Sub4 从 θ−90° 往上扫、Sub5 从 θ+90° 往下扫。
    local function bird_stream(owner, side, g)
        task.New(owner, function()
            task.Wait(1)
            if st.dead or g ~= gen then return end
            local ang = th_aim(owner.x, owner.y) + side * math.pi / 2
            local spd = MB_SPEED0
            for i = 1, MB_SHOTS do
                if st.dead or g ~= gen then return end
                sg_shot(89, sg_style(2), ex_color(10), owner.x, owner.y,
                        1, 1, spd, spd / 2, -math.deg(ang), 0, false, 0x202)
                ang = ang - side * MB_TURN
                spd = spd - MB_DECAY
                if spd > -MB_CLAMP and spd < MB_CLAMP then spd = -MB_CLAMP end
                if i < MB_SHOTS then task.Wait(1) end
            end
        end)
    end

    ---Sub3（@732）：181 帧一轮 —— t=0..50 每 10 帧起一个槽，t=121 挪一次，t=181 回到起点。
    local function sub3(owner)
        local g = gen
        task.New(owner, function()
            while not st.dead and g == gen do
                for k = 0, SLOT_N - 1 do
                    if k > 0 then
                        task.Wait(SLOT_GAP)
                        if st.dead or g ~= gen then return end
                    end
                    bird_stream(owner, (k % 2 == 0) and -1 or 1, g)  -- ins_117(k, 4/5)
                end
                task.Wait(MOVE_AT - (SLOT_N - 1) * SLOT_GAP)     -- t=121
                if st.dead or g ~= gen then return end
                sg_bmove(owner, st, MOVE_FRAMES, MOVE_EASE, MOVE_SPEED, BOX) -- ins_67(60,4,1)
                task.Wait(ROUND - MOVE_AT)                       -- t=181 → 下一轮
            end
        end)
    end

    ---Sub6（@1828，拍中第 3 张起接管）：t=60 清屏 + 8 个槽（每 7 帧一个）；
    ---t=125 一圈大玉；t=180 挪一次；t=240 跳回 t=60 ⇒ 周期 180 帧。
    ---（原作换主脚本时会把子上下文全释放——这里靠 gen 让 Sub3 的槽在切换帧立刻停。）
    local function sub6(owner)
        local g = gen
        task.New(owner, function()
            task.Wait(S6_LEAD)                                  -- t=60
            if st.dead or g ~= gen then return end
            sg_clear(lasers)                                    -- ins_102
            while not st.dead and g == gen do
                for k = 0, S6_SLOT_N - 1 do
                    if k > 0 then
                        task.Wait(S6_SLOT_GAP)
                        if st.dead or g ~= gen then return end
                    end
                    bird_stream(owner, (k % 2 == 0) and -1 or 1, g)
                end
                task.Wait(S6_RING_AT - S6_LEAD - (S6_SLOT_N - 1) * S6_SLOT_GAP)  -- t=125
                if st.dead or g ~= gen then return end
                sg_shot(89, sg_style(17), ex_color(3), owner.x, owner.y,
                        S6_RING_N, 1, S6_RING_SPEED, 1, sg_aim(owner.x, owner.y),
                        0, false, 0x202)
                task.Wait(S6_MOVE_AT - S6_RING_AT)              -- t=180
                if st.dead or g ~= gen then return end
                sg_bmove(owner, st, MOVE_FRAMES, MOVE_EASE, MOVE_SPEED, BOX)
                task.Wait(S6_SPAN - (S6_MOVE_AT - S6_LEAD))     -- t=240 → 下一轮
            end
        end)
    end

    local card = boss.card.New(CARD_NAME, 1, 3, CARD_TIME, CARD_HP)

    function card:before()
        gen = 1
        lasers = {}
    end

    function card:init()
        photo_damage_on(self, PHOTO_LIMIT)
        self.x, self.y = BOSS_X, BOSS_START_Y
        st.dead = false
        task.New(self, function()
            task.Wait(ENTRY_WAIT)
            task.MoveTo(HOME_X, HOME_Y, ENTRY_TIME, EASE_OUT)
            sub3(self)
            task.New(self, function()                   -- ins_115(0,3,6) 的监视器
                while not st.dead do
                    if photo_index(PHOTO_LIMIT) >= SWITCH_AT then
                        gen = gen + 1
                        sub6(self)
                        return
                    end
                    task.Wait(1)
                end
            end)
        end)
    end

    function card:frame()
    end

    function card:del()
        st.dead = true
        photo_damage_off(self)
        sg_clear(lasers)
    end

    boss.card.add({ { card, "25a" } }, LEVEL, CARD_NAME, CARD_ID)
end--夜符「ミッドナイトバード」（ecl2_c）

end  -- Stage 1
